window.CVICNE_OTAZKY = {"rozpis":[["FL-1.1.1","FL-1.2.2"],["FL-1.5.2"],["FL-1.1.2","FL-1.2.1","FL-1.2.3"],["FL-1.3.1"],["FL-1.4.1"],["FL-1.4.2","FL-1.4.3"],["FL-1.4.4","FL-1.4.5"],["FL-1.5.1","FL-1.5.3"],["FL-2.1.2"],["FL-2.1.3"],["FL-2.1.1","FL-2.1.4","FL-2.1.5","FL-2.1.6"],["FL-2.1.1","FL-2.1.4","FL-2.1.5","FL-2.1.6"],["FL-2.2.1","FL-2.2.2","FL-2.2.3","FL-2.3.1"],["FL-2.2.1","FL-2.2.2","FL-2.2.3","FL-2.3.1"],["FL-3.1.1","FL-3.2.1"],["FL-3.2.3","FL-3.2.5"],["FL-3.1.2","FL-3.1.3"],["FL-3.2.2","FL-3.2.4"],["FL-4.1.1"],["FL-4.2.1"],["FL-4.2.2"],["FL-4.2.3"],["FL-4.2.4"],["FL-4.3.1","FL-4.3.2","FL-4.3.3"],["FL-4.3.1","FL-4.3.2","FL-4.3.3"],["FL-4.4.1","FL-4.4.2","FL-4.4.3"],["FL-4.4.1","FL-4.4.2","FL-4.4.3"],["FL-4.5.1","FL-4.5.2"],["FL-4.5.3"],["FL-5.1.2","FL-5.1.6","FL-5.2.1","FL-5.3.1"],["FL-5.1.1","FL-5.1.3"],["FL-5.1.4"],["FL-5.1.5"],["FL-5.1.7"],["FL-5.2.2","FL-5.2.3","FL-5.2.4"],["FL-5.3.2","FL-5.3.3"],["FL-5.4.1"],["FL-5.5.1"],["FL-6.1.1"],["FL-6.2.1"]],"otazky":[{"id":"TR-002","n":null,"lo":"FL-1.1.2","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývá činnost, při které se hledá příčina selhání (defekt), analyzuje se a odstraní?","m":["Ladění","Konfirmační testování","Monitoring testování","Řízení testování"],"ok":[0],"vys":{"a":"Je správně. Ladění zahrnuje reprodukování selhání, diagnostiku (nalezení defektu) a opravu defektu.","b":"Není správně. Konfirmační testování až následně ověřuje, zda oprava defektu problém vyřešila.","c":"Není správně. Monitoring testování průběžně kontroluje testovací činnosti a porovnává skutečný stav s plánem.","d":"Není správně. Řízení testování se zabývá přijetím opatření nezbytných pro dosažení cílů testování, ne opravou defektů."},"obecne":"Sylabus 1.1.2: Testování a ladění jsou samostatné činnosti. Dynamické testování se snaží vyvolat selhání, ladění se zabývá hledáním jejich příčin (defektů), jejich analýzou a odstraněním. Konfirmační testování pak ověří, že oprava zabrala.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.1.2","nazev":"Testování a ladění","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-dva-testovani-a-ladeni"}},{"id":"TR-003","n":null,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"Co je to testware?","m":["Software nebo systém, který je předmětem testování (testovaný objekt)","Výstupní pracovní produkty testovacích činností, např. plán testování nebo testovací případy","Nástroj, který se používá výhradně pro automatizované provádění testů","Soubor norem ISO/IEC/IEEE, které závazně definují proces testování"],"ok":[1],"vys":{"a":"Není správně. Software, který se testuje, je testovaný objekt, nikoli testware.","b":"Je správně. Sylabus definuje testware jako výstupní pracovní produkty testovacích činností popsaných v kapitole 1.4.1.","c":"Není správně. Testware nejsou jen nástroje; jde o všechny výstupní pracovní produkty testovacích činností.","d":"Není správně. Normy ISO/IEC/IEEE 29119 jsou zdrojem informací o testování, nikoli testware."},"obecne":"Sylabus 1.4.3: Testware je definován jako výstupní pracovní produkt z testovacích činností (plánování, monitoring a řízení, analýza, návrh, implementace, provedení a dokončení testování), např. plán testování, testovací případy, testovací skripty, protokoly z testování nebo souhrnný report z testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"TR-004","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývá pracovní produkt, ze kterého se při testovací analýze a návrhu testů odvozují testovací podmínky a testovací případy?","m":["Testovací data","Testovaný objekt","Testovací báze","Testovací procedura"],"ok":[2],"vys":{"a":"Není správně. Testovací data jsou vstupy potřebné pro provedení testů, vznikají až při návrhu a implementaci.","b":"Není správně. Testovaný objekt je pracovní produkt, který se testuje, nikoli zdroj pro odvození testů.","c":"Je správně. Testovací báze (např. požadavky, uživatelské scénáře, návrh) je analyzována s cílem identifikovat testovací podmínky.","d":"Není správně. Testovací procedura je výstupem implementace testování, uspořádává testovací případy."},"obecne":"Sylabus 1.4.1: Testovací analýza zahrnuje analýzu testovací báze za účelem identifikace testovatelných užitných vlastností a definování testovacích podmínek, které se při návrhu testů rozpracují do testovacích případů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"TR-005","n":null,"lo":"FL-1.1.1","k":"K1","k3":true,"vyber":1,"q":"Jaký je hlavní rozdíl mezi ověřováním (verifikací) a validací?","m":["Verifikace se provádí pouze statickým testováním, validace pouze dynamickým testováním, tedy spuštěním testovaného softwaru","Verifikace a validace jsou synonyma, která obě označují kontrolu shody testovaného objektu se specifikací požadavků","Verifikace je odpovědností testerů, kdežto validace je výhradně odpovědností vývojářů a byznysových analytiků","Verifikace kontroluje splnění specifikovaných požadavků, validace splnění potřeb uživatelů a zainteresovaných stran v provozním prostředí"],"ok":[3],"vys":{"a":"Není správně. Statické i dynamické testování lze použít pro verifikaci i validaci.","b":"Není správně. Validace se neomezuje na shodu se specifikací, ověřuje skutečné potřeby uživatelů.","c":"Není správně. Sylabus nepřiřazuje verifikaci a validaci konkrétním rolím.","d":"Je správně. Přesně tak sylabus odlišuje verifikaci (soulad se specifikací) a validaci (splnění potřeb uživatelů v jejich provozním prostředí)."},"obecne":"Sylabus 1.1: Testování zahrnuje nejen ověření neboli verifikaci (kontrolu, zda systém splňuje specifikované požadavky), ale také validaci (kontrolu, zda systém splňuje potřeby uživatelů a ostatních zainteresovaných stran v jejich provozním prostředí).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"}},{"id":"TR-006","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Který princip testování vysvětluje, proč opakované provádění stále stejných testovacích případů postupně ztrácí schopnost odhalovat nové defekty?","m":["Testy se opotřebovávají","Kompletní testování není možné","Testování je závislé na kontextu","Shlukování defektů"],"ok":[0],"vys":{"a":"Je správně. Pokud se stejné testy neustále opakují, stávají se méně účinnými a nové defekty neodhalují.","b":"Není správně. Tento princip říká, že nelze otestovat všechny kombinace vstupů, a proto je třeba testy cílit.","c":"Není správně. Tento princip říká, že neexistuje jediný univerzální přístup k testování.","d":"Není správně. Shlukování defektů popisuje, že většinu defektů obsahuje malé množství komponent."},"obecne":"Sylabus 1.3, princip 5: Testy se opotřebovávají. Pokud se stejné testy opakují neustále dokola, stávají se stále méně účinnými. Je proto nutné měnit stávající testy a testovací data, případně vytvořit testy nové (výjimkou je např. automatizované regresní testování).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"TR-008","n":null,"lo":"FL-1.2.2","k":"K1","k3":true,"vyber":1,"q":"Jaký je vztah mezi testováním a zajištěním kvality (QA)?","m":["Testování je nadřazená disciplína, jejíž součástí je i zajištění kvality","Testování je nápravný přístup zaměřený na produkt, QA je preventivní přístup zaměřený na procesy","QA je nápravný přístup zaměřený na produkt a provádějí ho výhradně testeři","Testování a QA jsou totéž, oba pojmy lze libovolně zaměňovat"],"ok":[1],"vys":{"a":"Není správně. Testování je hlavní formou řízení kvality (QC), není nadřazené zajištění kvality.","b":"Je správně. Testování je nápravný přístup zaměřený na produkt (forma řízení kvality), QA je preventivní přístup orientovaný na procesy.","c":"Není správně. QA je preventivní a zaměřené na procesy a je odpovědností všech osob v projektu.","d":"Není správně. Sylabus výslovně uvádí, že testování a QA nejsou totéž."},"obecne":"Sylabus 1.2.2: Testování je nápravný přístup zaměřený na produkt a je hlavní formou řízení kvality (QC). QA je preventivní přístup orientovaný na procesy, založený na předpokladu, že dodržování správného procesu vede ke správnému produktu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.2","nazev":"Testování a zajištění kvality","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-dva-testovani-a-zajisteni-kvality"}},{"id":"TR-009","n":null,"lo":"FL-1.2.3","k":"K2","k3":true,"vyber":1,"q":"Co je kořenová příčina?","m":["Vždy technická závada v kódu, kterou odhalí ladění","Viditelný projev defektu při provozu systému","Primární důvod vzniku problému, např. situace vedoucí k chybě","Jiné označení pro defekt v kódu nebo v dokumentaci"],"ok":[2],"vys":{"a":"Není správně. Kořenová příčina nemusí být technická, může jít např. o časový tlak nebo nedostatečné školení.","b":"Není správně. Viditelný projev defektu při spuštění je selhání.","c":"Je správně. Sylabus definuje kořenovou příčinu jako primární důvod vzniku problému, např. situaci, která vede k chybě.","d":"Není správně. Defekt je důsledkem chyby, kořenová příčina je důvod, proč k chybě vůbec došlo."},"obecne":"Sylabus 1.2.3: Kořenová příčina je primárním důvodem vzniku problému (např. situace, která vede k chybě). Identifikuje se analýzou kořenových příčin, obvykle po výskytu selhání nebo identifikaci defektu, aby bylo možné zabránit podobným selháním nebo defektům.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"}},{"id":"TR-010","n":null,"lo":"FL-1.4.4","k":"K2","k3":true,"vyber":1,"q":"Proč je důležité udržovat trasovatelnost mezi testovací bází a testwarem?","m":["Umožňuje automaticky generovat testovací skripty z požadavků","Je vyžadována jen u bezpečnostně kritických a regulovaných systémů","Nahrazuje reporty o postupu prací i souhrnné reporty z testování","Umožňuje vyhodnocovat pokrytí, určit dopad změn a usnadňuje audity"],"ok":[3],"vys":{"a":"Není správně. Generování skriptů je úkolem nástrojů, ne přínosem trasovatelnosti.","b":"Není správně. Trasovatelnost je užitečná v každém projektu, nejen u kritických systémů.","c":"Není správně. Trasovatelnost reporty nenahrazuje, ale zlepšuje jejich srozumitelnost.","d":"Je správně. Sylabus uvádí vyhodnocení pokrytí, určení dopadu změn a usnadnění auditu jako hlavní přínosy trasovatelnosti."},"obecne":"Sylabus 1.4.4: Přesná trasovatelnost umožňuje vyhodnocovat pokrytí, určit dopad změn, usnadňuje provádění auditu, pomáhá plnit kritéria správného řízení IT a zlepšuje srozumitelnost reportů z testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.4","nazev":"Trasovatelnost mezi testovací bází a pracovními produkty z testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-ctyri-trasovatelnost-mezi-testovaci-bazi-a-pracovnimi-produkty-z-testovani"}},{"id":"TR-012","n":null,"lo":"FL-1.5.1","k":"K2","k3":true,"vyber":1,"q":"Která z uvedených dovedností NEPATŘÍ mezi obecné dovednosti, které sylabus uvádí jako důležité pro testery?","m":["Programování v jazyce symbolických adres (assembler)","Analytické a kritické myšlení","Znalost domény","Komunikační dovednosti a aktivní naslouchání"],"ok":[0],"vys":{"a":"Je správně. Znalost konkrétního programovacího jazyka sylabus mezi obecné dovednosti testera neuvádí.","b":"Není správně. Analytické a kritické myšlení a kreativita zvyšují efektivitu testování.","c":"Není správně. Znalost domény pomáhá porozumět koncovým uživatelům a komunikovat s nimi.","d":"Není správně. Komunikační dovednosti a aktivní naslouchání jsou pro testery klíčové."},"obecne":"Sylabus 1.5.1: Mezi obecné dovednosti testera patří znalost testování, důkladnost a pečlivost, komunikační dovednosti a aktivní naslouchání, analytické a kritické myšlení, technické znalosti a znalost domény. Znalost konkrétního programovacího jazyka mezi nimi není.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.1","nazev":"Obecné dovednosti potřebné pro testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-jedna-obecne-dovednosti-potrebne-pro-testovani"}},{"id":"TR-013","n":null,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":1,"q":"Co znamená týmový přístup (whole team approach)?","m":["Dva vývojáři píší kód společně u jednoho počítače a navzájem se kontrolují","Každý člen týmu s potřebnými dovednostmi může dělat jakýkoli úkol a všichni odpovídají za kvalitu","Testování provádí výhradně nezávislý testovací tým mimo vývojový tým","Projektový manažer přidělí každému členovi týmu pevnou roli a odpovědnost"],"ok":[1],"vys":{"a":"Není správně. Toto je popis párového programování.","b":"Je správně. Při týmovém přístupu může každý člen týmu s potřebnými znalostmi a dovednostmi vykonávat jakýkoliv úkol a každý je zodpovědný za kvalitu.","c":"Není správně. Týmový přístup naopak zapojuje do zajištění kvality celý tým.","d":"Není správně. Týmový přístup nestaví na pevně přidělených rolích, ale na flexibilitě a sdílené odpovědnosti."},"obecne":"Sylabus 1.5.2: Týmový přístup vychází z extrémního programování. Každý člen týmu s potřebnými znalostmi a dovednostmi může vykonávat jakýkoliv úkol a každý člen týmu je zodpovědný za kvalitu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"TR-014","n":null,"lo":"FL-1.5.3","k":"K2","k3":true,"vyber":1,"q":"Co je hlavní výhodou nezávislosti testování?","m":["Nezávislé testování vždy zkracuje celkovou dobu trvání projektu","Nezávislý tester nepotřebuje znát doménu ani testovaný systém","Nezávislý tester díky odlišnému pohledu spíše odhalí jiné druhy defektů","Nezávislé testování odstraňuje potřebu provádět revize"],"ok":[2],"vys":{"a":"Není správně. Nezávislí testeři se naopak mohou stát úzkým místem a být viněni ze zpoždění.","b":"Není správně. Nezávislost není náhradou za dobrou znalost systému.","c":"Je správně. Nezávislí testeři pravděpodobněji rozpoznají jiné druhy selhání a defektů díky odlišnému zázemí, technickému nadhledu a předsudkům.","d":"Není správně. Revize jsou samostatnou formou statického testování a nezávislost je nenahrazuje."},"obecne":"Sylabus 1.5.3: Hlavním přínosem nezávislosti testování je, že nezávislí testeři dokážou pravděpodobněji rozpoznat různé druhy selhání a defektů ve srovnání s vývojáři, a to díky odlišnému zázemí, technickému nadhledu a předsudkům (kognitivnímu zkreslení).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.3","nazev":"Nezávislost testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-tri-nezavislost-testovani"}},{"id":"TR-015","n":null,"lo":"FL-1.5.3","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností je jednou z nevýhod vysoké nezávislosti testování uváděných v sylabu?","m":["Snižuje účinnost testerů při hledání defektů v pracovních produktech","Zvyšuje u testerů konfirmační zkreslení vůči kódu vývojářů","Vylučuje, aby akceptační testování prováděli zástupci byznysu","Testeři mohou být izolováni od vývojového týmu"],"ok":[3],"vys":{"a":"Není správně. Určitá míra nezávislosti naopak činí testery efektivnějšími při hledání defektů.","b":"Není správně. Odlišné zkreslení testerů je naopak důvodem, proč nezávislost pomáhá.","c":"Není správně. Akceptační testování zástupci byznysu je naopak příkladem vyšší úrovně nezávislosti.","d":"Je správně. Sylabus uvádí izolaci nezávislých testerů od vývojového týmu (horší spolupráce, problémy v komunikaci) jako nevýhodu nezávislosti."},"obecne":"Sylabus 1.5.3: Nevýhodou nezávislosti je, že nezávislí testeři mohou být izolováni od vývojového týmu (horší spolupráce, komunikace, nepřátelský vztah), vývojáři mohou ztratit pocit zodpovědnosti za kvalitu a nezávislí testeři mohou být úzkým místem nebo být viněni za zpoždění.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.5.3","nazev":"Nezávislost testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-tri-nezavislost-testovani"}},{"id":"TR-016","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"Do které testovací činnosti patří definování testovacích podmínek a stanovení jejich priorit na základě rizik?","m":["Testovací analýza","Návrh testů","Provedení testů","Implementace testování"],"ok":[0],"vys":{"a":"Je správně. Při testovací analýze se definují testovací podmínky včetně stanovení jejich priorit a souvisejících rizik.","b":"Není správně. Návrh testů rozpracovává již definované testovací podmínky do testovacích případů.","c":"Není správně. Provedení testů spouští testy a porovnává skutečné výsledky s očekávanými.","d":"Není správně. Implementace testování vytváří testware potřebný pro provedení testů, např. testovací procedury a data."},"obecne":"Sylabus 1.4.1: Testovací analýza zahrnuje analýzu testovací báze, definování testovacích podmínek včetně stanovení jejich priorit a souvisejících rizik a odpovídá na otázku „Co se má testovat?“.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"TR-017","n":null,"lo":"FL-2.1.1","k":"K2","k3":true,"vyber":1,"q":"Který z následujících je příkladem sekvenčního modelu vývoje softwaru?","m":["Extrémní programování (XP)","Vodopádový model","Scrum","Kanban"],"ok":[1],"vys":{"a":"Není správně. Extrémní programování (XP) je agilní vývojová metoda s krátkými iteracemi.","b":"Je správně. Vodopádový model je spolu s V-modelem typickým příkladem sekvenčního modelu vývoje.","c":"Není správně. Scrum je agilní rámec založený na iterativním a inkrementálním vývoji.","d":"Není správně. Kanban je agilní metoda řízení toku práce, nikoli sekvenční model vývoje."},"obecne":"Sylabus 2.1.1: mezi modely SDLC patří sekvenční modely vývoje (např. vodopádový model, V-model), iterativní a inkrementální modely. Scrum, Kanban a extrémní programování (XP) sylabus uvádí jako vývojové metody a agilní postupy, které se používají v iterativním a inkrementálním vývoji.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.1","nazev":"Vliv životního cyklu vývoje softwaru na testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-jedna-vliv-zivotniho-cyklu-vyvoje-softwaru-na-testovani"}},{"id":"TR-019","n":null,"lo":"FL-2.2.1","k":"K2","k3":true,"vyber":1,"q":"Která úroveň testování se zaměřuje na testování izolovaných komponent a obvykle ji provádějí vývojáři ve svých vývojových prostředích?","m":["Systémové integrační testování","Systémové testování","Testování komponent","Akceptační testování"],"ok":[2],"vys":{"a":"Není správně. Systémové integrační testování se zaměřuje na rozhraní mezi testovaným systémem a jinými systémy či externími službami.","b":"Není správně. Systémové testování se zaměřuje na celkové chování a schopnosti celého systému.","c":"Je správně. Testování komponent se zaměřuje na izolované komponenty a obvykle je provádějí vývojáři ve svých vývojových prostředích.","d":"Není správně. Akceptační testování validuje, že systém splňuje byznysové potřeby uživatele, a ideálně je provádějí koncoví uživatelé."},"obecne":"Sylabus 2.2.1: testování komponent (také jednotkové testování) se zaměřuje na testování izolovaných komponent. Často vyžaduje speciální podporu, např. sadu testovacího vybavení (test harness) nebo frameworky pro jednotkové testování, a obvykle jej provádějí vývojáři ve svých vývojových prostředích.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"}},{"id":"TR-020","n":null,"lo":"FL-2.2.3","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývá testování, které se provádí po opravě defektu a ověřuje, zda byl původní defekt úspěšně opraven?","m":["Regresní testování","Testování údržby","Akceptační testování","Konfirmační testování"],"ok":[3],"vys":{"a":"Není správně. Regresní testování ověřuje, zda změna (včetně opravy) nezpůsobila nežádoucí dopady v jiných částech systému.","b":"Není správně. Testování údržby se týká změn systému, který je již v provozu; samo o sobě neoznačuje ověření konkrétní opravy.","c":"Není správně. Akceptační testování validuje připravenost systému k nasazení a splnění byznysových potřeb uživatele.","d":"Je správně. Konfirmační testování potvrzuje, že byl původní defekt úspěšně opraven."},"obecne":"Sylabus 2.2.3: konfirmační testování potvrzuje, že byl původní defekt úspěšně opraven (např. opakovaným provedením testů, které dříve selhaly). Regresní testování naopak ověřuje, zda po změnách nedošlo k nežádoucím dopadům jinde.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"}},{"id":"TR-021","n":null,"lo":"FL-2.1.1","k":"K2","k3":true,"vyber":1,"q":"Které z následujících tvrzení NEJLÉPE popisuje, jak volba modelu SDLC ovlivňuje testování?","m":["Ovlivňuje rozsah a načasování testovacích činností i míru automatizace testů","Mění jen formát reportů, ale nemá vliv na techniky testování ani automatizaci","Určuje počet testerů v týmu, ale nemění načasování testovacích činností","Nemá na testování vliv, protože proces testování je ve všech modelech shodný"],"ok":[0],"vys":{"a":"Je správně. Rozsah a načasování testovacích činností i rozsah automatizace testů patří mezi oblasti, které volba SDLC ovlivňuje.","b":"Není správně. Volba SDLC ovlivňuje i volbu technik testování a rozsah automatizace testů.","c":"Není správně. Volba SDLC ovlivňuje právě rozsah a načasování testovacích činností.","d":"Není správně. Testování musí být přizpůsobeno SDLC, aby bylo úspěšné."},"obecne":"Sylabus 2.1.1: aby bylo testování úspěšné, musí být přizpůsobeno SDLC. Volba SDLC má dopad na rozsah a načasování testovacích činností, úroveň detailu testovací dokumentace, volbu technik testování a přístupu k testování, rozsah automatizace testů a role a zodpovědnosti testerů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.1","nazev":"Vliv životního cyklu vývoje softwaru na testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-jedna-vliv-zivotniho-cyklu-vyvoje-softwaru-na-testovani"}},{"id":"TR-022","n":null,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"Co mají vývoj řízený testy (TDD), vývoj řízený akceptačními testy (ATDD) a vývoj řízený chováním (BDD) společné?","m":["Testy se v nich vždy zapisují formou modelů v jazyce UML","Testy se definují dříve, než je napsán odpovídající kód","Používají se výhradně v úrovni systémového testování","Díky nim již není potřeba provádět statické testování"],"ok":[1],"vys":{"a":"Není správně. Žádný z těchto přístupů nevyžaduje modely v UML; BDD naopak používá přirozený jazyk.","b":"Je správně. Všechny tři přístupy definují testy před napsáním kódu, a uplatňují tak včasné testování a shift left.","c":"Není správně. TDD se uplatňuje typicky při testování komponent, ATDD a BDD na úrovni akceptačních kritérií.","d":"Není správně. Tyto přístupy statické testování (např. revize) nenahrazují."},"obecne":"Sylabus 2.1.3: TDD, ATDD i BDD jsou aplikací principů včasného testování a shift left – testy jsou definovány dříve, než je napsán kód. Všechny tyto přístupy podporují iterativní model vývoje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"TR-024","n":null,"lo":"FL-2.1.6","k":"K2","k3":true,"vyber":1,"q":"Co je hlavním smyslem retrospektivy z hlediska zlepšování procesu?","m":["Určit, kdo z členů týmu nese vinu za nalezené defekty","Nahradit revize pracovních produktů společnou diskuzí","Zhodnotit, co se povedlo a co ne, a naplánovat zlepšení","Nahradit souhrnný report z testování ústní diskuzí týmu"],"ok":[2],"vys":{"a":"Není správně. Retrospektiva neslouží k hledání viníků, ale ke zlepšování procesu a spolupráce.","b":"Není správně. Retrospektiva revize pracovních produktů nenahrazuje; hodnotí proces, ne konkrétní pracovní produkty.","c":"Je správně. Účastníci retrospektivy probírají, co bylo úspěšné, co se nepovedlo a jak zlepšení zavést.","d":"Není správně. Výstupy retrospektivy se naopak obvykle zaznamenávají do souhrnného reportu z testování."},"obecne":"Sylabus 2.1.6: na retrospektivě účastníci probírají, co bylo úspěšné a mělo by být zachováno, co se nepovedlo a dalo by se zlepšit a jak návrhy na zlepšení implementovat. Výstupy se zaznamenávají, obvykle jako součást souhrnného reportu z testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"}},{"id":"TR-025","n":null,"lo":"FL-2.2.2","k":"K2","k3":true,"vyber":1,"q":"Které z následujících tvrzení NEJLÉPE vystihuje rozdíl mezi funkcionálním a nefunkcionálním testováním?","m":["Funkcionální testy patří do systémového testování, nefunkcionální do akceptačního","Funkcionální testy jsou vždy manuální, nefunkcionální testy vždy automatizované","Funkcionální testy se odvozují z kódu, nefunkcionální testy ze specifikace","Funkcionální testy ověřují, co systém dělá, nefunkcionální, jak dobře se chová"],"ok":[3],"vys":{"a":"Není správně. Všechny typy testů lze aplikovat ve všech úrovních testování.","b":"Není správně. Oba typy testů lze provádět manuálně i automatizovaně.","c":"Není správně. Zdrojem testů není typ testu, ale testovací báze; oba typy se obvykle odvozují ze specifikace (požadavků).","d":"Je správně. Funkcionální testování ověřuje, „co“ má systém dělat, nefunkcionální testování, „jak dobře“ se systém chová."},"obecne":"Sylabus 2.2.2: funkcionální testování ověřuje funkce, které má komponenta nebo systém vykonávat („co“ má systém dělat). Nefunkcionální testování vyhodnocuje jiné charakteristiky než funkcionalitu („jak dobře“ se systém chová), např. výkonnostní efektivitu nebo bezpečnost. Všechny typy testů lze aplikovat ve všech úrovních testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.2.2","nazev":"Typy testů","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-dva-typy-testu"}},{"id":"TR-026","n":null,"lo":"FL-2.2.2","k":"K2","k3":true,"vyber":1,"q":"Které z následujících tvrzení NEJLÉPE vystihuje rozdíl mezi testováním černé skříňky a testováním bílé skříňky?","m":["Testování černé skříňky vychází ze specifikace, testování bílé skříňky ze struktury","Testování bílé skříňky lze použít pouze pro nefunkcionální charakteristiky systému","Testování černé skříňky se provádí manuálně, testování bílé skříňky automatizovaně","Testování černé skříňky vyžaduje přístup ke zdrojovému kódu testovaného objektu"],"ok":[0],"vys":{"a":"Je správně. Testování černé skříňky je založeno na specifikaci, testování bílé skříňky na vnitřní struktuře (např. kódu).","b":"Není správně. Testování bílé skříňky se používá zejména pro funkcionalitu a strukturu kódu, není omezeno na nefunkcionální charakteristiky.","c":"Není správně. Oba typy testů lze provádět manuálně i automatizovaně.","d":"Není správně. Testování černé skříňky naopak nevychází z vnitřní struktury, přístup ke kódu nepotřebuje."},"obecne":"Sylabus 2.2.2: testování černé skříňky je založeno na specifikaci a odvozuje testy z dokumentace, která nesouvisí s vnitřní strukturou testovaného objektu. Testování bílé skříňky je založeno na struktuře a odvozuje testy z implementace nebo vnitřní struktury systému (kód, architektura, pracovní toky, datové toky).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.2","nazev":"Typy testů","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-dva-typy-testu"}},{"id":"TR-027","n":null,"lo":"FL-2.2.3","k":"K2","k3":true,"vyber":1,"q":"Proč je regresní testování vhodným kandidátem na automatizaci?","m":["Regresní testy nelze provádět manuálně, a proto se musí automatizovat","Regresní sady se spouštějí opakovaně a jejich rozsah s iteracemi roste","Regresní testování se v projektu provádí jen jednou, těsně před vydáním","Automatizaci regresních testů povinně vyžaduje norma ISO/IEC 25010"],"ok":[1],"vys":{"a":"Není správně. Regresní testy lze provádět i manuálně, jen je to při častém opakování neefektivní.","b":"Je správně. Sady regresních testů se spouštějí mnohokrát a jejich počet obvykle s každou iterací nebo vydáním roste.","c":"Není správně. Regresní testy se spouštějí mnohokrát, typicky po každé změně.","d":"Není správně. Norma ISO/IEC 25010 popisuje charakteristiky kvality, automatizaci regresních testů nepředepisuje."},"obecne":"Sylabus 2.2.3: sady regresních testů se spouštějí mnohokrát a obvykle se jejich počet zvyšuje s každou novou iterací nebo vydáním, proto je regresní testování silným kandidátem na automatizaci. Automatizaci je vhodné zahájit již v raných fázích projektu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"}},{"id":"TR-028","n":null,"lo":"FL-2.3.1","k":"K2","k3":true,"vyber":1,"q":"Co z následujícího typicky spouští testování údržby?","m":["Změna ve složení testovacího týmu nebo v jeho vedení","Návrh nového systému, který dosud nebyl v provozu","Úprava, migrace nebo vyřazení provozovaného systému","Dokončení revize požadavků na budoucí systém"],"ok":[2],"vys":{"a":"Není správně. Personální změny v týmu nejsou změnou systému, a tedy nespouštějí testování údržby.","b":"Není správně. Testování údržby se týká systému, který je již v provozu.","c":"Je správně. Úpravy, aktualizace či migrace provozního prostředí a vyřazení z provozu jsou spouštěči testování údržby.","d":"Není správně. Revize požadavků na nový systém je statické testování ve vývoji, nikoli spouštěč údržby."},"obecne":"Sylabus 2.3: spouštěči údržby a testování údržby jsou úpravy (plánovaná vylepšení, opravné změny, hotfixy), aktualizace nebo migrace provozního prostředí a vyřazení aplikace z provozu na konci její životnosti.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.3","nazev":"Testování údržby","href":"kapitola-2/vyklad.html#cast-dva-tecka-tri-testovani-udrzby"}},{"id":"TR-029","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"Který z uvedených NENÍ typem revize podle sylabu ISTQB?","m":["Předvedení (walkthrough)","Technická revize","Inspekce","Regresní revize"],"ok":[3],"vys":{"a":"Není správně. Předvedení (walkthrough) je jedním z běžně používaných typů revizí.","b":"Není správně. Technická revize je jedním z běžně používaných typů revizí.","c":"Není správně. Inspekce je nejformálnějším typem revize.","d":"Je správně. Regresní revize není typem revize uvedeným v sylabu; regresní je typ testování, ne revize."},"obecne":"Sylabus 3.2.4 uvádí jako běžně používané typy revizí neformální revizi, předvedení (walkthrough), technickou revizi a inspekci. „Regresní revize“ mezi ně nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"TR-030","n":null,"lo":"FL-3.2.3","k":"K1","k3":true,"vyber":1,"q":"Kdo při revizi zajišťuje efektivní průběh revizních schůzek včetně mediace, dodržení časového rámce a bezpečné atmosféry pro diskusi?","m":["Moderátor","Autor","Zapisovatel","Manažer"],"ok":[0],"vys":{"a":"Je správně. Moderátor (facilitátor) zajišťuje efektivní průběh revizních schůzek včetně mediace a dodržení časového rámce.","b":"Není správně. Autor vytváří a opravuje revidovaný pracovní produkt.","c":"Není správně. Zapisovatel shromažďuje anomálie a zaznamenává informace z revize.","d":"Není správně. Manažer rozhoduje, co se bude revidovat, a přiděluje zdroje."},"obecne":"Sylabus 3.2.3: moderátor (někdy také facilitátor) zajišťuje efektivní průběh revizních schůzek včetně mediace, dohlíží na časový rámec a vytváří bezpečné prostředí, kde může každý svobodně vyjádřit názor.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"}},{"id":"TR-031","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývá nejformálnější typ revize, který se řídí kompletním obecným procesem revize?","m":["Předvedení (walkthrough)","Inspekce","Technická revize","Neformální revize"],"ok":[1],"vys":{"a":"Není správně. Předvedení vede autor a nemusí se řídit kompletním procesem.","b":"Je správně. Inspekce je nejformálnějším typem revize a řídí se kompletním obecným procesem.","c":"Není správně. Technická revize je formální, ale nejformálnějším typem je inspekce.","d":"Není správně. Neformální revize se neřídí definovaným procesem."},"obecne":"Sylabus 3.2.4: inspekce jsou nejformálnějším typem revize, řídí se kompletním obecným procesem (viz 3.2.2) a jejich hlavním cílem je nalézt maximální počet anomálií.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"TR-032","n":null,"lo":"FL-3.1.3","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností NEJLÉPE popisuje statickou analýzu?","m":["Typ dynamického testování, při kterém se za běhu programu vyhodnocují logy","Typ revize vedené autorem, při které revidující společně procházejí produkt","Typ statického testování, při kterém nástroj hledá defekty bez spuštění kódu","Technika testování černé skříňky pro odvozování testovacích případů"],"ok":[2],"vys":{"a":"Není správně. Vyhodnocování za běhu programu je dynamické testování.","b":"Není správně. Revize vedená autorem je předvedení (walkthrough), tedy revize, nikoli statická analýza.","c":"Je správně. Statická analýza je nástroji podporované statické testování, které nevyžaduje spuštění kódu.","d":"Není správně. Statická analýza není technikou návrhu testovacích případů."},"obecne":"Sylabus 3.1: pracovní produkty se při statickém testování hodnotí buď manuálně (revize), nebo pomocí nástroje (statická analýza); software se přitom nespouští. Statická analýza tak může odhalit např. nedosažitelný kód nebo bezpečnostní zranitelnosti.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"}},{"id":"TR-033","n":null,"lo":"FL-3.1.3","k":"K2","k3":true,"vyber":1,"q":"Které z následujících tvrzení NEJLÉPE vystihuje rozdíl mezi statickým a dynamickým testováním?","m":["Statické testování hledá selhání za běhu, dynamické odhaluje defekty přímo v kódu","Statické testování lze použít pouze na zdrojový kód, dynamické na jakýkoli pracovní produkt","Dynamické testování je vždy levnější, protože nevyžaduje účast zainteresovaných stran","Statické testování nachází defekty přímo, dynamické hledá selhání, z nichž se defekty určí analýzou"],"ok":[3],"vys":{"a":"Není správně. Role jsou prohozené – selhání hledá dynamické testování.","b":"Není správně. Je to naopak: statické testování lze použít i na nespustitelné pracovní produkty, dynamické jen na spustitelné.","c":"Není správně. Defekty nalezené staticky v rané fázi bývají levnější na opravu; dynamické testování není vždy levnější.","d":"Je správně. Statické testování nachází defekty přímo, dynamické testování způsobuje selhání, z nichž se defekty určí následnou analýzou."},"obecne":"Sylabus 3.1.3: statické testování najde defekty přímo, zatímco dynamické testování hledá selhání, ze kterých jsou příslušné defekty určeny následnou analýzou. Statické testování lze navíc použít i na nespustitelné pracovní produkty.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"}},{"id":"TR-034","n":null,"lo":"FL-3.1.3","k":"K2","k3":true,"vyber":1,"q":"Který typ defektů se obvykle snáze a levněji odhalí statickým testováním než dynamickým?","m":["Nekonzistence a nejednoznačnosti v požadavcích","Nesprávné nastavení produkčního prostředí za provozu","Problémy s výkonností systému pod zátěží","Selhání projevující se jen při určité kombinaci vstupů za běhu"],"ok":[0],"vys":{"a":"Je správně. Defekty v požadavcích (nekonzistence, nejednoznačnosti, rozpory, opomenutí) se snáze a levněji odhalí revizí.","b":"Není správně. Problémy produkčního prostředí za provozu se projeví až při běhu systému.","c":"Není správně. Výkonnostní efektivitu, která závisí na spuštění kódu, měří dynamické testování.","d":"Není správně. Selhání při určité kombinaci vstupů odhalí spuštění kódu, tedy dynamické testování."},"obecne":"Sylabus 3.1.3 uvádí mezi typickými defekty, které se snáze a levněji odhalí statickým testováním, defekty v požadavcích, např. nesrovnalosti, nejednoznačnosti, rozpory, opomenutí, nepřesnosti a duplicity.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"}},{"id":"TR-035","n":null,"lo":"FL-3.2.1","k":"K1","k3":true,"vyber":1,"q":"Proč je včasná a častá zpětná vazba od zainteresovaných stran přínosná?","m":["Je vyžadována pouze u inspekcí, kde zainteresované strany působí jako revidující","Pomáhá včas odhalit potenciální problémy s kvalitou a předejít nákladnému přepracování","Umožňuje vynechat testování na konci iterace, protože požadavky jsou již ověřené","Nahrazuje dynamické testování, protože problémy odhalí samy zainteresované strany"],"ok":[1],"vys":{"a":"Není správně. Zpětná vazba se vyžaduje průběžně během celého SDLC, nejen u inspekcí.","b":"Je správně. Včasná a častá zpětná vazba pomáhá s odhalením potenciálních problémů s kvalitou a snižuje riziko vícenákladů na přepracování.","c":"Není správně. Zpětná vazba neodstraňuje potřebu testování.","d":"Není správně. Zpětná vazba od zainteresovaných stran testování nenahrazuje."},"obecne":"Sylabus 3.2.1: včasná a častá zpětná vazba pomáhá s odhalením potenciálních problémů s kvalitou. Bez ní hrozí, že produkt nebude odpovídat představám zainteresovaných stran, což vede k vícenákladům na přepracování, zmeškaným termínům a vzájemnému obviňování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.1","nazev":"Výhody včasné a časté zpětné vazby od zainteresovaných stran","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-jedna-vyhody-vcasne-a-caste-zpetne-vazby-od-zainteresovanych-stran"}},{"id":"TR-036","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"Co je hlavním cílem inspekce jako typu revize?","m":["Vzdělávat revidující bez nutnosti přípravy","Dosáhnout shody v technickém problému","Nalézt maximální počet anomálií","Generovat nové nápady bez zaznamenání výsledků"],"ok":[2],"vys":{"a":"Není správně. Vzdělávání revidujících je jedním z cílů předvedení, nikoli hlavním cílem inspekce.","b":"Není správně. Dosažení shody a rozhodnutí o technickém problému je hlavním cílem technické revize.","c":"Je správně. Hlavním cílem inspekce je nacházet maximální počet anomálií.","d":"Není správně. Inspekce má formální dokumentovaný výstup a shromažďují se při ní metriky."},"obecne":"Sylabus 3.2.4: inspekce je nejformálnějším typem revize; jejím hlavním cílem je nacházet maximální počet anomálií. Shromažďují se při ní metriky pro zlepšování SDLC včetně procesu inspekce.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"TR-037","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"Do které kategorie technik testování patří průzkumné testování?","m":["Techniky testování bílé skříňky","Přístupy k testování založené na spolupráci","Techniky testování černé skříňky","Techniky testování založené na zkušenostech"],"ok":[3],"vys":{"a":"Není správně. Techniky bílé skříňky vycházejí z vnitřní struktury testovaného objektu (např. testování příkazů a větví).","b":"Není správně. Přístupy založené na spolupráci (společné psaní uživatelských scénářů, akceptační kritéria, ATDD) se zaměřují na prevenci defektů, průzkumné testování mezi ně nepatří.","c":"Není správně. Techniky černé skříňky vycházejí z analýzy specifikovaného chování (např. rozdělení tříd ekvivalence), ne ze znalostí a zkušeností testera.","d":"Je správně. Průzkumné testování je spolu s odhadováním chyb a testováním založeným na kontrolních seznamech technikou založenou na zkušenostech."},"obecne":"Sylabus 4.4: Mezi nejznámější techniky testování založené na zkušenostech patří odhadování chyb, průzkumné testování a testování založené na kontrolních seznamech. Využívají znalosti a zkušenosti testerů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"TR-038","n":null,"lo":"FL-4.2.1","k":"K3","k3":false,"vyber":1,"q":"Na jakém předpokladu je založena technika rozdělení tříd ekvivalence?","m":["Všechny hodnoty jedné třídy ekvivalence zpracuje testovaný objekt stejným způsobem.","Každá třída ekvivalence musí obsahovat nekonečně mnoho hodnot, aby ji šlo testovat.","Třídy ekvivalence se odvozují ze struktury kódu, jde tedy o techniku bílé skříňky.","Testovací případy musí pokrýt všechny možné kombinace vstupních hodnot."],"ok":[0],"vys":{"a":"Je správně. Pokud test odhalí defekt pro jednu hodnotu třídy, měl by ho odhalit i pro kteroukoli jinou hodnotu téže třídy.","b":"Není správně. Třídy mohou být konečné i nekonečné, musí však být neprázdné a nesmí se překrývat.","c":"Není správně. Rozdělení tříd ekvivalence je technika testování černé skříňky, vychází ze specifikovaného chování.","d":"Není správně. Kompletní testování všech kombinací není možné; EP naopak počet testů snižuje."},"obecne":"Sylabus 4.2.1: Rozdělení tříd ekvivalence dělí data do tříd, u kterých lze očekávat stejný způsob zpracování testovaným objektem. Proto stačí z každé třídy otestovat alespoň jednu hodnotu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"TR-039","n":null,"lo":"FL-4.2.2","k":"K3","k3":false,"vyber":1,"q":"Jaký je rozdíl mezi dvouhodnotovou a tříhodnotovou analýzou hraničních hodnot?","m":["Tříhodnotovou variantu nelze použít pro uspořádané třídy, dvouhodnotovou ano.","U tříhodnotové varianty jsou položkami pokrytí hraniční hodnota i oba její sousedé.","Obě varianty mají pro každou hranici stejné položky pokrytí, liší se jen výpočtem pokrytí.","Dvouhodnotová varianta je technikou bílé skříňky, tříhodnotová technikou černé skříňky."],"ok":[1],"vys":{"a":"Není správně. Analýzu hraničních hodnot (obě varianty) lze naopak použít POUZE pro uspořádané třídy.","b":"Je správně. Dvouhodnotová varianta testuje hraniční hodnotu a nejbližšího souseda ze sousední třídy, tříhodnotová hraniční hodnotu a oba její sousedy, a je proto přísnější.","c":"Není správně. Dvouhodnotová varianta má pro každou hranici 2 položky pokrytí, tříhodnotová 3.","d":"Není správně. Obě varianty analýzy hraničních hodnot jsou techniky testování černé skříňky."},"obecne":"Sylabus 4.2.2: Při dvouhodnotové BVA existují pro každou hranici dvě položky pokrytí (hraniční hodnota a její nejbližší soused v sousední třídě), při tříhodnotové tři (hraniční hodnota a oba sousedé). Tříhodnotová BVA je přísnější a odhalí i defekty, které dvouhodnotová přehlédne (např. „x ≤ 10“ implementované jako „x = 10“).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"TR-040","n":null,"lo":"FL-4.2.3","k":"K3","k3":false,"vyber":1,"q":"Co představují sloupce rozhodovací tabulky?","m":["Testovací prostředí a konfigurace, ve kterých se pravidla ověřují","Jednotlivé akce, tedy výstupy, které může systém vyprodukovat","Jednotlivá pravidla, tj. jedinečné kombinace podmínek a jejich akcí","Jednotlivé podmínky, tedy vstupní parametry testovaného objektu"],"ok":[2],"vys":{"a":"Není správně. Testovací prostředí není součástí rozhodovací tabulky.","b":"Není správně. Akce tvoří druhou skupinu řádků tabulky.","c":"Je správně. Každý sloupec odpovídá jednomu pravidlu, které definuje jedinečnou kombinaci podmínek a akce, které z ní vyplývají.","d":"Není správně. Podmínky tvoří řádky (horní skupinu řádků) tabulky, nikoli sloupce."},"obecne":"Sylabus 4.2.3: Podmínky a akce tvoří dvě skupiny řádků rozhodovací tabulky. Každý sloupec odpovídá jednomu pravidlu, tj. jedinečné kombinaci podmínek vedoucí k provedení přiřazených akcí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"TR-041","n":null,"lo":"FL-4.2.3","k":"K3","k3":false,"vyber":1,"q":"Co znamená v rozhodovací tabulce symbol „–“ uvedený u podmínky?","m":["Akce by v daném pravidle neměla nastat.","Podmínka není v daném pravidle splněna.","Podmínka je pro dané pravidlo neproveditelná.","Hodnota podmínky je pro výsledek irelevantní."],"ok":[3],"vys":{"a":"Není správně. U akcí se to, že akce nemá nastat, označuje prázdnou buňkou; „–“ se používá u podmínek.","b":"Není správně. Nesplněnou podmínku označuje „F“ (false).","c":"Není správně. Neproveditelnou podmínku označuje symbol „N/A“.","d":"Je správně. „–“ znamená, že na hodnotě podmínky pro výsledek akce (výstup) nezáleží."},"obecne":"Sylabus 4.2.3: U podmínek se používají symboly „T“ (podmínka splněna), „F“ (nesplněna), „–“ (hodnota podmínky je pro výsledek irelevantní) a „N/A“ (podmínka je pro dané pravidlo neproveditelná).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"TR-042","n":null,"lo":"FL-4.2.4","k":"K3","k3":false,"vyber":1,"q":"Co zobrazuje stavová tabulka na rozdíl od stavového diagramu?","m":["Zobrazuje i neplatné přechody, a to jako prázdné buňky tabulky.","Obsahuje hotové testovací případy, které už není třeba odvozovat.","Zobrazuje pouze platné přechody, neplatné přechody vynechává.","Zobrazuje pouze stavy systému, přechody mezi nimi nezobrazuje."],"ok":[0],"vys":{"a":"Je správně. Řádky jsou stavy, sloupce události a prázdné buňky představují neplatné přechody.","b":"Není správně. Stavová tabulka je model, ze kterého se testovací případy teprve odvozují.","c":"Není správně. Platné přechody zobrazuje i stavový diagram; tabulka navíc ukazuje neplatné.","d":"Není správně. Buňky stavové tabulky představují právě přechody (cílový stav a případné akce)."},"obecne":"Sylabus 4.2.4: Stavová tabulka je ekvivalentní stavovému diagramu. Na rozdíl od něj však explicitně zobrazuje i neplatné přechody, které jsou reprezentovány prázdnými buňkami.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"TR-043","n":null,"lo":"FL-4.2.4","k":"K3","k3":false,"vyber":1,"q":"Které z následujících tvrzení o vztahu mezi pokrytím všech stavů a pokrytím platných přechodů je SPRÁVNÉ?","m":["Pokrytí všech stavů je silnější kritérium než pokrytí platných přechodů.","100% pokrytí platných přechodů zaručuje i 100% pokrytí všech stavů.","Obě kritéria jsou na sobě nezávislá, žádné nezaručuje splnění druhého.","Ani 100% pokrytí všech přechodů nezaručuje 100% pokrytí všech stavů."],"ok":[1],"vys":{"a":"Není správně. Je to naopak: pokrytí všech stavů je „slabší“, protože ho lze obvykle dosáhnout bez provedení všech přechodů.","b":"Je správně. Když testy projdou všechny platné přechody, navštíví tím i všechny stavy.","c":"Není správně. Plné pokrytí platných přechodů zaručuje plné pokrytí všech stavů.","d":"Není správně. Plné pokrytí všech přechodů zaručuje jak plné pokrytí všech stavů, tak plné pokrytí platných přechodů."},"obecne":"Sylabus 4.2.4: Dosažení plného pokrytí platných přechodů garantuje také plné pokrytí všech stavů. Plné pokrytí všech přechodů zaručuje obojí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"TR-047","n":null,"lo":"FL-4.5.2","k":"K2","k3":true,"vyber":1,"q":"Co jsou akceptační kritéria uživatelského scénáře?","m":["Technický popis architektury, podle které bude uživatelský scénář implementován","Harmonogram testovacích činností naplánovaných pro uživatelský scénář","Podmínky, které musí implementace scénáře splnit, aby ji zainteresované strany přijaly","Seznam defektů, které byly nalezeny při revizi uživatelského scénáře"],"ok":[2],"vys":{"a":"Není správně. Akceptační kritéria popisují požadované chování z pohledu zainteresovaných stran, ne technické řešení.","b":"Není správně. Harmonogram testování je součástí plánování testování, ne akceptačních kritérií.","c":"Je správně. Akceptační kritéria jsou podmínky přijetí implementace a lze je chápat jako testovací podmínky pro akceptační testy.","d":"Není správně. Výstupem revize jsou anomálie či defekty, ne akceptační kritéria."},"obecne":"Sylabus 4.5.2: Akceptační kritéria uživatelského scénáře jsou podmínky, které musí jeho implementace splňovat, aby byla přijata zainteresovanými stranami. Lze na ně pohlížet jako na testovací podmínky, které by měly testy prověřit.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"}},{"id":"TR-048","n":null,"lo":"FL-4.5.3","k":"K3","k3":false,"vyber":1,"q":"Co je hlavním principem vývoje řízeného akceptačními testy (ATDD)?","m":["Testovací případy z akceptačních testů nahrazují průzkumné testování a další techniky.","Testovací případy se píší až po nasazení uživatelského scénáře do produkce.","Testovací případy se tvoří výhradně technikami bílé skříňky na úrovni komponent.","Testovací případy se odvozují z akceptačních kritérií ještě před implementací scénáře."],"ok":[3],"vys":{"a":"Není správně. Při návrhu testů v ATDD lze naopak použít techniky z kapitol 4.2, 4.3 a 4.4; ATDD je nenahrazuje.","b":"Není správně. ATDD je přístup iniciovaný testy – testy vznikají před implementací, ne po nasazení.","c":"Není správně. ATDD vychází z akceptačních kritérií, tedy z pohledu zainteresovaných stran, ne ze struktury kódu.","d":"Je správně. Testovací případy vytvářejí členové týmu s různými perspektivami na základě akceptačních kritérií ještě před implementací."},"obecne":"Sylabus 4.5.3: ATDD je přístup iniciovaný testy, při kterém jsou testovací případy vytvořeny na základě akceptačních kritérií před vlastní implementací uživatelského scénáře.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"TR-049","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"Pole přijímá věk zákazníka v rozsahu 18–65 let (včetně), hodnoty jsou celá čísla. Které dvě hodnoty by měl tester použít pro DOLNÍ hranici platné třídy ekvivalence při použití dvouhodnotové analýzy hraničních hodnot?","m":["17 a 18","16 a 17","18 a 19","65 a 66"],"ok":[0],"vys":{"a":"Je správně. Hraniční hodnota 18 a její nejbližší soused v sousední (neplatné) třídě, tedy 17.","b":"Není správně. 16 není hraniční hodnotou žádné třídy; hraniční hodnotou je jen 17.","c":"Není správně. 19 patří do stejné třídy jako 18; dvojice 18 a 19 by vznikla jen jako část tříhodnotové BVA.","d":"Není správně. Jde o horní hranici platné třídy, ne o dolní."},"obecne":"Sylabus 4.2.2: Při dvouhodnotové BVA jsou pro každou hranici dvě položky pokrytí – hraniční hodnota a její nejbližší soused patřící do sousední třídy. Pro dolní hranici 18 jsou to hodnoty 17 a 18.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"TR-051","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"Rozhodovací tabulka s omezeným počtem vstupů má dvě podmínky, každá může nabývat hodnot T nebo F. Všechny kombinace podmínek jsou proveditelné. Kolik pravidel (sloupců) bude mít úplná rozhodovací tabulka?","m":["2","4","8","16"],"ok":[1],"vys":{"a":"Není správně. To je počet hodnot jedné podmínky, ne počet kombinací dvou podmínek.","b":"Je správně. Dvě podmínky se dvěma hodnotami dávají 2 × 2 = 4 kombinace.","c":"Není správně. 8 = 2³ by platilo pro tři podmínky.","d":"Není správně. 16 = 2⁴ by platilo pro čtyři podmínky."},"obecne":"Sylabus 4.2.3: Úplná rozhodovací tabulka obsahuje takový počet sloupců, aby pokryla každou kombinaci podmínek. Pro dvě booleovské podmínky je to 2² = 4 pravidla.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"TR-052","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"Model bankomatu obsahuje platné i neplatné přechody. Tester provede jeden testovací případ: vložení karty → zadání správného PIN → výběr hotovosti → vysunutí karty. Tento test projde každý platný přechod modelu, ale nepokusí se o žádný neplatný přechod. Jakého pokrytí tester dosáhl?","m":["100% pokrytí všech přechodů, protože prošel všechny přechody modelu","100% pokrytí všech stavů, ale ne 100% pokrytí platných přechodů","100% pokrytí platných přechodů, ale ne 100% pokrytí všech přechodů","0% pokrytí, protože neotestoval žádný neplatný přechod"],"ok":[2],"vys":{"a":"Není správně. Pokrytí všech přechodů vyžaduje i pokusy o neplatné přechody.","b":"Není správně. Test prošel všechny platné přechody, takže pokrytí platných přechodů je 100 %.","c":"Je správně. Všechny platné přechody byly provedeny, ale o neplatné přechody se test nepokusil.","d":"Není správně. Pokrytí platných přechodů a pokrytí všech stavů je stoprocentní; neplatné přechody ovlivňují jen pokrytí všech přechodů."},"obecne":"Sylabus 4.2.4: Pro 100% pokrytí platných přechodů musí testy provést všechny platné přechody (tím je zaručeno i pokrytí všech stavů). Pro 100% pokrytí všech přechodů je navíc nutné pokusit se provést i všechny neplatné přechody.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"TR-053","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"Pole přijímá jako platná celá čísla 1–100. Hodnoty menší než 1 systém odmítne s hlášením „hodnota je příliš nízká“, hodnoty větší než 100 s hlášením „hodnota je příliš vysoká“. Kolik tříd ekvivalence je třeba identifikovat a pokrýt pro dosažení 100% pokrytí rozdělení tříd ekvivalence?","m":["2 – jedna platná třída 1–100 a jedna společná neplatná třída","100 – každá platná hodnota tvoří samostatnou třídu ekvivalence","1 – jen platná třída 1–100, neplatné hodnoty se nepokrývají","3 – platná třída 1–100 a dvě neplatné třídy (pod 1 a nad 100)"],"ok":[3],"vys":{"a":"Není správně. Hodnoty pod 1 a nad 100 systém zpracovává odlišně (jiné hlášení), nemohou tedy být ve stejné třídě.","b":"Není správně. Všechny hodnoty 1–100 jsou zpracovány stejně, tvoří tedy jedinou třídu.","c":"Není správně. 100% pokrytí EP vyžaduje pokrýt i všechny neplatné třídy.","d":"Je správně. Platná třída 1–100 a dvě neplatné třídy, protože systém každou z nich zpracovává jinak."},"obecne":"Sylabus 4.2.1: Do stejné třídy ekvivalence patří jen hodnoty, u kterých lze očekávat stejný způsob zpracování. Pro 100% pokrytí je nutné pokrýt všechny identifikované třídy včetně neplatných – zde jednu platnou a dvě neplatné.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"TR-054","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"Kód obsahuje jediný příkaz IF-ELSE (jedna podmínka, dvě podmíněné větve) bez cyklů a vnořených konstrukcí. Kolik testovacích případů je MINIMÁLNĚ potřeba k dosažení 100% pokrytí větví?","m":["1","2","3","4"],"ok":[1],"vys":{"a":"Není správně. Jeden test projde jen jednou z obou podmíněných větví (pravda, nebo nepravda).","b":"Je správně. Jeden test pro výsledek pravda a jeden pro výsledek nepravda pokryje obě větve.","c":"Není správně. Třetí test by žádnou novou větev nepokryl.","d":"Není správně. Čtyři testy by byly potřeba až pro dvě nezávislá rozhodnutí v kombinacích."},"obecne":"Sylabus 4.3.2: Při 100% pokrytí větví musí testy pokrýt všechny podmíněné i nepodmíněné větve. Jedno rozhodnutí IF-ELSE má dvě podmíněné větve, takže stačí dva testy; tím je zároveň dosaženo i 100% pokrytí příkazů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"TR-055","n":null,"lo":"FL-4.2.4","k":"K3","k3":false,"vyber":1,"q":"Stavová tabulka modelu obsahuje 5 platných a 3 neplatné přechody. Co je potřeba k dosažení 100% pokrytí všech přechodů?","m":["Pokrýt všechny stavy modelu; tím jsou automaticky pokryty i všechny přechody.","Provést 5 platných přechodů a pokusit se o 3 neplatné, každý v jiném testu.","Provést všech 5 platných přechodů; neplatné se do tohoto pokrytí nezapočítávají.","Pokusit se jen o 3 neplatné přechody; platné jsou pokryty už pokrytím stavů."],"ok":[1],"vys":{"a":"Není správně. Pokrytí všech stavů je nejslabší kritérium a pokrytí přechodů nezaručuje.","b":"Je správně. Je nutné pokrýt platné i neplatné přechody; jeden neplatný přechod na test snižuje riziko maskování defektu.","c":"Není správně. To stačí jen pro pokrytí platných přechodů, pokrytí všech přechodů zahrnuje i neplatné.","d":"Není správně. Pokrytí všech stavů nezaručuje pokrytí platných přechodů; je nutné provést i všechny platné přechody."},"obecne":"Sylabus 4.2.4: Pro 100% pokrytí všech přechodů musí testy provést všechny platné přechody a pokusit se provést i neplatné. Je vhodné testovat jeden neplatný přechod v jednom testovacím případu, aby se snížilo riziko maskování defektu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"TR-056","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"Testovaná položka má dva nezávislé vstupní parametry; pro každý z nich byly identifikovány 2 třídy ekvivalence. Jaký je MINIMÁLNÍ počet testovacích případů pro dosažení 100% pokrytí každé volby (Each Choice)?","m":["1","2","4","8"],"ok":[1],"vys":{"a":"Není správně. Jeden test pokryje z každého parametru jen jednu třídu, druhá třída každého parametru zůstane nepokryta.","b":"Je správně. Každý test může pokrýt jednu třídu z každého parametru, takže dva testy pokryjí všechny čtyři třídy.","c":"Není správně. Čtyři testy by byly potřeba pro všechny kombinace tříd, ty ale pokrytí každé volby nevyžaduje.","d":"Není správně. Tolik testů není potřeba ani pro všechny kombinace (2 × 2 = 4)."},"obecne":"Sylabus 4.2.1: Pokrytí každé volby vyžaduje, aby testovací případy pokryly každou třídu z každé množiny tříd alespoň jednou, a nebere v úvahu kombinace tříd. Minimum je tedy rovno největšímu počtu tříd jednoho parametru, zde 2.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"TR-057","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"Pole „Sleva v %“ přijímá celá čísla v platném rozsahu 0–50. Které hodnoty představují položky pokrytí tříhodnotové analýzy hraničních hodnot pro HORNÍ hranici platné třídy?","m":["50, 51, 52","0, 50","48, 49, 50","49, 50, 51"],"ok":[3],"vys":{"a":"Není správně. 52 není sousedem hraniční hodnoty 50; chybí soused 49.","b":"Není správně. Jde o dolní a horní hraniční hodnotu platné třídy, ne o tři hodnoty jedné hranice.","c":"Není správně. 48 není sousedem hraniční hodnoty 50; chybí soused 51 z neplatné třídy.","d":"Je správně. Hraniční hodnota 50 a oba její sousedé 49 a 51."},"obecne":"Sylabus 4.2.2: Při tříhodnotové BVA existují pro každou hranici tři položky pokrytí – hraniční hodnota a oba její sousedé. Pro horní hranici 50 jsou to 49, 50 a 51.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"TR-058","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"Rozhodovací tabulka má dvě podmínky A a B (hodnoty T/F), všechny kombinace jsou proveditelné. Akce má nastat pouze tehdy, když A = T a současně B = F. V kolika pravidlech úplné rozhodovací tabulky bude tato akce označena „X“?","m":["1","2","3","4"],"ok":[0],"vys":{"a":"Je správně. Ze čtyř kombinací (TT, TF, FT, FF) vede k akci jen kombinace A = T, B = F.","b":"Není správně. Dvě pravidla by akci měla, kdyby stačilo splnit jen podmínku A.","c":"Není správně. Tři pravidla by akci měla, kdyby stačilo splnit A nebo nesplnit B.","d":"Není správně. Akce by pak nastala vždy, bez ohledu na podmínky."},"obecne":"Sylabus 4.2.3: Úplná tabulka se dvěma booleovskými podmínkami má 4 pravidla (TT, TF, FT, FF). Akce označená „X“ nastane jen v pravidle A = T, B = F.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"TR-059","n":null,"lo":"FL-5.1.1","k":"K2","k3":true,"vyber":1,"q":"Který dokument typicky obsahuje harmonogram testování, registr rizik a vstupní a výstupní kritéria?","m":["Report o defektu","Plán testování","Protokol testů","Souhrnný report z testování"],"ok":[1],"vys":{"a":"Není správně. Report o defektu popisuje jeden konkrétní defekt a informace potřebné k jeho reprodukci a vyřešení.","b":"Je správně. Plán testování obsahuje mimo jiné registr rizik, přístup k testování (včetně vstupních a výstupních kritérií) a rozpočet a harmonogram.","c":"Není správně. Protokol testů zaznamenává průběh a výsledky provedení testů, neobsahuje registr rizik ani kritéria.","d":"Není správně. Souhrnný report z testování vyhodnocuje dokončené testování; rizika a kritéria nedefinuje, jen hodnotí jejich stav."},"obecne":"Sylabus 5.1.1: Plán testování obvykle obsahuje kontext testování, předpoklady a omezení, zainteresované strany, plán komunikace, registr rizik, přístup k testování (včetně vstupních a výstupních kritérií) a rozpočet a harmonogram.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.1","nazev":"Účel a obsah plánu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-jedna-ucel-a-obsah-planu-testovani"}},{"id":"TR-060","n":null,"lo":"FL-5.1.3","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývají kritéria, která musí být splněna PŘED zahájením určité testovací činnosti?","m":["Akceptační kritéria","Kritéria pokrytí","Vstupní kritéria","Výstupní kritéria"],"ok":[2],"vys":{"a":"Není správně. Akceptační kritéria jsou podmínky, které musí splnit implementace uživatelského scénáře, aby ji zainteresované strany přijaly.","b":"Není správně. Kritéria pokrytí určují, jaké pokrytí má testování dosáhnout; mohou být součástí výstupních kritérií.","c":"Je správně. Vstupní kritéria určují předpoklady pro realizaci dané činnosti.","d":"Není správně. Výstupní kritéria určují podmínky, které musí být splněny, aby bylo možné činnost prohlásit za dokončenou."},"obecne":"Sylabus 5.1.3: Vstupní kritéria určují předpoklady pro realizaci dané činnosti (např. dostupnost zdrojů a testwaru, počáteční úroveň kvality testovaného objektu). Výstupní kritéria určují podmínky, kterých musí být dosaženo, aby bylo možné činnost prohlásit za dokončenou.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"}},{"id":"TR-061","n":null,"lo":"FL-5.2.2","k":"K2","k3":true,"vyber":1,"q":"Jaký je rozdíl mezi projektovým a produktovým rizikem?","m":["Produktová rizika se řeší pouze na úrovni akceptačního testování","Projektová rizika se týkají výhradně práce testovacího týmu","Projektové a produktové riziko jsou synonyma pro tutéž kategorii rizik","Projektové riziko ohrožuje cíle projektu, produktové kvalitu produktu"],"ok":[3],"vys":{"a":"Není správně. Produktová rizika ovlivňují testování na všech úrovních (rozsah, techniky, pokrytí, priority).","b":"Není správně. Projektová rizika se týkají managementu a řízení celého projektu (organizace, lidé, technika, dodavatelé).","c":"Není správně. Sylabus rozlišuje dva typy rizik s různým předmětem – projektová a produktová.","d":"Je správně. Projektová rizika ovlivňují harmonogram, rozpočet nebo rozsah projektu, produktová rizika souvisejí s kvalitativními charakteristikami produktu."},"obecne":"Sylabus 5.2.2: Projektová rizika se týkají managementu a řízení projektu a mohou mít dopad na harmonogram, rozpočet nebo rozsah. Produktová rizika souvisejí s kvalitativními charakteristikami produktu (např. chybějící funkcionalita, nedostatečná doba odezvy, bezpečnostní zranitelnosti).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.2.2","nazev":"Projektová a produktová rizika","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-dva-projektova-a-produktova-rizika"}},{"id":"TR-062","n":null,"lo":"FL-5.1.6","k":"K1","k3":true,"vyber":1,"q":"Co je hlavní myšlenkou modelu testovací pyramidy?","m":["Na nižších úrovních má být více malých, rychlých a izolovaných testů","Na všech úrovních testování má být přibližně stejný počet testů","Model platí pouze pro manuální testování, nikoli pro automatizaci","Model nahrazuje rozdělení testování do jednotlivých úrovní"],"ok":[0],"vys":{"a":"Je správně. Testy ve spodní vrstvě jsou malé, izolované a rychlé, takže jich je pro rozumné pokrytí potřeba velké množství.","b":"Není správně. Pyramida naopak ukazuje, že ve spodních vrstvách je testů mnohem více než v horních.","c":"Není správně. Testovací pyramida je pomůckou právě pro určení míry automatizace testů.","d":"Není správně. Vrstvy pyramidy úrovním testování odpovídají, úrovně testování nenahrazují."},"obecne":"Sylabus 5.1.6: Testovací pyramida ukazuje, že testy mohou mít různou granularitu. Čím vyšší vrstva, tím nižší granularita a izolace a delší doba provedení; ve spodní vrstvě je proto testů mnoho, komplexních E2E testů v horní vrstvě jen několik.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.6","nazev":"Testovací pyramida","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sest-testovaci-pyramida"}},{"id":"TR-063","n":null,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"Co představují testovací kvadranty?","m":["Čtyři úrovně testování od testování komponent po akceptační testování","Třídění testů podle zaměření (byznys/technologie) a účelu (podpora týmu/kritika produktu)","Model pro odhad pracnosti testování podle velikosti a složitosti produktu","Čtyři po sobě jdoucí fáze procesu testování od analýzy po dokončení"],"ok":[1],"vys":{"a":"Není správně. Kvadranty nejsou úrovně testování; dávají úrovně testování do souvislosti s typy testů.","b":"Je správně. Osa Y odlišuje testy zaměřené na byznys a na technologii, osa X testy podporující tým a testy kritizující produkt.","c":"Není správně. Pro odhad pracnosti slouží techniky odhadování (např. tříbodový odhad), ne testovací kvadranty.","d":"Není správně. Kvadranty nepopisují fáze procesu testování, ale seskupují typy a úrovně testů."},"obecne":"Sylabus 5.1.7: Testovací kvadranty dávají do souvislosti úrovně testování s typy testů, činnostmi, technikami a pracovními produkty v agilním vývoji. Kombinace os (byznys/technologie, podpora týmu/kritika produktu) určuje kvadranty Q1–Q4.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"TR-064","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"Jaký je rozdíl mezi monitoringem testování a řízením testování?","m":["Monitoring testování se provádí až na konci projektu","Řízení testování provádí pouze management mimo testovací tým","Monitoring sbírá informace o postupu, řízení podle nich přijímá opatření","Jde o synonyma, oba pojmy označují tutéž testovací činnost"],"ok":[2],"vys":{"a":"Není správně. Monitoring testování probíhá průběžně po celou dobu testování.","b":"Není správně. Řízení testování je součástí testovacích činností a může ho provádět i samotný tým.","c":"Je správně. Řízení testování využívá informace z monitoringu k nápravným opatřením, aby bylo dosaženo cílů testování.","d":"Není správně. Jde o dvě různé, navazující činnosti procesu testování."},"obecne":"Sylabus 1.4.1 a 5.3: Monitoring testování průběžně shromažďuje informace o testování a porovnává skutečný postup s plánem. Řízení testování tyto informace využívá k tomu, aby poskytlo pokyny a nezbytná nápravná opatření k dosažení cílů testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"TR-065","n":null,"lo":"FL-5.3.1","k":"K1","k3":true,"vyber":1,"q":"K čemu slouží metriky v testování?","m":["Jsou povinné pouze u projektů s vysokými požadavky na bezpečnost","Slouží výhradně k hodnocení výkonu jednotlivých testerů","Nahrazují reporty z testování, které pak není nutné vytvářet","Ukazují postup proti plánu, kvalitu testovaného objektu a efektivitu testování"],"ok":[3],"vys":{"a":"Není správně. Metriky se shromažďují v každém projektu jako podklad pro monitoring a řízení testování.","b":"Není správně. Metriky slouží k posouzení postupu, kvality a efektivity, ne k hodnocení jednotlivců.","c":"Není správně. Metriky jsou naopak typickou součástí reportů z testování.","d":"Je správně. Přesně tyto účely testovacích metrik uvádí sylabus."},"obecne":"Sylabus 5.3.1: Testovací metriky se shromažďují, aby ukazovaly postup proti plánovanému harmonogramu a rozpočtu, aktuální kvalitu testovaného objektu a efektivitu testovacích činností. Monitoring testování je shromažďuje pro podporu řízení a dokončení testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.3.1","nazev":"Metriky používané v testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-jedna-metriky-pouzivane-v-testovani"}},{"id":"TR-066","n":null,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"Co je hlavním účelem souhrnného reportu z testování?","m":["Shrnout dokončenou testovací činnost a vyhodnotit ji vůči plánu","Definovat techniky testování pro následující projekt","Sloužit pouze jako archivní záznam bez dalšího využití","Nahradit reporty o defektech nalezených během testování"],"ok":[0],"vys":{"a":"Je správně. Souhrnný report shrnuje testovací činnost (např. úroveň testování, iteraci) a vyhodnocuje testování a kvalitu produktu vůči plánu.","b":"Není správně. Techniky testování se stanovují v přístupu k testování v plánu testování.","c":"Není správně. Souhrnný report slouží zainteresovaným stranám a může poskytnout informace pro následné testování.","d":"Není správně. Reporty o defektech zůstávají samostatnými pracovními produkty; souhrnný report uvádí jen souhrnně nevyřešené defekty."},"obecne":"Sylabus 5.3.2: Souhrnný report z testování se připravuje při dokončení testování. Shrnuje testy, vyhodnocuje testování a kvalitu produktu vůči cílům a výstupním kritériím, uvádí odchylky od plánu, neošetřená rizika, nevyřešené defekty a ponaučení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"TR-067","n":null,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"Proč je konfigurační management důležitý pro testování?","m":["Umožňuje automaticky odvodit testovací případy z požadavků","Zajišťuje jednoznačnou identifikaci, verzování a sledování změn testwaru","Určuje pořadí provedení testů podle úrovně rizika","Zajišťuje, že každý nahlášený defekt bude opraven a konfirmován"],"ok":[1],"vys":{"a":"Není správně. Odvozování testovacích případů podporují nástroje pro návrh testů, ne konfigurační management.","b":"Je správně. Konfigurační management identifikuje, řídí a sleduje pracovní produkty včetně testwaru a zajišťuje trasovatelnost.","c":"Není správně. Pořadí provedení testů určuje prioritizace testovacích případů a harmonogram provedení testů.","d":"Není správně. Zpracování defektů od nahlášení po uzavření je úlohou managementu defektů."},"obecne":"Sylabus 5.4: Konfigurační management zajišťuje, že všechny konfigurační položky včetně položek testování jsou jednoznačně identifikovány, jejich verze jsou řízeny, změny evidovány a vztahy zaznamenány, takže je zajištěna trasovatelnost v průběhu celého procesu testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"TR-068","n":null,"lo":"FL-5.5.1","k":"K3","k3":false,"vyber":1,"q":"Co by měl obsahovat kvalitní report o defektu?","m":["Snímek obrazovky a krátký komentář k problému","Navrhovanou opravu kódu a odhad pracnosti opravy","Popis selhání s kroky k reprodukci, očekávaný a skutečný výsledek","Název defektu, datum nalezení a jméno testera, nic dalšího"],"ok":[2],"vys":{"a":"Není správně. Snímek obrazovky může být užitečnou přílohou, ale bez popisu kroků a výsledků nestačí.","b":"Není správně. Návrh opravy a odhad její pracnosti nejsou typickým obsahem reportu o defektu; oprava je úkolem vývojáře.","c":"Je správně. Popis umožňující reprodukci a porovnání očekávaného a skutečného výsledku jsou klíčovým obsahem reportu.","d":"Není správně. Tyto údaje nestačí k reprodukci a vyřešení problému."},"obecne":"Sylabus 5.5: Report o defektu obvykle obsahuje mimo jiné identifikátor, název, identifikaci testovaného objektu a prostředí, popis selhání umožňující reprodukci (včetně testovacích kroků), očekávané a skutečné výsledky, závažnost a prioritu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"TR-069","n":null,"lo":"FL-5.5.1","k":"K3","k3":false,"vyber":1,"q":"Jaký je rozdíl mezi závažností a prioritou defektu?","m":["Jsou to synonyma, obě vyjadřují důležitost defektu","Závažnost určuje vždy zákazník, prioritu vždy tester","Priorita se stanovuje pouze u kritických defektů","Závažnost vyjadřuje dopad defektu, priorita naléhavost opravy"],"ok":[3],"vys":{"a":"Není správně. Jde o dva různé údaje reportu o defektu.","b":"Není správně. Sylabus nestanovuje, že by tyto údaje určovala vždy konkrétní role.","c":"Není správně. Prioritu (naléhavost opravy) má každý reportovaný defekt.","d":"Je správně. Závažnost je míra dopadu na zájmy zainteresovaných stran nebo na požadavky, priorita je naléhavost opravy."},"obecne":"Sylabus 5.5: Report o defektu uvádí závažnost defektu (míru dopadu) na zájmy zainteresovaných stran nebo na požadavky a naléhavost / prioritu opravy. Defekt může mít vysokou závažnost, ale nízkou prioritu (např. ve zřídka používané funkci), a naopak.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"TR-070","n":null,"lo":"FL-5.1.4","k":"K3","k3":false,"vyber":1,"q":"Které techniky odhadování pracnosti testování popisuje sylabus?","m":["Techniky založené na metrikách a techniky založené na expertech","Pouze odhad podle počtu testerů v týmu","Pouze odhad podle počtu řádků zdrojového kódu","Žádné, pracnost testování se formálně neodhaduje"],"ok":[0],"vys":{"a":"Je správně. Odhad na základě poměrů a extrapolace jsou založené na metrikách, Wideband Delphi a tříbodový odhad na expertech.","b":"Není správně. Počet testerů je zdroj, nikoli technika odhadování pracnosti.","c":"Není správně. Odhad podle počtu řádků kódu sylabus mezi technikami odhadování neuvádí.","d":"Není správně. Sylabus popisuje čtyři techniky odhadování pracnosti testování."},"obecne":"Sylabus 5.1.4 popisuje čtyři techniky odhadování: odhad na základě poměrů a extrapolaci (techniky založené na metrikách) a Wideband Delphi a tříbodový odhad (techniky založené na expertech).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"TR-071","n":null,"lo":"FL-5.1.5","k":"K3","k3":false,"vyber":1,"q":"Tým má před vydáním omezený čas na regresní testování. Podle jakého principu by měl prioritizovat testovací případy, aby minimalizoval zbytkové riziko?","m":["Nejprve testovací případy s nejnižší úrovní rizika","Nejprve testovací případy pokrývající nejvyšší rizika","Podle pořadí, v jakém byly testovací případy napsány","Podle abecedního pořadí názvů testovacích případů"],"ok":[1],"vys":{"a":"Není správně. Nejnižší rizika by se při nedostatku času měla testovat naopak až nakonec.","b":"Je správně. Prioritizace na základě rizik provádí nejprve testy pokrývající nejdůležitější rizika.","c":"Není správně. Pořadí vzniku testů nijak nezohledňuje riziko.","d":"Není správně. Abecední pořadí nemá vztah k riziku ani k důležitosti testů."},"obecne":"Sylabus 5.1.5: Při prioritizaci na základě rizik vychází pořadí provádění testů z výsledků analýzy rizik a nejprve se provedou testovací případy pokrývající nejdůležitější rizika. V omezeném čase se tak zbytkové riziko sníží co nejvíce.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"TR-072","n":null,"lo":"FL-5.2.3","k":"K2","k3":true,"vyber":1,"q":"Analýza produktových rizik určila u platební funkce vysoké riziko (vysoký dopad i vysokou pravděpodobnost). Jak by se to mělo NEJPRAVDĚPODOBNĚJI projevit v testování?","m":["Testování platební funkce se odloží na konec, až bude systém stabilnější","Platební funkce se otestuje stejně důkladně jako ostatní, aby bylo pokrytí rovnoměrné","Platební funkce dostane vyšší prioritu a důkladnější testování","Platební funkce se otestuje jen průzkumným testováním bez dalších technik"],"ok":[2],"vys":{"a":"Není správně. Oblasti s vysokým rizikem se naopak testují dříve, aby se závažné problémy odhalily včas.","b":"Není správně. Testování založené na rizicích rozděluje úsilí podle úrovně rizika; rovnoměrné rozložení vysoké riziko nezohledňuje.","c":"Je správně. Výsledky analýzy rizik určují rozsah, pokrytí a priority testování; vysoké riziko vede k vyšší prioritě a důkladnějšímu testování.","d":"Není správně. Vysoké riziko vyžaduje důkladnější testování, typicky s formálními technikami a vyšším požadovaným pokrytím."},"obecne":"Sylabus 5.2.3: Výsledky analýzy produktových rizik se používají k určení rozsahu testování, technik, požadovaného pokrytí, odhadu pracnosti a priorit testování. Vysoká úroveň rizika vede k důkladnějšímu a dřívějšímu testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.2.3","nazev":"Analýza produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-tri-analyza-produktovych-rizik"}},{"id":"TR-073","n":null,"lo":"FL-5.1.3","k":"K2","k3":true,"vyber":1,"q":"Před koncem sprintu chybí testy pro 2 z 10 akceptačních kritérií, jejichž ověření vyžaduje definice hotového (DoD). Co by mělo NEJLÉPE následovat?","m":["O dokončení scénáře rozhodne tester podle vlastního odhadu kvality","Kritéria bez testů se z definice hotového pro tento scénář vypustí","Scénář se prohlásí za hotový a chybějící testy se doplní v dalším sprintu","Scénář není hotový, ledaže zainteresované strany přijmou riziko"],"ok":[3],"vys":{"a":"Není správně. O předčasném ukončení rozhodují zainteresované strany po přezkoumání rizik, ne tester sám.","b":"Není správně. Jednostranné oslabení DoD obchází výstupní kritéria; o přijetí rizika rozhodují zainteresované strany.","c":"Není správně. Bez splnění DoD není scénář hotový; odložení testů by musely vědomě schválit zainteresované strany jako přijaté riziko.","d":"Je správně. Dokud nejsou splněna výstupní kritéria (DoD), práce není hotová; výjimkou je vědomé přijetí rizika zainteresovanými stranami."},"obecne":"Sylabus 5.1.3: V agilním vývoji se výstupní kritéria často nazývají definice hotového (DoD). Činnost je dokončena po splnění výstupních kritérií; ukončit ji dříve lze, pokud zainteresované strany přezkoumají a přijmou související rizika.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"}},{"id":"TR-074","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"Manažer testování zjistí, že počet nově nalézaných defektů výrazně klesá, ačkoli plánovaný rozsah testování ještě nebyl dokončen. Které opatření řízení testování je NEJVHODNĚJŠÍ?","m":["Analyzovat příčinu a podle rizik upravit priority či přístup k testování","Snížit počet testerů, protože defektů je stále méně","Okamžitě ukončit testování, protože málo defektů znamená vysokou kvalitu","Trend ignorovat a pokračovat v testování beze změn"],"ok":[0],"vys":{"a":"Je správně. Řízení testování využívá informace z monitoringu k nápravným opatřením, např. přehodnocení priorit testů.","b":"Není správně. Snížení kapacity bez analýzy příčiny ohrozí dokončení plánovaného testování.","c":"Není správně. Málo nalezených defektů nemusí znamenat vysokou kvalitu (např. testy se opotřebovávají).","d":"Není správně. Řízení testování má na odchylky zjištěné monitoringem reagovat."},"obecne":"Sylabus 5.3: Řízení testování využívá informace z monitoringu k přijetí nápravných opatření, např. k přehodnocení priorit testů. Klesající počet nalezených defektů může mít různé příčiny, proto je nutné situaci analyzovat a nepředpokládat automaticky vysokou kvalitu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"TR-075","n":null,"lo":"FL-2.1.5","k":"K2","k3":true,"vyber":1,"q":"Retrospektiva odhalila, že nejasné požadavky opakovaně vedly k pozdnímu nalezení defektů. Které opatření NEJLÉPE podpoří přístup shift left v příštím sprintu?","m":["Zrušit revize požadavků, aby se ušetřil čas","Zapojit testery do revizí uživatelských scénářů před implementací","Posílit tým o další testery na konci sprintu","Přesunout většinu testování až po nasazení do produkce"],"ok":[1],"vys":{"a":"Není správně. Zrušení revizí by problém s nejasnými požadavky ještě zhoršilo.","b":"Je správně. Revize specifikace z pohledu testování je typickým příkladem přístupu shift left.","c":"Není správně. Více testerů na konci sprintu testování neposouvá dříve.","d":"Není správně. Jde o opak přístupu shift left."},"obecne":"Sylabus 2.1.5: Shift left znamená provádět testování v SDLC dříve. Příkladem je revize specifikace z pohledu testování, díky níž lze nejasnosti a defekty v požadavcích odhalit ještě před implementací.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"}},{"id":"TR-076","n":null,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"Testovací skript odkazoval na starou verzi testovacích dat, což způsobilo falešné selhání testu. Které opatření by tomu NEJLÉPE předešlo?","m":["Po každém selhání testu obnovit testovací data ze zálohy","Před každým během testů ručně zkontrolovat obsah testovacích dat","Verzovat testovací data spolu s odpovídající verzí testovaného objektu","Opakovat test automaticky, pokud první pokus selže"],"ok":[2],"vys":{"a":"Není správně. Obnovení ze zálohy nezaručí, že data odpovídají verzi testovaného objektu.","b":"Není správně. Ruční kontrola je pracná a náchylná k chybám a neřeší příčinu, kterou je chybějící řízení verzí.","c":"Je správně. Konfigurační management zajistí jednoznačnou identifikaci verzí a vztahů mezi testovacími daty a testovaným objektem.","d":"Není správně. Opakování testu se zastaralými daty povede ke stejnému falešnému selhání."},"obecne":"Sylabus 5.4: Konfigurační management zajišťuje, že všechny konfigurační položky (včetně testovacích dat a testovaného objektu) jsou jednoznačně identifikovány a verzovány, jejich vztahy zaznamenány a testware se na ně jednoznačně odkazuje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"TR-077","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"Do které kategorie testovacích nástrojů patří nástroj pro statickou analýzu kódu?","m":["Nástroje DevOps","Nástroje pro management testování","Nástroje pro nefunkcionální testování","Nástroje pro statické testování"],"ok":[3],"vys":{"a":"Není správně. Nástroje DevOps podporují pipeline, automatizované sestavování a CI/CD.","b":"Není správně. Nástroje pro management testování usnadňují správu požadavků, testů, defektů a konfigurací.","c":"Není správně. Nástroje pro nefunkcionální testování umožňují např. zátěžové testování, které nelze provést manuálně.","d":"Je správně. Nástroje pro statické testování podporují provádění revizí a statické analýzy."},"obecne":"Sylabus 6.1: nástroje pro statické testování podporují provádění revizí a statické analýzy. Nástroj pro statickou analýzu kódu proto patří do této kategorie.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"TR-078","n":null,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"Jak se nazývá položka testovacího prostředí, která při integračním testování nahrazuje volanou komponentu, jež ještě není k dispozici?","m":["Stub","Testovací listina","Testovací sada","Testovací procedura"],"ok":[0],"vys":{"a":"Je správně. Stub je položka testovacího prostředí, která simuluje chování chybějící volané komponenty.","b":"Není správně. Testovací listina je pracovní produkt návrhu testů pro průzkumné testování.","c":"Není správně. Testovací sada je skupina testovacích skriptů nebo procedur, ne náhrada komponenty.","d":"Není správně. Testovací procedura je posloupnost testovacích případů, ne náhrada komponenty."},"obecne":"Sylabus 1.4.3: mezi pracovní produkty implementace testování patří položky testovacího prostředí, např. stuby, ovladače (drivery), simulátory a virtualizace služeb. Stub nahrazuje volanou komponentu, která ještě není k dispozici.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"TR-081","n":null,"lo":"FL-2.2.1","k":"K2","k3":true,"vyber":1,"q":"Která úroveň testování je NEJVHODNĚJŠÍ pro odhalení defektu v logice uvnitř jedné funkce, která dosud nebyla integrována s ostatními komponentami?","m":["Akceptační testování","Testování komponent","Systémové integrační testování","Integrační testování komponent"],"ok":[1],"vys":{"a":"Není správně. Akceptační testování validuje splnění byznysových potřeb, ne logiku jednotlivé funkce.","b":"Je správně. Testování komponent se zaměřuje na izolované komponenty, a je proto nejvhodnější pro defekty v logice kódu.","c":"Není správně. Systémové integrační testování se zaměřuje na rozhraní mezi systémy a externími službami.","d":"Není správně. Integrační testování komponent se zaměřuje na rozhraní a interakce mezi komponentami; funkce ještě integrována není."},"obecne":"Sylabus 2.2.1: testování komponent se zaměřuje na testování izolovaných komponent. Defekty v logice uvnitř jedné komponenty se proto typicky odhalují právě v této úrovni, ještě před integrací s dalšími komponentami.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"}},{"id":"TR-082","n":null,"lo":"FL-2.2.3","k":"K2","k3":true,"vyber":1,"q":"Po opravě defektu, kvůli kterému selhal testovací případ TC1, provede tester druhý testovací cyklus: znovu spustí TC1 a navíc TC5, který v prvním cyklu prošel a s opravou přímo nesouvisí. Jak se nazývá opětovné spuštění TC5?","m":["Konfirmační test","Test komponenty","Regresní test","Akceptační test"],"ok":[2],"vys":{"a":"Není správně. Konfirmačním testem je opětovné spuštění TC1, který ověřuje samotnou opravu.","b":"Není správně. Test komponenty označuje úroveň testování, ne účel opakovaného spuštění testu.","c":"Je správně. TC5 dříve prošel a ověřuje, zda oprava nezpůsobila nežádoucí dopad jinde – jde o regresní test.","d":"Není správně. Akceptační test je zařazen podle úrovně testování, ne podle důvodu opakovaného spuštění."},"obecne":"Sylabus 2.2.3: konfirmační testování ověřuje, že byl původní defekt opraven (zde opětovné spuštění TC1). Regresní testování ověřuje, zda změna nezpůsobila nežádoucí dopady v jiných částech (zde opětovné spuštění TC5, který dříve prošel).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"}},{"id":"TR-083","n":null,"lo":"FL-4.2.3","k":"K3","k3":false,"vyber":1,"q":"V rozhodovací tabulce platí byznys pravidlo: je-li podmínka „Nový klient“ = T, nemůže být zároveň podmínka „Má věrnostní kartu“ = T, protože nový klient kartu ještě nemá. Jak se taková kombinace podmínek v tabulce správně označí?","m":["Symbolem „–“, protože hodnota podmínky je pro výsledek irelevantní","Jako pravidlo s nejvyšší prioritou, protože odhaluje rozpor v požadavcích","Jako běžné pravidlo, které je nutné otestovat stejně jako ostatní pravidla","Jako neproveditelná kombinace („N/A“), která není položkou pokrytí"],"ok":[3],"vys":{"a":"Není správně. „–“ znamená, že na hodnotě podmínky nezáleží; zde jde o kombinaci, která vůbec nemůže nastat.","b":"Není správně. Neproveditelná kombinace se netestuje, natož s nejvyšší prioritou.","c":"Není správně. Kombinace, která nemůže nastat, nelze otestovat; nepočítá se mezi proveditelné sloupce.","d":"Je správně. Neproveditelná podmínka se označuje „N/A“ a položkami pokrytí jsou jen sloupce s proveditelnou kombinací podmínek."},"obecne":"Sylabus 4.2.3: Symbol „N/A“ znamená, že podmínka je pro dané pravidlo neproveditelná. Položkami pokrytí jsou jen sloupce s proveditelnou kombinací podmínek a sloupce s neproveditelnou kombinací lze z tabulky odstranit.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"TR-084","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"Pole přijímá celá čísla v platném rozsahu 1–20. Sada testů obsahuje hodnoty 1 a 20, ale ne hodnoty 0 a 21. Jakého pokrytí dvouhodnotové analýzy hraničních hodnot sada dosahuje?","m":["25 %","50 %","75 %","100 %"],"ok":[1],"vys":{"a":"Není správně. Pokryté jsou 2 ze 4 položek pokrytí, ne 1.","b":"Je správně. Položkami pokrytí jsou 0, 1, 20 a 21; testy pokrývají 2 z nich (1 a 20), tedy 50 %.","c":"Není správně. Pokryté jsou 2 ze 4 položek pokrytí, ne 3.","d":"Není správně. Chybí hraniční hodnoty 0 a 21 neplatných tříd."},"obecne":"Sylabus 4.2.2: Pokrytí dvouhodnotové BVA je poměr pokrytých hraničních hodnot k počtu všech identifikovaných hraničních hodnot. Třídy jsou ≤ 0, 1–20 a ≥ 21, hraniční hodnoty 0, 1, 20, 21; pokryté jsou 2 ze 4 = 50 %.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"TR-085","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"Stavový diagram obsahuje 4 platné přechody, které lze všechny projít v jedné souvislé posloupnosti od počátečního do koncového stavu. Kolik testovacích případů je MINIMÁLNĚ potřeba k dosažení 100% pokrytí platných přechodů?","m":["1","2","3","4"],"ok":[0],"vys":{"a":"Je správně. Jeden testovací případ může pokrýt více přechodů; zde projde všechny čtyři najednou.","b":"Není správně. Druhý test by nepokryl žádný nový přechod.","c":"Není správně. Všechny přechody pokryje již jediná posloupnost.","d":"Není správně. Samostatný test pro každý přechod není nutný."},"obecne":"Sylabus 4.2.4: Testovací případ je obvykle série událostí vedoucí k posloupnosti změn stavů a jeden test může (a obvykle bude) pokrývat několik přechodů. Pokud lze všechny platné přechody projít jednou posloupností, stačí jeden test.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"TR-086","n":null,"lo":"FL-5.2.4","k":"K2","k3":true,"vyber":1,"q":"Tým se u vysoce rizikové funkce rozhodl provést důkladnější testování a revizi kódu, aby snížil pravděpodobnost výskytu defektu. O jaký typ reakce na riziko se jedná?","m":["Přijetí rizika","Záložní plán","Zmírnění rizika","Přenos rizika"],"ok":[2],"vys":{"a":"Není správně. Přijetí rizika znamená, že se proti riziku žádná opatření nepřijímají.","b":"Není správně. Záložní plán určuje, co dělat, pokud riziko nastane; nesnižuje jeho pravděpodobnost.","c":"Je správně. Důkladnější testování a revize jsou opatření ke snížení úrovně rizika, tedy zmírnění rizika.","d":"Není správně. Přenos rizika přesouvá riziko na jinou stranu (např. pojištěním nebo smluvně), nesnižuje ho testováním."},"obecne":"Sylabus 5.2.4: Na analyzované riziko lze reagovat zmírněním pomocí testování, přijetím, přenosem nebo záložním plánem. Opatření zmírnění rizik prostřednictvím testování zahrnují mj. provedení revizí a statické analýzy a použití vhodných technik testování a úrovní pokrytí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.2.4","nazev":"Řízení produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-ctyri-rizeni-produktovych-rizik"}},{"id":"TR-087","n":null,"lo":"FL-5.1.1","k":"K2","k3":true,"vyber":1,"q":"Část plánu testování popisuje, které úrovně testování a typy testů budou použity a jaké techniky testování se uplatní. Do které části plánu testování tento popis patří?","m":["Konfigurační management","Plán komunikace","Registr rizik","Přístup k testování"],"ok":[3],"vys":{"a":"Není správně. Konfigurační management není samostatnou částí obsahu plánu testování podle sylabu.","b":"Není správně. Plán komunikace popisuje způsoby a četnost komunikace a šablony dokumentace.","c":"Není správně. Registr rizik obsahuje produktová a projektová rizika.","d":"Je správně. Přístup k testování zahrnuje úrovně testování, typy testů, techniky, výstupy, kritéria, nezávislost, metriky aj."},"obecne":"Sylabus 5.1.1: Přístup k testování v plánu testování popisuje např. úrovně testování, typy testů, techniky testování, výstupy z testování, vstupní a výstupní kritéria, nezávislost testování, požadované metriky a požadavky na testovací data a prostředí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.1.1","nazev":"Účel a obsah plánu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-jedna-ucel-a-obsah-planu-testovani"}},{"id":"TR-089","n":null,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"Tým používá tříbodový odhad: nejoptimističtější odhad je 4 člověkohodiny, nejpravděpodobnější odhad 10 člověkohodin a nejpesimističtější odhad 22 člověkohodin. Jaký je výsledný odhad podle vzorce E = (a + 4 × m + b) / 6?","m":["10 člověkohodin","11 člověkohodin","12 člověkohodin","22 člověkohodin"],"ok":[1],"vys":{"a":"Není správně. 10 je pouze nejpravděpodobnější odhad m, nikoli vážený průměr.","b":"Je správně. E = (4 + 4 × 10 + 22) / 6 = 66 / 6 = 11 člověkohodin.","c":"Není správně. 12 je prostý aritmetický průměr (4 + 10 + 22) / 3, nikoli vážený průměr tříbodového odhadu.","d":"Není správně. 22 je nejpesimističtější odhad b."},"obecne":"Sylabus 5.1.4: Výsledný odhad tříbodového odhadu je vážený aritmetický průměr E = (a + 4 × m + b) / 6. Zde (4 + 40 + 22) / 6 = 11 člověkohodin.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"TR-091","n":null,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"Do kterého testovacího kvadrantu se typicky zařazuje testování použitelnosti?","m":["Q1 – zaměřený na technologii a podporu týmu","Q2 – zaměřený na byznys a podporu týmu","Q3 – zaměřený na byznys a kritiku produktu","Q4 – zaměřený na technologii a kritiku produktu"],"ok":[2],"vys":{"a":"Není správně. Q1 obsahuje testy komponent a integrační testy komponent.","b":"Není správně. Q2 obsahuje funkcionální testy, příklady, testy uživatelských scénářů, UX prototypy, testování API a simulace.","c":"Je správně. Q3 obsahuje průzkumné testování, testování použitelnosti a uživatelské akceptační testování.","d":"Není správně. Q4 obsahuje smoke testy a nefunkcionální testy, výslovně kromě testů použitelnosti."},"obecne":"Sylabus 5.1.7: Kvadrant Q3 (zaměřený na byznys a kritiku produktu) obsahuje průzkumné testování, testování použitelnosti a uživatelské akceptační testování. Tyto testy jsou uživatelsky orientované a často manuální.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"TR-093","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"Testovací případy TC1–TC4 pokrývají požadavky takto: TC1 pokrývá 4 požadavky; TC2 pokrývá 2 požadavky, které oba pokrývá i TC1; TC3 pokrývá 2 požadavky, které TC1 nepokrývá; TC4 pokrývá 1 požadavek, který nepokrývá žádný z ostatních testovacích případů. Testovací případy řadíte podle prioritizace dodatečného pokrytí. Který testovací případ by měl být proveden jako DRUHÝ?","m":["TC2","TC1","TC3","TC4"],"ok":[2],"vys":{"a":"Není správně. TC2 nepřidává žádné nové pokrytí, protože jeho požadavky už pokrývá TC1; provede se jako poslední.","b":"Není správně. TC1 má nejvyšší pokrytí (4 požadavky), proto se provede jako první.","c":"Je správně. Po TC1 přidává TC3 nejvíce dosud nepokrytých požadavků (2).","d":"Není správně. TC4 přidává jen 1 nový požadavek, tedy méně než TC3."},"obecne":"Sylabus 5.1.5: Při prioritizaci dodatečného pokrytí se nejprve provede testovací případ s nejvyšším pokrytím (TC1 – 4 požadavky) a každý další je ten, který přidá nejvíce dodatečného pokrytí: TC3 (+2), TC4 (+1), TC2 (+0). Pořadí je TC1, TC3, TC4, TC2.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"TR-096","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"Která z uvedených kategorií nástrojů NEJPŘÍMĚJI podporuje samotné provádění testů?","m":["Nástroje pro management testování","Nástroje pro návrh a implementaci testů","Nástroje pro spolupráci","Nástroje DevOps"],"ok":[3],"vys":{"a":"Není správně. Nástroje pro management testování usnadňují správu požadavků, testů, defektů a konfigurací.","b":"Není správně. Tyto nástroje usnadňují vytváření testovacích případů, dat a procedur, nikoli jejich provádění.","c":"Není správně. Nástroje pro spolupráci usnadňují komunikaci.","d":"Je správně. Nástroje DevOps podporují pipeline, automatizované sestavování a CI/CD, v jejichž rámci se testy automaticky spouštějí."},"obecne":"Sylabus 6.1: nástroje DevOps podporují pipeline, sledování pracovních toků, automatizované sestavování a CI/CD, kde se automatizované testy spouštějí při každé změně. Ostatní uvedené kategorie se zaměřují na jiné činnosti.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"TR-098","n":null,"lo":"FL-4.3.3","k":"K2","k3":true,"vyber":1,"q":"Ve kterém z následujících případů pomůže testování bílé skříňky odhalit defekt, který by testování černé skříňky typicky NEODHALILO?","m":["Kód obsahuje navíc funkcionalitu, kterou specifikace vůbec nepožaduje.","Uživatelské rozhraní neodpovídá schválenému grafickému návrhu obrazovek.","Systém nesplňuje dohodnutou maximální dobu odezvy při běžné zátěži.","Systém vůbec neimplementuje jeden z požadavků uvedených ve specifikaci."],"ok":[0],"vys":{"a":"Je správně. Testování bílé skříňky zohledňuje celou implementaci, a tak narazí i na kód, který ve specifikaci není a který by testy odvozené ze specifikace neprověřily.","b":"Není správně. Soulad s grafickým návrhem ověří testování černé skříňky podle návrhu.","c":"Není správně. Dobu odezvy ověřuje testování výkonnosti podle specifikovaných požadavků (černá skříňka).","d":"Není správně. Opomenutý požadavek v kódu není, takže ho testování bílé skříňky neodhalí; to je jeho slabina."},"obecne":"Sylabus 4.3.3: Silnou stránkou technik bílé skříňky je, že zohledňují samotnou implementaci softwaru, což usnadňuje detekci defektů i tehdy, když je specifikace vágní, zastaralá nebo neúplná. Slabinou je, že nemusí odhalit opomenutí implementace požadavků.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"}},{"id":"TR-099","n":null,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"Z historických projektů organizace vyplývá, že pracnost testování činí v průměru 12 % pracnosti vývoje. Pracnost vývoje nového projektu se odhaduje na 500 člověkodnů. Jaký je odhad pracnosti testování při použití odhadu na základě poměrů?","m":["50 člověkodnů","60 člověkodnů","120 člověkodnů","500 člověkodnů"],"ok":[1],"vys":{"a":"Není správně. 50 člověkodnů odpovídá poměru 10 %, nikoli 12 %.","b":"Je správně. 500 × 0,12 = 60 člověkodnů.","c":"Není správně. 120 člověkodnů odpovídá poměru 24 %, nikoli 12 %.","d":"Není správně. 500 člověkodnů je pracnost vývoje, nikoli testování."},"obecne":"Sylabus 5.1.4: Odhad na základě poměrů je technika založená na metrikách – z historických dat organizace se odvodí poměr pracnosti testování k pracnosti vývoje a použije se na nový projekt: 500 × 0,12 = 60 člověkodnů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"TR-100","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"Rozhodovací tabulka s 5 proveditelnými pravidly (R1–R5) popisuje výši slevy. Tester připravil 3 testovací případy, které pokrývají pravidla R1, R3 a R3 (R3 tedy dvakrát). Jakého pokrytí rozhodovací tabulky tyto testy dosahují?","m":["40 %","60 %","75 %","100 %"],"ok":[0],"vys":{"a":"Je správně. Pokrytá jsou 2 různá pravidla (R1 a R3) z 5, tedy 2/5 = 40 %.","b":"Není správně. 3/5 by platilo, kdyby každý test pokryl jiné pravidlo; R3 se však započítá jen jednou.","c":"Není správně. Pokrytí se počítá z počtu pravidel tabulky (5), ne z jiného základu.","d":"Není správně. Pravidla R2, R4 a R5 nejsou pokryta."},"obecne":"Sylabus 4.2.3: Pokrytí rozhodovací tabulky je poměr počtu pokrytých sloupců (pravidel) k celkovému počtu proveditelných sloupců. Opakované pokrytí stejného pravidla pokrytí nezvyšuje: 2/5 = 40 %.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"TR-101","n":null,"lo":"FL-4.3.1","k":"K2","k3":true,"vyber":1,"q":"Na stejném kódu byly spuštěny dva testy. Test T1 dosáhl 30% pokrytí příkazů a test T2 45% pokrytí příkazů. Které z následujících tvrzení je NUTNĚ pravdivé?","m":["Sada testů T1 a T2 dosahuje pokrytí příkazů přesně 75 %.","Existuje alespoň jeden příkaz, který provedl test T1 i test T2.","Alespoň 25 % příkazů v testovaném kódu je nespustitelných.","Sada testů T1 a T2 dosahuje pokrytí příkazů nejvýše 75 %."],"ok":[3],"vys":{"a":"Není správně. Přesně 75 % by platilo jen tehdy, kdyby se pokryté příkazy vůbec nepřekrývaly; to nevíme.","b":"Není správně. Protože 30 % + 45 % < 100 %, mohou být množiny pokrytých příkazů zcela disjunktní.","c":"Není správně. Pokrytí příkazů se počítá jen ze spustitelných příkazů; o nespustitelných nic neříká.","d":"Je správně. I kdyby se příkazy pokryté T1 a T2 vůbec nepřekrývaly, dosáhnou společně nejvýše 30 + 45 = 75 %."},"obecne":"Sylabus 4.3.1: Pokrytí příkazů je poměr provedených spustitelných příkazů k jejich celkovému počtu. Společné pokrytí dvou testů leží mezi větší z hodnot (45 %) a jejich součtem (75 %); bez dalších informací nelze určit přesnou hodnotu ani existenci společného příkazu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"}},{"id":"TR-104","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"Tester má čtyři testovací případy s prioritou (1 = nejvyšší) a logickými závislostmi: TC1 (priorita 3, bez závislosti), TC2 (priorita 1, závisí na TC1), TC3 (priorita 2, bez závislosti), TC4 (priorita 4, závisí na TC2). Který testovací případ by měl být proveden jako TŘETÍ?","m":["TC3","TC1","TC2","TC4"],"ok":[0],"vys":{"a":"Je správně. Pořadí je TC1, TC2, TC3, TC4; po TC2 má nejvyšší prioritu TC3.","b":"Není správně. TC1 se provede jako první, protože na něm závisí TC2 s nejvyšší prioritou.","c":"Není správně. TC2 má nejvyšší prioritu, a proto se provede hned po TC1, na kterém závisí – tedy jako druhý.","d":"Není správně. TC4 má nejnižší prioritu a provede se jako poslední."},"obecne":"Sylabus 5.1.5: Pokud testovací případ s vyšší prioritou závisí na testovacím případu s nižší prioritou, musí být nejdříve proveden testovací případ s nižší prioritou. TC2 (priorita 1) vyžaduje TC1, pořadí je tedy TC1, TC2, poté TC3 (priorita 2) a nakonec TC4. Třetí je TC3.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"TR-105","n":null,"lo":"FL-5.3.1","k":"K1","k3":true,"vyber":1,"q":"Která z uvedených metrik je metrikou KVALITY PRODUKTU, a nikoli metrikou postupu testování?","m":["Počet testovacích případů navržených za den","Dostupnost systému v procentech provozní doby","Celková pracnost testování v hodinách","Počet provedených testovacích procedur"],"ok":[1],"vys":{"a":"Není správně. Jde o metriku postupu testování (postup implementace testovacích případů).","b":"Je správně. Dostupnost uvádí sylabus jako příklad metriky týkající se kvality produktu.","c":"Není správně. Jde o metriku postupu projektu (pracnost testování).","d":"Není správně. Jde o metriku postupu testování."},"obecne":"Sylabus 5.3.1 uvádí mezi metrikami týkajícími se kvality produktu např. dostupnost, dobu odezvy a střední dobu mezi poruchami. Procento zjištěných defektů (DDP) patří mezi metriky nad defekty, nikoli mezi metriky kvality produktu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.3.1","nazev":"Metriky používané v testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-jedna-metriky-pouzivane-v-testovani"}},{"id":"TR-106","n":null,"lo":"FL-5.2.1","k":"K1","k3":true,"vyber":1,"q":"Dopad rizika je odhadnut na 4 000 Kč a pravděpodobnost rizika na 25 %. Jaká je úroveň rizika, počítá-li se kvantitativně jako součin pravděpodobnosti a dopadu?","m":["500 Kč","1 000 Kč","4 000 Kč","16 000 Kč"],"ok":[1],"vys":{"a":"Není správně. 500 Kč by odpovídalo pravděpodobnosti 12,5 %.","b":"Je správně. 0,25 × 4 000 Kč = 1 000 Kč.","c":"Není správně. 4 000 Kč je samotný dopad rizika bez zohlednění pravděpodobnosti.","d":"Není správně. 16 000 Kč vznikne chybným dělením dopadu pravděpodobností (4 000 / 0,25)."},"obecne":"Sylabus 5.2.1 a 5.2.3: Riziko charakterizují pravděpodobnost a dopad. Při kvantitativním přístupu se úroveň rizika vypočítá jako násobek pravděpodobnosti rizika a dopadu rizika: 0,25 × 4 000 Kč = 1 000 Kč.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.2.1","nazev":"Definice rizika a jeho atributy","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-jedna-definice-rizika-a-jeho-atributy"}},{"id":"TR-108","n":null,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"Protokol testů ukazuje, že testovací případy TC3, TC4 a TC5 řadicí funkce selhaly, a to vždy u vstupů obsahujících záporná čísla. Tester se domnívá, že příčinou je nesprávné zpracování znaménka minus, hypotézu však zatím neověřil. Jak by měl tuto skutečnost NEJLÉPE popsat v reportu o defektu?","m":["Uvést jako příčinu chybné zpracování znaménka minus, protože je nejpravděpodobnější","Vstupy použité v testech neuvádět, aby report zůstal stručný a přehledný","Napsat jednu větu a odkázat vývojáře, ať si protokol testů projdou sami","Popsat pozorované selhání s konkrétními vstupy a výstupy, bez neověřené příčiny"],"ok":[3],"vys":{"a":"Není správně. Neověřená hypotéza uvedená jako fakt může vývojáře nasměrovat špatným směrem.","b":"Není správně. Konkrétní vstupy jsou pro reprodukci selhání klíčové.","c":"Není správně. Report má sám poskytovat dostatek informací k reprodukci a vyřešení problému.","d":"Je správně. Report má popsat pozorované selhání tak, aby ho šlo reprodukovat, včetně vstupů a skutečných výsledků."},"obecne":"Sylabus 5.5: Report o defektu má poskytnout dostatek informací k vyřešení problému – popis selhání umožňující reprodukci, testovací kroky, relevantní protokoly testů a očekávané a skutečné výsledky. Neověřená domněnka o příčině do popisu selhání nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"TR-110","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"Do které kategorie NEJLÉPE patří nástroj, který primárně usnadňuje komunikaci a sdílení informací mezi členy týmu (např. chat, sdílené nástěnky)?","m":["Nástroje pro spolupráci","Nástroje pro statické testování","Nástroje DevOps","Nástroje podporující škálovatelnost a standardizaci nasazení"],"ok":[0],"vys":{"a":"Je správně. Nástroje pro spolupráci usnadňují komunikaci.","b":"Není správně. Nástroje pro statické testování podporují revize a statickou analýzu.","c":"Není správně. Nástroje DevOps podporují pipeline, automatizované sestavování a CI/CD.","d":"Není správně. Tyto nástroje (např. virtuální počítače, kontejnery) slouží k nasazení prostředí."},"obecne":"Sylabus 6.1: nástroje pro spolupráci usnadňují komunikaci. Chat nebo sdílené nástěnky do této kategorie patří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UC-1-01","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Proč je důležité při testování zohledňovat princip Testy se opotřebovávají?","m":["<p>Dynamické testy se opotřebovávají rychleji než statické testy.<\/p>","<p>Spouštění stále stejných testů dokola snižuje šanci na nalezení nových defektů.<\/p>","<p>Testy by neměly být závislé na kontextu.<\/p>","<p>Opakované spouštění stejných testů zvyšuje pravděpodobnost nalezení defektů.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Princip nerozlišuje mezi dynamickými a statickými testy.","b":"Je správně. Pokud se stejné testy opakují stále dokola, stávají se méně účinnými a nové defekty neodhalují.","c":"Není správně. Testování závislé na kontextu být má; s principem Testy se opotřebovávají to nesouvisí.","d":"Není správně. Opakované spouštění stejných testů pravděpodobnost nalezení nových defektů naopak snižuje."},"obecne":"Sylabus 1.3, princip 5: Pokud se stejné testy opakují neustále dokola, stávají se stále méně účinnými a nedochází k odhalování nových defektů. Je proto nutné měnit stávající testy a testovací data, případně vytvořit testy nové; výjimkou je např. automatizované regresní testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UC-1-03","n":null,"lo":"FL-1.4.4","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností NENÍ přínosem dobré trasovatelnosti?","m":["Usnadňuje určení dopadu změn.","Pomáhá ověřit, že všechny požadavky jsou pokryty testy.","Zaručuje, že testovací případy neobsahují žádné defekty.","Usnadňuje komunikaci výsledků testování se zainteresovanými stranami."],"ok":[2],"vys":{"a":"Není správně. Určení dopadu změn je jedním z přínosů trasovatelnosti.","b":"Není správně. Trasovatelnost mezi testovacími případy a požadavky pomáhá ověřit pokrytí požadavků.","c":"Je správně. Trasovatelnost propojuje položky testovací báze s testwarem, ale nijak nezaručuje bezchybnost testovacích případů.","d":"Není správně. Trasovatelnost zlepšuje srozumitelnost reportů a komunikaci se zainteresovanými stranami."},"obecne":"Sylabus 1.4.4: Dobrá trasovatelnost umožňuje vyhodnocovat pokrytí, určit dopad změn, usnadňuje audit a zlepšuje srozumitelnost reportů a komunikaci se zainteresovanými stranami. O kvalitě samotných testovacích případů nic nezaručuje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.4","nazev":"Trasovatelnost mezi testovací bází a pracovními produkty z testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-ctyri-trasovatelnost-mezi-testovaci-bazi-a-pracovnimi-produkty-z-testovani"}},{"id":"UC-1-04","n":null,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Přiřaďte následující testovací činnosti k pracovním produktům, které jsou jejich výstupem.<\/p><p>1. Plánování testování<br>2. Návrh testů<br>3. Implementace testování<br>4. Dokončení testování<\/p><p>A. Harmonogram provedení testů<br>B. Změnové požadavky (např. jako položky produktového backlogu)<br>C. Harmonogram testování<br>D. Testovací listiny<\/p>","m":["1A, 2C, 3D, 4B","1B, 2A, 3C, 4D","1C, 2D, 3A, 4B","1D, 2C, 3A, 4B"],"ok":[2],"vys":{"a":"Není správně. Harmonogram provedení testů vzniká při implementaci testování, testovací listiny při návrhu testů.","b":"Není správně. Změnové požadavky vznikají při dokončení testování, harmonogram testování při plánování.","c":"Je správně. Plánování = harmonogram testování (C), návrh testů = testovací listiny (D), implementace = harmonogram provedení testů (A), dokončení = změnové požadavky (B).","d":"Není správně. Testovací listiny nejsou výstupem plánování a harmonogram testování není výstupem návrhu testů."},"obecne":"Sylabus 1.4.3: Harmonogram testování je výstupem plánování testování, testovací listiny návrhu testů, harmonogram provedení testů implementace testování a změnové požadavky (např. položky produktového backlogu) dokončení testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"UC-1-05","n":null,"lo":"FL-1.5.1","k":"K2","k3":true,"vyber":1,"q":"Která z následujících dovedností NENÍ v sylabu uvedena mezi obecnými dovednostmi, které jsou pro testery obzvláště důležité?","m":["Řízení vlastního času","Důkladnost a komunikační dovednosti","Znalost domény","Technické znalosti"],"ok":[0],"vys":{"a":"Je správně. Řízení času je obecně užitečné, ale sylabus je mezi dovednostmi testera neuvádí.","b":"Není správně. Důkladnost a komunikační dovednosti sylabus výslovně uvádí.","c":"Není správně. Znalost domény pomáhá porozumět koncovým uživatelům a komunikovat s nimi.","d":"Není správně. Technické znalosti zvyšují efektivitu testování, např. použitím vhodných nástrojů."},"obecne":"Sylabus 1.5.1 uvádí jako obecné dovednosti testera znalost testování, důkladnost a pečlivost, komunikační dovednosti a týmovou spolupráci, analytické a kritické myšlení a kreativitu, technické znalosti a znalost domény. Řízení času mezi nimi není.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.1","nazev":"Obecné dovednosti potřebné pro testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-jedna-obecne-dovednosti-potrebne-pro-testovani"}},{"id":"UC-1-06","n":null,"lo":"FL-1.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností <strong>NENÍ<\/strong> kontextovým faktorem, který může ovlivnit způsob provádění testování?<\/p>","m":["Dostupnost a použitelnost nástrojů","Počet defektů v předchozích projektech","Obor podnikání a jeho právní předpisy","Dostupnost a dovednosti členů týmu"],"ok":[1],"vys":{"a":"Není správně. Nástroje (dostupnost, použitelnost, shoda s předpisy) jsou faktorem kontextu.","b":"Je správně. Počet defektů v dřívějších projektech sylabus mezi faktory kontextu neuvádí.","c":"Není správně. Obor podnikání (kritičnost, rizika, právní předpisy) je faktorem kontextu.","d":"Není správně. Členové týmu (dovednosti, zkušenosti, dostupnost) jsou faktorem kontextu."},"obecne":"Sylabus 1.4.2: Způsob provádění testování závisí např. na zainteresovaných stranách, členech týmu, oboru podnikání, technických faktorech, omezeních projektu, organizačních faktorech, SDLC a nástrojích. Počet defektů v předchozích projektech mezi nimi není.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.4.2","nazev":"Proces testování v souvislostech","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-dva-proces-testovani-v-souvislostech"}},{"id":"UC-1-07","n":null,"lo":"FL-1.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Vývojář pracuje na nové funkci webové aplikace, která uživatelům umožňuje nahrávat do aplikace obrázky. Vývojář napíše kód pro nahrávání obrázků, ale zapomene doplnit kód, který kontroluje velikost obrázků. V důsledku toho mohou uživatelé nahrát příliš velké obrázky, což způsobí pád aplikace. Co z následujícího je chyba?<\/p>","m":["<p>Vývojář zapomněl doplnit kód pro kontrolu velikosti obrázku.<\/p>","<p>Pád aplikace.<\/p>","<p>Uživatelé nahrávají obrázky ve velikosti, kterou web nepodporuje.<\/p>","<p>Žádná z uvedených možností.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Chyba (omyl) je lidské jednání – vývojář zapomněl doplnit kontrolu velikosti obrázku, čímž vznikl defekt v kódu.","b":"Není správně. Pád aplikace je selhání, tedy projev defektu při spuštění.","c":"Není správně. Nahrávání velkých obrázků je podmínka, za které se defekt projeví, nikoli chyba.","d":"Není správně. Chybou je opomenutí vývojáře v možnosti a."},"obecne":"Sylabus 1.2.3: Lidé dělají chyby (omyly), v jejichž důsledku vznikají defekty, které mohou při spuštění vést k selhání. Zde je chybou opomenutí vývojáře, defektem chybějící kontrola velikosti v kódu a selháním pád aplikace.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"}},{"id":"UC-1-08","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jako tester testujete novou mobilní hru. Posledních několik týdnů pečlivě spouštíte sadu automatizovaných testů, které pokrývají základní herní mechaniky. Tyto testy odhalily několik defektů týkajících se pohybu postavy, interakce s předměty a postupu mezi úrovněmi. V poslední době však testy i přes opakované spouštění žádné nové defekty neodhalily. Máte podezření, že ve hře mohou být další skryté defekty, ale vývojový tým je na základě úspěšně procházejících testů přesvědčen, že je hra stabilní.<\/p><p>Který z následujících principů testování NEJLÉPE vysvětluje vaše obavy?<\/p>","m":["<p>Shlukování defektů.<\/p>","<p>Testování prokazuje přítomnost defektů, nikoli jejich nepřítomnost.<\/p>","<p>Kompletní testování není možné.<\/p>","<p>Testy se opotřebovávají.<\/p>"],"ok":[3],"vys":{"a":"<p>Ve scénáři jste již odhalili defekty v základních herních mechanikách, což může naznačovat shlukování defektů v této oblasti. Vaše obava se ale netýká určení místa výskytu defektů (to se možná již děje). Máte podezření, že stávající testy navržené pro tyto základní mechaniky přestávají být účinné při hledání nových problémů ve stejné oblasti.<\/p>","b":"<p>Tento princip sice obecně platí, ale vaše konkrétní obavy přímo nevysvětluje. Defekty jste již nalezli, ale obáváte se, že současné testy některé další přehlížejí.<\/p>","c":"<p>Tento princip zdůrazňuje, že testovat všechno není reálné. Je sice důležitý pro návrh testů, ale nevysvětluje, proč by stávající testy měly být postupem času méně účinné.<\/p>","d":"<p>Tento princip vaše obavy vysvětluje přesně. Opakované spouštění stejných testů může vést k tomu, že jsou při hledání nových defektů méně účinné. Vaše podezření, že i přes úspěšně procházející testy existují další defekty, s tímto principem odpovídá.<\/p>"},"obecne":"Sylabus 1.3, princip 5 (Testy se opotřebovávají): Pokud se stejné testy opakují neustále dokola, stávají se stále méně účinnými a nedochází k odhalování nových defektů. Je nutné měnit stávající testy a testovací data nebo vytvořit testy nové.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UC-1-12","n":null,"lo":"FL-1.4.5","k":"K2","k3":true,"vyber":1,"q":"<p>Které DVA z následujících úkolů patří hlavně k roli testera?<\/p><p>i. Konfigurace testovacích prostředí<br>ii. Správa produktového backlogu<br>iii. Návrh řešení pro nové požadavky<br>iv. Vytvoření plánu testování<br>v. Reportování nalezených defektů<\/p>","m":["i a v","i a ii","ii a v","iii a iv"],"ok":[0],"vys":{"a":"Je správně. Příprava testovacího prostředí (implementace testování) i reportování defektů (provedení testů) patří k roli testera.","b":"Není správně. Správa produktového backlogu je úkolem vlastníka produktu.","c":"Není správně. Správa produktového backlogu není úkolem testera.","d":"Není správně. Návrh řešení je úkolem vývoje nebo analytiků a plán testování vytváří manažer testování."},"obecne":"Sylabus 1.4.5: Tester odpovídá za inženýrský aspekt testování a zaměřuje se na testovací analýzu, návrh testů, implementaci testování (včetně sestavení testovacího prostředí) a provedení testů (včetně reportování defektů). Plán testování vytváří manažer testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.4.5","nazev":"Role v testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-pet-role-v-testovani"}},{"id":"UC-1-14","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Byli jste přiděleni jako tester do týmu, který vyvíjí novou mobilní aplikaci pro e-commerce. Na jedné ze schůzek se vás zainteresovaná strana zeptala, zda je možné otestovat celou aplikaci úplně, se všemi kombinacemi vstupů. O který princip testování NEJLÉPE opřete svou odpověď?","m":["<p>Shlukování defektů.<\/p>","<p>Kompletní testování není možné.<\/p>","<p>Nepřítomnost defektů je klam.<\/p>","<p>Testy se opotřebovávají.<\/p>"],"ok":[1],"vys":{"a":"Princip „Shlukování defektů“ říká, že se defekty obvykle vyskytují v určitých oblastech nebo modulech softwarové aplikace. Může sice pomoci při plánování testování a zaměření na riziková místa, ale otázku proveditelnosti důkladného otestování celé aplikace přímo neřeší.","b":"Princip „Kompletní testování není možné“ říká, že v softwarové aplikaci nelze otestovat všechny možné kombinace vstupů a akcí. Důkladné otestování celé aplikace proto není proveditelné kvůli prakticky nekonečnému počtu testovacích případů, které by bylo možné vytvořit.","c":"Princip „Nepřítomnost defektů je klam“ varuje před mylnou představou, že pouhé ověřování (verifikace) a odstranění nalezených defektů zajistí úspěch systému. S proveditelností důkladného otestování celé aplikace ale přímo nesouvisí.","d":"Princip „Testy se opotřebovávají“ říká, že účinnost testu se s jeho opakováním postupně snižuje. S proveditelností důkladného otestování celé aplikace přímo nesouvisí, a proto není základem odpovědi na otázku zainteresované strany."},"obecne":"Sylabus 1.3, princip 2: Kompletní testování není možné. Testování všeho (např. všech kombinací vstupů) není možné s výjimkou triviálních případů; místo toho je lepší zaměřit se na vhodné techniky testování, prioritizaci testovacích případů a testování založené na rizicích.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UC-1-15","n":null,"lo":"FL-1.1.2","k":"K2","k3":true,"vyber":1,"q":"Co z následujícího NENÍ součástí procesu ladění?","m":["<p>Diagnostika (nalezení defektu).<\/p>","<p>Reprodukování selhání.<\/p>","<p>Psaní nových testovacích případů.<\/p>","<p>Oprava defektu.<\/p>"],"ok":[2],"vys":{"a":"Diagnostika, tedy nalezení příčiny problému (defektu), je základním krokem procesu ladění. Pochopení, proč problém nastal, je nezbytné pro účinné řešení.","b":"<p>Reprodukování selhání je klíčovou součástí procesu ladění, protože zahrnuje určení kroků, jimiž lze problém znovu vyvolat, což je nezbytné pro jeho pochopení a vyřešení.<\/p>","c":"Psaní nových testovacích případů obvykle součástí procesu ladění není. Ladění se zaměřuje na nalezení a opravu existujících problémů v kódu, nikoli na tvorbu nových testovacích případů.","d":"Oprava defektu je konečným cílem procesu ladění. Jakmile je příčina zjištěna, mohou vývojáři provést potřebné změny, problém vyřešit a zajistit správné fungování softwaru."},"obecne":"Sylabus 1.1.2: Typický proces ladění zahrnuje reprodukování selhání, diagnostiku (nalezení defektu) a opravu defektu. Psaní nových testovacích případů je testovací činnost (návrh testů), nikoli součást ladění.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.1.2","nazev":"Testování a ladění","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-dva-testovani-a-ladeni"}},{"id":"UC-1-16","n":null,"lo":"FL-1.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících faktorů (i–v) mají VÝZNAMNÝ vliv na proces testování?<\/p><p>i. SDLC<br>ii. Počet defektů zjištěných v předchozích projektech<br>iii. Kritičnost testovaného objektu<br>iv. Rozsah projektu<br>v. Počet certifikovaných testerů v organizaci<\/p>","m":["<p>iii, v<\/p>","<p>ii, iv, v <\/p>","<p>i, ii<\/p>","<p>i, iii, iv<\/p>"],"ok":[3],"vys":{"a":"Není správně. Počet certifikovaných testerů v organizaci není významným faktorem.","b":"Není správně. Počet defektů v předchozích projektech ani počet certifikovaných testerů nejsou významnými faktory.","c":"Není správně. Počet defektů v předchozích projektech nemá na proces testování významný vliv.","d":"Je správně. SDLC, kritičnost testovaného objektu (obor podnikání) i rozsah projektu (omezení projektu) sylabus uvádí jako faktory kontextu."},"obecne":"Sylabus 1.4.2: Způsob provádění testování závisí mimo jiné na oboru podnikání (kritičnost testovaného objektu), omezeních projektu (rozsah, čas, rozpočet, zdroje) a na životním cyklu vývoje softwaru.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.4.2","nazev":"Proces testování v souvislostech","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-dva-proces-testovani-v-souvislostech"}},{"id":"UC-1-17","n":null,"lo":"FL-1.1.1","k":"K1","k3":true,"vyber":1,"q":"Který z následujících faktorů NEOVLIVŇUJE cíle testování?","m":["<p>Míra automatizace používaná při testování.<\/p>","<p>Testovaný pracovní produkt.<\/p>","<p>Zvolený životní cyklus vývoje softwaru (SDLC).<\/p>","<p>Čas dostupný do uvedení produktu na trh.<\/p>"],"ok":[0],"vys":{"a":"<p>Míra automatizace používaná při testování s cíli testování přímo nesouvisí. Automatizace sice může výrazně ovlivnit efektivitu, pokrytí a spolehlivost testování, ale jde o způsob provádění testování, nikoli o faktor ovlivňující celkové cíle testování.<\/p>","b":"Testovaný pracovní produkt je zásadním faktorem, který cíle testování ovlivňuje. Složitost, velikost, kritičnost a kvalita pracovního produktu určují rozsah, hloubku a strategie testování potřebné k jeho důkladnému otestování.","c":"Zvolený životní cyklus vývoje softwaru (SDLC) může cíle testování ovlivnit, protože různé modely SDLC mohou mít odlišné požadavky a priority testování. Například v agilním SDLC musí být testování obvykle iterativnější a průběžnější než v SDLC typu vodopád.","d":"Čas dostupný do uvedení produktu na trh může cíle testování výrazně ovlivnit. Napjaté termíny mohou vyžadovat prioritizaci testovacích činností, zaměření na kritické funkcionality a vyvážení důkladnosti testování s včasným dodáním produktu."},"obecne":"Sylabus 1.1.1: Cíle testování se mohou lišit v závislosti na kontextu, např. na charakteristice testovaného pracovního produktu, úrovni testování, rizicích, zvoleném SDLC a byznysovém kontextu (struktura společnosti, konkurence, doba uvedení na trh). Míra automatizace testů mezi těmito faktory není; je to způsob provádění testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"}},{"id":"UC-1-19","n":null,"lo":"FL-1.2.2","k":"K1","k3":true,"vyber":1,"q":"Při vývoji softwaru se pojmy zajištění kvality (QA) a testování někdy používají zaměnitelně. Nakolik je tato praxe správná?","m":["<p>Nesprávná; QA je součástí procesu testování.<\/p>","<p>Nesprávná; QA zajišťuje kvalitu v průběhu celého procesu vývoje, zatímco testování kontroluje, zda něco funguje tak, jak má.<\/p>","<p>Nesprávná; testování je důkladnější proces, který se zaměřuje na zajištění toho, že software funguje tak, jak má.<\/p>","<p>Zcela správná; oba pojmy zahrnují všechny činnosti související s kvalitou softwaru.<\/p>"],"ok":[1],"vys":{"a":"Není správně. QA není součástí testování; je to preventivní přístup zaměřený na procesy vývoje i testování.","b":"Je správně. QA se zaměřuje na zavádění a zlepšování procesů v celém vývoji, testování je zaměřené na produkt a kontroluje, zda funguje, jak má.","c":"Není správně. Testování není širší než QA; je nápravným přístupem zaměřeným na produkt a formou řízení kvality.","d":"Není správně. Podle sylabu QA a testování nejsou totéž."},"obecne":"Sylabus 1.2.2: Testování a zajištění kvality nejsou totéž. Testování je nápravný přístup zaměřený na produkt a hlavní formou řízení kvality (QC). QA je preventivní přístup orientovaný na procesy, vztahuje se na procesy vývoje i testování a je odpovědností všech osob v projektu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.2.2","nazev":"Testování a zajištění kvality","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-dva-testovani-a-zajisteni-kvality"}},{"id":"UC-1-20","n":null,"lo":"FL-1.2.2","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího je <strong>PRAVDIVÉ<\/strong> o řízení kvality a zajištění kvality?<\/p>","m":["<p>Zajištění kvality a řízení kvality jsou totéž a lze je používat zaměnitelně.<\/p>","<p>Zajištění kvality je preventivní přístup orientovaný na produkt, zatímco řízení kvality je nápravný přístup orientovaný na procesy.<\/p>","<p>Zajištění kvality je preventivní přístup orientovaný na procesy, zatímco řízení kvality je nápravný přístup orientovaný na produkt.<\/p>","<p>Zajištění kvality je nápravný přístup orientovaný na procesy, zatímco řízení kvality je preventivní přístup orientovaný na procesy.<\/p>"],"ok":[2],"vys":{"a":"Zajištění kvality a řízení kvality nejsou totéž a nelze je používat zaměnitelně. Jde o dva odlišné přístupy s rozdílným zaměřením a cíli při zajišťování kvality produktu.","b":"Zajištění kvality je ve skutečnosti preventivní přístup orientovaný na procesy, který se zaměřuje na zlepšování procesů s cílem předcházet defektům. Řízení kvality je naopak nápravný přístup orientovaný na produkt, který se zaměřuje na odhalení defektů ve výsledném produktu a jejich opravu.","c":"Toto tvrzení správně rozlišuje zajištění kvality a řízení kvality. Zajištění kvality je preventivní přístup orientovaný na procesy, jehož cílem je zlepšovat procesy a předcházet tak defektům, zatímco řízení kvality je nápravný přístup orientovaný na produkt, který se zaměřuje na odhalování a opravu defektů ve výsledném produktu.","d":"<p>Zajištění kvality je ve skutečnosti preventivní přístup orientovaný na procesy, který zdůrazňuje, že dodržováním správných procesů vznikne správný produkt. Řízení kvality je naopak nápravný přístup orientovaný na produkt, zaměřený na odstraňování defektů v produktu.<\/p>"},"obecne":"Sylabus 1.2.2: Zajištění kvality (QA) je preventivní přístup orientovaný na procesy, založený na předpokladu, že správný proces vede ke správnému produktu. Řízení kvality (QC), jehož hlavní formou je testování, je nápravný přístup zaměřený na produkt.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.2.2","nazev":"Testování a zajištění kvality","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-dva-testovani-a-zajisteni-kvality"}},{"id":"UC-1-21","n":null,"lo":"FL-1.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Vývojář reviduje rozsáhlou sadu uživatelských scénářů pro novou funkci. Kvůli velkému množství informací špatně pochopí konkrétní požadavek týkající se formátování dat. Toto nepochopení ho vede k napsání kódu, který data zpracovává nesprávně. Co NEJLÉPE popisuje nesprávně implementovaný kód pro zpracování dat?<\/p>","m":["<p>Chyba<\/p>","<p>Selhání<\/p>","<p>Kořenová příčina<\/p>","<p>Defekt<\/p>"],"ok":[3],"vys":{"a":"<p>Chyba (omyl) je lidské jednání, které vede k nesprávnému výsledku – zde je to samotné špatné pochopení požadavku vývojářem. Nesprávně implementovaný kód je až důsledkem této chyby, tedy defektem, a pojem „chyba“ jej proto nevystihuje.<\/p>","b":"<p>Selhání označuje odchylku od očekávaného chování, tj. situaci, kdy systém nedosáhne požadovaného výsledku. Nesprávný kód pro zpracování dat sice může vést k selhání, ale pojem „selhání“ nepopisuje samotný kód.<\/p>","c":"<p>Pojem „kořenová příčina“ označuje primární důvod nebo zdroj problému. V tomto scénáři by kořenovou příčinou bylo špatné pochopení konkrétního požadavku na formátování dat, nikoli samotný kód, který data zpracovává nesprávně.<\/p>","d":"<p>Defekt je nedostatek nebo nedokonalost v produktu či systému, která může vést k nesprávnému chování nebo selhání. V tomto případě je kód, který kvůli nepochopení požadavku zpracovává data nesprávně, defektem.<\/p>"},"obecne":"Sylabus 1.2.3: Lidé dělají chyby (omyly), v jejichž důsledku vznikají defekty, které mohou vést k selhání. Špatné pochopení požadavku je chyba (jejíž kořenovou příčinou je velké množství informací), nesprávně napsaný kód je defekt a jeho projev při spuštění by byl selháním.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"}},{"id":"UC-1-23","n":null,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":1,"q":"Které z následujících tvrzení o týmovém přístupu je PRAVDIVÉ?","m":["<p>Při týmovém přístupu vývojáři a testeři úzce spolupracují, aby se dohodli na strategii testování a rozhodli o přístupech k automatizaci testů.<\/p>","<p>Týmový přístup je nejužitečnější při použití u bezpečnostně kritických systémů.<\/p>","<p>Při týmovém přístupu je sice každý zodpovědný za kvalitu, ale každý člen týmu vykonává pouze úkoly související s jeho rolí.<\/p>","<p>Týmový přístup je obecně lepší než nezávislé testování.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Testeři při týmovém přístupu úzce spolupracují s vývojáři, např. na dohodě o strategii testování a přístupech k automatizaci testů.","b":"Není správně. Týmový přístup není určen specificky pro bezpečnostně kritické systémy; u nich naopak může být nutná vysoká úroveň nezávislosti testování.","c":"Není správně. Každý člen týmu s potřebnými znalostmi a dovednostmi může vykonávat jakýkoliv úkol, nejen úkoly své role.","d":"Není správně. Týmový přístup není obecně lepší než nezávislé testování; vhodnost obou závisí na kontextu projektu."},"obecne":"Sylabus 1.5.2: Při týmovém přístupu testeři úzce spolupracují s vývojáři (např. na dohodě o strategii testování a přístupech k automatizaci testů) i se zástupci byznysu. Každý člen týmu může vykonávat jakýkoliv úkol, pro který má dovednosti, a u bezpečnostně kritických systémů nemusí být týmový přístup vhodný.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"UC-1-25","n":null,"lo":"FL-1.5.3","k":"K2","k3":true,"vyber":1,"q":"<p>Která DVĚ z následujících tvrzení patří mezi přínosy nezávislého testování?<\/p><p>i. Nezávislí testeři mohou být vnímáni jako úzké místo nebo mohou být viněni za zpoždění při vydávání produktu.<br>ii. Zvýšené pokrytí testy.<br>iii. Rozpoznání jiných druhů selhání a defektů ve srovnání s vývojáři.<br>iv. Smysl vývojářů pro kvalitu se díky soutěživosti zvyšuje.<br>v. Nezávislý tester může ověřit, napadnout či vyvrátit předpoklady zainteresovaných stran.<\/p>","m":["iv a v","iii a v","i a iv","i a iii"],"ok":[1],"vys":{"a":"Není správně. Tvrzení iv odporuje sylabu, vývojáři mohou naopak ztratit pocit odpovědnosti za kvalitu.","b":"Je správně. Rozpoznání jiných druhů selhání a defektů i zpochybnění předpokladů zainteresovaných stran jsou přínosy uvedené v sylabu.","c":"Není správně. Tvrzení i je nevýhoda a tvrzení iv odporuje sylabu (vývojáři mohou ztratit pocit odpovědnosti za kvalitu).","d":"Není správně. Tvrzení i popisuje nevýhodu nezávislosti, ne přínos."},"obecne":"Sylabus 1.5.3: Hlavním přínosem nezávislosti je, že nezávislí testeři pravděpodobněji rozpoznají jiné druhy selhání a defektů než vývojáři a mohou ověřit, napadnout či vyvrátit předpoklady zainteresovaných stran. Nevýhodou je izolace, ztráta pocitu odpovědnosti vývojářů za kvalitu a riziko, že testeři budou vnímáni jako úzké místo.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.5.3","nazev":"Nezávislost testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-tri-nezavislost-testovani"}},{"id":"UC-1-26","n":null,"lo":"FL-1.1.1","k":"K1","k3":true,"vyber":1,"q":"Který z následujících je typickým cílem testování?","m":["Soustředění defektů do malého počtu komponent","Nalezení a odstranění příčin selhání v kódu","Zajištění požadovaného pokrytí testovaného objektu","Provedení kompletního testování všech kombinací vstupů"],"ok":[2],"vys":{"a":"Není správně. Shlukování defektů je princip testování popisující, kde se defekty vyskytují, nikoli cíl.","b":"Není správně. Hledání a odstraňování příčin selhání je ladění, které je samostatnou činností.","c":"Je správně. Zajištění požadovaného pokrytí testovaného objektu je jedním z typických cílů testování.","d":"Není správně. Kompletní testování není možné s výjimkou triviálních případů."},"obecne":"Sylabus 1.1.1 uvádí mezi typickými cíli testování zajištění požadovaného pokrytí testovaného objektu. Kompletní testování není možné, shlukování defektů je princip testování a ladění je činnost oddělená od testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"}},{"id":"UC-1-37","n":null,"lo":"FL-1.2.2","k":"K1","k3":true,"vyber":1,"q":"Které z následujících tvrzení o testování softwaru a zajištění kvality NENÍ správné?","m":["Testování softwaru a zajištění kvality nejsou totéž.","Lidé často zaměňují pojmy testování a zajištění kvality.","Zajištění kvality se vztahuje i na procesy testování.","Zajištění kvality a testování musí vždy provádět dvě různé osoby."],"ok":[3],"vys":{"a":"Není správně. Tvrzení je pravdivé, sylabus výslovně uvádí, že testování a QA nejsou totéž.","b":"Není správně. Tvrzení je pravdivé, sylabus uvádí, že lidé tyto pojmy často zaměňují.","c":"Není správně. Tvrzení je pravdivé, QA se vztahuje na procesy vývoje i testování.","d":"Je správně. Toto tvrzení neplatí; QA je odpovědností všech osob v projektu a sylabus nepožaduje oddělené role."},"obecne":"Sylabus 1.2.2: Lidé často zaměňují pojmy testování a zajištění kvality, nicméně není to totéž. QA je preventivní přístup orientovaný na procesy, vztahuje se na procesy vývoje i testování a je odpovědností všech osob v projektu; žádné povinné oddělení rolí sylabus neuvádí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.2.2","nazev":"Testování a zajištění kvality","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-dva-testovani-a-zajisteni-kvality"}},{"id":"UC-1-38","n":null,"lo":"FL-1.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Tester prováděl testovací případ, v němž měl do vyhledávacího pole zadat název položky „Laptop“. Omylem však zadal hodnotu „labtob“.<\/p><p>Skutečným výsledkem byla zpráva „Pro slovo labtob nebyly nalezeny žádné výsledky, neměli jste na mysli laptop?“<\/p><p>Tester nahlásil defekt s popisem: „Když uživatel vyhledává laptopy, zobrazí se chybová zpráva, místo toho by se měl zobrazit seznam laptopů.“<\/p><p>Co NEJLÉPE popisuje tuto situaci?<\/p>","m":["Tester udělal chybu, jejímž důsledkem je falešně pozitivní výsledek.","Tester udělal chybu, jejímž důsledkem je falešně negativní výsledek.","Vývojář udělal chybu při psaní kódu, která vedla k defektu.","V této situaci žádný problém není, report o defektu je oprávněný."],"ok":[0],"vys":{"a":"Je správně. Tester nahlásil jako defekt chování, které je správné; jde o falešně pozitivní výsledek způsobený jeho chybou při zadání testovacích dat.","b":"Není správně. Falešně negativní výsledek by znamenal, že test neodhalil existující defekt.","c":"Není správně. Aplikace se zachovala správně, v kódu žádný defekt není.","d":"Není správně. Report popisuje neexistující defekt, takže problém existuje."},"obecne":"Sylabus 5.5 uvádí, že ne všechny nahlášené anomálie musí být skutečné defekty, např. falešně pozitivní výsledky testů. Falešně pozitivní výsledek je reportován jako defekt, ačkoli v testovaném objektu žádný defekt není; zde vznikl chybou testera (sylabus 1.2.3: lidé dělají chyby, i testeři).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"}},{"id":"UC-1-39","n":null,"lo":"FL-4.5.1","k":"K2","k3":true,"vyber":1,"q":"Který z následujících je správný formát zápisu uživatelského scénáře?","m":["Všechny požadavky musí dodržovat byznysové pravidlo č. 17","Jako &lt;role&gt; chci &lt;cíl&gt;, abych &lt;přínos&gt;","Za předpokladu &lt;kontext&gt;, když &lt;událost&gt;, pak &lt;výsledek&gt;","Uživatel se může přihlásit přes Facebook nebo Google"],"ok":[1],"vys":{"a":"Není správně. Jde o byznysové pravidlo, nikoli o uživatelský scénář.","b":"Je správně. Toto je nejběžnější formát uživatelského scénáře podle sylabu.","c":"Není správně. Formát kontext–událost–výsledek (Given/When/Then) se používá pro akceptační kritéria orientovaná na scénáře, ne pro samotný uživatelský scénář.","d":"Není správně. Jde o obecný požadavek bez role a přínosu."},"obecne":"Sylabus 4.5.1: Nejběžnějším formátem uživatelského scénáře je formule „Jako [ROLE] chci, aby [CÍL, který má být splněn], protože [výsledná byznysová HODNOTA pro roli]“, doplněná akceptačními kritérii. Formát Given/When/Then se podle 4.5.2 používá pro akceptační kritéria orientovaná na scénáře.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.1","nazev":"Společné psaní uživatelských scénářů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-jedna-spolecne-psani-uzivatelskych-scenaru"}},{"id":"UC-2-01","n":null,"lo":"FL-2.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení správně popisuje vztah mezi vývojovými a testovacími činnostmi podle osvědčených testovacích postupů?<\/p>","m":["<p>Testovací činnosti by měly být plánovány pouze na závěrečné fáze SDLC.<\/p>","<p>Testovací činnosti by měly být prováděny až po dokončení odpovídajících vývojových činností.<\/p>","<p>Ke každé vývojové činnosti by měla existovat odpovídající testovací činnost.<\/p>","<p>Mezi vývojovými a testovacími činnostmi neexistuje žádný přímý vztah.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Testování se plánuje a provádí v průběhu celého SDLC, ne jen v závěrečných fázích.","b":"Není správně. Testovací činnosti (např. revize, testovací analýza a návrh testů) začínají již během odpovídající vývojové činnosti.","c":"Je správně. Ke každé vývojové činnosti existuje odpovídající testovací činnost, takže všechny vývojové činnosti podléhají řízení kvality.","d":"Není správně. Ke každé vývojové činnosti má existovat odpovídající testovací činnost."},"obecne":"Sylabus 2.1.2: mezi osvědčené postupy nezávislé na modelu SDLC patří, že ke každé vývojové činnosti existuje odpovídající testovací činnost, takže všechny vývojové činnosti podléhají řízení kvality.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"}},{"id":"UC-2-02","n":null,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje vývoj řízený chováním (BDD)?<\/p>","m":["<p>V BDD jsou testy odvozovány z akceptačních kritérií jako součást procesu návrhu systému.<\/p>","<p>V BDD je psaní kódu řízeno pomocí testovacích případů.<\/p>","<p>V BDD je před zahájením jakéhokoli vývoje nutná úplná a finální sada akceptačních kritérií.<\/p>","<p>V BDD jsou testovací případy napsány v jednoduché formě přirozeného jazyka srozumitelného pro zainteresované strany.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Odvozování testů z akceptačních kritérií jako součásti návrhu systému charakterizuje ATDD.","b":"Není správně. Řízení psaní kódu pomocí testovacích případů charakterizuje TDD.","c":"Není správně. BDD podporuje iterativní vývoj; úplná a finální sada akceptačních kritérií předem není nutná.","d":"Je správně. V BDD se požadované chování popisuje testovacími případy v jednoduchém přirozeném jazyce srozumitelném zainteresovaným stranám."},"obecne":"Sylabus 2.1.3: v BDD je požadované chování aplikace popsáno testovacími případy v jednoduché formě přirozeného jazyka srozumitelného zainteresovaným stranám, obvykle ve formátu Given/When/Then. Ty se pak mají automaticky převést na spustitelné testy.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UC-2-04","n":null,"lo":"FL-2.1.6","k":"K2","k3":true,"vyber":1,"q":"<p>Všimli jste si, že v posledních vydáních opakovaně unikají testování některé chyby. Myslíte si, že by mohly pomoci retrospektivy. Který z následujících argumentů NEJLÉPE odpovídá vašemu cíli zlepšit efektivitu testování?<\/p>","m":["<p>Retrospektivy mohou odhalit slabiny v návrhu testů, což vede ke komplexnějšímu testwaru.<\/p>","<p>Retrospektivy zahrnují pět hodnot včetně odvahy a respektu, které jsou zásadní pro udržení neustálého zlepšování v organizaci.<\/p>","<p>Retrospektivy mohou zlepšit morálku týmu a komunikaci, což může vést k rychlejším vývojovým cyklům.<\/p>","<p>Retrospektivy jsou způsobem, jak externím zainteresovaným stranám doložit úsilí o neustálé zlepšování.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Retrospektiva může odhalit slabiny v návrhu testů a vést ke kvalitnějšímu testwaru, a tím k vyšší účinnosti testů.","b":"Není správně. Hodnoty jako odvaha a respekt nejsou podle sylabu podstatou retrospektiv a nepřispívají přímo k vyšší efektivitě testování.","c":"Není správně. Lepší morálka a komunikace jsou přínosem, ale přímo neřeší únik defektů a efektivitu testování.","d":"Není správně. Doložení zlepšování navenek nepřispívá ke zlepšení testování samotného."},"obecne":"Sylabus 2.1.6: mezi typické přínosy retrospektiv z pohledu testování patří vyšší efektivita a účinnost testů, vyšší kvalita testwaru, stmelování týmu a vzájemné učení, lepší kvalita testovací báze a lepší spolupráce mezi vývojem a testováním.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"}},{"id":"UC-2-05","n":null,"lo":"FL-2.2.1","k":"K2","k3":true,"vyber":1,"q":"<p>Narazíte na selhání, při kterém si dva vzájemně spolupracující moduly nesprávně předávají data. Ve které úrovni testování by takové selhání bylo NEJPRAVDĚPODOBNĚJI odhaleno?<\/p>","m":["<p>Testování komponent<\/p>","<p>Integrační testování komponent<\/p>","<p>Systémové testování<\/p>","<p>Systémové integrační testování<\/p>"],"ok":[1],"vys":{"a":"Není správně. Testování komponent se zaměřuje na izolované komponenty, ne na jejich vzájemnou komunikaci.","b":"Je správně. Integrační testování komponent se zaměřuje na rozhraní a interakce mezi komponentami.","c":"Není správně. Systémové testování se zaměřuje na celkové chování celého systému.","d":"Není správně. Systémové integrační testování se zaměřuje na rozhraní s jinými systémy a externími službami, ne mezi moduly jednoho systému."},"obecne":"Sylabus 2.2.1: integrační testování komponent se zaměřuje na testování rozhraní a interakcí mezi komponentami a silně závisí na zvolené integrační strategii (např. zdola nahoru, shora dolů, velký třesk). Systémové integrační testování naopak testuje rozhraní mezi testovaným systémem a dalšími systémy.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"}},{"id":"UC-2-06","n":null,"lo":"FL-2.1.6","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o retrospektivách je <strong>PRAVDIVÉ<\/strong>?<\/p>","m":["<p>Hlavním účelem retrospektivy je najít viníka nedostatků projektu.<\/p>","<p>Retrospektivy se konají jen na začátku projektu, před první iterací.<\/p>","<p>Retrospektivy se konají např. na konci iterace nebo po dosažení milníku.<\/p>","<p>Retrospektivy lze použít pouze v agilních modelech SDLC.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Retrospektiva slouží ke zlepšování procesu, ne k hledání viníků.","b":"Není správně. Retrospektivy se konají na konci projektu či iterace, při dosažení milníku nebo dle potřeby.","c":"Je správně. Retrospektivy se často konají na konci projektu nebo iterace, při dosažení milníku nebo dle potřeby.","d":"Není správně. Načasování a organizace retrospektiv závisí na modelu SDLC, ale nejsou omezeny na agilní modely."},"obecne":"Sylabus 2.1.6: retrospektivy se často konají na konci projektu nebo iterace, při dosažení milníku nebo dle potřeby. Jejich načasování a organizace závisí na konkrétním modelu SDLC a slouží ke kontinuálnímu zlepšování procesu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"}},{"id":"UC-2-08","n":null,"lo":"FL-2.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Pracujete jako tester v týmu, který vyvíjí e-commerce aplikaci podle agilního SDLC. Jak volba tohoto modelu životního cyklu vývoje softwaru (SDLC) ovlivňuje testovací činnosti?<\/p>","m":["<p>Dynamické testování nelze provádět v raných fázích SDLC<\/p>","<p>Ve Scrumu se při velkém důrazu na automatizaci testů manuální testování již neprovádí<\/p>","<p>Dynamické testování se provádí v raných fázích testování, zatímco statické testování probíhá až později v SDLC<\/p>","<p>Většina manuálních testovacích činností je prováděna pomocí technik testování založených na zkušenostech<\/p>"],"ok":[3],"vys":{"a":"Není správně. V agilním vývoji vzniká v každé iteraci funkční přírůstek, dynamické testování lze proto provádět od začátku.","b":"Není správně. I při rozsáhlé automatizaci se manuální testování stále provádí.","c":"Není správně. V iterativních modelech lze statické i dynamické testování provádět v každé iteraci.","d":"Je správně. V agilních projektech se většina manuálních testů často provádí pomocí technik testování založených na zkušenostech."},"obecne":"Sylabus 2.1.1: volba SDLC má dopad na rozsah a načasování testovacích činností, úroveň detailu testovací dokumentace, volbu technik testování a přístupu k testování, rozsah automatizace testů a role a zodpovědnosti testerů. V agilním vývoji se upřednostňuje stručnější dokumentace a rozsáhlá automatizace testů; většina manuálních testů se často provádí pomocí technik testování založených na zkušenostech.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.1","nazev":"Vliv životního cyklu vývoje softwaru na testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-jedna-vliv-zivotniho-cyklu-vyvoje-softwaru-na-testovani"}},{"id":"UC-2-09","n":null,"lo":"FL-2.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Tester pracuje na novém přihlašovacím systému banky, kde je zabezpečení kritické. Požadavek s vysokou prioritou zní: <em>„Hesla musí být před uložením do databáze zahashována pomocí bezpečného algoritmu.“<\/em><\/p><p>Tester prostuduje zdrojový kód funkce pro hashování hesel a navrhne testovací případy tak, aby se při jejich provedení vykonaly všechny větve této funkce.<\/p><p>Jaký typ testů tester NEJPRAVDĚPODOBNĚJI provádí?<\/p>","m":["<p>Testování použitelnosti<\/p>","<p>Testování výkonnosti<\/p>","<p>Testování bílé skříňky<\/p>","<p>Testování černé skříňky<\/p>"],"ok":[0],"vys":{"a":"Není správně. Testování použitelnosti hodnotí snadnost použití pro uživatele, ne strukturu kódu.","b":"Není správně. Testy neměří čas ani spotřebu zdrojů, ověřují pokrytí struktury funkce.","c":"Je správně. Testy jsou odvozeny ze struktury kódu s cílem pokrýt všechny větve – jde o testování bílé skříňky.","d":"Není správně. Testování černé skříňky vychází ze specifikace, ne z vnitřní struktury kódu."},"obecne":"Sylabus 2.2.2: testování bílé skříňky je založeno na struktuře a odvozuje testy z implementace nebo vnitřní struktury systému (např. kódu); jeho hlavním cílem je dosáhnout přijatelného pokrytí této struktury.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"2.2.2","nazev":"Typy testů","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-dva-typy-testu"}},{"id":"UC-2-10","n":null,"lo":"FL-2.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Interní reportovací software sloužil společnosti léta dobře, nyní ho však nahrazuje nová cloudová platforma. Starší software se blíží ke konci své životnosti, a proto se pozornost přesunula na řádnou archivaci jeho dat pro budoucí potřebu. Tým nyní testuje správnost archivace dat a to, zda lze archivovaná data později obnovit a načíst.<\/p><p>Který spouštěč testování údržby tuto situaci NEJLÉPE popisuje?<\/p>","m":["<p>Upgrade softwaru na novější verzi<\/p>","<p>Vyřazení původního systému z provozu<\/p>","<p>Přidání nových funkcionalit do systému<\/p>","<p>Optimalizace výkonu stávajícího systému<\/p>"],"ok":[1],"vys":{"a":"Není správně. Starší software se neaktualizuje, ale končí jeho životnost.","b":"Je správně. Při vyřazení systému z provozu se testuje archivace dat a procesy jejich obnovení a načtení.","c":"Není správně. Do starého systému se žádné nové funkce nepřidávají.","d":"Není správně. Scénář se netýká výkonu, ale archivace dat při ukončení provozu."},"obecne":"Sylabus 2.3: spouštěči testování údržby jsou úpravy (plánovaná vylepšení, opravné změny, hotfixy), aktualizace nebo migrace provozního prostředí (např. z jedné platformy na jinou) a vyřazení aplikace z provozu, kdy může být vhodné testovat archivaci dat a procesy jejich obnovení a načtení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.3","nazev":"Testování údržby","href":"kapitola-2/vyklad.html#cast-dva-tecka-tri-testovani-udrzby"}},{"id":"UC-2-11","n":null,"lo":"FL-2.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o roli testerů v sekvenčních modelech vývoje je pravdivé?<\/p>","m":["<p>Testeři se obvykle účastní revizí požadavků, testovací analýzy a návrhu testů a dynamické testování mohou provádět během celého SDLC.<\/p>","<p>Testeři se obvykle účastní pouze provedení testů a reportování defektů a do jiných fází SDLC zapojeni nejsou.<\/p>","<p>Testeři se obvykle účastní revizí požadavků, testovací analýzy a návrhu testů, ale dynamické testování mohou provádět až v pozdějších fázích SDLC.<\/p>","<p>Testeři se obvykle neúčastní žádné fáze sekvenčních SDLC.<\/p>"],"ok":[2],"vys":{"a":"Není správně. V sekvenčních modelech vzniká spustitelný kód až později, dynamické testování proto v raných fázích provádět nelze.","b":"Není správně. Testeři se v sekvenčních modelech zapojují už v počátečních fázích.","c":"Je správně. Testeři se účastní revizí požadavků, testovací analýzy a návrhu testů, dynamické testování je ale možné až později.","d":"Není správně. Testeři se v sekvenčních modelech účastní řady fází SDLC."},"obecne":"Sylabus 2.1.1: v sekvenčních modelech vývoje se testeři v počátečních fázích obvykle účastní revizí požadavků, testovací analýzy a návrhu testů. Spustitelný kód obvykle vzniká až v pozdějších fázích, proto v počátečních fázích nelze provádět dynamické testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.1","nazev":"Vliv životního cyklu vývoje softwaru na testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-jedna-vliv-zivotniho-cyklu-vyvoje-softwaru-na-testovani"}},{"id":"UC-2-12","n":null,"lo":"FL-2.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících aspektů testování <strong>NENÍ<\/strong> ovlivněn volbou SDLC?<\/p>","m":["<p>Rozsah automatizace testů<\/p>","<p>Rozsah a načasování testovacích činností<\/p>","<p>Úroveň detailu testovací dokumentace<\/p>","<p>Důležitost nalézání a opravování defektů<\/p>"],"ok":[3],"vys":{"a":"Není správně. Rozsah automatizace testů volba SDLC ovlivňuje.","b":"Není správně. Rozsah a načasování testovacích činností volba SDLC ovlivňuje.","c":"Není správně. Úroveň detailu testovací dokumentace volba SDLC ovlivňuje.","d":"Je správně. Důležitost nalézání a opravování defektů nezávisí na zvoleném modelu SDLC."},"obecne":"Sylabus 2.1.1: volba SDLC má dopad na rozsah a načasování testovacích činností, úroveň detailu testovací dokumentace, volbu technik testování a přístupu k testování, rozsah automatizace testů a role a zodpovědnosti testerů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.1","nazev":"Vliv životního cyklu vývoje softwaru na testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-jedna-vliv-zivotniho-cyklu-vyvoje-softwaru-na-testovani"}},{"id":"UC-2-13","n":null,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Při vývoji e-commerce aplikace byly testovací případy pro přihlášení napsány ve formátu „Given… When… Then“. Který přístup k vývoji se u této aplikace NEJPRAVDĚPODOBNĚJI uplatňuje?<\/p>","m":["<p>BDD<\/p>","<p>ATDD<\/p>","<p>Vodopádový model<\/p>","<p>TDD<\/p>"],"ok":[0],"vys":{"a":"Je správně. V BDD se chování popisuje v přirozeném jazyce, obvykle ve formátu Given/When/Then.","b":"Není správně. ATDD odvozuje testy z akceptačních kritérií; formát Given/When/Then je typický pro BDD.","c":"Není správně. Vodopádový model je sekvenční model vývoje, žádný formát testovacích případů nepředepisuje.","d":"Není správně. V TDD jde o testy, které řídí psaní kódu, typicky na úrovni komponent, ne o formát Given/When/Then."},"obecne":"Sylabus 2.1.3: v BDD je požadované chování aplikace popsáno testovacími případy v jednoduché formě přirozeného jazyka srozumitelného zainteresovaným stranám, obvykle ve formátu Given/When/Then.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UC-2-14","n":null,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o vývoji řízeném testy (TDD), vývoji řízeném akceptačními testy (ATDD) a vývoji řízeném chováním (BDD) je <strong>NESPRÁVNÉ<\/strong>?<\/p>","m":["<p>V těchto přístupech jsou testy definovány před napsáním kódu<\/p>","<p>Všechny uplatňují přístup k testování shift right (posun doprava)<\/p>","<p>Tyto přístupy podporují iterativní modely vývoje<\/p>","<p>Každý z těchto přístupů je aplikací principu včasného testování<\/p>"],"ok":[1],"vys":{"a":"Není správně. Tvrzení je pravdivé – testy se definují před napsáním kódu.","b":"Je správně. Tvrzení je nesprávné – TDD, ATDD i BDD uplatňují shift left, ne shift right.","c":"Není správně. Tvrzení je pravdivé – všechny tři přístupy podporují iterativní model vývoje.","d":"Není správně. Tvrzení je pravdivé – všechny tři přístupy jsou aplikací principu včasného testování."},"obecne":"Sylabus 2.1.3: TDD, ATDD i BDD jsou aplikací principů včasného testování a shift left – testy jsou definovány před napsáním kódu – a všechny podporují iterativní model vývoje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UC-2-16","n":null,"lo":"FL-2.1.4","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího z pohledu testování <strong>NENÍ<\/strong> výhodou zavedení DevOps?<\/p>","m":["<p>Vyšší míra automatizace prostřednictvím pipeline snižuje potřebu opakovaného manuálního testování<\/p>","<p>DevOps podporuje princip shift left při testování, a tím včasnější odhalování defektů<\/p>","<p>DevOps zcela odstraňuje potřebu manuálního testování<\/p>","<p>Pipeline CI/CD usnadňují vytváření stabilních a spolehlivých testovacích prostředí<\/p>"],"ok":[2],"vys":{"a":"Není správně. Snížení potřeby opakovaného manuálního testování díky automatizaci je výhodou DevOps.","b":"Není správně. Podpora shift left díky CI je výhodou DevOps.","c":"Je správně. DevOps manuální testování neodstraňuje; zejména z pohledu koncového uživatele je stále potřeba.","d":"Není správně. Automatizované zpracování (CI/CD) usnadňuje vytváření stabilních testovacích prostředí."},"obecne":"Sylabus 2.1.4: z pohledu testování DevOps poskytuje rychlou zpětnou vazbu o kvalitě kódu, díky CI podporuje shift left, usnadňuje vytváření stabilních testovacích prostředí, zvyšuje důraz na nefunkcionální charakteristiky kvality, snižuje potřebu opakovaného manuálního testování a minimalizuje riziko regrese díky automatizovaným regresním testům. Manuální testování, zejména z pohledu koncového uživatele, je však stále potřeba.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.4","nazev":"DevOps a testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-ctyri-devops-a-testovani"}},{"id":"UC-2-17","n":null,"lo":"FL-2.1.4","k":"K2","k3":true,"vyber":1,"q":"<p>Vývojový tým pracuje na nové platformě sociální sítě s průběžnými aktualizacemi funkcí. Kvůli častým nasazením je nepraktické po každé změně manuálně testovat všechny funkcionality. Zajištění pozitivní uživatelské zkušenosti však zůstává zásadní.<\/p><p>Které z následujících tvrzení NEJLÉPE popisuje, jak může přístup DevOps v tomto scénáři podpořit testování?<\/p>","m":["<p>DevOps klade důraz na podrobné uživatelské scénáře pro každou funkci, čímž snižuje potřebu testování uživatelské zkušenosti<\/p>","<p>DevOps vyžaduje, aby testeři před zahájením jakýchkoli testovacích činností počkali na dokončení funkce<\/p>","<p>DevOps zcela odstraňuje potřebu manuálního testování a spoléhá se výhradně na automatizované testování<\/p>","<p>DevOps podporuje automatizované regresní testování, které pomáhá včas odhalit defekty a minimalizovat riziko regrese<\/p>"],"ok":[3],"vys":{"a":"Není správně. Podrobné uživatelské scénáře potřebu testování uživatelské zkušenosti nesnižují a nejsou podstatou DevOps.","b":"Není správně. DevOps naopak podporuje shift left a testování průběžně během vývoje.","c":"Není správně. Manuální testování z pohledu koncového uživatele je v DevOps stále potřeba.","d":"Je správně. DevOps minimalizuje riziko regrese díky rozsáhlým automatizovaným regresním testům a rychlé zpětné vazbě."},"obecne":"Sylabus 2.1.4: z pohledu testování DevOps poskytuje rychlou zpětnou vazbu o kvalitě kódu, díky CI podporuje shift left, usnadňuje vytváření stabilních testovacích prostředí, zvyšuje důraz na nefunkcionální charakteristiky kvality, snižuje potřebu opakovaného manuálního testování a minimalizuje riziko regrese díky automatizovaným regresním testům. Manuální testování, zejména z pohledu koncového uživatele, je však stále potřeba.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.4","nazev":"DevOps a testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-ctyri-devops-a-testovani"}},{"id":"UC-2-18","n":null,"lo":"FL-2.1.5","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje princip shift left (posun doleva)?<\/p>","m":["<p>Testování, které se provádí dříve v SDLC.<\/p>","<p>Testování, které se provádí později v SDLC.<\/p>","<p>Testování, které se provádí po vydání produktu.<\/p>","<p>Testování, které se provádí souběžně s vývojem.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Shift left znamená provádět testování v dřívějších fázích SDLC.","b":"Není správně. Testování v pozdějších fázích je opakem shift left.","c":"Není správně. Testování po vydání produktu je pozdní testování, nikoli shift left.","d":"Není správně. Souběh s vývojem není podstatou shift left; jde o posun testování co nejdříve, např. již k revizi požadavků."},"obecne":"Sylabus 2.1.5: shift left (princip včasného testování) znamená provádět testování dříve v SDLC, např. nečekat na implementaci kódu nebo integraci komponent. Neznamená to, že by se testování v pozdějších fázích mělo zanedbávat. Zavedení může zpočátku znamenat vyšší náklady, ale v pozdějších fázích pracnost a náklady šetří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"}},{"id":"UC-2-19","n":null,"lo":"FL-2.1.5","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího je o principu shift left <strong>PRAVDIVÉ<\/strong>?<\/p>","m":["<p>Osvědčeným postupem v rámci principu shift left je psát testovací případy až po napsání kódu, aby se zvýšilo pokrytí.<\/p>","<p>Osvědčeným postupem v rámci principu shift left je psát testovací případy před napsáním kódu a během implementace spouštět kód v sadě testovacího vybavení (test harness).<\/p>","<p>Při uplatnění principu shift left se testuje dříve, takže testování v pozdějších fázích SDLC je zanedbáváno.<\/p>","<p>Princip shift left sice z dlouhodobého hlediska šetří pracnost, ale v pozdějších fázích procesu se očekává, že bude značně nákladný.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Shift left doporučuje psát testovací případy před kódem.","b":"Je správně. Psaní testovacích případů před kódem a spouštění kódu v sadě testovacího vybavení během implementace je příkladem shift left.","c":"Není správně. Shift left neznamená, že by se testování v pozdějších fázích mělo zanedbávat.","d":"Není správně. Shift left může být nákladnější na začátku, v pozdějších fázích ale pracnost a náklady šetří."},"obecne":"Sylabus 2.1.5: shift left (princip včasného testování) znamená provádět testování dříve v SDLC, např. nečekat na implementaci kódu nebo integraci komponent. Neznamená to, že by se testování v pozdějších fázích mělo zanedbávat. Zavedení může zpočátku znamenat vyšší náklady, ale v pozdějších fázích pracnost a náklady šetří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"}},{"id":"UC-2-20","n":null,"lo":"FL-2.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího <strong>NENÍ<\/strong> faktorem ovlivňujícím rozsah testování údržby?<\/p>","m":["<p>Rozsah provedené změny<\/p>","<p>Míra rizika dané změny<\/p>","<p>Počet plánovaných testů<\/p>","<p>Velikost stávajícího systému<\/p>"],"ok":[2],"vys":{"a":"Není správně. Rozsah změny je faktorem rozsahu testování údržby.","b":"Není správně. Míra rizika změny je faktorem rozsahu testování údržby.","c":"Je správně. Počet testů je důsledkem stanoveného rozsahu testování, ne faktorem, který ho určuje.","d":"Není správně. Velikost stávajícího systému je faktorem rozsahu testování údržby."},"obecne":"Sylabus 2.3: rozsah testování údržby závisí na míře rizika změny, velikosti stávajícího systému a rozsahu změny.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.3","nazev":"Testování údržby","href":"kapitola-2/vyklad.html#cast-dva-tecka-tri-testovani-udrzby"}},{"id":"UC-2-21","n":null,"lo":"FL-2.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Software, na kterém pracujete jako tester, bude převeden z desktopové aplikace na webovou. Jaký typ testování budete NEJPRAVDĚPODOBNĚJI provádět?<\/p>","m":["<p>Testování napříč prohlížeči<\/p>","<p>Konfirmační testování<\/p>","<p>Testování uživatelského rozhraní<\/p>","<p>Testování údržby<\/p>"],"ok":[3],"vys":{"a":"Není správně. Testování v různých prohlížečích může být součástí, ale nevystihuje situaci migrace provozovaného systému.","b":"Není správně. Konfirmační testování ověřuje opravu konkrétního defektu, o kterou zde nejde.","c":"Není správně. Testování uživatelského rozhraní může být součástí, ale nevystihuje situaci migrace provozovaného systému.","d":"Je správně. Migrace provozního prostředí z jedné platformy na jinou je spouštěčem testování údržby."},"obecne":"Sylabus 2.3: spouštěči testování údržby jsou úpravy (plánovaná vylepšení, opravné změny, hotfixy), aktualizace nebo migrace provozního prostředí (např. z jedné platformy na jinou) a vyřazení aplikace z provozu, kdy může být vhodné testovat archivaci dat a procesy jejich obnovení a načtení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.3","nazev":"Testování údržby","href":"kapitola-2/vyklad.html#cast-dva-tecka-tri-testovani-udrzby"}},{"id":"UC-2-22","n":null,"lo":"FL-2.1.6","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího <strong>NENÍ<\/strong> typickou výhodou retrospektivy z pohledu testování?<\/p>","m":["<p>Vyšší počet nalezených defektů<\/p>","<p>Zlepšování kvality testovací báze<\/p>","<p>Zvyšování efektivity testů<\/p>","<p>Zvyšování kvality testwaru<\/p>"],"ok":[0],"vys":{"a":"Je správně. Vyšší počet nalezených defektů sylabus mezi přínosy retrospektiv neuvádí; retrospektiva zlepšuje proces, ne přímo počet defektů.","b":"Není správně. Lepší kvalita testovací báze je typickým přínosem retrospektiv.","c":"Není správně. Vyšší efektivita a účinnost testů je typickým přínosem retrospektiv.","d":"Není správně. Vyšší kvalita testwaru je typickým přínosem retrospektiv."},"obecne":"Sylabus 2.1.6: mezi typické přínosy retrospektiv z pohledu testování patří vyšší efektivita a účinnost testů, vyšší kvalita testwaru, stmelování týmu a vzájemné učení, lepší kvalita testovací báze a lepší spolupráce mezi vývojem a testováním.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"}},{"id":"UC-3-01","n":null,"lo":"FL-3.2.3","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností uvádí pouze role při formální revizi podle sylabu?<\/p>","m":["<p>Autor, manažer, vedoucí revize, revidující, designér<\/p>","<p>Autor, moderátor, vedoucí revize, revidující, zapisovatel<\/p>","<p>Vývojář, moderátor, vedoucí revize, revidující, tester<\/p>","<p>Autor, moderátor, manažer, revidující, vývojář<\/p>"],"ok":[1],"vys":{"a":"Není správně. Designér není role při revizi.","b":"Je správně. Autor, moderátor, vedoucí revize, revidující a zapisovatel jsou hlavní role při revizi.","c":"Není správně. Vývojář a tester nejsou role při revizi; mohou být nanejvýš revidujícími.","d":"Není správně. Vývojář není role při revizi."},"obecne":"Sylabus 3.2.3 uvádí jako hlavní role při revizích manažera, autora, moderátora (facilitátora), zapisovatele, revidujícího a vedoucího revize.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"}},{"id":"UC-3-03","n":null,"lo":"FL-3.1.2","k":"K2","k3":true,"vyber":1,"q":"<p>Statické testování může být v životním cyklu vývoje softwaru (SDLC) cenným nástrojem. Co z následujícího je přínosem statického testování?<\/p>","m":["<p>Odhalování funkcionálních defektů uživatelského rozhraní za běhu<\/p>","<p>Měření výkonnosti aplikace za běhu<\/p>","<p>Identifikace defektů v nespustitelných pracovních produktech<\/p>","<p>Testování interakce mezi integrovanými komponentami<\/p>"],"ok":[2],"vys":{"a":"Není správně. Funkcionální defekty uživatelského rozhraní za běhu odhalí dynamické testování.","b":"Není správně. Výkonnost za běhu měří dynamické testování.","c":"Je správně. Statické testování může odhalit defekty v nespustitelných pracovních produktech, které dynamické testování zjistit nemůže.","d":"Není správně. Interakci integrovaných komponent ověřuje dynamické integrační testování."},"obecne":"Sylabus 3.1.2: statické testování může odhalit defekty v nejranějších fázích SDLC a také defekty, které nelze zjistit dynamickým testováním, např. nedosažitelný kód, chybně implementované návrhové vzory nebo defekty v nespustitelných pracovních produktech.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"}},{"id":"UC-3-04","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Váš vývojový tým se potýká s přetrvávajícím problémem v kritickém modulu, který výrazně ovlivňuje výkonnost systému. Vyřešení problému vyžaduje hluboké porozumění použitým algoritmům a architektuře. Rozhodnete se svolat malou skupinu seniorních vývojářů a architektů ke společné cílené diskusi, která má problém vyřešit. Každý člen skupiny se předem důkladně připraví, aby mohl efektivně přispět. Během schůzky, kterou vede moderátor (facilitátor), skupina diskutuje o možných řešeních a posuzuje kvalitu stávajícího návrhu.<\/p><p>Který typ revize NEJLÉPE popisuje tento scénář?<\/p>","m":["<p>Předvedení (walkthrough)<\/p>","<p>Neformální revize<\/p>","<p>Inspekce<\/p>","<p>Technická revize<\/p>"],"ok":[3],"vys":{"a":"Není správně. Předvedení vede autor, zde schůzku vede moderátor.","b":"Není správně. Neformální revize se neřídí definovaným procesem; zde jde o připravenou schůzku odborníků vedenou moderátorem.","c":"Není správně. Hlavním cílem inspekce je nalézt maximální počet anomálií, ne vyřešit technický problém.","d":"Je správně. Technickou revizi provádějí odborně kvalifikovaní revidující, vede ji moderátor a jejím hlavním cílem je dosáhnout shody a rozhodnout o technickém problému."},"obecne":"Sylabus 3.2.4: technickou revizi provádějí odborně kvalifikovaní revidující a vede ji moderátor. Jejím primárním cílem je dosáhnout shody a učinit rozhodnutí týkající se technického problému; dalšími cíli jsou např. vyhodnocení kvality a generování nových nápadů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UC-3-05","n":null,"lo":"FL-3.2.5","k":"K1","k3":true,"vyber":1,"q":"<p>Který faktor je klíčový pro zajištění úspěchu revizí?<\/p>","m":["<p>Poskytování zpětné vazby z revizí zainteresovaným stranám a autorům<\/p>","<p>Provádění revizí bez jasných cílů a měřitelných výstupních kritérií<\/p>","<p>Zavedení přísného časového limitu pro každou revizní schůzku<\/p>","<p>Provádění revizí příležitostně, nikoli jako součásti firemní kultury<\/p>"],"ok":[0],"vys":{"a":"Je správně. Zpětná vazba z revizí umožňuje zainteresovaným stranám a autorům zlepšovat produkt i své činnosti.","b":"Není správně. Faktorem úspěchu jsou naopak jasné cíle a měřitelná výstupní kritéria.","c":"Není správně. Přísný časový limit pro každou revizní schůzku sylabus mezi faktory úspěchu neuvádí.","d":"Není správně. Faktorem úspěchu je naopak to, že revize jsou součástí firemní kultury."},"obecne":"Sylabus 3.2.5 uvádí mezi faktory úspěchu revize poskytování zpětné vazby z revizí zainteresovaným stranám a autorům, aby mohli zlepšovat produkt a své činnosti, dále jasné cíle a měřitelná výstupní kritéria a začlenění revizí do firemní kultury.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.5","nazev":"Faktory úspěchu při revizi","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-pet-faktory-uspechu-pri-revizi"}},{"id":"UC-3-06","n":null,"lo":"FL-3.1.1","k":"K1","k3":true,"vyber":1,"q":"<p>Připravujete revizi pracovních produktů projektu a potřebujete určit, které z nich lze zahrnout do statického testování.<\/p><p>Který z následujících pracovních produktů je pro statické testování <strong>NEJMÉNĚ<\/strong> vhodný?<\/p>","m":["<p>Uživatelské scénáře pro nadcházející vydání<\/p>","<p>Spustitelný kód třetí strany, jehož analýzu zakazuje licence<\/p>","<p>Zdrojový kód aplikace vyvíjené vlastním týmem<\/p>","<p>Plán testování pro nadcházející vydání<\/p>"],"ok":[1],"vys":{"a":"Není správně. Uživatelské scénáře lze revidovat a odhalit v nich např. nejednoznačnosti.","b":"Je správně. Spustitelný kód třetí strany je pro člověka obtížně interpretovatelný a z právních důvodů jej nelze analyzovat nástroji.","c":"Není správně. Zdrojový kód lze revidovat i analyzovat nástroji statické analýzy.","d":"Není správně. Plán testování je pracovní produkt, který lze revidovat."},"obecne":"Sylabus 3.1.1: téměř každý pracovní produkt může být prozkoumán statickým testováním. Nevhodné jsou pracovní produkty, které jsou obtížně interpretovatelné lidmi a současně by neměly být analyzovány nástroji, např. spustitelný kód třetí strany, který z právních důvodů nelze analyzovat.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.1","nazev":"Pracovní produkty, které mohou být prověřeny statickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-jedna-pracovni-produkty-ktere-mohou-byt-provereny-statickym-testovanim"}},{"id":"UC-3-07","n":null,"lo":"FL-3.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení SPRÁVNĚ popisuje rozdíl mezi statickým a dynamickým testováním?<\/p>","m":["<p>Statické testování měří kvalitativní charakteristiky závislé na spuštění kódu, zatímco dynamické testování měří charakteristiky na spuštění kódu nezávislé.<\/p>","<p>Statické testování je při hledání defektů v požadavcích méně účinné než dynamické testování.<\/p>","<p>Statické testování lze použít na nespustitelné pracovní produkty, zatímco dynamické testování lze použít pouze na spustitelné pracovní produkty.<\/p>","<p>Statické testování přímo odhaluje selhání, zatímco dynamické testování přímo odhaluje defekty.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Role jsou prohozené – statické testování měří charakteristiky nezávislé na spuštění kódu (např. udržovatelnost).","b":"Není správně. Defekty v požadavcích se naopak snáze a levněji odhalí statickým testováním.","c":"Je správně. Dynamické testování lze použít pouze na spustitelné pracovní produkty, statické i na nespustitelné.","d":"Není správně. Je to naopak: statické testování nachází defekty přímo, dynamické hledá selhání."},"obecne":"Sylabus 3.1.3: dynamické testování lze použít pouze na spustitelné pracovní produkty, statické testování i na nespustitelné. Statické testování najde defekty přímo a lze jím měřit charakteristiky nezávislé na spuštění kódu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"}},{"id":"UC-3-08","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o předvedení (walkthrough) je <strong>PRAVDIVÉ<\/strong>?<\/p>","m":["<p>Hlavním cílem předvedení je formální dokumentovaný výstup revize.<\/p>","<p>Předvedení vždy provádějí externí revidující bez účasti autora.<\/p>","<p>Při předvedení se shromažďují metriky pro zlepšování procesu předvedení.<\/p>","<p>Předvedení vede autor a může sloužit např. ke vzdělávání revidujících.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Předvedení nevyžaduje formální dokumentovaný výstup; slouží mnoha cílům, např. hodnocení kvality a dosažení dohody.","b":"Není správně. Předvedení vede autor revidovaného pracovního produktu.","c":"Není správně. Shromažďování metrik pro zlepšování procesu je charakteristické pro inspekci.","d":"Je správně. Předvedení je vedené autorem a může sloužit mnoha cílům, mimo jiné vzdělávání revidujících."},"obecne":"Sylabus 3.2.4: předvedení (vedené autorem) může sloužit mnoha cílům, jako je hodnocení kvality a budování důvěry v pracovní produkt, vzdělávání revidujících, dosažení dohody, generování nových nápadů či odhalování anomálií.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UC-3-10","n":null,"lo":"FL-3.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího <strong>NENÍ<\/strong> přínosem včasné a časté zpětné vazby od zainteresovaných stran?<\/p>","m":["<p>Zabraňuje nedorozuměním při definici požadavků.<\/p>","<p>Zajišťuje, aby změny požadavků byly pochopeny a implementovány dříve.<\/p>","<p>Snižuje pracovní zátěž vývojářů, kteří se mohou věnovat výhradně programování.<\/p>","<p>Všechny výše uvedené možnosti jsou přínosy zpětné vazby.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Prevence nedorozumění při definici požadavků je přínosem zpětné vazby.","b":"Není správně. Včasné pochopení a implementace změn požadavků je přínosem zpětné vazby.","c":"Je správně. Snížení pracovní zátěže vývojářů není přínosem zpětné vazby uvedeným v sylabu.","d":"Není správně. Možnost c) přínosem není, takže ne všechny uvedené možnosti jsou přínosy."},"obecne":"Sylabus 3.2.1: častá zpětná vazba od zainteresovaných stran může zabránit nedorozuměním při definici požadavků a zajistit, aby změny požadavků byly správně a včas pochopeny a implementovány. Snížení pracovní zátěže vývojářů mezi přínosy nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.1","nazev":"Výhody včasné a časté zpětné vazby od zainteresovaných stran","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-jedna-vyhody-vcasne-a-caste-zpetne-vazby-od-zainteresovanych-stran"}},{"id":"UC-3-11","n":null,"lo":"FL-3.2.3","k":"K1","k3":true,"vyber":1,"q":"<p>Uvažujte následující role při revizi (1–4):<\/p><p>1. Moderátor<\/p><p>2. Manažer<\/p><p>3. Vedoucí revize<\/p><p>4. Autor<\/p><p>a jejich odpovědnosti (A–D):<\/p><p>A. Přebírá celkovou odpovědnost za revizi (např. rozhodování o tom, kdo do ní bude zapojen) a organizaci toho, kdy a kde se bude revize konat<\/p><p>B. Rozhoduje o tom, co má být revidováno a jaké zdroje budou využity (včetně lidí a času)<\/p><p>C. Zajišťuje efektivní průběh revizních schůzek<\/p><p>D. Vytváří a opravuje revidovaný pracovní produkt<\/p><p>Jak se uvedené role při revizi přiřazují k popsaným odpovědnostem?<\/p>","m":["<p>1A, 2C, 3B, 4D<\/p>","<p>1A, 2C, 3D, 4B<\/p>","<p>1C, 2B, 3D, 4A<\/p>","<p>1C, 2B, 3A, 4D<\/p>"],"ok":[3],"vys":{"a":"Není správně. Moderátor zajišťuje průběh schůzek (C), manažer rozhoduje o rozsahu a zdrojích (B) a vedoucí revize přebírá celkovou odpovědnost (A).","b":"Není správně. Kromě prohozených rolí moderátora a manažera je chybně přiřazen i autor a vedoucí revize.","c":"Není správně. Vedoucí revize přebírá celkovou odpovědnost (A) a autor vytváří a opravuje pracovní produkt (D).","d":"Je správně. Moderátor – C, manažer – B, vedoucí revize – A, autor – D."},"obecne":"Sylabus 3.2.3: manažer rozhoduje o tom, co má být revidováno, a o zdrojích; autor vytváří a opravuje pracovní produkt; moderátor zajišťuje efektivní průběh revizních schůzek; vedoucí revize přebírá celkovou odpovědnost za revizi a její organizaci.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"}},{"id":"UC-3-12","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Uvažujte následující typy revizí (1–4) a jejich vlastnosti (A–D):<\/p><p>1. Technická revize<\/p><p>2. Předvedení (walkthrough)<\/p><p>3. Inspekce<\/p><p>4. Neformální revize<\/p><p>A. Nejformálnější typ revize; jejím hlavním cílem je nacházet maximální počet anomálií.<\/p><p>B. Neřídí se definovaným procesem a jejím hlavním cílem je odhalování anomálií.<\/p><p>C. Provádějí ji odborně kvalifikovaní revidující a vede ji moderátor.<\/p><p>D. Vede ji autor a může sloužit mnoha cílům, jako je hodnocení kvality a budování důvěry v pracovní produkt.<\/p><p>Která z následujících možností NEJLÉPE přiřazuje typy revizí k vlastnostem?<\/p>","m":["<p>1C, 2D, 3A, 4B<\/p>","<p>1D, 2C, 3A, 4B<\/p>","<p>1A, 2D, 3C, 4B<\/p>","<p>1B, 2D, 3C, 4A<\/p>"],"ok":[0],"vys":{"a":"Je správně. Technická revize – C, předvedení – D, inspekce – A, neformální revize – B.","b":"Není správně. Technickou revizi nevede autor a předvedení nevede moderátor.","c":"Není správně. Nejformálnějším typem je inspekce, nikoli technická revize.","d":"Není správně. Technická revize se řídí procesem a neformální revize není nejformálnějším typem."},"obecne":"Sylabus 3.2.4: neformální revize se neřídí definovaným procesem; předvedení vede autor; technickou revizi provádějí odborně kvalifikovaní revidující a vede ji moderátor; inspekce je nejformálnějším typem s cílem nalézt maximální počet anomálií.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UC-3-13","n":null,"lo":"FL-3.1.2","k":"K2","k3":true,"vyber":1,"q":"<p>Jsou dána následující tvrzení o statickém testování:<\/p><p>A. Odhaluje defekty v nejranějších fázích SDLC.<\/p><p>B. Činí dynamické testování méně náročným.<\/p><p>C. Identifikuje defekty, které nelze odhalit dynamickým testováním.<\/p><p>D. Odhaluje selhání, ke kterým dochází za běhu systému.<\/p><p>E. U systémů kritických z hlediska bezpečnosti má menší hodnotu, protože dynamické testování je při hledání defektů účinnější.<\/p><p>Která DVĚ tvrzení jsou NEJPŘESNĚJŠÍ?<\/p>","m":["<p>A a C<\/p>","<p>A a B<\/p>","<p>B a D<\/p>","<p>B a C<\/p>"],"ok":[0],"vys":{"a":"Je správně. Statické testování odhaluje defekty v nejranějších fázích SDLC (A) i defekty, které dynamickým testováním zjistit nelze (C).","b":"Není správně. Tvrzení B sylabus neuvádí; statické testování dynamické testování nenahrazuje ani nezjednodušuje.","c":"Není správně. B neplatí a selhání za běhu (D) odhaluje dynamické testování.","d":"Není správně. C platí, ale B ne."},"obecne":"Sylabus 3.1.2: statické testování může odhalit defekty v nejranějších fázích SDLC a také defekty, které nelze zjistit dynamickým testováním (např. nedosažitelný kód nebo defekty v nespustitelných pracovních produktech).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"}},{"id":"UC-3-14","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících tvrzení o včasném návrhu testů jsou <strong>PRAVDIVÁ<\/strong>?<\/p><p>1. Oprava defektů nalezených při včasném návrhu testů je dražší.<\/p><p>2. Včasný návrh testů může odhalit defekty.<\/p><p>3. Včasný návrh testů může vést ke změnám požadavků.<\/p><p>4. Včasný návrh testů vyžaduje větší pracnost.<\/p>","m":["<p>1 a 3<\/p>","<p>1 a 4 <\/p>","<p>3 a 4<\/p>","<p>2 a 3 <\/p>"],"ok":[3],"vys":{"a":"Není správně. Tvrzení 1 je nepravdivé – defekty nalezené brzy jsou levnější na opravu.","b":"Není správně. Tvrzení 1 i 4 jsou nepravdivá.","c":"Není správně. Tvrzení 4 je nepravdivé – včasné testování pracnost spíše šetří.","d":"Je správně. Včasný návrh testů může odhalit defekty (2), např. v požadavcích, a vést tak k jejich změnám (3)."},"obecne":"Sylabus 1.3 (princip Včasné testování šetří čas a peníze) a 3.1.2: defekty odstraněné v rané fázi nezpůsobí následné defekty v odvozených pracovních produktech, takže celkové náklady klesají. Návrh testů nad požadavky v nich často odhalí defekty, které vedou ke změnám požadavků.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UC-3-16","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Jaký je hlavní rozdíl mezi předvedením (walkthrough) a inspekcí?<\/p>","m":["<p>Při inspekci autor není přítomen, zatímco při předvedení ano<\/p>","<p>Předvedení vede autor, zatímco inspekci autor vést nemůže<\/p>","<p>Inspekci vede moderátor, zatímco předvedení nemá žádného vedoucího<\/p>","<p>Inspekci vede autor, zatímco předvedení vede vyškolený moderátor<\/p>"],"ok":[1],"vys":{"a":"Není správně. Autor se inspekce účastní, jen ji nemůže vést.","b":"Je správně. Předvedení vede autor, zatímco při inspekci nemůže autor vystupovat jako vedoucí revize ani zapisovatel.","c":"Není správně. Předvedení vede autor, vedoucího tedy má.","d":"Není správně. Je to naopak – předvedení vede autor a inspekci autor vést nemůže."},"obecne":"Sylabus 3.2.4: předvedení je vedené autorem; u inspekce nemůže autor vystupovat jako vedoucí revize nebo zapisovatel.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UC-3-18","n":null,"lo":"FL-3.2.5","k":"K1","k3":true,"vyber":1,"q":"<p>Co <strong>NEJPRAVDĚPODOBNĚJI<\/strong> přispěje k úspěšné revizi pracovního produktu?<\/p>","m":["<p>Otevření revize komukoli, kdo se chce zúčastnit<\/p>","<p>Provázání výsledků revize s hodnocením výkonu účastníků<\/p>","<p>Definování jasných cílů procesu revize<\/p>","<p>Zaměření se pouze na identifikaci kritických defektů<\/p>"],"ok":[2],"vys":{"a":"Není správně. Typ revize a účastníci se mají volit podle cílů a kontextu, ne otevřením komukoli.","b":"Není správně. Hodnocení účastníků revize nesmí být jejím cílem; hodnotí se pracovní produkt.","c":"Je správně. Jasné cíle a měřitelná výstupní kritéria jsou faktorem úspěchu revize.","d":"Není správně. Revize má odhalovat anomálie obecně, ne pouze kritické defekty."},"obecne":"Sylabus 3.2.5: faktorem úspěchu je definování jasných cílů a měřitelných výstupních kritérií; hodnocení účastníků by nikdy nemělo být cílem revize.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.5","nazev":"Faktory úspěchu při revizi","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-pet-faktory-uspechu-pri-revizi"}},{"id":"UC-3-19","n":null,"lo":"FL-3.1.2","k":"K2","k3":true,"vyber":1,"q":"<p>Co NEJPRAVDĚPODOBNĚJI odhalí defekty v rané fázi SDLC?<\/p>","m":["<p>Systémové testování<\/p>","<p>Uživatelské akceptační testování<\/p>","<p>Validační testování hotového systému<\/p>","<p>Statická analýza<\/p>"],"ok":[3],"vys":{"a":"Není správně. Systémové testování probíhá až po integraci celého systému.","b":"Není správně. Uživatelské akceptační testování probíhá obvykle ke konci vývoje.","c":"Není správně. Validace hotového systému probíhá až po jeho dokončení.","d":"Je správně. Statická analýza nevyžaduje spuštění ani testovací případy, a lze ji proto použít velmi brzy, např. hned při psaní kódu."},"obecne":"Sylabus 3.1.2: statické testování může odhalit defekty v nejranějších fázích SDLC, čímž naplňuje princip včasného testování. Statická analýza navíc nevyžaduje tvorbu testovacích případů a často je součástí průběžné integrace.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"}},{"id":"UC-3-22","n":null,"lo":"FL-3.2.3","k":"K1","k3":true,"vyber":1,"q":"<p>Kdo při formální revizi přebírá celkovou odpovědnost za revizi?<\/p>","m":["<p>Vedoucí revize<\/p>","<p>Moderátor (facilitátor)<\/p>","<p>Autor<\/p>","<p>Revidující<\/p>"],"ok":[0],"vys":{"a":"Je správně. Vedoucí revize přebírá celkovou odpovědnost za revizi, rozhoduje o zapojených osobách a organizuje, kdy a kde se revize koná.","b":"Není správně. Moderátor zajišťuje efektivní průběh revizních schůzek.","c":"Není správně. Autor vytváří a opravuje revidovaný pracovní produkt.","d":"Není správně. Revidující provádí revizi."},"obecne":"Sylabus 3.2.3: vedoucí revize přebírá celkovou odpovědnost za revizi (např. rozhodování o tom, kdo do ní bude zapojen) a organizaci toho, kdy a kde se bude revize konat.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"}},{"id":"UC-3-23","n":null,"lo":"FL-3.2.3","k":"K1","k3":true,"vyber":1,"q":"<p>Kdo při formální revizi odpovídá za identifikaci anomálií (potenciálních defektů) v revidovaném pracovním produktu?<\/p>","m":["<p>Moderátor<\/p>","<p>Revidující<\/p>","<p>Manažer<\/p>","<p>Autor<\/p>"],"ok":[1],"vys":{"a":"Není správně. Moderátor zajišťuje efektivní průběh revizních schůzek.","b":"Je správně. Revidující provádí revizi a zaznamenává zjištěné anomálie, doporučení a otázky.","c":"Není správně. Manažer rozhoduje, co se bude revidovat, a přiděluje zdroje.","d":"Není správně. Autor vytváří a opravuje revidovaný pracovní produkt."},"obecne":"Sylabus 3.2.3 a 3.2.2: revidující provádí revizi – individuálně posuzuje kvalitu pracovního produktu a identifikuje a zaznamenává anomálie. Revidujícím může být člen projektu, odborník na danou problematiku nebo jiná zainteresovaná strana.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"}},{"id":"UC-3-24","n":null,"lo":"FL-3.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která činnost procesu revize se zaměřuje na zajištění toho, aby měli všichni účastníci přístup k revidovanému pracovnímu produktu?<\/p>","m":["<p>Komunikace a analýza<\/p>","<p>Plánování<\/p>","<p>Zahájení revize<\/p>","<p>Individuální revize<\/p>"],"ok":[2],"vys":{"a":"Není správně. Při komunikaci a analýze se diskutují zjištěné anomálie a rozhoduje se o nich.","b":"Není správně. Při plánování se stanoví rozsah, účel, výstupní kritéria, pracnost a časový rámec revize.","c":"Je správně. Při zahájení revize se zajistí, aby měl každý účastník přístup k pracovnímu produktu, rozuměl své roli a obdržel vše potřebné.","d":"Není správně. Při individuální revizi revidující posuzují pracovní produkt a zaznamenávají anomálie."},"obecne":"Sylabus 3.2.2: cílem zahájení revize je zajistit, aby bylo vše a všichni připraveni k revizi – každý účastník má přístup k revidovanému pracovnímu produktu, rozumí své roli a odpovědnostem a obdržel vše potřebné.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.2","nazev":"Činnosti procesu revize","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-dva-cinnosti-procesu-revize"}},{"id":"UC-3-25","n":null,"lo":"FL-3.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>V které činnosti revize revidující obvykle zaznamenávají svá doporučení ke zlepšení a případné otázky?<\/p>","m":["<p>Komunikace a analýza<\/p>","<p>Zahájení revize<\/p>","<p>Plánování<\/p>","<p>Individuální revize<\/p>"],"ok":[3],"vys":{"a":"Není správně. Při komunikaci a analýze se již zaznamenané anomálie analyzují a diskutují.","b":"Není správně. Zahájení revize zajišťuje připravenost účastníků a přístup k pracovnímu produktu.","c":"Není správně. Při plánování se stanoví rozsah a výstupní kritéria revize.","d":"Je správně. Při individuální revizi revidující zaznamenává všechny zjištěné anomálie, doporučení a otázky."},"obecne":"Sylabus 3.2.2: při individuální revizi každý revidující posuzuje kvalitu pracovního produktu pomocí jedné nebo více technik revize a zaznamenává všechny zjištěné anomálie, doporučení a otázky.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.2","nazev":"Činnosti procesu revize","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-dva-cinnosti-procesu-revize"}},{"id":"UC-3-28","n":null,"lo":"FL-3.2.5","k":"K1","k3":true,"vyber":1,"q":"<p>Který z následujících faktorů <strong>NENÍ<\/strong> faktorem úspěchu revizí?<\/p>","m":["<p>Hodnocení výkonu účastníků během revize.<\/p>","<p>Definování jasných cílů a měřitelných výstupních kritérií.<\/p>","<p>Provádění revizí po malých částech.<\/p>","<p>Poskytování zpětné vazby z revizí zainteresovaným stranám a autorům.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Hodnocení účastníků by nikdy nemělo být cílem revize; hodnotí se pracovní produkt.","b":"Není správně. Jasné cíle a měřitelná výstupní kritéria jsou faktorem úspěchu.","c":"Není správně. Revize po malých částech pomáhá revidujícím udržet koncentraci.","d":"Není správně. Zpětná vazba zainteresovaným stranám a autorům je faktorem úspěchu."},"obecne":"Sylabus 3.2.5: faktory úspěchu zahrnují jasné cíle a měřitelná výstupní kritéria, revize po malých částech a zpětnou vazbu zainteresovaným stranám a autorům. Hodnocení účastníků by nikdy nemělo být cílem revize.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.5","nazev":"Faktory úspěchu při revizi","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-pet-faktory-uspechu-pri-revizi"}},{"id":"UC-3-29","n":null,"lo":"FL-3.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností je výhodou včasné a časté zpětné vazby od zainteresovaných stran?<\/p>","m":["<p>Menší potřeba revizí kódu díky jasným požadavkům<\/p>","<p>Předcházení nedorozuměním ohledně požadavků<\/p>","<p>Včasné přisouzení viny za nedorozumění zainteresovaným stranám<\/p>","<p>Vývojový tým potřebuje méně technických znalostí<\/p>"],"ok":[1],"vys":{"a":"Není správně. Zpětná vazba od zainteresovaných stran revize kódu nenahrazuje.","b":"Je správně. Častá zpětná vazba může zabránit nedorozuměním při definici požadavků.","c":"Není správně. Vzájemné obviňování je naopak riziko, kterému zpětná vazba předchází.","d":"Není správně. Zpětná vazba nesnižuje potřebné technické znalosti týmu."},"obecne":"Sylabus 3.2.1: častá zpětná vazba od zainteresovaných stran během SDLC může zabránit nedorozuměním při definici požadavků a zajistit, aby změny požadavků byly správně a včas pochopeny a implementovány.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"3.2.1","nazev":"Výhody včasné a časté zpětné vazby od zainteresovaných stran","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-jedna-vyhody-vcasne-a-caste-zpetne-vazby-od-zainteresovanych-stran"}},{"id":"UC-4-16","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Textové pole přijímá řetězce číslic o délce nejméně 6 a nejvýše 18 znaků.<\/p><p>K otestování pole byly použity vstupy s následujícím počtem znaků:<\/p><ul><li>6 znaků<\/li><li>7 znaků<\/li><li>18 znaků<\/li><li>19 znaků<\/li><li>20 znaků<\/li><\/ul><p>Je použita tříhodnotová analýza hraničních hodnot. Uvažujte pouze hraniční hodnoty na přechodech mezi platnou třídou a sousedními neplatnými třídami.<\/p><p>Jakého pokrytí hraničních hodnot tyto vstupy dosahují?<\/p>","m":["<p>75 %<\/p>","<p>50 %<\/p>","<p>62,5 %<\/p>","<p>66,7 %<\/p>"],"ok":[2],"vys":{"a":"Není správně. 75 % by odpovídalo 6 pokrytým položkám z 8; pokryto je jich jen 5.","b":"Není správně. Položek pokrytí je 8 a vstupy pokrývají 5 z nich, nikoli 4.","c":"Je správně. Položky pokrytí jsou 4, 5, 6, 7, 17, 18, 19, 20; pokryty jsou 6, 7, 18, 19, 20, tedy 5/8 = 62,5 %.","d":"Není správně. 66,7 % (4 ze 6) by vyšlo, kdybychom uvažovali jen hranice 6 a 18 a jejich sousedy; hraničními hodnotami jsou však také 5 a 19."},"obecne":"Sylabus 4.2.2: hraničními hodnotami jsou 5 a 6 (dolní přechod) a 18 a 19 (horní přechod). Při tříhodnotové BVA jsou položkami pokrytí každá hraniční hodnota a oba její sousedé: 4, 5, 6, 7 a 17, 18, 19, 20 – celkem 8 hodnot. Vstupy pokrývají 6, 7, 18, 19 a 20, tedy 5/8 = 62,5 %.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-17","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Která z následujících sad testovacích dat dosáhne při použití tříhodnotové analýzy hraničních hodnot 100% pokrytí pro následující řádek kódu (x je celé číslo)?<\/p><p><code>if (x &gt;= 10) then y := 0<\/code><\/p>","m":["<p>7, 8, 9<\/p>","<p>7, 8, 10, 11<\/p>","<p>9, 10, 11, 12<\/p>","<p>8, 9, 10, 11<\/p>"],"ok":[3],"vys":{"a":"Není správně. Chybí hodnoty 10 a 11, hranice 10 tedy není pokryta.","b":"Není správně. Chybí hraniční hodnota 9; hodnota 7 položkou pokrytí není.","c":"Není správně. Chybí hodnota 8 (soused hraniční hodnoty 9); hodnota 12 položkou pokrytí není.","d":"Je správně. Hraniční hodnoty jsou 9 a 10; pro 9 testujeme 8, 9, 10 a pro 10 testujeme 9, 10, 11 – dohromady 8, 9, 10, 11."},"obecne":"<p>Je-li x větší nebo rovno 10, proměnné y se přiřadí nula. Je-li x menší než 10, proměnné y se nula nepřiřadí.<\/p><p>Hraničními hodnotami systému jsou tedy 9 a&nbsp;10.<\/p><p>Pro 9 budeme testovat hodnoty 8, 9, 10. Pro 10 budeme testovat hodnoty 9, 10, 11. Výsledná sada je tedy 8, 9, 10, 11.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-18","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Student může získat 0 až 100 bodů. Počet bodů je celé číslo. Body se převádějí na známky takto:<\/p><ul><li>více než 90 bodů: A<\/li><li>více než 75 bodů: B<\/li><li>více než 60 bodů: C<\/li><li>více než 49 bodů: D<\/li><li>jinak: F<\/li><\/ul><p>Systém neumožňuje zadat hodnotu mimo rozsah 0–100. Je použita tříhodnotová analýza hraničních hodnot.<\/p><p>Kolik různých hodnot je potřeba otestovat k dosažení 100% pokrytí hraničních hodnot?<\/p>","m":["<p>18 hodnot<\/p>","<p>20 hodnot<\/p>","<p>22 hodnot<\/p>","<p>24 hodnot<\/p>"],"ok":[1],"vys":{"a":"Není správně. 18 hodnot vynechává část sousedních hodnot; správný počet je 20.","b":"Je správně. Hraniční hodnoty jsou 0, 49, 50, 60, 61, 75, 76, 90, 91, 100; sjednocení hraničních hodnot a jejich zadatelných sousedů dává 20 různých hodnot.","c":"Není správně. 22 hodnot by vyšlo, kdyby šlo zadat i −1 a 101; systém však hodnoty mimo rozsah 0–100 zadat neumožňuje.","d":"Není správně. 24 hodnot by vyšlo při počítání některých hodnot vícekrát; každá hodnota se testuje jen jednou."},"obecne":"Sylabus 4.2.2: třídy jsou 0–49 (F), 50–60 (D), 61–75 (C), 76–90 (B) a 91–100 (A). Položky pokrytí tříhodnotové BVA: 0, 1 | 48, 49, 50, 51 | 59, 60, 61, 62 | 74, 75, 76, 77 | 89, 90, 91, 92 | 99, 100 – celkem 20 různých hodnot (−1 a 101 nelze zadat).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-19","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Systém přijímá rok narození (celé číslo). Platné roky jsou 1900 až 2020 včetně.<\/p><p>Která z následujících možností je minimální sadou testovacích hodnot, která dosáhne 100% pokrytí dvouhodnotovou analýzou hraničních hodnot i 100% pokrytí tříd ekvivalence?<\/p>","m":["<p>1900, 2003, 2020<\/p>","<p>1899, 1900, 2020, 2021<\/p>","<p>1900, 2020<\/p>","<p>1899, 1900, 2003, 2020, 2021<\/p>"],"ok":[1],"vys":{"a":"Není správně. Chybí neplatné třídy a hraniční hodnoty 1899 a 2021; hodnota 2003 je navíc nadbytečná.","b":"Je správně. 1899, 1900, 2020 a 2021 jsou všechny hraniční hodnoty a současně pokrývají všechny tři třídy ekvivalence.","c":"Není správně. Hodnoty 1900 a 2020 pokrývají jen platnou třídu; chybí neplatné třídy i hraniční hodnoty 1899 a 2021.","d":"Není správně. Sada dosahuje obou pokrytí, ale není minimální – hodnota 2003 je nadbytečná."},"obecne":"<p>Pokrytí všech hraničních hodnot zaručuje pokrytí všech tříd ekvivalence. V tomto příkladu máme tři třídy:<br>1 – Méně než 1900 – „pokryto hodnotou 1899“<\/p><p>2 – 1900 až 2020 – „pokryto hodnotami 1900 a 2020“<\/p><p>3 – Více než 2020 – „pokryto hodnotou 2021“<\/p><p><br><\/p><p>Pokud tedy dosáhneme 100% pokrytí analýzou hraničních hodnot, nepotřebujeme k dosažení 100% pokrytí tříd ekvivalence žádné další testovací případy.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-20","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Část programu zasílá uživateli upozornění podle počasí. Teplota se měří ve stupních Celsia, zaokrouhlená na celé stupně. Program funguje takto:<\/p><ul><li>teplota nižší než 20 stupňů: upozornění „chladno“,<\/li><li>teplota 20 až 30 stupňů včetně: „teplo“,<\/li><li>teplota vyšší než 30 stupňů: „horko“.<\/li><\/ul><p>Je použita tříhodnotová analýza hraničních hodnot. Jaký je minimální počet testovacích vstupů, který dosáhne 100% pokrytí?<\/p>","m":["<p>4<\/p>","<p>6<\/p>","<p>8<\/p>","<p>10<\/p>"],"ok":[2],"vys":{"a":"Není správně. 4 vstupy (19, 20, 30, 31) stačí pro dvouhodnotovou BVA, ne pro tříhodnotovou.","b":"Není správně. 6 vstupů nepokryje všechny sousedy čtyř hraničních hodnot.","c":"Je správně. Hraniční hodnoty jsou 19, 20, 30, 31; s jejich sousedy dostaneme 18, 19, 20, 21, 29, 30, 31, 32 – celkem 8 různých hodnot.","d":"Není správně. 10 vstupů by vyšlo jen při počítání duplicitních hodnot; každá hodnota se testuje jednou."},"obecne":"<p>Máme tři třídy ekvivalence:<br><br>Třída 1:&nbsp;pod 20<\/p><p>Třída 2:&nbsp;mezi 20 a 30<br>Třída 3:&nbsp;nad 30<\/p><p><br><\/p><p>Hraniční hodnoty, které je třeba otestovat, jsou tedy:&nbsp;19, 20, 30, 31<br><br>Pro 19 testujeme hodnoty:&nbsp;18, 19, 20<\/p><p>Pro 20 testujeme hodnoty: 19, 20, 21<\/p><p>Pro 30 testujeme hodnoty:&nbsp;29, 30, 31<\/p><p>Pro 31 testujeme hodnoty:&nbsp;30, 31, 32<\/p><p>Celkem tedy dostáváme 8 hodnot:&nbsp;18, 19, 20, 21, 29, 30, 31, 32<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-21","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Systém má 6 stavů (S1 až S6), počátečním stavem je S1. Jeho stavový diagram obsahuje právě těchto 8 platných přechodů:<\/p><table><tr><th>Ze stavu<\/th><th>Do stavu<\/th><\/tr><tr><td>S1<\/td><td>S2<\/td><\/tr><tr><td>S1<\/td><td>S4<\/td><\/tr><tr><td>S2<\/td><td>S3<\/td><\/tr><tr><td>S3<\/td><td>S4<\/td><\/tr><tr><td>S4<\/td><td>S2<\/td><\/tr><tr><td>S4<\/td><td>S5<\/td><\/tr><tr><td>S5<\/td><td>S3<\/td><\/tr><tr><td>S5<\/td><td>S6<\/td><\/tr><\/table><p>Byly provedeny tyto testovací případy:<\/p><ol type=\"i\"><li>S1 → S2 → S3 → S4<\/li><li>S1 → S4 → S5 → S6<\/li><li>S1 → S4 → S5 → S3 → S4<\/li><li>S1 → S4 → S2 → S3 → S4<\/li><\/ol><p>Které z následujících tvrzení je PRAVDIVÉ?<\/p>","m":["<p>Testovací případy i a iii dosahují 100% pokrytí všech stavů, zatímco ii a iv dosahují 66,7% pokrytí platných přechodů.<\/p>","<p>Testovací případy i a iv dosahují 100% pokrytí platných přechodů, zatímco ii a iii dosahují 100% pokrytí všech přechodů.<\/p>","<p>Testovací případy i a ii dosahují 100% pokrytí všech přechodů, zatímco iii a iv dosahují 33,3% pokrytí všech stavů.<\/p>","<p>Testovací případy i a ii dosahují 100% pokrytí všech stavů, zatímco iii a iv dosahují 75% pokrytí platných přechodů.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Případy i a iii nenavštíví stav S6; případy ii a iv pokrývají 6 z 8 přechodů, tedy 75 %.","b":"Není správně. Případy i a iv pokrývají jen 5 z 8 platných přechodů (chybí S4→S5, S5→S3, S5→S6); pokrytí všech přechodů navíc vyžaduje i testy neplatných přechodů.","c":"Není správně. Případy i a ii netestují žádné neplatné přechody, a nedosahují tedy pokrytí všech přechodů; iii a iv navštíví 5 z 6 stavů (83,3 %).","d":"Je správně. Případy i a ii navštíví stavy S1 až S6 (6/6); případy iii a iv pokrývají přechody S1→S4, S4→S5, S5→S3, S3→S4, S4→S2, S2→S3, tedy 6/8 = 75 %."},"obecne":"Sylabus 4.2.4: u pokrytí všech stavů jsou položkami pokrytí stavy, u pokrytí platných přechodů platné přechody a u pokrytí všech přechodů platné i neplatné přechody. Případy i a ii navštíví všech 6 stavů; případy iii a iv pokrývají 6 z 8 platných přechodů (chybí S1→S2 a S5→S6), tj. 75 %.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UC-4-22","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Stavový diagram systému obsahuje právě těchto 5 platných přechodů:<\/p><table><tr><th>Ze stavu<\/th><th>Do stavu<\/th><\/tr><tr><td>S1<\/td><td>S2<\/td><\/tr><tr><td>S1<\/td><td>S5<\/td><\/tr><tr><td>S5<\/td><td>S1<\/td><\/tr><tr><td>S2<\/td><td>S3<\/td><\/tr><tr><td>S2<\/td><td>S4<\/td><\/tr><\/table><p>Stavy S3 a S4 jsou koncové (nevede z nich žádný přechod). Testovací případ může začínat v libovolném stavu a končí v koncovém stavu.<\/p><p>Které z následujících tvrzení je PRAVDIVÉ?<\/p>","m":["<p>MINIMÁLNÍ počet testovacích případů pro pokrytí všech platných přechodů je 2 při začátku ve stavu S1.<\/p>","<p>MINIMÁLNÍ počet testovacích případů pro pokrytí všech stavů je 2 při začátku ve stavu S2.<\/p>","<p>MINIMÁLNÍ počet testovacích případů pro pokrytí všech platných přechodů je 2 při začátku ve stavu S2.<\/p>","<p>MINIMÁLNÍ počet testovacích případů pro pokrytí všech platných přechodů je 1 při začátku ve stavu S1.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Např. S1→S5→S1→S2→S4 a S1→S2→S3 pokryjí všech 5 platných přechodů; méně případů nestačí, protože existují dva koncové stavy.","b":"Není správně. Ze stavu S2 nelze dosáhnout stavů S1 a S5, takže pokrytí všech stavů při začátku v S2 dosáhnout nelze.","c":"Není správně. Ze stavu S2 se nelze dostat do S1 ani S5, přechody S1→S2, S1→S5 a S5→S1 by zůstaly nepokryté.","d":"Není správně. Stavy S3 a S4 jsou koncové, jeden testovací případ proto nemůže pokrýt oba přechody S2→S3 i S2→S4."},"obecne":"Sylabus 4.2.4: při pokrytí platných přechodů musí testovací případy provést každý platný přechod. Začneme-li v S1, stačí dva případy (S1→S5→S1→S2→S4 a S1→S2→S3). Jeden případ nestačí, protože S3 a S4 jsou koncové stavy; ze stavu S2 se nelze vrátit do S1 ani S5.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UC-4-23","n":null,"lo":"FL-4.5.3","k":"K3","k3":false,"vyber":1,"q":"<p>Které z následujících tvrzení o vývoji řízeném akceptačními testy (ATDD) je PRAVDIVÉ?<\/p>","m":["<p>Testovací případy vytvářejí především testeři, bez účasti dalších členů týmu<\/p>","<p>Testovací případy by měly být formulovány srozumitelně pro zainteresované strany<\/p>","<p>Prvním krokem je napsat testovací případy a teprve poté analyzovat uživatelský scénář<\/p>","<p>Testovací případy se vytvářejí až po dokončení implementace uživatelského scénáře<\/p>"],"ok":[1],"vys":{"a":"Není správně. Testy vytvářejí členové týmu s různými perspektivami – zákazníci, vývojáři a testeři.","b":"Je správně. Testovací případy mají být vyjádřeny tak, aby jim zainteresované strany rozuměly, typicky přirozeným jazykem.","c":"Není správně. Prvním krokem je specifikační workshop, kde tým analyzuje uživatelský scénář a jeho akceptační kritéria; testy se píší až potom.","d":"Není správně. V ATDD se testy vytvářejí před implementací uživatelského scénáře."},"obecne":"Sylabus 4.5.3: ATDD je přístup typu test first – testy se vytvářejí před implementací uživatelského scénáře, a to členy týmu s různými perspektivami. Prvním krokem je specifikační workshop. Testovací případy se zapisují tak, aby byly srozumitelné pro zainteresované strany.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UC-4-24","n":null,"lo":"FL-4.5.2","k":"K2","k3":true,"vyber":1,"q":"<p>Jaký formát byl použit k zápisu tohoto akceptačního kritéria?<\/p><p><em>Given: Uživatel je přihlášen.<br>When: Uživatel přejde na stránku „Můj účet“ a klikne na tlačítko „Upravit profil“.<br>Then: Uživatel může aktualizovat své osobní údaje a uložit změny.<\/em><\/p>","m":["<p>Orientovaný na pravidla<\/p>","<p>Orientovaný na funkce<\/p>","<p>Orientovaný na scénáře<\/p>","<p>Orientovaný na data<\/p>"],"ok":[2],"vys":{"a":"Není správně. Formát orientovaný na pravidla má podobu verifikačního seznamu s odrážkami nebo tabulky mapování vstupů a výstupů.","b":"Není správně. Sylabus formát „orientovaný na funkce“ nezná.","c":"Je správně. Formát Given/When/Then (za předpokladu – když – pak), používaný v BDD, je typický pro akceptační kritéria orientovaná na scénáře.","d":"Není správně. Sylabus formát „orientovaný na data“ nezná."},"obecne":"<p>Existuje několik způsobů, jak napsat akceptační kritéria pro uživatelský scénář. Dva nejběžnější formáty jsou:<\/p><ul><li><p><strong>orientovaný na scénáře (např. formát Given/When/Then používaný v BDD)<\/strong><\/p><\/li><li><p>orientovaný na pravidla (např. verifikační seznam s odrážkami nebo tabulka s mapováním vstupů a výstupů)<\/p><\/li><\/ul>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"}},{"id":"UC-4-25","n":null,"lo":"FL-4.5.2","k":"K2","k3":true,"vyber":1,"q":"<p>Mějme následující akceptační kritéria:<\/p><ul><li><p>Uživatel by měl mít k videu přístup z webových stránek, a to buď přes přímý odkaz, nebo procházením knihovny videí na webu.<\/p><\/li><li><p>Video by mělo být přehratelné na řadě zařízení a prohlížečů bez nutnosti instalovat další zásuvné moduly nebo software.<\/p><\/li><li><p>Přehrávač videa by měl mít základní ovládací prvky přehrávání, jako je přehrát, pozastavit a posun.<\/p><\/li><li><p>Přehrávač videa by měl podporovat režim celé obrazovky, aby si uživatel mohl video prohlédnout ve větší velikosti.<\/p><\/li><\/ul><p>Jaký formát byl použit k zápisu těchto kritérií?<\/p>","m":["<p>Orientovaný na data<\/p>","<p>Orientovaný na scénáře<\/p>","<p>Orientovaný na funkce<\/p>","<p>Orientovaný na pravidla<\/p>"],"ok":[3],"vys":{"a":"Není správně. Sylabus formát „orientovaný na data“ nezná.","b":"Není správně. Formát orientovaný na scénáře používá posloupnost Given/When/Then; zde jde o seznam pravidel.","c":"Není správně. Sylabus formát „orientovaný na funkce“ nezná.","d":"Je správně. Kritéria tvoří verifikační seznam s odrážkami, což je typický formát orientovaný na pravidla."},"obecne":"<p>Existuje několik způsobů, jak napsat akceptační kritéria pro uživatelský scénář. Dva nejběžnější formáty jsou:<\/p><ul><li><p>orientovaný na scénáře (např. formát Given/When/Then používaný v BDD)<\/p><\/li><li><p><strong>orientovaný na pravidla (např. verifikační seznam s odrážkami nebo tabulka s mapováním vstupů a výstupů)<\/strong><\/p><\/li><\/ul>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"}},{"id":"UC-4-26","n":null,"lo":"FL-4.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Tester testuje proces dokončení objednávky na webu e-shopu. Pokusí se pokračovat s prázdným nákupním košíkem a systém mu neočekávaně umožní přejít na platební stránku.<\/p><p>Tento test navrhl proto, že si vzpomněl na dřívější projekty, v nichž vývojáři zapomněli implementovat kontrolu prázdného košíku.<\/p><p>Jakou techniku testování tester použil?<\/p>","m":["<p>Odhadování chyb<\/p>","<p>Testování založené na kontrolních seznamech<\/p>","<p>Testování přechodů stavů<\/p>","<p>Průzkumné testování<\/p>"],"ok":[0],"vys":{"a":"Je správně. Test vychází ze znalosti typických chyb vývojářů z minulosti, což je podstata odhadování chyb.","b":"Není správně. Tester nepostupoval podle kontrolního seznamu testovacích podmínek.","c":"Není správně. Test nebyl odvozen ze stavového modelu systému, ale ze zkušenosti testera.","d":"Není správně. U průzkumného testování se testy navrhují, provádějí a vyhodnocují současně s učením o testovaném objektu; zde tester cíleně využil znalost typické chyby vývojářů."},"obecne":"Sylabus 4.4.1: odhadování chyb předvídá výskyt chyb, defektů a selhání na základě znalostí testera, např. typických chyb vývojářů a defektů, které z nich vznikají. Tester zde cíleně otestoval situaci, o níž ví, že ji vývojáři často opomíjejí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"}},{"id":"UC-4-27","n":null,"lo":"FL-4.3.3","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o technikách testování bílé skříňky NENÍ správné?<\/p>","m":["<p>Pokud software neimplementuje některý požadavek, testování bílé skříňky nemusí tento defekt opomenutí odhalit<\/p>","<p>Metriky pokrytí bílé skříňky poskytují subjektivní měření pokrytí a informace pro vytváření dalších testů<\/p>","<p>Při testování je zohledněna celá implementace softwaru<\/p>","<p>Detekce defektů je usnadněna i tehdy, když je specifikace vágní, zastaralá nebo neúplná<\/p>"],"ok":[1],"vys":{"a":"Není správně. Toto tvrzení platí: slabinou testování bílé skříňky je, že nemusí odhalit defekty při opomenutí implementace požadavku.","b":"Je správně. Toto tvrzení neplatí: měření pokrytí bílé skříňky je objektivní, nikoli subjektivní.","c":"Není správně. Toto tvrzení platí: při testování bílé skříňky je zohledněna samotná implementace softwaru.","d":"Není správně. Toto tvrzení platí: protože testy vycházejí z implementace, usnadňuje to detekci defektů i při vágní, zastaralé nebo neúplné specifikaci."},"obecne":"<p>Silnou stránkou technik testování bílé skříňky je, <strong>že při testování je zohledněna samotná implementace softwaru<\/strong>, což <strong>usnadňuje detekci defektů v případech, kdy je jeho specifikace vágní, zastaralá nebo neúplná<\/strong>. Slabinou je fakt, že <strong>nemusí odhalit defekty při opomenutí implementace jednoho nebo více požadavků<\/strong>. <\/p><p><br><\/p><p>Výsledky testování s využitím technik bílé skříňky poskytují <strong>objektivní<\/strong> (nikoli subjektivní) měření pokrytí a také nezbytné informace umožňující vytváření dalších testů s cílem zvyšování tohoto pokrytí a tím i následné zvyšování důvěry v kód.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"}},{"id":"UC-4-28","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Testujete systém, který hodnotí písemné zkoušky a přiděluje známky. Systém je v rané fázi vývoje a validace vstupních hodnot zatím není doplněna. Počet bodů je celé číslo a známky se přidělují takto:<\/p><ul><li>1–49 bodů: F<\/li><li>50–59 bodů: D−<\/li><li>60–69 bodů: D<\/li><li>70–79 bodů: C<\/li><li>80–89 bodů: B<\/li><li>90–100 bodů: A<\/li><\/ul><p>Kolik testovacích případů NEJMÉNĚ potřebujete k dosažení 100% pokrytí rozdělením tříd ekvivalence (platných i neplatných tříd)?<\/p>","m":["<p>8<\/p>","<p>6<\/p>","<p>10<\/p>","<p>12<\/p>"],"ok":[0],"vys":{"a":"Je správně. Existuje 6 platných tříd (známky F až A) a 2 neplatné třídy (méně než 1 a více než 100), z každé stačí jedna hodnota – celkem 8.","b":"Není správně. 6 testovacích případů pokryje jen platné třídy; chybí neplatné třídy pod 1 a nad 100.","c":"Není správně. 10 testovacích případů je víc než minimum; z každé třídy stačí jedna hodnota.","d":"Není správně. 12 testovacích případů odpovídá spíše dvěma hodnotám z každé platné třídy, což rozdělení tříd ekvivalence nevyžaduje."},"obecne":"<p>Abychom při použití rozdělení tříd ekvivalence určili počet testovacích případů potřebných pro minimální pokrytí, identifikujeme jednotlivé třídy ekvivalence podle zadaných rozsahů bodů:<\/p><p>Identifikované třídy ekvivalence:<\/p><ol><li><p><strong>Neplatné třídy (mimo rozsah)<\/strong>:<\/p><ul><li><p>Pod 1 (např. 0)<\/p><\/li><li><p>Nad 100 (např. 101)<\/p><\/li><\/ul><\/li><li><p><strong>Platné třídy (známky):<\/strong><\/p><ul><li><p>1-49 (známka F)<\/p><\/li><li><p>50-59 (známka D-)<\/p><\/li><li><p>60-69 (známka D)<\/p><\/li><li><p>70-79 (známka C)<\/p><\/li><li><p>80-89 (známka B)<\/p><\/li><li><p>90-100 (známka A)<\/p><\/li><\/ul><\/li><\/ol><p>Celkový počet tříd je tedy 8.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-29","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Testujete systém regulace teploty, který řídí vytápění a chlazení. Teplota se měří v celých stupních Celsia a systém pracuje v těchto režimech:<\/p><ul><li>pod 0 °C: „Režim ochrany proti zamrznutí“<\/li><li>0 °C až 10 °C: „Režim mírného vytápění“<\/li><li>11 °C až 20 °C: „Režim normálního vytápění“<\/li><li>21 °C až 30 °C: „Režim chlazení“<\/li><li>nad 30 °C: „Režim intenzivního chlazení“<\/li><\/ul><p>Kolik testovacích případů NEJMÉNĚ potřebujete k dosažení 100% pokrytí dvouhodnotovou analýzou hraničních hodnot?<\/p>","m":["<p>8<\/p>","<p>9<\/p>","<p>10<\/p>","<p>11<\/p>"],"ok":[0],"vys":{"a":"Je správně. Hraniční hodnoty jsou −1, 0, 10, 11, 20, 21, 30 a 31 – celkem 8 hodnot.","b":"Není správně. Hraničních hodnot je 8; devátá hodnota není potřeba.","c":"Není správně. 10 hodnot by odpovídalo přidání dalších hodnot, které hraničními hodnotami nejsou (třídy pod 0 a nad 30 nemají definovanou vnější mez).","d":"Není správně. 11 hodnot neodpovídá žádnému výpočtu dvouhodnotové BVA pro tyto třídy."},"obecne":"Sylabus 4.2.2: při dvouhodnotové BVA jsou položkami pokrytí hraniční hodnoty (minimum a maximum každé třídy). Pět tříd má hraniční hodnoty −1 | 0, 10 | 11, 20 | 21, 30 | 31; krajní třídy (pod 0 a nad 30) nemají definovanou vnější mez. Celkem 8 testovacích případů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-30","n":null,"lo":"FL-4.2.3","k":"K3","k3":false,"vyber":1,"q":"<p>U které z následujících technik testování jsou položkami pokrytí sloupce obsahující proveditelné kombinace podmínek?<\/p>","m":["<p>Testování dle rozhodovací tabulky<\/p>","<p>Rozdělení tříd ekvivalence<\/p>","<p>Testování přechodů stavů<\/p>","<p>Analýza hraničních hodnot<\/p>"],"ok":[0],"vys":{"a":"Je správně. U rozhodovacích tabulek jsou položkami pokrytí sloupce s proveditelnou kombinací podmínek.","b":"Není správně. Položkami pokrytí u rozdělení tříd ekvivalence jsou třídy ekvivalence; pokrytí každé volby kombinace tříd nebere v úvahu.","c":"Není správně. Položkami pokrytí u testování přechodů stavů jsou stavy nebo přechody.","d":"Není správně. Položkami pokrytí u analýzy hraničních hodnot jsou hraniční hodnoty (případně i jejich sousedé)."},"obecne":"<p><strong>U rozhodovacích tabulek jsou položkami pokrytí sloupce obsahující proveditelnou kombinaci podmínek.<\/strong> Pro dosažení 100% pokrytí touto technikou musí testovací případy pokrýt všechny takové sloupce. Pokrytí se měří jako poměr počtu pokrytých sloupců k celkovému počtu proveditelných sloupců (obvykle vyjádřeno v procentech).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UC-4-31","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Testujete systém vah, který určuje sazby za přepravu pro regionálního internetového distributora autodílů. Hmotnosti se zaokrouhlují na celé kilogramy. Sazby jsou určeny takto:<\/p><table><tr><th>Hmotnost zásilky<\/th><th>Sazba za přepravu<\/th><\/tr><tr><td>1 až 10 kg<\/td><td>sazba 1<\/td><\/tr><tr><td>11 až 25 kg<\/td><td>sazba 2<\/td><\/tr><tr><td>26 až 50 kg<\/td><td>sazba 3<\/td><\/tr><tr><td>51 kg a více<\/td><td>sazba 4<\/td><\/tr><\/table><p>Zásilky lehčí než 1 kg systém odmítne. Chcete seskupit testovací podmínky tak, abyste testování minimalizovali.<\/p><p>Kolik tříd ekvivalence (platných i neplatných) je pro hmotnost potřeba?<\/p>","m":["<p>4<\/p>","<p>5<\/p>","<p>6<\/p>","<p>8<\/p>"],"ok":[1],"vys":{"a":"Není správně. 4 třídy pokrývají jen platné hodnoty; chybí neplatná třída hmotností pod 1 kg.","b":"Je správně. Platné třídy jsou 1–10, 11–25, 26–50 a 51 kg a více, neplatná třída je méně než 1 kg – celkem 5 tříd.","c":"Není správně. 6 tříd by vyžadovalo i neplatnou třídu nad horní mezí, ta však neexistuje – třída „51 kg a více“ je shora neomezená.","d":"Není správně. 8 tříd by vyšlo např. při zdvojení tříd; tabulka definuje 4 platné třídy a existuje jediná neplatná třída."},"obecne":"Sylabus 4.2.1: rozdělení tříd ekvivalence dělí data do tříd, které testovaný objekt zpracovává stejně; uvažujeme platné i neplatné třídy. Zde jsou 4 platné třídy podle sazeb a 1 neplatná třída (méně než 1 kg). Poslední třída „51 kg a více“ nemá horní mez, takže další neplatná třída nevzniká.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-32","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Testujete systém vah, který určuje sazby za přepravu pro regionálního internetového distributora autodílů. Kvůli předpisům byl systém upraven tak, aby zásilky nemohly přesáhnout 100 kg. Hmotnost se vybírá z rozbalovacího seznamu s celými hodnotami od 0 do 100 kg; zásilku s hmotností 0 kg systém odmítne. Sazby jsou určeny takto:<\/p><table><tr><th>Hmotnost zásilky<\/th><th>Sazba za přepravu<\/th><\/tr><tr><td>1 až 10 kg<\/td><td>sazba 1<\/td><\/tr><tr><td>11 až 25 kg<\/td><td>sazba 2<\/td><\/tr><tr><td>26 až 50 kg<\/td><td>sazba 3<\/td><\/tr><tr><td>51 až 100 kg<\/td><td>sazba 4<\/td><\/tr><\/table><p>Jako součást návrhu testů černé skříňky chcete použít tříhodnotovou analýzu hraničních hodnot. Kolik různých hodnot musíte otestovat, abyste dosáhli 100% pokrytí?<\/p>","m":["<p>16<\/p>","<p>17<\/p>","<p>18<\/p>","<p>20<\/p>"],"ok":[1],"vys":{"a":"Není správně. 16 hodnot vynechává jednu z položek pokrytí, např. souseda 2 nebo 52.","b":"Je správně. Hraniční hodnoty jsou 0, 1, 10, 11, 25, 26, 50, 51 a 100; jejich sjednocení se zadatelnými sousedy dává 17 různých hodnot.","c":"Není správně. 18 hodnot by vyšlo, kdyby šlo zadat i hodnotu −1 nebo 101; rozbalovací seznam to neumožňuje.","d":"Není správně. 20 hodnot by vyšlo při počítání duplicitních hodnot nebo nezadatelných hodnot mimo rozsah."},"obecne":"Sylabus 4.2.2: při tříhodnotové BVA jsou položkami pokrytí hraniční hodnoty a jejich sousedé. Hraniční hodnoty: 0 (neplatná třída), 1, 10, 11, 25, 26, 50, 51, 100. Sjednocení: 0, 1, 2, 9, 10, 11, 12, 24, 25, 26, 27, 49, 50, 51, 52, 99, 100 = 17 hodnot (−1 a 101 nelze vybrat).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-33","n":null,"lo":"FL-4.2.1","k":"K3","k3":false,"vyber":1,"q":"<p>Která z následujících tvrzení o technice rozdělení tříd ekvivalence jsou PRAVDIVÁ?<\/p><ol type=\"A\"><li>Rozděluje možné vstupy do tříd, které testovaný objekt zpracovává stejně.<\/li><li>Používá platné i neplatné třídy.<\/li><li>Využívá pouze platné třídy.<\/li><li>Musí zahrnovat alespoň dvě hodnoty z každé třídy ekvivalence.<\/li><li>Pokrytí každé volby bere v úvahu kombinace tříd.<\/li><\/ol>","m":["<p>A a C<\/p>","<p>A, C a D<\/p>","<p>A, B a E<\/p>","<p>A a B<\/p>"],"ok":[3],"vys":{"a":"Není správně. C neplatí – rozdělení tříd ekvivalence používá i neplatné třídy.","b":"Není správně. C neplatí (používají se i neplatné třídy) a D neplatí (z každé třídy stačí jedna hodnota).","c":"Není správně. E neplatí – pokrytí každé volby kombinace tříd nebere v úvahu.","d":"Je správně. Platí A (třídy se zpracovávají stejně) a B (pokrývají se platné i neplatné třídy)."},"obecne":"<p>- Rozdělení tříd ekvivalence (EP) rozděluje data do tříd (označovaných jako třídy ekvivalence), u kterých lze očekávat stejný způsob zpracování testovaným objektem.<\/p><p>- Pokrývají se platné i neplatné třídy, pokud není uvedeno jinak.<\/p><p>- Pokrytí je měřeno jako poměr počtu tříd otestovaných alespoň <strong>jedním testovacím případem<\/strong> k celkovému počtu identifikovaných tříd (obvykle vyjádřeno v procentech).<\/p><p>- Pokrytí každé volby vyžaduje, aby testovací případy pokryly každou třídu z každé množiny tříd alespoň jednou, a <strong>nebere v úvahu<\/strong> kombinace tříd.<\/p><p><br><\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-34","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností obsahuje POUZE techniky testování černé skříňky?<\/p>","m":["<p>Rozdělení tříd ekvivalence, rozhodovací tabulky a testování přechodů stavů.<\/p>","<p>Rozdělení tříd ekvivalence, graf příčin a následků, testování založené na kontrolních seznamech, pokrytí rozhodnutí, případy užití.<\/p>","<p>Rozdělení tříd ekvivalence, graf příčin a následků, testování založené na kontrolních seznamech, pokrytí rozhodnutí a hraniční hodnoty.<\/p>","<p>Rozdělení tříd ekvivalence, rozhodovací tabulky, testování založené na kontrolních seznamech, pokrytí příkazů a případy užití.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Rozdělení tříd ekvivalence, rozhodovací tabulky i testování přechodů stavů jsou techniky testování černé skříňky.","b":"Není správně. Testování založené na kontrolních seznamech je technika založená na zkušenostech a pokrytí rozhodnutí patří k testování bílé skříňky.","c":"Není správně. Testování založené na kontrolních seznamech je technika založená na zkušenostech a pokrytí rozhodnutí patří k testování bílé skříňky.","d":"Není správně. Testování založené na kontrolních seznamech je technika založená na zkušenostech a pokrytí příkazů patří k testování bílé skříňky."},"obecne":"<p>Běžně používané techniky testování černé skříňky popsané v sylabu jsou: <\/p><ul><li><p>rozdělení tříd ekvivalence, <\/p><\/li><li><p>analýza hraničních hodnot, <\/p><\/li><li><p>testování dle rozhodovací tabulky, <\/p><\/li><li><p>testování přechodů stavů.<\/p><\/li><\/ul>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UC-4-35","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Má být vypočítán bonus zaměstnance. Bonus závisí na délce pracovního poměru v celých letech (nemůže být záporná): do 2 let včetně žádný bonus, více než 2 roky, ale méně než 5 let bonus 10 %, 5 až 10 let včetně bonus 25 % a více než 10 let bonus 35 %.<\/p><p>Která z následujících sad hodnot délky pracovního poměru pokrývá všechny PLATNÉ třídy ekvivalence?<\/p>","m":["<p>1, 3, 7, 12<\/p>","<p>2, 5, 10, 11<\/p>","<p>0, 2, 4, 10<\/p>","<p>3, 4, 8, 15<\/p>"],"ok":[0],"vys":{"a":"Je správně. 1 leží ve třídě 0–2, 3 ve třídě 3–4, 7 ve třídě 5–10 a 12 ve třídě nad 10 let.","b":"Není správně. Chybí hodnota z třídy více než 2 a méně než 5 let (3–4).","c":"Není správně. Chybí hodnota z třídy více než 10 let.","d":"Není správně. Chybí hodnota z třídy do 2 let včetně."},"obecne":"<p>Sylabus 4.2.1: Platné třídy jsou 0–2 roky, 3–4 roky (více než 2 a méně než 5), 5–10 let a více než 10 let. Pro 100% pokrytí platných tříd musí sada obsahovat alespoň jednu hodnotu z každé z nich, což splňuje jen sada 1, 3, 7, 12.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-37","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Systém počítá provizi, kterou zaměstnanec získá ze svých prodejů (v celých librách):<\/p><ul><li>Prvních 4000 £ prodejů je bez provize.<\/li><li>Z dalších 1500 £ prodejů je provize 10 %.<\/li><li>Z dalších 28000 £ prodejů je provize 22 %.<\/li><li>Z jakékoli další částky prodejů je provize 40 %.<\/li><\/ul><p>Která z těchto skupin hodnot patří celá do STEJNÉ třídy ekvivalence?<\/p>","m":["<p>28001, 32000, 35000<\/p>","<p>4800, 14000, 28000<\/p>","<p>5800, 28000, 32000<\/p>","<p>5200, 5500, 28000<\/p>"],"ok":[2],"vys":{"a":"Není správně. 28001 a 32000 patří do třídy 5501–33500, ale 35000 do třídy nad 33500 (40 %).","b":"Není správně. 4800 patří do třídy 4001–5500 (10 %), kdežto 14000 a 28000 do třídy 5501–33500 (22 %).","c":"Je správně. 5800, 28000 i 32000 leží v třídě 5501–33500 £ (provize 22 %).","d":"Není správně. 5200 a 5500 patří do třídy 4001–5500, ale 28000 do třídy 5501–33500."},"obecne":"<p>V systému existují tyto třídy:<\/p><p><strong>Třída 1:<\/strong> prodeje od 0 £ do 4000 £ (bez provize)<\/p><p><strong>Třída 2:<\/strong> prodeje od 4001 £ do 5500 £ (provize 10 %)<\/p><p><strong>Třída 3:<\/strong> prodeje od 5501 £ do 33500 £ (provize 22 %)<\/p><p><strong>Třída 4:<\/strong> prodeje vyšší než 33500 £ (provize 40 %)<\/p><p>Nezapomeňte, že otázka se ptá na možnost, ve které všechny hodnoty patří do stejné třídy.<\/p><p><br><\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-38","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Systém počítá provizi, kterou zaměstnanec získá ze svých prodejů (v celých librách):<\/p><ul><li>Prvních 4000 £ prodejů je bez provize.<\/li><li>Z dalších 1500 £ prodejů je provize 10 %.<\/li><li>Z dalších 28000 £ prodejů je provize 22 %.<\/li><li>Z jakékoli další částky prodejů je provize 40 %.<\/li><\/ul><p>Která z těchto hodnot je hraniční hodnotou při použití analýzy hraničních hodnot?<\/p>","m":["<p>1500<\/p>","<p>32001<\/p>","<p>28000<\/p>","<p>33501<\/p>"],"ok":[3],"vys":{"a":"Není správně. 1500 je šířka pásma s provizí 10 %, nikoli hraniční hodnota; pásmo je 4001–5500.","b":"Není správně. 32001 leží uvnitř třídy 5501–33500.","c":"Není správně. 28000 je šířka pásma s provizí 22 %, nikoli hraniční hodnota; leží uvnitř třídy 5501–33500.","d":"Je správně. 33501 je nejmenší hodnota třídy s provizí 40 % (horní mez předchozí třídy je 4000 + 1500 + 28000 = 33500)."},"obecne":"Sylabus 4.2.2: hraniční hodnoty jsou minimální a maximální hodnoty tříd. Třídy jsou 0–4000, 4001–5500, 5501–33500 a od 33501 výše, takže hraničními hodnotami jsou 0, 4000, 4001, 5500, 5501, 33500 a 33501.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-39","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Programátor validuje číselné pole s celými čísly takto: hodnoty menší než 10 jsou odmítnuty, hodnoty od 10 do 21 jsou přijaty, hodnoty větší nebo rovné 22 jsou odmítnuty.<\/p><p>Která z následujících sad vstupních hodnot pokrývá všechny třídy ekvivalence?<\/p>","m":["<p>3, 10, 22<\/p>","<p>10, 11, 12<\/p>","<p>10, 21, 22<\/p>","<p>3, 20, 21<\/p>"],"ok":[0],"vys":{"a":"Je správně. 3 pokrývá třídu menší než 10, 10 třídu 10–21 a 22 třídu 22 a více.","b":"Není správně. Všechny hodnoty leží v platné třídě 10–21.","c":"Není správně. Chybí hodnota z třídy menší než 10.","d":"Není správně. Chybí hodnota z třídy 22 a více."},"obecne":"<p>Existují tři třídy:<\/p><p>- menší než 10<\/p><p>- 10 až 21<\/p><p>- větší než 21 <\/p><p>Z každé třídy stačí otestovat jednu hodnotu.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-40","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Programátor validuje číselné pole s celými čísly takto: hodnoty menší než 10 jsou odmítnuty, hodnoty od 10 do 21 jsou přijaty, hodnoty větší nebo rovné 22 jsou odmítnuty.<\/p><p>Která z následujících sad vstupních hodnot pokrývá NEJVÍCE hraničních hodnot (dvouhodnotová analýza hraničních hodnot)?<\/p>","m":["<p>10, 11, 21, 22<\/p>","<p>9, 10, 21, 22<\/p>","<p>9, 10, 11, 12<\/p>","<p>10, 11, 20, 21<\/p>"],"ok":[1],"vys":{"a":"Není správně. Pokrývá hraniční hodnoty 10, 21 a 22 (3 ze 4), chybí 9.","b":"Je správně. Pokrývá všechny čtyři hraniční hodnoty 9, 10, 21 a 22.","c":"Není správně. Pokrývá jen hraniční hodnoty 9 a 10 (2 ze 4).","d":"Není správně. Pokrývá jen hraniční hodnoty 10 a 21 (2 ze 4)."},"obecne":"Sylabus 4.2.2: hraničními hodnotami jsou 9 (maximum třídy menší než 10), 10 a 21 (minimum a maximum platné třídy) a 22 (minimum třídy 22 a více). Všechny čtyři pokrývá pouze sada 9, 10, 21, 22.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-41","n":null,"lo":"FL-4.5.3","k":"K3","k3":true,"vyber":1,"q":"<p>Uvažujte následující uživatelský scénář:<\/p><p><em>Jako student Nezam Academy chci vyplňovat kvízy online, abych mohl posoudit, jak rozumím studijní látce, a sledovat svůj pokrok.<\/em><\/p><p>Akceptační kritéria:<\/p><ol><li><strong>Přístup ke kvízu:<\/strong><ul><li>Studenti musí mít možnost otevřít kvíz přímo ze svého přehledu kurzu.<\/li><li>Kvíz by měli mít možnost vyplnit pouze studenti zapsaní do kurzu.<\/li><\/ul><\/li><li><strong>Obsah kvízu:<\/strong><ul><li>Kvíz musí obsahovat otázky s výběrem z možností, otázky typu pravda/nepravda a otázky s krátkou odpovědí.<\/li><li>Každý kvíz musí mít název, popis a jasné pokyny, jak jej vyplnit.<\/li><\/ul><\/li><li><strong>Navigace mezi otázkami:<\/strong><ul><li>Studenti musí mít možnost přecházet mezi otázkami v rámci kvízu.<\/li><li>Indikátor průběhu musí zobrazovat počet zodpovězených a zbývajících otázek.<\/li><\/ul><\/li><li><strong>Časovač:<\/strong><ul><li>Na obrazovce by měl být zobrazen časovač ukazující zbývající čas na dokončení kvízu.<\/li><li>Časovač se musí spustit, když student začne kvíz, a zastavit se, když je kvíz odeslán.<\/li><\/ul><\/li><\/ol><p>Který z následujících testovacích případů NENÍ platným testovacím případem ATDD pro tento uživatelský scénář?<\/p>","m":["<p>Otevřít přehled kurzu a přejít na stránku s kvízy<\/p>","<p>Přečíst si pokyny vztahující se ke kvízu<\/p>","<p>Zopakovat kvíz poté, co student nedosáhl potřebného počtu bodů pro úspěšné složení<\/p>","<p>V kvízu s 10 otázkami přejít na otázku 10 a poté se vrátit na otázku 1<\/p>"],"ok":[2],"vys":{"a":"Není správně. Test odpovídá kritériu Přístup ke kvízu – otevření kvízu z přehledu kurzu.","b":"Není správně. Test odpovídá kritériu Obsah kvízu – každý kvíz musí mít jasné pokyny.","c":"Je správně. Opakování kvízu po neúspěchu nepokrývá žádné akceptační kritérium; test by přesahoval rámec uživatelského scénáře.","d":"Není správně. Test odpovídá kritériu Navigace mezi otázkami."},"obecne":"Sylabus 4.5.3: v ATDD se testovací případy odvozují z akceptačních kritérií; musí pokrývat všechny charakteristiky uživatelského scénáře a neměly by přesahovat jeho rámec. Opakování kvízu po neúspěchu žádné kritérium nepožaduje – může být předmětem jiného uživatelského scénáře.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UC-4-42","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Vstupní pole přijímá rok narození (celé číslo) v rozsahu 1900 až 2004 včetně. Která z následujících sad hodnot poskytuje NEJVYŠŠÍ pokrytí tříhodnotovou analýzou hraničních hodnot?<\/p>","m":["<p>1899, 1900, 1950, 2004, 2005<\/p>","<p>0, 1899, 1900, 2004, 2005, 9999<\/p>","<p>1900, 1901, 2003, 2004, 2005<\/p>","<p>1899, 1900, 1901, 2003, 2004, 2005<\/p>"],"ok":[3],"vys":{"a":"Není správně. Pokrývá 4 z 8 položek pokrytí; hodnota 1950 položkou pokrytí není.","b":"Není správně. Pokrývá 4 z 8 položek pokrytí (1899, 1900, 2004, 2005); hodnoty 0 a 9999 položkami pokrytí nejsou.","c":"Není správně. Pokrývá 5 z 8 položek pokrytí; chybí 1898, 1899 a 2006.","d":"Je správně. Pokrývá 6 z 8 položek pokrytí (chybí jen 1898 a 2006), což je nejvíce."},"obecne":"Sylabus 4.2.2: hraniční hodnoty jsou 1899, 1900, 2004 a 2005. Při tříhodnotové BVA jsou položkami pokrytí tyto hodnoty a jejich sousedé: 1898, 1899, 1900, 1901, 2003, 2004, 2005, 2006 (8 položek). Sada 1899, 1900, 1901, 2003, 2004, 2005 jich pokrývá 6, tj. 75 %.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-44","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Uvažujte následující rozhodovací tabulku pro část online rezervačního systému letecké společnosti, která umožňuje věrným zákazníkům uplatnit body za odměnovou letenku (A = ano, N = ne, – = na hodnotě nezáleží):<\/p><table><tr><th>Podmínky / akce<\/th><th>Pravidlo 1<\/th><th>Pravidlo 2<\/th><th>Pravidlo 3<\/th><\/tr><tr><td>Účet/heslo v pořádku<\/td><td>N<\/td><td>A<\/td><td>A<\/td><\/tr><tr><td>Dostatek bodů<\/td><td>–<\/td><td>A<\/td><td>N<\/td><\/tr><tr><td>Zobrazit chybu přihlášení<\/td><td>X<\/td><td><\/td><td><\/td><\/tr><tr><td>Nabídnout odměnové lety<\/td><td><\/td><td>X<\/td><td><\/td><\/tr><tr><td>Zobrazit hlášení o nedostatku bodů<\/td><td><\/td><td><\/td><td>X<\/td><\/tr><\/table><p>Pro podmínku „Účet/heslo v pořádku“ = N existují dvě třídy ekvivalence: neplatný účet a platný účet s neplatným heslem. Pro hodnotu A existuje jediná třída ekvivalence: platný účet i heslo.<\/p><p>Chcete navrhnout testy tak, aby pokryly všechny třídy ekvivalence podmínky „Účet/heslo v pořádku“ a zároveň všechna pravidla rozhodovací tabulky. Jaký je MINIMÁLNÍ počet potřebných testů?<\/p>","m":["<p>2<\/p>","<p>3<\/p>","<p>4<\/p>","<p>9<\/p>"],"ok":[2],"vys":{"a":"Není správně. Dva testy nepokryjí ani všechna tři pravidla tabulky.","b":"Není správně. Tři testy pokryjí pravidla tabulky, ale pravidlo 1 je třeba testovat pro obě třídy ekvivalence (neplatný účet, neplatné heslo).","c":"Je správně. Pravidlo 1 vyžaduje 2 testy (neplatný účet; platný účet s neplatným heslem), pravidla 2 a 3 po jednom testu – celkem 4.","d":"Není správně. 9 testů by odpovídalo kombinaci všech hodnot bez ohledu na pravidla; to není minimum."},"obecne":"Sylabus 4.2.3 a 4.2.1: položkami pokrytí rozhodovací tabulky jsou sloupce s proveditelnou kombinací podmínek (zde 3 pravidla). Protože hodnota N podmínky „Účet/heslo v pořádku“ zahrnuje dvě třídy ekvivalence, musí mít pravidlo 1 dva testy. Celkem 2 + 1 + 1 = 4 testy.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UC-4-47","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o testerovi, který používá techniky testování černé skříňky, NEPLATÍ?<\/p>","m":["<p>Měl by rozumět uživatelským scénářům a jejich akceptačním kritériím<\/p>","<p>Měl by znát vnitřní strukturu kódu, ze které odvozuje testovací případy<\/p>","<p>Měl by umět posoudit uživatelské scénáře podle kritérií INVEST<\/p>","<p>Měl by být kreativní, aby dokázal odhalit slabá místa systému<\/p>"],"ok":[1],"vys":{"a":"Není správně. Toto tvrzení platí: uživatelské scénáře a akceptační kritéria jsou testovací bází pro testování černé skříňky.","b":"Je správně. Toto tvrzení neplatí: odvozování testů z vnitřní struktury kódu je podstatou testování bílé skříňky, nikoli černé skříňky.","c":"Není správně. Toto tvrzení platí: posouzení uživatelských scénářů podle INVEST (včetně testovatelnosti) pomáhá připravit kvalitní testovací bázi.","d":"Není správně. Toto tvrzení platí pro každého testera, tedy i pro testera černé skříňky."},"obecne":"Sylabus 4.1: techniky testování černé skříňky vycházejí z analýzy specifikovaného chování testovaného objektu bez znalosti jeho vnitřní struktury. Testovací případy odvozené z vnitřní struktury kódu jsou doménou testování bílé skříňky.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UC-4-48","n":null,"lo":"FL-4.2.1","k":"K3","k3":false,"vyber":1,"q":"<p>Příkaz programu přijímá pouze celočíselné vstupy od 1 do 10. Při použití rozdělení tříd ekvivalence by prostřední třída ekvivalence zahrnovala hodnoty od ____ do ____.<\/p>","m":["<p>3 do 7<\/p>","<p>0 do 10<\/p>","<p>1 do 10<\/p>","<p>4 do 6<\/p>"],"ok":[2],"vys":{"a":"Není správně. Hodnoty 3 až 7 jsou jen částí platné třídy 1–10.","b":"Není správně. Hodnota 0 je neplatná a patří do třídy menší než 1.","c":"Je správně. Platná třída 1–10 leží mezi neplatnými třídami menší než 1 a větší než 10.","d":"Není správně. Hodnoty 4 až 6 jsou jen částí platné třídy; všechny hodnoty 1 až 10 se zpracovávají stejně."},"obecne":"<p>V tomto příkladu máme pouze jednu platnou třídu ekvivalence, která obsahuje hodnoty od 1 do 10. Tato třída je prostřední, protože leží mezi dvěma neplatnými třídami (menší než 1 a větší než 10).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-49","n":null,"lo":"FL-4.2.1","k":"K3","k3":false,"vyber":1,"q":"<p>Které z následujících tvrzení o platných a neplatných hodnotách v technice rozdělení tříd ekvivalence je v souladu se sylabem?<\/p>","m":["<p>Platné hodnoty jsou vždy jen ty, které specifikace výslovně uvádí jako přípustné<\/p>","<p>Neplatné hodnoty se při rozdělení tříd ekvivalence netestují, pokrývají se jen platné třídy<\/p>","<p>Neplatné hodnoty jsou vždy ty, které testovaný objekt musí odmítnout chybovým hlášením<\/p>","<p>Definice platných a neplatných hodnot se mohou lišit v závislosti na týmech a organizacích<\/p>"],"ok":[3],"vys":{"a":"Není správně. Jde jen o jednu z možných interpretací; sylabus neuvádí, že by platila vždy.","b":"Není správně. Pro 100% pokrytí je nutné pokrýt platné i neplatné třídy.","c":"Není správně. Neplatné hodnoty lze chápat také jako ignorované nebo jako hodnoty bez definovaného zpracování; nejde vždy o odmítnutí s chybovým hlášením.","d":"Je správně. Sylabus uvádí, že definice platných a neplatných hodnot se mohou v praxi lišit podle týmů a organizací."},"obecne":"Sylabus 4.2.1: definice platných a neplatných hodnot se mohou výrazně lišit podle týmů a organizací. Platné hodnoty lze chápat např. jako ty, které má testovaný objekt zpracovat, nebo ty, pro které specifikace definuje zpracování; neplatné jako ty, které má ignorovat či odmítnout, nebo ty, pro které zpracování definováno není.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-50","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Je dána následující specifikace (věk je celé číslo):<\/p><ul><li>Pokud je vám méně než 18 let, jste příliš mladí na to, abyste si mohli pronajmout byt.<\/li><li>Pokud je váš věk mezi 18 a 30 lety včetně, získáte slevu 20 %.<\/li><li>Kdokoli starší 30 let nemá na slevu nárok.<\/li><\/ul><p>Které z následujících hodnot věku patří všechny do STEJNÉ třídy ekvivalence?<\/p>","m":["<p>18, 29, 30<\/p>","<p>17, 29, 31<\/p>","<p>29, 30, 31<\/p>","<p>17, 18, 19<\/p>"],"ok":[0],"vys":{"a":"Je správně. 18, 29 i 30 leží v třídě 18–30 (sleva 20 %).","b":"Není správně. Každá hodnota patří do jiné třídy.","c":"Není správně. 29 a 30 patří do třídy 18–30, kdežto 31 do třídy nad 30.","d":"Není správně. 17 patří do třídy méně než 18, kdežto 18 a 19 do třídy 18–30."},"obecne":"Sylabus 4.2.1: specifikace definuje tři třídy ekvivalence – méně než 18, 18 až 30 včetně a více než 30. Otázka nežádá výběr jedné hodnoty z každé třídy, ale hodnoty, které leží ve stejné třídě: 18, 29 a 30.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-51","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Je dána následující specifikace (věk je celé číslo):<\/p><ul><li>Pokud je vám méně než 18 let, jste příliš mladí na to, abyste si mohli pronajmout byt.<\/li><li>Pokud je váš věk mezi 18 a 30 lety včetně, získáte slevu 20 %.<\/li><li>Kdokoli starší 30 let nemá na slevu nárok.<\/li><\/ul><p>Vámi navržené testovací případy dosáhly 100% pokrytí dvouhodnotovou analýzou hraničních hodnot. Kvůli známým rizikům potřebujete dosáhnout také 100% pokrytí tříhodnotovou analýzou hraničních hodnot. Které hodnoty je nutné do sady testů doplnit?<\/p>","m":["<p>16, 32<\/p>","<p>16, 19, 29, 32<\/p>","<p>19, 29<\/p>","<p>V tomto příkladu není mezi dvouhodnotovou a tříhodnotovou BVA žádný rozdíl<\/p>"],"ok":[1],"vys":{"a":"Není správně. Chybí také sousedé 19 a 29.","b":"Je správně. Dvouhodnotová BVA použila 17, 18, 30, 31; tříhodnotová vyžaduje 16, 17, 18, 19, 29, 30, 31, 32, takže chybí 16, 19, 29 a 32.","c":"Není správně. Chybí také sousedé 16 a 32.","d":"Není správně. Tříhodnotová BVA přidává ke každé hraniční hodnotě oba sousedy, takže vyžaduje další hodnoty."},"obecne":"Sylabus 4.2.2: hraniční hodnoty jsou 17, 18, 30 a 31 (dvouhodnotová BVA). Tříhodnotová BVA přidává ke každé hraniční hodnotě oba sousedy: 16, 17, 18, 19, 29, 30, 31, 32. Doplnit je tedy třeba 16, 19, 29 a 32.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-52","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících technik testování je založená na struktuře?<\/p>","m":["<p>Analýza hraničních hodnot<\/p>","<p>Testování přechodů stavů<\/p>","<p>Testování větví<\/p>","<p>Rozdělení tříd ekvivalence<\/p>"],"ok":[2],"vys":{"a":"Není správně. Analýza hraničních hodnot je technika testování černé skříňky.","b":"Není správně. Testování přechodů stavů je technika testování černé skříňky.","c":"Je správně. Testování větví je technika testování bílé skříňky, tedy technika založená na struktuře.","d":"Není správně. Rozdělení tříd ekvivalence je technika testování černé skříňky."},"obecne":"Sylabus 4.1: techniky testování bílé skříňky (známé také jako techniky založené na struktuře) vycházejí z analýzy vnitřní struktury testovaného objektu. Sylabus z nich popisuje testování příkazů a testování větví.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UC-4-54","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Je dán následující případ užití:<\/p><p><strong>Název:<\/strong> Přihlášení uživatele<\/p><p><strong>Hlavní úspěšný scénář:<\/strong><\/p><ol><li>Uživatel přejde na přihlašovací stránku.<\/li><li>Uživatel zadá své uživatelské jméno a heslo.<\/li><li>Uživatel odešle přihlašovací formulář.<\/li><li>Systém ověří uživatelské jméno a heslo.<\/li><li>Systém uživateli udělí přístup.<\/li><\/ol><p><strong>Alternativní scénář – neplatné uživatelské jméno nebo heslo:<\/strong> uživatel zadá nesprávné údaje; systém zobrazí chybovou zprávu a vyzve uživatele, aby to zkusil znovu.<\/p><p>Vývojář implementoval ověření jako podmínku „pokud jsou údaje platné, uděl přístup“, větev pro neplatné údaje však vynechal – při nesprávných údajích systém nic nezobrazí.<\/p><p>Která technika testování, pokud by byla použita, toto selhání NEJPRAVDĚPODOBNĚJI NEODHALÍ?<\/p>","m":["<p>Rozdělení tříd ekvivalence<\/p>","<p>Testování přechodů stavů<\/p>","<p>Testování větví<\/p>","<p>Testování příkazů<\/p>"],"ok":[3],"vys":{"a":"Není správně. Neplatné přihlašovací údaje tvoří samostatnou třídu ekvivalence, test této třídy selhání odhalí.","b":"Není správně. Stavový model přihlášení obsahuje i přechod při neplatných údajích, jeho test selhání odhalí.","c":"Není správně. 100% pokrytí větví vyžaduje i nepravdivý výsledek podmínky, tedy test s neplatnými údaji, při němž se ukáže chybějící chybová zpráva.","d":"Je správně. 100% pokrytí příkazů lze dosáhnout jediným testem s platnými údaji, protože pro neplatné údaje neexistuje žádný příkaz – selhání tak zůstane neodhaleno."},"obecne":"Sylabus 4.3.1 a 4.3.2: pokrytí příkazů zajistí jen provedení existujících příkazů, kdežto pokrytí větví vyžaduje provést každý výsledek rozhodnutí. Protože větev pro neplatné údaje neobsahuje žádný příkaz, pokrytí příkazů lze dosáhnout bez testu s neplatnými údaji. Techniky černé skříňky z případu užití odvodí test alternativního scénáře přímo.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UC-4-55","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Jaký je minimální počet testovacích případů potřebný pro 100% pokrytí příkazů a pro 100% pokrytí větví u následujícího kódu?<\/p><pre>int vyska = nactiVysku();\nint hmotnost = nactiHmotnost();\nString poznamka = \"\";\nif (vyska &gt; 140) {\n    poznamka = poznamka + \"Vysoký pacient. \";\n}\nif (hmotnost &gt; 70) {\n    poznamka = poznamka + \"Vyšší hmotnost. \";\n}\nvypis(poznamka);<\/pre>","m":["<p>1 testovací případ pro pokrytí příkazů, 2 testovací případy pro pokrytí větví<\/p>","<p>4 testovací případy pro pokrytí příkazů, 2 testovací případy pro pokrytí větví<\/p>","<p>2 testovací případy pro pokrytí příkazů, 2 testovací případy pro pokrytí větví<\/p>","<p>1 testovací případ pro pokrytí příkazů, 3 testovací případy pro pokrytí větví<\/p>"],"ok":[0],"vys":{"a":"Je správně. Test (150, 80) provede všechny příkazy; přidáním testu (120, 50) se pokryjí i nepravdivé výsledky obou rozhodnutí.","b":"Není správně. Pro pokrytí příkazů nejsou potřeba 4 testy – obě větve if jsou bez else a provede je jediný test.","c":"Není správně. Pro pokrytí příkazů stačí jeden test, v němž jsou obě podmínky pravdivé (např. výška 150, hmotnost 80).","d":"Není správně. Pro pokrytí větví stačí dva testy: oba výsledky obou rozhodnutí pokryje dvojice „obě podmínky pravdivé“ a „obě nepravdivé“."},"obecne":"Sylabus 4.3.1 a 4.3.2: oba příkazy if jsou bez else, takže jeden test s pravdivými podmínkami provede všechny příkazy. Pro 100% pokrytí větví je nutné pokrýt i nepravdivé výsledky obou rozhodnutí; stačí k tomu jeden další test, v němž jsou obě podmínky nepravdivé.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UC-4-57","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Pokud k zacílení testování používáte odhadování chyb, do jaké kategorie technik testování tato technika patří?<\/p>","m":["<p>Techniky založené na struktuře<\/p>","<p>Techniky založené na zkušenostech<\/p>","<p>Techniky založené na referencích<\/p>","<p>Techniky založené na chování<\/p>"],"ok":[1],"vys":{"a":"Není správně. Techniky založené na struktuře (bílé skříňky) vycházejí z vnitřní struktury testovaného objektu.","b":"Je správně. Odhadování chyb je spolu s průzkumným testováním a testováním založeným na kontrolních seznamech technikou založenou na zkušenostech.","c":"Není správně. Kategorii „technik založených na referencích“ sylabus nezná.","d":"Není správně. Techniky založené na chování (černé skříňky) vycházejí ze specifikace, nikoli ze zkušenosti testera."},"obecne":"<p>Běžně používané techniky testování založené na zkušenostech popsané v sylabu (kap. 4.4) jsou: <\/p><ul><li><p>odhadování chyb,<\/p><\/li><\/ul><ul><li><p>průzkumné testování,<\/p><\/li><\/ul><ul><li><p>testování založené na kontrolních seznamech.<\/p><\/li><\/ul>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UC-4-58","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Pokud používáte techniku testování k nalezení testovacích případů, které byly opomenuty při použití formálních technik testování, jaký typ technik používáte?<\/p>","m":["<p>Techniky testování černé skříňky<\/p>","<p>Techniky založené na defektech<\/p>","<p>Techniky založené na zkušenostech<\/p>","<p>Techniky testování bílé skříňky<\/p>"],"ok":[2],"vys":{"a":"Není správně. Techniky černé skříňky patří k formálním technikám, jejichž mezery se mají doplnit.","b":"Není správně. Kategorii „techniky založené na defektech“ sylabus v4.0 nerozlišuje.","c":"Je správně. Techniky založené na zkušenostech mohou odhalit defekty, které techniky černé a bílé skříňky neodhalí; jsou jejich doplňkem.","d":"Není správně. Techniky bílé skříňky patří k formálním technikám, jejichž mezery se mají doplnit."},"obecne":"<p>Při porovnání technik černé skříňky, bílé skříňky a technik založených na zkušenostech považujeme techniky černé a bílé skříňky za formální techniky a techniky založené na zkušenostech za neformální techniky.<\/p><p><br><\/p><p><strong>Podle sylabu (kap. 4.1):<\/strong><br>Techniky testování založené na zkušenostech využívají znalosti a zkušenosti testerů pro návrh a implementaci testovacích případů. Efektivita těchto technik testování silně závisí na dovednostech testerů. <strong>Techniky testování založené na zkušenostech mohou odhalit defekty, které techniky testování černé a bílé skříňky neodhalí. Lze tedy říct, že techniky testování založené na zkušenostech jsou doplňkem technik testování černé a bílé skříňky.<\/strong><\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UC-4-59","n":null,"lo":"FL-4.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících přístupů k testování je NEJVHODNĚJŠÍ v situaci, kdy je specifikace nekvalitní a na testování je velký časový tlak?<\/p>","m":["<p>Testování případů užití<\/p>","<p>Pokrytí podmínek<\/p>","<p>Testování cest<\/p>","<p>Průzkumné testování<\/p>"],"ok":[3],"vys":{"a":"Není správně. Testování případů užití vyžaduje kvalitní případy užití jako testovací bázi.","b":"Není správně. Pokrytí podmínek je technika bílé skříňky náročná na čas a sylabus CTFL ji nepopisuje.","c":"Není správně. Testování cest je pracná technika bílé skříňky, kterou sylabus CTFL nepopisuje.","d":"Je správně. Průzkumné testování je nejužitečnější, když je specifikace nedostatečná nebo chybí a když je na testování výrazný časový tlak."},"obecne":"<p><strong>Podle sylabu (kap. 4.4.2):<\/strong> <strong>Průzkumné testování je nejvíce užitečné v případech, kdy je specifikace nedostatečná nebo úplně chybí, taktéž je vhodnou metodou v případě výrazného časového tlaku na testování.<\/strong> Je také užitečné jako doplněk jiných (formálnějších) testovacích technik. Obecně bude účinnější v případech, kdy jsou testeři zkušení, mají znalosti z dané domény a vysokou úroveň základních dovedností jako jsou analytické schopnosti, zvídavost a kreativita.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.2","nazev":"Průzkumné testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-dva-pruzkumne-testovani"}},{"id":"UC-4-60","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Stavový model bankomatu obsahuje právě tyto platné přechody:<\/p><table><tr><th>Ze stavu<\/th><th>Událost<\/th><th>Do stavu<\/th><\/tr><tr><td>Start<\/td><td>vložení karty<\/td><td>Čekání na PIN<\/td><\/tr><tr><td>Čekání na PIN<\/td><td>zadání PIN<\/td><td>1. pokus<\/td><\/tr><tr><td>1. pokus<\/td><td>PIN správný<\/td><td>Přístup k účtu<\/td><\/tr><tr><td>1. pokus<\/td><td>PIN chybný<\/td><td>2. pokus<\/td><\/tr><tr><td>2. pokus<\/td><td>PIN správný<\/td><td>Přístup k účtu<\/td><\/tr><tr><td>2. pokus<\/td><td>PIN chybný<\/td><td>3. pokus<\/td><\/tr><tr><td>3. pokus<\/td><td>PIN správný<\/td><td>Přístup k účtu<\/td><\/tr><tr><td>3. pokus<\/td><td>PIN chybný<\/td><td>Zadržení karty<\/td><\/tr><\/table><p>Stavy „Přístup k účtu“ a „Zadržení karty“ jsou koncové. Každý testovací případ začíná ve stavu „Start“ a končí v koncovém stavu.<\/p><p>Jaký MINIMÁLNÍ počet testovacích případů je potřebný k dosažení 100% pokrytí platných přechodů (pokrytí 0-switch)?<\/p>","m":["<p>3<\/p>","<p>4<\/p>","<p>5<\/p>","<p>6<\/p>"],"ok":[1],"vys":{"a":"Není správně. Do koncových stavů vedou 4 různé přechody a každý testovací případ může provést jen jeden z nich; 3 testy nestačí.","b":"Je správně. Každý ze 4 přechodů do koncového stavu vyžaduje vlastní testovací případ a 4 případy zároveň pokryjí všech 8 platných přechodů.","c":"Není správně. 5 testovacích případů není minimum; stačí 4.","d":"Není správně. 6 testovacích případů není minimum; stačí 4."},"obecne":"Sylabus 4.2.4: při pokrytí platných přechodů (0-switch) musí testy provést každý platný přechod. Protože testovací případ končí v koncovém stavu, může provést jen jeden ze 4 přechodů vedoucích do koncových stavů. Stačí 4 případy: Start → Čekání na PIN → 1. pokus → Přístup k účtu; …→ 1. pokus → 2. pokus → Přístup k účtu; …→ 2. pokus → 3. pokus → Přístup k účtu; …→ 3. pokus → Zadržení karty.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UC-4-61","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Stavový model bankomatu obsahuje právě tyto platné přechody:<\/p><table><tr><th>Ze stavu<\/th><th>Událost<\/th><th>Do stavu<\/th><\/tr><tr><td>Start<\/td><td>vložení karty<\/td><td>Čekání na PIN<\/td><\/tr><tr><td>Čekání na PIN<\/td><td>zadání PIN<\/td><td>1. pokus<\/td><\/tr><tr><td>1. pokus<\/td><td>PIN správný<\/td><td>Přístup k účtu<\/td><\/tr><tr><td>1. pokus<\/td><td>PIN chybný<\/td><td>2. pokus<\/td><\/tr><tr><td>2. pokus<\/td><td>PIN správný<\/td><td>Přístup k účtu<\/td><\/tr><tr><td>2. pokus<\/td><td>PIN chybný<\/td><td>3. pokus<\/td><\/tr><tr><td>3. pokus<\/td><td>PIN správný<\/td><td>Přístup k účtu<\/td><\/tr><tr><td>3. pokus<\/td><td>PIN chybný<\/td><td>Zadržení karty<\/td><\/tr><\/table><p>Stavy „Přístup k účtu“ a „Zadržení karty“ jsou koncové. Každý testovací případ začíná ve stavu „Start“ a končí v koncovém stavu.<\/p><p>Jaký MINIMÁLNÍ počet testovacích případů je potřebný k dosažení 100% pokrytí všech stavů?<\/p>","m":["<p>2<\/p>","<p>3<\/p>","<p>4<\/p>","<p>5<\/p>"],"ok":[0],"vys":{"a":"Je správně. Stačí dva případy: Start → Čekání na PIN → 1. pokus → 2. pokus → 3. pokus → Zadržení karty a Start → Čekání na PIN → 1. pokus → Přístup k účtu.","b":"Není správně. Tři testovací případy nejsou minimum; stačí dva.","c":"Není správně. Čtyři testovací případy jsou potřeba pro pokrytí platných přechodů, ne pro pokrytí všech stavů.","d":"Není správně. Pět testovacích případů není minimum; stačí dva."},"obecne":"Sylabus 4.2.4: při pokrytí všech stavů jsou položkami pokrytí stavy. Protože jsou koncové stavy dva a každý test končí v jednom z nich, jsou potřeba alespoň dva testy; jeden test projde všemi pokusy až do zadržení karty, druhý skončí přístupem k účtu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UC-4-62","n":null,"lo":"FL-1.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Pracujete na kritickém projektu, který musí být dodán v napjatém termínu. Tým tvoří vysoce kvalifikovaní odborníci, včetně seniorního testera s rozsáhlými zkušenostmi s testováním a dobrou znalostí byznysové domény. Kvůli velkému časovému omezení musí být testování účinné i efektivní.<\/p><p>Jaký způsob definování testovacích procedur je v této situaci NEJVHODNĚJŠÍ?<\/p>","m":["<p>Podrobné rozepsání každého kroku testu včetně očekávaných výsledků<\/p>","<p>Úplná dokumentace všech testovacích případů a záznam každého kroku<\/p>","<p>Přehled testovacích podmínek a obecných kroků na vysoké úrovni<\/p>","<p>Odvození všech testů formálními technikami a jejich podrobná specifikace<\/p>"],"ok":[2],"vys":{"a":"Není správně. Podrobné rozepisování kroků je časově náročné a u zkušeného testera v napjatém termínu zbytečné.","b":"Není správně. Úplná dokumentace a záznam každého kroku jsou v napjatém termínu neefektivní.","c":"Je správně. Zkušený tester se znalostí domény nepotřebuje podrobný návod; stručný přehled šetří čas a ponechává prostor pro jeho úsudek.","d":"Není správně. Podrobná specifikace všech testů je časově náročná a nevyužívá zkušenosti testera."},"obecne":"Sylabus 1.4.2: proces testování závisí na kontextu – mimo jiné na dovednostech, znalostech a zkušenostech členů týmu a na omezeních projektu (např. čas). Tyto faktory ovlivňují i úroveň podrobnosti testwaru. Seniornímu testerovi s doménovou znalostí v napjatém termínu nejlépe poslouží přehled testovacích podmínek a obecných kroků.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.2","nazev":"Proces testování v souvislostech","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-dva-proces-testovani-v-souvislostech"}},{"id":"UC-4-63","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností uvádí VŠECHNY položky, které lze použít k hodnocení pokrytí dosaženého technikami testování černé skříňky?<\/p><ol type=\"A\"><li>Pokryté podmíněné větve<\/li><li>Pokryté třídy ekvivalence<\/li><li>Pokryté hraniční hodnoty<\/li><li>Pokryté platné přechody (pokrytí 0-switch)<\/li><li>Provedené příkazy<\/li><\/ol>","m":["<p>B a C<\/p>","<p>B, C a D<\/p>","<p>A, C a E<\/p>","<p>B, C, D a E<\/p>"],"ok":[1],"vys":{"a":"Není správně. Chybí D – pokrytí platných přechodů je měřítkem pokrytí testování přechodů stavů, tedy techniky černé skříňky.","b":"Je správně. Třídy ekvivalence, hraniční hodnoty i platné přechody jsou položky pokrytí technik černé skříňky.","c":"Není správně. Větve (A) a příkazy (E) jsou položky pokrytí technik bílé skříňky.","d":"Není správně. Příkazy (E) jsou položkou pokrytí testování bílé skříňky."},"obecne":"Sylabus 4.2: položkami pokrytí technik černé skříňky jsou třídy ekvivalence (4.2.1), hraniční hodnoty (4.2.2), sloupce rozhodovací tabulky (4.2.3) a stavy či přechody (4.2.4; pokrytí platných přechodů se nazývá také 0-switch). Větve a příkazy jsou položky pokrytí technik bílé skříňky (4.3).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UC-4-64","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Stavový diagram obsahuje počáteční stav SS, koncový stav ES a právě těchto 7 platných přechodů:<\/p><table><tr><th>Ze stavu<\/th><th>Do stavu<\/th><\/tr><tr><td>SS<\/td><td>S1<\/td><\/tr><tr><td>S1<\/td><td>S2<\/td><\/tr><tr><td>S1<\/td><td>S3<\/td><\/tr><tr><td>S2<\/td><td>S4<\/td><\/tr><tr><td>S4<\/td><td>S1<\/td><\/tr><tr><td>S3<\/td><td>S4<\/td><\/tr><tr><td>S3<\/td><td>ES<\/td><\/tr><\/table><p>Který z následujících testovacích případů dosáhne 100% pokrytí všech stavů s NEJMENŠÍM počtem přechodů?<\/p>","m":["<p>SS-S1-S2-S4-S1-S3-ES<\/p>","<p>SS-S1-S2-S3-S4-ES<\/p>","<p>SS-S1-S2-S4-S1-S3-S4-S1-S3-ES<\/p>","<p>SS-S1-S4-S2-S1-S3-ES<\/p>"],"ok":[0],"vys":{"a":"Je správně. Prochází jen platnými přechody, navštíví všech 6 stavů a potřebuje k tomu jen 6 přechodů.","b":"Není správně. Obsahuje neplatné přechody S2→S3 a S4→ES.","c":"Není správně. Dosahuje pokrytí všech stavů, ale potřebuje 9 přechodů, tedy více než možnost a).","d":"Není správně. Obsahuje neplatné přechody S1→S4 a S2→S1."},"obecne":"Sylabus 4.2.4: při pokrytí všech stavů jsou položkami pokrytí stavy a testovací případ smí procházet jen platnými přechody. Cesta SS–S1–S2–S4–S1–S3–ES navštíví všech 6 stavů nejkratším způsobem z nabízených.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UC-4-65","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Pokud teplota klesne pod 18 stupňů, zapne se topení. Když teplota dosáhne 21 stupňů, topení se vypne. Teplota se měří v celých stupních. Jaká je minimální sada vstupních hodnot pro pokrytí všech platných tříd ekvivalence?<\/p>","m":["<p>18, 20 a 22 stupňů<\/p>","<p>15, 19 a 25 stupňů<\/p>","<p>17, 18, 20 a 21 stupňů<\/p>","<p>16 a 26 stupňů<\/p>"],"ok":[1],"vys":{"a":"Není správně. 18 a 20 leží ve stejné třídě a chybí hodnota z třídy pod 18.","b":"Je správně. 15 pokrývá třídu pod 18, 19 třídu 18–20 a 25 třídu 21 a více – tři hodnoty pro tři třídy.","c":"Není správně. Sada pokrývá všechny třídy, ale není minimální – 18 a 20 leží ve stejné třídě.","d":"Není správně. Chybí hodnota z třídy 18–20."},"obecne":"<p>V tomto příkladu máme tři třídy ekvivalence:<br>1 – <strong>teplota nižší než 18<\/strong> -&gt; topení se zapne<\/p><p>2 – <strong>teplota mezi 18 a 20<\/strong> (včetně) -&gt; nic se nestane<\/p><p>3 – <strong>teplota dosáhne 21<\/strong> (teplota &gt;= 21) -&gt; topení se vypne<\/p><p><br><\/p><p>Správná volba musí obsahovat jeden testovací případ pro každou třídu.<\/p><p><br><\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-67","n":null,"lo":"FL-4.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NEJLÉPE vystihuje průzkumné testování?<\/p>","m":["<p>Předvídání nebo odhadování, kde by se mohly vyskytnout defekty<\/p>","<p>Systematický přístup k identifikaci tříd ekvivalence vstupů<\/p>","<p>Souběžný návrh, provádění a vyhodnocování testů spojený s učením se<\/p>","<p>Testování prováděné výhradně podle předem připravených podrobných skriptů<\/p>"],"ok":[2],"vys":{"a":"Není správně. Toto je popis odhadování chyb.","b":"Není správně. Toto je popis rozdělení tříd ekvivalence.","c":"Je správně. Při průzkumném testování jsou testy současně navrhovány, prováděny a vyhodnocovány, zatímco tester získává znalosti o testovaném objektu.","d":"Není správně. Průzkumné testování naopak nepracuje s předem připravenými podrobnými skripty."},"obecne":"<p><strong>Podle sylabu (kap. 4.4.2):<\/strong> Při průzkumném testování jsou testy současně navrhovány, prováděny a vyhodnocovány, zatímco testeři získávají znalosti o testovaném objektu. Testování se (mimo jiné) používá k získání dalších informací o testovaném objektu, k jeho hlubšímu prozkoumání pomocí cílených testů a k vytvoření testů pro dosud neotestované oblasti.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.2","nazev":"Průzkumné testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-dva-pruzkumne-testovani"}},{"id":"UC-4-68","n":null,"lo":"FL-4.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co znamená, že sada testů dosáhla 90% pokrytí příkazů?<\/p>","m":["<p>Na tomto softwaru bylo spuštěno 9 z každých 10 testů<\/p>","<p>Touto sadou testů bylo prověřeno 9 z každých 10 výsledků rozhodnutí<\/p>","<p>Touto sadou testů bylo prověřeno 9 z každých 10 větví<\/p>","<p>Touto sadou testů bylo prověřeno 9 z každých 10 spustitelných příkazů<\/p>"],"ok":[3],"vys":{"a":"Není správně. Podíl spuštěných testů je metrika provedení testů, nikoli pokrytí kódu.","b":"Není správně. Výsledky rozhodnutí souvisejí s pokrytím větví, nikoli příkazů.","c":"Není správně. Podíl pokrytých větví je pokrytí větví, nikoli příkazů.","d":"Je správně. Pokrytí příkazů je podíl spustitelných příkazů provedených testy ze všech spustitelných příkazů."},"obecne":"Sylabus 4.3.1: při testování příkazů jsou položkami pokrytí spustitelné příkazy a pokrytí se měří jako podíl spustitelných příkazů pokrytých testy ze všech spustitelných příkazů. 90% pokrytí příkazů tedy znamená, že bylo provedeno 9 z každých 10 spustitelných příkazů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"}},{"id":"UC-4-69","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Stavový diagram obsahuje počáteční stav SS, koncový stav ES a právě těchto 7 platných přechodů:<\/p><table><tr><th>Ze stavu<\/th><th>Do stavu<\/th><\/tr><tr><td>SS<\/td><td>S1<\/td><\/tr><tr><td>S1<\/td><td>S2<\/td><\/tr><tr><td>S1<\/td><td>S3<\/td><\/tr><tr><td>S2<\/td><td>S4<\/td><\/tr><tr><td>S4<\/td><td>S1<\/td><\/tr><tr><td>S3<\/td><td>S4<\/td><\/tr><tr><td>S3<\/td><td>ES<\/td><\/tr><\/table><p>Který z následujících testovacích případů dosáhne 100% pokrytí platných přechodů (pokrytí 0-switch) s NEJMENŠÍM počtem přechodů?<\/p>","m":["<p>SS-S1-S2-S4-S1-S3-S4-S1-S3-ES<\/p>","<p>SS-S1-S2-S3-S4-S3-S4-ES<\/p>","<p>SS-S1-S2-S4-S1-S3-S4-S1-S3-S4-S1-S3-ES<\/p>","<p>SS-S1-S2-S4-S1-S3-ES<\/p>"],"ok":[0],"vys":{"a":"Je správně. Pokrývá všech 7 platných přechodů a potřebuje k tomu jen 9 přechodů.","b":"Není správně. Obsahuje neplatné přechody S2→S3, S4→S3 a S4→ES.","c":"Není správně. Pokrývá všechny platné přechody, ale s 12 přechody, tedy zbytečně dlouhou cestou.","d":"Není správně. Pokrývá všechny stavy, ale nepokrývá platný přechod S3→S4."},"obecne":"Sylabus 4.2.4: pokrytí platných přechodů (0-switch) vyžaduje provést každý platný přechod: SS→S1, S1→S2, S1→S3, S2→S4, S4→S1, S3→S4, S3→ES. Všechny je z nabízených možností nejkratší cestou pokrývá SS-S1-S2-S4-S1-S3-S4-S1-S3-ES.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UC-4-70","n":null,"lo":"FL-4.2.2","k":"K3","k3":false,"vyber":1,"q":"<p>Rozhodnutí „if (x ≤ 10) …“ bylo nesprávně implementováno jako „if (x = 10) …“. Kterou techniku je NEJLEPŠÍ použít k nalezení tohoto defektu?<\/p>","m":["<p>Testování větví<\/p>","<p>Tříhodnotová analýza hraničních hodnot<\/p>","<p>Testování přechodů stavů<\/p>","<p>Dvouhodnotová analýza hraničních hodnot<\/p>"],"ok":[1],"vys":{"a":"Není správně. Pokrytí větví lze dosáhnout např. hodnotami 10 a 20, které defekt neodhalí.","b":"Je správně. Tříhodnotová BVA testuje u hranice 10 i hodnotu 9, která chybnou implementaci pravděpodobně odhalí.","c":"Není správně. Testování přechodů stavů se zaměřuje na stavy a přechody, nikoli na hraniční hodnoty podmínky.","d":"Není správně. Dvouhodnotová BVA testuje jen hodnoty 10 a 11, které chybnou implementaci neodhalí."},"obecne":"Sylabus 4.2.2 uvádí právě tento příklad: žádný z testů dvouhodnotové BVA (x = 10, x = 11) chybnou implementaci „x = 10“ neodhalí, kdežto test x = 9 odvozený tříhodnotovou BVA ji pravděpodobně odhalí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-71","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Vstupem do systému kurzu testování softwaru je počet přihlášených studentů. Kurz může mít libovolný kladný počet studentů až do zadané kapacity kurzu. Tříhodnotovou analýzou hraničních hodnot byl pro minimum a maximum platné třídy vytvořen seznam testovacích hodnot.<\/p><p>Který z následujících seznamů je správný?<\/p>","m":["<p>0, 1, 10, 100, kapacita, kapacita + 1<\/p>","<p>−1, 0, 1, kapacita − 1, kapacita, kapacita + 1<\/p>","<p>0, 1, 2, kapacita − 1, kapacita, kapacita + 1<\/p>","<p>0, 1, 2, kapacita + 1, velmi velké číslo<\/p>"],"ok":[2],"vys":{"a":"Není správně. Hodnoty 10 a 100 nejsou položkami pokrytí a chybí 2 a kapacita − 1.","b":"Není správně. Nejmenší platná hodnota je 1 (0 není kladné číslo), sousedé hranice 1 jsou 0 a 2, nikoli −1.","c":"Je správně. Platná třída je 1 až kapacita; u hranice 1 testujeme 0, 1, 2 a u hranice kapacita testujeme kapacita − 1, kapacita, kapacita + 1.","d":"Není správně. Chybí hodnoty kapacita − 1 a kapacita; „velmi velké číslo“ není položkou pokrytí."},"obecne":"Sylabus 4.2.2: nejmenší kladný počet studentů je 1, největší je kapacita. Při tříhodnotové BVA testujeme každou hraniční hodnotu a oba její sousedy: 0, 1, 2 a kapacita − 1, kapacita, kapacita + 1.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-72","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Jak se nazývají větve, které obvykle odpovídají pravdivému nebo nepravdivému výsledku rozhodnutí „if … then“, výsledku příkazu switch/case nebo rozhodnutí, zda ukončit, nebo pokračovat v cyklu?<\/p>","m":["<p>Větve příkazů<\/p>","<p>Větve kódu<\/p>","<p>Nepodmíněné větve<\/p>","<p>Podmíněné větve<\/p>"],"ok":[3],"vys":{"a":"Není správně. Pojem „větve příkazů“ sylabus nepoužívá.","b":"Není správně. Pojem „větve kódu“ sylabus jako druh větví nerozlišuje.","c":"Není správně. Nepodmíněné větve jsou přímé přechody v kódu bez rozhodnutí.","d":"Je správně. Sylabus takové větve nazývá podmíněné větve."},"obecne":"<p><strong>Podle sylabu (kap. 4.3.2):<\/strong> Při dosažení 100% pokrytí větví jsou všechny nepodmíněné a podmíněné větve v kódu pokryty testovacími případy. <strong>Podmíněné větve obvykle odpovídají pravdivému nebo nepravdivému výsledku z podmínky (IF / THEN / ELSE), výsledku z vícecestné podmínky (SWITCH / CASE) nebo rozhodnutí, zda ukončit nebo pokračovat ve smyčce (FOR / NEXT, WHILE / DO, DO / WHILE, REPEAT / UNTIL).<\/strong> Opět ale platí, že otestování větve pomocí testovacího případu nemusí vždy odhalit defekt, například nemusí detekovat defekt vyžadující provedení určité cesty v kódu.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UC-4-73","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Digitální „duhový“ teploměr zobrazuje okolní teplotu 7 barvami. Každá barva pokrývá rozsah právě 5 stupňů; provozní minimum je −5 a maximum 30 stupňů. Které z následujících hodnot by NEJMÉNĚ PRAVDĚPODOBNĚ byly identifikovány při použití analýzy hraničních hodnot?<\/p>","m":["<p>8, 15<\/p>","<p>25, 30<\/p>","<p>0, 5<\/p>","<p>15, 20<\/p>"],"ok":[0],"vys":{"a":"Je správně. Hodnota 8 leží uvnitř pásma 5–10, hraniční hodnotou tedy není.","b":"Není správně. 25 i 30 leží na hranicích pásem (30 je navíc provozní maximum).","c":"Není správně. 0 i 5 leží na hranicích pásem.","d":"Není správně. 15 i 20 leží na hranicích pásem."},"obecne":"Sylabus 4.2.2: 7 pásem po 5 stupních pokrývá rozsah −5 až 30 a hranice pásem leží na násobcích pěti (−5, 0, 5, 10, 15, 20, 25, 30). Všechny nabízené hodnoty kromě 8 jsou hraničními hodnotami; 8 by se mohla objevit nanejvýš jako soused hraniční hodnoty při tříhodnotové BVA.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-74","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Testujete modul kódu. Jak určíte dosažené pokrytí větví?<\/p>","m":["<p>Vezmete počet otestovaných větví a vydělíte jej celkovým počtem spustitelných příkazů v modulu<\/p>","<p>Vezmete počet otestovaných větví a vydělíte jej celkovým počtem podmíněných a nepodmíněných větví v modulu<\/p>","<p>Vezmete počet otestovaných větví a vydělíte jej celkovým počtem rozhodnutí v modulu<\/p>","<p>Vezmete počet otestovaných rozhodnutí a vydělíte jej celkovým počtem řádků kódu v modulu<\/p>"],"ok":[1],"vys":{"a":"Není správně. Pokrytí větví se počítá vzhledem k celkovému počtu větví, nikoli spustitelných příkazů.","b":"Je správně. Pokrytí větví je počet větví pokrytých testy vydělený celkovým počtem podmíněných i nepodmíněných větví.","c":"Není správně. Jmenovatelem je celkový počet větví, nikoli počet rozhodnutí.","d":"Není správně. Pokrytí větví nesouvisí s počtem řádků kódu."},"obecne":"<p><strong>Podle sylabu (kap. 4.3.2):<\/strong> Při testování větví jsou položkami pokrytí větve a cílem je navrhovat testovací případy tak, aby došlo k pokrytí větví v určité části kódu při definované akceptovatelné úrovni pokrytí. <strong>Pokrytí se měří jako počet větví pokrytých testy k celkovému počtu větví (obvykle vyjádřeno v procentech).<\/strong><\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UC-4-75","n":null,"lo":"FL-4.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Je dán následující fragment programu:<\/p><pre>if day = Monday\n   then příkaz a\nelse\n   příkaz b\nend if\nif day = Tuesday\n   then příkaz c\nend if<\/pre><p>Jaký je minimální počet testovacích případů potřebný k dosažení 100% pokrytí příkazů?<\/p>","m":["<p>1<\/p>","<p>2<\/p>","<p>3<\/p>","<p>4<\/p>"],"ok":[1],"vys":{"a":"Není správně. Příkazy a a b leží ve vzájemně se vylučujících větvích, jeden test je nemůže provést oba.","b":"Je správně. Test „Monday“ provede příkaz a, test „Tuesday“ provede příkazy b a c.","c":"Není správně. Tři testy nejsou potřeba; příkazy b a c lze provést jedním testem.","d":"Není správně. Čtyři testy nejsou potřeba; stačí dva."},"obecne":"Sylabus 4.3.1: pro 100% pokrytí příkazů musí být každý spustitelný příkaz proveden alespoň jednou. Hodnota Monday provede příkaz a; hodnota Tuesday provede příkaz b (else první podmínky) i příkaz c. Stačí tedy 2 testovací případy.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"}},{"id":"UC-4-76","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Potřebujete dosáhnout určité úrovně pokrytí kódu u softwarového produktu, který váš tým testuje. Jakou kategorii technik testování byste měli použít?<\/p>","m":["<p>Techniky založené na spolupráci<\/p>","<p>Techniky testování černé skříňky<\/p>","<p>Techniky založené na zkušenostech<\/p>","<p>Techniky testování bílé skříňky<\/p>"],"ok":[3],"vys":{"a":"Není správně. Přístupy založené na spolupráci se zaměřují na prevenci defektů, nikoli na pokrytí kódu.","b":"Není správně. Techniky černé skříňky vycházejí ze specifikovaného chování a pokrytí kódu přímo necílí.","c":"Není správně. Techniky založené na zkušenostech vycházejí ze znalostí testera a pokrytí kódu neměří.","d":"Je správně. Techniky bílé skříňky (založené na struktuře), např. testování příkazů a větví, cílí právě na pokrytí kódu."},"obecne":"Sylabus 4.1 a 4.3: techniky testování bílé skříňky vycházejí z vnitřní struktury testovaného objektu a jejich položky pokrytí (příkazy, větve) umožňují měřit a cíleně zvyšovat pokrytí kódu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UC-4-77","n":null,"lo":"FL-4.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jak se určuje pokrytí příkazů?<\/p>","m":["<p>Počet pokrytých spustitelných příkazů vydělený celkovým počtem spustitelných příkazů, v procentech<\/p>","<p>Počet pokrytých výsledků rozhodnutí vydělený celkovým počtem výsledků rozhodnutí, v procentech<\/p>","<p>Počet provedených příkazů vydělený celkovým počtem řádků kódu včetně komentářů, v procentech<\/p>","<p>Počet provedených testovacích případů vydělený počtem navržených testovacích případů, v procentech<\/p>"],"ok":[0],"vys":{"a":"Je správně. Pokrytí příkazů je podíl spustitelných příkazů pokrytých testy ze všech spustitelných příkazů, obvykle v procentech.","b":"Není správně. Výsledky rozhodnutí se týkají pokrytí větví, nikoli příkazů.","c":"Není správně. Jmenovatelem jsou spustitelné příkazy, nikoli všechny řádky kódu včetně komentářů.","d":"Není správně. Podíl provedených testů je metrika postupu testování, nikoli pokrytí příkazů."},"obecne":"<p><strong>Podle sylabu (kap. 4.3.1):<\/strong> Při testování příkazů jsou položkami pokrytí spustitelné příkazy. Cílem je navrhovat takové testovací případy, které pokryjí příkazy v určité části kódu při definované akceptovatelné úrovni pokrytí. <strong>Pokrytí se měří jako počet spustitelných příkazů pokrytých testy k celkovému počtu spustitelných příkazů v kódu (obvykle vyjádřeno v procentech).<\/strong><\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"}},{"id":"UC-4-78","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Testujete lékařskou aplikaci, kterou smějí používat pouze teenageři, tj. osoby ve věku 13 až 19 let včetně (věk je celé číslo). Která z následujících sad vstupů dosáhne 100% pokrytí rozdělením tříd ekvivalence?<\/p>","m":["<p>13, 18, 25<\/p>","<p>12, 15, 20<\/p>","<p>9, 15, 18<\/p>","<p>12, 15, 18<\/p>"],"ok":[1],"vys":{"a":"Není správně. Chybí hodnota z neplatné třídy pod 13.","b":"Je správně. 12 pokrývá třídu pod 13, 15 platnou třídu 13–19 a 20 třídu nad 19.","c":"Není správně. Chybí hodnota z neplatné třídy nad 19; 15 a 18 leží ve stejné třídě.","d":"Není správně. Chybí hodnota z neplatné třídy nad 19."},"obecne":"Sylabus 4.2.1: vstup věku tvoří tři třídy ekvivalence – méně než 13 (neplatná), 13 až 19 (platná) a více než 19 (neplatná). Pro 100% pokrytí stačí jedna hodnota z každé třídy, např. 12, 15 a 20.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UC-4-80","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Navrhli jste testovací případy, které poskytují 100% pokrytí příkazů a 100% pokrytí větví pro následující fragment kódu:<\/p><pre>if (grade1 &gt; grade2)\n    print(\"Vyšší je známka 1\")\nelse\n    print(\"Vyšší je známka 2\")<\/pre><p>Za konstrukci if/else byly do kódu přidány tyto příkazy:<\/p><pre>print(\"Známka 1 je\", grade1)\nprint(\"Známka 2 je\", grade2)\nprint(\"Součet známek je\", grade1 + grade2)<\/pre><p>Kolik dalších testovacích případů je po této změně potřeba k dosažení 100% pokrytí příkazů i 100% pokrytí větví?<\/p>","m":["<p>Pro 100% pokrytí větví budou potřeba dva další testovací případy, jeden z nich dosáhne 100% pokrytí příkazů<\/p>","<p>Pro 100% pokrytí větví budou potřeba dva další testovací případy, pro pokrytí příkazů nebudou potřeba žádné další testovací případy<\/p>","<p>Nebudou potřeba žádné další testovací případy, dříve navržené testovací případy dosáhnou 100% pokrytí příkazů i větví<\/p>","<p>Pro 100% pokrytí větví bude potřeba jeden další testovací případ<\/p>"],"ok":[2],"vys":{"a":"Není správně. Nové příkazy se provedou při každém testu; žádné další testy nejsou potřeba.","b":"Není správně. Přidáním nepodmíněných příkazů nevznikají nové podmíněné větve.","c":"Je správně. Nové příkazy jsou nepodmíněné a provede je každý stávající test, takže stávající sada zůstává na 100% pokrytí příkazů i větví.","d":"Není správně. Nové příkazy neobsahují žádné rozhodnutí, nevzniká tedy žádná nová větev k pokrytí."},"obecne":"<p>Nové příkazy přidané do kódu se provedou vždy, protože neobsahují žádná rozhodnutí, smyčky ani větvení. Proto není potřeba do již navržené sady testů přidávat žádné nové testovací případy.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UC-5-12","n":null,"lo":"FL-5.1.6","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o testovací pyramidě <strong>NENÍ<\/strong> pravdivé?<\/p>","m":["<p>Počet a pojmenování vrstev pyramidy se mohou v různých modelech lišit.<\/p>","<p>Čím vyšší vrstva pyramidy, tím nižší granularita a izolace testů.<\/p>","<p>Testovací pyramida zdůrazňuje větší počet testů na nižších úrovních testování.<\/p>","<p>Čím blíže k vrcholu pyramidy, tím formálnější by měla být automatizace testů.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Tvrzení je pravdivé – např. původní model má vrstvy jednotkové testy, testy služeb a testy UI, jiný model testy komponent, integrační testy komponent a E2E testy.","b":"Není správně. Tvrzení je pravdivé – s výškou vrstvy klesá granularita i izolace testů a roste doba jejich provádění.","c":"Není správně. Tvrzení je pravdivé – testů ve spodní vrstvě je potřeba velké množství, v horní vrstvě jen několik.","d":"Je správně. Tvrzení není pravdivé – pyramida popisuje granularitu, izolaci a dobu provádění testů, o formálnosti automatizace nic neříká."},"obecne":"Sylabus 5.1.6: Testovací pyramida ukazuje, že testy mohou mít různou granularitu. Čím vyšší vrstva, tím nižší granularita a izolace testů a delší doba provádění; testů ve spodní vrstvě je potřeba hodně, v horní jen několik. Počet a pojmenování vrstev se mohou lišit. O formálnosti automatizace pyramida nic neříká.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.6","nazev":"Testovací pyramida","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sest-testovaci-pyramida"}},{"id":"UC-5-18","n":null,"lo":"FL-5.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Zvažte následující část plánu testování:<\/p><p><em>Testování musí být dokončeno v napjatém termínu dvou týdnů kvůli nedávnému vydání konkurenční aplikace.<\/em><\/p><p>Do které části plánu testování tato část patří?<\/p>","m":["<p>Předpoklady a omezení<\/p>","<p>Přístup k testování<\/p>","<p>Plán komunikace<\/p>","<p>Registr rizik<\/p>"],"ok":[0],"vys":{"a":"Je správně. Pevný termín dokončení testování daný situací na trhu je omezení testovacího projektu.","b":"Není správně. Přístup k testování popisuje úrovně testování, typy testů, techniky testování, vstupní a výstupní kritéria apod.","c":"Není správně. Plán komunikace popisuje formy a četnost komunikace a šablony dokumentace.","d":"Není správně. Registr rizik obsahuje produktová a projektová rizika; pevný termín je dané omezení, nikoli potenciální událost."},"obecne":"Sylabus 5.1.1: Plán testování obvykle obsahuje kontext testování (rozsah, cíle testování, testovací báze), předpoklady a omezení testovacího projektu, definici zainteresovaných stran, plán komunikace, registr rizik, přístup k testování a rozpočet a harmonogram. Povinnost dokončit testování v napjatém dvoutýdenním termínu je omezení testovacího projektu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.1.1","nazev":"Účel a obsah plánu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-jedna-ucel-a-obsah-planu-testovani"}},{"id":"UC-5-19","n":null,"lo":"FL-5.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Následující úryvky pocházejí z různých částí plánu testování.<\/p><p><em>i. Rozpočet na testování tohoto projektu byl stanoven na 50 000 USD. Tento rozpočet pokryje náklady na hardware, softwarové licence, zdroje pro testování a další výdaje související s testováním. Jakékoli výdaje přesahující přidělený rozpočet vyžadují schválení projektovým manažerem.<\/em><\/p><p><em>ii.<\/em><\/p><ul><li><em>Všechny kritické defekty byly opraveny a ověřeny.<\/em><\/li><li><em>Nezůstávají otevřené žádné defekty s vysokou prioritou.<\/em><\/li><li><em>Všechny testovací případy byly úspěšně provedeny.<\/em><\/li><li><em>Bylo dosaženo pokrytí testy alespoň 95 %.<\/em><\/li><\/ul><p>Do kterých částí plánu testování tyto úryvky patří?<\/p>","m":["<p>i patří do rozpočtu a harmonogramu, ii do kontextu testování.<\/p>","<p>i patří do rozpočtu a harmonogramu, ii do přístupu k testování.<\/p>","<p>i patří do předpokladů a omezení, ii do rozpočtu a harmonogramu.<\/p>","<p>i patří do kontextu testování, ii do přístupu k testování.<\/p>"],"ok":[1],"vys":{},"obecne":"Sylabus 5.1.1: Plán testování obsahuje mj. část rozpočet a harmonogram (sem patří úryvek i) a přístup k testování, který zahrnuje mimo jiné vstupní a výstupní kritéria. Úryvek ii je seznam výstupních kritérií (opravené kritické defekty, žádné otevřené defekty s vysokou prioritou, provedení testů, dosažené pokrytí), patří tedy do přístupu k testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.1","nazev":"Účel a obsah plánu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-jedna-ucel-a-obsah-planu-testovani"}},{"id":"UC-5-20","n":null,"lo":"FL-5.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících činností <strong>NENÍ<\/strong> odpovědností testerů zapojených do plánování vydání?<\/p>","m":["<p>Specifikace testovatelných uživatelských scénářů a akceptačních kritérií<\/p>","<p>Podíl na analýzách projektových a produktových rizik<\/p>","<p>Odhad pracnosti vývoje spojené s uživatelskými scénáři<\/p>","<p>Stanovení přístupu k testování a plánování testování pro vydání<\/p>"],"ok":[2],"vys":{},"obecne":"<p>Podle sylabu (kap. 5.1.2) se testeři zapojení do plánování vydání podílí na specifikaci testovatelných uživatelských scénářů a akceptačních kritérií, podílí se na analýzách projektových a produktových rizik, provádí odhady pracnosti potřebné k <strong>testování<\/strong> uživatelských scénářů, stanovují přístup k testování a plánují testování související s vydáním. Odhad pracnosti <strong>vývoje<\/strong> mezi jejich odpovědnosti nepatří.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.2","nazev":"Přínos testerů při plánování iterací a vydání","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-dva-prinos-testeru-pri-planovani-iteraci-a-vydani"}},{"id":"UC-5-21","n":null,"lo":"FL-5.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Kterou z následujících činností by tester prováděl během plánování vydání?<\/p>","m":["<p>Podrobná analýza rizik uživatelských scénářů<\/p>","<p>Stanovení testovatelnosti uživatelských scénářů<\/p>","<p>Rozklad uživatelských scénářů do testovacích úkolů<\/p>","<p>Podíl na analýzách projektových a produktových rizik<\/p>"],"ok":[3],"vys":{"a":"Není správně. Podrobná analýza rizik uživatelských scénářů patří k plánování iterace.","b":"Není správně. Stanovení testovatelnosti uživatelských scénářů patří k plánování iterace.","c":"Není správně. Rozklad uživatelských scénářů do (testovacích) úkolů patří k plánování iterace.","d":"Je správně. Při plánování vydání se tester podílí na analýzách projektových a produktových rizik."},"obecne":"<p>Podle sylabu (kap. 5.1.2) se testeři zapojení do plánování vydání <strong>podílí na analýzách projektových a produktových rizik<\/strong>. Podrobná analýza rizik uživatelských scénářů, stanovení jejich testovatelnosti a rozklad do (testovacích) úkolů jsou činnosti testerů při plánování iterací.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.2","nazev":"Přínos testerů při plánování iterací a vydání","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-dva-prinos-testeru-pri-planovani-iteraci-a-vydani"}},{"id":"UC-5-22","n":null,"lo":"FL-5.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících činností <strong>NENÍ<\/strong> odpovědností testerů zapojených do plánování iterací?<\/p>","m":["<p>Stanovení přístupu k testování pro celé vydání<\/p>","<p>Stanovení testovatelnosti uživatelských scénářů<\/p>","<p>Podíl na podrobné analýze rizik uživatelských scénářů<\/p>","<p>Rozklad uživatelských scénářů do úkolů, zejména testovacích<\/p>"],"ok":[0],"vys":{},"obecne":"Sylabus 5.1.2: Testeři zapojení do plánování iterací se podílejí na podrobné analýze rizik uživatelských scénářů, stanovují jejich testovatelnost, podílejí se na jejich rozkladu do úkolů (zejména testovacích), odhadují pracnost všech testovacích úkolů a zpřesňují funkcionální a nefunkcionální aspekty testovaného objektu. Stanovení přístupu k testování a plánování testování pro vydání patří k plánování vydání.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.2","nazev":"Přínos testerů při plánování iterací a vydání","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-dva-prinos-testeru-pri-planovani-iteraci-a-vydani"}},{"id":"UC-5-23","n":null,"lo":"FL-5.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Kterou z následujících činností by tester prováděl během plánování iterace?<\/p>","m":["<p>Specifikace testovatelných uživatelských scénářů a akceptačních kritérií<\/p>","<p>Podíl na podrobné analýze rizik uživatelských scénářů<\/p>","<p>Plánování testování pro vydání<\/p>","<p>Stanovení přístupu k testování<\/p>"],"ok":[1],"vys":{"a":"Není správně. Specifikace testovatelných uživatelských scénářů a akceptačních kritérií je činností testera při plánování vydání.","b":"Je správně. Při plánování iterace se tester podílí na podrobné analýze rizik uživatelských scénářů.","c":"Není správně. Testování pro vydání se plánuje při plánování vydání.","d":"Není správně. Přístup k testování se stanovuje při plánování vydání."},"obecne":"<p>Podle sylabu (kap. 5.1.2) se testeři zapojení do plánování iterací <strong>podílí na podrobné analýze rizik uživatelských scénářů<\/strong>. Specifikace testovatelných uživatelských scénářů a akceptačních kritérií, plánování testování pro vydání a stanovení přístupu k testování jsou činnosti testerů při plánování vydání.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.2","nazev":"Přínos testerů při plánování iterací a vydání","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-dva-prinos-testeru-pri-planovani-iteraci-a-vydani"}},{"id":"UC-5-24","n":null,"lo":"FL-5.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Které DVĚ z následujících možností NEJSOU součástí vstupních kritérií pro systémové testování?<\/p><p>i. Dostupnost testovacích dat<br>ii. Všechny smoke testy prošly<br>iii. Bylo provedeno statické testování<br>iv. Počet nevyřešených defektů<br>v. Dostupnost testovací báze<\/p>","m":["<p>ii a v<\/p>","<p>i a iv<\/p>","<p>iii a iv<\/p>","<p>i a iii<\/p>"],"ok":[2],"vys":{"a":"Není správně. Úspěšnost smoke testů (ii) i dostupnost testovací báze (v) jsou typická vstupní kritéria.","b":"Není správně. Dostupnost testovacích dat (i) je typické vstupní kritérium.","c":"Je správně. Provedení statického testování (iii) a počet nevyřešených defektů (iv) sylabus uvádí jako typická výstupní kritéria.","d":"Není správně. Dostupnost testovacích dat (i) je typické vstupní kritérium."},"obecne":"<p>Podle sylabu (kap. 5.1.3) patří mezi typická vstupní kritéria dostupnost zdrojů (např. testovací data), dostupnost testwaru (např. testovací báze) a počáteční úroveň kvality testovaného objektu (např. úspěšnost všech smoke testů) – to jsou možnosti i, ii a v. Naopak „provedení statického testování“ a „počet nevyřešených defektů“ sylabus uvádí jako typická <strong>výstupní<\/strong> kritéria. Vstupními kritérii tedy nejsou iii a iv.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"}},{"id":"UC-5-25","n":null,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"<p>Společnost používá k odhadu pracnosti testování svých projektů poměry. V předchozím projektu, který je podobný aktuálně plánovanému projektu, byl poměr pracnosti vývoje k pracnosti testování 2:1. Očekává se, že pracnost vývoje bude 400 člověko-dnů.<\/p><p>Jaká je odhadovaná pracnost testování nového projektu?<\/p>","m":["<p>200 člověkodnů.<\/p>","<p>250 člověkodnů.<\/p>","<p>300 člověkodnů.<\/p>","<p>400 člověkodnů.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Pracnost testování = 400 / 2 = 200 člověkodnů.","b":"Není správně. 250 člověkodnů neodpovídá poměru 2 : 1.","c":"Není správně. 300 člověkodnů by odpovídalo poměru 4 : 3.","d":"Není správně. 400 člověkodnů je pracnost vývoje (poměr 1 : 1), ne testování."},"obecne":"<p>Odhad na základě poměrů (sylabus kap. 5.1.4): pracnost vývoje : pracnost testování = 2 : 1, tedy pracnost testování = 400 / 2 = <strong>200 člověko-dnů<\/strong>. (Obdobně sylabus uvádí příklad: poměr 3:2 a pracnost vývoje 600 člověko-dnů → pracnost testování 400 člověko-dnů.)<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UC-5-26","n":null,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"<p>Společnost používá tříbodový odhad k odhadu pracnosti testování nové funkce. Tým expertů dospěl k následujícím odhadům:<\/p><p>• nejoptimističtější odhad: 6 člověko-hodin<\/p><p>• nejpravděpodobnější odhad: 12 člověko-hodin<\/p><p>• nejpesimističtější odhad: 18 člověko-hodin<\/p><p>Jaký je výsledný odhad?<\/p>","m":["<p>9 člověko-hodin<\/p>","<p>14 člověko-hodin<\/p>","<p>12 člověko-hodin<\/p>","<p>10 člověko-hodin<\/p>"],"ok":[2],"vys":{},"obecne":"<p>Tříbodový odhad (sylabus kap. 5.1.4): E = (a + 4 * m + b) / 6 = (6 + 4 * 12 + 18) / 6 = (6 + 48 + 18) / 6 = 72 / 6 = <strong>12 člověko-hodin<\/strong>.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UC-5-27","n":null,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"<p>Tým používá tříbodový odhad včetně chyby měření k odhadu pracnosti testování potřebné pro novou funkci. Tým expertů dospěl k následujícím odhadům:<\/p><p>• nejoptimističtější odhad: 6 člověko-hodin<\/p><p>• nejpravděpodobnější odhad: 12 člověko-hodin<\/p><p>• nejpesimističtější odhad: 18 člověko-hodin<\/p><p>Jaký je výsledný odhad?<\/p>","m":["<p>mezi 9 a 11 člověko-hodinami<\/p>","<p>mezi 11 a 13 člověko-hodinami<\/p>","<p>mezi 10 a 14 člověko-hodinami<\/p>","<p>mezi 13 a 15 člověko-hodinami<\/p>"],"ok":[2],"vys":{},"obecne":"<p>Podle sylabu (kap. 5.1.4) umožňuje tříbodový odhad vypočítat chybu měření ve formě směrodatné odchylky SD = (b - a) / 6.<\/p><p>E = (6 + 4 * 12 + 18) / 6 = 12; SD = (18 - 6) / 6 = 2. Výsledný odhad je tedy 12 ± 2 člověko-hodin, tj. <strong>mezi 10 a 14 člověko-hodinami<\/strong>.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UC-5-29","n":null,"lo":"FL-5.1.6","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o testovací pyramidě je <strong>PRAVDIVÉ<\/strong>?<\/p>","m":["<p>Počet testů je ve všech vrstvách pyramidy stejný.<\/p>","<p>Počet testů nesouvisí s vrstvou pyramidy.<\/p>","<p>Počet testů se směrem k vrcholu pyramidy snižuje.<\/p>","<p>Počet testů se směrem k vrcholu pyramidy zvyšuje.<\/p>"],"ok":[2],"vys":{},"obecne":"<p>Podle sylabu (kap. 5.1.6) jsou testy ve spodní vrstvě malé, izolované a rychlé, takže k dosažení rozumného pokrytí je jich obvykle potřeba velké množství; komplexní E2E testy v horní vrstvě ověřují velkou část funkcionality, takže je jich zapotřebí jen několik. Počet testů se tedy směrem k vrcholu pyramidy <strong>snižuje<\/strong>.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.6","nazev":"Testovací pyramida","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sest-testovaci-pyramida"}},{"id":"UC-5-30","n":null,"lo":"FL-5.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího <strong>NENÍ<\/strong> cílem analýzy produktových rizik z hlediska testování?<\/p>","m":["<p>Stanovit priority testování s cílem nalézt kritické defekty co nejdříve<\/p>","<p>Nasměrovat úsilí při testování tak, aby došlo k minimalizaci reziduální úrovně produktových rizik<\/p>","<p>Poskytnout povědomí o produktových rizicích<\/p>","<p>Zajistit, aby po vydání nezůstalo žádné reziduální produktové riziko<\/p>"],"ok":[3],"vys":{},"obecne":"Sylabus 5.2.3: Z hlediska testování je cílem analýzy produktových rizik poskytnout povědomí o produktových rizicích a nasměrovat úsilí při testování tak, aby se minimalizovala reziduální úroveň produktových rizik; její výsledky se mj. používají ke stanovení priorit testování s cílem nalézt kritické defekty co nejdříve. Produktové riziko však testováním nelze úplně odstranit, lze ho jen snížit.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.2.3","nazev":"Analýza produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-tri-analyza-produktovych-rizik"}},{"id":"UC-5-31","n":null,"lo":"FL-5.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících opatření <strong>NENÍ<\/strong> opatřením, které lze přijmout ke zmírnění produktových rizik prostřednictvím testování?<\/p>","m":["<p>Omezení regresního testování v oblastech s vysokým rizikem<\/p>","<p>Provedení revizí a statické analýzy<\/p>","<p>Výběr testerů se zkušenostmi a dovednostmi vhodnými pro daný typ rizika<\/p>","<p>Použití vhodné úrovně nezávislosti testování<\/p>"],"ok":[0],"vys":{},"obecne":"Sylabus 5.2.4 uvádí tato opatření ke zmírnění produktových rizik prostřednictvím testování: výběr testerů se zkušenostmi a dovednostmi vhodnými pro daný typ rizika, použití vhodné úrovně nezávislosti testování, provedení revizí a statické analýzy, použití vhodných technik testování a úrovní pokrytí, použití vhodných typů testů a provedení dynamického testování včetně regresního testování. Omezení regresního testování v rizikových oblastech by riziko naopak zvýšilo.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.2.4","nazev":"Řízení produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-ctyri-rizeni-produktovych-rizik"}},{"id":"UC-5-32","n":null,"lo":"FL-5.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Analýza rizik aplikace, do které byl nedávno přidán způsob platby za předplatné, přinesla následující výsledky.<\/p><p>Riziko: Platební sekce webu může obsahovat chyby nebo zranitelnosti, které by mohly vést k finanční ztrátě pro společnost i její zákazníky a poškodit pověst společnosti.<\/p><p>Pravděpodobnost rizika: Vysoká.<\/p><p>Reakce na riziko: najmout nezávislý testovací tým, který provede komplexní testování platební sekce.<\/p><p>Které z následujících opatření se navrhuje přijmout v reakci na toto analyzované riziko?<\/p>","m":["<p>Záložní plán<\/p>","<p>Zmírnění rizika<\/p>","<p>Přijetí rizika<\/p>","<p>Přenos rizika<\/p>"],"ok":[1],"vys":{},"obecne":"<p>Podle sylabu (kap. 5.2.4) lze na analyzované riziko reagovat jeho zmírněním pomocí testování, přijetím, přenosem nebo záložním plánem. Mezi opatření ke zmírnění produktových rizik prostřednictvím testování patří mj. použití vhodné úrovně nezávislosti testování a provedení dynamického testování. Najmutí nezávislého testovacího týmu ke komplexnímu otestování platební sekce je proto <strong>zmírnění rizika<\/strong> (nikoli přenos – odpovědnost za riziko zůstává na společnosti).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.2.4","nazev":"Řízení produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-ctyri-rizeni-produktovych-rizik"}},{"id":"UC-5-33","n":null,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Zvažte následující obsah reportů z testování:<\/p><p>i. Nová a změněná rizika během testovacího období<br>ii. Neošetřená rizika, nevyřešené defekty<br>iii. Postup prací při testování včetně všech významných odchylek<br>iv. Ponaučení (lessons learned), která jsou relevantní pro testování<\/p><p>Které z nich patří do reportu o postupu prací při testování a které do souhrnného reportu z testování?<\/p>","m":["<p>ii a iii jsou součástí reportu o postupu prací při testování, zatímco i a iv jsou součástí souhrnného reportu z testování.<\/p>","<p>i a iv jsou součástí reportu o postupu prací při testování, zatímco iii a iv jsou součástí souhrnného reportu z testování.<\/p>","<p>i a iii jsou součástí reportu o postupu prací při testování, zatímco ii a iv jsou součástí souhrnného reportu z testování.<\/p>","<p>i a ii jsou součástí reportu o postupu prací při testování, zatímco iii a iv jsou součástí souhrnného reportu z testování.<\/p>"],"ok":[2],"vys":{},"obecne":"Sylabus 5.3.2: Report o postupu prací při testování obsahuje mj. postup prací při testování včetně všech významných odchylek (iii) a nová a změněná rizika během testovacího období (i). Souhrnný report z testování obsahuje mj. neošetřená rizika a nevyřešené defekty (ii) a ponaučení (lessons learned), která jsou relevantní pro testování (iv).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UC-5-34","n":null,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího <strong>NENÍ<\/strong> součástí obsahu souhrnného reportu z testování?<\/p>","m":["<p>Vyhodnocení kvality produktu na základě původního plánu testování.<\/p>","<p>Odchylky od plánu testování.<\/p>","<p>Neošetřená rizika, nevyřešené defekty.<\/p>","<p>Nová a změněná rizika během testovacího období.<\/p>"],"ok":[3],"vys":{},"obecne":"<p>Podle sylabu (kap. 5.3.2) obsahuje souhrnný report z testování mj. vyhodnocení testování a kvality produktu na základě původního plánu testování, odchylky od plánu testování a neošetřená rizika a nevyřešené defekty. „Nová a změněná rizika během testovacího období“ jsou obsahem <strong>reportu o postupu prací při testování<\/strong>.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UC-5-35","n":null,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o reportech o postupu prací při testování NENÍ PRAVDIVÉ?<\/p>","m":["<p>Shrnují určitou testovací činnost, např. úroveň testování nebo iteraci.<\/p>","<p>Obvykle se generují pravidelně (např. denně, týdně atd.).<\/p>","<p>Obsahují nová a změněná rizika během testovacího období.<\/p>","<p>Obsahují překážky při testování a jejich řešení.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Toto tvrzení není pravdivé – shrnutí určité testovací činnosti (úrovně testování, testovacího cyklu, iterace) je účelem souhrnného reportu z testování.","b":"Není správně. Tvrzení je pravdivé – reporty o postupu prací se obvykle generují pravidelně.","c":"Není správně. Tvrzení je pravdivé – nová a změněná rizika jsou součástí reportu o postupu prací.","d":"Není správně. Tvrzení je pravdivé – report o postupu prací uvádí překážky při testování a jejich řešení."},"obecne":"Sylabus 5.3.2: Reporty o postupu prací při testování se obvykle generují pravidelně (např. denně, týdně) a obsahují mj. postup prací, překážky při testování a jejich řešení, testovací metriky, nová a změněná rizika během testovacího období a testování plánované pro následující období. Shrnutí určité testovací činnosti (např. úrovně testování, testovacího cyklu, iterace) je úlohou souhrnného reportu z testování, proto tvrzení a) není pravdivé.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UC-5-36","n":null,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Byli jste požádáni o revizi následujícího reportu o defektu:<\/p><p><em>Aplikace spadne, když uživatel dokončuje nákup s platbou přes PayPal. Závažnost je vysoká a defekt je nutné opravit co nejrychleji. Pokud chce uživatel dokončit nákup a zaplatit přes PayPal, aplikace spadne. Aplikace by měla platbu zpracovat a potvrdit. Defekt byl nalezen na mobilním telefonu s OS Android 8.<\/em><\/p><p>Která důležitá informace v tomto reportu CHYBÍ, ačkoli by vývojářům pomohla defekt opravit?<\/p>","m":["<p>Očekávaný výsledek a skutečný výsledek.<\/p>","<p>Kroky k reprodukci selhání.<\/p>","<p>Testovací prostředí.<\/p>","<p>Priorita a závažnost.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Skutečný výsledek (aplikace spadne) i očekávaný výsledek (platba se zpracuje a potvrdí) report obsahuje.","b":"Je správně. Report neuvádí přesné kroky, které k pádu vedly, takže reprodukce selhání je obtížná.","c":"Není správně. Prostředí je uvedeno – mobilní telefon s OS Android 8.","d":"Není správně. Závažnost (vysoká) i naléhavost opravy report uvádí."},"obecne":"Sylabus 5.5: Report o defektu má obsahovat mj. popis selhání umožňující reprodukci a vyřešení včetně testovacích kroků, které anomálii odhalily, dále očekávané a skutečné výsledky, testovací prostředí, závažnost a prioritu. V reportu je uveden skutečný výsledek (aplikace spadne), očekávaný výsledek (platba má být zpracována a potvrzena), prostředí (telefon s Androidem 8) i závažnost a naléhavost. Chybí přesné kroky k reprodukci selhání.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UC-5-37","n":null,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Je dán následující report o defektu:<\/p><p><em>Název: Přihlášení má problém.<br>Popis: Uživatelé se nemohou přihlásit s platným telefonním číslem.<br>Kroky k reprodukci: přejděte na přihlašovací stránku a zadejte platné telefonní číslo a heslo.<br>Očekávaný výsledek: Uživatel se úspěšně přihlásí.<br>Skutečný výsledek: Zobrazí se chybová hláška, že zadané telefonní číslo není správné.<br>Závažnost: Vysoká.<br>Priorita: Vysoká.<br>Prostředí: Desktop, Windows 11.<\/em><\/p><p>Co je s tímto reportem NEJPRAVDĚPODOBNĚJI za problém?<\/p>","m":["<p>Kroky nejsou podrobné.<\/p>","<p>Popis neodpovídá zbytku reportu.<\/p>","<p>Název je vágní.<\/p>","<p>Očekávané a skutečné výsledky nejsou jasné.<\/p>"],"ok":[2],"vys":{},"obecne":"<p>Podle sylabu (kap. 5.5) má report o defektu obsahovat „název obsahující krátké shrnutí reportované anomálie“. Název „Přihlášení má problém“ nic konkrétního neshrnuje – je vágní. Lepší by byl např. „Přihlášení s platným telefonním číslem selže s chybou neplatného čísla“. Popis, kroky i očekávaný a skutečný výsledek jsou v tomto reportu dostatečně jasné a konzistentní.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UC-5-42","n":null,"lo":"FL-5.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících je projektové riziko?<\/p>","m":["<p>Neúspěšný test výkonnosti<\/p>","<p>Problém s rozhraním mezi testovaným systémem a periferním zařízením<\/p>","<p>Modul, který provádí nesprávné výpočty kvůli defektu ve vzorci<\/p>","<p>Vývojový manažer bez udání důvodu zamítá všechny reporty o defektech<\/p>"],"ok":[3],"vys":{"a":"Není správně. Nevyhovující výkonnost je problém kvality produktu, tedy produktové riziko.","b":"Není správně. Problém s rozhraním se týká kvality produktu, jde o produktové riziko.","c":"Není správně. Nesprávné výpočty jsou nesprávná funkcionalita, tedy produktové riziko.","d":"Je správně. Problém s lidmi (konflikty, komunikace) se týká managementu a řízení projektu, jde o projektové riziko."},"obecne":"<p>Podle sylabu (kap. 5.2.2) se projektová rizika týkají managementu a řízení projektu; patří mezi ně mj. problémy s lidmi (např. konflikty, komunikační problémy). Problém s vývojovým manažerem, který zamítá všechny reporty o defektech, je proto projektové riziko. Nesprávné výpočty, nevyhovující výkonnost a problémy s rozhraním souvisejí s kvalitativními charakteristikami produktu – jde o produktová rizika (resp. jejich projevy).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.2.2","nazev":"Projektová a produktová rizika","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-dva-projektova-a-produktova-rizika"}},{"id":"UC-5-44","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Seřaďte testovací případy, které implementují následující testovací podmínky, do nejlepšího pořadí pro harmonogram provedení testů v rámci testu, který ověřuje úpravy zákazníků v databázi.<\/p><ol><li>Vytisknout upravený záznam zákazníka.<\/li><li>Změnit adresu zákazníka: číslo domu a název ulice.<\/li><li>Zachytit a vytisknout chybovou hlášku zobrazenou na obrazovce.<\/li><li>Změnit adresu zákazníka: PSČ.<\/li><li>Ověřit, že existující zákazník je v databázi, otevřením jeho záznamu.<\/li><li>Zavřít záznam zákazníka a zavřít databázi.<\/li><li>Pokusit se přidat nového zákazníka zcela bez údajů.<\/li><\/ol>","m":["<p>5, 4, 2, 1, 7, 3, 6<\/p>","<p>4, 2, 5, 1, 6, 7, 3<\/p>","<p>5, 1, 2, 3, 4, 7, 6<\/p>","<p>5, 4, 2, 1, 3, 7, 6<\/p>"],"ok":[0],"vys":{"a":"Je správně. Otevření záznamu (5), úpravy (4, 2), tisk upraveného záznamu (1), vyvolání chyby (7), zachycení hlášky (3) a nakonec zavření (6).","b":"Není správně. Adresa se mění (4, 2) dřív, než je záznam zákazníka otevřen (5), a databáze se zavírá (6) před negativním testem.","c":"Není správně. Upravený záznam se tiskne (1) dřív, než je upraven, a hláška (3) se zachytává před jejím vyvoláním (7).","d":"Není správně. Chybová hláška (3) se zachytává dřív, než ji vyvolá pokus o přidání zákazníka bez údajů (7)."},"obecne":"Sylabus 5.1.5: Pořadí v harmonogramu provedení testů musí respektovat logické závislosti mezi testovacími případy. Nejprve je nutné otevřít záznam existujícího zákazníka (5), pak ho upravit (4, 2), upravený záznam vytisknout (1), poté vyvolat chybovou hlášku pokusem přidat zákazníka bez údajů (7) a hlášku zachytit (3); nakonec se záznam a databáze zavřou (6).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UC-5-45","n":null,"lo":"FL-5.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících je riziko, které by mohlo ohrozit cíle projektu?<\/p>","m":["<p>V softwaru je několik problémů s použitelností<\/p>","<p>Testovací prostředí není připraveno<\/p>","<p>Software nerozpozná, že uživatel s omezenými právy zvolil neplatnou cestu pracovního postupu<\/p>","<p>Konverze dat selhává kvůli neočekávanému formátu dat<\/p>"],"ok":[1],"vys":{"a":"Není správně. Problémy s použitelností jsou produktové riziko.","b":"Je správně. Nepřipravené testovací prostředí ohrožuje harmonogram projektu, jde o projektové riziko.","c":"Není správně. Nerozpoznání neplatné cesty pracovního postupu je nesprávná funkcionalita, tedy produktové riziko.","d":"Není správně. Selhání konverze dat kvůli neočekávanému formátu je problém kvality produktu, tedy produktové riziko."},"obecne":"<p>Podle sylabu (kap. 5.2.2) se projektová rizika týkají managementu a řízení projektu a mohou mít dopad na harmonogram, rozpočet nebo rozsah projektu, což ovlivňuje schopnost projektu dosáhnout svých cílů. Nepřipravené testovací prostředí je organizační / technický problém (zpoždění při dodávání pracovních produktů), tedy projektové riziko. Ostatní možnosti popisují produktová rizika (nesprávná funkcionalita, chyby při běhu, špatná uživatelská zkušenost).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.2.2","nazev":"Projektová a produktová rizika","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-dva-projektova-a-produktova-rizika"}},{"id":"UC-6-04","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jsou dány následující kategorie testovacích nástrojů (1–4) a činnosti (A–D):<\/p><p>1. Nástroje pro statické testování<\/p><p>2. Nástroje DevOps<\/p><p>3. Nástroje pro návrh a implementaci testů<\/p><p>4. Nástroje pro management testování<\/p><p>A. Podporují sledování pracovních toků, procesy automatizovaného sestavování a CI/CD.<\/p><p>B. Zvyšují efektivitu testování usnadněním správy SDLC, požadavků, testů, defektů a konfigurací.<\/p><p>C. Usnadňují vytváření testovacích případů, testovacích dat a testovacích procedur.<\/p><p>D. Podporují provádění revizí a statické analýzy.<\/p><p>Která z následujících možností NEJLÉPE přiřazuje kategorie nástrojů k činnostem?<\/p>","m":["<p>1D, 2B, 3C, 4A<\/p>","<p>1D, 2A, 3C, 4B<\/p>","<p>1D, 2A, 3B, 4C<\/p>","<p>1A, 2C, 3D, 4B<\/p>"],"ok":[1],"vys":{"a":"Není správně. Sledování pracovních toků a CI/CD podporují nástroje DevOps (2A), správu SDLC nástroje pro management testování (4B).","b":"Je správně. 1D, 2A, 3C a 4B odpovídá sylabu 6.1.","c":"Není správně. Nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů (3C), ne správu SDLC.","d":"Není správně. Nástroje pro statické testování podporují revize (1D), ne CI/CD."},"obecne":"Sylabus 6.1: nástroje pro statické testování podporují revize a statickou analýzu; nástroje DevOps podporují pipeline, sledování pracovních toků, automatizované sestavování a CI/CD; nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, dat a procedur; nástroje pro management testování usnadňují správu SDLC, požadavků, testů, defektů a konfigurací.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UC-6-05","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jak se nazývají nástroje, které usnadňují vytváření testovacích případů, testovacích dat a testovacích procedur?<\/p>","m":["<p>Nástroje pro provádění testů a měření pokrytí<\/p>","<p>Nástroje pro management testování<\/p>","<p>Nástroje pro statické testování<\/p>","<p>Nástroje pro návrh a implementaci testů<\/p>"],"ok":[3],"vys":{"a":"Není správně. Nástroje pro provádění testů a měření pokrytí testy spouštějí, nevytvářejí.","b":"Není správně. Nástroje pro management testování usnadňují správu SDLC, požadavků, testů, defektů a konfigurací.","c":"Není správně. Nástroje pro statické testování podporují revize a statickou analýzu.","d":"Je správně. Nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, dat a procedur."},"obecne":"Sylabus 6.1: nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, testovacích dat a testovacích procedur.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UC-6-06","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jak se nazývají nástroje, které podporují sledování pracovních toků, procesy automatizovaného sestavování a CI/CD?<\/p>","m":["<p>Nástroje DevOps<\/p>","<p>Nástroje pro návrh a implementaci testů<\/p>","<p>Nástroje pro statické testování<\/p>","<p>Nástroje pro management testování<\/p>"],"ok":[0],"vys":{"a":"Je správně. Nástroje DevOps podporují pipeline v DevOps, sledování pracovních toků, automatizované sestavování a CI/CD.","b":"Není správně. Nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, dat a procedur.","c":"Není správně. Nástroje pro statické testování podporují revize a statickou analýzu.","d":"Není správně. Nástroje pro management testování usnadňují správu SDLC, požadavků, testů, defektů a konfigurací."},"obecne":"Sylabus 6.1: nástroje DevOps podporují pipeline v DevOps, sledování pracovních toků, procesy automatizovaného sestavování a CI/CD.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UC-6-07","n":null,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností správně uvádí možný přínos automatizace testů?<\/p>","m":["<p>Univerzální nástroje, které dokážou otestovat jakýkoli systém<\/p>","<p>Kratší doba provádění testů<\/p>","<p>Nižší pracnost testování za cenu delší doby provádění testů<\/p>","<p>Méně času pro testery na návrh nových testů<\/p>"],"ok":[1],"vys":{"a":"Není správně. Nástroje nejsou univerzální; výběr nevhodného nástroje je naopak riziko.","b":"Je správně. Kratší doba provádění testů umožňuje dřívější odhalení defektů a rychlejší zpětnou vazbu.","c":"Není správně. Automatizace dobu provádění testů zkracuje, ne prodlužuje.","d":"Není správně. Automatizace testerům naopak uvolní čas na návrh nových, hlubších testů."},"obecne":"Sylabus 6.2 uvádí mezi přínosy automatizace kratší dobu provádění testů, která vede k dřívějšímu odhalení defektů, rychlejší zpětné vazbě a rychlejšímu uvedení na trh, a také více času pro testery na návrh nových testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}},{"id":"UC-6-08","n":null,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností správně uvádí možné riziko automatizace testů?<\/p>","m":["<p>Nástroj pro automatizaci vždy způsobí pád systému a ztrátu dat.<\/p>","<p>Nástroj pro automatizaci nevratně poškodí testovaný software.<\/p>","<p>Nástroj pro automatizaci není kompatibilní s vývojovou platformou.<\/p>","<p>Nástroj pro automatizaci zanese do testovaného softwaru zranitelnosti.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Pád systému a ztrátu dat sylabus mezi riziky automatizace neuvádí.","b":"Není správně. Nevratné poškození softwaru nástrojem není riziko uvedené v sylabu.","c":"Je správně. Nekompatibilita nástroje pro automatizaci s vývojovou platformou je rizikem uvedeným v sylabu.","d":"Není správně. Zanesení zranitelností do testovaného softwaru sylabus mezi riziky neuvádí."},"obecne":"Sylabus 6.2 uvádí mezi riziky automatizace testů to, že nástroj pro automatizaci není kompatibilní s vývojovou platformou.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}},{"id":"UC-6-09","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího TYPICKY měří nástroje pro provádění testů a měření pokrytí?<\/p>","m":["<p>Dodržování konvencí pro programování<\/p>","<p>Pracnost potřebnou k přípravě testů<\/p>","<p>Spokojenost uživatelů s aplikací<\/p>","<p>Pokrytí kódu dosažené provedenými testy<\/p>"],"ok":[3],"vys":{"a":"Není správně. Dodržování konvencí pro programování kontrolují nástroje pro statickou analýzu.","b":"Není správně. Pracnost přípravy testů se odhaduje nebo sleduje v rámci managementu testování.","c":"Není správně. Spokojenost uživatelů tyto nástroje neměří.","d":"Je správně. Nástroje pro měření pokrytí zjišťují, jaká část kódu (např. příkazů nebo větví) byla provedenými testy vykonána."},"obecne":"Sylabus 6.1: nástroje pro provádění testů a měření pokrytí usnadňují automatizované provádění testů a měření pokrytí – typicky pokrytí kódu (např. pokrytí příkazů nebo větví, viz 4.3).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UC-6-11","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jaký je hlavní účel nástroje pro provádění testů?<\/p>","m":["<p>Spouští testovaný objekt pomocí automatizovaných testovacích skriptů<\/p>","<p>Analyzuje kód s cílem odhalit porušení konvencí pro programování<\/p>","<p>Sleduje testovací případy, defekty a trasovatelnost k požadavkům<\/p>","<p>Spravuje reporty o defektech a sleduje jejich stav až do uzavření<\/p>"],"ok":[0],"vys":{"a":"Je správně. Hlavním účelem nástroje pro provádění testů je automatizované spouštění testů.","b":"Není správně. Analýzu kódu bez spuštění provádějí nástroje pro statické testování.","c":"Není správně. Sledování testů, defektů a trasovatelnosti zajišťují nástroje pro management testování.","d":"Není správně. Správu defektů zajišťují nástroje pro management testování (management defektů)."},"obecne":"Sylabus 6.1: nástroje pro provádění testů a měření pokrytí usnadňují automatizované provádění testů a měření pokrytí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UC-6-12","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Organizace chce zlepšit efektivitu testování. Který z následujících cílů by NEJLÉPE podpořil nástroj pro management testování?<\/p>","m":["<p>Zvýšit schopnost testů odhalovat selhání<\/p>","<p>Vytvořit trasovatelnost mezi požadavky, testy a defekty<\/p>","<p>Rychleji opravovat nalezené defekty v kódu<\/p>","<p>Automaticky spouštět vybrané testovací případy<\/p>"],"ok":[1],"vys":{"a":"Není správně. Schopnost testů odhalovat selhání závisí na návrhu testů, ne na nástroji pro management testování.","b":"Je správně. Nástroje pro management testování usnadňují správu požadavků, testů a defektů, a tím i trasovatelnost mezi nimi.","c":"Není správně. Opravu defektů provádějí vývojáři; nástroj pro management ji sám neurychlí.","d":"Není správně. Spouštění testů podporují nástroje pro provádění testů."},"obecne":"Sylabus 6.1: nástroje pro management testování zvyšují efektivitu testování usnadněním správy SDLC, požadavků, testů, defektů a konfigurací; umožňují tak udržovat trasovatelnost mezi požadavky, testy a defekty.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-1-01","n":null,"lo":"FL-1.1.1","k":"K1","k3":true,"vyber":1,"q":"Testovací případy jsou navrhovány v rané fázi životního cyklu a testovací báze je přitom prověřována prostřednictvím návrhu testů. Kterého typického cíle testování se tím NEJLÉPE dosahuje?","m":["Ověření souladu testovaného objektu s právními předpisy","Vytvoření důvěry v úroveň kvality testovaného objektu","Ohodnocení pracovních produktů, jako jsou požadavky a návrhy","Poskytnutí informací zainteresovaným stranám pro rozhodnutí"],"ok":[2],"vys":{"a":"Není správně. Ověření souladu s předpisy je samostatný cíl, který s prověřováním testovací báze přímo nesouvisí.","b":"Není správně. Důvěra v kvalitu testovaného objektu vzniká až na základě výsledků jeho testování.","c":"Je správně. Návrh testů v rané fázi prověřuje testovací bázi (požadavky, návrhy), a ohodnocuje tak pracovní produkty dříve, než se defekty v nich promítnou do kódu.","d":"Není správně. Informace pro rozhodnutí poskytují hlavně výsledky testů a reporty, ne prověřování testovací báze."},"obecne":"Sylabus 1.1.1 uvádí mezi typickými cíli testování ohodnocení pracovních produktů jako jsou požadavky, uživatelské scénáře, návrhy a kód. Časný návrh testů odhaluje nejasnosti a defekty v testovací bázi, a přispívá tak k ohodnocení těchto pracovních produktů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"}},{"id":"UP-1-02","n":null,"lo":"FL-1.1.2","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností je příkladem ladění?","m":["Tester znovu otestuje opravu od vývojáře a najde regresi","Tester najde defekt a nahlásí ho","Vývojář provádí testování komponent","Vývojář najde příčinu selhání a opraví defekt"],"ok":[3],"vys":{"a":"Není správně. Jde o konfirmační, resp. regresní testování, které následuje po ladění.","b":"Není správně. Nalezení a nahlášení defektu je součástí testování, ne ladění.","c":"Není správně. Testování komponent je úroveň testování; ladění následuje až po zjištění selhání.","d":"Je správně. Ladění zahrnuje reprodukování selhání, diagnostiku (nalezení defektu) a jeho opravu."},"obecne":"Sylabus 1.1.2: Testování a ladění jsou samostatné činnosti. Testování vyvolává selhání nebo přímo nachází defekty, ladění hledá příčiny selhání (defekty), analyzuje je a odstraňuje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.1.2","nazev":"Testování a ladění","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-dva-testovani-a-ladeni"}},{"id":"UP-1-03","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností NEJLÉPE popisuje hlavní přínos ověřování (verifikace) v rané fázi životního cyklu?","m":["Omezuje šíření defektů do navazujících pracovních produktů.","Umožňuje testerům zapojit se do projektu v rané fázi.","Umožňuje včas identifikovat změny v uživatelských požadavcích.","Usnadňuje včasné připravení testovacího prostředí."],"ok":[0],"vys":{"a":"Je správně. Defekty odstraněné v rané fázi nezpůsobí další defekty v odvozených pracovních produktech.","b":"Není správně. Zapojení testerů je předpokladem časného testování, nikoli jeho přínosem.","c":"Není správně. Změny požadavků přicházejí od zainteresovaných stran; včasné testování je neidentifikuje.","d":"Není správně. Příprava testovacího prostředí s časným ověřováním pracovních produktů přímo nesouvisí."},"obecne":"Sylabus 1.3, princip 3 (Včasné testování šetří čas a peníze): Defekty, které jsou odstraněny v rané fázi procesu, nezpůsobí následně jiné defekty v odvozených pracovních produktech. Chybné požadavky by jinak vedly k chybnému návrhu a ten k chybnému kódu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-1-04","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností je HLAVNÍM úkolem monitoringu a řízení testování?","m":["Vyhodnocení testovatelnosti požadavků a testovaného objektu","Vytvoření reportu o postupu prací při testování pro zainteresované strany","Definování cílů testování a výběr vhodného přístupu k testování","Zaznamenání výsledků testů po jejich provedení do protokolu"],"ok":[1],"vys":{"a":"Není správně. Vyhodnocení testovatelnosti testovací báze a testovaného objektu patří do testovací analýzy.","b":"Je správně. Reporty o postupu prací při testování jsou typickým výstupem monitoringu a řízení testování.","c":"Není správně. Definování cílů testování a výběr přístupu patří do plánování testování.","d":"Není správně. Zaznamenání výsledků testů je součástí provedení testů."},"obecne":"Sylabus 1.4.1 a 1.4.3: Monitoring testování průběžně kontroluje testovací činnosti a porovnává skutečný stav s plánem, řízení testování přijímá nápravná opatření. Pracovními produkty jsou reporty o postupu prací při testování, pokyny a nápravná opatření a informace o rizicích.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"UP-1-05","n":null,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Je dán následující testware:<\/p><ol><li>Plán testování<\/li><li>Testovací případy<\/li><li>Harmonogram provedení testů<\/li><li>Souhrnný report z testování<\/li><\/ol><p>a následující testovací činnosti:<\/p><p>A. Implementace testování<br>B. Návrh testů<br>C. Plánování testování<br>D. Dokončení testování<\/p><p>Která z následujících možností NEJLÉPE přiřazuje testware k činnostem, jejichž je výstupem?<\/p>","m":["1A, 2B, 3C, 4D","1D, 2B, 3A, 4C","1B, 2C, 3D, 4A","1C, 2B, 3A, 4D"],"ok":[3],"vys":{"a":"Není správně. Plán testování vzniká při plánování (C), harmonogram provedení testů při implementaci (A).","b":"Není správně. Plán testování není výstupem dokončení testování a souhrnný report není výstupem plánování.","c":"Není správně. Testovací případy nejsou výstupem plánování a harmonogram provedení testů není výstupem dokončení.","d":"Je správně. Plán testování = plánování (C), testovací případy = návrh testů (B), harmonogram provedení testů = implementace (A), souhrnný report = dokončení testování (D)."},"obecne":"Sylabus 1.4.3: Plán testování je výstupem plánování testování, testovací případy návrhu testů, harmonogram provedení testů implementace testování a souhrnný report z testování dokončení testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"UP-1-06","n":null,"lo":"FL-1.4.5","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících činností by TYPICKY prováděl manažer testování a které tester?<\/p><ol><li>Vytvoření plánu testování<\/li><li>Vytvoření testovacích případů<\/li><li>Založení reportu o defektu<\/li><li>Sepsání souhrnného reportu z testování<\/li><\/ol>","m":["1 a 3 by prováděl manažer testování, 2 a 4 tester","1 a 2 by prováděl manažer testování, 3 a 4 tester","2 a 3 by prováděl manažer testování, 1 a 4 tester","1 a 4 by prováděl manažer testování, 2 a 3 tester"],"ok":[3],"vys":{"a":"Není správně. Reporty o defektech zakládá při provedení testů tester, souhrnný report vytváří manažer testování.","b":"Není správně. Vytváření testovacích případů (návrh testů) je úkolem testera, souhrnný report z testování manažera testování.","c":"Není správně. Role jsou zde přesně prohozené.","d":"Je správně. Plán testování a souhrnný report jsou výstupy plánování a dokončení testování (manažer testování), testovací případy a reporty o defektech vytváří tester."},"obecne":"Sylabus 1.4.5: Manažer testování se zaměřuje na plánování, monitoring a řízení a dokončení testování (plán testování, souhrnný report z testování). Tester se zaměřuje na testovací analýzu, návrh, implementaci a provedení testů (testovací případy, reporty o defektech).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.5","nazev":"Role v testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-pet-role-v-testovani"}},{"id":"UP-1-07","n":null,"lo":"FL-1.5.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících dovedností je pro testera NEJCENNĚJŠÍ v kontextu analýzy složitých softwarových požadavků?<\/p>","m":["<p>Analytické a kritické myšlení, které umožní odhalit nejasnosti a nekonzistence.<\/p>","<p>Zběhlost v používání nástrojů pro management testování k organizaci testovacích případů.<\/p>","<p>Znalost různých metodik vývoje softwaru, jako je agilní vývoj a vodopád.<\/p>","<p>Schopnost efektivně spolupracovat s vývojáři a byznys analytiky.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Analytické a kritické myšlení (sylabus 1.5.1) umožňuje složitým požadavkům porozumět, najít v nich nejasnosti, nekonzistence a defekty a odvodit z nich testovací podmínky.","b":"Není správně. Práce s nástroji pro management testování pomáhá testovací případy organizovat, ale k pochopení a posouzení složitých požadavků nepřispívá.","c":"Není správně. Znalost metodik vývoje poskytuje kontext, ale pro analýzu konkrétních složitých požadavků není rozhodující.","d":"Není správně. Spolupráce je důležitá pro získávání informací a vyjasňování požadavků, samotnou analýzu požadavků však nenahradí."},"obecne":"Sylabus 1.5.1 uvádí mezi obecnými dovednostmi testera analytické a kritické myšlení a kreativitu. Při analýze složitých požadavků jsou právě analytické dovednosti klíčové pro jejich pochopení, nalezení nejasností a defektů a odvození testovacích podmínek.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.1","nazev":"Obecné dovednosti potřebné pro testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-jedna-obecne-dovednosti-potrebne-pro-testovani"}},{"id":"UP-1-08","n":null,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností je přínosem týmového přístupu?<\/p>","m":["<p>Snížená týmová synergie<\/p>","<p>Kolektivní odpovědnost všech za výsledek<\/p>","<p>Omezená flexibilita při přidělování úkolů<\/p>","<p>Omezená komunikace mezi členy týmu<\/p>"],"ok":[1],"vys":{"a":"Není správně. Týmový přístup synergii naopak vytváří.","b":"Je správně. Při týmovém přístupu je každý člen týmu zodpovědný za kvalitu – odpovědnost je kolektivní.","c":"Není správně. Při týmovém přístupu může každý člen týmu s potřebnými dovednostmi vykonávat jakýkoliv úkol, flexibilita tedy roste.","d":"Není správně. Týmový přístup komunikaci a spolupráci v týmu naopak zlepšuje."},"obecne":"Sylabus 1.5.2: Při týmovém přístupu je každý člen týmu zodpovědný za kvalitu. Týmový přístup zvyšuje týmovou dynamiku, zlepšuje komunikaci a spolupráci a vytváří synergii. Ostatní možnosti popisují opak těchto přínosů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"UP-1-12","n":null,"lo":"FL-2.1.4","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je typickou výhodou DevOps?<\/p>","m":["<p>Menší zaměření na neustálé zlepšování a zpětnou vazbu<\/p>","<p>Větší spoléhání na manuální procesy nasazení<\/p>","<p>Lepší spolupráce a komunikace mezi vývojem a provozem<\/p>","<p>Menší důraz na spolupráci mezi vývojovými a provozními týmy<\/p>"],"ok":[2],"vys":{"a":"Není správně. DevOps podporuje rychlou zpětnou vazbu a průběžné zlepšování.","b":"Není správně. DevOps prosazuje automatizaci (CI/CD), nikoli manuální nasazení.","c":"Je správně. DevOps staví na synergii vývoje (včetně testování) a provozu a překlenuje mezery mezi nimi.","d":"Není správně. DevOps naopak spolupráci vývoje a provozu posiluje."},"obecne":"Sylabus 2.1.4: DevOps je přístup postavený na synergii mezi vývojem (včetně testování) a provozem. Vyžaduje změnu kultury, která překlene mezery mezi oběma útvary, a podporuje autonomii týmu, rychlou zpětnou vazbu a CI/CD.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.4","nazev":"DevOps a testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-ctyri-devops-a-testovani"}},{"id":"UP-1-13","n":null,"lo":"FL-2.2.1","k":"K2","k3":true,"vyber":1,"q":"<p>Na co se akceptační testování zaměřuje PŘEDEVŠÍM?<\/p>","m":["<p>Na nalezení co největšího počtu defektů v kódu systému<\/p>","<p>Na testování rozhraní mezi systémem a dalšími systémy<\/p>","<p>Na ověření logiky jednotlivých komponent v izolaci<\/p>","<p>Na validaci, že systém splňuje byznysové potřeby uživatele<\/p>"],"ok":[3],"vys":{"a":"Není správně. Hledání defektů v kódu je typické pro nižší úrovně testování, ne hlavní zaměření akceptačního testování.","b":"Není správně. Rozhraní s jinými systémy se testují při systémovém integračním testování.","c":"Není správně. Izolované komponenty se testují při testování komponent.","d":"Je správně. Akceptační testování validuje, že systém splňuje byznysové potřeby uživatele a je připraven k nasazení."},"obecne":"Sylabus 2.2.1: akceptační testování se zaměřuje na validaci a prokázání připravenosti systému k nasazení, tj. že systém splňuje byznysové potřeby uživatele. Ideálně by jej měli provádět zamýšlení uživatelé.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"}},{"id":"UP-1-14","n":null,"lo":"FL-2.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>V softwaru byla opravena řada kritických defektů. Všechny se nacházely v jednom modulu, který zajišťuje reporty. Manažerka testování se rozhodne provést regresní testování pouze na modulu reportů.<\/p><p>Které z následujících tvrzení toto rozhodnutí NEJLÉPE hodnotí?<\/p>","m":["Regresní testování by mělo zahrnout i další moduly, protože je oprava může ovlivnit.","Rozhodnutí je oprávněné, protože v jiných modulech nebyl opraven žádný defekt.","Stačí provést pouze konfirmační testování, regresní testování není potřeba.","Manažerka by měla provést pouze automatizované regresní testování modulu reportů."],"ok":[0],"vys":{"a":"Je správně. Změna může ovlivnit i jiné komponenty a propojené části; rozsah regresního testování má určit analýza dopadu.","b":"Není správně. Oprava v jednom modulu může mít nežádoucí dopady i na jiné, nezměněné části systému.","c":"Není správně. Konfirmační testování ověří jen opravy samotné; regresní testování je po změnách stále potřeba.","d":"Není správně. Způsob provedení (automatizace) neřeší problém, že regrese může nastat i mimo modul reportů."},"obecne":"Sylabus 2.2.3: regresní testování ověřuje, zda po změnách (včetně oprav) nedošlo k nežádoucím dopadům. Nemusí být omezeno na samotný testovaný objekt, ale může zahrnovat i další komponenty ve stejném systému či propojené systémy; rozsah pomáhá určit analýza dopadu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"}},{"id":"UP-1-15","n":null,"lo":"FL-3.1.1","k":"K1","k3":true,"vyber":1,"q":"<p>Který z následujících pracovních produktů je vhodný pro posouzení pomocí statického testování?<\/p>","m":["<p>Systémové logy v reálném čase<\/p>","<p>Specifikace softwarových požadavků<\/p>","<p>Živá produkční databáze<\/p>","<p>Zašifrovaný zdrojový kód<\/p>"],"ok":[1],"vys":{"a":"Není správně. Systémové logy v reálném čase zachycují události za běhu systému; nejde o pracovní produkt, který se posuzuje statickým testováním.","b":"Je správně. Specifikace požadavků je typickým pracovním produktem pro revize, které odhalí nejednoznačnosti nebo nekonzistence v rané fázi SDLC.","c":"Není správně. Živá produkční databáze obsahuje provozní data, nejde o pracovní produkt vhodný pro statické testování.","d":"Není správně. Zašifrovaný zdrojový kód není pro člověka čitelný a nelze jej revidovat ani běžně staticky analyzovat."},"obecne":"Sylabus 3.1.1: téměř každý pracovní produkt může být prozkoumán statickým testováním, např. specifikace požadavků, zdrojový kód, plány testování nebo testovací případy. Revizi lze použít na jakýkoli pracovní produkt, který lze přečíst a porozumět mu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.1","nazev":"Pracovní produkty, které mohou být prověřeny statickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-jedna-pracovni-produkty-ktere-mohou-byt-provereny-statickym-testovanim"}},{"id":"UP-1-16","n":null,"lo":"FL-3.1.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o statické analýze PLATÍ?<\/p>","m":["<p>Předvedení (walkthrough) je typem statické analýzy.<\/p>","<p>Dokáže posoudit, zda požadavky odpovídají potřebám zákazníka.<\/p>","<p>Lze ji použít při testování zabezpečení.<\/p>","<p>Používá se pouze v sekvenčních modelech vývoje.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Předvedení je typ revize, tedy manuálního statického testování, nikoli statické analýzy.","b":"Není správně. Žádný nástroj neověří, co zákazník skutečně potřebuje; k tomu je nutné zapojení lidí (např. revize se zainteresovanými stranami).","c":"Je správně. Statickou analýzu lze použít k vyhodnocení bezpečnosti, např. k odhalení některých bezpečnostních zranitelností.","d":"Není správně. Statická analýza se používá ve všech modelech vývoje a často je začleněna do nástrojů průběžné integrace."},"obecne":"<p>Sylabus 3.1: statická analýza se sice z velké části používá k odhalování specifických defektů kódu, lze ji ale také použít k vyhodnocení udržovatelnosti a bezpečnosti. Často je začleněna do nástrojů průběžné integrace, tedy i v agilním vývoji.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"}},{"id":"UP-1-17","n":null,"lo":"FL-3.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je jedním z účelů fáze plánování revize?<\/p>","m":["<p>Revizní schůzka.<\/p>","<p>Zajištění přístupu účastníků k pracovnímu produktu.<\/p>","<p>Zaznamenání nalezených anomálií.<\/p>","<p>Stanovení rozsahu revize včetně výstupních kritérií.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Revizní schůzka obvykle probíhá v rámci činnosti komunikace a analýza.","b":"Není správně. Zajištění, aby měl každý účastník přístup k pracovnímu produktu a rozuměl své roli, je cílem zahájení revize.","c":"Není správně. Anomálie zaznamenává každý revidující během individuální revize.","d":"Je správně. Během plánování se stanoví rozsah revize – účel, revidovaný pracovní produkt, kvalitativní charakteristiky, oblasti zájmu, výstupní kritéria, pracnost a časový rámec."},"obecne":"Sylabus 3.2.2: během plánování se stanoví rozsah revize obsahující definici účelu a revidovaného pracovního produktu, kvalitativní charakteristiky pro vyhodnocení, oblasti zájmu, výstupní kritéria, doplňující informace, pracnost a časový rámec.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.2","nazev":"Činnosti procesu revize","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-dva-cinnosti-procesu-revize"}},{"id":"UP-1-18","n":null,"lo":"FL-3.2.3","k":"K1","k3":true,"vyber":1,"q":"<p>Kdo při formální revizi typicky provádí přepracování, tj. opravu nalezených defektů?<\/p>","m":["Autor","Revidující","Zapisovatel","Moderátor (facilitátor)"],"ok":[0],"vys":{"a":"Je správně. Autor vytváří a opravuje revidovaný pracovní produkt.","b":"Není správně. Revidující provádí revizi a identifikuje anomálie, opravy ale neprovádí.","c":"Není správně. Zapisovatel shromažďuje anomálie a zaznamenává informace z revize.","d":"Není správně. Moderátor zajišťuje efektivní průběh revizních schůzek, pracovní produkt neopravuje."},"obecne":"Sylabus 3.2.3: autor vytváří a opravuje revidovaný pracovní produkt. Přepracování na základě výsledků revize je proto odpovědností autora.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"}},{"id":"UP-1-19","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o technikách testování černé a bílé skříňky je SPRÁVNÉ?<\/p>","m":["<p>Rozdělení tříd ekvivalence, analýza hraničních hodnot a testování větví jsou techniky testování černé skříňky.<\/p>","<p>Rozdělení tříd ekvivalence, testování přechodů stavů a analýza hraničních hodnot jsou techniky testování černé skříňky.<\/p>","<p>Rozdělení tříd ekvivalence, testování dle rozhodovací tabulky a pokrytí příkazů jsou techniky testování bílé skříňky.<\/p>","<p>Testování příkazů a testování dle rozhodovací tabulky jsou techniky testování bílé skříňky.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Testování větví je technika bílé skříňky.","b":"Je správně. Všechny tři uvedené techniky jsou techniky testování černé skříňky.","c":"Není správně. Rozdělení tříd ekvivalence a testování dle rozhodovací tabulky jsou techniky černé skříňky; bílé skříňky je jen pokrytí příkazů.","d":"Není správně. Testování dle rozhodovací tabulky je technika černé skříňky."},"obecne":"<p>Sylabus 4.2 a 4.3: Rozdělení tříd ekvivalence, analýza hraničních hodnot, testování dle rozhodovací tabulky a testování přechodů stavů jsou techniky testování černé skříňky. Testování příkazů a testování větví jsou techniky testování bílé skříňky.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UP-1-20","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Zkouška má 40 otázek, za každou správnou odpověď je 1 bod. Ke složení zkoušky je potřeba alespoň 25 bodů, ke složení s vyznamenáním alespoň 80 % bodů. Která sada hodnot patří do STEJNÉ třídy ekvivalence?<\/p>","m":["<p>0, 12, 25 <\/p>","<p>30, 36, 39 <\/p>","<p>32,37,40<\/p>","<p>23, 24, 25 <\/p>"],"ok":[2],"vys":{"a":"Není správně. 0 a 12 patří do třídy „nesložil“, 25 do třídy „složil“.","b":"Není správně. 30 patří do třídy „složil“, 36 a 39 do třídy „s vyznamenáním“.","c":"Je správně. Všechny hodnoty patří do třídy „s vyznamenáním“ (32–40).","d":"Není správně. 23 a 24 patří do třídy „nesložil“ (0–24), 25 do třídy „složil“ (25–31)."},"obecne":"<p>Sylabus 4.2.1: 80 % ze 40 je 32 bodů. Platné třídy jsou 0–24 (nesložil), 25–31 (složil) a 32–40 (s vyznamenáním). Do stejné třídy patří pouze hodnoty 32, 37 a 40.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UP-1-21","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Vstupní pole přijímá rok narození v rozmezí 1900 až 2004 (včetně). Které hodnoty je třeba otestovat při použití dvouhodnotové analýzy hraničních hodnot?<\/p>","m":["1899, 1900, 1901, 2003, 2004, 2005","0, 1900, 2004, 2005","1900, 2004","1899, 1900, 2004, 2005"],"ok":[3],"vys":{"a":"Není správně. Tyto hodnoty odpovídají tříhodnotové analýze hraničních hodnot.","b":"Není správně. 0 není hraniční hodnotou; chybí 1899.","c":"Není správně. Chybí hraniční hodnoty neplatných tříd 1899 a 2005.","d":"Je správně. Hranice 1899 | 1900 a 2004 | 2005."},"obecne":"<p>Sylabus 4.2.2: Třídy jsou ≤ 1899 (neplatná), 1900–2004 (platná) a ≥ 2005 (neplatná). Dvouhodnotová BVA testuje každou hraniční hodnotu a jejího nejbližšího souseda ze sousední třídy: 1899, 1900, 2004, 2005. Tříhodnotová by navíc přidala 1901 a 2003.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UP-1-22","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Je dána následující rozhodovací tabulka:<\/p><table><tr><th>Podmínky / akce<\/th><th>R1<\/th><th>R2<\/th><th>R3<\/th><th>R4<\/th><\/tr><tr><td>Platné uživatelské jméno<\/td><td>F<\/td><td>T<\/td><td>T<\/td><td>T<\/td><\/tr><tr><td>Platné heslo<\/td><td>–<\/td><td>F<\/td><td>T<\/td><td>T<\/td><\/tr><tr><td>Dostatečný zůstatek<\/td><td>–<\/td><td>–<\/td><td>F<\/td><td>T<\/td><\/tr><tr><td>Hlášení „Neplatné přihlašovací údaje“<\/td><td>X<\/td><td>X<\/td><td><\/td><td><\/td><\/tr><tr><td>Hlášení „Nedostatečný zůstatek“<\/td><td><\/td><td><\/td><td>X<\/td><td><\/td><\/tr><tr><td>Provedení platby<\/td><td><\/td><td><\/td><td><\/td><td>X<\/td><\/tr><\/table><p>Již existují 2 testovací případy:<\/p><p>1 – neplatné uživatelské jméno<br>2 – platné uživatelské jméno, platné heslo a dostatečný zůstatek<\/p><p>Které testovací případy je třeba doplnit, aby bylo s co NEJMENŠÍM počtem testů dosaženo 100% pokrytí rozhodovací tabulky?<\/p>","m":["<p>Dva testovací případy: 1- platné uživatelské jméno a neplatné heslo 2- platné uživatelské jméno a platné heslo, ale nedostatečný zůstatek<\/p>","<p>Jeden testovací případ: platné uživatelské jméno a heslo<\/p>","<p>Tři testovací případy: 1- neplatné uživatelské jméno a platné heslo 2- platné uživatelské jméno a neplatné heslo 3- platné uživatelské jméno a platné heslo, ale nedostatečný zůstatek<\/p>","<p>Dva testovací případy: 1- neplatné uživatelské jméno a platné heslo 2- platné uživatelské jméno a neplatné heslo, ale nedostatečný zůstatek<\/p>"],"ok":[0],"vys":{"a":"Je správně. První test pokryje R2, druhý R3; spolu s existujícími testy (R1 a R4) jsou pokryta všechna 4 pravidla.","b":"Není správně. Platné jméno a heslo vede k pravidlu R3 nebo R4 podle zůstatku; pravidlo R2 by zůstalo nepokryto.","c":"Není správně. Tato sada sice pokryje všechna pravidla, ale první test znovu pokrývá R1, takže nejde o nejmenší počet testů.","d":"Není správně. První test pokrývá opět R1 (heslo je pro neplatné jméno irelevantní) a druhý R2; pravidlo R3 zůstane nepokryto."},"obecne":"<p>Sylabus 4.2.3: Položkami pokrytí jsou proveditelné sloupce tabulky. Existující testy pokrývají R1 a R4, chybí R2 (platné jméno, neplatné heslo) a R3 (platné jméno i heslo, nedostatečný zůstatek). Stačí tedy přesně dva další testy.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UP-1-23","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Zjednodušený model přihlášení k bankomatu má tři stavy: S1 – Čekání na zákazníka, S2 – Zpracování PIN, S3 – Zpracování v bankomatu. Platné přechody jsou uvedeny v tabulce:<\/p><table><tr><th>Výchozí stav<\/th><th>Událost [podmínka] / akce<\/th><th>Cílový stav<\/th><\/tr><tr><td>S1<\/td><td>Vložení karty [neplatná karta] / vrácení karty<\/td><td>S1<\/td><\/tr><tr><td>S1<\/td><td>Vložení karty [platná karta]<\/td><td>S2<\/td><\/tr><tr><td>S2<\/td><td>Zadání PIN [neplatný PIN, 1. nebo 2. pokus]<\/td><td>S2<\/td><\/tr><tr><td>S2<\/td><td>Zadání PIN [neplatný PIN, 3. pokus] / ponechání karty<\/td><td>S1<\/td><\/tr><tr><td>S2<\/td><td>Zrušení / vrácení karty<\/td><td>S1<\/td><\/tr><tr><td>S2<\/td><td>Zadání PIN [platný PIN]<\/td><td>S3<\/td><\/tr><tr><td>S3<\/td><td>Zrušení / vrácení karty<\/td><td>S1<\/td><\/tr><tr><td>S3<\/td><td>Hotovo / vrácení karty<\/td><td>S1<\/td><\/tr><\/table><p>Každý testovací případ začíná ve stavu S1 a končí, jakmile se do stavu S1 vrátí. Jaký je MINIMÁLNÍ počet testovacích případů potřebný k dosažení 100% pokrytí platných přechodů?<\/p>","m":["<p>4<\/p>","<p>5<\/p>","<p>6<\/p>","<p>7<\/p>"],"ok":[1],"vys":{"a":"Není správně. Do stavu S1 vede 5 různých přechodů a každý test smí obsahovat jen jeden z nich (na konci).","b":"Je správně. Každý z 5 přechodů vedoucích do S1 test ukončí, proto je potřeba 5 testů; ostatní přechody se pokryjí cestou.","c":"Není správně. Šestý test by nepokryl žádný nový přechod.","d":"Není správně. Přechody S1 → S2, S2 → S2 a S2 → S3 lze pokrýt v testech, které končí jiným přechodem do S1."},"obecne":"<p>Sylabus 4.2.4: Do stavu S1 vede 5 přechodů (neplatná karta, 3. neplatný PIN, zrušení v S2, zrušení v S3, hotovo) a každý z nich test ukončí. Testy: 1) neplatná karta; 2) platná karta, neplatný PIN, zrušení; 3) platná karta, 3× neplatný PIN; 4) platná karta, platný PIN, zrušení; 5) platná karta, platný PIN, hotovo. Celkem 5 testů pokryje všech 8 platných přechodů.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UP-1-24","n":null,"lo":"FL-4.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících popisů pokrytí příkazů je SPRÁVNÝ?<\/p>","m":["<p>Pokrytí příkazů je míra procenta řádků zdrojového kódu provedených testy.<\/p>","<p>Pokrytí příkazů je míra počtu řádků zdrojového kódu (bez komentářů) provedených testy.<\/p>","<p>Pokrytí příkazů je míra podílu spustitelných příkazů ve zdrojovém kódu provedených testy.<\/p>","<p>Pokrytí příkazů je míra počtu spustitelných příkazů ve zdrojovém kódu provedených testy.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Pokrytí příkazů je procento provedených spustitelných příkazů; mnoho řádků zdrojového kódu (např. komentáře) spustitelných není.","b":"Není správně. Pokrytí příkazů je podíl provedených spustitelných příkazů. Počet spustitelných příkazů se často blíží počtu řádků bez komentářů, tato možnost však hovoří o počtu provedených řádků, ne o podílu.","c":"Je správně. Pokrytí příkazů je podíl provedených spustitelných příkazů (obvykle vyjádřený v procentech).","d":"Není správně. Tato možnost hovoří jen o počtu provedených spustitelných příkazů, ne o jejich podílu (procentu)."},"obecne":"<p>Sylabus 4.3.1: Při testování příkazů jsou položkami pokrytí spustitelné příkazy. Pokrytí se měří jako počet spustitelných příkazů pokrytých testy dělený celkovým počtem spustitelných příkazů v kódu (obvykle v procentech).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"}},{"id":"UP-1-25","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících popisů pokrytí větví je SPRÁVNÝ?<\/p>","m":["<p>Pokrytí větví je míra procenta byznysových toků komponentou provedených testy.<\/p>","<p>Pokrytí větví je míra procenta možných cest zdrojovým kódem provedených testy.<\/p>","<p>Pokrytí větví je míra příkazů IF v kódu, které testy provedly s výsledkem pravda i nepravda.<\/p>","<p>Pokrytí větví je míra podílu větví ve zdrojovém kódu, které byly provedeny testy.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Byznysové toky jsou předmětem technik černé skříňky; pokrytí větví se měří na kódu.","b":"Není správně. Cesta je celá trasa kódem od vstupu k výstupu a prochází řadou větví. Pokrytí větví vyžaduje jen zlomek testů potřebných pro pokrytí cest; programy s cykly mají potenciálně nekonečně mnoho cest.","c":"Není správně. Větve vznikají i u příkazů SWITCH/CASE a cyklů a patří k nim i nepodmíněné větve, nejen výsledky příkazů IF.","d":"Je správně. Pokrytí větví je podíl provedených větví (podmíněných i nepodmíněných) k jejich celkovému počtu, obvykle v procentech."},"obecne":"<p>Sylabus 4.3.2: Při testování větví jsou položkami pokrytí větve (podmíněné i nepodmíněné přenosy řízení). Pokrytí se měří jako počet větví pokrytých testy dělený celkovým počtem větví.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UP-1-26","n":null,"lo":"FL-4.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Skupina zajištění kvality strávila poslední měsíc procházením systému pro management defektů a sestavila seznam všech selhání nahlášených při testování i v produkčním provozu. Seznam předala testovacímu týmu, který podle něj bude navrhovat testy pro příští vydání. Která z následujících technik testování NEJLÉPE odpovídá tomuto využití seznamu?<\/p>","m":["<p>Útok na vady<\/p>","<p>Průzkumné testování<\/p>","<p>Testování založené na kontrolních seznamech<\/p>","<p>Testování dle rozhodovací tabulky<\/p>"],"ok":[0],"vys":{"a":"Je správně. Útok na vady vyžaduje vytvořit nebo získat seznam možných chyb, defektů a selhání (např. z údajů o defektech) a navrhnout testy, které je odhalí nebo vyvolají.","b":"Není správně. Při průzkumném testování se testy navrhují, provádějí a vyhodnocují souběžně s poznáváním testovaného objektu, ne podle předem získaného seznamu selhání.","c":"Není správně. Kontrolní seznam obsahuje testovací podmínky, které se ověřují; zde jde o seznam selhání, na která se testy cíleně zaměří.","d":"Není správně. Testování dle rozhodovací tabulky je technika černé skříňky vycházející z kombinací podmínek ve specifikaci."},"obecne":"<p>Sylabus 4.4.1: Útok na vady je příkladem implementace odhadování chyb. Testeři vytvoří nebo získají seznam možných chyb, defektů a selhání – na základě zkušeností, údajů o defektech a selháních nebo obecných znalostí – a navrhnou testy, které je identifikují, odhalí nebo způsobí.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"}},{"id":"UP-1-27","n":null,"lo":"FL-4.4.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NEJLÉPE popisuje průzkumné testování?<\/p>","m":["<p>Testování založené na zkušenostech, znalostech a intuici testera.<\/p>","<p>Přístup k testování, při kterém testeři dynamicky navrhují a provádějí testy na základě svých znalostí, průzkumu testované položky a výsledků předchozích testů.<\/p>","<p>Praxe testování, při které se k identifikaci potenciálních slabin, jež jsou následně prověřovány testovacími případy, používá hloubkové zkoumání pozadí testovaného objektu.<\/p>","<p>Přístup k návrhu testů, při kterém jsou testovací činnosti plánovány jako nepřerušované relace testovací analýzy a návrhu testů, často ve spojení s kontrolními seznamy.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Jde o definici testování založeného na zkušenostech obecně, ne konkrétně průzkumného testování.","b":"Je správně. Testy se při průzkumném testování souběžně navrhují, provádějí a vyhodnocují, zatímco tester získává znalosti o testovaném objektu.","c":"Není správně. Průzkumné testování se často provádí při nedostatku času, takže hloubkové zkoumání pozadí testovaného objektu je nepravděpodobné.","d":"Není správně. Popis vychází z definice testování v relacích, ale provádění testů je v něm nahrazeno testovací analýzou."},"obecne":"<p>Sylabus 4.4.2: Při průzkumném testování jsou testy současně navrhovány, prováděny a vyhodnocovány, zatímco testeři získávají znalosti o testovaném objektu.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.2","nazev":"Průzkumné testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-dva-pruzkumne-testovani"}},{"id":"UP-1-28","n":null,"lo":"FL-4.5.1","k":"K2","k3":true,"vyber":1,"q":"<p>Se zástupci byznysu a vlastníkem produktu revidujete následující uživatelský scénář:<\/p><p><em>Jako majitel psa chci svého psa zaregistrovat online, abych mohl rychle splnit zákonnou povinnost spojenou s jeho vlastnictvím.<\/em><\/p><p>Scénář posuzujete podle kritérií INVEST. Které kritérium tento scénář zatím NESPLŇUJE a vyžadoval by další rozpracování?<\/p>","m":["<p>Hodnotný<\/p>","<p>Zabezpečený<\/p>","<p>Testovatelný<\/p>","<p>Úplný podle konceptu 3C<\/p>"],"ok":[2],"vys":{"a":"Není správně. Hodnota je ve scénáři uvedena – rychlé splnění zákonné povinnosti.","b":"Není správně. Zabezpečení není jedním z kritérií INVEST (nezávislý, schůdný, hodnotný, odhadnutelný, malý, testovatelný).","c":"Je správně. Scénář nemá akceptační kritéria, takže není jasné, jak ověřit, že je splněn; je třeba ho rozpracovat, aby byl testovatelný.","d":"Není správně. Koncept 3C (karta, konverzace, potvrzení) popisuje části uživatelského scénáře, není kritériem INVEST."},"obecne":"<p>Sylabus 4.5.1: Správné uživatelské scénáře by měly splňovat INVEST – nezávislé, schůdné, hodnotné, odhadnutelné, malé a testovatelné. Pokud zainteresované strany nevědí, jak scénář otestovat, nemusí být dostatečně jasný; zde chybí akceptační kritéria (potvrzení).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.5.1","nazev":"Společné psaní uživatelských scénářů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-jedna-spolecne-psani-uzivatelskych-scenaru"}},{"id":"UP-1-29","n":null,"lo":"FL-4.5.3","k":"K3","k3":true,"vyber":1,"q":"<p>Pracujete jako tester v agilním projektu a obdržíte následující uživatelský scénář:<\/p><p><em>Jako administrátor chci odebrat existujícímu účtu přístupová oprávnění ke komponentě reportování prodejů v našem e-commerce systému, abychom mohli řídit přístup k údajům o prodejích.<\/em><\/p><p>Testovací případy ATDD zapisujete do tabulky se sloupci ID, Akce, Účet a Očekávaný výsledek. Akce může být jedna z následujících: ‘add-account’, ‘delete-account’, ‘add-privilege’, ‘remove-privilege’, ‘view-sales’ nebo ‘report-sales’.<\/p><p>Všechny tyto akce kromě ‘remove-privilege’ byly úspěšně implementovány a otestovány v předchozích iteracích a testovací účty vytvořené v těchto iteracích (včetně jejich oprávnění) stále existují v testovacích datech.<\/p><p>Která z následujících podmnožin testovacích případů ATDD je proveditelná a zároveň poskytuje NEJRYCHLEJŠÍ zpětnou vazbu k nově přidávané funkci? Každý řádek je zapsán jako (ID, Akce, Účet, Očekávaný výsledek).<\/p>","m":["<p>(1, add-privilege, test-acct-1, „Oprávnění k prodejním datům přidáno“); (2, remove-privilege, test-acct-1, „Oprávnění k prodejním datům odebráno“)<\/p>","<p>(1, add-account, test-acct-1, „Účet přidán“); (2, add-privilege, test-acct-1, „Oprávnění k prodejním datům přidáno“); (3, remove-privilege, test-acct-1, „Oprávnění k prodejním datům odebráno“)<\/p>","<p>(1, add-account, test-acct-1, „Účet přidán“); (2, add-privilege, test-acct-1, „Oprávnění k prodejním datům přidáno“); (3, report-sales, test-acct-1, „Report prodejů zobrazen“); (4, remove-privilege, test-acct-1, „Oprávnění k prodejním datům odebráno“)<\/p>","<p>(1, remove-privilege, test-acct-1, „Oprávnění k prodejním datům odebráno“)<\/p>"],"ok":[3],"vys":{"a":"Není správně. Přidání oprávnění je již otestováno a jen zbytečně oddaluje zpětnou vazbu k nové funkci.","b":"Není správně. Vytvoření účtu a přidání oprávnění jsou zbytečné kroky, protože testovací účty s oprávněním již existují.","c":"Není správně. Obsahuje ještě více zbytečných kroků (včetně zobrazení reportu), které s novou funkcí přímo nesouvisejí.","d":"Je správně. Ostatní akce jsou již otestované a testovací data existují, takže jediný test přímo ověřuje novou funkci a dává nejrychlejší zpětnou vazbu."},"obecne":"<p>Sylabus 4.5.3: Testovací případy ATDD vycházejí z akceptačních kritérií uživatelského scénáře, mají pokrývat jeho charakteristiky a nepřesahovat jeho rámec. Protože ostatní akce i testovací data již existují, stačí jediný test akce ‘remove-privilege’.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UP-1-30","n":null,"lo":"FL-5.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího NENÍ součástí plánu testování?<\/p>","m":["Výsledek analýzy specifikací","Vstupní a výstupní kritéria","Funkce, které se nebudou testovat","Potřebné zdroje"],"ok":[0],"vys":{"a":"Je správně. Výsledkem analýzy specifikací jsou testovací podmínky; vznikají při testovací analýze, ne v plánu testování.","b":"Není správně. Vstupní a výstupní kritéria jsou součástí přístupu k testování v plánu testování.","c":"Není správně. Vymezení rozsahu včetně toho, co se testovat nebude, patří do kontextu testování v plánu testování.","d":"Není správně. Plán testování popisuje cíle, zdroje a procesy testování."},"obecne":"Sylabus 5.1.1: Plán testování popisuje cíle, zdroje a procesy testování (kontext a rozsah, předpoklady a omezení, zainteresované strany, komunikaci, registr rizik, přístup k testování včetně vstupních a výstupních kritérií, rozpočet a harmonogram). Výsledky analýzy testovací báze jsou výstupem testovací analýzy.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.1","nazev":"Účel a obsah plánu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-jedna-ucel-a-obsah-planu-testovani"}},{"id":"UP-1-31","n":null,"lo":"FL-5.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení platí pro agilní tým?<\/p>","m":["Plány vydání jsou podrobné, zatímco plány iterací jsou vysokoúrovňové.","Plány vydání jsou vysokoúrovňové, zatímco plány iterací jsou podrobné.","Plánování vydání přesně stanovuje předpoklady pro vydání každého přírůstku.","Plánování vydání se zaměřuje na akceptační kritéria, plánování iterace na regresní testy."],"ok":[1],"vys":{"a":"Není správně. Je tomu naopak – při plánování vydání tým ještě podrobně neví, jak položky backlogu implementovat.","b":"Je správně. Plánování vydání pracuje s produktovým backlogem a hrubě odhadnutými položkami, plánování iterace vyžaduje podrobnou analýzu a podrobnější odhady.","c":"Není správně. Plánování vydání vyhlíží dopředu k vydání produktu a pracuje s hrubými odhady; přesné předpoklady pro jednotlivé přírůstky nestanovuje.","d":"Není správně. Plánování iterace se zabývá backlogem iterace, podrobnou analýzou rizik a rozkladem uživatelských scénářů do úkolů, nejen regresními testy."},"obecne":"Sylabus 5.1.2: Plánování vydání vyhlíží dopředu k vydání produktu a definuje a upravuje produktový backlog. Plánování iterace vyhlíží ke konci jedné iterace, pracuje s backlogem iterace a zahrnuje podrobnou analýzu rizik uživatelských scénářů a jejich rozklad do úkolů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.2","nazev":"Přínos testerů při plánování iterací a vydání","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-dva-prinos-testeru-pri-planovani-iteraci-a-vydani"}},{"id":"UP-1-32","n":null,"lo":"FL-5.1.4","k":"K3","k3":false,"vyber":1,"q":"<p>Které z následujících tvrzení o plánovacím pokeru NENÍ správné?<\/p>","m":["Během plánovacího pokeru probíhá diskuse a odhadci své odhady zdůvodňují.","Doporučuje se, aby tým provádějící odhad zahrnoval zástupce různých rolí.","Plánovací poker hrají pouze seniorní členové týmu a vlastník produktu.","Plánovací poker spojuje při odhadování názory více odborníků."],"ok":[2],"vys":{"a":"Není správně (tvrzení platí). Rozdílné odhady se diskutují a odhadci je zdůvodňují, poté se odhaduje znovu.","b":"Není správně (tvrzení platí). Cross-funkční složení týmu umožňuje zohlednit pracnost vývoje i testování.","c":"Je správně (tvrzení neplatí). Plánovací poker hraje celý tým, nikoli jen seniorní členové.","d":"Není správně (tvrzení platí). Plánovací poker je varianta Wideband Delphi, tedy techniky založené na expertech."},"obecne":"Sylabus 5.1.4: Plánovací poker je varianta techniky Wideband Delphi používaná v agilním vývoji. Odhady provádí celý tým pomocí karet s čísly, rozdílné odhady se diskutují a odhad se opakuje až do dosažení shody.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UP-1-35","n":null,"lo":"FL-5.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Následující seznam obsahuje rizika, která byla identifikována pro vyvíjený softwarový produkt. Které z těchto rizik je příkladem produktového rizika?<\/p>","m":["Dodavatel třetí strany nedodává podle ujednání","Dodávka softwaru je opožděna oproti harmonogramu","Nedostatek kvalifikovaných testerů k dokončení plánovaných testů","Chybný výpočet v softwaru může ohrozit život pacienta"],"ok":[3],"vys":{"a":"Není správně. Selhání dodávky třetí strany je projektové riziko (problémy s dodavateli).","b":"Není správně. Zpoždění dodávky je projektové riziko (organizační problémy).","c":"Není správně. Nedostatek kvalifikovaných lidí je projektové riziko (problémy s lidmi).","d":"Je správně. Riziko souvisí s kvalitou produktu (nesprávné výpočty) a jeho důsledkem může být zranění nebo smrt."},"obecne":"Sylabus 5.2.2: Projektová rizika se týkají managementu a řízení projektu (organizace, lidé, technika, dodavatelé). Produktová rizika souvisejí s kvalitativními charakteristikami produktu (např. nesprávné výpočty) a jejich důsledkem může být i fyzické poškození, zranění nebo smrt.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.2.2","nazev":"Projektová a produktová rizika","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-dva-projektova-a-produktova-rizika"}},{"id":"UP-1-36","n":null,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Jako manažer testování máte připravit souhrnný report z testování. Co z následujícího je jeho hlavním obsahem týkajícím se testovacích činností?<\/p>","m":["Shrnutí hlavních testovacích činností, událostí a jejich stavu vůči cílům","Rozdíly mezi skutečnými a očekávanými výsledky jednotlivých testů","Školení, která členové týmu absolvovali na podporu testování","Počet testovacích případů navržených technikami černé skříňky"],"ok":[0],"vys":{"a":"Je správně. Souhrnný report shrnuje testy a vyhodnocuje testování vůči cílům testování a výstupním kritériím.","b":"Není správně. Rozdíly mezi očekávaným a skutečným výsledkem konkrétního testu se uvádějí v reportu o defektu.","c":"Není správně. Školení týmu nepatří k obsahu souhrnného reportu z testování.","d":"Není správně. Takto podrobná metrika návrhu testů není hlavním obsahem souhrnného reportu."},"obecne":"Sylabus 5.3.2: Souhrnný report z testování obsahuje shrnutí testů, vyhodnocení testování a kvality produktu vůči plánu (cílům a výstupním kritériím), odchylky od plánu, překážky, metriky, neošetřená rizika, nevyřešené defekty a ponaučení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UP-1-38","n":null,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Testovací inženýr testuje videopřehrávač (videorekordér) a zaznamená tento report:<\/p><p>Název: Rychlé převíjení vpřed se zastaví po 2 minutách. Děje se to pokaždé.<br>Očekávaný výsledek: Rychlé převíjení vpřed pokračuje až do konce pásky.<br>Závažnost: Vysoká<br>Priorita: Naléhavá<\/p><p>Kterou důležitou informaci inženýr vynechal?<\/p>","m":["Historii všech změn stavu tohoto reportu","Identifikaci testovaného objektu (verze softwaru a hardwaru)","Skutečný výsledek pozorovaný při provedení testu","Nápady na zlepšení použitého testovacího případu"],"ok":[1],"vys":{"a":"Není správně. U nového reportu historie změn ještě neexistuje; stav a jeho změny obvykle eviduje nástroj pro management defektů.","b":"Je správně. Bez identifikace testovaného objektu a prostředí nelze selhání spolehlivě reprodukovat.","c":"Není správně. Skutečný výsledek je uveden již v názvu – převíjení se zastaví po 2 minutách.","d":"Není správně. Nápady na zlepšení testovacího případu do reportu o defektu nepatří."},"obecne":"Sylabus 5.5: Report o defektu obvykle obsahuje identifikaci testovaného objektu a testovacího prostředí. Bez ní vývojář neví, kterou verzi softwaru a hardwaru má zkoumat.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UP-1-39","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Do které kategorie byste typicky zařadili nástroje používané k provádění zátěžového a stresového testování?<\/p>","m":["Nástroje pro provedení testů a měření pokrytí","Nástroje pro spolupráci","Nástroje pro nefunkcionální testování","Nástroje pro management testování"],"ok":[2],"vys":{"a":"Není správně. Tyto nástroje usnadňují automatizované provádění testů a měření pokrytí, nejsou určeny pro zátěž.","b":"Není správně. Nástroje pro spolupráci usnadňují komunikaci v týmu.","c":"Je správně. Nástroje pro nefunkcionální testování umožňují provádět testy, které jsou manuálně obtížné nebo nemožné, např. zátěžové a stresové.","d":"Není správně. Nástroje pro management testování spravují proces testování, testovací případy, defekty a konfiguraci."},"obecne":"Sylabus 6.1: Nástroje pro nefunkcionální testování umožňují testerovi provádět nefunkcionální testování, které je obtížné nebo nemožné provést manuálně – typicky testování výkonnosti, zátěžové a stresové testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-1-40","n":null,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího je NEJPRAVDĚPODOBNĚJI rizikem automatizace testů?<\/p>","m":["Více subjektivního hodnocení výsledků testů","Nárůst opakující se manuální práce","Přesné odhady času, nákladů a pracnosti údržby testovacích skriptů","Nekompatibilita nástroje pro automatizaci s vývojovou platformou"],"ok":[3],"vys":{"a":"Není správně. Automatizace přináší objektivnější a konzistentnější hodnocení – to je přínos.","b":"Není správně. Omezení opakující se manuální práce je naopak přínosem automatizace.","c":"Není správně. Rizikem jsou nepřesné odhady; přesné odhady rizikem nejsou.","d":"Je správně. Nekompatibilita nástroje s vývojovou platformou je typickým rizikem automatizace testů."},"obecne":"Sylabus 6.2: Mezi rizika automatizace testů patří mj. nerealistická očekávání, nepřesné odhady času, nákladů a pracnosti, nekompatibilita nástroje s vývojovou platformou a volba nevhodného nástroje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}},{"id":"UP-2-01","n":null,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NEJLÉPE popisuje testovací případ?<\/p><p><br><\/p>","m":["Sada vstupních hodnot a očekávaných výsledků se vstupními a výstupními podmínkami provedení, vytvořená pro konkrétní testovací podmínku.","Testovatelný aspekt komponenty nebo systému, např. funkce, transakce, užitná vlastnost nebo atribut kvality, určený jako základ pro testování.","Posloupnost akcí pro provedení testu, známá také jako testovací skript nebo manuální testovací skript.","Atribut systému specifikovaný v dokumentaci požadavků (například spolehlivost, použitelnost nebo omezení návrhu), který je prověřen testem."],"ok":[0],"vys":{"a":"Je správně. Testovací případ obsahuje vstupy, očekávané výsledky a vstupní a výstupní podmínky a je odvozen z testovací podmínky.","b":"Není správně. Toto je popis testovací podmínky.","c":"Není správně. Toto je popis testovací procedury (testovacího skriptu).","d":"Není správně. Toto je popis užitné vlastnosti (feature)."},"obecne":"Sylabus 1.4.1 a 1.4.3: Při návrhu testů se testovací podmínky rozpracovávají do testovacích případů. Testovací případ je sada vstupních podmínek, vstupů, očekávaných výsledků a výstupních podmínek vytvořená na základě testovací podmínky.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"UP-2-02","n":null,"lo":"FL-1.2.2","k":"K1","k3":true,"vyber":1,"q":"<p>Co je kvalita?<\/p>","m":["Činnosti zaměřené na poskytnutí důvěry, že požadavky na kvalitu budou splněny.","Stupeň, do jakého pracovní produkt splňuje stanovené i implicitní potřeby svých zainteresovaných stran.","Celkové náklady na činnosti související s kvalitou, tj. náklady na prevenci, hodnocení a interní a externí selhání.","Stupeň, do jakého komponenta nebo systém chrání informace a data podle úrovně oprávnění osob či systémů."],"ok":[1],"vys":{"a":"Není správně. Toto je definice zajištění kvality (QA).","b":"Je správně. Toto je definice kvality podle slovníku ISTQB.","c":"Není správně. Toto je definice nákladů na kvalitu.","d":"Není správně. Toto je definice zabezpečení (security)."},"obecne":"Podle slovníku ISTQB je kvalita stupeň, do jakého pracovní produkt splňuje stanovené i implicitní potřeby svých zainteresovaných stran. Testování (sylabus 1.2) je jedním ze způsobů řízení kvality.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.2.2","nazev":"Testování a zajištění kvality","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-dva-testovani-a-zajisteni-kvality"}},{"id":"UP-2-03","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje jeden ze sedmi klíčových principů testování softwaru?<\/p>","m":["Kompletní testování je při dostatečném úsilí a podpoře nástrojů proveditelné pro jakýkoli software.","Automatizované testy umožňují kompletní testování, které u manuálních testů není možné.","U softwarového systému obvykle není možné otestovat všechny kombinace vstupů a výstupů.","Účelem testování je prokázat, že v testovaném objektu nejsou žádné defekty."],"ok":[2],"vys":{"a":"Není správně. Kompletní testování není možné s výjimkou triviálních případů, bez ohledu na úsilí a nástroje.","b":"Není správně. Ani automatizace neumožní otestovat všechny kombinace vstupů, s výjimkou triviálních případů.","c":"Je správně. Odpovídá principu Kompletní testování není možné.","d":"Není správně. Testování prokazuje přítomnost defektů, nikoli jejich nepřítomnost."},"obecne":"Sylabus 1.3, princip 2: Kompletní testování není možné. Testování všeho (např. všech kombinací vstupů) není možné s výjimkou triviálních případů, proto je lepší zaměřit se na techniky testování, prioritizaci testovacích případů a testování založené na rizicích.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-2-04","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Následující tvrzení se týkají činností, které jsou součástí procesu testování:<\/p><p>(i) Identifikace testovacích dat potřebných pro testovací podmínky a testovací případy<br>(ii) Vytváření automatizovaných testovacích skriptů<br>(iii) Návrh testovacího prostředí<br>(iv) Vytváření a prioritizace testovacích procedur<br>(v) Ověření, že je testovací prostředí správně nastaveno<\/p><p>Které z následujících tvrzení je PRAVDIVÉ?<\/p>","m":["(i) a (ii) jsou součástí návrhu testů, (iii), (iv) a (v) jsou součástí implementace testování.","(i) a (v) jsou součástí návrhu testů, (ii), (iii) a (iv) jsou součástí implementace testování.","(i) a (iv) jsou součástí návrhu testů, (ii), (iii) a (v) jsou součástí implementace testování.","(i) a (iii) jsou součástí návrhu testů, (ii), (iv) a (v) jsou součástí implementace testování."],"ok":[3],"vys":{"a":"Není správně. Vytváření automatizovaných testovacích skriptů patří do implementace testování, návrh testovacího prostředí do návrhu testů.","b":"Není správně. Ověření nastavení prostředí patří do implementace, návrh prostředí do návrhu testů.","c":"Není správně. Vytváření a prioritizace testovacích procedur patří do implementace testování.","d":"Je správně. Požadavky na testovací data a návrh testovacího prostředí patří do návrhu testů; skripty, testovací procedury a ověření prostředí do implementace testování."},"obecne":"Sylabus 1.4.1: Návrh testů zahrnuje stanovení požadavků na testovací data a návrh testovacího prostředí. Implementace testování zahrnuje vytvoření testovacích procedur a jejich prioritizaci v harmonogramu, vytvoření manuálních a automatizovaných testovacích skriptů a sestavení testovacího prostředí včetně ověření jeho správného nastavení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"UP-2-05","n":null,"lo":"FL-1.4.2","k":"K2","k3":true,"vyber":1,"q":"Který z následujících faktorů NEJPRAVDĚPODOBNĚJI ovlivní způsob, jakým se testování provádí?","m":["Časový plán projektu a termíny","Umístění kanceláře projektového manažera","Barevné schéma testovacího prostředí","Preference vývojářů ohledně barevného motivu vývojového prostředí"],"ok":[0],"vys":{"a":"Je správně. Omezení projektu (rozsah, čas, rozpočet, zdroje) patří mezi faktory, které ovlivňují, jak se testování provádí.","b":"Není správně. Umístění kanceláře není faktorem kontextu, který by sylabus uváděl jako vliv na testování.","c":"Není správně. Barevné schéma prostředí nemá vliv na strategii, techniky ani rozsah testování.","d":"Není správně. Osobní preference vzhledu vývojového prostředí nejsou faktorem kontextu testování."},"obecne":"Sylabus 1.4.2: Způsob, jakým se testování provádí, závisí na kontextu, např. na zainteresovaných stranách, členech týmu, oboru podnikání, technických faktorech, omezeních projektu (rozsah, čas, rozpočet, zdroje), organizačních faktorech, SDLC a nástrojích.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.2","nazev":"Proces testování v souvislostech","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-dva-proces-testovani-v-souvislostech"}},{"id":"UP-2-07","n":null,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":1,"q":"<p>Který z následujících bodů je klíčovým aspektem týmového přístupu?<\/p>","m":["<p>Přidělování pevných rolí členům týmu<\/p>","<p>Usnadňování komunikace a spolupráce<\/p>","<p>Vyloučení zástupců byznysu z týmu<\/p>","<p>Podpora izolovaného pracovního prostředí (sil)<\/p>"],"ok":[1],"vys":{"a":"Přidělování pevných rolí členům týmu může omezit flexibilitu a přizpůsobivost týmu, což je v rozporu s týmovým přístupem. V týmovém přístupu jsou členové týmu vedeni k tomu, aby přebírali různé odpovědnosti a spolupracovali napříč oblastmi na dosažení společných cílů, místo aby byli omezeni na konkrétní role.","b":"Usnadňování komunikace a spolupráce je klíčovým aspektem týmového přístupu. Podporou otevřených komunikačních kanálů a vedením členů týmu ke spolupráci na společných cílech vytváří týmový přístup kulturu sdílené odpovědnosti, sdílení znalostí a společného řešení problémů.","c":"Vyloučení zástupců byznysu z týmu je v rozporu s týmovým přístupem, který zdůrazňuje důležitost zapojení všech relevantních zainteresovaných stran, včetně zástupců byznysu, do procesu vývoje. Zástupci byznysu poskytují cenné poznatky, požadavky a zpětnou vazbu, které jsou nezbytné pro úspěšné dodání produktů a projektů.","d":"Podpora izolovaného pracovního prostředí (sil) jde proti týmovému přístupu, jehož cílem je odbourávat bariéry mezi různými rolemi a podporovat spolupráci a komunikaci mezi členy týmu. Izolované pracovní prostředí může bránit sdílení znalostí a odbornosti, což vede k neefektivitě a nedostatku součinnosti v týmu."},"obecne":"Sylabus 1.5.2: Týmový přístup zvyšuje týmovou dynamiku, zlepšuje komunikaci a spolupráci v rámci týmu a vytváří synergii. Členové týmu sdílejí pracovní prostor a testeři úzce spolupracují i se zástupci byznysu a vývojáři; izolace, pevné role nebo vyloučení byznysu jsou s ním v rozporu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"UP-2-09","n":null,"lo":"FL-2.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících bodů jsou osvědčenými postupy testování platnými v jakémkoli modelu životního cyklu vývoje softwaru (SDLC)?<\/p><p>I. Zajistit, aby byly v softwaru odhaleny všechny defekty.<\/p><p>II. Ke každé vývojové činnosti existuje odpovídající testovací činnost.<\/p><p>III. Testeři se zapojují do revize pracovních produktů, jakmile jsou k dispozici jejich pracovní verze (drafty).<\/p><p>IV. Každá úroveň testování má své specifické cíle testování.<\/p>","m":["<p>I a II<\/p>","<p>I a III<\/p>","<p>II, III a IV<\/p>","<p>I, III a IV<\/p>"],"ok":[2],"vys":{"a":"Není správně. Obsahuje nesprávný bod I a chybí body III a IV.","b":"Není správně. Obsahuje nesprávný bod I a chybí body II a IV.","c":"Je správně. Body II, III a IV jsou osvědčené postupy platné v každém modelu SDLC.","d":"Není správně. Bod I není osvědčeným postupem – kompletní testování není možné a testování nemůže prokázat nepřítomnost defektů."},"obecne":"Sylabus 2.1.2: osvědčenými postupy nezávislými na modelu SDLC jsou: ke každé vývojové činnosti existuje odpovídající testovací činnost; každá úroveň testování má své specifické cíle; testovací analýza a návrh testů začínají během odpovídající vývojové fáze; testeři se zapojují do revize pracovních produktů, jakmile jsou k dispozici jejich pracovní verze. Bod I je v rozporu s principem, že testování prokazuje přítomnost defektů, nikoli jejich nepřítomnost (kompletní testování není možné).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"}},{"id":"UP-2-10","n":null,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje vývoj řízený testy (TDD)?<\/p>","m":["<p>TDD se zaměřuje na vytvoření rozsáhlých návrhových dokumentů před kódováním.<\/p>","<p>TDD se zabývá především testováním uživatelského rozhraní aplikace.<\/p>","<p>TDD spočívá v psaní testů až po napsání kódu, aby byl pokryt veškerý kód.<\/p>","<p>TDD začíná psaním testů, které řídí psaní kódu; testy i kód lze pak refaktorovat.<\/p>"],"ok":[3],"vys":{"a":"Není správně. V TDD je psaní kódu řízeno testovacími případy místo rozsáhlého návrhu softwaru.","b":"Není správně. TDD se uplatňuje především při testování komponent, ne při testování uživatelského rozhraní.","c":"Není správně. V TDD se testy píší před kódem, nikoli po něm.","d":"Je správně. Nejprve se napíší testy, potom kód, který jim vyhovuje, a následně mohou být testy i kód refaktorovány."},"obecne":"Sylabus 2.1.3: ve vývoji řízeném testy (TDD) je psaní kódu řízeno testovacími případy (místo rozsáhlého návrhu softwaru). Nejprve se napíší testy, poté kód tak, aby testům vyhovoval, a následně mohou (ale nemusí) být testy i kód refaktorovány.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UP-2-11","n":null,"lo":"FL-2.1.5","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících scénářů ukazuje přístup shift left (posun doleva)?<\/p>","m":["<p>Testeři se účastní schůzek ke sběru požadavků, aby včas identifikovali testovací podmínky<\/p>","<p>Uživatelské akceptační testování (UAT) se odkládá až na samotný konec vývoje<\/p>","<p>Zátěžové testování se provádí až poté, co byl software vydán zákazníkům<\/p>","<p>Automatizované testy komponent se implementují až po nasazení softwaru do produkce<\/p>"],"ok":[0],"vys":{"a":"Je správně. Zapojení testerů již při sběru požadavků posouvá testovací činnosti do dřívější fáze SDLC.","b":"Není správně. Odkládání testování na konec vývoje je opakem přístupu shift left.","c":"Není správně. Zátěžové testování až po vydání je pozdní testování, nikoli shift left.","d":"Není správně. Implementace testů komponent až po nasazení do produkce testování posouvá doprava, ne doleva."},"obecne":"Sylabus 2.1.5: shift left znamená provádět testování dříve v SDLC (např. nečekat na implementaci kódu nebo integraci komponent). Typickým příkladem je revidování specifikací z pohledu testerů a včasná identifikace problémů v požadavcích.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"}},{"id":"UP-2-12","n":null,"lo":"FL-2.1.6","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího NEJLÉPE vystihuje, jak se retrospektiva využívá jako mechanismus zlepšování procesu v softwarových projektech?<\/p>","m":["<p>Ke zlepšení procesů a lidí dochází, když se každý den identifikují zlepšení produktu<\/p>","<p>Fakta a metriky z uplynulého období umožňují týmu společně navrhnout zlepšení<\/p>","<p>Retrospektiva umožňuje členům týmu vyventilovat stížnosti a odejít v dobré náladě<\/p>","<p>Na retrospektivě se revidují všechny testovací případy a aktualizují se pro další iteraci<\/p>"],"ok":[1],"vys":{"a":"Není správně. Retrospektiva se zaměřuje na proces a spolupráci týmu, ne na každodenní zlepšování produktu.","b":"Je správně. Tým na základě objektivních informací rozebírá, co se povedlo a co ne, a navrhuje zlepšení.","c":"Není správně. Cílem retrospektivy nejsou stížnosti, ale identifikace konkrétních zlepšení procesu.","d":"Není správně. Revize testovacích případů není účelem retrospektivy, ta hodnotí proces jako celek."},"obecne":"Sylabus 2.1.6: na retrospektivě účastníci rozebírají, co bylo úspěšné, co se nepovedlo a jak zlepšení zavést. Retrospektivy jsou kritické pro kontinuální zlepšování procesu a doporučená opatření je třeba sledovat.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"}},{"id":"UP-2-14","n":null,"lo":"FL-2.3.1","k":"K2","k3":true,"vyber":1,"q":"Co z následujícího určuje rozsah testování údržby?","m":["Defekty nalezené při posledním běhu regresních testů.","Pokrytí aktuální sady regresních testů.","Velikost a riziko jakékoli změny (změn) systému.","Doba, která uplynula od poslední změny systému."],"ok":[2],"vys":{"a":"Není správně. Defekty z posledního regresního běhu mohou pomoci při výběru testů, ale rozsah neurčují.","b":"Není správně. Pokrytí stávající regresní sady rozsah testování údržby neurčuje.","c":"Je správně. Rozsah testování údržby závisí na míře rizika změny, rozsahu změny a velikosti stávajícího systému.","d":"Není správně. Doba od poslední změny rozsah testování údržby neurčuje."},"obecne":"Sylabus 2.3: rozsah testování údržby závisí na míře rizika změny, velikosti stávajícího systému a rozsahu změny. Malá změna s nízkým rizikem (např. oprava překlepu) vyžaduje málo testů, změna klíčového modulu rozsáhlé testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.3","nazev":"Testování údržby","href":"kapitola-2/vyklad.html#cast-dva-tecka-tri-testovani-udrzby"}},{"id":"UP-2-15","n":null,"lo":"FL-3.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících problémů lze ve srovnání se statickým testováním snáze odhalit dynamickým testováním?<\/p>","m":["<p>Vývojáři při psaní kódu nedodržují standard pro pojmenování proměnných.<\/p>","<p>Výkonnostní požadavek „systém by měl pracovat efektivně“ je nejednoznačný.<\/p>","<p>Některé požadavky nelze trasovat k testovacím případům.<\/p>","<p>Systém umožňuje neoprávněnému uživateli získat administrátorská práva.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Odchylky od konvencí pro programování snadno odhalí statická analýza nebo revize kódu.","b":"Není správně. Nejednoznačný požadavek je defekt v požadavcích, který se snáze odhalí revizí.","c":"Není správně. Chybějící pokrytí testovací báze testy se snáze odhalí statickým testováním.","d":"Je správně. Zda systém skutečně umožní neoprávněnému uživateli získat administrátorská práva, se nejsnáze ověří spuštěním softwaru."},"obecne":"<p>Sylabus 3.1.3: dynamické testování hledá selhání za běhu, statické testování nachází defekty přímo. Mezi defekty, které se snáze odhalí statickým testováním, patří defekty v požadavcích, odchylky od norem a chybějící pokrytí testovací báze. Získání administrátorských práv neoprávněným uživatelem se projeví jako selhání za běhu.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"}},{"id":"UP-2-17","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Autor kódu vede revizi svého kódu pro další vývojáře a testery. O jaký typ revize se jedná?<\/p>","m":["<p>Předvedení (walkthrough)<\/p>","<p>Neformální vývojářská revize<\/p>","<p>Audit<\/p>","<p>Inspekce<\/p>"],"ok":[0],"vys":{"a":"Je správně. Předvedení (walkthrough) je revize vedená autorem.","b":"Není správně. Neformální revize se neřídí definovaným procesem; vedení autorem je charakteristické pro předvedení.","c":"Není správně. Audit není typem revize uvedeným v sylabu a obvykle jej provádí nezávislá třetí strana.","d":"Není správně. Inspekci nesmí autor vést – nemůže v ní vystupovat jako vedoucí revize ani zapisovatel."},"obecne":"Sylabus 3.2.4: předvedení (walkthrough) je revize vedená autorem, která může sloužit např. k hodnocení kvality, vzdělávání revidujících a dosažení dohody.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UP-2-18","n":null,"lo":"FL-3.2.5","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících bodů jsou faktory úspěchu revizí?<\/p><p>I. Jsou definovány jasné cíle a měřitelná výstupní kritéria.<\/p><p>II. Účastníci mají na přípravu revize dostatek času.<\/p><p>III. Revize jsou součástí firemní kultury.<\/p><p>IV. Výsledky revize slouží k hodnocení výkonu jejích účastníků.<\/p>","m":["<p>I a III<\/p>","<p>II, III a IV<\/p>","<p>I, II a III<\/p>","<p>IV<\/p>"],"ok":[2],"vys":{"a":"Není správně. Chybí bod II – dostatek času na přípravu je faktorem úspěchu.","b":"Není správně. Bod IV faktorem úspěchu není; hodnotí se pracovní produkt, ne účastníci.","c":"Je správně. Body I, II a III jsou faktory úspěchu podle sylabu.","d":"Není správně. Hodnocení účastníků revize je v rozporu s faktory úspěchu."},"obecne":"Sylabus 3.2.5 uvádí mezi faktory úspěchu jasné cíle a měřitelná výstupní kritéria (hodnocen je pracovní produkt, nikoli účastníci), dostatek času na přípravu a to, že revize jsou součástí firemní kultury. Bod IV je proto chybný.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.5","nazev":"Faktory úspěchu při revizi","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-pet-faktory-uspechu-pri-revizi"}},{"id":"UP-2-20","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Automatická klimatizace zapne topení, když teplota klesne pod 17 °C, a chlazení, když teplota překročí 26 °C. Klimatizace je určena pro provoz při teplotách od −10 °C do +40 °C; teplota se měří v celých stupních. Která z následujících sad hodnot pokrývá všechny třídy ekvivalence (platné i neplatné) s NEJMENŠÍM počtem hodnot?<\/p>","m":["−11, 18, 51","−1, 12, 18, 27","−11, −1, 18, 27, 51","−11, −1, 12, 18, 27, 51"],"ok":[2],"vys":{"a":"Není správně. Chybí hodnoty z tříd „topení“ (−10 až 16) a „chlazení“ (27 až 40).","b":"Není správně. Chybí obě neplatné třídy (pod −10 a nad 40); −1 a 12 navíc patří do stejné třídy.","c":"Je správně. Každá z pěti tříd je pokryta právě jednou hodnotou.","d":"Není správně. Pokrývá sice všech pět tříd, ale −1 a 12 patří do stejné třídy (topení), sada tedy není minimální."},"obecne":"<p>Sylabus 4.2.1: Třídy ekvivalence jsou: pod −10 (neplatná), −10 až 16 (topení), 17 až 26 (bez zásahu), 27 až 40 (chlazení) a nad 40 (neplatná). Hodnoty −11, −1, 18, 27 a 51 pokrývají každou třídu právě jednou.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UP-2-21","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Systém počítá daň z platu takto: prvních 4 000 $ je osvobozeno od daně, dalších 1 500 $ je zdaněno sazbou 10 %, dalších 28 000 $ sazbou 22 % a jakákoli další částka sazbou 40 %. Částky se zadávají v celých dolarech. Která z následujících hodnot je hraniční hodnotou podle analýzy hraničních hodnot?<\/p>","m":["<p>$1500<\/p>","<p>$28000<\/p>","<p>$32001<\/p>","<p>$33501<\/p>"],"ok":[3],"vys":{"a":"Není správně. 1 500 $ leží uvnitř třídy 0–4 000 $.","b":"Není správně. 28 000 $ leží uvnitř třídy 5 501–33 500 $.","c":"Není správně. 32 001 $ leží uvnitř třídy 5 501–33 500 $.","d":"Je správně. 33 501 $ je dolní hraniční hodnota třídy se sazbou 40 %."},"obecne":"<p>Sylabus 4.2.2: Třídy jsou 0–4 000 (0 %), 4 001–5 500 (10 %), 5 501–33 500 (22 %) a od 33 501 (40 %). Hraničními hodnotami jsou 4 000, 4 001, 5 500, 5 501, 33 500 a 33 501 (a 0), takže z nabídnutých je hraniční jen 33 501 $.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UP-2-22","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Daň z příjmu činí 20 % ročně pro všechny příjmy, avšak se dvěma výjimkami: roční příjmy nižší než 5 000 USD jsou od daně osvobozeny a rodiny s jediným výdělečně činným členem a více než pěti členy dostávají slevu na dani 5 %. Kolik testovacích případů vznikne při testování dle úplné (nezjednodušené) rozhodovací tabulky, pokud připadá jeden testovací případ na každé pravidlo?<\/p>","m":["3","4","6","8"],"ok":[3],"vys":{"a":"Není správně. 3 je počet podmínek, ne pravidel.","b":"Není správně. 4 pravidla by měla úplná tabulka se dvěma podmínkami.","c":"Není správně. Žádná kombinace podmínek není neproveditelná, úplná tabulka má tedy všech 2³ pravidel.","d":"Je správně. Tři nezávislé podmínky (příjem < 5 000, jediný výdělečně činný člen, více než 5 členů) dávají 2³ = 8 pravidel."},"obecne":"<p>Sylabus 4.2.3: Úplná rozhodovací tabulka obsahuje sloupec pro každou kombinaci podmínek. Podmínky jsou tři a všechny kombinace jsou proveditelné, tedy 2³ = 8 pravidel. Zjednodušením (sloučením sloupců s příjmem pod 5 000, kde na ostatních podmínkách nezáleží) by vzniklo 5 pravidel, to však otázka nepožaduje.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UP-2-24","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Část kódu operačního systému má 1 200 řádků. Obsahuje jediný příkaz IF bez větve ELSE, jehož tělo obsahuje pouze zobrazení chybového hlášení. Kód neobsahuje žádné další rozhodnutí ani cykly. Kolik testovacích případů je MINIMÁLNĚ potřeba k dosažení 100% pokrytí příkazů a kolik k dosažení 100% pokrytí větví?<\/p>","m":["2 pro pokrytí příkazů a 2 pro pokrytí větví","1 pro pokrytí příkazů a 2 pro pokrytí větví","1 200 pro pokrytí příkazů a 2 pro pokrytí větví","1 pro pokrytí příkazů a 1 pro pokrytí větví"],"ok":[1],"vys":{"a":"Není správně. Pro pokrytí příkazů stačí jediný test, který vstoupí do těla IF.","b":"Je správně. Jeden test s podmínkou splněnou provede všechny příkazy; pro pokrytí větví je třeba ještě test s podmínkou nesplněnou.","c":"Není správně. Jeden test provede všechny příkazy, počet řádků kódu nerozhoduje.","d":"Není správně. Test, který zobrazí chybové hlášení, nepokryje větev, kdy podmínka IF není splněna."},"obecne":"<p>Sylabus 4.3.1 a 4.3.2: Test, ve kterém je podmínka IF splněna, provede všechny spustitelné příkazy (100% pokrytí příkazů). Podmíněná větev „nesplněno“ však zůstane nepokryta, proto 100% pokrytí větví vyžaduje dva testy. Pokrytí větví zaručuje pokrytí příkazů, ale ne naopak.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UP-2-25","n":null,"lo":"FL-4.3.3","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího NEJLÉPE popisuje přínos testování bílé skříňky?<\/p>","m":["<p>Spočívá v provádění testů bez znalosti vnitřní struktury kódu.<\/p>","<p>Spoléhá výhradně na techniky, které nevyžadují přístup k vnitřnímu kódu.<\/p>","<p>Poskytuje objektivní měření pokrytí kódu a informace pro návrh dalších testů.<\/p>","<p>Zaměřuje se na validaci vnějšího chování softwaru.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Testy bez znalosti vnitřní struktury jsou testy černé skříňky.","b":"Není správně. Testování bílé skříňky naopak vychází z vnitřní struktury a zpracování uvnitř testovaného objektu.","c":"Je správně. Výsledky testování bílé skříňky poskytují objektivní měření pokrytí a informace pro vytváření dalších testů, které pokrytí a důvěru v kód zvýší.","d":"Není správně. Vnější chování se typicky ověřuje technikami černé skříňky."},"obecne":"<p>Sylabus 4.3.3: Samotné testování černé skříňky neposkytuje informaci o skutečném pokrytí kódu. Testování bílé skříňky poskytuje objektivní měření pokrytí a informace pro vytvoření dalších testů ke zvýšení pokrytí. Jeho slabinou naopak je, že nemusí odhalit opomenutí implementace požadavků.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"}},{"id":"UP-2-26","n":null,"lo":"FL-4.4.1","k":"K2","k3":true,"vyber":2,"q":"<p>Která DVĚ z následujících tvrzení vysvětlují, proč je odhadování chyb užitečnou technikou testování?<\/p>","m":["<p>Může pomoci odvodit testovací případy na základě analýzy specifikačních dokumentů.<\/p>","<p>Může identifikovat testy, které formální techniky snadno nezachytí.<\/p>","<p>Umí dobře využít zkušenosti testera a dostupná data o defektech.<\/p>","<p>Nachází více defektů než formálnější techniky návrhu testů<\/p>"],"ok":[1,2],"vys":{"a":"Není správně. Odhadování chyb nevychází z analýzy specifikace, ale ze znalostí a zkušeností testera.","b":"Je správně. Techniky založené na zkušenostech mohou odhalit defekty, které techniky černé a bílé skříňky neodhalí.","c":"Je správně. Odhadování chyb využívá znalosti testera o tom, jak aplikace fungovala dříve, o typických chybách vývojářů a o selháních v podobných aplikacích.","d":"Není správně. Není zaručeno, že najde více defektů; techniky založené na zkušenostech jsou doplňkem formálních technik."},"obecne":"<p>Sylabus 4.4 a 4.4.1: Odhadování chyb předvídá výskyt chyb, defektů a selhání na základě znalostí a zkušeností testera (včetně údajů o defektech). Techniky založené na zkušenostech mohou odhalit defekty, které jiné techniky přehlédnou, a jsou jejich doplňkem.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"}},{"id":"UP-2-28","n":null,"lo":"FL-4.5.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících akceptačních kritérií je zapsáno ve formátu orientovaném na scénáře?<\/p>","m":["<p>Za předpokladu, že uživatel vyplnil formulář, když klikne na „Odeslat“, pak se zobrazí potvrzení.<\/p>","<p>Systém zvládne 1 000 současně přihlášených uživatelů bez pádu.<\/p>","<p>Uživatel si může obnovit heslo zodpovězením bezpečnostních otázek.<\/p>","<p>Překročí-li uživatel maximální počet pokusů o přihlášení, účet se dočasně zablokuje.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Kritérium popisuje scénář ve formátu Given/When/Then (za předpokladu – když – pak), typickém pro BDD.","b":"Není správně. Jde o výkonnostní požadavek zapsaný jako pravidlo, ne o scénář.","c":"Není správně. Jde o funkcionální pravidlo bez struktury scénáře (výchozí stav – akce – výsledek).","d":"Není správně. Jde o byznys pravidlo, typickou položku kritérií orientovaných na pravidla."},"obecne":"<p>Sylabus 4.5.2: Dva nejběžnější formáty akceptačních kritérií jsou orientovaný na scénáře (např. formát Given/When/Then používaný v BDD) a orientovaný na pravidla (např. verifikační seznam s odrážkami nebo tabulka mapování vstupů a výstupů).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"}},{"id":"UP-2-29","n":null,"lo":"FL-4.5.3","k":"K3","k3":true,"vyber":1,"q":"<p>Váš tým používá vývoj řízený akceptačními testy (ATDD) k odvození testovacích případů pro následující uživatelský scénář:<\/p><p><em>Jako zákazník chci mít možnost přizpůsobit si nastavení svého profilu, abych si mohl personalizovat své prostředí na platformě.<\/em><\/p><p>Který z následujících testovacích případů je NEJVHODNĚJŠÍ pro ověření tohoto uživatelského scénáře?<\/p>","m":["<p>Otestovat, zda platforma odesílá e-mailová oznámení o aktualizacích profilu.<\/p>","<p>Otestovat, zda platforma umožňuje uživatelům změnit si profilový obrázek.<\/p>","<p>Otestovat, zda platforma podporuje více jazyků pro přizpůsobení profilu.<\/p>","<p>Otestovat, zda platforma zobrazuje doporučená nastavení na základě preferencí uživatele.<\/p>"],"ok":[1],"vys":{"a":"Není správně. E-mailová oznámení jsou samostatná užitná vlastnost a scénář je nepožaduje.","b":"Je správně. Změna profilového obrázku přímo ověřuje možnost přizpůsobit si nastavení profilu, tedy jádro uživatelského scénáře.","c":"Není správně. Podpora více jazyků je samostatná užitná vlastnost a nevaliduje přizpůsobení nastavení profilu.","d":"Není správně. Doporučování nastavení je samostatná užitná vlastnost, která přesahuje rámec scénáře."},"obecne":"<p>Sylabus 4.5.3: Testovací případy ATDD vycházejí z akceptačních kritérií, musí pokrývat charakteristiky uživatelského scénáře a nemají přesahovat jeho rámec. Přímo ho validuje jen test změny profilového obrázku.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UP-2-30","n":null,"lo":"FL-5.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Výstupní kritéria mohou zahrnovat:<\/p><p>i. Míru důkladnosti, např. pokrytí kódu, funkcionality nebo rizik<br>ii. Odhad hustoty defektů nebo míry spolehlivosti<br>iii. Zbytkové riziko, např. neopravené defekty nebo nedostatečné pokrytí testy v určitých oblastech<br>iv. Ověření připravenosti testovacího prostředí<\/p><p>Která z následujících možností je správná?<\/p>","m":["iii a iv jsou správně, i a ii nejsou správně","ii je správně, i, iii a iv nejsou správně","i, ii a iii jsou správně, iv není správně","iv je správně, i, ii a iii nejsou správně"],"ok":[2],"vys":{"a":"Není správně. Bod iv je vstupní kritérium a body i a ii jsou výstupní kritéria.","b":"Není správně. Výstupními kritérii jsou i body i a iii, nejen ii.","c":"Je správně. Míra důkladnosti, hustota defektů a zbytkové riziko jsou typická výstupní kritéria; připravenost prostředí je vstupní kritérium.","d":"Není správně. Připravenost testovacího prostředí je vstupní kritérium a i–iii jsou výstupní kritéria."},"obecne":"Sylabus 5.1.3: Typická výstupní kritéria jsou míry důkladnosti (dosažená úroveň pokrytí, počet nevyřešených defektů, hustota defektů, počet neúspěšných testovacích případů) a binární kritéria ano/ne. Připravenost testovacího prostředí je naopak typickým vstupním kritériem (dostupnost zdrojů).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"}},{"id":"UP-2-31","n":null,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"<p>Manažer testování odhaduje pracnost testování migrace databáze technikou tříbodového odhadu. Pro tento úkol byly stanoveny tyto odhady:<\/p><ul><li><p>Optimistický odhad: 10 hodin<\/p><\/li><li><p>Nejpravděpodobnější odhad: 15 hodin<\/p><\/li><li><p>Pesimistický odhad: 20 hodin<\/p><\/li><\/ul><p>Jaká je podle techniky tříbodového odhadu chyba měření, tj. směrodatná odchylka (SD)?<\/p>","m":["<p>1,67 hodiny<\/p>","<p>2,5 hodiny<\/p>","<p>3,33 hodiny<\/p>","<p>5 hodin<\/p>"],"ok":[0],"vys":{"a":"Je správně. SD = (b − a) / 6 = (20 − 10) / 6 ≈ 1,67 hodiny.","b":"Není správně. 2,5 hodiny = 15 / 6; nejpravděpodobnější odhad se do vzorce pro SD nedosazuje.","c":"Není správně. 3,33 hodiny = 20 / 6; chybí odečtení optimistického odhadu.","d":"Není správně. 5 hodin = (20 − 10) / 2; rozdíl se dělí šesti, ne dvěma."},"obecne":"Sylabus 5.1.4: U tříbodového odhadu se chyba měření vyjadřuje směrodatnou odchylkou SD = (b − a) / 6, kde b je pesimistický a a optimistický odhad: (20 − 10) / 6 ≈ 1,67 hodiny. Výsledný odhad by byl E = (10 + 4 × 15 + 20) / 6 = 15 hodin.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UP-2-33","n":null,"lo":"FL-5.1.6","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího je klíčovým přínosem konceptu testovací pyramidy?<\/p>","m":["Pomoc při rozvržení úsilí věnovaného automatizaci testů na jednotlivých úrovních","Zajištění stejného počtu testovacích případů na všech úrovních testování","Zvýšení závislosti na manuálním testování na vyšších úrovních","Upřednostnění testů GUI před testy komponent a integračními testy"],"ok":[0],"vys":{"a":"Je správně. Testovací pyramida je pomůckou pro určení míry automatizovaných testů a rozložení úsilí mezi vrstvy.","b":"Není správně. Na nižších úrovních má být testů více, na vyšších méně.","c":"Není správně. Zvýšení závislosti na manuálním testování není cílem ani přínosem testovací pyramidy.","d":"Není správně. Pyramida naopak ukazuje, že testů GUI (E2E) má být méně než testů na nižších úrovních."},"obecne":"Sylabus 5.1.6: Testovací pyramida ukazuje, že testy mohou mít různou granularitu, a pomáhá týmu určit míru automatizace testů rozložením pracnosti mezi jednotlivé vrstvy. Ve spodních vrstvách je mnoho malých, rychlých a izolovaných testů, v horní jen několik E2E testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.6","nazev":"Testovací pyramida","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sest-testovaci-pyramida"}},{"id":"UP-2-34","n":null,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"<p>Který testovací kvadrant bude NEJPRAVDĚPODOBNĚJI obsahovat testy, které ověřují interakce mezi komponentami?<\/p>","m":["<p>Kvadrant Q1<\/p>","<p>Kvadrant Q2<\/p>","<p>Kvadrant Q3<\/p>","<p>Kvadrant Q4<\/p>"],"ok":[0],"vys":{"a":"Je správně. Q1 (zaměřený na technologii a podporu týmu) obsahuje testy komponent a integrační testy komponent, které ověřují interakce mezi komponentami.","b":"Není správně. Q2 obsahuje funkcionální testy, příklady, testy uživatelských scénářů, UX prototypy, testování API a simulace.","c":"Není správně. Q3 obsahuje průzkumné testování, testování použitelnosti a uživatelské akceptační testování.","d":"Není správně. Q4 obsahuje smoke testy a nefunkcionální testy (kromě testů použitelnosti)."},"obecne":"Sylabus 5.1.7: Kvadrant Q1 (zaměřený na technologii a podporu týmu) obsahuje testy komponent a integrační testy komponent. Integrační testy komponent se zaměřují právě na interakce a rozhraní mezi komponentami.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"UP-2-35","n":null,"lo":"FL-5.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Čím přispívá identifikace rizik k analýze produktových rizik?<\/p>","m":["Určením rozsahu testování, které má být provedeno","Odhadem celkové úrovně všech identifikovaných rizik","Vytvořením komplexního seznamu možných rizik","Navržením způsobů řešení identifikovaných rizik"],"ok":[2],"vys":{"a":"Není správně. Rozsah testování se určuje na základě výsledků celé analýzy rizik, zejména ohodnocení rizik.","b":"Není správně. Určení pravděpodobnosti, dopadu a úrovně rizik je součástí ohodnocení rizik.","c":"Je správně. Identifikace rizik spočívá ve vytvoření komplexního seznamu rizik, např. pomocí brainstormingu, workshopů nebo rozhovorů.","d":"Není správně. Navržení způsobů řešení rizik je součástí ohodnocení rizik."},"obecne":"Sylabus 5.2.3: Analýza produktových rizik se skládá z identifikace a ohodnocení rizik. Identifikace rizik spočívá ve vytvoření komplexního seznamu rizik; kategorizace, určení pravděpodobnosti, dopadu a úrovně, stanovení priorit a navržení řešení patří do ohodnocení rizik.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.2.3","nazev":"Analýza produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-tri-analyza-produktovych-rizik"}},{"id":"UP-2-37","n":null,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co by systém pro konfigurační management obvykle NEPOSKYTOVAL?<\/p>","m":["Propojení požadavků zákazníka s čísly verzí","Omezený přístup ke knihovně zdrojového kódu","Přesné rozdíly mezi verzemi zdrojového kódu komponent","Porovnání výsledků testů s očekávanými výsledky"],"ok":[3],"vys":{"a":"Není správně. Zaznamenávání vztahů mezi konfiguračními položkami a jejich verzemi je úkolem konfiguračního managementu.","b":"Není správně. Řízení přístupu a změn ke konfiguračním položkám je součástí konfiguračního managementu.","c":"Není správně. Evidence verzí a změn mezi nimi je základní funkcí konfiguračního managementu.","d":"Je správně. Porovnání skutečných a očekávaných výsledků zajišťují nástroje pro provedení testů, ne konfigurační management."},"obecne":"Sylabus 5.4: Konfigurační management slouží k identifikaci, řízení a sledování pracovních produktů – eviduje verze, změny, vztahy mezi položkami a baseline. Porovnávání výsledků testů s očekávanými výsledky k jeho úkolům nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"UP-2-38","n":null,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Pracujete jako tester na systému internetového bankovnictví. Dostupnost je považována za jedno z hlavních produktových rizik (rizik kvality) systému. Najdete reprodukovatelné selhání, při kterém zákazníci při převodu prostředků mezi běžnými typy účtů ztratí spojení s webem banky a po dobu tří až pěti minut se nemohou znovu připojit.<\/p><p>Které z následujících shrnutí by bylo vhodné pro report o defektu k tomuto selhání, tedy takové, které vystihuje jak podstatu selhání, tak jeho dopad na zainteresované strany?<\/p>","m":["Běžný převod mezi účty ukončí relaci zákazníka a opětovné připojení je několik minut nemožné","Vývojáři zanesli závažný defekt dostupnosti, který naše zákazníky vážně rozladí","Protokoly webového serveru ukazují při testu 07.005 chybu 0x44AB27, která není očekávaným hlášením v /tmp","Výkonnost je nízká a spolehlivost pod zátěží je nestabilní"],"ok":[0],"vys":{"a":"Je správně. Shrnutí věcně popisuje konkrétní selhání (ukončení relace při převodu) i jeho dopad na zákazníky (nedostupnost).","b":"Není správně. Shrnutí nepopisuje konkrétní selhání a obviňuje vývojáře, což komunikaci s nimi poškozuje.","c":"Není správně. Technické detaily jsou užitečné pro vývojáře, ale shrnutí nepopisuje selhání ani jeho dopad na zainteresované strany.","d":"Není správně. Shrnutí je příliš vágní – nepopisuje konkrétní selhání ani situaci, kdy nastává."},"obecne":"Sylabus 5.5: Název reportu o defektu má obsahovat krátké shrnutí reportované anomálie a report má uvádět závažnost, tj. dopad na zájmy zainteresovaných stran. Dobré shrnutí popisuje konkrétní pozorované selhání a jeho dopad, je věcné a nikoho neobviňuje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UP-2-39","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících nástrojů je NEJUŽITEČNĚJŠÍ pro reportování metrik testování?<\/p>","m":["<p>Nástroj pro management defektů<\/p>","<p>Nástroj pro management testování<\/p>","<p>Nástroj pro statickou analýzu<\/p>","<p>Nástroj pro měření pokrytí<\/p>"],"ok":[1],"vys":{"a":"Není správně. Nástroj pro management defektů pokrývá jen defekty, ne celkový stav testování.","b":"Je správně. Nástroj pro management testování spravuje požadavky, testy, výsledky a defekty, a proto umí reportovat souhrnné metriky testování.","c":"Není správně. Nástroj pro statickou analýzu hodnotí kód, metriky provádění testů nesleduje.","d":"Není správně. Nástroj pro měření pokrytí měří jen pokrytí kódu, ne celkový postup testování."},"obecne":"Sylabus 6.1: nástroje pro management testování zvyšují efektivitu testování usnadněním správy SDLC, požadavků, testů, defektů a konfigurací. Díky tomu jsou nejužitečnější pro reportování metrik testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-2-40","n":null,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která položka správně uvádí možné riziko automatizace testů?<\/p>","m":["<p>Nástroj se nepoužívá v každém projektu.<\/p>","<p>Realistické odhady času, nákladů a pracnosti zavedení nástroje.<\/p>","<p>Dodavatel nástroje může ukončit činnost.<\/p>","<p>Objektivnější hodnocení (např. měření pokrytí).<\/p>"],"ok":[2],"vys":{"a":"Není správně. Nepoužívání nástroje v každém projektu není rizikem automatizace.","b":"Není správně. Rizikem jsou nepřesné odhady; realistické odhady riziko naopak snižují.","c":"Je správně. Ukončení činnosti dodavatele, vyřazení nebo prodej nástroje je jedním z rizik automatizace.","d":"Není správně. Objektivnější hodnocení je přínosem automatizace."},"obecne":"Sylabus 6.2 uvádí mezi riziky automatizace testů to, že dodavatel nástroje může ukončit činnost, nástroj vyřadit z provozu nebo jej prodat jinému dodavateli.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}},{"id":"UP-3-01","n":null,"lo":"FL-1.2.1","k":"K2","k3":true,"vyber":1,"q":"<p>Proč je testování softwaru někdy vyžadováno z právních důvodů?<\/p>","m":["<p>Zabraňuje tomu, aby vývojáři žalovali testery<\/p>","<p>Mezinárodní zákony vyžadují testování softwaru u exportovaných produktů<\/p>","<p>Testování napříč systémy musí být doprovázeno právní dokumentací<\/p>","<p>Smlouvy mohou stanovovat požadavky na testování, které musí být splněny<\/p>"],"ok":[3],"vys":{"a":"Není správně. Testování nemá nic společného s ochranou testerů před žalobami vývojářů.","b":"Není správně. Neexistují mezinárodní zákony, které by vyžadovaly testování u všech exportovaných produktů.","c":"Není správně. Testování napříč systémy nevyžaduje žádnou zvláštní právní dokumentaci.","d":"Je správně. Testování může být vyžadováno ke splnění smluvních nebo zákonných požadavků či regulatorních norem."},"obecne":"Sylabus 1.2.1: Vedle hodnocení kvality testovaného objektu může být testování softwaru vyžadováno také z důvodu splnění smluvních nebo zákonných požadavků či regulatorních norem.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.2.1","nazev":"Jak testování přispívá k úspěchu","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-jedna-jak-testovani-prispiva-k-uspechu"}},{"id":"UP-3-02","n":null,"lo":"FL-1.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího může být kořenovou příčinou defektu v softwarovém produktu?<\/p><p>(I) Projekt měl neúplné postupy konfiguračního managementu.<br>(II) Harmonogram pro vývoj určité komponenty byl zkrácen.<br>(III) Specifikace byla nejasná.<br>(IV) Dodržování standardů kódování nebylo kontrolováno.<br>(V) Testeři nebyli certifikovaní.<\/p>","m":["(I) až (IV) jsou správně","(I), (II) a (IV) jsou správně","(I) a (II) jsou správně","(III) až (V) jsou správně"],"ok":[0],"vys":{"a":"Je správně. Neúplný konfigurační management, časový tlak, nejasná specifikace i nekontrolované standardy kódování mohou vést k chybám a tím k defektům.","b":"Není správně. Chybí nejasná specifikace (III), která je typickou kořenovou příčinou defektů.","c":"Není správně. Kořenovou příčinou mohou být také nejasná specifikace (III) a nekontrolované standardy kódování (IV).","d":"Není správně. Chybějící certifikace testerů (V) nezpůsobuje vznik defektů v produktu, nanejvýš ovlivní jejich odhalení."},"obecne":"Sylabus 1.2.3: Kořenová příčina je primárním důvodem vzniku problému, např. situace, která vede k chybě. Lidské chyby vznikají např. kvůli časovému tlaku, složitosti pracovních produktů, procesů a infrastruktury. Certifikace testerů neovlivňuje vznik defektů, jen jejich odhalování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"}},{"id":"UP-3-03","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Vlastník produktu (product owner) prohlásí, že vaší rolí testera v agilním týmu je zachytit všechny defekty před koncem každé iterace. Který z následujících principů testování můžete NEJLÉPE použít jako odpověď na toto tvrzení?","m":["Většinu defektů obvykle obsahuje malé množství komponent systému.","Testování může prokázat přítomnost defektů, ale ne jejich nepřítomnost.","Ani odstranění všech nalezených defektů nezaručí úspěch systému.","Defekty odstraněné v rané fázi nezpůsobí další defekty v odvozených produktech."],"ok":[1],"vys":{"a":"Není správně. Princip shlukování defektů říká, kde se defekty nejspíše nacházejí, ne zda lze najít všechny.","b":"Je správně. Testování nemůže prokázat, že žádné defekty nezůstaly, proto nelze slíbit zachycení všech defektů.","c":"Není správně. Princip Nepřítomnost defektů je klam se týká toho, že ani bezchybný systém nemusí splnit potřeby uživatelů, což vlastník produktu nepožaduje.","d":"Není správně. Princip Včasné testování šetří čas a peníze neodpovídá na požadavek najít všechny defekty."},"obecne":"Sylabus 1.3, princip 1: Testování prokazuje přítomnost defektů, nikoli jejich nepřítomnost. Testování snižuje pravděpodobnost, že v testovaném objektu zůstaly neodhalené defekty, ale nemůže prokázat, že v něm žádné nejsou. Požadavek zachytit všechny defekty je proto nesplnitelný.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-3-05","n":null,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Je dán následující testware:<\/p><ol><li>Protokoly z testování<\/li><li>Pokyny k řízení a nápravná opatření<\/li><li>Reporty o defektech v testovací bázi<\/li><li>Souhrnný report z testování<\/li><\/ol><p>a následující testovací činnosti:<\/p><p>w. Testovací analýza<br>x. Provedení testů<br>y. Dokončení testování<br>z. Monitoring a řízení testování<\/p><p>Která z následujících možností NEJLÉPE přiřazuje testware k činnostem, jejichž je výstupem?<\/p>","m":["1w, 2z, 3x, 4y","1z, 2y, 3x, 4w","1x, 2z, 3w, 4y","1x, 2y, 3w, 4z"],"ok":[2],"vys":{"a":"Není správně. Protokoly z testování nevznikají při testovací analýze a reporty o defektech v testovací bázi nevznikají při provedení testů.","b":"Není správně. Protokoly z testování vznikají při provedení testů a souhrnný report při dokončení testování.","c":"Je správně. Protokoly z testování = provedení testů (x), pokyny k řízení = monitoring a řízení (z), reporty o defektech v testovací bázi = testovací analýza (w), souhrnný report = dokončení testování (y).","d":"Není správně. Pokyny k řízení jsou výstupem monitoringu a řízení a souhrnný report výstupem dokončení testování."},"obecne":"Sylabus 1.4.3: Testovací analýza produkuje (prioritizované) testovací podmínky a reporty o defektech v testovací bázi, provedení testů protokoly z testování a reporty o defektech, monitoring a řízení testování reporty o postupu prací, pokyny k řízení a informace o rizicích a dokončení testování souhrnný report z testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"UP-3-06","n":null,"lo":"FL-1.4.5","k":"K2","k3":true,"vyber":1,"q":"<p>Kdo je obvykle zodpovědný za vytvoření a aktualizaci plánu testování pro projekt?<\/p>","m":["Tester","Projektový manažer","Vlastník produktu (product owner)","Manažer testování"],"ok":[3],"vys":{"a":"Není správně. Tester se zaměřuje na testovací analýzu, návrh, implementaci a provedení testů.","b":"Není správně. Projektový manažer odpovídá za projekt jako celek a k plánu testování může přispívat, ale obvykle jej nevytváří.","c":"Není správně. Vlastník produktu odpovídá za produktový backlog a priority, nikoli za plán testování.","d":"Je správně. Plánování testování a vytvoření i aktualizace plánu testování je typickým úkolem manažera testování."},"obecne":"Sylabus 1.4.5: Manažer testování má celkovou odpovědnost za proces testování a zaměřuje se především na plánování testování, monitoring a řízení testování a dokončení testování. Vytvoření a aktualizace plánu testování je proto typicky jeho úkolem.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.5","nazev":"Role v testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-pet-role-v-testovani"}},{"id":"UP-3-11","n":null,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Který z následujících přístupů klade důraz na vytváření testů na základě akceptačních kritérií, které řídí proces vývoje?<\/p>","m":["<p>Vývoj řízený akceptačními testy (ATDD)<\/p>","<p>Vývoj řízený integračními testy (ITDD)<\/p>","<p>Vývoj řízený testy komponent (CTDD)<\/p>","<p>Vývoj řízený systémovými testy (STDD)<\/p>"],"ok":[0],"vys":{"a":"Je správně. ATDD odvozuje testy z akceptačních kritérií jako součást návrhu systému a tyto testy řídí vývoj.","b":"Není správně. Vývoj řízený integračními testy (ITDD) není přístup uvedený v sylabu.","c":"Není správně. Vývoj řízený testy komponent (CTDD) není přístup uvedený v sylabu.","d":"Není správně. Vývoj řízený systémovými testy (STDD) není přístup uvedený v sylabu."},"obecne":"Sylabus 2.1.3: vývoj řízený akceptačními testy (ATDD) odvozuje testy z akceptačních kritérií jako součást procesu návrhu systému; daná část aplikace se vytváří tak, aby vyhověla testům napsaným před samotným vývojem.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UP-3-12","n":null,"lo":"FL-2.1.4","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení přesně popisuje výzvu spojenou se zaváděním DevOps?<\/p>","m":["<p>Snížená složitost správy testovacích prostředí<\/p>","<p>Nutnost definovat a zavést DevOps pipeline pro dodávání<\/p>","<p>Omezený důraz na nefunkcionální charakteristiky kvality<\/p>","<p>Vysoká závislost na manuálních procesech testování<\/p>"],"ok":[1],"vys":{"a":"Není správně. Snížená složitost by byla přínosem, nikoli výzvou; DevOps automatizace usnadňuje vytváření stabilních testovacích prostředí.","b":"Je správně. Sylabus uvádí jako riziko DevOps nutnost definovat a zavést DevOps pipeline.","c":"Není správně. DevOps naopak zvyšuje důraz na nefunkcionální charakteristiky kvality (např. výkonnost, spolehlivost).","d":"Není správně. DevOps snižuje potřebu opakovaného manuálního testování díky automatizaci v pipeline."},"obecne":"Sylabus 2.1.4: mezi rizika a výzvy DevOps patří nutnost definovat a zavést DevOps pipeline, zavést a udržovat nástroje CI/CD a vyšší náklady na tvorbu a údržbu automatizovaných testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"2.1.4","nazev":"DevOps a testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-ctyri-devops-a-testovani"}},{"id":"UP-3-13","n":null,"lo":"FL-2.2.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jak se nazývá forma akceptačního testování, kterou provádějí osoby mimo vývojový tým (např. potenciální zákazníci) v testovacím prostředí vývojářské organizace?<\/p>","m":["<p>Beta testování<\/p>","<p>Testování komponent<\/p>","<p>Alfa testování<\/p>","<p>Regresní testování<\/p>"],"ok":[2],"vys":{"a":"Není správně. Beta testování provádějí zákazníci nebo uživatelé ve svém vlastním prostředí.","b":"Není správně. Testování komponent provádějí obvykle sami vývojáři a nejde o formu akceptačního testování.","c":"Je správně. Alfa testování probíhá v prostředí vývojářské organizace, ale provádějí je osoby mimo vývojový tým.","d":"Není správně. Regresní testování je typ testování po změnách, nikoli forma akceptačního testování vázaná na místo."},"obecne":"Sylabus 2.2.1 uvádí alfa a beta testování mezi formami akceptačního testování. Podle slovníku ISTQB probíhá alfa testování v prostředí vývojářské organizace a provádějí je role mimo vývojovou organizaci, kdežto beta testování provádějí potenciální či stávající uživatelé ve svém vlastním prostředí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"}},{"id":"UP-3-15","n":null,"lo":"FL-3.1.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností obsahuje pouze vhodné kandidáty pro manuální statické testování (revizi)?<\/p>","m":["<p>Specifikace požadavků, plán testování, kód, úniky paměti.<\/p>","<p>Specifikace požadavků, kód, čtení založené na perspektivách.<\/p>","<p>Specifikace požadavků, uživatelské příručky, testování výkonnosti.<\/p>","<p>Specifikace požadavků, testovací případy, uživatelské příručky.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Úniky paměti nejsou pracovní produkt, ale typ defektu.","b":"Není správně. Čtení založené na perspektivách je technika revize, nikoli pracovní produkt.","c":"Není správně. Testování výkonnosti je činnost, nikoli pracovní produkt k revizi.","d":"Je správně. Specifikace požadavků, testovací případy i uživatelské příručky jsou čitelné pracovní produkty vhodné pro revizi."},"obecne":"Sylabus 3.1.1: revizi lze použít na jakýkoli pracovní produkt, který lze přečíst a porozumět mu, např. specifikace požadavků, testovací případy nebo dokumentaci.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.1","nazev":"Pracovní produkty, které mohou být prověřeny statickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-jedna-pracovni-produkty-ktere-mohou-byt-provereny-statickym-testovanim"}},{"id":"UP-3-16","n":null,"lo":"FL-3.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Čtete uživatelský scénář v produktovém backlogu jako přípravu na schůzku s vlastníkem produktu a vývojářem a průběžně si poznamenáváte možné defekty. Které z následujících tvrzení o této činnosti je pravdivé?<\/p>","m":["<p>Jde o statický test, protože statické testování nezahrnuje spuštění testovaného objektu.<\/p>","<p>Jde o statický test, protože jakékoli defekty, které najdete, by bylo možné najít levněji během dynamického testování.<\/p>","<p>Nejde o statický test, protože statické testování se vždy provádí pomocí nástroje.<\/p>","<p>Nejde o statický test, protože statické testování zahrnuje spuštění testovaného objektu.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Jde o revizi, tedy statický test, protože testovaný objekt se nespouští.","b":"Není správně. Defekty nalezené statickým testováním bývají naopak levnější na opravu.","c":"Není správně. Nástroj se používá při statické analýze, revize jej nutně nevyžadují.","d":"Není správně. Statické testování nezahrnuje spuštění testovaného objektu."},"obecne":"Sylabus 3.1: na rozdíl od dynamického testování není při statickém testování nutné testovaný software spouštět; pracovní produkty se hodnotí manuálně (revize) nebo nástrojem (statická analýza). Čtení uživatelského scénáře s poznamenáváním defektů je revize.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"}},{"id":"UP-3-17","n":null,"lo":"FL-3.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících posloupností NEJLÉPE ukazuje hlavní činnosti procesu revize pracovního produktu?<\/p>","m":["<p>Plánování a příprava – Úvodní schůzka – Individuální revize – Oprava – Report<\/p>","<p>Plánování – Zahájení revize – Individuální revize – Komunikace a analýza – Opravy a reportování<\/p>","<p>Zahájení revize – Výběr revidujících – Individuální revize – Komunikace a analýza – Přepracování<\/p>","<p>Příprava – Detekce problémů – Komunikace a analýza problémů – Přepracování – Report<\/p>"],"ok":[1],"vys":{"a":"Není správně. Úvodní schůzka není činností procesu revize a chybí komunikace a analýza.","b":"Je správně. Takto sylabus uvádí činnosti procesu revize.","c":"Není správně. Chybí plánování a výběr revidujících není samostatnou činností procesu revize.","d":"Není správně. Chybí plánování i zahájení revize a posloupnost neodpovídá sylabu."},"obecne":"Sylabus 3.2.2: činnosti procesu revize jsou plánování, zahájení revize, individuální revize, komunikace a analýza a opravy a reportování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.2","nazev":"Činnosti procesu revize","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-dva-cinnosti-procesu-revize"}},{"id":"UP-3-18","n":null,"lo":"FL-3.2.5","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících jsou klíčové faktory úspěchu procesu revize?<\/p>","m":["<p>Účastníci jsou proškoleni, všechny revizní schůzky jsou časově omezeny a moderátory jsou vždy projektoví manažeři.<\/p>","<p>Zapojen je každý člen týmu, na každý pracovní produkt se použijí všechny techniky revize a proces revize řídí manažeři testování.<\/p>","<p>Každá revize má jasný cíl, jsou zapojeni vhodní lidé, je zajištěno školení v technice revize a management proces plně podporuje.<\/p>","<p>Čas na revize je vyhrazen v harmonogramu provedení testů, zlepšování procesu je uznáno na navazující schůzce a cílem je vždy najít defekty.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Moderátory nemusí být projektoví manažeři.","b":"Není správně. Není nutné zapojit každého ani použít všechny techniky revize na každý produkt.","c":"Je správně. Jasné cíle, vhodní účastníci, školení a podpora managementu patří mezi faktory úspěchu revize.","d":"Není správně. Cílem revize nemusí být vždy hledání defektů a vyhrazení času v harmonogramu provedení testů není faktorem úspěchu."},"obecne":"Sylabus 3.2.5 uvádí mezi faktory úspěchu jasné cíle a měřitelná výstupní kritéria, výběr vhodného typu revize pro dané účastníky, podporu managementu a odpovídající školení účastníků.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.5","nazev":"Faktory úspěchu při revizi","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-pet-faktory-uspechu-pri-revizi"}},{"id":"UP-3-19","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Vyvíjený systém obsahuje složité výpočty a rozhodovací logiku. Je hodnocen jako vysoce rizikový, protože vývojový tým nemá v dané aplikační doméně mnoho zkušeností. Která z následujících technik testování by byla NEJVHODNĚJŠÍ pro testování komponent?<\/p>","m":["<p>Rozdělení tříd ekvivalence<\/p>","<p>Testování příkazů<\/p>","<p>Testování přechodů stavů<\/p>","<p>Testování větví<\/p>"],"ok":[3],"vys":{"a":"Není správně. Rozdělení tříd ekvivalence je technika černé skříňky, nepracuje s rozhodovací logikou v kódu a při vysokém riziku samo o sobě nestačí.","b":"Není správně. 100% pokrytí příkazů nezaručuje otestování veškeré rozhodovací logiky.","c":"Není správně. Zadání nezmiňuje žádné stavy ani přechody mezi nimi.","d":"Je správně. Testování větví prověří všechny výsledky rozhodovací logiky v kódu a je silnější než testování příkazů."},"obecne":"<p>Sylabus 4.3.1 a 4.3.2: Testování větví pokryje všechny podmíněné a nepodmíněné větve, a tedy i rozhodovací logiku; 100% pokrytí větví zaručuje i 100% pokrytí příkazů. Pro rizikovou komponentu se složitou rozhodovací logikou je proto nejvhodnější.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UP-3-20","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Systém počítá daň z platu takto: prvních 4 000 £ je osvobozeno od daně, dalších 1 500 £ je zdaněno sazbou 10 %, dalších 28 000 £ sazbou 22 % a jakákoli další částka sazbou 40 %. Částky se zadávají v celých librách. Která z následujících skupin hodnot patří do STEJNÉ třídy ekvivalence?<\/p>","m":["<p>5 800 £; 28 000 £; 32 000 £<\/p>","<p>4 800 £; 14 000 £; 28 000 £<\/p>","<p>5 200 £; 5 500 £; 28 000 £<\/p>","<p>28 001 £; 32 000 £; 35 000 £<\/p>"],"ok":[0],"vys":{"a":"Je správně. Všechny tři hodnoty patří do třídy 5 501–33 500 £ (sazba 22 %).","b":"Není správně. 4 800 £ patří do třídy 4 001–5 500 £, zbylé dvě hodnoty do třídy 5 501–33 500 £.","c":"Není správně. 5 200 £ a 5 500 £ patří do třídy 4 001–5 500 £, 28 000 £ do třídy 5 501–33 500 £.","d":"Není správně. 28 001 £ a 32 000 £ patří do třídy 5 501–33 500 £, 35 000 £ do třídy od 33 501 £."},"obecne":"<p>Sylabus 4.2.1: Třídy jsou 0–4 000 £ (0 %), 4 001–5 500 £ (10 %), 5 501–33 500 £ (22 %) a od 33 501 £ (40 %). Hodnoty 5 800, 28 000 a 32 000 £ leží všechny ve třetí třídě.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UP-3-21","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Velkoobchod prodává tonerové kazety. Minimální objednávka je 5 kusů, na objednávky 100 a více kusů je sleva 20 %. Máte připravit testovací případy s různým počtem objednaných kazet. Která z následujících skupin obsahuje tři vstupy, které jsou hraničními hodnotami podle analýzy hraničních hodnot?<\/p>","m":["1, 20, 100","4, 5, 99","5, 6, 20","4, 5, 80"],"ok":[1],"vys":{"a":"Není správně. 1 a 20 nejsou hraniční hodnoty (hraniční je jen 100).","b":"Je správně. 4, 5 a 99 jsou všechny hraniční hodnoty tříd.","c":"Není správně. 6 a 20 nejsou hraniční hodnoty.","d":"Není správně. 80 není hraniční hodnota."},"obecne":"<p>Sylabus 4.2.2: Třídy jsou ≤ 4 (pod minimem), 5–99 (bez slevy) a ≥ 100 (sleva). Hraničními hodnotami jsou 4, 5, 99 a 100; všechny tři hodnoty jsou hraniční jen ve skupině 4, 5, 99.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UP-3-25","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Čím se liší testování bílé skříňky od testování černé skříňky?<\/p>","m":["<p>Testování bílé skříňky nevyžaduje znalost vnitřního kódu, zatímco testování černé skříňky silně spoléhá na porozumění vnitřní implementaci.<\/p>","<p>Testování bílé skříňky se vztahuje pouze na požadavky vysoké úrovně, zatímco testování černé skříňky se zaměřuje na specifikace nízké úrovně.<\/p>","<p>Testování bílé skříňky vychází z vnitřní struktury a logiky kódu, zatímco testování černé skříňky se zaměřuje na vnější chování.<\/p>","<p>Testování bílé skříňky je vhodnější pro dynamické testování, zatímco testování černé skříňky se používá především pro statické testování.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Je to naopak: znalost vnitřní struktury vyžaduje testování bílé skříňky.","b":"Není správně. Obě kategorie technik lze použít na různých úrovních testování; rozdíl je ve zdroji testovacích případů, ne v úrovni požadavků.","c":"Je správně. Techniky bílé skříňky vycházejí z vnitřní struktury a zpracování uvnitř testovaného objektu, techniky černé skříňky ze specifikovaného chování bez znalosti vnitřní struktury.","d":"Není správně. Obě kategorie se používají při dynamickém testování a techniky bílé skříňky lze použít i při statickém testování."},"obecne":"<p>Sylabus 4.1: Techniky černé skříňky jsou založeny na analýze specifikovaného chování testovaného objektu bez informací o jeho vnitřní struktuře. Techniky bílé skříňky jsou založeny na analýze vnitřní struktury a zpracování uvnitř testovaného objektu.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UP-3-26","n":null,"lo":"FL-5.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího byste očekávali v plánu testování?<\/p>","m":["Podrobný seznam testovacích podmínek pro testování bílé skříňky v první iteraci","Produktový backlog","Popis, jak jsou testovací případy v nástroji pro management testování provázány s požadavky","Přístup k testování, který bude uplatněn při systémovém integračním testování"],"ok":[3],"vys":{"a":"Není správně. Testovací podmínky jsou výstupem testovací analýzy; plán testování je podrobně nevyjmenovává.","b":"Není správně. Produktový backlog je artefakt plánování vydání, nikoli součást plánu testování.","c":"Není správně. Technický popis provázání v nástroji je podrobnost implementace trasovatelnosti, nikoli obsah plánu testování.","d":"Je správně. Přístup k testování (úrovně testování, typy testů, techniky, kritéria aj.) je součástí plánu testování."},"obecne":"Sylabus 5.1.1: Plán testování obsahuje mimo jiné přístup k testování – úrovně testování, typy testů, techniky testování, vstupní a výstupní kritéria, nezávislost testování, metriky a požadavky na testovací data a prostředí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.1","nazev":"Účel a obsah plánu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-jedna-ucel-a-obsah-planu-testovani"}},{"id":"UP-3-28","n":null,"lo":"FL-5.1.4","k":"K3","k3":false,"vyber":1,"q":"<p>Které z následujících přístupů patří mezi techniky odhadování pracnosti testování popsané v sylabu?<\/p><p>I. Přístup založený na dovednostech, kdy odhad vychází z dovedností všech testerů.<br>II. Wideband Delphi, kdy několik expertů samostatně odhaduje a odhady se opakovaně diskutují, dokud není dosaženo shody.<br>III. Odhad na základě poměrů, kdy odhad vychází z poměrů zjištěných v předchozích projektech.<br>IV. Přístup zdola nahoru, kdy každý tester odhadne svou práci a jednotlivé odhady se sečtou.<\/p>","m":["<p>II a III<\/p>","<p>II, III a IV<\/p>","<p>I, III a IV<\/p>","<p>I a IV<\/p>"],"ok":[0],"vys":{"a":"Je správně. Wideband Delphi a odhad na základě poměrů patří mezi čtyři techniky popsané v sylabu.","b":"Není správně. Přístup zdola nahoru (IV) sylabus mezi techniky odhadování neřadí.","c":"Není správně. Přístup založený na dovednostech (I) ani přístup zdola nahoru (IV) sylabus neuvádí.","d":"Není správně. Ani jeden z uvedených přístupů není technikou odhadování podle sylabu."},"obecne":"Sylabus 5.1.4 popisuje čtyři techniky odhadování: odhad na základě poměrů, extrapolaci, Wideband Delphi a tříbodový odhad. Wideband Delphi je iterativní technika, při níž více expertů samostatně odhaduje a postup se opakuje až do dosažení shody.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UP-3-29","n":null,"lo":"FL-5.2.1","k":"K1","k3":true,"vyber":1,"q":"Kterou dvojicí faktorů se charakterizuje (kvantifikuje) riziko?","m":["Produkt a projekt","Pravděpodobnost a dopad","Dopad a náklady","Možnost výskytu a pravděpodobnost"],"ok":[1],"vys":{"a":"Není správně. Produkt a projekt jsou typy rizik, nikoli faktory jejich úrovně.","b":"Je správně. Riziko charakterizuje pravděpodobnost rizika a dopad rizika.","c":"Není správně. Náklady nejsou jedním ze dvou faktorů rizika.","d":"Není správně. Možnost výskytu i pravděpodobnost vyjadřují totéž; chybí dopad."},"obecne":"Sylabus 5.2.1: Riziko lze charakterizovat dvěma faktory – pravděpodobností rizika a dopadem rizika (škodou). Tyto faktory vyjadřují úroveň rizika; při kvantitativním přístupu je úroveň rizika jejich součinem.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.2.1","nazev":"Definice rizika a jeho atributy","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-jedna-definice-rizika-a-jeho-atributy"}},{"id":"UP-3-30","n":null,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Chystáte se předat report o postupu prací při testování vyššímu manažerovi, který není specialistou na testování. Které z následujících témat by v tomto reportu NEMĚLO být uvedeno?<\/p>","m":["Stav plnění stanovených výstupních kritérií v porovnání s plánem","Produktová rizika, která již byla zmírněna, a rizika, která zůstávají otevřená","Podrobný technický popis přístupu k testování založeného na rizicích","Doporučení k řídicím opatřením, která je vhodné v projektu přijmout"],"ok":[2],"vys":{"a":"Není správně. Postup vůči plánu a stav kritérií jsou základním obsahem reportu o postupu prací.","b":"Není správně. Nová a změněná rizika patří do reportu o postupu prací a pro manažera jsou podstatná.","c":"Je správně. Podrobný technický popis přístupu k testování patří do plánu testování; manažer bez znalostí testování ho nepotřebuje.","d":"Není správně. Report má poskytnout dostatek informací pro případné změny harmonogramu, zdrojů nebo plánu."},"obecne":"Sylabus 5.3.2: Různé cílové skupiny potřebují v reportech různé informace. Report o postupu prací obsahuje postup vůči plánu, překážky, metriky, nová a změněná rizika a plánované testování; podrobný technický popis přístupu k testování do něj pro vyššího manažera nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UP-3-31","n":null,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o testwaru (např. testovacích případech a sadách testovacích dat) je pravdivé?<\/p>","m":["Testware není nutné dokumentovat, protože není součástí vydaného produktu.","Testware by měl být pro každou novou verzi softwaru vytvořen znovu.","Testware je potřeba jen do doby, než je software nasazen do produkce.","Testware potřebuje konfigurační management stejně jako požadavky, návrh a kód."],"ok":[3],"vys":{"a":"Není správně. Testware musí být dokumentován a řízen, aby ho šlo udržovat a znovu použít.","b":"Není správně. Testware lze znovu použít a udržovat; vytvářet ho stále znovu je neefektivní.","c":"Není správně. Testware je potřeba i po nasazení, např. pro regresní testování a testování údržby.","d":"Je správně. Plány testování, testovací případy, skripty, výsledky a reporty jsou konfiguračními položkami."},"obecne":"Sylabus 5.4: Konfiguračními položkami mohou být plány a strategie testování, testovací podmínky, testovací případy, skripty, výsledky testů, protokoly testů a reporty z testování. Testware se proto řídí konfiguračním managementem stejně jako ostatní pracovní produkty.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"UP-3-33","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Typický nástroj pro provádění testů by měl umět všechny následující činnosti KROMĚ:<\/p>","m":["<p>generování očekávaných výsledků<\/p>","<p>opakovaného přehrávání vstupů podle naprogramovaného skriptu<\/p>","<p>nahrávání testovacích vstupů<\/p>","<p>porovnání očekávaných výsledků se skutečnými výsledky<\/p>"],"ok":[0],"vys":{"a":"Je správně. Očekávané výsledky se určují při návrhu testů (z testovací báze nebo testovacího orákula), nástroj pro provádění testů je negeneruje.","b":"Není správně. Přehrávání vstupů podle skriptu je typickou funkcí nástroje pro provádění testů.","c":"Není správně. Nahrávání testovacích vstupů je typickou funkcí nástroje pro provádění testů.","d":"Není správně. Porovnání očekávaných a skutečných výsledků je typickou funkcí nástroje pro provádění testů."},"obecne":"Sylabus 6.1: nástroje pro provádění testů a měření pokrytí usnadňují automatizované provádění testů – přehrávají vstupy, porovnávají očekávané výsledky se skutečnými a zaznamenávají výsledky. Očekávané výsledky však musí být určeny při návrhu testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-3-35","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících NENÍ opatřením řízení testování, ke kterému může dojít během testování?<\/p>","m":["Přehodnocení priorit testů, když vývoj dodá software pozdě","Příprava testovacího prostředí","Stanovení vstupního kritéria, že vývojáři musí opravy znovu otestovat před přijetím do buildu","Změna harmonogramu testování kvůli dostupnosti testovacího prostředí"],"ok":[1],"vys":{"a":"Není správně. Přehodnocení priorit testů je příkladem opatření řízení testování ze sylabu.","b":"Je správně. Příprava testovacího prostředí je úkolem implementace testování, nikoli opatřením řízení.","c":"Není správně. Úprava vstupních kritérií v reakci na průběh testování je opatřením řízení testování.","d":"Není správně. Úprava harmonogramu kvůli dostupnosti prostředí je příkladem opatření řízení testování ze sylabu."},"obecne":"Sylabus 5.3: Řízení testování využívá informace z monitoringu k nápravným opatřením, např. přehodnocení priorit testů, přehodnocení splnění vstupních či výstupních kritérií nebo úpravě harmonogramu kvůli zpoždění testovacího prostředí. Příprava testovacího prostředí patří do implementace testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"UP-3-36","n":null,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího je součástí souhrnného reportu z testování?<\/p>","m":["Podrobný popis kroků všech provedených testovacích procedur","Stav připravenosti testovacího prostředí","Vyhodnocení kvality testovaného objektu","Definování kritérií úspěchu/neúspěchu a cílů testování"],"ok":[2],"vys":{"a":"Není správně. Podrobné kroky procedur jsou testwarem, souhrnný report uvádí jen shrnutí testů.","b":"Není správně. Připravenost testovacího prostředí je typickým vstupním kritériem, ne obsahem souhrnného reportu.","c":"Je správně. Souhrnný report obsahuje vyhodnocení testování a kvality produktu na základě plánu testování.","d":"Není správně. Cíle testování a kritéria se definují v plánu testování; souhrnný report je jen vyhodnocuje."},"obecne":"Sylabus 5.3.2: Souhrnný report z testování obsahuje shrnutí testů, vyhodnocení testování a kvality produktu vůči plánu testování, odchylky od plánu, překážky, metriky, neošetřená rizika, nevyřešené defekty a ponaučení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UP-3-37","n":null,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Pokud vývojáři předávají k testování kód, který není pod správou verzí, jaký proces chybí?<\/p>","m":["<p>Analýza rizik<\/p>","<p>Management defektů<\/p>","<p>Ladění<\/p>","<p>Konfigurační management<\/p>"],"ok":[3],"vys":{"a":"Není správně. Analýza rizik zahrnuje identifikaci a ohodnocení rizik, nikoli správu verzí.","b":"Není správně. Management defektů řeší zpracování anomálií a defektů od nahlášení po uzavření.","c":"Není správně. Ladění je hledání a oprava příčin selhání v kódu, se správou verzí nesouvisí.","d":"Je správně. Konfigurační management zajišťuje jednoznačnou identifikaci a řízení verzí všech konfiguračních položek včetně testovaného objektu."},"obecne":"Sylabus 5.4: Konfigurační management zajišťuje, že všechny konfigurační položky včetně testovaného objektu jsou jednoznačně identifikovány, jejich verze řízeny a změny evidovány. Pokud kód předávaný k testování není pod správou verzí, chybí právě tento proces.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"UP-3-38","n":null,"lo":"FL-5.5.1","k":"K3","k3":false,"vyber":1,"q":"<p>Co z následujícího bude NEJMÉNĚ pravděpodobně součástí reportu o defektu?<\/p>","m":["Návrhy na odstranění problému","Míra dopadu na zájmy zainteresovaných stran","Fáze SDLC, ve které byla anomálie zjištěna","Datum zjištění anomálie"],"ok":[0],"vys":{"a":"Je správně. Návrh opravy není typickou součástí reportu o defektu; oprava je úkolem vývojáře.","b":"Není správně. Závažnost (míra dopadu na zájmy zainteresovaných stran) je typickou součástí reportu.","c":"Není správně. Fáze SDLC patří ke kontextu defektu, který report obvykle obsahuje.","d":"Není správně. Datum zjištění anomálie je typickou součástí reportu."},"obecne":"Sylabus 5.5: Report o defektu obvykle obsahuje mj. datum zjištění anomálie, kontext defektu (včetně fáze SDLC), závažnost (míru dopadu na zájmy zainteresovaných stran) a prioritu. Návrhy na odstranění problému mezi typický obsah nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UP-3-39","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jsou dány následující testovací činnosti a kategorie testovacích nástrojů:<\/p><p>1. Měření výkonnosti.<\/p><p>2. Provádění testů a protokolování.<\/p><p>3. Správa testování a testwaru.<\/p><p>4. Sledování pracovních toků.<\/p><p>A. Nástroje pro provádění testů a měření pokrytí.<\/p><p>B. Nástroje pro nefunkcionální testování.<\/p><p>C. Nástroje DevOps.<\/p><p>D. Nástroje pro management testování.<\/p><p>Která z následujících možností NEJLÉPE přiřazuje činnosti k nástrojům?<\/p>","m":["<p>1B-2D-3A-4C<\/p>","<p>1B-2A-3D-4C<\/p>","<p>1C-2A-3B-4D<\/p>","<p>1A-2C-3D-4B<\/p>"],"ok":[1],"vys":{"a":"Není správně. Provádění testů nepodporují nástroje pro management testování a správu testwaru nepodporují nástroje pro provádění testů.","b":"Je správně. 1B, 2A, 3D a 4C odpovídá kategoriím nástrojů v sylabu 6.1.","c":"Není správně. Měření výkonnosti nepatří k nástrojům DevOps a sledování pracovních toků nepatří k nástrojům pro management testování.","d":"Není správně. Měření výkonnosti patří k nástrojům pro nefunkcionální testování a sledování pracovních toků k nástrojům DevOps."},"obecne":"Sylabus 6.1: nástroje pro nefunkcionální testování umožňují např. měření výkonnosti, nástroje pro provádění testů a měření pokrytí usnadňují automatizované provádění testů, nástroje pro management testování usnadňují správu testů, defektů a konfigurací a nástroje DevOps podporují pipeline a sledování pracovních toků.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-3-40","n":null,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího je NEJPRAVDĚPODOBNĚJI rizikem automatizace testů?<\/p>","m":["<p>Častější odhalování defektů s vysokou závažností<\/p>","<p>Podstatně kratší doba provádění testů<\/p>","<p>Použití nástroje tam, kde je vhodnější manuální testování<\/p>","<p>Vyšší konzistence a opakovatelnost provádění testů<\/p>"],"ok":[2],"vys":{"a":"Není správně. Odhalení dalších závažných defektů je přínosem, nikoli rizikem.","b":"Není správně. Kratší doba provádění testů je přínosem automatizace.","c":"Je správně. Použití nástroje tam, kde je vhodnější manuální testování, je rizikem automatizace.","d":"Není správně. Vyšší konzistence a opakovatelnost je přínosem automatizace (předchází lidským chybám)."},"obecne":"Sylabus 6.2 uvádí mezi riziky automatizace testů použití testovacího nástroje tam, kde je vhodnější manuální testování, a přílišné spoléhání na nástroj.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}},{"id":"UP-4-01","n":null,"lo":"FL-1.1.2","k":"K2","k3":true,"vyber":1,"q":"Které tvrzení správně popisuje typické rozdělení odpovědností mezi testováním a laděním?","m":["<p>Vývojáři identifikují, lokalizují a opravují defekty, testeři potvrdí, že oprava odstranila původní defekt<\/p>","<p>Testeři identifikují a lokalizují defekty, vývojáři defekty opraví a potvrdí, že oprava odstranila původní defekt<\/p>","<p>Vývojáři identifikují defekty, testeři defekty lokalizují, vývojáři je opraví a potvrdí, že oprava odstranila původní defekt<\/p>","<p>Testeři identifikují defekty, vývojáři defekty lokalizují a opravují. Testeři potvrdí, že oprava odstranila původní defekt<\/p>"],"ok":[3],"vys":{"a":"Není správně. Testování a ladění jsou samostatné činnosti; identifikace defektů testováním je typicky úkolem testerů.","b":"Není správně. Lokalizace defektu je součástí ladění, nikoli testování, a potvrzení opravy je úkolem testera.","c":"Není správně. Lokalizace defektu (diagnostika) je součástí ladění, které provádějí vývojáři, a konfirmační testování ideálně provádí ten, kdo provedl prvotní test.","d":"Je správně. Testeři testováním odhalí defekty (selhání), vývojáři při ladění defekty lokalizují a opraví a testeři konfirmačním testováním potvrdí, že oprava zabrala."},"obecne":"Sylabus 1.1.2: Testování vyvolá selhání nebo přímo najde defekty. Ladění zahrnuje reprodukování selhání, diagnostiku (nalezení defektu) a opravu. Následné konfirmační testování ověří, že oprava problém vyřešila, a provádí jej ideálně stejná osoba, která provedla prvotní test.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.1.2","nazev":"Testování a ladění","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-dva-testovani-a-ladeni"}},{"id":"UP-4-02","n":null,"lo":"FL-1.1.1","k":"K1","k3":true,"vyber":1,"q":"Která z následujících možností NEJLÉPE popisuje, jak testování přispívá k dosažení kvality?","m":["Snižuje úroveň rizika plynoucího z nedostatečné kvality systému.","Zajišťuje, že všechny požadavky jsou dostatečně podrobné.","Zajišťuje dodržování procesních standardů v celé organizaci.","Měří kvalitu softwaru počtem provedených testovacích případů."],"ok":[0],"vys":{"a":"Je správně. Snížení úrovně rizika plynoucího z nedostatečné kvality softwaru je typickým cílem testování.","b":"Není správně. Testování (revize) může nedostatky v požadavcích odhalit, ale jejich dostatečnou podrobnost nezajišťuje.","c":"Není správně. Zavádění a dodržování procesů je doménou zajištění kvality (QA), které je preventivní a zaměřené na procesy.","d":"Není správně. Samotný počet provedených testů bez znalosti jejich výsledků o kvalitě nic neříká."},"obecne":"Sylabus 1.1.1 a 1.2.2: Snížení úrovně rizika plynoucího z nedostatečné kvality softwaru je typickým cílem testování. Testování je nápravný přístup zaměřený na produkt a hlavní formou řízení kvality (QC), zatímco zajištění kvality (QA) se zaměřuje na zavádění a zlepšování procesů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"}},{"id":"UP-4-03","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Jako manažer testování shromažďujete měření týkající se defektů. Zjistíte, že po prvním testovacím cyklu, který pokryl všechny požadavky, má subsystém C hustotu defektů o 150 % vyšší, než je průměr. Subsystém A má naopak hustotu defektů o 60 % nižší, než je průměr. Jaký závěr pro další testovací cyklus můžete z této skutečnosti NEJLÉPE vyvodit?","m":["<p>Zjištěná hustota defektů neumožňuje vyvodit žádné závěry o rozsahu dalšího testování.<\/p>","<p>Je pravděpodobné, že subsystém C obsahuje ještě další skryté defekty. Proto musíme subsystém C testovat podrobněji.<\/p>","<p>Protože jsme v subsystému C již našli mnoho defektů, měli bychom testovací zdroje soustředit na subsystém A.<\/p>","<p>Měli bychom se snažit vyrovnat rozsah testování napříč všemi moduly, abychom všechny subsystémy testovali rovnoměrně.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Pozorované shluky defektů jsou významným vstupem pro testování založené na rizicích.","b":"Je správně. Podle principu shlukování defektů lze v subsystému C s vysokou hustotou defektů očekávat další skryté defekty, proto je vhodné jej testovat podrobněji.","c":"Není správně. Vysoký počet nalezených defektů v C nesvědčí o tom, že je již vyčištěný; spíše naopak.","d":"Není správně. Rovnoměrné rozložení úsilí ignoruje zjištěné shluky defektů a riziko."},"obecne":"Sylabus 1.3, princip 4 (Shlukování defektů): Většinu defektů obvykle obsahuje malé množství komponent. Předpokládané a skutečně pozorované shluky defektů jsou významným vstupem pro testování založené na rizicích, proto se další testování soustředí na subsystém C.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-4-04","n":null,"lo":"FL-1.4.2","k":"K2","k3":true,"vyber":2,"q":"Které DVĚ z následujících možností NEJSOU faktory, které mohou významně ovlivnit proces testování?","m":["<p>Uspořádání kanceláře<\/p>","<p>Dostupnost nástrojů pro automatizované testování<\/p>","<p>Politické události<\/p>","<p>Míra zapojení zainteresovaných stran do testovacích činností<\/p>","<p>Volba životního cyklu vývoje softwaru (SDLC)<\/p>"],"ok":[0,2],"vys":{"a":"Uspořádání kanceláře může ovlivnit pracovní prostředí a spolupráci v týmu, ale samotný proces testování významně neovlivňuje. Souvisí spíše s pohodlím a produktivitou členů týmu než s testovacími činnostmi.","b":"Dostupnost nástrojů pro automatizované testování může proces testování výrazně ovlivnit, protože zvyšuje efektivitu, přesnost a pokrytí testovacích činností. Nedostupnost automatizačních nástrojů může účinnost procesu testování snížit.","c":"Politické události mohou tým rozptylovat nebo ovlivnit jeho morálku, ale proces testování přímo neovlivňují. Pracovní prostředí mohou ovlivnit nepřímo, nepatří však mezi klíčové faktory, které testovací činnosti významně ovlivňují.","d":"Míra zapojení zainteresovaných stran do testovacích činností může mít na proces testování významný dopad. Zainteresované strany hrají zásadní roli při definování požadavků, poskytování zpětné vazby a přijímání rozhodnutí, která ovlivňují výsledky testování. Jejich nedostatečné zapojení může vést k nedorozuměním, zpožděním a nedostatečnému testování.","e":"Volba životního cyklu vývoje softwaru (SDLC) může proces testování výrazně ovlivnit. Různé modely SDLC (např. agilní, vodopád, DevOps) přistupují rozdílně k testování, managementu požadavků i spolupráci, což ovlivňuje, jak jsou testovací činnosti plánovány, prováděny a monitorovány."},"obecne":"Sylabus 1.4.2: Proces testování ovlivňují mimo jiné zainteresované strany (jejich potřeby a ochota spolupracovat), nástroje (dostupnost, použitelnost) a zvolený životní cyklus vývoje softwaru. Uspořádání kanceláře ani politické události mezi tyto faktory nepatří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.2","nazev":"Proces testování v souvislostech","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-dva-proces-testovani-v-souvislostech"}},{"id":"UP-4-05","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"Co je testovací báze?","m":["Okamžik během vývoje softwaru, kdy by mělo začít testování","Metoda používaná k systematickému odvozování testovacích podmínek","Zdroj pro určení skutečných výsledků sady testů","Soubor znalostí používaný jako základ pro testovací analýzu a návrh testů"],"ok":[3],"vys":{"a":"Není správně. Okamžik zahájení testování není testovací báze.","b":"Není správně. Metodou pro odvozování testovacích podmínek je technika testování, ne testovací báze.","c":"Není správně. Skutečné výsledky vznikají provedením testů, nelze je určit z testovací báze.","d":"Je správně. Slovník ISTQB definuje testovací bázi jako soubor znalostí použitý jako základ pro testovací analýzu a návrh testů."},"obecne":"Testovací báze (např. požadavky, uživatelské scénáře, návrh, kód) je soubor znalostí, který se podle sylabu 1.4.1 analyzuje při testovací analýze s cílem identifikovat testovací podmínky a slouží jako základ pro návrh testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"UP-4-06","n":null,"lo":"FL-1.4.4","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností NEJLÉPE popisuje, jakou přidanou hodnotu přináší udržování trasovatelnosti mezi testovací bází a testwarem?","m":["Lze určit, zda nový testovací případ zvýšil pokrytí požadavků.","Na oblasti, které mohou být zasaženy vedlejšími účinky změny, lze zacílit konfirmační testování.","Testování údržby lze plně automatizovat na základě změn původních požadavků.","Manažeři testování mohou zjistit, kteří testeři našli defekty s nejvyšší závažností."],"ok":[0],"vys":{"a":"Je správně. Pokud jsou testovací případy propojeny s požadavky, lze u nového testovacího případu zjistit, zda pokrývá dosud nepokryté požadavky.","b":"Není správně. Trasovatelnost pomáhá určit dopad změn, ale oblasti zasažené vedlejšími účinky změny jsou předmětem regresního, nikoli konfirmačního testování.","c":"Není správně. Trasovatelnost pomůže najít testovací případy dotčené změnou požadavků, ale testování údržby plně neautomatizuje.","d":"Není správně. Trasovatelnost mezi testovací bází a testwarem neposkytuje informace o výkonu jednotlivých testerů."},"obecne":"Sylabus 1.4.4: Přesná trasovatelnost umožňuje vyhodnocovat pokrytí; trasovatelnost mezi testovacími případy a požadavky pomůže ověřit, že požadavky jsou pokryty testovacími případy. Dále umožňuje určit dopad změn a usnadňuje audit.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.4.4","nazev":"Trasovatelnost mezi testovací bází a pracovními produkty z testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-ctyri-trasovatelnost-mezi-testovaci-bazi-a-pracovnimi-produkty-z-testovani"}},{"id":"UP-4-07","n":null,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":1,"q":"Ve které z následujících situací NEMUSÍ být týmový přístup vhodný?","m":["<p>Projekty mobilních aplikací<\/p>","<p>Bezpečnostně kritické projekty<\/p>","<p>Projekty vývoje webu<\/p>","<p>Agilní projekty<\/p>"],"ok":[1],"vys":{"a":"Není správně. U projektů mobilních aplikací nic nebrání využití týmového přístupu.","b":"Je správně. U bezpečnostně kritických systémů je obvykle nutné zachovat vysokou úroveň nezávislosti testování, proto týmový přístup nemusí být vhodný.","c":"Není správně. U projektů vývoje webu nic nebrání využití týmového přístupu.","d":"Není správně. Týmový přístup vychází z extrémního programování a v agilních projektech se běžně uplatňuje."},"obecne":"Sylabus 1.5.2: Týmový přístup nemusí být v kontextu projektu vždy vhodnou metodikou. Typickým příkladem je testování bezpečnostně kritických systémů, kdy je nutné zachovat vysokou úroveň nezávislosti testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"UP-4-09","n":null,"lo":"FL-2.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>V jakém okamžiku vývoje softwaru mohou testovací činnosti NEJDŘÍVE začít?<\/p>","m":["<p>Když je dokončen návrh<\/p>","<p>Když je první modul připraven k testování komponent<\/p>","<p>Když je k dispozici pracovní verze požadavků<\/p>","<p>Když je dokončen kód<\/p>"],"ok":[2],"vys":{"a":"Není správně. Testeři mohou revidovat již požadavky, tedy dříve než je dokončen návrh.","b":"Není správně. Statické testování (revize) může začít dávno před dokončením prvního modulu kódu.","c":"Je správně. Testeři se zapojují do revize pracovních produktů, jakmile jsou k dispozici jejich pracovní verze.","d":"Není správně. Čekat na dokončení kódu je v rozporu s principem včasného testování."},"obecne":"Sylabus 2.1.2: v okamžiku, kdy je k dispozici pracovní verze (draft) libovolného pracovního produktu, jsou do jeho revize zapojeni testeři. To jako forma včasného testování a včasné detekce defektů podporuje princip shift left.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"}},{"id":"UP-4-10","n":null,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Který z následujících přístupů řídí proces kódování prostřednictvím vytváření testovacích případů ještě před napsáním vlastního kódu?<\/p>","m":["<p>Vývoj řízený pokrytím (CDD)<\/p>","<p>Vývoj řízený výkonností (PDD)<\/p>","<p>Vývoj řízený kvalitou (QDD)<\/p>","<p>Vývoj řízený testy (TDD)<\/p>"],"ok":[3],"vys":{"a":"Není správně. Vývoj řízený pokrytím (CDD) není přístup typu test-first uvedený v sylabu.","b":"Není správně. Vývoj řízený výkonností (PDD) není přístup typu test-first uvedený v sylabu.","c":"Není správně. Vývoj řízený kvalitou (QDD) není přístup typu test-first uvedený v sylabu.","d":"Je správně. V TDD se nejprve píší testovací případy a teprve potom kód, který jim vyhovuje."},"obecne":"Sylabus 2.1.3: ve vývoji řízeném testy (TDD) je psaní kódu řízeno testovacími případy; nejprve se napíší testy a poté kód tak, aby jim vyhovoval.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UP-4-11","n":null,"lo":"FL-2.1.5","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NENÍ příkladem uplatnění přístupu shift left?<\/p>","m":["<p>Provádění testování výkonnosti až během systémového integračního testování<\/p>","<p>Revize návrhových dokumentů z hlediska testovatelnosti před zahájením kódování<\/p>","<p>Spouštění statické analýzy kódu ještě před dynamickým testováním<\/p>","<p>Psaní automatizovaných akceptačních testů ještě před zahájením vývoje<\/p>"],"ok":[0],"vys":{"a":"Je správně. Testování výkonnosti v pozdní úrovni systémové integrace testování dříve neposouvá; shift left by znamenal např. nefunkcionální testy už při testování komponent.","b":"Není správně. Revize dokumentů před kódováním je příkladem včasného testování, tedy shift left.","c":"Není správně. Spouštění statické analýzy před dynamickým testováním sylabus výslovně uvádí jako příklad shift left.","d":"Není správně. Psaní testů před kódem je typickým příkladem shift left."},"obecne":"Sylabus 2.1.5: příklady shift left jsou revize specifikací z pohledu testerů, psaní testovacích případů před kódem, používání CI/CD, spouštění statické analýzy před dynamickým testováním a provádění nefunkcionálních testů už v úrovni testování komponent.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"}},{"id":"UP-4-12","n":null,"lo":"FL-2.1.6","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících záležitostí by NEMĚLA být vznesena na retrospektivě?<\/p>","m":["<p>Proces sestavení (build) je manuální a trvá příliš dlouho. Mělo by se prozkoumat a zavést automatizované sestavení.<\/p>","<p>Tester XYZ má potíže s nalézáním defektů. Potřebuje školení v návrhu testů.<\/p>","<p>V budoucnu by měl být kladen větší důraz na testování komponent, aby se zlepšila celková kvalita.<\/p>","<p>Běh automatizovaných regresních sad trvá příliš dlouho. Je nutná revize testů a odstranění nadbytečných testů.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Automatizace sestavení je zlepšení procesu, které je vhodné na retrospektivě vznést.","b":"Je správně. Retrospektiva nemá vyčleňovat ani hodnotit jednotlivce; zaměřuje se na proces a tým jako celek.","c":"Není správně. Jde o návrh na zlepšení procesu, který na retrospektivu patří.","d":"Není správně. Zefektivnění regresních sad je typické zlepšení procesu vhodné pro retrospektivu."},"obecne":"Sylabus 2.1.6: na retrospektivě se probírá, co bylo úspěšné, co se nepovedlo a jak zlepšení zavést. Cílem je zlepšení procesu a spolupráce, nikoli hodnocení jednotlivých členů týmu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"}},{"id":"UP-4-13","n":null,"lo":"FL-2.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje nefunkcionální testování?<\/p>","m":["<p>Testování integrovaného systému s cílem ověřit, že splňuje specifikované požadavky<\/p>","<p>Testování s cílem určit, zda zdrojový kód dodržuje standardy kódování<\/p>","<p>Testování charakteristik systému, jako je použitelnost, spolehlivost nebo udržovatelnost<\/p>","<p>Testování bez ohledu na vnitřní strukturu testovaného systému<\/p>"],"ok":[2],"vys":{"a":"Není správně. Jde o obecný popis systémového testování, nikoli nefunkcionálního testování.","b":"Není správně. Kontrola dodržování standardů kódování je typická pro statickou analýzu.","c":"Je správně. Nefunkcionální testování vyhodnocuje charakteristiky kvality jiné než funkcionalitu, tj. jak dobře se systém chová.","d":"Není správně. Jde o popis testování černé skříňky, které může být funkcionální i nefunkcionální."},"obecne":"Sylabus 2.2.2: nefunkcionální testování vyhodnocuje jiné charakteristiky komponenty nebo systému než funkcionalitu („jak dobře se systém chová“). Podle ISO/IEC 25010 jde např. o výkonnostní efektivitu, kompatibilitu, použitelnost (schopnost interakce), spolehlivost, bezpečnost, udržovatelnost a přenositelnost.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.2.2","nazev":"Typy testů","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-dva-typy-testu"}},{"id":"UP-4-14","n":null,"lo":"FL-2.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>Vyřazení softwaru nebo systému z provozu by vyvolalo který typ testování?<\/p>","m":["<p>Testování udržovatelnosti<\/p>","<p>Testování obnovitelnosti<\/p>","<p>Testování přenositelnosti<\/p>","<p>Testování údržby<\/p>"],"ok":[3],"vys":{"a":"Není správně. Testování udržovatelnosti ověřuje, jak snadno lze systém upravovat; nejde o testování vyvolané vyřazením systému.","b":"Není správně. Testování obnovitelnosti je nefunkcionální testování (spolehlivost), nespouští ho vyřazení systému.","c":"Není správně. Testování přenositelnosti ověřuje přenos na jinou platformu, ne vyřazení z provozu.","d":"Je správně. Vyřazení systému z provozu je jedním ze spouštěčů testování údržby."},"obecne":"Sylabus 2.3: spouštěči testování údržby jsou úpravy (plánovaná vylepšení, opravné změny, hotfixy), aktualizace nebo migrace provozního prostředí (např. z jedné platformy na jinou) a vyřazení aplikace z provozu, kdy může být vhodné testovat archivaci dat a procesy jejich obnovení a načtení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"2.3","nazev":"Testování údržby","href":"kapitola-2/vyklad.html#cast-dva-tecka-tri-testovani-udrzby"}},{"id":"UP-4-15","n":null,"lo":"FL-3.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NESOUVISÍ se statickým testováním?<\/p>","m":["<p>Příprava testovacích dat<\/p>","<p>Včasné odhalení defektů<\/p>","<p>Role zapisovatele<\/p>","<p>Kontrola kódu kompilátorem<\/p>"],"ok":[0],"vys":{"a":"Je správně. Testovací data se připravují pro provádění testů, tedy pro dynamické testování.","b":"Není správně. Statické testování umožňuje odhalit defekty v nejranějších fázích SDLC.","c":"Není správně. Zapisovatel je role při revizích, které jsou statickým testováním.","d":"Není správně. Kompilátor kontroluje kód bez jeho spuštění, jde tedy o formu statické analýzy."},"obecne":"Sylabus 3.1: statické testování nevyžaduje spuštění softwaru ani tvorbu testovacích případů. Příprava testovacích dat slouží dynamickému testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"}},{"id":"UP-4-16","n":null,"lo":"FL-3.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností je přínosem časné a časté zpětné vazby od zainteresovaných stran?<\/p>","m":["<p>Zvyšuje složitost plánování a realizace projektu<\/p>","<p>Zajišťuje, že změny požadavků jsou pochopeny a implementovány dříve.<\/p>","<p>Minimalizuje potřebu zapojení zainteresovaných stran v průběhu projektu<\/p>","<p>Urychluje rozhodování tím, že snižuje počet zapojených zainteresovaných stran.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Cílem zpětné vazby je soulad s potřebami zainteresovaných stran, nikoli zvýšení složitosti.","b":"Je správně. Častá zpětná vazba zajišťuje, aby změny požadavků byly správně a včas pochopeny a implementovány.","c":"Není správně. Častá zpětná vazba naopak vyžaduje průběžné zapojení zainteresovaných stran.","d":"Není správně. Zpětná vazba počet zapojených zainteresovaných stran nesnižuje."},"obecne":"Sylabus 3.2.1: častá zpětná vazba od zainteresovaných stran během SDLC může zabránit nedorozuměním při definici požadavků a zajistit, aby změny požadavků byly správně a včas pochopeny a implementovány.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"3.2.1","nazev":"Výhody včasné a časté zpětné vazby od zainteresovaných stran","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-jedna-vyhody-vcasne-a-caste-zpetne-vazby-od-zainteresovanych-stran"}},{"id":"UP-4-17","n":null,"lo":"FL-3.2.3","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností SPRÁVNĚ přiřazuje role a odpovědnosti při formální revizi?<\/p>","m":["<p>Zapisovatel – opravuje defekty v revidovaném pracovním produktu<\/p>","<p>Moderátor – rozhoduje o zdrojích vyčleněných na revizi<\/p>","<p>Manažer – rozhoduje o tom, co se bude revidovat<\/p>","<p>Vedoucí revize – zajišťuje efektivní průběh revizních schůzek<\/p>"],"ok":[2],"vys":{"a":"Není správně. Revidovaný pracovní produkt opravuje autor.","b":"Není správně. O zdrojích pro revizi rozhoduje manažer.","c":"Je správně. Manažer rozhoduje o tom, co má být revidováno, a o zdrojích.","d":"Není správně. Efektivní průběh revizních schůzek zajišťuje moderátor."},"obecne":"Sylabus 3.2.3: manažer rozhoduje o tom, co má být revidováno a jaké zdroje budou využity; moderátor zajišťuje efektivní průběh revizních schůzek; autor opravuje pracovní produkt; zapisovatel zaznamenává informace z revize.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"}},{"id":"UP-4-18","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Který z níže uvedených typů revizí je NEJLEPŠÍ volbou, pokud musí revize probíhat podle formálního procesu založeného na pravidlech a kontrolních seznamech?<\/p>","m":["<p>Předvedení (walkthrough)<\/p>","<p>Neformální revize<\/p>","<p>Technická revize<\/p>","<p>Inspekce<\/p>"],"ok":[3],"vys":{"a":"Není správně. Předvedení vede autor a formální proces nevyžaduje.","b":"Není správně. Neformální revize se neřídí definovaným procesem.","c":"Není správně. Technická revize je zaměřena hlavně na dosažení shody v technickém problému; nejformálnější není.","d":"Je správně. Inspekce je nejformálnějším typem revize a řídí se kompletním obecným procesem."},"obecne":"Sylabus 3.2.4: inspekce jsou nejformálnějším typem revize a řídí se kompletním obecným procesem revize; shromažďují se při nich metriky.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UP-4-19","n":null,"lo":"FL-2.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Během testování byl nalezen defekt. Když se při příjmu dat ze serveru přerušilo síťové připojení, systém havaroval. Defekt byl opraven úpravou kódu, který během přenosu dat kontroloval dostupnost sítě.&nbsp;Stávající testovací případy pokrývaly 100 % všech příkazů příslušného&nbsp;modulu. Aby bylo možné opravu ověřit a zajistit rozsáhlejší pokrytí, byly navrženy nové testy a přidány do sady testů.<\/p><p>Které typy testování jsou výše zmíněny?<\/p><p>i. Funkcionální testování.<\/p><p>ii. Testování bílé skříňky.<\/p><p>iii. Konfirmační testování (přetestování).<\/p><p>iv. Testování výkonnosti.<\/p>","m":["<p>i, ii a iii<\/p>","<p>i, iii a iv<\/p>","<p>i a iii<\/p>","<p>i, ii a iv<\/p>"],"ok":[0],"vys":{"a":"Je správně. Zadání zmiňuje funkcionální testování, testování bílé skříňky i konfirmační testování.","b":"Není správně. Testování výkonnosti zmíněno není a chybí testování bílé skříňky.","c":"Není správně. Chybí testování bílé skříňky (pokrytí příkazů a nové testy pro rozsáhlejší pokrytí).","d":"Není správně. O testování výkonnosti se v zadání nemluví a chybí konfirmační testování."},"obecne":"<p>Sylabus 2.2.2 a 2.2.3: Nalezení havárie systému při testování jeho chování odpovídá funkcionálnímu testování (i). Měření a zvyšování pokrytí příkazů je testování bílé skříňky (ii). Ověření opravy defektu je konfirmační testování (iii). O testování výkonnosti (iv) se zadání nezmiňuje.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.2.2","nazev":"Typy testů","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-dva-typy-testu"}},{"id":"UP-4-20","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Spínač se vypne, jakmile teplota klesne pod 18 °C, a znovu se zapne, když je teplota vyšší než 21 °C. Teplota se měří v celých stupních. Které hodnoty patří do STEJNÉ třídy ekvivalence?<\/p>","m":["<p>14, 15, 19<\/p>","<p>22, 23, 24<\/p>","<p>12, 16, 22<\/p>","<p>24, 27, 17<\/p>"],"ok":[1],"vys":{"a":"Není správně. 14 a 15 patří do třídy pod 18 °C, 19 do třídy 18–21 °C.","b":"Je správně. Všechny tři hodnoty patří do třídy nad 21 °C.","c":"Není správně. 12 a 16 patří do třídy pod 18 °C, 22 do třídy nad 21 °C.","d":"Není správně. 24 a 27 patří do třídy nad 21 °C, 17 do třídy pod 18 °C."},"obecne":"<p>Sylabus 4.2.1: Třídy ekvivalence jsou pod 18 °C, 18–21 °C a nad 21 °C. Hodnoty 22, 23 a 24 patří všechny do třetí třídy.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UP-4-24","n":null,"lo":"FL-4.3.1","k":"K2","k3":true,"vyber":1,"q":"<p>U daného kódu jsme dosáhli 100% pokrytí příkazů. Čím si můžeme být jisti?<\/p>","m":["<p>Že jsme otestovali veškeré možné chování kódu.<\/p>","<p>Že naše testy dosáhly také 100% pokrytí větví.<\/p>","<p>Že naše testy provedly všechny spustitelné příkazy v kódu.<\/p>","<p>Že v kódu nejsou žádná rozhodnutí.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Provedení všech příkazů nezaručuje otestování všech cest, kombinací vstupů ani dat (např. dělení nulou).","b":"Není správně. 100% pokrytí příkazů nezaručuje 100% pokrytí větví; platí jen opačná implikace.","c":"Je správně. 100% pokrytí příkazů znamená, že každý spustitelný příkaz byl alespoň jednou proveden.","d":"Není správně. Kód může obsahovat rozhodnutí, jejichž některé větve nebyly provedeny."},"obecne":"<p>Sylabus 4.3.1: Při 100% pokrytí příkazů je zajištěno, že všechny spustitelné příkazy v kódu byly otestovány alespoň jednou. Nezaručuje to však odhalení všech defektů ani otestování veškeré rozhodovací logiky.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"}},{"id":"UP-4-25","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které tvrzení o vztahu mezi pokrytím příkazů a pokrytím větví je PRAVDIVÉ?<\/p>","m":["<p>Pokrytí větví nemůže nikdy dosáhnout 100 %.<\/p>","<p>50% pokrytí větví zaručuje také 50% pokrytí příkazů.<\/p>","<p>100% pokrytí příkazů zaručuje také 100% pokrytí větví.<\/p>","<p>100% pokrytí větví zaručuje také 100% pokrytí příkazů.<\/p>"],"ok":[3],"vys":{"a":"Není správně. 100% pokrytí větví dosáhnout lze.","b":"Není správně. Mezi částečným pokrytím větví a pokrytím příkazů žádný takový pevný vztah neexistuje.","c":"Není správně. 100% pokrytí příkazů nezaručuje provedení všech větví (např. chybějící větve ELSE).","d":"Je správně. Každá sada testů, která dosáhne 100% pokrytí větví, dosáhne i 100% pokrytí příkazů."},"obecne":"<p>Sylabus 4.3.2: Pokrytí větví automaticky zaručuje pokrytí příkazů – jakákoli sada testů, která dosáhne 100% pokrytí větví, dosáhne také 100% pokrytí příkazů (ale ne naopak).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UP-4-26","n":null,"lo":"FL-4.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Co z následujícího by bylo NEJLEPŠÍM základem pro útok na vady?<\/p>","m":["<p>Zkušenosti, údaje o defektech a selháních a znalosti o selhávání softwaru<\/p>","<p>Testovací případy odvozené doménovými experty z byznys procesů<\/p>","<p>Očekávané výsledky získané porovnáním se stávajícím systémem<\/p>","<p>Analýza rizik provedená na začátku projektu<\/p>"],"ok":[0],"vys":{"a":"Je správně. Seznam možných chyb, defektů a selhání pro útok na vady se sestavuje ze zkušeností, údajů o defektech a selháních a z obecných znalostí o selhávání softwaru.","b":"Není správně. Testy odvozené z byznys procesů vycházejí ze specifikovaného chování (černá skříňka).","c":"Není správně. Porovnání se stávajícím systémem je zdroj očekávaných výsledků (testovací orákulum), ne seznam selhání.","d":"Není správně. Analýza rizik slouží k zaměření a prioritizaci testování, ne k sestavení seznamu možných selhání."},"obecne":"<p>Sylabus 4.4.1: Útok na vady je příkladem implementace odhadování chyb. Testeři vytvoří nebo získají seznam možných chyb, defektů a selhání a navrhnou testy, které je odhalí. Seznamy lze sestavit na základě zkušeností, údajů o defektech a selháních nebo obecných znalostí o tom, proč software selhává.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"}},{"id":"UP-4-28","n":null,"lo":"FL-4.5.2","k":"K2","k3":true,"vyber":1,"q":"<p>Uvažujte následující akceptační kritérium uživatelského scénáře:<\/p><p><em>Given uživatel dokončil registraci, When klikne na odkaz „Zapomenuté heslo“, Then systém mu odešle e-mail pro obnovení hesla.<\/em><\/p><p>V jakém formátu je toto akceptační kritérium zapsáno?<\/p>","m":["<p>Orientovaném na proces<\/p>","<p>Orientovaném na scénáře<\/p>","<p>Orientovaném na produkt<\/p>","<p>Orientovaném na pravidla<\/p>"],"ok":[1],"vys":{"a":"Není správně. Formát „orientovaný na proces“ sylabus neuvádí.","b":"Je správně. Formát Given/When/Then (výchozí stav – akce – očekávaný výsledek) je typickým formátem orientovaným na scénáře, používaným v BDD.","c":"Není správně. Formát „orientovaný na produkt“ sylabus neuvádí.","d":"Není správně. Kritéria orientovaná na pravidla mají podobu např. verifikačního seznamu s odrážkami nebo tabulky mapování vstupů a výstupů."},"obecne":"<p>Sylabus 4.5.2: Dva nejběžnější formáty akceptačních kritérií jsou orientovaný na scénáře (např. formát Given/When/Then používaný v BDD) a orientovaný na pravidla (např. verifikační seznam s odrážkami nebo tabulka mapování vstupů a výstupů).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"}},{"id":"UP-4-30","n":null,"lo":"FL-5.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících seznamů obsahuje pouze typická výstupní kritéria testování?<\/p>","m":["Míry spolehlivosti, pokrytí testy, míra nezávislosti testera a úplnost produktu","Doba uvedení na trh, zbývající defekty, kvalifikace testera, dostupnost testovatelných případů užití, pokrytí testy a náklady na testování","Míry spolehlivosti, pokrytí testy, náklady na testování, harmonogram, stav oprav defektů a zbývající rizika","Míry spolehlivosti, pokrytí testy, náklady na testování, dostupnost testovacího prostředí, doba uvedení na trh a úplnost produktu"],"ok":[2],"vys":{"a":"Není správně. Míra nezávislosti testera není výstupním kritériem.","b":"Není správně. Kvalifikace testera a dostupnost testovatelných případů užití jsou vstupní kritéria.","c":"Je správně. Všechny uvedené položky (včetně vyčerpání času či rozpočtu) lze použít jako výstupní kritéria.","d":"Není správně. Dostupnost testovacího prostředí je vstupní kritérium."},"obecne":"Sylabus 5.1.3: Typická výstupní kritéria jsou míry důkladnosti (pokrytí, počet nevyřešených defektů, hustota defektů) a binární kritéria; za platná výstupní kritéria lze považovat i vyčerpání času nebo rozpočtu. Dostupnost zdrojů a testwaru jsou naopak vstupní kritéria.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"}},{"id":"UP-4-31","n":null,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"<p>Je dán následující uživatelský scénář: <\/p><p><em>Jako prezident chci, aby žádná data, která nahraji, nemohl zobrazit žádný jiný uživatel systému<\/em><\/p><p>Během prvního sezení plánovacího pokeru byly na základě rizika, pracnosti, složitosti a odpovídajícího rozsahu testování přiděleny tyto body (story points):<\/p><ul><li><p>Zákazníci: 5<\/p><\/li><li><p>Vývojáři: 5<\/p><\/li><li><p>Testeři: 20<\/p><\/li><\/ul><p>Jaký je nejlepší výsledek tohoto plánovacího sezení?<\/p>","m":["<p>Protože se odhady velikosti od zákazníků a vývojářů shodují, může si být tým jistý, že je tento odhad dobrý, a měl by přejít k dalšímu uživatelskému scénáři.<\/p>","<p>Sezení plánovacího pokeru by měla pokračovat, dokud se odhadované body (story points) zákazníků, vývojářů a testerů přesně neshodují.<\/p>","<p>Protože systém nakonec vlastní zákazník, měly by být v případě neshody za správné považovány odhady zákazníků.<\/p>","<p>Tým by měl vést diskusi, aby pochopil, proč testeři považovali tento uživatelský scénář za výrazně pracnější. Po této diskusi by mělo proběhnout další kolo plánovacího pokeru.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Zákazníci a vývojáři mohli přehlédnout pracnost testování potřebnou k validaci scénáře; na odhadu se musí shodnout celý tým.","b":"Není správně. Odhady se nemusí přesně shodovat; tým může mít pravidlo, např. přijmout hodnotu s většinou hlasů.","c":"Není správně. Na odhadu se musí shodnout celý tým; zákazník sám nerozumí složitosti vývoje ani testování.","d":"Je správně. Při výrazně odlišných odhadech se o nich diskutuje a poté následuje další kolo odhadování, dokud není dosaženo shody."},"obecne":"Sylabus 5.1.4: Plánovací poker je variantou Wideband Delphi – pokud se odhady liší mimo dohodnuté hranice, experti o nich diskutují a poté každý samostatně odhaduje znovu, dokud není dosaženo shody. Velký rozdíl ukazuje, že testeři zřejmě vidí pracnost (např. testování zabezpečení), kterou ostatní přehlédli.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UP-4-32","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Před vytvořením faktury je nutný účet. Před založením účtu je nutný uživatel účtu (který účet založí). Software se dodává pouze s hlavním uživatelem, který může vytvářet jen jiné typy uživatelů. K otestování struktury softwaru na vysoké úrovni byly napsány tyto testovací případy:<\/p><p>TC1 – Vytvořit fakturu<br>TC2 – Upravit fakturu<br>TC3 – Zpracovat fakturu (odeslat zákazníkovi)<br>TC4 – Smazat fakturu<br>TC5 – Vytvořit účet<br>TC6 – Vytvořit uživatele účtu<br>TC7 – Upravit uživatele účtu<br>TC8 – Smazat uživatele účtu<br>TC9 – Upravit účet<br>TC10 – Smazat účet<\/p><p>Která z následujících testovacích procedur by umožnila provést všechny testy?<\/p>","m":["TC6, TC7, TC5, TC9, TC1, TC2, TC3, TC4, TC10, TC8","TC5, TC9, TC1, TC3, TC2, TC4, TC6, TC7, TC8, TC10","TC5, TC9, TC6, TC7, TC1, TC3, TC2, TC4, TC8, TC10","TC6, TC7, TC1, TC3, TC2, TC4, TC5, TC9, TC10, TC8"],"ok":[0],"vys":{"a":"Je správně. Uživatel účtu → účet → faktura (vytvořit, upravit, zpracovat, smazat) → smazání účtu → smazání uživatele; všechny závislosti jsou splněny.","b":"Není správně. Účet (TC5) se zakládá dříve, než existuje uživatel účtu (TC6).","c":"Není správně. Účet (TC5) se zakládá dříve, než existuje uživatel účtu (TC6).","d":"Není správně. Faktura (TC1) se vytváří dříve, než je založen účet (TC5)."},"obecne":"Sylabus 5.1.5: Při sestavování harmonogramu provádění je nutné respektovat logické závislosti mezi testovacími případy. Hlavní uživatel nejprve vytvoří uživatele účtu (TC6), ten založí účet (TC5), k němuž lze vytvořit fakturu (TC1); mazání probíhá v opačném pořadí (faktura, účet, uživatel). Jediné vyhovující pořadí je d.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UP-4-33","n":null,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"<p>Čím se v modelu testovacích kvadrantů vyznačuje kvadrant Q4?<\/p>","m":["<p>Obsahuje testy zaměřené na technologii, které podporují tým (např. testy komponent).<\/p>","<p>Obsahuje testy zaměřené na technologii, které kritizují produkt (např. testy výkonnosti).<\/p>","<p>Obsahuje převážně manuální testy prováděné koncovými uživateli (např. beta testy).<\/p>","<p>Obsahuje testy zaměřené na byznys, které kritizují produkt (např. testy použitelnosti).<\/p>"],"ok":[1],"vys":{"a":"Není správně. Testy zaměřené na technologii, které podporují tým (testy komponent a integrační testy komponent), patří do kvadrantu Q1.","b":"Je správně. Kvadrant Q4 obsahuje testy zaměřené na technologii, které kritizují produkt – smoke testy a nefunkcionální testy (kromě testů použitelnosti), např. testy výkonnosti.","c":"Není správně. Kvadrant Q4 není vymezen manuálním testováním; jeho testy jsou naopak často automatizované.","d":"Není správně. Testy zaměřené na byznys, které kritizují produkt (průzkumné testování, testování použitelnosti, uživatelské akceptační testování), patří do kvadrantu Q3."},"obecne":"Sylabus 5.1.7: Kvadranty vznikají kombinací dvou hledisek – zaměření na byznys / na technologii a podpora týmu / kritika produktu. Kvadrant Q4 (zaměřený na technologii, kritika produktu) obsahuje smoke testy a nefunkcionální testy kromě testů použitelnosti; tyto testy bývají často automatizované.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"UP-4-34","n":null,"lo":"FL-5.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Pracujete jako tester na projektu vývoje pokladního systému (point-of-sale) pro obchody s potravinami a další podobné maloobchodní prodejny. Která z následujících možností je pro takový projekt produktovým rizikem?<\/p>","m":["<p>Uvedení spolehlivějšího konkurenčního produktu na trh.<\/p>","<p>Dodání neúplného vydání pro testování do prvního cyklu systémového testování.<\/p>","<p>Systém nepřijme povolené platební karty.<\/p>","<p>Při konfirmačním testování selže nadměrně vysoký počet oprav defektů.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Příchod konkurenčního produktu je vnější obchodní riziko, netýká se kvalitativních charakteristik vyvíjeného produktu.","b":"Není správně. Zpožděné nebo neúplné dodávky pracovních produktů jsou organizační problém, tedy projektové riziko.","c":"Je správně. Nepřijetí povolených platebních karet je chybějící nebo nesprávná funkcionalita, tedy produktové riziko.","d":"Není správně. Vysoký počet neúspěšných oprav ohrožuje harmonogram a rozpočet projektu – jde o projektové riziko."},"obecne":"Sylabus 5.2.2: Produktová rizika souvisejí s kvalitativními charakteristikami produktu (např. chybějící nebo nesprávná funkcionalita), projektová rizika s managementem a řízením projektu (organizační, lidské, technické a dodavatelské problémy). Nepřijetí povolených platebních karet je selhání funkcionality systému, proto jde o produktové riziko.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.2.2","nazev":"Projektová a produktová rizika","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-dva-projektova-a-produktova-rizika"}},{"id":"UP-4-35","n":null,"lo":"FL-5.3.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností je běžnou metrikou testování, která NEJLÉPE indikuje postup testování?<\/p>","m":["<p>Počet a závažnost produktových rizik<\/p>","<p>Počet testerů zapojených do provedení testů<\/p>","<p>Plánované datum dokončení provedení testů<\/p>","<p>Míra selhání provedených testů<\/p>"],"ok":[3],"vys":{"a":"Není správně. Počet a závažnost produktových rizik slouží k plánování a prioritizaci testování, postup testování neměří.","b":"Není správně. Počet testerů je údaj o zdrojích; skutečný postup testování neměří (nanejvýš pomáhá odhadnout očekávaný postup).","c":"Není správně. Plánované datum dokončení je odhad z plánu, nikoli měření skutečného postupu.","d":"Je správně. Počet provedených testů, které prošly nebo selhaly, patří mezi metriky postupu testování; ukazuje také, kolik práce zbývá na konfirmačních testech."},"obecne":"Sylabus 5.3.1 uvádí mezi metrikami postupu testování mj. počet spuštěných/nespuštěných testovacích případů a testovacích případů, které prošly/selhaly. Míra selhání provedených testů je proto z nabízených možností jediná metrika, která vypovídá o skutečném postupu testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.3.1","nazev":"Metriky používané v testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-jedna-metriky-pouzivane-v-testovani"}},{"id":"UP-4-36","n":null,"lo":"FL-5.3.3","k":"K2","k3":true,"vyber":1,"q":"<p>Na projektu se podílejí zainteresované strany z několika zemí v různých časových pásmech. Který komunikační prostředek je NEJVHODNĚJŠÍ k tomu, aby měly kdykoli k dispozici aktuální přehled o stavu testování?<\/p>","m":["<p>Dashboardy<\/p>","<p>Ústní komunikace<\/p>","<p>Formální reporty z testování<\/p>","<p>Online dokumentace<\/p>"],"ok":[0],"vys":{"a":"Je správně. Dashboardy (např. CI/CD dashboard, tabule s úkoly, graf burn-down) ukazují aktuální stav testování a zainteresované strany si je mohou zobrazit kdykoli, bez synchronní komunikace.","b":"Není správně. Ústní komunikace vyžaduje, aby byli účastníci k dispozici ve stejnou dobu, což je při rozdílných časových pásmech obtížné.","c":"Není správně. Formální reporty jsou pro distribuované týmy vhodné, vznikají však v určitých intervalech, takže neukazují kdykoli aktuální stav.","d":"Není správně. Online dokumentace je dostupná kdykoli, ale typicky neposkytuje průběžně aktualizovaný přehled o stavu testování; informace si musí zainteresované strany samy vyhledat."},"obecne":"Sylabus 5.3.3 uvádí jako možnosti komunikace stavu testování ústní komunikaci, dashboardy, elektronické komunikační kanály, online dokumentaci a formální reporty z testování. Pro geograficky rozptýlené zainteresované strany, které potřebují kdykoli vidět aktuální stav, jsou nejvhodnější dashboardy, protože se průběžně aktualizují a nevyžadují synchronní komunikaci.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.3.3","nazev":"Komunikování stavu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-tri-komunikovani-stavu-testovani"}},{"id":"UP-4-37","n":null,"lo":"FL-5.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících tvrzení popisují účel konfiguračního managementu při testování?<\/p><ol><li>Vybrat a zavést vhodný nástroj pro konfigurační management.<\/li><li>Jednoznačně identifikovat položky testwaru a s nimi související vyvinutý software.<\/li><li>Zajistit trasovatelnost mezi položkami testwaru a vyvinutým softwarem.<\/li><li>Umožnit uživatelům konfigurovat software.<\/li><li>Řídit verze softwaru uvolňované do testovacího prostředí.<\/li><\/ol>","m":["<p>2, 3 a 4<\/p>","<p>2, 3 a 5<\/p>","<p>1, 2 a 4<\/p>","<p>1, 3 a 5<\/p>"],"ok":[1],"vys":{"a":"Není správně. Konfigurace softwaru uživateli (4) s konfiguračním managementem nesouvisí.","b":"Je správně. Jednoznačná identifikace (2), trasovatelnost (3) a řízení verzí (5) jsou přesně to, co konfigurační management při testování zajišťuje.","c":"Není správně. Tvrzení 1 a 4 účel konfiguračního managementu nepopisují.","d":"Není správně. Výběr nástroje (1) není účelem konfiguračního managementu, je jen prostředkem k jeho zavedení."},"obecne":"Sylabus 5.4: Konfigurační management zajišťuje, že všechny konfigurační položky, včetně položek testování, jsou jednoznačně identifikovány, mají řízené verze, jsou sledovány jejich změny a jsou provázány s ostatními položkami, aby byla zachována trasovatelnost. Tomu odpovídají tvrzení 2, 3 a 5.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"}},{"id":"UP-4-38","n":null,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Testovací skript „Transval 001“ ověřuje obrazovku pro validaci transakcí „TRN03“. Podle specifikace (PID verze 1.3, oddíl 10.2) by validační obrazovka neměla přijímat transakce s budoucím datem. <\/p><p>Testovací skript „EOD 004“ ověřuje zpracování na konci dne; tento skript je naplánován ke spuštění poté, co jsou data zadána prostřednictvím obrazovky „TRN03“. <\/p><p>Během provedení testů testovací skript „Transval 001“ prošel, ale testovací skript „EOD 004“ selhal, protože transakce s budoucím datem zřejmě způsobily selhání zpracování na konci dne. <\/p><p>Je třeba vytvořit report o defektu. Který z následujících obsahů je NEJLEPŠÍ do něj uvést?<\/p>","m":["<p><strong>Název<\/strong>: Selhání zpracování na konci dne. <\/p><p><strong>Reprodukovatelné<\/strong>: Ano. <\/p><p><strong>Popis<\/strong>: Skript „EOD 004“ selže, když má první transakce dne budoucí datum. Snímek obrazovky se selháním je přiložen<\/p>","<p><strong>Název<\/strong>: Validace na obrazovce pro zadávání transakcí. <\/p><p><strong>Reprodukovatelné<\/strong>: Ano. <\/p><p><strong>Popis<\/strong>: Zpracování na konci dne selhává. Validace zadání transakce na obrazovce TRN03 by neměla povolit transakce s budoucím datem – viz PID ver. 1.3, oddíl 10.2. Přiložen je snímek obrazovky se selháním a doklad o transakci s budoucím datem ze vstupní obrazovky spolu s databázovým dotazem, který transakci s budoucím datem zobrazuje<\/p>","<p><strong>Název<\/strong>: Validace data transakce na obrazovce TRN03. <\/p><p><strong>Reprodukovatelné<\/strong>: Ne. <\/p><p><strong>Popis<\/strong>: Když je transakce s budoucím datem zpracována zpracováním na konci dne, může dojít k selhání. Tři dnešní běhy zpracování na konci dne prošly, takže k tomu nedochází vždy. Snímek obrazovky se selháním je přiložen<\/p>","<p><strong>Název<\/strong>: Validace data transakce na obrazovce TRN03. <\/p><p><strong>Reprodukovatelné<\/strong>: Ano. <\/p><p><strong>Popis<\/strong>: Skript „EOD 004“ selhal, protože transakce měla budoucí datum. Přiložen je snímek obrazovky se selháním a také databázový dotaz zobrazující transakci s budoucím datem. Validace zadání transakce na obrazovce TRN03 by neměla povolit transakce s budoucím datem – viz PID ver. 1.3, oddíl 10.2<\/p>"],"ok":[3],"vys":{"a":"Není správně. Report popisuje jen důsledek ve zpracování na konci dne a neuvádí, že příčinou je chybějící validace na obrazovce TRN03, ani odkaz na specifikaci.","b":"Není správně. Název je obecný a popis začíná selháním zpracování na konci dne; chybí odkaz na skript „EOD 004“, při jehož provedení bylo selhání zjištěno.","c":"Není správně. Report nesprávně uvádí, že selhání není reprodukovatelné, a nezmiňuje, že validace na obrazovce TRN03 neměla transakci s budoucím datem vůbec propustit.","d":"Je správně. Report má výstižný název, uvádí reprodukovatelnost, testovací skript, při kterém se selhání projevilo, přiložené důkazy (snímek obrazovky, databázový dotaz) a odkaz na specifikaci s očekávaným chováním."},"obecne":"Sylabus 5.5: Report o defektu má obsahovat mj. název se stručným shrnutím anomálie, kontext defektu (např. spuštěný testovací případ), popis selhání umožňující reprodukci včetně příloh, očekávané a skutečné výsledky a odkazy. Možnost d) míří na skutečnou příčinu (chybějící validace data na obrazovce TRN03) a obsahuje všechny tyto údaje.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UP-4-39","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících kategorií nástrojů NEJPRAVDĚPODOBNĚJI usnadní automatizované provádění testů?<\/p>","m":["<p>Nástroje pro spolupráci a komunikaci v týmu<\/p>","<p>Nástroje pro statické testování a revize<\/p>","<p>Nástroje pro management testování a defektů<\/p>","<p>Nástroje pro provádění testů a měření pokrytí<\/p>"],"ok":[3],"vys":{"a":"Není správně. Nástroje pro spolupráci usnadňují komunikaci.","b":"Není správně. Nástroje pro statické testování podporují revize a statickou analýzu, testy nespouštějí.","c":"Není správně. Nástroje pro management testování usnadňují správu požadavků, testů, defektů a konfigurací.","d":"Je správně. Nástroje pro provádění testů a měření pokrytí usnadňují automatizované provádění testů a měření pokrytí."},"obecne":"Sylabus 6.1: nástroje pro provádění testů a měření pokrytí usnadňují automatizované provádění testů a měření pokrytí.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-4-40","n":null,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího je možným rizikem používání nástrojů pro automatizaci testů?<\/p>","m":["<p>Nerealistická očekávání, tj. očekávání, že nástroj zvládne příliš mnoho.<\/p>","<p>Nástroj zopakuje přesně totéž, co provedl při minulém spuštění.<\/p>","<p>Nedostatečné spoléhání na nástroj, tj. pokračování v manuálním testování i po pořízení nástroje.<\/p>","<p>Objektivnější hodnocení, např. měření pokrytí.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Nerealistická očekávání ohledně přínosů nástroje jsou rizikem automatizace.","b":"Není správně. Opakování stejných kroků je žádoucí konzistence a opakovatelnost, tedy přínos.","c":"Není správně. Rizikem je naopak přílišné spoléhání na nástroj; manuální testování má automatizaci doplňovat.","d":"Není správně. Objektivnější hodnocení je přínosem automatizace."},"obecne":"Sylabus 6.2 uvádí mezi riziky automatizace testů nerealistická očekávání ohledně přínosů nástroje (včetně funkcionality a snadnosti použití) a přílišné spoléhání na nástroj.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}},{"id":"UP-5-01","n":null,"lo":"FL-1.1.1","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení je platným cílem testování?<\/p>","m":["Prokázat, že žádné zbývající defekty nezpůsobí v provozu selhání.","Vyvolat selhání a najít defekty, aby je bylo možné identifikovat a opravit.","Testování by mělo začít co nejpozději, aby měl vývoj dostatek času na vytvoření dobrého produktu.","Prokázat, že byly identifikovány všechny defekty v testovaném objektu."],"ok":[1],"vys":{"a":"Není správně. Aby bylo možné tvrdit, že zbývající defekty nezpůsobí selhání, musely by být všechny nalezeny, což není možné.","b":"Je správně. Vyvolání selhání a nalezení defektů je typickým cílem testování.","c":"Není správně. Je v rozporu s principem Včasné testování šetří čas a peníze.","d":"Není správně. Kompletní testování není možné a testování nemůže prokázat nepřítomnost defektů."},"obecne":"Sylabus 1.1.1 uvádí mezi typickými cíli testování vyvolání selhání a nalezení defektů. Prokázat nepřítomnost defektů nebo selhání testování nemůže (sylabus 1.3, principy 1 a 2).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"}},{"id":"UP-5-02","n":null,"lo":"FL-1.2.1","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících scénářů NEJLÉPE ilustruje význam testování?<\/p>","m":["<p>Zavedení pipeline pro kontinuální dodávání za účelem automatizace nasazování softwaru<\/p>","<p>Vytváření person uživatelů za účelem pochopení různých potřeb a preferencí uživatelů<\/p>","<p>Provedení uživatelského akceptačního testování za účelem zajištění souladu s očekáváními uživatelů<\/p>","<p>Pořádání teambuildingových výjezdů za účelem podpory pozitivního pracovního prostředí<\/p>"],"ok":[2],"vys":{"a":"Není správně. Pipeline pro kontinuální dodávání automatizuje nasazování, sama o sobě význam testování neilustruje.","b":"Není správně. Persony pomáhají porozumět potřebám uživatelů, ale nejde o testování.","c":"Je správně. Uživatelské akceptační testování validuje, že software splňuje potřeby a očekávání uživatelů, a ukazuje tak, proč je testování nezbytné.","d":"Není správně. Teambuilding podporuje pracovní prostředí, s testováním nesouvisí."},"obecne":"Sylabus 1.2.1: Testování poskytuje prostředky pro přímé hodnocení kvality testovaného objektu a zajišťuje, že pochopení potřeb uživatelů je zohledněno v průběhu celého životního cyklu vývoje. Uživatelské akceptační testování je přímým příkladem validace vůči očekáváním uživatelů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.2.1","nazev":"Jak testování přispívá k úspěchu","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-jedna-jak-testovani-prispiva-k-uspechu"}},{"id":"UP-5-03","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Pan Novák testuje softwarové aplikace na mobilních zařízeních již 5 let. Má bohaté zkušenosti s testováním mobilních aplikací a dosahuje lepších výsledků v kratším čase než ostatní. Po delší dobu však neupravoval stávající automatizované testovací případy ani nevytvářel nové. Provedením testů se proto nachází stále méně defektů. Který princip testování pan Novák nedodržel?","m":["Kompletní testování není možné.","Shlukování defektů.","Testování je závislé na kontextu.","Testy se opotřebovávají."],"ok":[3],"vys":{"a":"Není správně. Kompletní testování není možné bez ohledu na vynaložené úsilí, se stále stejnými testy to nesouvisí.","b":"Není správně. Shlukování defektů popisuje, že většina defektů je v malém počtu komponent, ne pokles účinnosti testů.","c":"Není správně. Princip říká, že testování se v různých kontextech provádí odlišně; klesající počet nalezených defektů nevysvětluje.","d":"Je správně. Pokud se stejné testy opakují stále dokola, stávají se méně účinnými; je třeba je měnit nebo vytvářet nové."},"obecne":"Sylabus 1.3, princip 5 (Testy se opotřebovávají): Pokud se stejné testy opakují neustále dokola, stávají se stále méně účinnými a nedochází k odhalování nových defektů. Je nutné měnit stávající testy a testovací data, případně vytvářet testy nové.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-5-04","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"Která z následujících činností je součástí testovací analýzy?","m":["Vyhodnocení testovatelnosti testovací báze.","Identifikace potřebné infrastruktury a nástrojů.","Seskupení testovacích skriptů do sad testů.","Analýza ponaučení (lessons learned) za účelem zlepšení procesu."],"ok":[0],"vys":{"a":"Je správně. Při testovací analýze jsou testovací báze a testované objekty hodnoceny za účelem posouzení jejich testovatelnosti a identifikace defektů.","b":"Není správně. Identifikace potřebné infrastruktury a nástrojů je součástí návrhu testů.","c":"Není správně. Seskupování testovacích případů a skriptů do sad testů je součástí implementace testování.","d":"Není správně. Analýza ponaučení probíhá při dokončení testování."},"obecne":"Sylabus 1.4.1: Testovací analýza zahrnuje analýzu testovací báze za účelem identifikace testovatelných užitných vlastností a definování testovacích podmínek. Testovací báze a testované objekty jsou také hodnoceny za účelem posouzení jejich testovatelnosti.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"UP-5-05","n":null,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Rozlište následující pracovní produkty testování (1–4) tak, že je přiřadíte ke správnému popisu (A–D).<\/p><p>1. Sada testů<br>2. Testovací případ<br>3. Testovací skript<br>4. Testovací listina<\/p><p>A. Skupina testovacích skriptů, které se mají provést v jednom běhu testů<br>B. Posloupnost instrukcí pro provedení testu<br>C. Obsahuje vstupy, vstupní podmínky a očekávané výsledky<br>D. Popis cílů testování a případných testovacích nápadů, jak testovat<\/p>","m":["1A, 2C, 3B, 4D","1D, 2B, 3A, 4C","1A, 2C, 3D, 4B","1D, 2C, 3B, 4A"],"ok":[0],"vys":{"a":"Je správně. Sada testů = skupina skriptů (A), testovací případ = vstupy a očekávané výsledky (C), testovací skript = posloupnost instrukcí (B), testovací listina = cíle a testovací nápady (D).","b":"Není správně. Testovací listina nepopisuje sadu testů a testovací skript není skupinou skriptů.","c":"Není správně. Testovací skript a testovací listina jsou zaměněny.","d":"Není správně. Sada testů a testovací listina jsou zaměněny."},"obecne":"Sada testů je skupina testovacích skriptů nebo procedur provedených v jednom běhu (výstup implementace testování), testovací případ obsahuje vstupní podmínky, vstupy, očekávané výsledky a výstupní podmínky, testovací skript je posloupnost instrukcí pro provedení testu a testovací listina (sylabus 4.4.2) popisuje cíle testování a testovací nápady pro průzkumné testování v relacích.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"UP-5-06","n":null,"lo":"FL-1.4.5","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje, jak jsou úkoly rozděleny mezi manažera testování a testera?<\/p>","m":["Manažer testování plánuje testovací činnosti a volí normy, které se budou dodržovat, zatímco tester volí nástroje a pravidla pro jejich používání.","Manažer testování plánuje a organizuje testování a specifikuje testovací případy, zatímco tester prioritizuje a provádí testy.","Manažer testování plánuje, monitoruje a řídí testovací činnosti, zatímco tester analyzuje testovací bázi, navrhuje testy a provádí je.","Manažer testování plánuje, monitoruje a řídí testovací činnosti, zatímco tester navrhuje testy a rozhoduje o uvolnění testovaného objektu."],"ok":[2],"vys":{"a":"Není správně. Výběr nástrojů a pravidel pro jejich používání není typickým úkolem testera.","b":"Není správně. Specifikace testovacích případů (návrh testů) je úkolem testera, nikoli manažera testování.","c":"Je správně. Manažer testování se zaměřuje na plánování, monitoring a řízení testování, tester na testovací analýzu, návrh testů, implementaci a provedení testů.","d":"Není správně. O uvolnění testovaného objektu nerozhoduje tester; testování k rozhodnutí poskytuje informace."},"obecne":"Sylabus 1.4.5: Manažer testování má celkovou odpovědnost za proces testování a zaměřuje se na plánování, monitoring a řízení a dokončení testování. Tester odpovídá za inženýrský aspekt testování: testovací analýzu, návrh testů, implementaci testování a provedení testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.5","nazev":"Role v testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-pet-role-v-testovani"}},{"id":"UP-5-08","n":null,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":2,"q":"Které DVĚ z následujících možností NEJLÉPE představují odpovědnosti, které jsou v souladu s týmovým přístupem?","m":["Testeři odpovídají za vývoj testů komponent, které předávají vývojářům k provedení.","Od zástupců byznysu se očekává, že vyberou nástroje, které bude tým během projektu používat.","Od testerů se očekává, že budou spolupracovat se zástupci zákazníka na vytváření akceptačních testů.","Za kvalitu produktu odpovídá celý tým, nejen testeři.","Od vývojářů se očekává, že budou testovat nefunkcionální požadavky (výkonnost, použitelnost, zabezpečení atd.)."],"ok":[2,3],"vys":{"a":"Není správně. Rozdělení úkolů závisí na dovednostech členů týmu; testy komponent obvykle vytvářejí vývojáři.","b":"Není správně. Nástroje vybírá tým společně, nikoli pouze zástupci byznysu.","c":"Je správně. Testeři spolupracují se zástupci byznysu a pomáhají jim vytvořit vhodné akceptační testy.","d":"Je správně. Při týmovém přístupu je každý člen týmu zodpovědný za kvalitu.","e":"Není správně. Nefunkcionální testování není vyhrazeno vývojářům; úkoly přebírá ten, kdo má potřebné dovednosti."},"obecne":"Sylabus 1.5.2: Při týmovém přístupu může každý člen týmu s potřebnými znalostmi a dovednostmi vykonávat jakýkoliv úkol a každý je zodpovědný za kvalitu. Testeři úzce spolupracují se zástupci byznysu, např. na vytvoření vhodných akceptačních testů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"UP-5-09","n":null,"lo":"FL-2.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o životním cyklu podle V-modelu je pravdivé?<\/p>","m":["<p>Proces testování je provázán s procesem vývoje<\/p>","<p>Dynamické testování lze provádět již v úvodních fázích projektu<\/p>","<p>Software vzniká po přírůstcích, z nichž každý prochází všemi fázemi<\/p>","<p>Testeři se do projektu zapojují až po dokončení kódu<\/p>"],"ok":[0],"vys":{"a":"Je správně. Ve V-modelu odpovídá každé vývojové fázi příslušná úroveň testování, testování je tedy s vývojem provázáno.","b":"Není správně. V sekvenčních modelech vzniká spustitelný kód až v pozdějších fázích, dynamické testování proto na začátku provádět nelze.","c":"Není správně. Jde o popis inkrementálního modelu, V-model je sekvenční.","d":"Není správně. Ve V-modelu se testeři zapojují už v počátečních fázích (revize požadavků, testovací analýza a návrh testů)."},"obecne":"Sylabus 2.1.1 a 2.1.2: V-model je sekvenční model vývoje, v němž ke každé vývojové činnosti existuje odpovídající testovací činnost. Testeři se v počátečních fázích účastní revizí požadavků, testovací analýzy a návrhu testů; dynamické testování je možné až v pozdějších fázích, kdy existuje spustitelný kód.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.1","nazev":"Vliv životního cyklu vývoje softwaru na testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-jedna-vliv-zivotniho-cyklu-vyvoje-softwaru-na-testovani"}},{"id":"UP-5-10","n":null,"lo":"FL-2.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Jsou dána následující tvrzení o vztazích mezi činnostmi vývoje softwaru a testovacími činnostmi v životním cyklu vývoje softwaru:<\/p><p>1. Každá vývojová činnost by měla mít odpovídající testovací činnost.<\/p><p>2. Revize by měly začít, jakmile jsou k dispozici finální verze dokumentů.<\/p><p>3. Návrh a implementace testů by měly začít během odpovídající vývojové činnosti.<\/p><p>4. Testovací činnosti by měly začít v raných fázích životního cyklu vývoje softwaru.<\/p><p><br><\/p><p>Která z následujících možností SPRÁVNĚ ukazuje, která tvrzení jsou pravdivá a která nepravdivá?<\/p><p><br><\/p>","m":["<p>Pravdivá – 1, 2; nepravdivá – 3, 4<\/p>","<p>Pravdivá – 1, 4; nepravdivá – 2, 3<\/p>","<p>Pravdivá – 2, 3; nepravdivá – 1, 4<\/p>","<p>Pravdivá – 1, 2, 4; nepravdivá – 3<\/p>"],"ok":[1],"vys":{"a":"Není správně. Tvrzení 2 je nepravdivé (revize mají začít už u pracovních verzí) a tvrzení 4 je pravdivé.","b":"Je správně. Pravdivá jsou tvrzení 1 a 4; tvrzení 2 a 3 jsou nepravdivá.","c":"Není správně. Tvrzení 1 je pravdivé a tvrzení 2 a 3 jsou nepravdivá.","d":"Není správně. Tvrzení 2 je nepravdivé – testeři se zapojují do revize už u pracovních verzí, ne až u finálních."},"obecne":"<p>Sylabus 2.1.2:<\/p><p>1. PRAVDA – ke každé vývojové činnosti existuje odpovídající testovací činnost.<\/p><p>2. NEPRAVDA – testeři se zapojují do revize, jakmile jsou k dispozici pracovní verze (drafty), ne až finální verze.<\/p><p>3. NEPRAVDA – během odpovídající vývojové fáze má začít testovací analýza a návrh testů, nikoli implementace testů.<\/p><p>4. PRAVDA – včasné testování a shift left.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"}},{"id":"UP-5-11","n":null,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje vývoj řízený chováním (BDD)?<\/p>","m":["<p>BDD spočívá v psaní testů komponent zaměřených výhradně na funkčnost kódu.<\/p>","<p>BDD při ověřování chování softwaru spoléhá na manuální testování.<\/p>","<p>BDD podporuje spolupráci vývojářů, testerů a zástupců byznysu.<\/p>","<p>BDD klade důraz na zápis akceptačních kritérií v technickém jazyce.<\/p>"],"ok":[2],"vys":{"a":"Není správně. BDD popisuje požadované chování aplikace, nejde o testy komponent zaměřené jen na kód.","b":"Není správně. Testovací případy v BDD by se měly automaticky převádět na spustitelné testy.","c":"Je správně. Společný popis chování v přirozeném jazyce usnadňuje spolupráci vývojářů, testerů a zástupců byznysu.","d":"Není správně. V BDD se chování popisuje v přirozeném jazyce srozumitelném zainteresovaným stranám, ne v technickém jazyce."},"obecne":"Sylabus 2.1.3: v BDD je požadované chování aplikace popsáno testovacími případy v jednoduché formě přirozeného jazyka srozumitelného zainteresovaným stranám (obvykle Given/When/Then), které se poté automaticky převádějí na spustitelné testy. Společný jazyk podporuje spolupráci celého týmu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UP-5-12","n":null,"lo":"FL-2.1.4","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je běžnou výhodou zavedení DevOps?<\/p>","m":["<p>Trvalá dostupnost zastaralých verzí softwaru<\/p>","<p>Nárůst počtu manuálních regresních testů<\/p>","<p>Zpoždění vydání produktu kvůli manuálním procesům nasazení<\/p>","<p>Zkrácení doby uvedení nových služeb na trh (time to market)<\/p>"],"ok":[3],"vys":{"a":"Není správně. DevOps směřuje k častému dodávání aktuálních verzí, ne k udržování zastaralých.","b":"Není správně. DevOps díky automatizaci snižuje potřebu opakovaného manuálního testování.","c":"Není správně. DevOps prosazuje automatizované nasazení (CI/CD), které vydávání zrychluje.","d":"Je správně. Rychlejší a častější vydávání a kratší doba uvedení na trh jsou typickou výhodou DevOps."},"obecne":"Sylabus 2.1.4: z pohledu testování DevOps poskytuje rychlou zpětnou vazbu o kvalitě kódu, díky CI podporuje shift left, usnadňuje vytváření stabilních testovacích prostředí, zvyšuje důraz na nefunkcionální charakteristiky kvality, snižuje potřebu opakovaného manuálního testování a minimalizuje riziko regrese díky automatizovaným regresním testům. Manuální testování, zejména z pohledu koncového uživatele, je však stále potřeba.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.4","nazev":"DevOps a testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-ctyri-devops-a-testovani"}},{"id":"UP-5-13","n":null,"lo":"FL-2.2.1","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení porovnávajících testování komponent a systémové testování je PRAVDIVÉ?<\/p>","m":["<p>Testovací případy pro testování komponent se obvykle odvozují ze specifikací komponent, detailního návrhu nebo datových modelů, zatímco pro systémové testování ze specifikací požadavků na systém.<\/p>","<p>Za testování komponent odpovídají testeři, zatímco za systémové testování obvykle odpovídají uživatelé systému.<\/p>","<p>Testování komponent se zaměřuje pouze na funkcionální charakteristiky, zatímco systémové testování na funkcionální i nefunkcionální charakteristiky.<\/p>","<p>Testování komponent ověřuje funkcionalitu samostatně testovatelných modulů, objektů a tříd, zatímco systémové testování ověřuje rozhraní mezi komponentami a interakce mezi různými částmi systému.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Testovací báze se mezi úrovněmi liší: u komponent jde o specifikace komponent a detailní návrh, u systémového testování o specifikace systému.","b":"Není správně. Testování komponent obvykle provádějí vývojáři a systémové testování často nezávislý testovací tým.","c":"Není správně. Nefunkcionální testy lze provádět i při testování komponent.","d":"Není správně. Rozhraní a interakce mezi komponentami jsou předmětem integračního testování komponent, ne systémového testování."},"obecne":"Sylabus 2.2.1: úrovně testování se liší mj. testovaným objektem, cíli, testovací bází a zodpovědnostmi. Testování komponent se zaměřuje na izolované komponenty a obvykle jej provádějí vývojáři; systémové testování se zaměřuje na chování celého systému, vychází ze specifikací systému a může jej provádět nezávislý testovací tým.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"}},{"id":"UP-5-16","n":null,"lo":"FL-3.1.2","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení SPRÁVNĚ vystihuje hodnotu statického testování?<\/p>","m":["<p>Díky statickému testování máme levnější management defektů, protože defekty lze snadno odstraňovat později v SDLC.<\/p>","<p>Od doby, kdy používáme statickou analýzu, nacházíme defekty v kódu, které by samotné dynamické testování nemuselo odhalit.<\/p>","<p>Od doby, kdy vyžadujeme statickou analýzu, ubylo opomenutých požadavků a zlepšila se komunikace mezi testery a vývojáři.<\/p>","<p>Zavedením revizí jsme zjistili, že se zvýšila jak kvalita specifikací, tak čas potřebný pro vývoj a testování.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Defekty se naopak snáze a levněji odstraňují v raných fázích SDLC.","b":"Je správně. Statická analýza může odhalit defekty v kódu, které dynamickým testováním nelze zjistit nebo se zjišťují obtížně.","c":"Není správně. Opomenuté požadavky a lepší komunikaci přinášejí revize, nikoli statická analýza.","d":"Není správně. Revize zvyšují kvalitu specifikací, celková pracnost vývoje a testování se však díky nim obvykle snižuje."},"obecne":"Sylabus 3.1.2: statické testování může odhalit defekty, které nelze zjistit dynamickým testováním (např. nedosažitelný kód), a některé defekty v kódu odhalí statická analýza mnohem efektivněji než dynamické testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"}},{"id":"UP-5-17","n":null,"lo":"FL-3.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností NENÍ výhodou včasné a časté zpětné vazby od zainteresovaných stran?<\/p>","m":["<p>Lepší porozumění prioritám a cílům projektu<\/p>","<p>Snížení rizika vývoje funkcí, které nejsou v souladu s potřebami zainteresovaných stran.<\/p>","<p>Lepší spolupráce mezi vývojovým a provozním týmem<\/p>","<p>Včasná identifikace potenciálních projektových rizik a problémů<\/p>"],"ok":[2],"vys":{"a":"Není správně. Zpětná vazba pomáhá týmu lépe porozumět tomu, co vyvíjí, a zaměřit se na nejhodnotnější funkce.","b":"Není správně. Zpětná vazba pomáhá zajistit, aby vyvíjené funkce odpovídaly potřebám zainteresovaných stran.","c":"Je správně. Spolupráce vývojového a provozního týmu souvisí s DevOps, nikoli se zpětnou vazbou od zainteresovaných stran.","d":"Není správně. Včasná zpětná vazba pomáhá odhalit potenciální problémy a rizika."},"obecne":"Sylabus 3.2.1: včasná a častá zpětná vazba pomáhá odhalit potenciální problémy s kvalitou, předchází nedorozuměním v požadavcích a pomáhá týmu zaměřit se na užitné vlastnosti s nejvyšší přidanou hodnotou. Spolupráce vývoje a provozu je tématem DevOps (2.1.4).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.1","nazev":"Výhody včasné a časté zpětné vazby od zainteresovaných stran","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-jedna-vyhody-vcasne-a-caste-zpetne-vazby-od-zainteresovanych-stran"}},{"id":"UP-5-19","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností NEJLÉPE přiřazuje popisy ke kategoriím technik testování?<\/p><p>1. Pokrytí se měří na základě zvolené struktury testovaného objektu.<br>2. Ověřuje se zpracování uvnitř testovaného objektu.<br>3. Testy vycházejí z pravděpodobnosti výskytu defektů a jejich rozložení.<br>4. Ověřují se odchylky od požadavků.<br>5. Jako testovací báze se používají uživatelské scénáře.<\/p><p>Černá – techniky testování černé skříňky<br>Bílá – techniky testování bílé skříňky<br>Zkušenosti – techniky testování založené na zkušenostech<\/p>","m":["<p>Černá – 4; Bílá – 1, 2; Zkušenosti – 3, 5<\/p>","<p>Černá – 3; Bílá – 1, 2; Zkušenosti – 4, 5<\/p>","<p>Černá – 1, 3, 5; Bílá – 2; Zkušenosti – 4<\/p>","<p>Černá – 4, 5; Bílá – 1, 2; Zkušenosti – 3<\/p>"],"ok":[3],"vys":{},"obecne":"<p>Sylabus 4.1: Techniky černé skříňky vycházejí ze specifikovaného chování – ověřují odchylky od požadavků (4) a testovací bází mohou být uživatelské scénáře (5). Techniky bílé skříňky vycházejí z vnitřní struktury – pokrytí se měří na zvolené struktuře (1) a ověřuje se zpracování uvnitř objektu (2). Techniky založené na zkušenostech využívají znalosti testerů, např. o pravděpodobném výskytu a rozložení defektů (3).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UP-5-20","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Počítá se prémie zaměstnance. Délka zaměstnání nemůže být záporná, ale může být nulová. Výše prémie se odvíjí od délky zaměstnání v těchto kategoriích:<\/p><ul><li>2 roky nebo méně,<\/li><li>více než 2 roky, ale méně než 5 let,<\/li><li>5 až 10 let včetně,<\/li><li>více než 10 let.<\/li><\/ul><p>Jaký je minimální počet testovacích případů potřebný k pokrytí všech PLATNÝCH tříd ekvivalence?<\/p>","m":["<p>2<\/p>","<p>3<\/p>","<p>4<\/p>","<p>5<\/p>"],"ok":[2],"vys":{"a":"Není správně. Platné třídy jsou čtyři, dva testy nepokryjí všechny.","b":"Není správně. O jednu méně, než je platných tříd.","c":"Je správně. Každá ze čtyř platných tříd potřebuje alespoň jeden testovací případ.","d":"Není správně. Pátá třída (záporná délka) je neplatná a otázka se ptá jen na platné třídy."},"obecne":"<p>Sylabus 4.2.1: Platné třídy jsou 0 ≤ délka ≤ 2, 2 < délka < 5, 5 ≤ délka ≤ 10 a délka > 10. Pro pokrytí každé z nich je potřeba alespoň jeden testovací případ, tedy 4.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UP-5-21","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Systém pro kontrolu rychlosti a hlášení přestupků funguje takto:<\/p><p>Při rychlosti 50 km/h nebo nižší se nic nestane.<br>Při rychlosti vyšší než 50 km/h, ale nejvýše 55 km/h, budete varováni.<br>Při rychlosti vyšší než 55 km/h, ale nejvýše 60 km/h, dostanete pokutu.<br>Při rychlosti vyšší než 60 km/h vám bude pozastaveno řidičské oprávnění.<\/p><p>Rychlost má systém k dispozici jako celé číslo. Která sada hodnot (km/h) by NEJPRAVDĚPODOBNĚJI vznikla použitím dvouhodnotové analýzy hraničních hodnot, pokud jsou relevantní pouze hraniční hodnoty na hranicích mezi uvedenými třídami?<\/p>","m":["<p>0, 49, 50, 54, 59, 60<\/p>","<p>50, 51, 55, 56, 60, 61<\/p>","<p>49, 50, 54, 55, 60, 62<\/p>","<p>50, 55, 60<\/p>"],"ok":[1],"vys":{"a":"Není správně. Chybí 51, 55, 56 a 61; hodnoty 0, 49, 54 a 59 nejsou hraniční hodnoty na hranicích tříd.","b":"Je správně. Obsahuje obě hraniční hodnoty každé ze tří hranic: 50 | 51, 55 | 56 a 60 | 61.","c":"Není správně. Chybí 51, 56 a 61; hodnoty 49, 54 a 62 nejsou hraniční hodnoty.","d":"Není správně. Obsahuje jen horní hranice tříd; chybí 51, 56 a 61."},"obecne":"<p>Sylabus 4.2.2: Třídy jsou ≤ 50, 51–55, 56–60 a ≥ 61. Na třech hranicích mezi nimi leží hraniční hodnoty 50 a 51, 55 a 56, 60 a 61.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UP-5-23","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Stavový diagram systému má tři stavy S1, S2 a S3 a tyto platné přechody: S1 –a→ S2, S2 –b→ S1, S2 –c→ S3, S3 –d→ S2 a S3 –e→ S1. Neplatné přechody diagram nezobrazuje.<\/p><p>Tester navrhl tyto testovací případy:<\/p><table><tr><th>Testovací případ<\/th><th>Výchozí stav<\/th><th>Událost<\/th><th>Očekávaný stav<\/th><\/tr><tr><td>TC1<\/td><td>S1<\/td><td>a<\/td><td>S2<\/td><\/tr><tr><td>TC2<\/td><td>S2<\/td><td>b<\/td><td>S1<\/td><\/tr><tr><td>TC3<\/td><td>S2<\/td><td>c<\/td><td>S3<\/td><\/tr><tr><td>TC4<\/td><td>S3<\/td><td>d<\/td><td>S2<\/td><\/tr><tr><td>TC5<\/td><td>S3<\/td><td>e<\/td><td>S1<\/td><\/tr><\/table><p>Které z následujících tvrzení o těchto testovacích případech je PRAVDIVÉ?<\/p>","m":["<p>Testovací případy pokrývají jen některé z platných přechodů stavového diagramu.<\/p>","<p>Testovací případy nepokrývají všechny stavy stavového diagramu.<\/p>","<p>Testovací případy pokrývají všechny platné přechody stavového diagramu.<\/p>","<p>Testovací případy pokrývají platné i neplatné přechody stavového diagramu.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Pokryty jsou všechny platné přechody.","b":"Není správně. Testy navštíví všechny tři stavy; 100% pokrytí platných přechodů zaručuje i 100% pokrytí všech stavů.","c":"Je správně. Pět testů pokrývá všech pět platných přechodů, tedy 100% pokrytí platných přechodů.","d":"Není správně. Žádný z testů se nepokouší o neplatný přechod."},"obecne":"<p>Sylabus 4.2.4: Testy pokrývají všech pět platných přechodů (S1 → S2, S2 → S1, S2 → S3, S3 → S2, S3 → S1), dosahují tedy 100% pokrytí platných přechodů a tím i všech stavů. Neplatné přechody netestují, takže nedosahují 100% pokrytí všech přechodů.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UP-5-25","n":null,"lo":"FL-4.3.3","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení o testování bílé skříňky je PRAVDIVÉ?<\/p>","m":["<p>Testování bílé skříňky se používá především k validaci vnějšího chování systému.<\/p>","<p>Testování bílé skříňky se opírá výhradně o analýzu externích specifikací.<\/p>","<p>Techniky testování bílé skříňky nejsou použitelné při statickém testování.<\/p>","<p>Testování bílé skříňky dokáže identifikovat defekty v kódu i bez podrobné dokumentace požadavků.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Vnější chování systému se ověřuje především technikami černé skříňky.","b":"Není správně. Testování bílé skříňky vychází z vnitřní struktury kódu, ne z externích specifikací.","c":"Není správně. Techniky bílé skříňky lze použít i při statickém testování, např. při revizi kódu nebo „běhu nanečisto“.","d":"Je správně. Testování bílé skříňky zohledňuje samotnou implementaci, proto odhalí defekty i tehdy, když je specifikace vágní, zastaralá nebo neúplná."},"obecne":"<p>Sylabus 4.3.3: Silnou stránkou technik bílé skříňky je, že zohledňují samotnou implementaci softwaru, což usnadňuje detekci defektů v případech, kdy je specifikace vágní, zastaralá nebo neúplná. Lze je použít i při statickém testování.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"}},{"id":"UP-5-27","n":null,"lo":"FL-4.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Co je testování založené na kontrolních seznamech?<\/p>","m":["<p>Technika založená na zkušenostech, při níž tester ověřuje produkt podle seznamu položek, pravidel nebo kritérií.<\/p>","<p>Postup odvození testovacích případů z analýzy funkcionální či nefunkcionální specifikace bez ohledu na vnitřní strukturu.<\/p>","<p>Technika, při níž se testy odvozují ze znalostí testera o chybách z minulosti nebo z obecných znalostí o selháních.<\/p>","<p>Přístup, při němž testeři dynamicky navrhují a provádějí testy na základě svých znalostí a výsledků předchozích testů.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Testeři navrhují, implementují a provádějí testy tak, aby pokryli testovací podmínky z kontrolního seznamu.","b":"Není správně. Toto je testování černé skříňky.","c":"Není správně. Toto je odhadování chyb.","d":"Není správně. Toto je průzkumné testování."},"obecne":"<p>Sylabus 4.4.3: Při testování založeném na kontrolních seznamech testeři navrhují, implementují a provádějí testy za účelem pokrytí testovacích podmínek uvedených v kontrolním seznamu. Seznamy lze vytvářet na základě zkušeností, znalostí o tom, co je pro uživatele důležité, nebo pochopení, proč a jak software selhává.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.4.3","nazev":"Testování založené na kontrolních seznamech","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-tri-testovani-zalozene-na-kontrolnich-seznamech"}},{"id":"UP-5-28","n":null,"lo":"FL-4.5.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jakou roli hraje konverzace při společném psaní uživatelských scénářů?<\/p>","m":["<p>Určuje prioritu uživatelských scénářů na základě jejich obchodní hodnoty.<\/p>","<p>Pomáhá týmu pochopit, jak bude software používán, a vyjasnit požadavky.<\/p>","<p>Slouží zainteresovaným stranám jako prostředek k vyjednávání změn uživatelských scénářů.<\/p>","<p>Zajišťuje, že uživatelské scénáře jsou napsány ve formátu, který je malý, nezávislý a testovatelný.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Prioritu určuje typicky vlastník produktu, např. při plánování iterace, ne konverzace.","b":"Je správně. Konverzace vysvětluje, jak bude software používán, a pomáhá vyjasnit požadavky a nejednoznačnosti.","c":"Není správně. Hlavním účelem konverzace není vyjednávání změn, ale společné porozumění tomu, jak bude software používán.","d":"Není správně. Vlastnosti INVEST jsou kritéria kvality scénáře; konverzace je jedna ze tří částí 3C, ne nástroj formátování."},"obecne":"<p>Sylabus 4.5.1: Uživatelský scénář má tři části (3C): karta, konverzace a potvrzení. Konverzace vysvětluje, jak bude software používán (může být dokumentovaná nebo jen verbální), a spolupráce umožňuje týmu získat společnou vizi toho, co má být dodáno.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.1","nazev":"Společné psaní uživatelských scénářů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-jedna-spolecne-psani-uzivatelskych-scenaru"}},{"id":"UP-5-29","n":null,"lo":"FL-4.5.3","k":"K3","k3":true,"vyber":1,"q":"<p>Váš tým používá vývoj řízený akceptačními testy (ATDD) k odvození testovacích případů pro následující uživatelský scénář:<\/p><p><em>Jako uživatel sociální sítě chci mít možnost zveřejňovat fotografie s popisky, abych mohl sdílet okamžiky s přáteli.<\/em><\/p><p>Který z následujících testovacích případů je NEJVHODNĚJŠÍ pro ověření tohoto uživatelského scénáře?<\/p>","m":["<p>Otestovat, zda uživatel může smazat svůj účet na sociální síti.<\/p>","<p>Otestovat, zda uživatel může nahrát fotografii bez přidání popisku.<\/p>","<p>Otestovat, zda uživatel může přidat popisek ke zveřejněné fotografii.<\/p>","<p>Otestovat, zda uživatel může prohlížet fotoalba svých přátel.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Smazání účtu je samostatná užitná vlastnost mimo rámec scénáře.","b":"Není správně. Test zveřejnění bez popisku nevaliduje požadované chování – zveřejnění fotografie s popiskem.","c":"Je správně. Test přímo ověřuje jádro scénáře – zveřejněnou fotografii s popiskem.","d":"Není správně. Prohlížení alb přátel je samostatná užitná vlastnost mimo rámec scénáře."},"obecne":"<p>Sylabus 4.5.3: Testovací případy ATDD vycházejí z akceptačních kritérií, musí pokrývat charakteristiky uživatelského scénáře a nemají přesahovat jeho rámec. Obvykle se začíná pozitivními testy, které potvrzují správné chování.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UP-5-30","n":null,"lo":"FL-5.1.1","k":"K2","k3":true,"vyber":2,"q":"<p>Které DVĚ z následujících možností mohou ovlivnit (počáteční) plánování testování a být jeho součástí?<\/p>","m":["<p>Rozpočtová omezení.<\/p>","<p>Cíle testování.<\/p>","<p>Protokol z testování (test log).<\/p>","<p>Míra selhání.<\/p>","<p>Testovací případy.<\/p>"],"ok":[0,1],"vys":{"a":"Je správně. Rozpočet a jeho omezení ovlivňují rozsah testování i to, čemu se dá priorita; rozpočet a harmonogram jsou součástí plánu testování.","b":"Je správně. Cíle testování jsou součástí kontextu testování v plánu testování a určují, co a jak se bude testovat.","c":"Není správně. Protokol z testování vzniká až při provedení testů a slouží k monitoringu, nikoli k počátečnímu plánování.","d":"Není správně. Míra selhání je metrika, kterou lze měřit až během provedení testů.","e":"Není správně. Testovací případy vznikají až při návrhu testů, tedy po plánování."},"obecne":"Sylabus 5.1.1: Plán testování obvykle obsahuje mj. kontext testování (rozsah, cíle testování, testovací báze), předpoklady a omezení testovacího projektu a rozpočet a harmonogram. Rozpočtová omezení a cíle testování proto plánování ovlivňují a jsou jeho součástí; ostatní možnosti vznikají až při pozdějších činnostech.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.1","nazev":"Účel a obsah plánu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-jedna-ucel-a-obsah-planu-testovani"}},{"id":"UP-5-31","n":null,"lo":"FL-5.1.4","k":"K3","k3":false,"vyber":1,"q":"<p>Které z následujících tvrzení přesně popisuje metodu odhadu Wideband Delphi?<\/p>","m":["<p>Spočívá ve výběru týmu expertů, kteří poskytnou samostatné odhady pracnosti, o nichž se pak společně diskutuje, dokud není dosaženo konsenzu.<\/p>","<p>Zahrnuje provedení tří odhadů – optimistického, pesimistického a nejpravděpodobnějšího – a výpočet konečného odhadu jako jejich váženého aritmetického průměru.<\/p>","<p>Opírá se o historická data a standardní poměry z předchozích projektů v organizaci za účelem odhadu pracnosti testování pro nový projekt.<\/p>","<p>Využívá matematickou extrapolaci k předpovědi budoucích trendů a výsledků na základě prvních měření v aktuálním projektu.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Ve Wideband Delphi experti nejprve odhadují každý samostatně, odchylky prodiskutují a odhad opakují, dokud nedosáhnou konsenzu.","b":"Není správně. Tento popis odpovídá tříbodovému odhadu.","c":"Není správně. Tento popis odpovídá odhadu na základě poměrů (technika založená na metrikách).","d":"Není správně. Tento popis odpovídá extrapolaci (technika založená na metrikách)."},"obecne":"Sylabus 5.1.4: Wideband Delphi je iterativní technika založená na expertech – každý expert odhaduje pracnost samostatně, výsledky se shromáždí, a pokud se odhady liší víc, než je dohodnuto, experti je prodiskutují a odhadují znovu, dokud nedosáhnou konsenzu. Jeho variantou je plánovací poker.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UP-5-32","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Testujete mobilní aplikaci, která uživatelům umožňuje najít nedalekou restauraci podle druhu jídla, které chtějí jíst. Máte k dispozici tento seznam testovacích případů, jejich priorit (menší číslo znamená vyšší prioritu) a logických závislostí:<\/p><table><tr><th>Testovací případ<\/th><th>Pokrytá testovací podmínka<\/th><th>Priorita<\/th><th>Závisí na<\/th><\/tr><tr><td>01.001<\/td><td>Výběr druhu jídla<\/td><td>3<\/td><td>–<\/td><\/tr><tr><td>01.002<\/td><td>Výběr restaurace<\/td><td>2<\/td><td>01.001<\/td><\/tr><tr><td>01.003<\/td><td>Zobrazení trasy<\/td><td>1<\/td><td>01.002<\/td><\/tr><tr><td>01.004<\/td><td>Zavolání do restaurace<\/td><td>1<\/td><td>01.002<\/td><\/tr><tr><td>01.005<\/td><td>Rezervace stolu<\/td><td>2<\/td><td>01.002<\/td><\/tr><\/table><p>Který z následujících harmonogramů provedení testů zohledňuje priority i závislosti?<\/p>","m":["<p>01.001, 01.002, 01.004, 01.005, 01.003<\/p>","<p>01.001, 01.002, 01.004, 01.003, 01.005<\/p>","<p>01.003, 01.004, 01.002, 01.001, 01.002<\/p>","<p>01.001, 01.002, 01.003, 01.005, 01.004<\/p>"],"ok":[1],"vys":{"a":"Není správně. 01.005 (priorita 2) je zařazen před 01.003 (priorita 1).","b":"Je správně. Nejprve se kvůli závislostem provedou 01.001 a 01.002, pak oba případy s prioritou 1 (01.004 a 01.003, jejich vzájemné pořadí je libovolné) a nakonec 01.005 s prioritou 2.","c":"Není správně. Harmonogram porušuje závislosti (01.003 a 01.004 před 01.002 a 01.001) a 01.002 v něm figuruje dvakrát.","d":"Není správně. 01.005 (priorita 2) je zařazen před 01.004 (priorita 1), ačkoli oba mají splněnou závislost na 01.002."},"obecne":"Sylabus 5.1.5: Testovací případy se řadí podle priority, ale pokud případ s vyšší prioritou závisí na případu s nižší prioritou, musí se nejdříve provést ten s nižší prioritou. Proto musí jako první proběhnout 01.001 (priorita 3) a 01.002, na kterých závisí ostatní případy; poté případy s prioritou 1 a nakonec 01.005.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UP-5-33","n":null,"lo":"FL-5.1.6","k":"K1","k3":true,"vyber":1,"q":"<p>Co v kontextu testovací pyramidy znamená pojem „granularita testů“?<\/p>","m":["<p>Hloubku dosaženého pokrytí testy.<\/p>","<p>Míru podrobnosti testovací dokumentace.<\/p>","<p>Rozsah nebo velikost testovaných jednotek.<\/p>","<p>Míru, do jaké testy interagují s externími systémy.<\/p>"],"ok":[2],"vys":{"a":"Není správně. Pokrytí vyjadřuje, do jaké míry testy pokrývají kód nebo požadavky, nikoli granularitu jednotlivých testů.","b":"Není správně. Podrobnost testovací dokumentace s granularitou testů nesouvisí.","c":"Je správně. Granularita vyjadřuje rozsah testované části: testy ve spodní vrstvě pyramidy jsou malé a ověřují malou část funkcionality, E2E testy v horní vrstvě velkou část.","d":"Není správně. Míra závislosti na dalších částech systému odpovídá izolaci testů, což je v pyramidě samostatná vlastnost."},"obecne":"Sylabus 5.1.6: Testovací pyramida ukazuje, že různé testy mohou mít různou granularitu. Čím vyšší vrstva, tím nižší granularita (test ověřuje větší část funkcionality), menší izolace a delší doba provádění testu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.6","nazev":"Testovací pyramida","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sest-testovaci-pyramida"}},{"id":"UP-5-34","n":null,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících kategorií testů by TYPICKY spadala do kvadrantu Q3 modelu testovacích kvadrantů?<\/p>","m":["<p>Integrační testování komponent<\/p>","<p>Funkcionální testování<\/p>","<p>Prototypy<\/p>","<p>Uživatelské akceptační testování<\/p>"],"ok":[3],"vys":{"a":"Není správně. Integrační testy komponent patří do kvadrantu Q1 (zaměřený na technologii, podpora týmu).","b":"Není správně. Funkcionální testy sylabus řadí do kvadrantu Q2.","c":"Není správně. UX prototypy patří do kvadrantu Q2 (zaměřený na byznys, podpora týmu).","d":"Je správně. Uživatelské akceptační testování patří do kvadrantu Q3 (zaměřený na byznys, kritika produktu) spolu s průzkumným testováním a testováním použitelnosti."},"obecne":"Sylabus 5.1.7: Kvadrant Q3 (zaměřený na byznys, kritika produktu) obsahuje průzkumné testování, testování použitelnosti a uživatelské akceptační testování; tyto testy jsou orientované na uživatele a často manuální.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"UP-5-36","n":null,"lo":"FL-5.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících položek NENÍ obsažena v souhrnném reportu z testování?<\/p>","m":["<p>Definice kritérií úspěšnosti/neúspěšnosti a cílů testování.<\/p>","<p>Vyhodnocení skutečného postupu vůči výstupním kritériím.<\/p>","<p>Odchylky od plánu testování.<\/p>","<p>Vyhodnocení kvality testovaného produktu.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Cíle testování a kritéria se definují už při plánování testování (v plánu testování); souhrnný report z testování je pouze vyhodnocuje.","b":"Není správně. Souhrnný report obsahuje vyhodnocení testování na základě původního plánu testování, tj. vůči cílům testování a výstupním kritériím.","c":"Není správně. Odchylky od plánu testování (např. od harmonogramu, trvání a pracnosti) jsou typickým obsahem souhrnného reportu z testování.","d":"Není správně. Vyhodnocení kvality produktu je typickým obsahem souhrnného reportu z testování."},"obecne":"Sylabus 5.3.2: Souhrnný report z testování obsahuje mj. shrnutí testů, vyhodnocení testování a kvality produktu na základě původního plánu testování (cílů testování a výstupních kritérií), odchylky od plánu testování, neošetřená rizika a nevyřešené defekty a ponaučení. Definice cílů a kritérií patří do plánu testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"}},{"id":"UP-5-38","n":null,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Testujete novou verzi softwaru pro kávovar. Kávovar umí připravit různé druhy kávy podle čtyř kategorií:<\/p><ul><li>velikost kávy (malá, střední, velká),<\/li><li>cukr (žádný, 1 dávka, 2 dávky, 3 dávky, 4 dávky),<\/li><li>mléko (ano, nebo ne),<\/li><li>ochucovací sirup (bez sirupu, karamel, lískový oříšek, vanilka).<\/li><\/ul><p>Píšete report o defektu s těmito informacemi:<\/p><p><strong>Název:<\/strong> Nízká teplota kávy.<br><strong>Stručné shrnutí:<\/strong> Při výběru kávy s mlékem je doba přípravy příliš dlouhá a teplota nápoje je příliš nízká (méně než 40 °C).<br><strong>Očekávaný výsledek:<\/strong> Teplota kávy by měla být standardní (přibližně 75 °C).<br><strong>Závažnost:<\/strong> Střední<br><strong>Priorita:<\/strong> Normální<\/p><p>Která důležitá informace v tomto reportu o defektu CHYBÍ?<\/p>","m":["<p>Skutečný výsledek testu.<\/p>","<p>Údaje identifikující testovaný kávovar.<\/p>","<p>Stav defektu.<\/p>","<p>Nápady na zlepšení testovacího případu.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Skutečný výsledek je uveden ve stručném shrnutí (doba přípravy je příliš dlouhá, teplota nižší než 40 °C).","b":"Je správně. Chybí identifikace testovaného objektu (kávovaru a verze jeho softwaru); bez ní nelze defekt spolehlivě reprodukovat, zvlášť když se testuje nová verze.","c":"Není správně. Stav defektu se při založení reportu nastaví na počáteční hodnotu (např. otevřený), často automaticky nástrojem.","d":"Není správně. Nápady na zlepšení testovacího případu nejsou součástí reportu o defektu."},"obecne":"Sylabus 5.5: Report o defektu obsahuje mj. identifikaci testovaného objektu a testovacího prostředí. V uvedeném reportu je skutečný i očekávaný výsledek, závažnost i priorita, ale chybí údaj o tom, který kávovar a jaká verze softwaru byly testovány.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UP-5-39","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Nástroj pro návrh a implementaci testů by byl NEJUŽITEČNĚJŠÍ při:<\/p>","m":["<p>monitorování postupu provádění testů<\/p>","<p>sledování pracovních toků vývojových úkolů<\/p>","<p>vytváření testovacích případů a testovacích dat<\/p>","<p>usnadňování komunikace mezi členy týmu<\/p>"],"ok":[2],"vys":{"a":"Není správně. Monitorování postupu testování podporují nástroje pro management testování.","b":"Není správně. Sledování pracovních toků podporují nástroje DevOps.","c":"Je správně. Nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, testovacích dat a testovacích procedur.","d":"Není správně. Komunikaci usnadňují nástroje pro spolupráci."},"obecne":"Sylabus 6.1: nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, testovacích dat a testovacích procedur.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-5-40","n":null,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Co z následujícího je NEJPRAVDĚPODOBNĚJI přínosem nástrojů pro provádění testů?<\/p>","m":["<p>Snadná správa verzí testwaru.<\/p>","<p>Snadný návrh testů zabezpečení.<\/p>","<p>Snadné vytváření regresních testů.<\/p>","<p>Snadné spouštění regresních testů.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Správu verzí zajišťuje konfigurační management, ne nástroj pro provádění testů.","b":"Není správně. Návrh testů zabezpečení nástroj pro provádění testů nepodporuje.","c":"Není správně. Přínos se projevuje při opakovaném provádění regresních testů, ne při jejich vytváření.","d":"Je správně. Snížení opakované manuální práce, např. spouštění regresních testů, je přínosem automatizace."},"obecne":"Sylabus 6.2: přínosem automatizace je úspora času snížením opakované manuální práce, např. provádění regresních testů, opakované zadávání stejných testovacích dat nebo porovnávání očekávaných a skutečných výsledků.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}},{"id":"UP-6-02","n":null,"lo":"FL-1.2.3","k":"K2","k3":true,"vyber":1,"q":"Která z následujících možností je u fitness náramku defektem, a nikoli kořenovou příčinou?","m":["<p>Nesprávně implementovaná konfigurační proměnná funkce GPS by mohla během letního času způsobovat problémy s určováním polohy.<\/p>","<p>Protože autor požadavků neznal doménu fitness tréninku, mylně předpokládal, že uživatelé chtějí tepovou frekvenci v úderech za hodinu.<\/p>","<p>Tester rozhraní chytrého telefonu nebyl proškolen v testování přechodů stavů, a proto přehlédl závažný defekt.<\/p>","<p>Protože návrhářka uživatelského rozhraní nikdy předtím nepracovala na nositelných zařízeních, špatně pochopila vliv odraženého slunečního světla.<\/p>"],"ok":[0],"vys":{"a":"Je správně. Nesprávně implementovaná konfigurační proměnná je defekt v softwaru, který může způsobit selhání (problémy s určováním polohy).","b":"Není správně. Neznalost domény fitness na straně autora požadavků je kořenovou příčinou.","c":"Není správně. Chybějící proškolení testera je kořenovou příčinou toho, že defekt nebyl odhalen.","d":"Není správně. Nedostatek zkušeností návrhářky s nositelnými zařízeními je kořenovou příčinou, která vedla k chybě v návrhu."},"obecne":"Sylabus 1.2.3: Kořenová příčina je primární důvod vzniku problému (např. nedostatečné znalosti nebo školení), který vede k chybě. Defekt je vada v pracovním produktu (např. nesprávná konfigurační proměnná v kódu), která může při spuštění způsobit selhání.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"}},{"id":"UP-6-03","n":null,"lo":"FL-1.3.1","k":"K2","k3":true,"vyber":1,"q":"Na základě analýzy rizik se více testování zaměřuje na ty oblasti testovaného systému, ve kterých počáteční testování odhalilo nadprůměrný počet defektů. Který z následujících principů testování je uplatňován?","m":["Testování je závislé na kontextu.","Shlukování defektů.","Testy se opotřebovávají.","Nepřítomnost defektů je klam."],"ok":[1],"vys":{"a":"Není správně. Princip se týká provádění testování různými způsoby podle kontextu (např. hra vs. bezpečnostně kritický systém).","b":"Je správně. Pozorované shluky defektů jsou významným vstupem pro testování založené na rizicích, proto se testovací úsilí zaměřuje na tyto oblasti.","c":"Není správně. Princip se týká opakovaného spouštění stejných testů, jejichž účinnost postupně klesá.","d":"Není správně. Princip říká, že ani systém bez nalezených defektů nemusí splnit potřeby uživatelů."},"obecne":"Sylabus 1.3, princip 4 (Shlukování defektů): Většinu defektů obvykle obsahuje malé množství komponent. Předpokládané a skutečně pozorované shluky defektů jsou významným vstupem pro testování založené na rizicích.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"}},{"id":"UP-6-04","n":null,"lo":"FL-1.4.1","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je příkladem úlohy, kterou lze provádět jako součást procesu testování?<\/p>","m":["Přidělení verze testovanému produktu","Napsání uživatelského scénáře","Návrh testovacích dat","Analýza a oprava defektu v kódu"],"ok":[2],"vys":{"a":"Není správně. Přidělování verzí položkám je součástí konfiguračního managementu.","b":"Není správně. Na psaní uživatelských scénářů se tester může podílet (plánování vydání), nejde však o činnost procesu testování, ale o tvorbu testovací báze.","c":"Je správně. Stanovení požadavků na testovací data je součástí návrhu testů a jejich vytvoření součástí implementace testování.","d":"Není správně. Diagnostika a oprava defektu jsou součástí ladění, nikoli procesu testování."},"obecne":"Sylabus 1.4.1: Návrh testů zahrnuje mimo jiné stanovení požadavků na testovací data, implementace testování jejich vytvoření. Analýza a oprava defektu je ladění, které podle sylabu 1.1.2 není součástí testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"}},{"id":"UP-6-05","n":null,"lo":"FL-1.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících pracovních produktů NENÍ spojen s návrhem testů?<\/p>","m":["Testovací případy","Požadavky na testovací data","Testovací listiny","Souhrnný report z testování"],"ok":[3],"vys":{"a":"Není správně. (Prioritizované) testovací případy jsou typickým výstupem návrhu testů.","b":"Není správně. Požadavky na testovací data jsou výstupem návrhu testů.","c":"Není správně. Testovací listiny jsou podle sylabu výstupem návrhu testů.","d":"Je správně. Souhrnný report z testování je výstupem dokončení testování, nikoli návrhu testů."},"obecne":"Sylabus 1.4.3: Pracovními produkty z návrhu testů jsou (prioritizované) testovací případy, testovací listiny, položky pokrytí, požadavky na testovací data a požadavky na testovací prostředí. Souhrnný report z testování vzniká při dokončení testování.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"}},{"id":"UP-6-06","n":null,"lo":"FL-1.4.4","k":"K2","k3":true,"vyber":1,"q":"<p>Který z následujících scénářů NEJLÉPE ukazuje přínos udržování trasovatelnosti při testování?<\/p>","m":["Propojení testovacích případů s konkrétními uživatelskými scénáři pomáhá měřit postup projektu vzhledem k byznysovým cílům.","Mapování testovacích dat na testovací prostředí usnadňuje hodnocení výkonu jednotlivých testerů.","Trasování defektů zpět k jejich kořenovým příčinám pomáhá identifikovat oblasti, v nichž je třeba vývojáře proškolit.","Vytvoření vazby mezi plány testování a milníky projektu pomáhá při přidělování zdrojů."],"ok":[0],"vys":{"a":"Je správně. Sylabus uvádí, že trasovatelnost poskytuje informace pro posouzení postupu prací v projektu vzhledem k byznysovým cílům.","b":"Není správně. Trasovatelnost neslouží k hodnocení výkonu testerů.","c":"Není správně. Analýza kořenových příčin není přínosem trasovatelnosti mezi testovací bází a testwarem.","d":"Není správně. Přidělování zdrojů je úkolem plánování, nejde o přínos trasovatelnosti."},"obecne":"Sylabus 1.4.4: Trasovatelnost poskytuje informace pro posouzení kvality produktu, způsobilosti procesů a postupu prací v projektu vzhledem k byznysovým cílům. Propojení testovacích případů s uživatelskými scénáři ukazuje stav položek testovací báze.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.4.4","nazev":"Trasovatelnost mezi testovací bází a pracovními produkty z testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-ctyri-trasovatelnost-mezi-testovaci-bazi-a-pracovnimi-produkty-z-testovani"}},{"id":"UP-6-07","n":null,"lo":"FL-1.5.2","k":"K1","k3":true,"vyber":1,"q":"<p>Jak přispívá týmový přístup ke sdílení znalostí v rámci týmu?<\/p>","m":["<p>Tím, že přiděluje testovací úlohy pouze k tomu určeným testerům<\/p>","<p>Tím, že vytváří prostředí, v němž všichni členové týmu sdílejí znalosti<\/p>","<p>Tím, že omezuje spolupráci na konkrétní role<\/p>","<p>Tím, že odrazuje od interakce mezi členy týmu<\/p>"],"ok":[1],"vys":{"a":"Přidělování testovacích úloh pouze k tomu určeným testerům je v rozporu s týmovým přístupem, který zdůrazňuje zapojení všech členů týmu do testovacích činností. Když jsou testovací úlohy omezeny na určené testery, je sdílení znalostí omezeno a tým může přijít o cenné poznatky a pohledy ostatních členů týmu.","b":"Týmový přístup vytváří prostředí, v němž všichni členové týmu sdílejí znalosti, a to podporou otevřené komunikace, spolupráce a začlenění všech. Když jsou všichni členové týmu povzbuzováni ke sdílení svých znalostí a poznatků, vede to k ucelenějšímu pochopení projektu a lepšímu rozhodování.","c":"Omezení spolupráce na konkrétní role je v rozporu s týmovým přístupem, který podporuje, aby všichni členové týmu přispívali do projektu svými odbornými znalostmi. Když je spolupráce omezena na konkrétní role v týmu, je omezeno i sdílení znalostí.","d":"Odrazování od interakce mezi členy týmu je v rozporu s týmovým přístupem, jehož cílem je zapojit do projektu všechny členy týmu. Když jsou členové týmu odrazováni od vzájemné interakce a spolupráce, sdílení znalostí je omezeno."},"obecne":"Sylabus 1.5.2: Týmový přístup zlepšuje komunikaci a spolupráci v rámci týmu a vytváří synergii tím, že umožňuje využití různých dovedností v týmu. Členové týmu sdílejí pracovní prostor a testeři mohou předávat znalost testování ostatním členům týmu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"}},{"id":"UP-6-08","n":null,"lo":"FL-1.5.3","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je výhodou nezávislého testování?<\/p>","m":["<p>Nezávislí testeři nemusejí trávit čas komunikací s projektovým týmem.<\/p>","<p>Ostatní členové projektu mohou na nezávislé testery vyvíjet tlak, aby na konci harmonogramu urychlili testování.<\/p>","<p>Nezávislí testeři někdy zpochybňují předpoklady, na nichž jsou založeny požadavky, návrhy a implementace.<\/p>","<p>Programátoři si nemusejí dělat starosti s kvalitou své práce a mohou se soustředit na produkci většího množství kódu.<\/p>"],"ok":[2],"vys":{"a":"Nezávislí testeři musejí s projektovým týmem komunikovat, aby porozuměli požadavkům, poskytovali zpětnou vazbu a spolupracovali na strategiích testování. Efektivní komunikace je pro úspěšné výsledky testování nezbytná.","b":"Nezávislé testování má poskytovat nestranné posouzení kvality softwaru bez vnějších tlaků a vlivů. Tlak na nezávislé testery, aby testování urychlili, může ohrozit důkladnost a účinnost procesu testování.","c":"Nezávislí testeři hrají klíčovou roli při zpochybňování předpokladů a ověřování správnosti požadavků, návrhů a implementací. Tím, že tyto aspekty zpochybňují, pomáhají odhalit potenciální problémy a zlepšit celkovou kvalitu softwaru.","d":"Programátoři by se měli o kvalitu své práce vždy zajímat, protože přímo ovlivňuje celkový úspěch projektu. Nezávislé testování pomáhá zajistit, aby kód splňoval požadované standardy kvality, a pomáhá včas identifikovat defekty v procesu vývoje."},"obecne":"Sylabus 1.5.3: Nezávislí testeři mohou ověřit, napadnout či vyvrátit předpoklady, které měly zainteresované strany v době přípravy specifikace či implementace systému. Ostatní možnosti popisují nevýhody nebo nesprávné představy o nezávislosti.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"1.5.3","nazev":"Nezávislost testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-tri-nezavislost-testovani"}},{"id":"UP-6-09","n":null,"lo":"FL-2.1.2","k":"K1","k3":true,"vyber":1,"q":"<p>Který osvědčený postup zajišťuje, že testování je přiměřeně důkladné a zároveň se mezi úrovněmi testování zbytečně nepřekrývá?<\/p>","m":["<p>Automatizovat všechny testovací činnosti ve všech úrovních<\/p>","<p>Ve vyšších úrovních testování používat pouze manuální testy<\/p>","<p>Spouštět stejnou sadu testů ve všech úrovních testování<\/p>","<p>Stanovit pro každou úroveň specifické a odlišné cíle testování<\/p>"],"ok":[3],"vys":{"a":"Není správně. Automatizace zvyšuje efektivitu, ale nezajišťuje, aby se úrovně testování nepřekrývaly.","b":"Není správně. Volba manuálních testů nemá vliv na překrývání úrovní testování.","c":"Není správně. Opakování stejných testů ve všech úrovních by vedlo právě k nadbytečnosti.","d":"Je správně. Specifické a odlišné cíle jednotlivých úrovní zajišťují přiměřenou důkladnost bez nadbytečnosti."},"obecne":"Sylabus 2.1.2: existují různé úrovně testování a každá má své specifické (a někdy i odlišné) cíle. Díky tomu je testování přiměřeně detailní a zároveň nedochází k nadbytečnosti.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"}},{"id":"UP-6-10","n":null,"lo":"FL-2.1.3","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností NEJLÉPE popisuje cyklus vývoje řízeného testy (TDD)?<\/p>","m":["<p>Napsat test, napsat kód, refaktorovat<\/p>","<p>Refaktorovat, napsat kód, napsat test<\/p>","<p>Napsat test, refaktorovat, napsat kód<\/p>","<p>Napsat kód, napsat test, refaktorovat<\/p>"],"ok":[0],"vys":{"a":"Je správně. Nejprve se napíše test, poté kód, který test splní, a následně lze testy i kód refaktorovat.","b":"Není správně. Toto pořadí neodpovídá TDD – test se má napsat jako první.","c":"Není správně. Refaktorovat lze až existující kód, tedy po jeho napsání.","d":"Není správně. V TDD se test píše před kódem, nikoli po něm."},"obecne":"Sylabus 2.1.3: v TDD se nejprve napíší testy, poté kód tak, aby testům vyhovoval, a následně mohou (ale nemusí) být testy i kód refaktorovány.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"}},{"id":"UP-6-12","n":null,"lo":"FL-2.1.5","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je klíčovým přínosem přístupu shift left (posun doleva)?<\/p>","m":["<p>Vyšší náklady na opravu defektů<\/p>","<p>Včasné odhalení defektů a předcházení jim<\/p>","<p>Menší potřeba automatizovaného testování<\/p>","<p>Menší spolupráce mezi vývojáři a testery<\/p>"],"ok":[1],"vys":{"a":"Není správně. Shift left naopak snižuje náklady, protože defekty se najdou dříve, kdy je jejich oprava levnější.","b":"Je správně. Dřívější testování (např. revize, testy před kódem) umožňuje defekty včas odhalit nebo jim předejít.","c":"Není správně. Shift left často využívá automatizaci (např. CI/CD a automatizované testy komponent).","d":"Není správně. Shift left spolupráci vývojářů a testerů posiluje."},"obecne":"Sylabus 2.1.5: shift left (princip včasného testování) znamená provádět testování dříve v SDLC, např. nečekat na implementaci kódu nebo integraci komponent. Neznamená to, že by se testování v pozdějších fázích mělo zanedbávat. Zavedení může zpočátku znamenat vyšší náklady, ale v pozdějších fázích pracnost a náklady šetří.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"}},{"id":"UP-6-13","n":null,"lo":"FL-2.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Ve kterých úrovních testování lze provádět nefunkcionální testy?<\/p>","m":["<p>Pouze při integračním, systémovém a akceptačním testování<\/p>","<p>Pouze při systémovém testování<\/p>","<p>Při testování komponent, integračním, systémovém i akceptačním testování<\/p>","<p>Pouze při testování komponent a integračním testování<\/p>"],"ok":[2],"vys":{"a":"Není správně. Nefunkcionální testy lze provádět i při testování komponent (např. výkonnost komponenty).","b":"Není správně. Nefunkcionální testy lze provádět i v jiných úrovních, např. už při testování komponent.","c":"Je správně. Všechny typy testů včetně nefunkcionálních lze aplikovat ve všech úrovních testování.","d":"Není správně. Nefunkcionální testy se neomezují na nižší úrovně testování."},"obecne":"Sylabus 2.2.2: všechny čtyři typy testů (funkcionální, nefunkcionální, černé a bílé skříňky) lze aplikovat ve všech úrovních testování, i když konkrétní zaměření se v každé úrovni liší. Nefunkcionální testování je někdy vhodné začít již v rané fázi, např. při testování komponent.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"2.2.2","nazev":"Typy testů","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-dva-typy-testu"}},{"id":"UP-6-14","n":null,"lo":"FL-2.2.3","k":"K2","k3":true,"vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE porovnává účel konfirmačního testování a regresního testování?<\/p>","m":["<p>Účelem konfirmačního testování je potvrdit, že změny systému byly úspěšně provedeny, zatímco účelem regresního testování je spustit testy, které dříve selhaly, a ověřit, že nyní fungují správně.<\/p>","<p>Účelem regresního testování je zajistit, aby změny v jedné části systému nezpůsobily selhání jiné části, zatímco účelem konfirmačního testování je ověřit, že všechny dříve spuštěné testy stále poskytují stejné výsledky jako dříve.<\/p>","<p>Účelem regresního testování je zajistit, aby všechny dříve spuštěné testy stále fungovaly správně, zatímco účelem konfirmačního testování je zajistit, aby opravy provedené v jedné části systému negativně neovlivnily jiné části.<\/p>","<p>Účelem konfirmačního testování je ověřit, že dříve nalezený defekt byl opraven, zatímco účelem regresního testování je zajistit, aby oprava negativně neovlivnila žádné jiné části systému.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Popis regresního testování je chybný – opakované spuštění dříve selhaných testů je konfirmační testování.","b":"Není správně. Popis konfirmačního testování je chybný – to se týká opravených defektů, ne všech dříve spuštěných testů.","c":"Není správně. Popis konfirmačního testování je chybný – to ověřuje opravu defektu, ne dopady na jiné části.","d":"Je správně. Konfirmační testování ověřuje opravu dříve nalezeného defektu, regresní testování nežádoucí dopady změny na další části systému."},"obecne":"Sylabus 2.2.3: konfirmační testování potvrzuje, že byl původní defekt úspěšně opraven. Regresní testování ověřuje, zda po realizovaných změnách (včetně oprav) nedošlo k nežádoucím dopadům, a to i v dalších komponentách či propojených systémech.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"}},{"id":"UP-6-15","n":null,"lo":"FL-3.1.1","k":"K1","k3":true,"vyber":1,"q":"<p>Na který z následujících pracovních produktů lze použít statické testování, aby se ověřilo dodržování norem a směrnic?<\/p>","m":["<p>Zdrojový kód softwaru<\/p>","<p>Zátěž systému při stresovém testu<\/p>","<p>Použitelnost uživatelského rozhraní za provozu<\/p>","<p>Výsledky provádění testů za běhu<\/p>"],"ok":[0],"vys":{"a":"Je správně. Statická analýza i revize kódu odhalí odchylky od norem, např. od konvencí pro programování.","b":"Není správně. Chování pod zátěží se posuzuje dynamickým (stresovým) testováním.","c":"Není správně. Použitelnost za provozu se hodnotí dynamickým testováním s uživateli.","d":"Není správně. Výsledky provádění testů vznikají až dynamickým testováním."},"obecne":"Sylabus 3.1.1 a 3.1.3: zdrojový kód je typickým pracovním produktem statického testování a odchylky od norem (např. nedodržování konvencí pro programování) patří mezi defekty, které se snáze odhalí staticky.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"3.1.1","nazev":"Pracovní produkty, které mohou být prověřeny statickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-jedna-pracovni-produkty-ktere-mohou-byt-provereny-statickym-testovanim"}},{"id":"UP-6-16","n":null,"lo":"FL-3.1.2","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je příkladem toho, proč je statické testování přínosné?<\/p>","m":["<p>Automatizace manuálních testů a jejich mnohonásobné spouštění ušetřily v projektu spoustu času.<\/p>","<p>Během revize požadavků si tým uvědomil, že v dokumentu chybí jeden požadavek.<\/p>","<p>Vývojář píše lepší kód, když postupuje podle vývoje řízeného testy (TDD) a spouští automatizované testy komponent.<\/p>","<p>Tester pomohl svému manažerovi odhadnout pracnost testování pro nadcházející úroveň testování.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Automatizace a spouštění testů je dynamické testování.","b":"Je správně. Revize požadavků odhalila opomenutí v požadavcích, tedy defekt, který by se dynamickým testováním odhaloval obtížně a později.","c":"Není správně. Spouštění testů komponent je dynamické testování.","d":"Není správně. Odhad pracnosti testování není statickým testováním."},"obecne":"Sylabus 3.1.2 a 3.1.3: statické testování odhalí defekty v nejranějších fázích SDLC, např. opomenutí v požadavcích, a tím se sníží náklady na jejich pozdější opravu.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"}},{"id":"UP-6-17","n":null,"lo":"FL-3.2.2","k":"K2","k3":true,"vyber":1,"q":"<p>Ve které činnosti procesu revize se stanoví výstupní kritéria revize?<\/p>","m":["<p>Individuální revize<\/p>","<p>Zahájení revize<\/p>","<p>Plánování<\/p>","<p>Opravy a reportování<\/p>"],"ok":[2],"vys":{"a":"Není správně. Během individuální revize revidující posuzuje pracovní produkt a zaznamenává anomálie.","b":"Není správně. Zahájení revize zajišťuje, aby bylo vše a všichni připraveni k revizi.","c":"Je správně. Během plánování se stanoví rozsah revize včetně výstupních kritérií.","d":"Není správně. Při opravách a reportování se vyhodnocuje splnění výstupních kritérií, nestanovují se."},"obecne":"Sylabus 3.2.2: během plánování se stanoví rozsah revize obsahující mimo jiné výstupní kritéria. Jejich splnění se ověřuje v činnosti opravy a reportování, kdy může být pracovní produkt akceptován.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.2","nazev":"Činnosti procesu revize","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-dva-cinnosti-procesu-revize"}},{"id":"UP-6-18","n":null,"lo":"FL-3.2.4","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících tvrzení o inspekci jsou pravdivá?<\/p><p>i. Autor nemůže vystupovat jako vedoucí revize ani zapisovatel.<\/p><p>ii. Revidující se před revizní schůzkou nepřipravují.<\/p><p>iii. Shromažďují se metriky pro zlepšování SDLC včetně procesu inspekce.<\/p><p>iv. Hlavním cílem je nalézt maximální počet anomálií.<\/p>","m":["<p>i, ii a iii jsou pravdivé; iv je nepravdivé<\/p>","<p>iii je pravdivé; i, ii a iv jsou nepravdivé<\/p>","<p>ii je pravdivé; i, iii a iv jsou nepravdivé<\/p>","<p>i, iii a iv jsou pravdivé; ii je nepravdivé<\/p>"],"ok":[3],"vys":{"a":"Není správně. Tvrzení ii je nepravdivé a iv je pravdivé.","b":"Není správně. Pravdivá jsou i tvrzení i a iv.","c":"Není správně. Tvrzení ii je nepravdivé a i, iii, iv jsou pravdivá.","d":"Je správně. Tvrzení i, iii a iv odpovídají popisu inspekce v sylabu, ii nikoli."},"obecne":"Sylabus 3.2.4: inspekce je nejformálnějším typem revize, řídí se kompletním procesem včetně individuální revize (přípravy), jejím hlavním cílem je nalézt maximální počet anomálií, shromažďují se metriky a autor nemůže vystupovat jako vedoucí revize nebo zapisovatel.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"}},{"id":"UP-6-19","n":null,"lo":"FL-4.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Tester analyzuje uživatelské scénáře jako testovací bázi. Odvodí z nich testovací případy pomocí testování přechodů stavů, provede je a změří dosažené pokrytí platných přechodů. Jde o příklad použití které kategorie technik testování?<\/p>","m":["<p>Techniky testování černé skříňky<\/p>","<p>Techniky testování bílé skříňky<\/p>","<p>Techniky testování založené na zkušenostech<\/p>","<p>Přístupy k testování založené na spolupráci<\/p>"],"ok":[0],"vys":{"a":"Je správně. Testování přechodů stavů je technika černé skříňky – vychází ze specifikovaného chování (modelu), ne z kódu.","b":"Není správně. Pokrytí se měří na stavovém modelu odvozeném ze specifikace, ne na struktuře kódu.","c":"Není správně. Testy jsou odvozeny systematicky z modelu, ne ze znalostí a intuice testera.","d":"Není správně. Uživatelské scénáře zde slouží jen jako testovací báze; použitou technikou je testování přechodů stavů."},"obecne":"<p>Sylabus 4.1 a 4.2: Testování přechodů stavů patří mezi techniky testování černé skříňky, které jsou založeny na analýze specifikovaného chování testovaného objektu bez informací o jeho vnitřní struktuře.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"}},{"id":"UP-6-20","n":null,"lo":"FL-4.2.1","k":"K3","k3":true,"vyber":1,"q":"<p>Fitness aplikace měří počet kroků ušlých za den a poskytuje zpětnou vazbu, která má uživatele motivovat k udržování kondice.<\/p><p>Zpětná vazba pro různé počty kroků by měla být:<\/p><p>Do 1000 – Gaučový povaleč!<\/p><p>Nad 1000, do 2000 – Lenochod!<\/p><p>Nad 2000, do 4000 – Už to bude!<\/p><p>Nad 4000, do 6000 – Není to špatné!<\/p><p>Nad 6000 – Jen tak dál!<\/p><p>Která z následujících sad testovacích vstupů by dosáhla nejvyššího pokrytí tříd ekvivalence?<\/p>","m":["<p>1000, 2001, 4000, 4001, 6000<\/p>","<p>666, 999, 2222, 5555, 6666<\/p>","<p>123, 2345, 3456, 4567, 5678<\/p>","<p>0, 1000, 2000, 3000, 4000<\/p>"],"ok":[1],"vys":{"a":"Není správně. Pokrývá jen třídy 1, 3 a 4 (60 %).","b":"Je správně. Pokrývá třídy 1, 3, 4 a 5 (80 %), nejvíce ze všech sad.","c":"Není správně. Pokrývá jen třídy 1, 3 a 4 (60 %).","d":"Není správně. Pokrývá jen třídy 1, 2 a 3 (60 %)."},"obecne":"<p>Sylabus 4.2.1: Třídy ekvivalence jsou: 1) do 1000, 2) 1001–2000, 3) 2001–4000, 4) 4001–6000, 5) nad 6000. Sada 0, 1000, 2000, 3000, 4000 pokrývá třídy 1, 2, 3 (3 z 5); 1000, 2001, 4000, 4001, 6000 třídy 1, 3, 4 (3 z 5); 123, 2345, 3456, 4567, 5678 třídy 1, 3, 4 (3 z 5); 666, 999, 2222, 5555, 6666 třídy 1, 3, 4, 5 (4 z 5) – ta je nejlepší.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"}},{"id":"UP-6-21","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Aplikace pro chytrou domácnost měří průměrnou teplotu v domě za uplynulý týden a podle ní dává obyvatelům zpětnou vazbu o jejich šetrnosti k životnímu prostředí.<\/p><p>Zpětná vazba pro rozmezí průměrné teploty (zaokrouhlené na celé °C):<\/p><p>Do 10 °C – Ledově chladno!<br>11 °C až 15 °C – Pěkně vychlazeno!<br>16 °C až 19 °C – Pohodička!<br>20 °C až 22 °C – Moc teplo!<br>Nad 22 °C – Horko a pot!<\/p><p>Která z následujících sad testovacích vstupů dosahuje NEJVYŠŠÍHO pokrytí dvouhodnotové analýzy hraničních hodnot?<\/p>","m":["<p>0 °C, 11 °C, 20 °C, 22 °C, 23 °C<\/p>","<p>9 °C, 15 °C, 19 °C, 23 °C, 100 °C<\/p>","<p>10 °C, 16 °C, 19 °C, 22 °C, 23 °C<\/p>","<p>14 °C, 15 °C, 18 °C, 19 °C, 21 °C, 22 °C<\/p>"],"ok":[2],"vys":{"a":"Není správně. Pokrývá 4 hraniční hodnoty (11, 20, 22, 23).","b":"Není správně. Pokrývá 3 hraniční hodnoty (15, 19, 23).","c":"Je správně. Pokrývá 5 hraničních hodnot (10, 16, 19, 22, 23), nejvíce ze všech sad.","d":"Není správně. Pokrývá 3 hraniční hodnoty (15, 19, 22)."},"obecne":"<p>Sylabus 4.2.2: Hraniční hodnoty jsou 10 | 11, 15 | 16, 19 | 20 a 22 | 23 (celkem 8). Sady pokrývají: 0, 11, 20, 22, 23 → 4; 9, 15, 19, 23, 100 → 3; 10, 16, 19, 22, 23 → 5; 14, 15, 18, 19, 21, 22 → 3.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UP-6-22","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>U systému pro udělování pokut za překročení rychlosti se provádí testování dle úplné rozhodovací tabulky:<\/p><table><tr><th>Podmínky / akce<\/th><th>R1<\/th><th>R2<\/th><th>R3<\/th><th>R4<\/th><\/tr><tr><td>Rychlost &gt; 50 km/h<\/td><td>T<\/td><td>T<\/td><td>F<\/td><td>F<\/td><\/tr><tr><td>Školní zóna<\/td><td>T<\/td><td>F<\/td><td>T<\/td><td>F<\/td><\/tr><tr><td>Pokuta 4 000 Kč a body<\/td><td>X<\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><td>Pokuta 2 000 Kč<\/td><td><\/td><td>X<\/td><td><\/td><td><\/td><\/tr><tr><td>Bez pokuty<\/td><td><\/td><td><\/td><td>X<\/td><td>X<\/td><\/tr><\/table><p>Pro pravidla R1 a R4 již existují testovací případy (65 km/h ve školní zóně; 40 km/h mimo školní zónu). Jsou dány tyto další testovací případy:<\/p><table><tr><th>Test<\/th><th>Rychlost (km/h)<\/th><th>Školní zóna<\/th><\/tr><tr><td>DT1<\/td><td>45<\/td><td>ne<\/td><\/tr><tr><td>DT2<\/td><td>35<\/td><td>ano<\/td><\/tr><tr><td>DT3<\/td><td>70<\/td><td>ano<\/td><\/tr><tr><td>DT4<\/td><td>60<\/td><td>ne<\/td><\/tr><\/table><p>Které dva z dalších testovacích případů by spolu s existujícími testy pro R1 a R4 dosáhly 100% pokrytí rozhodovací tabulky?<\/p>","m":["<p>DT1, DT2<\/p>","<p>DT2, DT3<\/p>","<p>DT2, DT4<\/p>","<p>DT3, DT4<\/p>"],"ok":[2],"vys":{"a":"Není správně. DT1 (45 km/h, mimo zónu) pokrývá znovu R4; R2 zůstane nepokryto.","b":"Není správně. DT3 (70 km/h, školní zóna) pokrývá znovu R1; R2 zůstane nepokryto.","c":"Je správně. DT2 pokrývá R3 (F, T) a DT4 pokrývá R2 (T, F); spolu s R1 a R4 jsou pokryta všechna 4 pravidla.","d":"Není správně. DT3 pokrývá znovu R1; R3 zůstane nepokryto."},"obecne":"<p>Sylabus 4.2.3: Položkami pokrytí jsou proveditelné sloupce (R1–R4). Existující testy pokrývají R1 (T, T) a R4 (F, F); chybí R2 (T, F) a R3 (F, T). R2 pokrývá DT4 (60 km/h mimo zónu), R3 pokrývá DT2 (35 km/h ve školní zóně).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UP-6-24","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Dávková aplikace je v produkčním provozu beze změn již více než dva roky. Jednou měsíčně běží přes noc a vytváří výpisy, které se zasílají zákazníkům e-mailem. Pro každého zákazníka aplikace projde všechny účty a u každého účtu vypíše všechny transakce za poslední měsíc. Ke zpracování používá strukturu vnořených cyklů: zákazníci (vnější cyklus), účty každého zákazníka (prostřední cyklus) a transakce každého účtu (vnitřní cyklus).<\/p><p>Jedné noci se dávková aplikace předčasně ukončí a některým zákazníkům výpisy neodešle, když narazí na zákazníka s jedním účtem, na kterém v posledním měsíci neproběhla žádná transakce. Jde o velmi neobvyklou situaci, která za celé roky od nasazení aplikace do produkce nenastala.<\/p><p>Při opravě defektu vás programátor požádá, abyste doporučili techniky testování, které jsou proti tomuto druhu defektu účinné. Která z následujících technik testování by NEJPRAVDĚPODOBNĚJI dokázala odhalit příslušný defekt?<\/p>","m":["<p>Testování větví<\/p>","<p>Testování příkazů<\/p>","<p>Testování založené na kontrolních seznamech<\/p>","<p>Odhadování chyb<\/p>"],"ok":[0],"vys":{"a":"Je správně. Testování větví se zaměřuje na výsledky rozhodnutí v kódu včetně rozhodnutí, zda cyklus provést (pokračovat), nebo ukončit; systematický návrh testů pro tato rozhodnutí vede i k případu, kdy se vnitřní cyklus neprovede ani jednou.","b":"Není správně. 100% pokrytí příkazů lze dosáhnout i testy, v nichž má každý účet alespoň jednu transakci, takže situace s prázdným vnitřním cyklem nemusí být vůbec otestována.","c":"Není správně. Obecný kontrolní seznam nemusí obsahovat položku, která by vedla k otestování účtu bez transakcí; technika se nezaměřuje na výsledky rozhodnutí v kódu.","d":"Není správně. Odhadování chyb může tento defekt odhalit, ale závisí na zkušenosti testera; testy výsledků rozhodnutí v cyklech k této situaci vedou systematičtěji."},"obecne":"Sylabus 4.3.2: Při testování větví jsou položkami pokrytí větve, mezi něž patří i výsledky rozhodnutí, zda pokračovat v cyklu, nebo jej ukončit. Návrh testů zaměřený na tato rozhodnutí přirozeně vede i k případu, kdy se vnitřní cyklus neprovede ani jednou (účet bez transakcí), což je přesně situace, která defekt vyvolala. Pokrytí příkazů tento případ nevynucuje a techniky založené na zkušenostech na něj mohou, ale nemusí pamatovat.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UP-6-25","n":null,"lo":"FL-4.3.3","k":"K2","k3":true,"vyber":1,"q":"<p>Co je hlavní výhodou testování bílé skříňky?<\/p>","m":["<p>Provádí se snáze než testování černé skříňky.<\/p>","<p>Umožňuje zkoumat vnitřní strukturu a logiku testovaného objektu.<\/p>","<p>Nevyžaduje žádnou znalost vnitřního kódu.<\/p>","<p>Zaměřuje se výhradně na uživatelský zážitek.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Testování bílé skříňky není obecně snazší; naopak vyžaduje znalost kódu a jeho struktury.","b":"Je správně. Testování bílé skříňky vychází z vnitřní struktury testovaného objektu, takže je při něm zohledněna samotná implementace softwaru.","c":"Není správně. Znalost vnitřní struktury kódu je pro testování bílé skříňky naopak nezbytná.","d":"Není správně. Testování bílé skříňky se zaměřuje na kód a jeho strukturu, nikoli na uživatelský zážitek."},"obecne":"Sylabus 4.3.3: silnou stránkou technik testování bílé skříňky je, že při testování je zohledněna samotná implementace softwaru, což usnadňuje detekci defektů i tehdy, když je specifikace vágní, zastaralá nebo neúplná.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"}},{"id":"UP-6-27","n":null,"lo":"FL-4.4.3","k":"K2","k3":true,"vyber":1,"q":"<p>Jaký je hlavní účel testování založeného na kontrolních seznamech?<\/p>","m":["<p>Zlepšit uživatelský zážitek z aplikace<\/p>","<p>Zajistit, aby byly provedeny všechny testovací případy<\/p>","<p>Poskytnout vodítko a určitou míru konzistence při testování<\/p>","<p>Automatizovat provedení testů<\/p>"],"ok":[2],"vys":{"a":"Není správně. Kontrolní seznam se může týkat i použitelnosti, ale zlepšování uživatelského zážitku není jeho hlavním účelem.","b":"Není správně. Kontrolní seznam obsahuje testovací podmínky, nikoli seznam testovacích případů k provedení.","c":"Je správně. Při absenci podrobných testovacích případů může testování založené na kontrolních seznamech poskytnout vodítko pro testování a zajistit určitou míru konzistence.","d":"Není správně. Testování založené na kontrolních seznamech je technika založená na zkušenostech; jeho cílem není automatizace. Položky ověřitelné automaticky do kontrolního seznamu dokonce nepatří."},"obecne":"Sylabus 4.4.3: testeři navrhují, implementují a provádějí testy tak, aby pokryli testovací podmínky z kontrolního seznamu. Při absenci podrobných testovacích případů poskytuje tato technika vodítko pro testování a zajišťuje určitou míru konzistence.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.4.3","nazev":"Testování založené na kontrolních seznamech","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-tri-testovani-zalozene-na-kontrolnich-seznamech"}},{"id":"UP-6-28","n":null,"lo":"FL-4.5.2","k":"K2","k3":true,"vyber":1,"q":"<p>Uvažujte následující akceptační kritéria k uživatelskému scénáři:<\/p><p><em>Za předpokladu, že uživatel vybral položky k nákupu,<\/em><\/p><p><em>když uživatel přejde k pokladně,<\/em><\/p><p><em>pak by měl systém vypočítat celkovou částku objednávky včetně daní a nákladů na dopravu.<\/em><\/p><p>V jakém formátu jsou tato akceptační kritéria napsána?<\/p>","m":["<p>Orientovaný na pravidla<\/p>","<p>Orientovaný na rozhraní<\/p>","<p>Orientovaný na kvalitu<\/p>","<p>Orientovaný na scénáře<\/p>"],"ok":[3],"vys":{"a":"Není správně. Akceptační kritéria orientovaná na pravidla mají podobu seznamu pravidel (např. verifikační seznam s odrážkami nebo tabulka vstupů a výstupů), nikoli posloupnosti předpoklad–akce–výsledek.","b":"Není správně. Sylabus formát „orientovaný na rozhraní“ nezná.","c":"Není správně. Sylabus formát „orientovaný na kvalitu“ nezná.","d":"Je správně. Kritéria popisují scénář ve formátu Given/When/Then (za předpokladu – když – pak), který je typický pro formát orientovaný na scénáře používaný v BDD."},"obecne":"Sylabus 4.5.2: dva nejběžnější formáty akceptačních kritérií jsou orientovaný na scénáře (např. Given/When/Then používaný v BDD) a orientovaný na pravidla (např. verifikační seznam s odrážkami nebo tabulka mapování vstupů a výstupů).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"}},{"id":"UP-6-29","n":null,"lo":"FL-4.5.3","k":"K3","k3":true,"vyber":1,"q":"<p>Uvažujte následující uživatelský scénář:<\/p><p><em>Jako online nakupující<\/em><\/p><p><em>chci přidávat položky do svého nákupního košíku,<\/em><\/p><p><em>abych je mohl později zakoupit.<\/em><\/p><p><br><\/p><p>Akceptační kritéria:<\/p><ul><li><p>Uživatel se může přihlásit na nákupní platformu.<\/p><\/li><li><p>Uživatel může vyhledávat položky.<\/p><\/li><li><p>Uživatel může přidávat položky do nákupního košíku.<\/p><\/li><li><p>Uživatel může zobrazit nákupní košík.<\/p><\/li><li><p>Uživatel může odebírat položky z nákupního košíku.<\/p><\/li><li><p>Uživatel může s položkami v košíku přejít k pokladně.<\/p><\/li><\/ul><p>Která z následujících možností je NEJLEPŠÍM příkladem testu ATDD pro tento uživatelský scénář?<\/p>","m":["<p>Otestovat, zda uživatel může přidat položku do košíku a poté košík zobrazit<\/p>","<p>Otestovat, zda uživatel může zobrazit historii svých dřívějších objednávek<\/p>","<p>Otestovat, zda uživatel může uložit platební kartu pro budoucí nákupy<\/p>","<p>Otestovat, zda uživatel může přesunout položku z košíku do seznamu přání<\/p>"],"ok":[0],"vys":{"a":"Je správně. Test přímo ověřuje akceptační kritéria „Uživatel může přidávat položky do nákupního košíku“ a „Uživatel může zobrazit nákupní košík“.","b":"Není správně. Historie objednávek není předmětem tohoto uživatelského scénáře ani jeho akceptačních kritérií.","c":"Není správně. Ukládání platební karty akceptační kritéria nezmiňují; test by přesahoval rámec uživatelského scénáře.","d":"Není správně. Seznam přání v akceptačních kritériích není; test by přesahoval rámec uživatelského scénáře."},"obecne":"Sylabus 4.5.3: v ATDD se testovací případy odvozují z akceptačních kritérií; musí pokrývat charakteristiky uživatelského scénáře a neměly by přesahovat jeho rámec. Jediný test, který odpovídá akceptačním kritériím, je přidání položky do košíku a jeho zobrazení.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"}},{"id":"UP-6-30","n":null,"lo":"FL-5.1.3","k":"K2","k3":true,"vyber":1,"q":"<p>Která z následujících možností je příkladem dobrého výstupního kritéria systémového testování?<\/p>","m":["<p>Vývojáři musí potvrdit, že je systém hotový.<\/p>","<p>Musí být vyřešeny všechny defekty se závažností 1.<\/p>","<p>Testování musí trvat nejméně čtyři týdny.<\/p>","<p>Musí být nalezeny všechny defekty v systému.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Subjektivní prohlášení vývojářů není měřitelná míra důkladnosti ani binární kritérium splnění testovacích úkolů.","b":"Je správně. Počet nevyřešených defektů (zde kritických) je podle sylabu typickým měřitelným výstupním kritériem.","c":"Není správně. Pevně daná minimální délka testování neříká nic o dosažené důkladnosti testování ani o kvalitě systému.","d":"Není správně. Nalezení všech defektů nelze dosáhnout ani ověřit – kompletní testování není možné."},"obecne":"Sylabus 5.1.3: Typická výstupní kritéria zahrnují míry důkladnosti (např. dosažená úroveň pokrytí, počet nevyřešených defektů, hustota defektů) a binární kritéria ano/ne (např. provedení plánovaných testů). Vyřešení všech defektů nejvyšší závažnosti je měřitelné a splnitelné kritérium; ostatní možnosti měřitelné nebo splnitelné nejsou.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"}},{"id":"UP-6-31","n":null,"lo":"FL-5.1.4","k":"K3","k3":true,"vyber":1,"q":"<p>Váš tým používá plánovací poker k odhadu pracnosti testování nově požadované funkce. V týmu platí pravidlo, že pokud není čas dosáhnout úplné shody, použije se tříbodový odhad: nejčastěji zvolená hodnota je nejpravděpodobnější odhad, nejnižší hodnota optimistický odhad a nejvyšší hodnota pesimistický odhad.<\/p><p>Ani po třetím kole nebylo dosaženo shody a na další kolo už není čas. Výsledky třetího kola:<\/p><table><tr><th>Člen týmu<\/th><th>Odhad<\/th><\/tr><tr><td>Vlastník produktu<\/td><td>11<\/td><\/tr><tr><td>Vývojář 1<\/td><td>13<\/td><\/tr><tr><td>Vývojář 2<\/td><td>10<\/td><\/tr><tr><td>Vývojář 3<\/td><td>13<\/td><\/tr><tr><td>Tester 1<\/td><td>13<\/td><\/tr><tr><td>Tester 2 (funkci zná nejlépe)<\/td><td>22<\/td><\/tr><\/table><p>Který z následujících kroků je NEJLEPŠÍ?<\/p>","m":["<p>Přijmout 11 jako konečný odhad, protože jde o odhad vlastníka produktu.<\/p>","<p>Přijmout 13 jako konečný odhad, protože získal nejvíce hlasů.<\/p>","<p>Přijmout 22 jako konečný odhad, protože jde o odhad testera, který funkci zná nejlépe.<\/p>","<p>Přijmout 14 jako konečný odhad vypočtený podle pravidla týmu.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Pravidlo týmu nedává odhadu vlastníka produktu přednost; 11 není nejčastější ani vypočtená hodnota.","b":"Není správně. 13 je nejčastější hodnota, tedy jen nejpravděpodobnější odhad (m), který vstupuje do výpočtu.","c":"Není správně. 22 je nejvyšší hodnota, tedy pesimistický odhad (b), nikoli konečný odhad.","d":"Je správně. E = (a + 4·m + b) / 6 = (10 + 4·13 + 22) / 6 = 84 / 6 = 14."},"obecne":"Sylabus 5.1.4: Při tříbodovém odhadu se konečný odhad vypočítá jako E = (a + 4·m + b) / 6. Podle pravidla týmu je a = 10 (nejnižší hodnota), m = 13 (nejčastější hodnota) a b = 22 (nejvyšší hodnota), takže E = (10 + 52 + 22) / 6 = 14.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"}},{"id":"UP-6-33","n":null,"lo":"FL-5.1.7","k":"K2","k3":true,"vyber":1,"q":"<p>Jak souvisejí testovací kvadranty s různými úrovněmi testování (např. testováním komponent, integračním testováním, systémovým testováním a akceptačním testováním)?<\/p>","m":["<p>Kvadranty s úrovněmi testování nijak nesouvisejí a používají se samostatně.<\/p>","<p>Kvadranty představují postupné fáze procesu testování, které jdou za sebou.<\/p>","<p>Každý kvadrant odpovídá právě jedné konkrétní úrovni testování.<\/p>","<p>Kvadranty seskupují úrovně testování s vhodnými typy testů a činnostmi.<\/p>"],"ok":[3],"vys":{"a":"Není správně. Model kvadrantů úrovně testování výslovně seskupuje s typy testů, nejsou na sobě nezávislé.","b":"Není správně. Kvadranty nejsou fáze ani posloupnost; testy z různých kvadrantů mohou probíhat souběžně.","c":"Není správně. Kvadrant může zahrnovat testy z více úrovní testování; např. Q1 obsahuje testy komponent i integrační testy komponent.","d":"Je správně. Kvadranty seskupují úrovně testování s vhodnými typy testů, činnostmi, technikami testování a pracovními produkty a ukazují, že některé typy testů jsou pro určité úrovně relevantnější."},"obecne":"Sylabus 5.1.7: Testovací kvadranty seskupují úrovně testování s vhodnými typy testů, činnostmi, technikami testování a pracovními produkty. Pomáhají zajistit, aby byly v SDLC zahrnuty všechny vhodné typy testů a úrovně testování, a ukazují, že některé typy testů jsou pro určité úrovně testování relevantnější než jiné.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"}},{"id":"UP-6-34","n":null,"lo":"FL-5.2.3","k":"K2","k3":true,"vyber":2,"q":"<p>Které DVĚ z následujících možností by se měly zohlednit při rozhodování, kolik testování je dostatečné?<\/p>","m":["<p>Úroveň rizika, včetně technických a byznysových produktových a projektových rizik.<\/p>","<p>Projektová omezení, jako je čas a rozpočet.<\/p>","<p>Velikost testovacího týmu.<\/p>","<p>Velikost vývojového týmu.<\/p>","<p>Nalezení všech defektů v systému.<\/p>"],"ok":[0,1],"vys":{"a":"Je správně. Analýza rizik určuje rozsah a důkladnost testování – oblasti s vyšší úrovní rizika se testují důkladněji.","b":"Je správně. Čas a rozpočet jsou omezení, v jejichž rámci je třeba rozsah testování stanovit.","c":"Není správně. Velikost testovacího týmu ovlivňuje, jak rychle se testování provede, ale ne to, kolik testování je potřeba.","d":"Není správně. Velikost vývojového týmu s potřebným rozsahem testování přímo nesouvisí.","e":"Není správně. Nalézt všechny defekty není možné – kompletní testování není možné, testováním lze riziko jen snížit."},"obecne":"Sylabus 5.2.3: Výsledky analýzy produktových rizik se používají k určení rozsahu testování, úrovní, typů a technik testování a požadovaného pokrytí. Kolik testování je dostatečné, proto závisí především na úrovni rizika a na projektových omezeních, jako je čas a rozpočet.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.2.3","nazev":"Analýza produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-tri-analyza-produktovych-rizik"}},{"id":"UP-6-35","n":null,"lo":"FL-5.3.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících metrik by byla NEJUŽITEČNĚJŠÍ pro monitoring během provedení testů?<\/p>","m":["<p>Průměrný počet testerů zapojených do provedení testů.<\/p>","<p>Procento provedených testovacích případů.<\/p>","<p>Pokrytí požadavků zdrojovým kódem.<\/p>","<p>Procento již vytvořených a zrevidovaných testovacích případů.<\/p>"],"ok":[1],"vys":{"a":"Není správně. Počet testerů je údaj o zdrojích; o postupu testování ani o kvalitě testovaného objektu nevypovídá.","b":"Je správně. Počet spuštěných/nespuštěných testovacích případů je typická metrika postupu testování během provedení testů.","c":"Není správně. Pokrytí se měří jako pokrytí kódu nebo požadavků testy, nikoli pokrytí požadavků zdrojovým kódem.","d":"Není správně. Procento vytvořených a zrevidovaných testovacích případů sleduje přípravu testů, ne jejich provedení."},"obecne":"Sylabus 5.3.1 uvádí mezi metrikami postupu testování mj. počet spuštěných/nespuštěných testovacích případů a testovacích případů, které prošly/selhaly. Během provedení testů je proto nejužitečnější sledovat procento provedených testovacích případů.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.3.1","nazev":"Metriky používané v testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-jedna-metriky-pouzivane-v-testovani"}},{"id":"UP-6-36","n":null,"lo":"FL-5.3.3","k":"K2","k3":true,"vyber":1,"q":"<p>Která komunikační metoda je NEJVHODNĚJŠÍ pro předávání naléhavých problémů souvisejících s testováním členům týmu, kteří pracují na dálku?<\/p>","m":["<p>Online dokumentace<\/p>","<p>Formální reporty z testování<\/p>","<p>Videokonference<\/p>","<p>E-mail<\/p>"],"ok":[2],"vys":{"a":"Není správně. Online dokumentace je vhodná pro trvalé informace, ale nezajistí okamžitou pozornost ani diskusi nad naléhavým problémem.","b":"Není správně. Formální reporty z testování vznikají v pravidelných intervalech a na naléhavé problémy jsou příliš pomalé.","c":"Je správně. Videokonference je ústní komunikace v reálném čase, která i na dálku umožňuje problém okamžitě prodiskutovat a domluvit další postup.","d":"Není správně. E-mail je asynchronní; příjemce si ho nemusí přečíst včas a neumožňuje okamžitou diskusi."},"obecne":"Sylabus 5.3.3 uvádí jako možnosti komunikace stavu testování mj. ústní komunikaci, dashboardy, elektronické komunikační kanály (e-mail, chat), online dokumentaci a formální reporty z testování. Pro naléhavé problémy, které je třeba hned prodiskutovat se vzdálenými členy týmu, je nejvhodnější ústní komunikace v reálném čase, tedy videokonference.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.3.3","nazev":"Komunikování stavu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-tri-komunikovani-stavu-testovani"}},{"id":"UP-6-38","n":null,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Provádíte systémové testování systému pro rezervaci vlakových jízdenek a zjistili jste, že systém občas hlásí, že nejsou k dispozici žádné vlaky, ačkoli podle testovacích případů, které jste spustili, by k dispozici být měly. Vedoucímu vývoje jste poskytli shrnutí defektu a verzi testovaného systému. Vývojáři si uvědomují naléhavost defektu a nyní čekají, až jim poskytnete další podrobnosti, aby ho mohli opravit.<\/p><p>Jsou dány následující informace:<\/p><ol><li><p>Míra dopadu (závažnost) defektu<\/p><\/li><li><p>Identifikace položky testování<\/p><\/li><li><p>Podrobnosti o testovacím prostředí<\/p><\/li><li><p>Naléhavost/priorita opravy<\/p><\/li><li><p>Skutečné výsledky<\/p><\/li><li><p>Odkaz na specifikaci testovacího případu<\/p><\/li><\/ol><p>Které z těchto informací by bylo kromě popisu defektu, který obsahuje výpis databáze a snímky obrazovky, NEJUŽITEČNĚJŠÍ uvést v prvotním reportu o defektu?<\/p>","m":["<p>1, 2, 6<\/p>","<p>1, 4, 5, 6<\/p>","<p>2, 3, 4, 5<\/p>","<p>3, 5, 6<\/p>"],"ok":[3],"vys":{"a":"Není správně. Závažnost (1) i identifikaci položky testování (2) už vývojáři znají; chybí podrobnosti o prostředí (3) a skutečné výsledky (5).","b":"Není správně. Závažnost (1) a priorita (4) jsou vývojářům známé – naléhavost defektu už sami uznali; chybí podrobnosti o testovacím prostředí (3).","c":"Není správně. Identifikace položky (2) a priorita (4) jsou již známé; chybí odkaz na specifikaci testovacího případu (6) se vstupy a očekávanými výsledky.","d":"Je správně. Podrobnosti o testovacím prostředí, skutečné výsledky a odkaz na testovací případ (vstupy a očekávané výsledky) vývojářům nejvíce pomohou občasné selhání reprodukovat a opravit."},"obecne":"Sylabus 5.5: Report o defektu má poskytnout dostatek informací k vyřešení problému. Vývojáři už znají verzi systému (identifikaci položky testování) a defekt považují za naléhavý, takže závažnost a priorita pro ně nejsou nové. K reprodukci občasného selhání nejvíce potřebují podrobnosti o testovacím prostředí (3), skutečné výsledky (5) a odkaz na testovací případ se vstupy a očekávanými výsledky (6).","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UP-6-39","n":null,"lo":"FL-6.1.1","k":"K2","k3":true,"vyber":1,"q":"<p>Jsou dány následující popisy:<\/p><ol><li>Testování výkonnosti a zátěžové testování<\/li><li>Podpora pipeline dodávání a CI/CD<\/li><li>Vytváření testovacích případů a testovacích dat<\/li><li>Podpora managementu defektů a konfiguračního managementu<\/li><\/ol><p>A následující kategorie testovacích nástrojů:<\/p><p>A. Nástroje pro management testování<br>B. Nástroje pro návrh a implementaci testů<br>C. Nástroje pro nefunkcionální testování<br>D. Nástroje DevOps<\/p><p>Která z následujících možností NEJLÉPE přiřazuje popisy ke kategoriím nástrojů?<\/p>","m":["<p>1A, 2B, 3C, 4D<\/p>","<p>1B, 2D, 3C, 4A<\/p>","<p>1C, 2D, 3B, 4A<\/p>","<p>1D, 2C, 3A, 4B<\/p>"],"ok":[2],"vys":{"a":"Není správně. Testování výkonnosti nepodporují nástroje pro management testování a CI/CD nepodporují nástroje pro návrh testů.","b":"Není správně. Testování výkonnosti nepodporují nástroje pro návrh a implementaci testů.","c":"Je správně. 1C, 2D, 3B a 4A odpovídá kategoriím nástrojů v sylabu 6.1.","d":"Není správně. Žádné z přiřazení neodpovídá sylabu."},"obecne":"Sylabus 6.1: nástroje pro nefunkcionální testování umožňují např. zátěžové testování, nástroje DevOps podporují pipeline a CI/CD, nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů a dat a nástroje pro management testování usnadňují správu defektů a konfigurací.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"}},{"id":"UP-6-40","n":null,"lo":"FL-6.2.1","k":"K1","k3":true,"vyber":1,"q":"<p>Která z následujících možností je NEJPRAVDĚPODOBNĚJI rizikem automatizace testů?<\/p>","m":["<p>Podstatně kratší doba provádění testů<\/p>","<p>Nástroj pro provádění testů může vyžadovat časté aktualizace<\/p>","<p>Více času pro testery na návrh nových a hlubších testů<\/p>","<p>Odhalení dalších defektů s vysokou závažností<\/p>"],"ok":[1],"vys":{"a":"Není správně. Kratší doba provádění testů je přínosem automatizace.","b":"Je správně. Závislost na nástroji, který vyžaduje časté aktualizace (např. open source) nebo jehož podpora skončí, je rizikem automatizace.","c":"Není správně. Více času na návrh nových a hlubších testů je přínosem automatizace.","d":"Není správně. Odhalení dalších závažných defektů je přínos, ne riziko."},"obecne":"Sylabus 6.2 uvádí mezi riziky automatizace závislost na dodavateli nástroje a použití open source nástroje, který může být opuštěn nebo jehož komponenty mohou vyžadovat poměrně časté aktualizace.","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":true,"kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"}},{"id":"UC-4-36","n":null,"lo":"FL-4.2.2","k":"K3","k3":true,"vyber":1,"q":"<p>Zahájili jste testování založené na specifikaci. Testovaná funkce <code>nsd(A, B)<\/code> počítá největšího společného dělitele dvou celých čísel A a B, která musí být větší než nula. MAX_INT je největší hodnota, kterou může celočíselná proměnná nabývat.<\/p><p>Byly navrženy tyto testovací případy (TC):<\/p><table><thead><tr><th>TC<\/th><th>A<\/th><th>B<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>2<\/td><td>MAX_INT<\/td><td>MAX_INT<\/td><\/tr><tr><td>3<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>4<\/td><td>0<\/td><td>1<\/td><\/tr><tr><td>5<\/td><td>MAX_INT + 1<\/td><td>1<\/td><\/tr><tr><td>6<\/td><td>1<\/td><td>MAX_INT + 1<\/td><\/tr><\/tbody><\/table><p>Která testovací technika byla NEJPRAVDĚPODOBNĚJI použita k odvození testovacích případů 1 až 6?<\/p>","m":["<p>Dvouhodnotová analýza hraničních hodnot<\/p>","<p>Tříhodnotová analýza hraničních hodnot<\/p>","<p>Rozdělení do tříd ekvivalence<\/p>","<p>Testování dle rozhodovací tabulky<\/p>"],"ok":[0],"vys":{"a":"Je správně. Pro každou proměnnou jsou použity obě hranice platné třídy (1 a MAX_INT) a nejbližší sousedé z neplatných tříd (0 a MAX_INT + 1), což přesně odpovídá dvouhodnotové analýze hraničních hodnot.","b":"Není správně. Tříhodnotová analýza by u každé hranice přidala i druhého souseda uvnitř platné třídy (2 a MAX_INT − 1), ty však v testovacích případech chybí.","c":"Není správně. Při rozdělení do tříd ekvivalence stačí jedna libovolná hodnota z každé třídy; systematický výběr hodnot přesně na hranicích tříd ukazuje na analýzu hraničních hodnot.","d":"Není správně. Testovací případy nevznikly z kombinací podmínek a akcí, ale z hranic rozsahu vstupních hodnot."},"obecne":"<p>Sylabus 4.2.2: u dvouhodnotové analýzy hraničních hodnot jsou položkami pokrytí každá hraniční hodnota a její nejbližší soused z sousední třídy. Platná třída pro A i B je 1 až MAX_INT, takže hraniční hodnoty jsou 1 a MAX_INT a jejich sousedé v neplatných třídách 0 a MAX_INT + 1. Testovací případy 1–6 pokrývají právě tyto čtyři hodnoty pro obě proměnné.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"}},{"id":"UC-4-45","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Letecká společnost nabízí cestujícím povýšení do vyšší třídy podle této rozhodovací tabulky („–“ = akce není relevantní):<\/p><table><thead><tr><th><\/th><th>Pravidlo 1<\/th><th>Pravidlo 2<\/th><th>Pravidlo 3<\/th><th>Pravidlo 4<\/th><\/tr><\/thead><tbody><tr><td><strong>Podmínky<\/strong><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><td>Člen věrnostního programu<\/td><td>Ano<\/td><td>Ano<\/td><td>Ne<\/td><td>Ne<\/td><\/tr><tr><td>Cestovní třída<\/td><td>Business<\/td><td>Ekonomická<\/td><td>Business<\/td><td>Ekonomická<\/td><\/tr><tr><td><strong>Akce<\/strong><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><td>Povýšit do první třídy<\/td><td>Ano<\/td><td>Ne<\/td><td>Ne<\/td><td>Ne<\/td><\/tr><tr><td>Povýšit do business třídy<\/td><td>–<\/td><td>Ano<\/td><td>–<\/td><td>Ne<\/td><\/tr><\/tbody><\/table><p>Jaký je očekávaný výsledek pro každý z následujících testovacích případů?<\/p><p>1 – Člen věrnostního programu, který cestuje v business třídě<\/p><p>2 – Cestující, který není členem věrnostního programu a cestuje v ekonomické třídě<\/p>","m":["<p>1 – povýšit do první třídy; 2 – povýšit do business třídy<\/p>","<p>1 – žádné povýšení nenabízet; 2 – žádné povýšení nenabízet<\/p>","<p>1 – žádné povýšení nenabízet; 2 – povýšit do business třídy<\/p>","<p>1 – povýšit do první třídy; 2 – žádné povýšení nenabízet<\/p>"],"ok":[3],"vys":{"a":"Není správně. Testovací případ 2 odpovídá pravidlu 4, podle kterého se povýšení do business třídy nenabízí.","b":"Není správně. Testovací případ 1 odpovídá pravidlu 1, podle kterého se nabízí povýšení do první třídy.","c":"Není správně. Testovací případ 1 odpovídá pravidlu 1 (povýšení do první třídy) a testovací případ 2 pravidlu 4, které žádné povýšení nenabízí.","d":"Je správně. Testovací případ 1 (člen, business) odpovídá pravidlu 1 – povýšit do první třídy; testovací případ 2 (nečlen, ekonomická) odpovídá pravidlu 4 – žádné povýšení."},"obecne":"<p>Sylabus 4.2.3: každý sloupec rozhodovací tabulky je pravidlo, které pro jednu kombinaci podmínek určuje akce. Testovací případ 1 (člen věrnostního programu, business třída) odpovídá pravidlu 1, testovací případ 2 (nečlen, ekonomická třída) pravidlu 4.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UC-4-46","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Uvažujte následující stavový diagram vypínače:<\/p><svg viewBox=\"0 0 600 290\" width=\"100%\" role=\"img\" aria-label=\"Stavový diagram vypínače se stavy VYPNUTO, ZAPNUTO a PORUCHA\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"sipka-uc446\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"8\" markerHeight=\"8\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"currentColor\"/><\/marker><\/defs><rect x=\"40\" y=\"30\" width=\"140\" height=\"50\" rx=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"110\" y=\"60\" text-anchor=\"middle\" font-family=\"inherit\" font-size=\"14\" fill=\"currentColor\">VYPNUTO<\/text><rect x=\"40\" y=\"220\" width=\"140\" height=\"50\" rx=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"110\" y=\"250\" text-anchor=\"middle\" font-family=\"inherit\" font-size=\"14\" fill=\"currentColor\">ZAPNUTO<\/text><rect x=\"420\" y=\"220\" width=\"140\" height=\"50\" rx=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><text x=\"490\" y=\"250\" text-anchor=\"middle\" font-family=\"inherit\" font-size=\"14\" fill=\"currentColor\">PORUCHA<\/text><line x1=\"85\" y1=\"80\" x2=\"85\" y2=\"218\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sipka-uc446)\"/><text x=\"78\" y=\"155\" text-anchor=\"end\" font-family=\"inherit\" font-size=\"14\" fill=\"currentColor\">zapnout<\/text><line x1=\"135\" y1=\"220\" x2=\"135\" y2=\"82\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sipka-uc446)\"/><text x=\"142\" y=\"155\" text-anchor=\"start\" font-family=\"inherit\" font-size=\"14\" fill=\"currentColor\">vypnout<\/text><line x1=\"180\" y1=\"245\" x2=\"418\" y2=\"245\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sipka-uc446)\"/><text x=\"299\" y=\"236\" text-anchor=\"middle\" font-family=\"inherit\" font-size=\"14\" fill=\"currentColor\">přetížení<\/text><path d=\"M465,220 C445,150 535,150 515,218\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sipka-uc446)\"/><text x=\"490\" y=\"152\" text-anchor=\"middle\" font-family=\"inherit\" font-size=\"14\" fill=\"currentColor\">zapnout<\/text><\/svg><p>Přechody zobrazené v diagramu:<\/p><table><thead><tr><th>Výchozí stav<\/th><th>Událost<\/th><th>Cílový stav<\/th><\/tr><\/thead><tbody><tr><td>VYPNUTO<\/td><td>zapnout<\/td><td>ZAPNUTO<\/td><\/tr><tr><td>ZAPNUTO<\/td><td>vypnout<\/td><td>VYPNUTO<\/td><\/tr><tr><td>ZAPNUTO<\/td><td>přetížení<\/td><td>PORUCHA<\/td><\/tr><tr><td>PORUCHA<\/td><td>zapnout<\/td><td>PORUCHA<\/td><\/tr><\/tbody><\/table><p>Který z následujících přechodů je NEPLATNÝ?<\/p>","m":["<p>Ze stavu PORUCHA do stavu ZAPNUTO<\/p>","<p>Ze stavu PORUCHA do stavu PORUCHA<\/p>","<p>Ze stavu ZAPNUTO do stavu PORUCHA<\/p>","<p>Ze stavu VYPNUTO do stavu ZAPNUTO<\/p>"],"ok":[0],"vys":{"a":"Je správně. Z PORUCHA do ZAPNUTO nevede v diagramu žádný přechod, jde tedy o neplatný přechod.","b":"Není správně. Přechod PORUCHA → PORUCHA je v diagramu zobrazen jako smyčka (událost „zapnout“), je tedy platný.","c":"Není správně. Přechod ZAPNUTO → PORUCHA (událost „přetížení“) je v diagramu zobrazen, je tedy platný.","d":"Není správně. Přechod VYPNUTO → ZAPNUTO (událost „zapnout“) je v diagramu zobrazen, je tedy platný."},"obecne":"<p>Sylabus 4.2.4: stavový diagram zobrazuje pouze platné přechody; každý přechod, který v diagramu (ani ve stavové tabulce) není, je neplatný. Ze stavu PORUCHA vede jen smyčka zpět do stavu PORUCHA, přechod do stavu ZAPNUTO tedy neexistuje.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UC-4-66","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Půjčovna aut rozhoduje o zapůjčení vozu podle této rozhodovací tabulky (A = ano, N = ne, „–“ = na hodnotě podmínky nezáleží):<\/p><table><thead><tr><th><\/th><th>Pravidlo 1<\/th><th>Pravidlo 2<\/th><th>Pravidlo 3<\/th><th>Pravidlo 4<\/th><\/tr><\/thead><tbody><tr><td><strong>Podmínky<\/strong><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><td>Věk nad 20 let?<\/td><td>N<\/td><td>A<\/td><td>A<\/td><td>A<\/td><\/tr><tr><td>Čistý řidičský záznam?<\/td><td>–<\/td><td>N<\/td><td>A<\/td><td>A<\/td><\/tr><tr><td>Služební cesta?<\/td><td>–<\/td><td>–<\/td><td>N<\/td><td>A<\/td><\/tr><tr><td><strong>Akce<\/strong><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><td>Půjčit auto?<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>A<\/td><\/tr><tr><td>Účtovat příplatek?<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><\/tr><\/tbody><\/table><p>Jaký je očekávaný výsledek pro tyto testovací případy?<\/p><p>TC1: 26letý zákazník na služební cestě, který má v řidičském záznamu přestupky nebo nehody<\/p><p>TC2: 62letý turista s čistým řidičským záznamem<\/p>","m":["<p>TC1: auto nepůjčit; TC2: půjčit auto s příplatkem<\/p>","<p>TC1: auto nepůjčit; TC2: půjčit auto bez příplatku<\/p>","<p>TC1: půjčit auto s příplatkem; TC2: půjčit auto bez příplatku<\/p>","<p>TC1: půjčit auto s příplatkem; TC2: auto nepůjčit<\/p>"],"ok":[1],"vys":{"a":"Není správně. TC2 není na služební cestě, odpovídá tedy pravidlu 3, které příplatek neúčtuje.","b":"Je správně. TC1 (nad 20 let, záznam není čistý) odpovídá pravidlu 2 – auto nepůjčit; TC2 (nad 20 let, čistý záznam, není na služební cestě) odpovídá pravidlu 3 – půjčit bez příplatku.","c":"Není správně. TC1 nemá čistý řidičský záznam, odpovídá tedy pravidlu 2 a auto se mu nepůjčí, i když je na služební cestě.","d":"Není správně. Oba výsledky jsou opačně: TC1 odpovídá pravidlu 2 (nepůjčit) a TC2 pravidlu 3 (půjčit bez příplatku)."},"obecne":"<p>Sylabus 4.2.3: pro každý testovací případ se najde pravidlo, jehož podmínky odpovídají vstupům, a očekávaný výsledek se převezme z akcí tohoto pravidla; „–“ znamená, že na hodnotě podmínky nezáleží. TC1 (26 let, záznam není čistý) odpovídá pravidlu 2 – auto nepůjčit. TC2 (62 let, čistý záznam, turista) odpovídá pravidlu 3 – půjčit auto bez příplatku.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UC-5-38","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>K testování účetního systému se používají následující testovací případy (priorita 1 = nejvyšší, 3 = nejnižší). Test může být proveden až po provedení testu, na kterém závisí.<\/p><table><thead><tr><th>ID testu<\/th><th>Název<\/th><th>Závisí na<\/th><th>Priorita<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>Nákup položky<\/td><td>–<\/td><td>2<\/td><\/tr><tr><td>2<\/td><td>Přijetí faktury<\/td><td>test 1<\/td><td>3<\/td><\/tr><tr><td>3<\/td><td>Příjem zboží<\/td><td>test 1<\/td><td>1<\/td><\/tr><tr><td>4<\/td><td>Odeslání platby<\/td><td>test 2<\/td><td>3<\/td><\/tr><tr><td>5<\/td><td>Přehled plateb<\/td><td>test 4<\/td><td>2<\/td><\/tr><\/tbody><\/table><p>Jaké je na základě těchto informací NEJLEPŠÍ pořadí provedení testovacích případů?<\/p>","m":["<p>5, 1, 3, 2, 4<\/p>","<p>3, 4, 5, 1, 2<\/p>","<p>1, 3, 2, 4, 5<\/p>","<p>1, 2, 4, 3, 5<\/p>"],"ok":[2],"vys":{"a":"Není správně. Test 5 závisí na testu 4 (a ten nepřímo na testech 2 a 1), nemůže tedy být proveden jako první.","b":"Není správně. Test 3 závisí na testu 1 a test 4 na testu 2, nemohou tedy být provedeny jako první.","c":"Je správně. Nejprve test 1 (bez závislostí), hned po něm test 3 s nejvyšší prioritou; test 5 (priorita 2) vyžaduje testy 2 a 4, které proto musí proběhnout před ním.","d":"Není správně. Pořadí sice respektuje závislosti, ale test 3 s nejvyšší prioritou je proveden až po testech 2 a 4 s nejnižší prioritou, přestože mohl být proveden hned po testu 1."},"obecne":"<p>Sylabus 5.1.5: testovací případy se v ideálním případě provádějí podle priority, ale pokud test s vyšší prioritou závisí na testu s nižší prioritou, musí být nejdříve proveden test s nižší prioritou. Test 1 nemá závislosti, proto jde první; poté test 3 (priorita 1). Test 5 (priorita 2) závisí přes test 4 na testu 2, proto následují testy 2, 4 a 5. Výsledné pořadí je 1, 3, 2, 4, 5.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UC-5-39","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Jako manažer testování máte otestovat následující požadavky. Sloupec „Závisí na“ uvádí logické závislosti: požadavek lze testovat až po otestování všech požadavků, na kterých závisí.<\/p><table><thead><tr><th>Požadavek<\/th><th>Název<\/th><th>Složitost<\/th><th>Závisí na<\/th><\/tr><\/thead><tbody><tr><td>R1<\/td><td>Anomálie procesu<\/td><td>vysoká<\/td><td>–<\/td><\/tr><tr><td>R2<\/td><td>Vzdálené služby<\/td><td>střední<\/td><td>R1<\/td><\/tr><tr><td>R3<\/td><td>Synchronizace<\/td><td>střední<\/td><td>R1, R2, R5<\/td><\/tr><tr><td>R4<\/td><td>Potvrzení<\/td><td>střední<\/td><td>R1<\/td><\/tr><tr><td>R5<\/td><td>Uzavírání procesů<\/td><td>nízká<\/td><td>R4<\/td><\/tr><tr><td>R6<\/td><td>Problémy<\/td><td>nízká<\/td><td>R3, R7, R8<\/td><\/tr><tr><td>R7<\/td><td>Finanční data<\/td><td>nízká<\/td><td>R3<\/td><\/tr><tr><td>R8<\/td><td>Data diagramu<\/td><td>nízká<\/td><td>R3<\/td><\/tr><tr><td>R9<\/td><td>Změny uživatelského profilu<\/td><td>střední<\/td><td>R3, R7, R8<\/td><\/tr><\/tbody><\/table><p>Jak byste uspořádali harmonogram provedení testů, aby respektoval závislosti požadavků?<\/p>","m":["<p>R1 &gt; R2 &gt; R3 &gt; R7 &gt; R8 &gt; R4 &gt; R5 &gt; R6 &gt; R9<\/p>","<p>R4 &gt; R5 &gt; R1 &gt; R2 &gt; R3 &gt; R7 &gt; R8 &gt; R6 &gt; R9<\/p>","<p>R1 &gt; R2 &gt; R3 &gt; R4 &gt; R5 &gt; R7 &gt; R8 &gt; R6 &gt; R9<\/p>","<p>R1 &gt; R2 &gt; R4 &gt; R5 &gt; R3 &gt; R7 &gt; R8 &gt; R6 &gt; R9<\/p>"],"ok":[3],"vys":{"a":"Není správně. R3 je testován dříve než R4 a R5, přestože na R5 závisí.","b":"Není správně. R4 závisí na R1, nemůže tedy být testován jako první.","c":"Není správně. R3 závisí na R5 (a ten na R4), nemůže tedy být testován před R4 a R5.","d":"Je správně. Každý požadavek je v tomto pořadí testován až po všech požadavcích, na kterých závisí."},"obecne":"<p>Sylabus 5.1.5: pořadí provedení testů musí respektovat závislosti – test, na kterém jiný test závisí, musí být proveden dříve. Pouze pořadí R1 &gt; R2 &gt; R4 &gt; R5 &gt; R3 &gt; R7 &gt; R8 &gt; R6 &gt; R9 splňuje všechny závislosti z tabulky; složitost požadavků na pořadí v této otázce vliv nemá.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UC-5-41","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Máte za úkol uspořádat sadu testovacích případů do testovací procedury, která určí pořadí jejich spuštění. Pořadí je důležité, protože v aplikaci e-shopu s knihami chcete otestovat end-to-end transakce, a zároveň musíte zohlednit prioritu testovacích případů, protože některé jsou kritičtější než jiné (priorita rizika 1 = nejvyšší riziko). Testovací případ lze v proceduře v případě potřeby spustit opakovaně.<\/p><table><thead><tr><th>Testovací případ<\/th><th>Testovaná funkce<\/th><th>Priorita rizika<\/th><th>Závisí na funkci<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>Procházení katalogu<\/td><td>2<\/td><td>–<\/td><\/tr><tr><td>2<\/td><td>Výběr knihy<\/td><td>3<\/td><td>Procházení katalogu<\/td><\/tr><tr><td>3<\/td><td>Výběr knihy<\/td><td>2<\/td><td>Procházení katalogu<\/td><\/tr><tr><td>4<\/td><td>Nákupní košík<\/td><td>1<\/td><td>Výběr knihy<\/td><\/tr><tr><td>5<\/td><td>Nákupní košík<\/td><td>3<\/td><td>Výběr knihy<\/td><\/tr><tr><td>6<\/td><td>Dokončení nákupu<\/td><td>1<\/td><td>Nákupní košík<\/td><\/tr><tr><td>7<\/td><td>Vrácení peněz<\/td><td>4<\/td><td>Dokončení nákupu<\/td><\/tr><\/tbody><\/table><p>Jaké pořadí provedení NEJLÉPE splňuje oba cíle?<\/p>","m":["<p>1, 3, 4, 6, 1, 2, 5, 6, 7<\/p>","<p>1, 2, 5, 6, 7, 1, 3, 4, 6, 7<\/p>","<p>4, 6, 1, 3, 2, 5, 7<\/p>","<p>1, 3, 2, 4, 5, 6, 7<\/p>"],"ok":[0],"vys":{"a":"Je správně. První transakce (1, 3, 4, 6) co nejdříve pokryje nejrizikovější případy 4 a 6, druhá transakce (1, 2, 5, 6, 7) dokončí zbývající případy včetně vrácení peněz.","b":"Není správně. Pořadí sice tvoří dvě end-to-end transakce, ale nejprve testuje transakci s nižším rizikem (2, 5) a vysoce rizikové případy 4 a 6 odkládá.","c":"Není správně. Testovací případy 4 a 6 nelze spustit dříve než procházení katalogu a výběr knihy, na kterých závisí.","d":"Není správně. Pořadí respektuje závislosti, ale netvoří end-to-end transakce a test 2 s prioritou 3 předřazuje testu 4 s prioritou 1."},"obecne":"<p>Sylabus 5.1.5: testovací případy se řadí podle priority (zde podle rizika), ale je nutné respektovat závislosti. Aby bylo nejvyšší riziko pokryto co nejdříve a zároveň vznikaly celé transakce, proběhne nejprve transakce s nejrizikovějšími případy 1, 3, 4, 6 a poté transakce 1, 2, 5, 6, 7 se zbývajícími případy (procházení a dokončení nákupu se opakují).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UC-5-43","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Dostali jste ke spuštění následující sadu testovacích případů. Máte je spouštět v pořadí podle rizika a provést testování co nejrychleji, abyste vývojářům co nejdříve poskytli zpětnou vazbu. Testovací případ lze spustit až po testovacím případu, na kterém závisí.<\/p><table><thead><tr><th>ID testovacího případu<\/th><th>Doba trvání<\/th><th>Priorita rizika<\/th><th>Závisí na<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>30 min<\/td><td>nízká<\/td><td>6<\/td><\/tr><tr><td>2<\/td><td>10 min<\/td><td>střední<\/td><td>–<\/td><\/tr><tr><td>3<\/td><td>45 min<\/td><td>vysoká<\/td><td>1<\/td><\/tr><tr><td>4<\/td><td>30 min<\/td><td>vysoká<\/td><td>2<\/td><\/tr><tr><td>5<\/td><td>10 min<\/td><td>střední<\/td><td>4<\/td><\/tr><tr><td>6<\/td><td>15 min<\/td><td>nízká<\/td><td>2<\/td><\/tr><\/tbody><\/table><p>Jaké je na základě těchto informací NEJLEPŠÍ pořadí spuštění testů?<\/p>","m":["<p>6, 1, 3, 2, 4, 5<\/p>","<p>2, 4, 5, 6, 1, 3<\/p>","<p>4, 3, 2, 5, 6, 1<\/p>","<p>2, 5, 6, 4, 1, 3<\/p>"],"ok":[1],"vys":{"a":"Není správně. Test 6 závisí na testu 2, nemůže tedy být spuštěn jako první.","b":"Je správně. Jako jediné respektuje všechny závislosti a vždy spouští test s nejvyšším rizikem z těch, které už lze spustit (2, pak 4, pak 5, a nakonec řetězec 6, 1, 3).","c":"Není správně. Test 4 závisí na testu 2, nemůže tedy být spuštěn jako první.","d":"Není správně. Test 5 závisí na testu 4, nemůže tedy být spuštěn před ním."},"obecne":"<p>Sylabus 5.1.5: testovací případy se řadí podle priority (zde podle rizika), ale závislosti mají přednost – test, na kterém jiný test závisí, musí proběhnout dříve. Jako první lze spustit pouze test 2; poté test 4 (vysoké riziko), následně test 5 a nakonec řetězec 6 → 1 → 3, protože vysoce rizikový test 3 vyžaduje testy 6 a 1. Pořadí 2, 4, 5, 6, 1, 3 je jediné z nabízených, které všechny závislosti splňuje.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UP-1-33","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Jako manažer testování odpovídáte za otestování následujících požadavků:<\/p><ul><li>R1 – Anomálie procesu (vysoká složitost)<\/li><li>R2 – Vzdálené služby (střední složitost)<\/li><li>R3 – Synchronizace (střední složitost)<\/li><li>R4 – Potvrzení (střední složitost)<\/li><li>R5 – Uzavření procesu (nízká složitost)<\/li><li>R6 – Problémy (nízká složitost)<\/li><li>R7 – Finanční data (nízká složitost)<\/li><li>R8 – Data diagramů (nízká složitost)<\/li><li>R9 – Změny uživatelského profilu (střední složitost)<\/li><\/ul><p>Mezi požadavky existují tyto logické závislosti (testy požadavku lze provést až po otestování všech požadavků, na kterých závisí):<\/p><ul><li>R2 závisí na R1.<\/li><li>R4 závisí na R1.<\/li><li>R5 závisí na R4.<\/li><li>R3 závisí na R2 a na R5.<\/li><li>R7 a R8 závisí na R3.<\/li><li>R6 a R9 závisí na R3, R7 a R8 (tj. na dokončení celé skupiny R3, R7, R8).<\/li><\/ul><p>Které z následujících pořadí harmonogramu provedení testů respektuje závislosti mezi požadavky?<\/p>","m":["<p>R4 → R5 → R1 → R2 → R3 → R7 → R8 → R6 → R9<\/p>","<p>R1 → R2 → R3 → R4 → R5 → R7 → R8 → R6 → R9<\/p>","<p>R1 → R2 → R4 → R5 → R3 → R7 → R8 → R6 → R9<\/p>","<p>R1 → R2 → R3 → R7 → R8 → R4 → R5 → R6 → R9<\/p>"],"ok":[2],"vys":{"a":"Není správně. R4 závisí na R1, nemůže se proto testovat jako první.","b":"Není správně. R3 závisí na R5 (a ten na R4), R3 se tedy nesmí testovat před R4 a R5.","c":"Je správně. Každý požadavek je zařazen až po všech požadavcích, na kterých závisí.","d":"Není správně. R3, R7 a R8 jsou zařazeny před R4 a R5, ačkoli R3 na R5 (a nepřímo na R4) závisí."},"obecne":"<p>Sylabus 5.1.5: Při sestavování harmonogramu provedení testů je nutné respektovat závislosti – test, který závisí na jiném, se provede až po něm. Začít lze jen R1 (na ničem nezávisí), následuje R2 a větev R4 → R5; teprve poté R3, pak R7 a R8 a nakonec R6 a R9. Tomu odpovídá pouze pořadí R1, R2, R4, R5, R3, R7, R8, R6, R9.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UP-2-23","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Je dán následující stavový diagram internetového obchodu:<\/p><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 180\" width=\"100%\" role=\"img\" aria-label=\"Stavový diagram e-shopu se stavy PŘIHLÁŠENÍ, PROCHÁZENÍ, KOŠÍK, POKLADNA, PLATBA a ODHLÁŠENÍ; přechody jsou vypsány pod diagramem.\" font-family=\"inherit\"><defs><marker id=\"sip-up223\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"currentColor\"/><\/marker><\/defs><circle cx=\"8\" cy=\"100\" r=\"5\" fill=\"currentColor\"/><path d=\"M13,100 L24,100\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up223)\"/><rect x=\"26\" y=\"82\" width=\"96\" height=\"36\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"74\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">PŘIHLÁŠENÍ<\/text><rect x=\"128\" y=\"82\" width=\"96\" height=\"36\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"176\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">PROCHÁZENÍ<\/text><rect x=\"230\" y=\"82\" width=\"96\" height=\"36\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"278\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">KOŠÍK<\/text><rect x=\"332\" y=\"82\" width=\"96\" height=\"36\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"380\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">POKLADNA<\/text><rect x=\"434\" y=\"82\" width=\"96\" height=\"36\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"482\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">PLATBA<\/text><rect x=\"536\" y=\"82\" width=\"96\" height=\"36\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><rect x=\"540\" y=\"86\" width=\"88\" height=\"28\" rx=\"7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"584\" y=\"105\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">ODHLÁŠENÍ<\/text><path d=\"M94,82 Q125,30 156,80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up223)\"/><text x=\"125\" y=\"48\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">A<\/text><path d=\"M196,82 Q227,30 258,80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up223)\"/><text x=\"227\" y=\"48\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">B<\/text><path d=\"M298,82 Q329,30 360,80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up223)\"/><text x=\"329\" y=\"48\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">D<\/text><path d=\"M400,82 Q431,30 462,80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up223)\"/><text x=\"431\" y=\"48\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">F<\/text><path d=\"M502,82 Q533,30 564,80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up223)\"/><text x=\"533\" y=\"48\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">G<\/text><path d=\"M258,118 Q227,170 196,120\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up223)\"/><text x=\"227\" y=\"162\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">C<\/text><path d=\"M360,118 Q329,170 298,120\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up223)\"/><text x=\"329\" y=\"162\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">E<\/text><\/svg><p>Počáteční stav je PŘIHLÁŠENÍ, koncový stav je ODHLÁŠENÍ. Diagram obsahuje tyto přechody:<\/p><ul><li>A: PŘIHLÁŠENÍ → PROCHÁZENÍ<\/li><li>B: PROCHÁZENÍ → KOŠÍK<\/li><li>C: KOŠÍK → PROCHÁZENÍ<\/li><li>D: KOŠÍK → POKLADNA<\/li><li>E: POKLADNA → KOŠÍK<\/li><li>F: POKLADNA → PLATBA<\/li><li>G: PLATBA → ODHLÁŠENÍ<\/li><\/ul><p>Která z následujících posloupností stavů obsahuje NEPLATNÝ přechod, který může ukazovat na defekt v návrhu systému?<\/p>","m":["<p>PŘIHLÁŠENÍ, PROCHÁZENÍ, KOŠÍK, POKLADNA, PLATBA, ODHLÁŠENÍ<\/p>","<p>PŘIHLÁŠENÍ, PROCHÁZENÍ, KOŠÍK, PROCHÁZENÍ, KOŠÍK, POKLADNA, PLATBA, ODHLÁŠENÍ<\/p>","<p>PŘIHLÁŠENÍ, PROCHÁZENÍ, KOŠÍK, POKLADNA, KOŠÍK, POKLADNA, PLATBA, ODHLÁŠENÍ<\/p>","<p>PŘIHLÁŠENÍ, PROCHÁZENÍ, KOŠÍK, POKLADNA, KOŠÍK, ODHLÁŠENÍ<\/p>"],"ok":[3],"vys":{"a":"Není správně. Posloupnost odpovídá přechodům A, B, D, F, G – jde o základní platnou cestu.","b":"Není správně. Posloupnost odpovídá přechodům A, B, C, B, D, F, G – všechny existují.","c":"Není správně. Posloupnost odpovídá přechodům A, B, D, E, D, F, G – všechny existují.","d":"Je správně. Ze stavu KOŠÍK nevede žádný přechod do stavu ODHLÁŠENÍ, poslední krok je tedy neplatný přechod."},"obecne":"<p>Sylabus 4.2.4: Platné přechody jsou ty, které stavový diagram zobrazuje; přechod, který v diagramu chybí, je neplatný. Do stavu ODHLÁŠENÍ vede jediný přechod G, a to ze stavu PLATBA. Posloupnost končící krokem KOŠÍK → ODHLÁŠENÍ proto obsahuje neplatný přechod.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UP-2-32","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Máte za úkol uspořádat sadu testovacích případů do testovací procedury, která určí pořadí jejich provedení v e-shopu s knihami. Chcete testovat ucelené transakce od začátku do konce (end-to-end) a zároveň zohlednit prioritu rizika – některé testovací případy jsou kritičtější než jiné (1 = nejvyšší riziko). Testovací případ lze spustit, jen pokud v téže transakci před ním proběhl test typu, na kterém závisí; kvůli další transakci lze testovací případ spustit opakovaně.<\/p><table><thead><tr><th>Testovací případ<\/th><th>Typ testu<\/th><th>Priorita rizika<\/th><th>Závisí na typu testu<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>Procházení<\/td><td>2<\/td><td>–<\/td><\/tr><tr><td>2<\/td><td>Výběr<\/td><td>3<\/td><td>Procházení<\/td><\/tr><tr><td>3<\/td><td>Výběr<\/td><td>2<\/td><td>Procházení<\/td><\/tr><tr><td>4<\/td><td>Nákupní košík<\/td><td>1<\/td><td>Výběr<\/td><\/tr><tr><td>5<\/td><td>Nákupní košík<\/td><td>3<\/td><td>Výběr<\/td><\/tr><tr><td>6<\/td><td>Nákup<\/td><td>1<\/td><td>Nákupní košík<\/td><\/tr><tr><td>7<\/td><td>Vrácení peněz<\/td><td>4<\/td><td>Nákup<\/td><\/tr><\/tbody><\/table><p>Které pořadí provedení NEJLÉPE splňuje oba cíle?<\/p>","m":["<p>1, 3, 4, 6, 1, 2, 5, 6, 7<\/p>","<p>4, 6, 1, 3, 2, 5, 7<\/p>","<p>1, 3, 2, 4, 5, 6, 7<\/p>","<p>1, 2, 5, 6, 7, 1, 3, 4, 6, 7<\/p>"],"ok":[0],"vys":{"a":"Je správně. První transakce 1, 3, 4, 6 co nejdříve pokryje testy s nejvyšším rizikem (4 a 6), druhá transakce 1, 2, 5, 6, 7 doplní zbývající testy.","b":"Není správně. Testy 4 a 6 nelze spustit jako první – nejprve musí proběhnout procházení, výběr a (pro test 6) nákupní košík.","c":"Není správně. Závislosti jsou sice dodrženy, ale před nejrizikovější testy 4 a 6 se zařazují méně rizikové testy 2 a 5 a transakce nejsou ucelené.","d":"Není správně. Závislosti jsou dodrženy, ale nejrizikovější testy 4 a 6 se provádějí až ve druhé transakci."},"obecne":"<p>Sylabus 5.1.5: Testovací případy se řadí podle priority (zde rizika) s ohledem na závislosti. Nejrizikovější jsou testy 4 a 6; test 6 vyžaduje nákupní košík (4), ten výběr (3 má vyšší prioritu než 2) a ten procházení (1). První transakce je tedy 1, 3, 4, 6. Zbývající testy 2, 5 a 7 pokryje druhá transakce 1, 2, 5, 6, 7 (vrácení peněz vyžaduje předchozí nákup).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UP-3-22","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Je dána následující rozhodovací tabulka pojištění:<\/p><table><thead><tr><th><\/th><th>Pravidlo 1<\/th><th>Pravidlo 2<\/th><th>Pravidlo 3<\/th><th>Pravidlo 4<\/th><\/tr><\/thead><tbody><tr><th colspan=\"5\">Podmínky<\/th><\/tr><tr><td>Věk pojištěnce<\/td><td>méně než 21 let<\/td><td>21–29 let<\/td><td>30–50 let<\/td><td>více než 50 let<\/td><\/tr><tr><td>Pojistná třída<\/td><td>A<\/td><td>A nebo B<\/td><td>B, C nebo D<\/td><td>C nebo D<\/td><\/tr><tr><th colspan=\"5\">Akce<\/th><\/tr><tr><td>Pojistné (Kč)<\/td><td>100<\/td><td>90<\/td><td>70<\/td><td>70<\/td><\/tr><tr><td>Spoluúčast (Kč)<\/td><td>2 500<\/td><td>2 500<\/td><td>500<\/td><td>1 000<\/td><\/tr><\/tbody><\/table><p>Který z následujících testovacích případů s očekávaným výsledkem je PLATNÝ?<\/p>","m":["<p>43letý pojištěnec v pojistné třídě C: pojistné 70 Kč, spoluúčast 1 000 Kč<\/p>","<p>23letý pojištěnec v pojistné třídě A: pojistné 90 Kč, spoluúčast 2 500 Kč<\/p>","<p>31letý pojištěnec v pojistné třídě B: pojistné 90 Kč, spoluúčast 2 500 Kč<\/p>","<p>51letý pojištěnec v pojistné třídě C: pojistné 70 Kč, spoluúčast 500 Kč<\/p>"],"ok":[1],"vys":{"a":"Není správně. 43 let a třída C odpovídá pravidlu 3, spoluúčast má být 500 Kč, ne 1 000 Kč.","b":"Je správně. 23 let a třída A odpovídá pravidlu 2: pojistné 90 Kč a spoluúčast 2 500 Kč.","c":"Není správně. 31 let a třída B odpovídá pravidlu 3: pojistné 70 Kč a spoluúčast 500 Kč.","d":"Není správně. 51 let a třída C odpovídá pravidlu 4, spoluúčast má být 1 000 Kč, ne 500 Kč."},"obecne":"<p>Sylabus 4.2.3: Každý sloupec rozhodovací tabulky je pravidlo – kombinace podmínek s odpovídajícími akcemi. Testovací případ je platný, pokud jeho vstupy spadají do některého pravidla a očekávaný výsledek odpovídá akcím tohoto pravidla. To splňuje jen 23letý pojištěnec ve třídě A (pravidlo 2).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UP-3-23","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Je dán následující stavový diagram:<\/p><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"-80 0 640 225\" width=\"100%\" role=\"img\" aria-label=\"Stavový diagram se stavy S0, S1 a S2; přechody jsou vypsány pod diagramem.\" font-family=\"inherit\"><defs><marker id=\"sip-up323\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"currentColor\"/><\/marker><\/defs><rect x=\"30\" y=\"90\" width=\"100\" height=\"40\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"80\" y=\"115\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">S0<\/text><rect x=\"190\" y=\"90\" width=\"100\" height=\"40\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"240\" y=\"115\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">S1<\/text><rect x=\"350\" y=\"90\" width=\"100\" height=\"40\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"400\" y=\"115\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">S2<\/text><path d=\"M100,90 Q160,35 218,88\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up323)\"/><text x=\"160\" y=\"52\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">A<\/text><path d=\"M260,90 Q320,35 378,88\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up323)\"/><text x=\"320\" y=\"52\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">B<\/text><path d=\"M220,130 Q160,180 102,132\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up323)\"/><text x=\"160\" y=\"175\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">D<\/text><path d=\"M400,130 Q240,250 67,132\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up323)\"/><text x=\"240\" y=\"208\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">C<\/text><circle cx=\"8\" cy=\"110\" r=\"5\" fill=\"currentColor\"/><path d=\"M13,110 L28,110\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up323)\"/><\/svg><p>Přechody: událost A vede ze S0 do S1, událost B ze S1 do S2, událost C ze S2 do S0 a událost D ze S1 do S0.<\/p><p>Která posloupnost událostí pokryje tuto posloupnost stavů: S1, S0, S1, S2, S0?<\/p>","m":["<p>A, B, C, D<\/p>","<p>D, A, B<\/p>","<p>D, A, B, C<\/p>","<p>A, B, C<\/p>"],"ok":[2],"vys":{"a":"Není správně. Ze stavu S1 nelze začít událostí A – ta vede jen ze S0.","b":"Není správně. Tři události skončí ve stavu S2, chybí poslední přechod C do S0.","c":"Je správně. D (S1 → S0), A (S0 → S1), B (S1 → S2), C (S2 → S0).","d":"Není správně. Ze stavu S1 nelze začít událostí A a posloupnost má navíc o přechod méně."},"obecne":"<p>Sylabus 4.2.4: Testovací případ ve stavovém diagramu je posloupnost událostí, které vyvolají přechody mezi stavy. Ze S1 do S0 vede D, ze S0 do S1 A, ze S1 do S2 B a ze S2 do S0 C, tedy D, A, B, C.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UP-3-24","n":null,"lo":"FL-4.3.2","k":"K2","k3":true,"vyber":1,"q":"<p>Je dán následující graf řídicího toku modulu:<\/p><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"-140 0 640 350\" width=\"100%\" role=\"img\" aria-label=\"Graf řídicího toku s uzly A až G; hrany jsou vypsány pod grafem.\" font-family=\"inherit\"><defs><marker id=\"sip-up324\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"currentColor\"/><\/marker><\/defs><rect x=\"175\" y=\"10\" width=\"50\" height=\"30\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"200\" y=\"30\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">A<\/text><rect x=\"95\" y=\"70\" width=\"50\" height=\"30\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"120\" y=\"90\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">B<\/text><rect x=\"255\" y=\"70\" width=\"50\" height=\"30\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"280\" y=\"90\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">C<\/text><rect x=\"175\" y=\"130\" width=\"50\" height=\"30\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"200\" y=\"150\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">D<\/text><rect x=\"255\" y=\"190\" width=\"50\" height=\"30\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"280\" y=\"210\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">E<\/text><rect x=\"255\" y=\"250\" width=\"50\" height=\"30\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"280\" y=\"270\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">F<\/text><rect x=\"175\" y=\"310\" width=\"50\" height=\"30\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"200\" y=\"330\" text-anchor=\"middle\" font-size=\"14\" fill=\"currentColor\">G<\/text><path d=\"M200,40 L122,68\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up324)\"/><path d=\"M200,40 L278,68\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up324)\"/><path d=\"M120,100 L198,128\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up324)\"/><path d=\"M280,100 L202,128\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up324)\"/><path d=\"M200,160 L278,188\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up324)\"/><path d=\"M280,220 L280,248\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up324)\"/><path d=\"M280,280 L202,308\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up324)\"/><path d=\"M200,160 L200,308\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up324)\"/><\/svg><p>Graf obsahuje tyto hrany (větve): A→B, A→C, B→D, C→D, D→E, E→F, F→G a D→G. Uzly A a D jsou rozhodnutí.<\/p><p>Modul byl otestován jediným testovacím případem, který prošel cestou A, B, D, E, F, G. Jakého pokrytí větví bylo dosaženo?<\/p>","m":["<p>50 %<\/p>","<p>62,5 %<\/p>","<p>85,7 %<\/p>","<p>100 %<\/p>"],"ok":[1],"vys":{"a":"Není správně. 50 % (2 ze 4) je podíl pokrytých výstupů rozhodnutí; pokrytí větví však počítá všechny hrany grafu.","b":"Je správně. Cesta provede 5 z 8 větví (A→B, B→D, D→E, E→F, F→G), tedy 5/8 = 62,5 %.","c":"Není správně. 85,7 % (6 ze 7) je podíl provedených uzlů, tedy pokrytí příkazů, nikoli větví.","d":"Není správně. Neprovedené zůstaly větve A→C, C→D a D→G."},"obecne":"<p>Sylabus 4.3.2: Větev je přenos řízení mezi dvěma uzly grafu řídicího toku (podmíněný i nepodmíněný). Pokrytí větví = počet provedených větví / celkový počet větví. Graf má 8 větví, testovací případ provede 5 z nich, pokrytí větví je tedy 62,5 %.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"}},{"id":"UP-3-27","n":null,"lo":"FL-5.1.5","k":"K3","k3":true,"vyber":1,"q":"<p>Následující tabulka uvádí 6 testovacích procedur (P až U), které je třeba zařadit do harmonogramu provedení testů. Pro pořadí je nejdůležitější byznysová priorita, ale je nutné zohlednit i další závislosti. Regresní testování lze spustit až po dokončení všech ostatních testů.<\/p><table><thead><tr><th>Testovací procedura<\/th><th>Byznysová priorita (1 vysoká, 2 střední, 3 nízká)<\/th><th>Závislost na jiných procedurách<\/th><th>Jiné závislosti<\/th><\/tr><\/thead><tbody><tr><td>P<\/td><td>3<\/td><td>žádná<\/td><td>Dodávka kódu pro tuto část systému má velké zpoždění<\/td><\/tr><tr><td>Q<\/td><td>1<\/td><td>žádná<\/td><td>Pouze regresní testování<\/td><\/tr><tr><td>R<\/td><td>1<\/td><td>Vyžaduje předchozí provedení S<\/td><td>žádné<\/td><\/tr><tr><td>S<\/td><td>2<\/td><td>žádná<\/td><td>žádné<\/td><\/tr><tr><td>T<\/td><td>2<\/td><td>žádná<\/td><td>Pouze regresní testování<\/td><\/tr><tr><td>U<\/td><td>3<\/td><td>žádná<\/td><td>žádné<\/td><\/tr><\/tbody><\/table><p>Které z následujících pořadí je pro harmonogram provedení testů NEJÚČINNĚJŠÍ (první položka se provede jako první, druhá jako druhá atd.)?<\/p>","m":["<p>S, R, U, P, Q, T<\/p>","<p>Q, R, S, T, P, U<\/p>","<p>S, R, P, U, Q, T<\/p>","<p>R, Q, S, T, U, P<\/p>"],"ok":[0],"vys":{"a":"Je správně. Nejprve S a R (R vyžaduje S, R má prioritu 1), pak U a P (P až kvůli zpožděnému kódu), nakonec regresní Q a T podle priority.","b":"Není správně. Regresní procedury Q a T jsou zařazeny před ostatní testy a R je před S.","c":"Není správně. Procedura P je zařazena před U, ačkoli dodávka kódu pro P má velké zpoždění a obě mají stejnou prioritu.","d":"Není správně. R nelze provést před S a regresní procedury Q a T nesmějí předcházet ostatním testům."},"obecne":"<p>Sylabus 5.1.5: Testy se řadí podle priority, ale s ohledem na závislosti. Regresní procedury Q a T přijdou na konec (Q před T podle priority). Z ostatních má nejvyšší prioritu R, která vyžaduje S, proto S, R. Z procedur s nízkou prioritou se U provede před P, jejíž kód bude dodán pozdě. Výsledné pořadí: S, R, U, P, Q, T.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"}},{"id":"UP-3-32","n":null,"lo":"FL-5.5.1","k":"K3","k3":true,"vyber":1,"q":"<p>Čtyři testeři podali každý report o defektu, v němž popsali problém s přihlášením uživatele. Přihlášení uživatele je kritickou komponentou systému. Následující tabulka shrnuje čtyři podané reporty o defektu:<\/p><table><thead><tr><th>Tester<\/th><th>Popis incidentu<\/th><th>Vstupy / očekávaný a skutečný výsledek<\/th><th>Byznysová priorita (1 vysoká, 2 střední, 3 nízká)<\/th><\/tr><\/thead><tbody><tr><td>Tester 1<\/td><td>Chyba ověření při přihlášení uživatele<\/td><td>Zadal jsem uživatele J SMITH a heslo ABC01, ale dostal jsem chybové hlášení.<\/td><td>1<\/td><\/tr><tr><td>Tester 2<\/td><td>Přihlášení nesplňuje požadavek<\/td><td>Vstupy: zadáno platné uživatelské jméno a heslo.<br>Očekávaný výsledek: zobrazí se hlavní nabídka.<br>Skutečný výsledek: chyba „nesprávné heslo“.<\/td><td>2<\/td><\/tr><tr><td>Tester 3<\/td><td>Chyba ověření hesla při přihlášení<\/td><td>Vstupy: uživatel = J SMITH, heslo = ABC01.<br>Očekávaný výsledek: hlavní nabídka.<br>Skutečný výsledek: chybové hlášení EM008 „Neplatné heslo“.<br>Tento test už mnohokrát prošel.<\/td><td>2<\/td><\/tr><tr><td>Tester 4<\/td><td>Chyba ověření hesla<\/td><td>Vstupy: uživatel = J SMITH, heslo = ABC01.<br>Očekávaný výsledek: hlavní nabídka.<br>Skutečný výsledek: EM008 „Neplatné heslo“.<br>Pozn.: stejné vstupy fungovaly včera, před dodáním vydání 1.2.<\/td><td>1<\/td><\/tr><\/tbody><\/table><p>Který tester reportoval defekt NEJÚČINNĚJI s ohledem na uvedené informace a prioritu?<\/p>","m":["<p>Tester 1<\/p>","<p>Tester 2<\/p>","<p>Tester 3<\/p>","<p>Tester 4<\/p>"],"ok":[3],"vys":{"a":"Není správně. Priorita je správná, ale report je nestrukturovaný – chybí očekávaný výsledek i přesné chybové hlášení.","b":"Není správně. Report neuvádí konkrétní vstupní data, takže defekt nelze spolehlivě reprodukovat, a priorita 2 je u kritické komponenty příliš nízká.","c":"Není správně. Report je dobře strukturovaný a reprodukovatelný, ale priorita 2 neodpovídá kritické komponentě.","d":"Je správně. Report obsahuje konkrétní vstupy, očekávaný i skutečný výsledek, správnou prioritu 1 a navíc kontext – defekt se projevil po dodání vydání 1.2."},"obecne":"<p>Sylabus 5.5: Report o defektu má obsahovat mimo jiné kroky a data pro reprodukci, očekávaný a skutečný výsledek, závažnost či prioritu a kontext (např. testovaný objekt a jeho verzi). Všechny tyto údaje včetně správné priority pro kritickou komponentu a informace o vydání 1.2 obsahuje jen report testera 4.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"}},{"id":"UP-4-22","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Dálkový vlak má zvláštní pravidla pro jízdenky, která popisuje následující rozhodovací tabulka:<\/p><table><thead><tr><th><\/th><th>P1<\/th><th>P2<\/th><th>P3<\/th><th>P4<\/th><th>P5<\/th><th>P6<\/th><th>P7<\/th><\/tr><\/thead><tbody><tr><th colspan=\"8\">Podmínky<\/th><\/tr><tr><td>Jízdenka 1. třídy<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><\/tr><tr><td>Flexibilní jízdenka 2. třídy<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><\/tr><tr><td>Jednodenní zpáteční jízdenka 2. třídy<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>N<\/td><\/tr><tr><td>Zvýhodněná jízdenka 2. třídy (Super Saver)<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>A<\/td><\/tr><tr><td>Držitel slevové železniční karty<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>A<\/td><td>A<\/td><\/tr><tr><th colspan=\"8\">Akce<\/th><\/tr><tr><td>Smí cestovat<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><\/tr><tr><td>Nárok na přestup do vyšší třídy<\/td><td>N<\/td><td>A<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>N<\/td><\/tr><tr><td>Zlevněné jízdné<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>A<\/td><td>A<\/td><td>N<\/td><\/tr><\/tbody><\/table><p>A = ano, N = ne; P1–P7 = pravidla.<\/p><p>TC 1: Karolína má studentskou slevovou železniční kartu a cestuje s flexibilní jízdenkou 2. třídy.<\/p><p>TC 2: Jakub má seniorskou slevovou železniční kartu a cestuje se zvýhodněnou jízdenkou 2. třídy (Super Saver).<\/p><p>Která možnost uvádí správné akce pro tyto dva testovací případy?<\/p>","m":["<p>Karolína: cestovat NE, přestup ANO, zlevněné jízdné ANO; Jakub: cestovat NE, přestup NE, zlevněné jízdné NE<\/p>","<p>Karolína: cestovat ANO, přestup NE, zlevněné jízdné ANO; Jakub: cestovat NE, přestup ANO, zlevněné jízdné NE<\/p>","<p>Karolína: cestovat ANO, přestup ANO, zlevněné jízdné NE; Jakub: cestovat ANO, přestup ANO, zlevněné jízdné NE<\/p>","<p>Karolína: cestovat ANO, přestup NE, zlevněné jízdné NE; Jakub: cestovat NE, přestup NE, zlevněné jízdné NE<\/p>"],"ok":[0],"vys":{"a":"Je správně. TC 1 odpovídá pravidlu P6 (smí cestovat N, přestup A, zlevněné jízdné A), TC 2 pravidlu P7 (všechny akce N).","b":"Není správně. Podle P6 Karolína cestovat nesmí, ale má nárok na přestup; Jakub podle P7 nárok na přestup nemá.","c":"Není správně. Podle P6 Karolína cestovat nesmí a má nárok na zlevněné jízdné; Jakub podle P7 nesmí cestovat ani přestoupit.","d":"Není správně. Akce pro Jakuba odpovídají P7, ale Karolína podle P6 cestovat nesmí a má nárok na přestup i zlevněné jízdné."},"obecne":"<p>Sylabus 4.2.3: Pro každý testovací případ se najde pravidlo, jehož podmínky odpovídají vstupům, a očekávaný výsledek se odvodí z akcí tohoto pravidla. Karolína (flexibilní jízdenka 2. třídy + slevová karta) spadá do P6, Jakub (Super Saver + slevová karta) do P7.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UP-4-23","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Je dána následující stavová tabulka televizoru (řádky = stavy, sloupce = události):<\/p><table><thead><tr><th>Stav \\ událost<\/th><th>Zapnout<\/th><th>Vypnout<\/th><th>Kanál 1<\/th><th>Kanál 2<\/th><th>Kanál &gt; 2<\/th><th>Pohotovost<\/th><\/tr><\/thead><tbody><tr><td>POHOTOVOST<\/td><td>ŽIVÝ OBRAZ<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>N<\/td><\/tr><tr><td>ŽIVÝ OBRAZ<\/td><td>N<\/td><td>POHOTOVOST<\/td><td>KANÁL 1<\/td><td>KANÁL 2<\/td><td>N<\/td><td>POHOTOVOST<\/td><\/tr><tr><td>KANÁL 1<\/td><td>N<\/td><td>N<\/td><td>N<\/td><td>KANÁL 2<\/td><td>ŽIVÝ OBRAZ<\/td><td>POHOTOVOST<\/td><\/tr><tr><td>KANÁL 2<\/td><td>N<\/td><td>N<\/td><td>KANÁL 1<\/td><td>N<\/td><td>ŽIVÝ OBRAZ<\/td><td>POHOTOVOST<\/td><\/tr><\/tbody><\/table><p>Buňka udává cílový stav přechodu; N = neplatný přechod.<\/p><p>Která z následujících možností představuje NEPLATNÝ přechod (N)?<\/p>","m":["<p>Událost Kanál 2 ve stavu KANÁL 1<\/p>","<p>Událost Pohotovost ve stavu ŽIVÝ OBRAZ<\/p>","<p>Událost Kanál 2 ve stavu ŽIVÝ OBRAZ<\/p>","<p>Událost Vypnout ve stavu KANÁL 1<\/p>"],"ok":[3],"vys":{"a":"Není správně. Událost Kanál 2 ve stavu KANÁL 1 vede do stavu KANÁL 2, jde o platný přechod.","b":"Není správně. Událost Pohotovost ve stavu ŽIVÝ OBRAZ vede do stavu POHOTOVOST, jde o platný přechod.","c":"Není správně. Událost Kanál 2 ve stavu ŽIVÝ OBRAZ vede do stavu KANÁL 2, jde o platný přechod.","d":"Je správně. V řádku KANÁL 1 a sloupci Vypnout je N – přechod je neplatný."},"obecne":"<p>Sylabus 4.2.4: Stavová tabulka zobrazuje pro každou kombinaci stavu a události buď cílový stav (platný přechod), nebo prázdnou či označenou buňku (neplatný přechod). Kombinace stavu KANÁL 1 a události Vypnout je označena N, je tedy neplatná.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"id":"UP-5-22","n":null,"lo":"FL-4.2.3","k":"K3","k3":true,"vyber":1,"q":"<p>Zaměstnancům společnosti se vyplácí prémie, pokud ve společnosti pracují déle než rok a splní cíl, který s nimi byl předem individuálně dohodnut.<\/p><p>Tyto skutečnosti zachycuje následující rozhodovací tabulka:<\/p><table><thead><tr><th>Testovací případ<\/th><th><\/th><th>T1<\/th><th>T2<\/th><th>T3<\/th><th>T4<\/th><\/tr><\/thead><tbody><tr><td>Podmínka 1<\/td><td>Pracuje ve společnosti déle než rok?<\/td><td>ANO<\/td><td>NE<\/td><td>NE<\/td><td>ANO<\/td><\/tr><tr><td>Podmínka 2<\/td><td>Byl dohodnut cíl?<\/td><td>NE<\/td><td>NE<\/td><td>ANO<\/td><td>ANO<\/td><\/tr><tr><td>Podmínka 3<\/td><td>Byl cíl splněn?<\/td><td>NE<\/td><td>NE<\/td><td>ANO<\/td><td>ANO<\/td><\/tr><tr><td>Akce<\/td><td>Vyplacení prémie<\/td><td>NE<\/td><td>NE<\/td><td>NE<\/td><td>ANO<\/td><\/tr><\/tbody><\/table><p>Který testovací případ pro situaci, která může reálně nastat, v rozhodovací tabulce chybí?<\/p>","m":["<p>Podmínka 1 = NE, Podmínka 2 = ANO, Podmínka 3 = NE, Akce = NE<\/p>","<p>Podmínka 1 = NE, Podmínka 2 = NE, Podmínka 3 = ANO, Akce = NE<\/p>","<p>Podmínka 1 = ANO, Podmínka 2 = NE, Podmínka 3 = ANO, Akce = NE<\/p>","<p>Podmínka 1 = ANO, Podmínka 2 = ANO, Podmínka 3 = NE, Akce = ANO<\/p>"],"ok":[0],"vys":{"a":"Je správně. Zaměstnanec pracuje méně než rok a dohodnutý cíl nesplnil – situace může nastat, prémie se nevyplácí a v tabulce chybí.","b":"Není správně. Cíl, který nebyl dohodnut, nelze splnit – tato kombinace je neproveditelná.","c":"Není správně. Cíl, který nebyl dohodnut, nelze splnit – tato kombinace je neproveditelná.","d":"Není správně. Kombinace podmínek v tabulce chybí, ale očekávaná akce je chybná – při nesplněném cíli se prémie nevyplácí."},"obecne":"<p>Sylabus 4.2.3: Úplná rozhodovací tabulka obsahuje všechny kombinace podmínek, neproveditelné kombinace se vynechávají. Proveditelné jsou kombinace, kde splněný cíl předpokládá dohodnutý cíl; v tabulce chybí (ANO, ANO, NE) a (NE, ANO, NE), obě s akcí NE. Mezi možnostmi je se správnou akcí jen (NE, ANO, NE).<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":true,"varianta":false,"kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"}},{"id":"UP-6-23","n":null,"lo":"FL-4.2.4","k":"K3","k3":true,"vyber":1,"q":"<p>Uvažujte následující stavový diagram samoobslužného čerpacího stojanu, který přijímá pouze platební karty:<\/p><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 400\" width=\"100%\" role=\"img\" aria-label=\"Stavový diagram samoobslužného čerpacího stojanu se čtyřmi stavy; přechody jsou vypsány pod diagramem.\" font-family=\"inherit\"><defs><marker id=\"sip-up623\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"currentColor\"/><\/marker><\/defs><rect x=\"40\" y=\"90\" width=\"170\" height=\"44\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"125\" y=\"117\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">ČEKÁNÍ NA ZÁKAZNÍKA<\/text><rect x=\"430\" y=\"90\" width=\"170\" height=\"44\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"515\" y=\"117\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">ČEKÁNÍ NA DRUH PALIVA<\/text><rect x=\"430\" y=\"320\" width=\"170\" height=\"44\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"515\" y=\"347\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">ČEKÁNÍ NA ČERPÁNÍ<\/text><rect x=\"40\" y=\"320\" width=\"170\" height=\"44\" rx=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"125\" y=\"347\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">ČERPÁNÍ<\/text><circle cx=\"12\" cy=\"112\" r=\"5\" fill=\"currentColor\"/><path d=\"M17,112 L38,112\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><path d=\"M100,90 C80,40 170,40 150,88\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"125\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">vložení karty [neplatná] / chybové hlášení<\/text><path d=\"M210,102 L428,102\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"320\" y=\"78\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">vložení karty [platná] /<\/text><text x=\"320\" y=\"93\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">výzva k volbě paliva<\/text><path d=\"M430,124 L212,124\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"320\" y=\"142\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">zrušení nebo časový limit /<\/text><text x=\"320\" y=\"157\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">rozloučení<\/text><path d=\"M515,134 L515,318\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"505\" y=\"220\" text-anchor=\"end\" font-size=\"12\" fill=\"currentColor\">stisk tlačítka paliva /<\/text><text x=\"505\" y=\"235\" text-anchor=\"end\" font-size=\"12\" fill=\"currentColor\">zahájení čerpání<\/text><path d=\"M430,330 L182,136\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"345\" y=\"292\" text-anchor=\"end\" font-size=\"12\" fill=\"currentColor\">zrušení nebo časový limit /<\/text><text x=\"345\" y=\"307\" text-anchor=\"end\" font-size=\"12\" fill=\"currentColor\">rozloučení<\/text><path d=\"M430,352 L212,352\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"320\" y=\"376\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">zákazník čerpá /<\/text><text x=\"320\" y=\"391\" text-anchor=\"middle\" font-size=\"12\" fill=\"currentColor\">hlášení o zahájení čerpání<\/text><path d=\"M125,320 L125,136\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#sip-up623)\"/><text x=\"135\" y=\"210\" text-anchor=\"start\" font-size=\"12\" fill=\"currentColor\">zákazník skončil /<\/text><text x=\"135\" y=\"225\" text-anchor=\"start\" font-size=\"12\" fill=\"currentColor\">tisk účtenky<\/text><\/svg><p>Přechody (událost [podmínka] / akce):<\/p><ol><li>ČEKÁNÍ NA ZÁKAZNÍKA → ČEKÁNÍ NA ZÁKAZNÍKA: vložení karty [neplatná] / chybové hlášení<\/li><li>ČEKÁNÍ NA ZÁKAZNÍKA → ČEKÁNÍ NA DRUH PALIVA: vložení karty [platná] / výzva k volbě paliva<\/li><li>ČEKÁNÍ NA DRUH PALIVA → ČEKÁNÍ NA ZÁKAZNÍKA: zrušení nebo časový limit / rozloučení<\/li><li>ČEKÁNÍ NA DRUH PALIVA → ČEKÁNÍ NA ČERPÁNÍ: stisk tlačítka paliva / zahájení čerpání<\/li><li>ČEKÁNÍ NA ČERPÁNÍ → ČEKÁNÍ NA ZÁKAZNÍKA: zrušení nebo časový limit / rozloučení<\/li><li>ČEKÁNÍ NA ČERPÁNÍ → ČERPÁNÍ: zákazník čerpá / hlášení o zahájení čerpání<\/li><li>ČERPÁNÍ → ČEKÁNÍ NA ZÁKAZNÍKA: zákazník skončil / tisk účtenky<\/li><\/ol><p>Chcete navrhnout minimální počet testů, které pokryjí každý přechod ve stavovém diagramu. Každý test musí začínat v počátečním stavu ČEKÁNÍ NA ZÁKAZNÍKA a končí, jakmile se systém do tohoto stavu znovu vrátí. Kolik testů potřebujete?<\/p>","m":["<p>1<\/p>","<p>4<\/p>","<p>7<\/p>","<p>Nekonečně mnoho<\/p>"],"ok":[1],"vys":{"a":"Není správně. Každý test končí prvním návratem do stavu ČEKÁNÍ NA ZÁKAZNÍKA, jeden test proto pokryje jen jeden ze čtyř přechodů do tohoto stavu.","b":"Je správně. Do stavu ČEKÁNÍ NA ZÁKAZNÍKA vedou 4 přechody (1, 3, 5, 7) a každý test končí právě jedním z nich; 4 testy zároveň stačí na pokrytí všech 7 přechodů.","c":"Není správně. 7 je počet přechodů; testy, které procházejí přechody 2, 4 a 6, je pokryjí společně, takže 7 testů není minimum.","d":"Není správně. Přechodů je konečný počet a pro jejich pokrytí stačí konečný počet testů."},"obecne":"<p>Sylabus 4.2.4: Pro pokrytí platných přechodů musí testy provést každý přechod alespoň jednou. Protože test končí prvním návratem do počátečního stavu a do něj vedou 4 přechody, jsou potřeba alespoň 4 testy: neplatná karta (1); platná karta a zrušení (2, 3); platná karta, volba paliva a zrušení (2, 4, 5); úplný nákup (2, 4, 6, 7). Tyto 4 testy pokryjí všech 7 přechodů.<\/p>","pozn":"","pozn_vyh":"","zdroj":"AI vygenerovaná otázka","navic":false,"varianta":false,"kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"}},{"n":1,"lo":"FL-1.1.1","k":"K1","vyber":1,"q":"<p>Které z následujících tvrzení popisuje správný cíl testování?<\/p>","m":["Prokázat, že testovaný systém neobsahuje žádné neopravené defekty.","Prokázat, že po nasazení systému do produkce nedojde k selháním.","Snížit úroveň rizika testovaného objektu a vybudovat důvěru v úroveň kvality.","Ověřit, že neexistují žádné netestované kombinace vstupů."],"ok":[2],"vys":{"a":"Není správně. Není možné prokázat, že v testovaném systému již nejsou žádné další defekty. Viz princip testování 1","b":"Není správně. Viz princip testování 7","c":"Je správně. Testování odhaluje defekty a selhání, což snižuje míru rizika a zároveň dává větší důvěru v úroveň kvality testovaného objektu","d":"Není správně. Není možné otestovat všechny kombinace vstupů (viz princip testování 2)"},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"},"id":"OF-A1","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 1 (© ISTQB®, překlad CaSQB)"},{"n":2,"lo":"FL-1.2.1","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení je příkladem testovacích činností, které přispívají k úspěchu?<\/p>","m":["Zapojení testerů do různých činností životního cyklu vývoje softwaru (SDLC) pomůže odhalit defekty v pracovních produktech.","Testeři se snaží nerušit vývojáře při programování, takže vývojáři vytváří lepší kód.","Testeři spolupracující s koncovými uživateli pomáhají zlepšovat kvalitu reportů o defektu během integračního testování komponent a systémového testování.","Certifikovaní testeři navrhnou mnohem lepší testovací případy než necertifikovaní testeři."],"ok":[0],"vys":{"a":"Je správně. Je důležité, aby testeři byli zapojeni v rámci životního cyklu vývoje softwaru (SDLC) od samotného začátku, což umožňuje lépe porozumět rozhodnutím souvisejících s návrhem a zároveň včas odhalit defekty.","b":"Není správně. Vývojáři i testeři budou lépe rozumět svým pracovním produktům a způsobu testování kódu.","c":"Není správně. Koncoví uživatelé nepomohou testerům zvýšit kvalitu reportů o defektech, zároveň se obvykle neúčastní testování v nízkých úrovních jako je například integrační testování.","d":"Není správně. Certifikace automaticky neznamená, že tester bude lepší při návrhu testů"},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.2.1","nazev":"Jak testování přispívá k úspěchu","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-jedna-jak-testovani-prispiva-k-uspechu"},"id":"OF-A2","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 2 (© ISTQB®, překlad CaSQB)"},{"n":3,"lo":"FL-1.3.1","k":"K2","vyber":1,"q":"<p>Byli jste přiřazeni jako tester do týmu, který inkrementálně vytváří nový systém. Všimli jste si, že nebyly po několik iterací provedeny žádné změny ve stávajících testovacích případech regresních testů a nebyly identifikovány žádné nové regresní defekty. Váš manažer je spokojený, ale vy ne.<br>Který princip testování vysvětluje vaši skepsi?<\/p>","m":["Testy se opotřebovávají.","Nepřítomnost defektů je klam.","Shlukování defektů.","Kompletní testování není možné."],"ok":[0],"vys":{"a":"Je správně. Tento princip říká, že pokud se stejné testy opakují nestále dokola, nenajdou nakonec žádné nové defekty. To je pravděpodobně důvod, proč v tomto vydání všechny testy prošly.","b":"Není správně. Tento princip říká, že pouhé nalezení a oprava velkého počtu defektů nezajistí úspěch systému.","c":"Není správně. Tento princip říká, že malý počet komponent obvykle obsahuje většinu defektů.","d":"Není správně. Tento princip říká, že otestování všech kombinací vstupů a vstupních podmínek není proveditelné."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"},"id":"OF-A3","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 3 (© ISTQB®, překlad CaSQB)"},{"n":4,"lo":"FL-1.4.1","k":"K2","vyber":1,"q":"<p>Pracujete v týmu, který vyvíjí mobilní aplikaci pro objednávání jídla. V aktuální iteraci se tým rozhodl implementovat funkcionalitu platby.<\/p><p>Která z následujících činností je součástí testovací analýzy?<\/p>","m":["Odhad, že testování integrace s platební službou bude trvat 8 člověkodnů.","Rozhodnutí, že by tým měl otestovat, zda je možné korektně rozdělit platbu mezi více uživatelů.","Použití analýzy hraničních hodnot (BVA) k odvození testovacích dat pro testovací případy, které kontrolují správné zpracování plateb pro minimální povolenou částku pro placení.","Analýza rozporu mezi skutečným výsledkem a očekávaným výsledkem a nahlášení defektu po provedení testovacího případu, který kontroluje proces platby kreditní kartou."],"ok":[1],"vys":{"a":"Není správně. Odhad pracnosti testování je součástí plánování testování.","b":"Je správně. Toto je příklad definice testovacích podmínek, které jsou součástí testovací analýzy.","c":"Není správně. Použití technik testování k odvození položek pokrytí je součástí návrhu testů.","d":"Není správně. Reportování defektů zjištěných při dynamickém testování je součástí provedení testů."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"},"id":"OF-A4","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 4 (© ISTQB®, překlad CaSQB)"},{"n":5,"lo":"FL-1.4.2","k":"K2","vyber":1,"q":"<p>Který z následujících faktorů má VÝZNAMNÝ vliv na přístup k testování?<\/p><ol type=\"i\"><li>SDLC (životní cyklus vývoje softwaru).<\/li><li>Počet nalezených defektů v předchozích projektech.<\/li><li>Identifikovaná produktová rizika.<\/li><li>Nové regulatorní požadavky vyžadující formální testování bílé skříňky.<\/li><li>Nastavení testovacího prostředí.<\/li><\/ol>","m":["i, ii mají významný vliv.","i, iii, iv mají významný vliv.","ii, iv, v mají významný vliv.","iii, v mají významný vliv."],"ok":[1],"vys":{"a":"Není správně","b":"Je správně.","c":"Není správně","d":"Není správně"},"obecne":"<ol type=\"i\"><li>Je správně. Zvolený SDLC nemá žádný vliv na přístup k testování.<\/li><li>Není správně. Počet zjištěných defektů v předchozích projektech může mít určitý vliv, ale ne tak významný jako i, iii a iv.<\/li><li>Je správně. Identifikovaná produktová rizika jsou jedním z nejdůležitějších faktorů ovlivňujících přístup k testování.<\/li><li>Je správně. Regulatorní požadavky jsou důležitými faktory ovlivňujícími přístup k testování.<\/li><li>Není správně. Testovací prostředí nemá významný vliv na přístup k testování.<\/li><\/ol><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"V oficiálním českém zdůvodnění bodu i. je chyba překladu: anglický originál říká, že SDLC <em>má<\/em> vliv na přístup k testování („The SDLC has an influence on the test approach“). Bod i. je proto správně, protože SDLC přístup k testování významně ovlivňuje.","kap":{"c":"1.4.2","nazev":"Proces testování v souvislostech","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-dva-proces-testovani-v-souvislostech"},"id":"OF-A5","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 5 (© ISTQB®, překlad CaSQB)"},{"n":6,"lo":"FL-1.4.5","k":"K2","vyber":2,"q":"<p>Které DVA z následujících úkolů jsou HLAVNÍ náplní role testera?<\/p>","m":["Konfigurace testovacích prostředí.","Udržování produktového backlogu.","Návrh řešení nových požadavků.","Vytvoření plánu testování.","Analýza testovací báze"],"ok":[0,4],"vys":{"a":"Je správně. Toto je prováděno testery.","b":"Není správně. Produktový backlog je vytvořen a udržován vlastníkem produktu.","c":"Není správně. Toto provádí vývojový tým.","d":"Není správně. Jedná se o manažerskou roli.","e":"Je správně. Tuto činnost provádějí testeři, protože je to technický úkol prováděný v rámci testovací analýzy."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.4.5","nazev":"Role v testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-pet-role-v-testovani"},"id":"OF-A6","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 6 (© ISTQB®, překlad CaSQB)"},{"n":7,"lo":"FL-1.5.1","k":"K2","vyber":1,"q":"<p>Které z následujících dovedností (i-v) jsou NEJVÍCE důležité dovednosti testera?<\/p><ol type=\"i\"><li>Znalost domény.<\/li><li>Vytvoření vize produktu.<\/li><li>Být dobrým týmovým hráčem.<\/li><li>Plánování a organizace práce týmu.<\/li><li>Kritické myšlení.<\/li><\/ol>","m":["ii a iv jsou důležité.","i, iii a v jsou důležité.","i, ii a v jsou důležité.","iii a iv jsou důležité."],"ok":[1],"vys":{"a":"Není správně","b":"Je správně.","c":"Není správně","d":"Není správně"},"obecne":"<ol type=\"i\"><li>Je správně. Znalost domény je důležitou dovedností testera.<\/li><li>Není správně. To je úkolem byznysového analytika společně se zástupcem byznysu.<\/li><li>Je správně. Být dobrým týmovým hráčem je důležitá dovednost.<\/li><li>Není správně. Plánování a organizace práce týmu je úkolem manažera testování nebo (v agilním projektu) celého týmu (tedy nejen testera).<\/li><li>Je správně. Kritické myšlení je jednou z nejdůležitějších dovedností testerů.<\/li><\/ol><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"1.5.1","nazev":"Obecné dovednosti potřebné pro testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-jedna-obecne-dovednosti-potrebne-pro-testovani"},"id":"OF-A7","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 7 (© ISTQB®, překlad CaSQB)"},{"n":8,"lo":"FL-1.5.2","k":"K1","vyber":1,"q":"<p>Jak se týmový přístup projevuje v interakcích mezi testery a zástupci byznysu?<\/p>","m":["Zástupci byznysu rozhodují o přístupu k automatizaci testů.","Testeři pomáhají zástupcům byznysu definovat strategii testování.","Zástupci byznysu nejsou součástí týmového přístupu.","Testeři pomáhají zástupcům byznysu vytvořit vhodné akceptační testy."],"ok":[3],"vys":{"a":"Není správně. Přístup k automatizaci testování definují testeři za podpory vývojářů a zástupců byznysu.","b":"Není správně. O strategii testování se rozhoduje ve spolupráci s vývojáři.","c":"Není správně. Testeři, vývojáři a zástupci byznysu jsou součástí týmového přístupu.","d":"Je správně. Testeři úzce spolupracují se zástupci byznysu, aby zajistili dosažení požadované úrovně kvality, což zahrnuje vzájemnou podporu a spolupráci tak, aby jim pomohli vytvořit vhodné akceptační testy."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"},"id":"OF-A8","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 8 (© ISTQB®, překlad CaSQB)"},{"n":9,"lo":"FL-2.1.2","k":"K1","vyber":1,"q":"<p>Pro které SDLC modely je platné pravidlo \"pro každou činnost SDLC existuje odpovídající testovací činnost\"?<\/p>","m":["Pouze v sekvenčních vývojových modelech.","Pouze v iterativních vývojových modelech.","Pouze v iterativních a inkrementálních vývojových modelech.","V sekvenčních, inkrementálních a iterativních vývojových modelech."],"ok":[3],"vys":{"a":"Není správně","b":"Není správně","c":"Není správně","d":"Je správně. Toto tvrzení platí pro všechny modely SDLC."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"},"id":"OF-A9","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 9 (© ISTQB®, překlad CaSQB)"},{"n":10,"lo":"FL-2.1.3","k":"K1","vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE vystihuje přístup k vývoji řízenému akceptačními testy (ATDD)?<\/p>","m":["V ATDD jsou akceptační kritéria obvykle vytvářena s využitím formátu Given/When/Then.","V ATDD jsou testovací případy vytvářeny hlavně při testování komponent a jsou orientovány na kód.","V ATDD jsou testy vytvářeny na základě akceptačních kritérií s cílem řídit vývoj daného softwaru.","v ATDD jsou testy založeny na požadovaném chování softwaru, což členům týmu usnadňuje jejich pochopení."],"ok":[2],"vys":{"a":"Není správně. Častěji se používá při vývoji řízeném chováním (BDD).","b":"Není správně. Jedná se o popis vývoje řízeného testy (TDD).","c":"Je správně. Při vývoji řízeném akceptačními testy (ATDD) se testy tvoří na základě akceptačních kritérií jako součást procesu návrhu (softwaru).","d":"Není správně. Používá se při BDD."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"},"id":"OF-A10","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 10 (© ISTQB®, překlad CaSQB)"},{"n":11,"lo":"FL-2.1.5","k":"K2","vyber":1,"q":"<p>Která z následujících možností NENÍ příkladem přístupu shift left?<\/p>","m":["Revize uživatelských požadavků předtím, než jsou formálně akceptovány zainteresovanými stranami.","Tvorba testů komponent před tvorbou odpovídajícího kódu.","Provedení testů výkonnostní efektivity (výkonnosti) během testování komponent.","Tvorba testovacího skriptu před nastavením procesu konfiguračního managementu."],"ok":[3],"vys":{"a":"Není správně. Včasná revize je příkladem přístupu shift left.","b":"Není správně. TDD je příkladem přístupu shift left.","c":"Není správně. Včasné nefunkcionální testování je příkladem přístupu shift left.","d":"Je správně. Testovací skripty by měly podléhat konfiguračnímu managementu, takže nemá smysl vytvářet testovací skripty před jeho zavedením."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"},"id":"OF-A11","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 11 (© ISTQB®, překlad CaSQB)"},{"n":12,"lo":"FL-2.1.6","k":"K2","vyber":1,"q":"<p>Který z níže uvedených argumentů byste použili, abyste přesvědčili svého manažera, aby po dokončení prací na novém vydání (release) uspořádal retrospektivu?<\/p>","m":["Retrospektivy jsou v dnešní době velmi populární a klienti by ocenili, kdybychom je přidali do našich procesů.","Organizování retrospektiv ušetří organizaci peníze, protože bez nich zástupci koncových uživatelů neposkytnou okamžitou zpětnou vazbu o produktu.","Slabé stránky procesů identifikované během retrospektivy lze analyzovat a mohou následně sloužit jako seznam úkolů v rámci kontinuálního zlepšování procesů organizace.","Retrospektivy zdůrazňují pět hodnot včetně odvahy a respektu, které jsou klíčové pro udržení trendu kontinuálního zlepšování v organizaci."],"ok":[2],"vys":{"a":"Není správně. Retrospektivy jsou vhodné spíše pro identifikaci příležitostí ke zlepšení a pro klienty mají malý význam.","b":"Není správně. Cílem retrospektivy není shromažďovat zpětnou vazbu o produktu, ale o procesu. Retrospektivy jsou navíc interní aktivitou týmu a neměli by se jich účastnit zástupci koncových uživatelů.","c":"Je správně. Pravidelně prováděné retrospektivy (pokud jsou následně zahájeny příslušné navazující činnosti) jsou zásadní pro kontinuální zlepšování procesů vývoje a procesů testování.","d":"Není správně. Odvaha a respekt jsou hodnoty extrémního programování a s retrospektivami souvisejí nepřímo."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"},"id":"OF-A12","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 12 (© ISTQB®, překlad CaSQB)"},{"n":13,"lo":"FL-2.2.1","k":"K2","vyber":1,"q":"<p>Které typy selhání (1-4) nejlépe vyhovují daným úrovním testování (A-D)?<\/p><ol><li>Selhání v chování systému, protože se odchyluje od byznysových potřeb uživatelů.<\/li><li>Selhání v komunikaci mezi komponentami.<\/li><li>Selhání v logice kódu.<\/li><li>Selhání v nesprávně implementovaných byznysových pravidlech.<\/li><\/ol><ol type=\"A\"><li>Testování komponent.<\/li><li>Integrační testování komponent.<\/li><li>Systémové testování.<\/li><li>Akceptační testování.<\/li><\/ol>","m":["1D, 2B, 3A, 4C","1D, 2B, 3C, 4A","1B, 2A, 3D, 4C","1C, 2B, 3A, 4D"],"ok":[0],"vys":{"a":"Je správně.","b":"Není správně","c":"Není správně","d":"Není správně"},"obecne":"<p>Platí, že:<\/p><ul><li>Testovací bázi pro akceptační testování tvoří byznysové potřeby uživatelů (1D).<\/li><li>Komunikace mezi komponentami je testována během integračního testování komponent (2B).<\/li><li>Selhání v logice mohou být nalezeny během testování komponent (3A).<\/li><li>Byznysová pravidla tvoří testovací bází pro systémové testování (4C).<\/li><\/ul><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"},"id":"OF-A13","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 13 (© ISTQB®, překlad CaSQB)"},{"n":14,"lo":"FL-2.2.3","k":"K2","vyber":1,"q":"<p>Testujete uživatelský scénář se třemi akceptačními kritérii: AC1, AC2 a AC3. AC1 je pokryt testovacím případem TC1, AC2 TC2 a AC3 TC3. Při dosavadním provádění testů proběhly tři testovací běhy ve třech po sobě jdoucích verzích softwaru následujícím způsobem:<\/p><table><thead><tr><th><\/th><th>Běh 1<\/th><th>Běh 2<\/th><th>Běh 3<\/th><\/tr><\/thead><tbody><tr><th>TC1<\/th><td>(1) Selhal<\/td><td>(4) Prošel<\/td><td>(7) Prošel<\/td><\/tr><tr><th>TC2<\/th><td>(2) Prošel<\/td><td>(5) Selhal<\/td><td>(8) Prošel<\/td><\/tr><tr><th>TC3<\/th><td>(3) Selhal<\/td><td>(6) Selhal<\/td><td>(9) Prošel<\/td><\/tr><\/tbody><\/table><p>Testy jsou zopakovány po sdělení, že všechny defekty zjištěné při běhu testu jsou opraveny a je k dispozici nová verze softwaru.<br>Které z výše uvedených testů byly provedeny jako regresní testy?<\/p>","m":["Pouze 4, 7, 8, 9.","Pouze 5, 7.","Pouze 4, 6, 8, 9.","Pouze 5, 6."],"ok":[1],"vys":{"a":"Není správně","b":"Je správně.","c":"Není správně","d":"Není správně"},"obecne":"<p>Vzhledem k tomu, že TC1 a TC3 selhaly při běhu 1 (tj. test 1 a test 3), test 4 a test 6 jsou při běhu 2 konfirmačními testy.<br>Vzhledem k tomu, že TC2 a TC3 selhaly při běhu 2 (tj. test 5 a test 6), test 8 a test 9 jsou při běhu 3 také konfirmačními testy.<br>TC2 prošel při běhu 1 (tj. test 2), takže test 5 je regresní test.<br>TC1 prošel při běhu 2 (tj. test 4), takže test 7 je také regresní test.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"},"id":"OF-A14","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 14 (© ISTQB®, překlad CaSQB)"},{"n":15,"lo":"FL-3.1.2","k":"K2","vyber":1,"q":"<p>Která z následujících možností NENÍ výhodou statického testování?<\/p>","m":["Levnější management defektů díky jejich snadné detekci v pozdějších fázích SDLC.","Oprava defektů zjištěných během statického testování je obecně mnohem levnější než oprava defektů zjištěných během dynamického testování.","Hledání defektů v kódu, které by nemusely být nalezeny pouze dynamickým testováním.","Detekce nedostatků a nesrovnalostí v požadavcích."],"ok":[0],"vys":{"a":"Je správně. Management defektů není levnější. Vyhledávání a oprava defektů v pozdější fázi SDLC je nákladnější.","b":"Není správně. Toto je výhoda statického testování.","c":"Není správně. Toto je výhoda statického testování.","d":"Není správně. Toto je výhoda statického testování."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"},"id":"OF-A15","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 15 (© ISTQB®, překlad CaSQB)"},{"n":16,"lo":"FL-3.2.1","k":"K1","vyber":1,"q":"<p>Která z následujících možností je výhodou včasné a časté zpětné vazby?<\/p>","m":["Zlepšuje proces testování pro budoucí projekty.","Nutí zákazníky stanovit si priority svých požadavků na základě odsouhlasených rizik.","Poskytuje míru kvality změn.","Pomáhá předcházet nedorozuměním v požadavcích."],"ok":[3],"vys":{"a":"Není správně. Zpětná vazba může zlepšit proces testování, ale pokud má dojít ke zlepšení pouze budoucích projektů, nemusí zpětná vazba přijít ani včas, ani dostatečně často.","b":"Není správně. Zpětná vazba se nepoužívá ke stanovení priorit požadavků.","c":"Není správně. Neexistuje univerzální doporučený způsob měření kvality změn. Navíc to není také jedna z výhod včasné zpětné vazby (viz kapitola 3.2.1).","d":"Je správně. Včasná a častá zpětná vazba může zabránit nedorozuměním ohledně požadavků."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"3.2.1","nazev":"Výhody včasné a časté zpětné vazby od zainteresovaných stran","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-jedna-vyhody-vcasne-a-caste-zpetne-vazby-od-zainteresovanych-stran"},"id":"OF-A16","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 16 (© ISTQB®, překlad CaSQB)"},{"n":17,"lo":"FL-3.2.4","k":"K2","vyber":1,"q":"<p>Revize, které se používají ve vaší organizaci, mají následující atributy:<\/p><ul><li>existuje role zapisovatele,<\/li><li>hlavním účelem je hodnocení kvality,<\/li><li>revizní schůzky vede autor pracovního produktu,<\/li><li>je prováděna individuální příprava,<\/li><li>je vypracována revizní zpráva.<\/li><\/ul><p>Který z následujících typů revize se s NEJVĚTŠÍ pravděpodobností používá?<\/p>","m":["Neformální revize.","Předvedení (walkthrough).","Technická revize.","Inspekce."],"ok":[1],"vys":{"a":"Není správně","b":"Je správně.","c":"Není správně","d":"Není správně"},"obecne":"<p>Na základě uvedených rysů je možno odvodit následující:<\/p><ul><li>Zapisovatel bývá přítomen při předvedení, technické revizi a inspekci, takže se nejedná o neformální revizi.<\/li><li>Hodnocení kvality je jedním z nejdůležitějších cílů při předvedení.<\/li><li>To není povoleno pro inspekce a obvykle se to neprovádí při technických revizích. Moderátor je potřeba při předvedení a je povolen pro neformální revize.<\/li><li>Všechny typy revizí mohou zahrnovat individuální přípravu (i neformální revize).<\/li><li>Revizní zprávu lze vypracovat u všech typů revizí, i když neformální revize dokumentaci nevyžadují.<\/li><\/ul><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"},"id":"OF-A17","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 17 (© ISTQB®, překlad CaSQB)"},{"n":18,"lo":"FL-3.2.5","k":"K1","vyber":1,"q":"<p>Které z těchto tvrzení NENÍ faktorem, který přispívá k úspěšným revizím?<\/p>","m":["Účastníci by měli revizím věnovat dostatek času.","Rozdělení velkých pracovních produktů na menší části vede k tomu, že práce probíhá méně intenzivně.","Účastníci by se měli vyvarovat chování, které by mohlo naznačovat nudu, podráždění nebo nepřátelství vůči ostatním účastníkům.","Zjištěná selhání by měla být uznána, oceněna a řešena objektivně."],"ok":[3],"vys":{"a":"Není správně. Dostatek času pro účastníky je faktorem úspěchu.","b":"Není správně. Rozdělení pracovních produktů na menší části je faktorem úspěchu.","c":"Není správně. Vyvarování se chování, které by mohlo naznačovat nudu, podráždění atd., je faktorem úspěchu.","d":"Je správně. Při revizích lze identifikovat defekty, nikoli selhání."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"3.2.5","nazev":"Faktory úspěchu při revizi","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-pet-faktory-uspechu-pri-revizi"},"id":"OF-A18","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 18 (© ISTQB®, překlad CaSQB)"},{"n":19,"lo":"FL-4.1.1","k":"K2","vyber":1,"q":"<p>Která z následujících vlastností je charakteristická pro techniky testování založené na zkušenostech?<\/p>","m":["Testovací případy jsou vytvářeny na základě podrobných informací o návrhu.","Položky testované v rámci kódu rozhraní se používají k měření pokrytí.","Testovací techniky se do značné míry spoléhají na znalosti testera o softwaru a byznysové doméně.","Testovací případy se používají k identifikaci odchylek od požadavků."],"ok":[2],"vys":{"a":"Není správně. To je běžná charakteristika technik testování bílé skříňky. Testovací podmínky, testovací případy a testovací data jsou odvozeny z testovací báze, která může zahrnovat kód, architekturu softwaru, detailní návrh nebo jakýkoli jiný zdroj informací týkající se struktury softwaru.","b":"Není správně. To je běžná charakteristika technik testování bílé skříňky. Pokrytí se měří na základě položek testovaných v rámci zvolené struktury a testovací techniky aplikované na testovací bázi.","c":"Je správně. Toto je obecná charakteristika technik testování založených na zkušenostech. Tyto znalosti a zkušenosti zahrnující očekávané použití softwaru, jeho prostředí, pravděpodobné defekty a distribuci těchto defektů se používají k definování testů.","d":"Není správně. To je obecná charakteristika technik testování černé skříňky. Testovací případy lze použít k odhalení nedostatků v požadavcích, v jejich implementaci a také odchylek od požadavků."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"},"id":"OF-A19","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 19 (© ISTQB®, překlad CaSQB)"},{"n":20,"lo":"FL-4.2.1","k":"K3","vyber":1,"q":"<p>Testujete zjednodušený formulář pro vyhledávání bytů, který má pouze dvě kritéria vyhledávání:<\/p><ul><li>patro (se třemi možnými variantami: 1. přízemí, 2. první patro, 3. druhé nebo vyšší patro),<\/li><li>typ zahrady (se třemi možnými variantami: žádná zahrada, malá zahrada, velká zahrada).<\/li><\/ul><p>Každý z bytů v přízemí má zahradu, byty ve vyšších patrech ji nemají. Formulář má vestavěný validační mechanismus, který vám nedovolí použít kritéria vyhledávání, která porušují toto pravidlo.<\/p><p>Každý test má dvě vstupní hodnoty: patro a typ zahrady. Chcete použít rozdělení tříd ekvivalence (EP) tak, aby testy pokryly všechny typy pater a všechny typy zahrad.<\/p><p>Jaký je <strong>minimální<\/strong> počet testovacích případů pro dosažení 100% pokrytí platných tříd ekvivalence?<\/p>","m":["3","4","5","6"],"ok":[1],"vys":{"a":"Není správně","b":"Je správně.","c":"Není správně","d":"Není správně"},"obecne":"<p>Situace uvedená v otázce je v učebních osnovách popsána jako pokrytí všech možností.<\/p><p>Hodnoty „malá zahrada“ a „velká zahrada“ kritéria „zahrada“ mohou být použity pouze s hodnotou „přízemí\" kritéria „patro“, takže potřebujeme dva testovací případy s hodnotou „přízemí\", které pokrývají tyto dvě třídy u kritéria „zahrada“.<br>Potřebujeme další dva testovací případy, abychom pokryli další dvě \"podlahové\" třídy. Zbývající třída „bez zahrady“ kritéria \"zahrada\" je těmito testy pokryta.<br>Potřebujeme tak celkem čtyři testovací případy:<br>TC1 (přízemí, malá zahrada),<br>TC2 (přízemí, velká zahrada),<br>TC3 (první patro, bez zahrady),<br>TC4 (druhé nebo vyšší patro, bez zahrady).<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"},"id":"OF-A20","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 20 (© ISTQB®, překlad CaSQB)"},{"n":21,"lo":"FL-4.2.2","k":"K3","vyber":1,"q":"<p>Testujete systém, který vypočítává pro daného studenta jeho celkovou známku z určitého předmětu.<\/p><p>Celková známka je přidělena na základě konečného výsledku podle následujících pravidel:<\/p><ul><li>0 – 50 bodů: neprospěl<\/li><li>51 – 60 bodů: dostatečně<\/li><li>61 – 70 bodů: uspokojivě<\/li><li>71 – 80 bodů: dobře<\/li><li>81 – 90 bodů: velmi dobře<\/li><li>91 – 100 bodů: výborně<\/li><\/ul><p>Připravili jste následující sadu testovacích případů:<\/p><table><thead><tr><th><\/th><th>Konečný výsledek<\/th><th>Závěrečné hodnocení<\/th><\/tr><\/thead><tbody><tr><th>TC1<\/th><td>91<\/td><td>výborně<\/td><\/tr><tr><th>TC2<\/th><td>50<\/td><td>neprospěl<\/td><\/tr><tr><th>TC3<\/th><td>81<\/td><td>velmi dobře<\/td><\/tr><tr><th>TC4<\/th><td>60<\/td><td>dostatečně<\/td><\/tr><tr><th>TC5<\/th><td>70<\/td><td>uspokojivě<\/td><\/tr><tr><th>TC6<\/th><td>80<\/td><td>dobře<\/td><\/tr><\/tbody><\/table><p>Jaké je <strong>pokrytí<\/strong> hraničních hodnot při užití 2-hodnotové analýzy hraničních hodnot, kterého je dosaženo pomocí výše definovaných testovacích případů?<\/p>","m":["50%","60%","33,3%","100%"],"ok":[0],"vys":{"a":"Je správně.","b":"Není správně","c":"Není správně","d":"Není správně"},"obecne":"<p>Existuje 12 hraničních hodnot: 0, 50, 51, 60, 61, 70, 71, 80, 81, 90, 91 a 100.<br>Testovací případy pokrývají šest z nich (TC1 – 91, TC2 – 50, TC3 – 81, TC4 – 60, TC5 – 70 a TC7 – 51).<br>Testovací případy tedy pokrývají 6/12 = 50 %.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"Zdůvodnění uvádí „TC7 – 51“, v otázce je ale jen TC1–TC6. Jde o chybu převzatou z anglického originálu: šestou pokrytou hraniční hodnotou je 80 z TC6. Výsledek 6/12 = 50 % platí.","kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"},"id":"OF-A21","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 21 (© ISTQB®, překlad CaSQB)"},{"n":22,"lo":"FL-4.2.3","k":"K3","vyber":1,"q":"<p>Vaše oblíbená půjčovna kol právě představila nový CRM systém (systém pro řízení vztahů se zákazníky) a požádala vás jako jednoho z jejich nejvěrnějších členů, abyste jej otestovali.<\/p><p>Implementované funkcionality jsou následující:<\/p><ul><li>Kolo si může půjčit kdokoliv, ale členové mají 20% slevu.<\/li><li>Pokud dojde k překročení lhůty pro vrácení, nárok na slevu zaniká.<\/li><li>Po 15 výpůjčkách dostanou členové dárek (tričko).<\/li><\/ul><p>Rozhodovací tabulka popisující implementované funkcionality vypadá takto (T-true/pravda, F-false/nepravda):<\/p><table><thead><tr><th>Podmínky<\/th><th>R1<\/th><th>R2<\/th><th>R3<\/th><th>R4<\/th><th>R5<\/th><th>R6<\/th><th>R7<\/th><th>R8<\/th><\/tr><\/thead><tbody><tr><th>Členství<\/th><td>T<\/td><td>T<\/td><td>T<\/td><td>T<\/td><td>F<\/td><td>F<\/td><td>F<\/td><td>F<\/td><\/tr><tr><th>Překročení lhůty pro vrácení<\/th><td>T<\/td><td>F<\/td><td>T<\/td><td>F<\/td><td>T<\/td><td>F<\/td><td>F<\/td><td>T<\/td><\/tr><tr><th>15. výpůjčka<\/th><td>F<\/td><td>F<\/td><td>T<\/td><td>T<\/td><td>F<\/td><td>F<\/td><td>T<\/td><td>T<\/td><\/tr><tr><th colspan=\"9\">Akce<\/th><\/tr><tr><th>20% sleva<\/th><td><\/td><td>X<\/td><td><\/td><td>X<\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><th>dárek (tričko)<\/th><td><\/td><td><\/td><td>X<\/td><td>X<\/td><td><\/td><td><\/td><td><\/td><td>X<\/td><\/tr><\/tbody><\/table><p>Které z výše uvedených pravidel popisuje POUZE na základě výše uvedeného popisu funkcionalit systému nemožnou situaci?<\/p>","m":["R4","R2","R6","R8"],"ok":[3],"vys":{"a":"Není správně. Člen, který nezmešká termín vrácení, může po 15 výpůjčkách kola získat slevu a dárkové tričko.","b":"Není správně. Člen, který nezmešká termín vrácení, může získat slevu, ale nedostane dárkové tričko, dokud si 15krát nepůjčí kolo.","c":"Není správně. Nečlenové nemohou získat slevu, a to ani v případě, že ještě nezmeškali termín vrácení.","d":"Je správně. Pro nečleny, kteří zmeškali termín vrácení, není k dispozici žádná sleva, ale ani tričko (pouze členové mohou získat dárkové tričko). Výsledná akce (tričko) tedy není správně."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"},"id":"OF-A22","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 22 (© ISTQB®, překlad CaSQB)"},{"n":23,"lo":"FL-4.2.4","k":"K3","vyber":1,"q":"<p>Testujete systém, jehož životní cyklus je znázorněn na níže uvedeném diagramu přechodů stavů uvedeným níže. Systém se spustí ve stavu INICIALIZACE a ukončí svou činnost ve stavu VYPNUTO.<\/p><p><img src=\"assets/vzorove/a-23.png\" alt=\"Diagram přechodů stavů: INICIALIZACE, LADICÍ REŽIM, V PROVOZU, PŘERUŠENO, VYPNUTO\"><\/p><p>Jaký je minimální počet testovacích případů pro dosažení pokrytí všech platných přechodů?<\/p>","m":["4","2","7","3"],"ok":[3],"vys":{"a":"Není správně","b":"Není správně","c":"Není správně","d":"Je správně."},"obecne":"<p>Přechody \"test\" a \"chyba\" se nemohou vyskytovat v jednom testovacím případě.<br>Ani jeden z těchto testů pokrývající přechody „test“ a „chyba“ nemůže zároveň přejít přes přechod \"hotovo\".<br>To znamená, že pro dosažení pokrytí přechodů potřebujeme alespoň tři testovací případy. Například:<br>TC1: test, hotovo<br>TC2: spustit, chyba, hotovo<br>TC3: spustit, pauza, obnovit, pauza, hotovo<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"},"id":"OF-A23","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 23 (© ISTQB®, překlad CaSQB)"},{"n":24,"lo":"FL-4.3.1","k":"K2","vyber":1,"q":"<p>Vaše testovací sada dosáhla 100% pokrytí příkazů. Co je důsledkem této skutečnosti?<\/p>","m":["Každá instrukce v kódu obsahující defekt byla provedena alespoň jednou.","Jakákoli testovací sada obsahující více testovacích případů než vaše testovací sada dosáhne také 100% pokrytí příkazů.","Každá cesta v kódu byla spuštěna alespoň jednou.","Každá kombinace vstupních hodnot byla alespoň jednou testována."],"ok":[0],"vys":{"a":"Je správně. Vzhledem k tomu, že je dosaženo 100% pokrytí příkazů, musí být každý příkaz (včetně těch, ve kterých se vyskytují defekty) proveden a vyhodnocen alespoň jednou.","b":"Není správně. Pokrytí závisí na tom, co se prověřuje testy, ne na počtu testovacích případů. Například pro kód \"if (x==0) y=1\" je dosaženo 100 % pokrytí příkazů jedním testovacím případem (x=0), ale dva testovací případy (x=1) a (x=2) společně dosáhnou pouze 50 % pokrytí příkazů.","c":"Není správně. Pokud je v kódu smyčka, může existovat nekonečný počet možných cest, takže není možné projít všechny možné cesty v kódu.","d":"Není správně. Kompletní testování není možné (viz kapitola Principy testování v učebních osnovách). Například pro kód \"input x; print x\" platí,že libovolný jednotlivý test s libovolným x dosahuje 100 % pokrytí příkazů, ale pokrývá jednu vstupní hodnotu."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"},"id":"OF-A24","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 24 (© ISTQB®, překlad CaSQB)"},{"n":25,"lo":"FL-4.3.3","k":"K2","vyber":1,"q":"<p>Která z následujících možností NENÍ pravdivá pro testování bílé skříňky?<\/p>","m":["Při testování bílé skříňky je analyzována celá implementace softwaru.","Metriky pokrytí bílé skříňky mohou pomoci identifikovat další testy a zvýšit tak pokrytí kódu.","Techniky bílé skříňky mohou být použity při statickém testování.","Testování bílé skříňky může pomoci identifikovat chyby v implementaci požadavků."],"ok":[3],"vys":{"a":"Není správně. Význam technik testování bílé skříňky spočívá v tom, že se při testování bere v úvahu celá implementace softwaru.","b":"Není správně. Míra pokrytí technikou testování bílé skříňky poskytuje objektivní měření pokrytí a poskytují nezbytné informace umožňující vytváření dalších testů s cílem zvýšení tohoto pokrytí.","c":"Není správně. Techniky testování bílé skříňky mohou být využity k provádění revizí (což je forma statického testování).","d":"Je správně. Toto je slabina technik testování bílé skříňky. Tyto techniky nejsou schopny identifikovat chybějící implementaci, protože jsou založeny pouze na struktuře testovaného objektu, nikoli na specifikaci požadavků."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"},"id":"OF-A25","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 25 (© ISTQB®, překlad CaSQB)"},{"n":26,"lo":"FL-4.4.1","k":"K2","vyber":1,"q":"<p>Které z následujících vyjádření NEJLÉPE vystihuje koncept odhadování chyb?<\/p>","m":["Odhadování chyb zahrnuje využití vašich znalostí a zkušeností s defekty nalezenými v minulosti a typickými chybami vývojářů.","Odhadování chyb zahrnuje využití vašich osobních zkušeností s vývojem a s chybami, kterých jste se jako vývojáři dopustili.","Odhadování chyb vyžaduje, abyste si představili, že jste uživatelem testovaného objektu, a abyste odhadli chyby, kterých by se uživatel mohl dopustit při interakci s ním.","Odhadování chyb vyžaduje, abyste rychle duplikovali úkol pro vývojáře s cílem identifikace druhu chyby, kterou může vývojář udělat."],"ok":[0],"vys":{"a":"Je správně. Základní koncept odhadování chyb spočívá v tom, že se tester snaží odhadnout na základě předchozích zkušeností (a někdy i kontrolních seznamů), jakých chyb se vývojář mohl dopustit a jaké defekty mohou být v testovaném objektu.","b":"Není správně. Ačkoli může tester, který býval vývojářem, využít své osobní zkušenosti při odhadování chyb, testovací technika není založena na předchozích znalostech o vývoji softwaru.","c":"Není správně. Odhadování chyb není technika použitelnosti, tzn. nedá se použít pro odhad toho, jakým způsobem může dojít k selhání při interakci uživatelů s testovaným objektem.","d":"Není správně. Duplikování vývojového úkolu má několik nedostatků, které jej činí nepraktickým, například to, že tester má stejné dovednosti jako vývojář a nebo čas (navíc) potřebný k provedení vývojové aktivity. Nejedná se o odhadování chyb."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"},"id":"OF-A26","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 26 (© ISTQB®, překlad CaSQB)"},{"n":27,"lo":"FL-4.4.2","k":"K2","vyber":1,"q":"<p>Ve vašem projektu došlo ke zpoždění ve vydání zcela nové aplikace a testování začalo později než mělo. Vy ale máte velmi dobré a podrobné znalosti z byznysové domény a dobré analytické dovednosti. Týmu ještě nebyl dodán úplný seznam požadavků, přesto vedení žádá o předložení výsledků nějakých testů.<\/p><p>Která testovací technika se v této situaci hodí NEJLÉPE?<\/p>","m":["Testování založené na kontrolních seznamech.","Odhadování chyb.","Průzkumné testování.","Testování větví."],"ok":[2],"vys":{"a":"Není správně. Jedná se o nový produkt, proto pravděpodobně ještě není k dispozici kontrolní seznam ani testovací podmínky z důvodu chybějících požadavků","b":"Není správně. Jedná se o nový produkt, proto pravděpodobně ještě není k dispozici dostatek informací k tomu, aby bylo možno správně provést odhadování chyb","c":"Je správně. Průzkumné testování je nejvhodnější v situaci, kdy nejsou k dispozici detailnější požadavky a/nebo je testování pod tlakem vzhledem k termínům.","d":"Není správně. Testování větví je časově náročné a vaše vedení požaduje nějaké výsledků testů co nejdříve (hned). Navíc testování větví nezohledňuje znalost domény."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.4.2","nazev":"Průzkumné testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-dva-pruzkumne-testovani"},"id":"OF-A27","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 27 (© ISTQB®, překlad CaSQB)"},{"n":28,"lo":"FL-4.5.2","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje způsob, jakým lze dokumentovat akceptační kritéria?<\/p>","m":["Provádění retrospektiv za účelem zjištění skutečných potřeb zainteresovaných stran týkajících se daného uživatelského scénáře.","Použití formátu Given/When/Then k popisu ukázkové testovací podmínky související s daným uživatelským scénářem.","Používání verbální komunikace ke snížení rizika nepochopení akceptačních kritérií ostatními.","Dokumentace rizik souvisejících s daným uživatelským scénářem v testovacím plánu s cílem usnadnit testování daného uživatelského scénáře na základě rizik."],"ok":[1],"vys":{"a":"Není správně. Retrospektivy se používají k zachycení získaných poznatků a ke zlepšování procesů vývoje a testování, nikoli k dokumentaci akceptačních kritérií.","b":"Je správně. Jedná se o standardní způsob dokumentace akceptačních kritérií.","c":"Není správně. Verbální komunikace neumožňuje fyzicky zdokumentovat akceptační kritéria jako součást uživatelského scénáře, viz element \"karta\" (card) v technice 3C.","d":"Není správně. Akceptační kritéria souvisejí s uživatelským scénářem, nikoli s plánem testování. Akceptační kritéria jsou také podmínky, při jejichž splnění je možno prohlásit uživatelský scénář za kompletní. Rizika nejsou takovými podmínkami."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"},"id":"OF-A28","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 28 (© ISTQB®, překlad CaSQB)"},{"n":29,"lo":"FL-4.5.3","k":"K3","vyber":1,"q":"<p>Předpokládejme existenci následujícího uživatelského scénáře:<\/p><blockquote><p><em>Jako editor<br>chci zkontrolovat obsah (článku) před jeho zveřejněním,<br>abych se mohl ujistit, že je gramaticky správně.<\/em><\/p><\/blockquote><p>Akceptační kritéria tohoto scénáře byla definována takto:<\/p><ul><li>Uživatel se může přihlásit do redakčního systému v roli \"Editor\".<\/li><li>Editor může zobrazit existující seznam článků.<\/li><li>Editor může upravovat obsah článku.<\/li><li>Editor může přidávat revizní poznámky.<\/li><li>Editor může ukládat změny.<\/li><li>Editor může článek vrátit k přepracování autorovi článku za účelem aktualizace.<\/li><\/ul><p>Který z následujících příkladů je NEJLEPŠÍM příkladem testu při použití přístupu vývoj řízený akceptačními testy (ATDD)?<\/p>","m":["Test, zda editor může článek uložit po jeho úpravě.","Test, zda se autor článku může přihlásit a provádět aktualizace jeho obsahu.","Test, zda editor může naplánovat upravený článek k publikaci.","Test, zda editor může článek přiřadit jinému editoru, aby provedl aktualizace."],"ok":[0],"vys":{"a":"Je správně. Tento test pokrývá dvě akceptační kritéria: jedno se týká úprav dokumentu a druhé ukládání změn.","b":"Není správně. Akceptační kritéria pokrývají aktivity editora, nikoli na aktivity autora článku.","c":"Není správně. Naplánování zveřejnění upraveného obsahu může být hezká funkcionalita, ale nevztahují se na ni akceptační kritéria.","d":"Není správně. Akceptační kritéria uvádějí změnu přiřazení z editora na autora článku, nikoli na jiného editora."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"},"id":"OF-A29","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 29 (© ISTQB®, překlad CaSQB)"},{"n":30,"lo":"FL-5.1.2","k":"K1","vyber":1,"q":"<p>Jakou přidanou hodnotou má přítomnost testera pro plánování iterací a plánování vydání?<\/p>","m":["Testeři určují prioritu uživatelských scénářů, které mají být implementovány.","Testeři se zaměřují pouze na funkcionální aspekty testovaného systému.","Testeři se podílejí na detailní identifikaci a ohodnocení rizik uživatelských scénářů.","Testeři garantují vydání vysoce kvalitního softwaru prostřednictvím včasného návrhu testů během plánování vydání."],"ok":[2],"vys":{"a":"Není správně. Priority uživatelských scénářů určují zástupci byznysu společně s vývojovým týmem.","b":"Není správně. Testeři se zaměřují na funkcionální i nefunkcionální aspekty testovaného systému.","c":"Je správně. Podle učebních osnov je to jeden z přínosů testerů zapojených do plánování iterací a plánování vydání.","d":"Není správně. Včasný návrh testů není součástí plánování vydání. Včasný návrh testů automaticky nezaručuje vydání kvalitního softwaru."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.1.2","nazev":"Přínos testerů při plánování iterací a vydání","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-dva-prinos-testeru-pri-planovani-iteraci-a-vydani"},"id":"OF-A30","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 30 (© ISTQB®, překlad CaSQB)"},{"n":31,"lo":"FL-5.1.3","k":"K2","vyber":2,"q":"<p>Které DVĚ z následujících možností jsou výstupními kritérii pro testování systému?<\/p>","m":["Připravenost testovacího prostředí.","Schopnost přihlásit se do testovanému objektu testerem.","Odhadovaná hustota defektů je dosažena.","Požadavky jsou přeloženy do formátu Given/When/Then.","Regresní testy jsou automatizovány."],"ok":[2,4],"vys":{"a":"Není správně. Připravenost testovacího prostředí je kritériem dostupnosti zdrojů a patří tedy mezi vstupní kritéria.","b":"Není správně. Jedná se také o kritérium dostupnosti zdrojů, patří tedy také mezi vstupní kritéria.","c":"Je správně. Odhadovaná hustota defektů je mírou důkladnosti, a proto patří mezi výstupní kritéria.","d":"Není správně. Požadavky přeložené do daného formátu vedou k testovatelným požadavkům, a proto patří mezi vstupní kritéria.","e":"Je správně. Automatizace regresních testů je kritériem dokončení, patří mezi výstupní kritéria."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"},"id":"OF-A31","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 31 (© ISTQB®, překlad CaSQB)"},{"n":32,"lo":"FL-5.1.4","k":"K3","vyber":1,"q":"<p>Váš tým používá techniku tříbodového odhadu k odhadu pracnosti při testování nové vysoce rizikové užitné vlastnosti (feature). Byly provedeny následující odhady:<\/p><ul><li>Nejoptimističtější odhad: 2 člověko-hodiny.<\/li><li>Nejpravděpodobnější odhad: 11 člověko-hodin.<\/li><li>Nejpesimističtější odhad: 14 člověko-hodin.<\/li><\/ul><p>Jaký je konečný odhad?<\/p>","m":["9 člověko-hodin.","14 člověko-hodin.","11 člověko-hodin.","10 člověko-hodin."],"ok":[3],"vys":{"a":"Není správně","b":"Není správně","c":"Není správně","d":"Je správně."},"obecne":"<p>U techniky tříbodového odhadu platí:<br>E = (optimistický + 4 * nejpravděpodobnější + pesimistický) / 6<br>E = (2 + (4 * 11) + 14) / 6 = 10<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"},"id":"OF-A32","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 32 (© ISTQB®, překlad CaSQB)"},{"n":33,"lo":"FL-5.1.5","k":"K3","vyber":1,"q":"<p>Testujete mobilní aplikaci, která uživatelům umožňuje najít restauraci v okolí na základě typu jídla, které chtějí jíst. Máme definován následující seznam testovacích případů, priorit (menší číslo znamená vyšší prioritu) a závislostí:<\/p><table><thead><tr><th>Číslo testovacího případu<\/th><th>Pokrytá testovací podmínka<\/th><th>Priorita<\/th><th>Logická závislost<\/th><\/tr><\/thead><tbody><tr><td>TC 001<\/td><td>Vyber druh jídla<\/td><td>3<\/td><td>žádná<\/td><\/tr><tr><td>TC 002<\/td><td>Vyber restauraci<\/td><td>2<\/td><td>TC 001<\/td><\/tr><tr><td>TC 003<\/td><td>Získej adresu<\/td><td>1<\/td><td>TC 002<\/td><\/tr><tr><td>TC 004<\/td><td>Zavolej do restaurace<\/td><td>2<\/td><td>TC 002<\/td><\/tr><tr><td>TC 005<\/td><td>Vytvoř rezervaci<\/td><td>3<\/td><td>TC 002<\/td><\/tr><\/tbody><\/table><p>Který z následujících testovacích případů by měl být proveden jako třetí?<\/p>","m":["TC 003","TC 005","TC 002","TC 001"],"ok":[0],"vys":{"a":"Je správně.","b":"Není správně","c":"Není správně","d":"Není správně"},"obecne":"<p>Z důvodu splnění závislosti musí být test TC 001 proveden jako první, TC 002 jako druhý. Následně TC 003 (z důvodu dodržení priorit), poté TC 004 a nakonec TC 005.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"},"id":"OF-A33","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 33 (© ISTQB®, překlad CaSQB)"},{"n":34,"lo":"FL-5.1.7","k":"K2","vyber":1,"q":"<p>Uvažujme následující kategorie testů (1-4) a agilní testovací kvadranty (A-D):<\/p><ol><li>Testování použitelnosti.<\/li><li>Testování komponent.<\/li><li>Funkcionální testování.<\/li><li>Testování spolehlivosti.<\/li><\/ol><ol type=\"A\"><li>Agilní testovací kvadrant Q1: zaměřený na technologii, podporující tým.<\/li><li>Agilní testovací kvadrant Q2: zaměřený na byznys, podporující tým.<\/li><li>Kvadrant Q3: zaměřený na byznys, revidující produkt.<\/li><li>Kvadrant Q4: zaměřený na technologii, revidující produkt.<\/li><\/ol><p>Do kterých kvadrantů byste výše uvedené testy zařadili?<\/p>","m":["1C, 2A, 3B, 4D","1D, 2A, 3C, 4B","1C, 2B, 3D, 4A","1D, 2B, 3C, 4A"],"ok":[0],"vys":{"a":"Je správně.","b":"Není správně","c":"Není správně","d":"Není správně"},"obecne":"<p>Platí, že:<\/p><ul><li>Testování použitelnosti je zařazeno v Q3 (1 – C).<\/li><li>Testování komponent je zařazeno v Q1 (2 – A).<\/li><li>Funkcionální testování je zařazeno v Q2 (3 – B).<\/li><li>Testování spolehlivosti je zařazeno v Q4 (4 – D).<\/li><\/ul><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"},"id":"OF-A34","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 34 (© ISTQB®, překlad CaSQB)"},{"n":35,"lo":"FL-5.2.4","k":"K2","vyber":1,"q":"<p>Během analýzy rizik bylo identifikováno a ohodnoceno následující riziko:<\/p><ul><li>Riziko: doba odezvy je příliš dlouhá na to, aby bylo možné vygenerovat sestavu.<\/li><li>Pravděpodobnost rizika: střední; dopad rizika: vysoký.<\/li><li>Reakce na riziko:<ul><li>Nezávislý testovací tým provádí během systémového testování testování výkonnostní efektivity (výkonnosti).<\/li><li>Vybraný vzorek koncových uživatelů provádí před vydáním alfa a beta testování.<\/li><\/ul><\/li><\/ul><p>Jaký způsob reakce na toto analyzované riziko je zvolen?<\/p>","m":["Přijetí rizika.","Záložní plán.","Zmírnění rizika.","Přenos rizika."],"ok":[2],"vys":{"a":"Není správně. Riziko nemůže být akceptováno. Jsou navrhována konkrétní opatření.","b":"Není správně. Nejsou navrhovány žádné pohotovostní plány.","c":"Je správně. Navrhovaná opatření souvisí s testováním, které je formou zmírňování rizik.","d":"Není správně. Riziko se nepřenáší, ale zmírňuje."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.2.4","nazev":"Řízení produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-ctyri-rizeni-produktovych-rizik"},"id":"OF-A35","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 35 (© ISTQB®, překlad CaSQB)"},{"n":36,"lo":"FL-5.3.3","k":"K2","vyber":1,"q":"<p>Který pracovní produkt může agilní tým použít k zobrazení množství dokončené práce a množství celkové zbývající práce pro danou iteraci?<\/p>","m":["Akceptační kritéria.","Report o defektu.","Souhrnný report z testování.","Graf burn-down."],"ok":[3],"vys":{"a":"Není správně. Akceptační kritéria jsou podmínky, které se používají k rozhodnutí, zda je uživatelský scénář hotový a nejsou určena k zobrazení postupu prací.","b":"Není správně. Reporty o defektu informují o defektech a taktéž nejsou určena k zobrazení postupu prací.","c":"Není správně. Souhrnný report z testování se vytváří po dokončení iterace, takže nemůže zobrazovat postup prací v průběhu iterace.","d":"Je správně. Grafy burndown jsou grafickým znázorněním zbývající práce (pracnosti) v závislosti na zbývajícím čase. Jsou denně aktualizovány, takže mohou průběžně ukazovat postup prací."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.3.3","nazev":"Komunikování stavu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-tri-komunikovani-stavu-testovani"},"id":"OF-A36","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 36 (© ISTQB®, překlad CaSQB)"},{"n":37,"lo":"FL-5.4.1","k":"K2","vyber":1,"q":"<p>Je třeba aktualizovat jeden z automatizovaných testovacích skriptů tak, aby byl v souladu s novým požadavkem. Který proces vyžaduje tvorbu nové verze testovacího skriptu v repozitáři testů?<\/p>","m":["Management trasovatelnosti.","Testování údržby.","Konfigurační management.","Management požadavků."],"ok":[2],"vys":{"a":"Není správně. Trasovatelnost je vztah mezi dvěma nebo více pracovními produkty, nikoli mezi různými verzemi stejného pracovního produktu.","b":"Není správně. Testování údržby se zabývá testováním změn a nesouvisí přímo s verzováním.","c":"Je správně. Z důvodu podpory testování může konfigurační management zahrnovat také správu verzí všech položek testování.","d":"Není správně. Řízení požadavků je získávání, dokumentace a správa požadavků a nesouvisí přímo s verzováním testovacích skriptů."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"},"id":"OF-A37","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 37 (© ISTQB®, překlad CaSQB)"},{"n":38,"lo":"FL-5.5.1","k":"K3","vyber":1,"q":"<p>Od vývojářů jste obdrželi vyjádření k následujícímu report o defektu, kde uvádí, že popsaná anomálie není reprodukovatelná.<\/p><blockquote><p><em>Aplikace zamrzne<\/em><\/p><p><em>3. května 2022 – John Doe – Odmítnuto<\/em><\/p><p><em>Aplikace zamrzne po zadání \"Test input: $ä\" do pole Název na obrazovce pro vytvoření nového uživatele. Zkusil jsem se odhlásit a přihlásit pomocí účtu test_admin01, stejný problém. Zkusil jsem i s jinými testovacími účty správců, stejný problém. Nezobrazila se žádná chybová zpráva, log (viz příloha) obsahuje upozornění na závažnou chybu. Na základě testovacího případu TC-1305 by aplikace měla akceptovat poskytnutý vstup a vytvořit uživatele. Prosím o opravu s vysokou prioritou, tato funkcionalita souvisí s REQ-0012, což je nový kritický byznysový požadavek.<\/em><\/p><\/blockquote><p>Jaké kritické informace, které by byly pro vývojáře užitečné, v tomto reportu CHYBÍ?<\/p>","m":["Očekávané a skutečné výsledky.","Reference a stav defektu.","Testovací prostředí a položka testování.","Priorita a závažnost."],"ok":[2],"vys":{"a":"Není správně. Očekávaným výsledkem je: aplikace by měla přijmout zadaný vstup a vytvořit uživatele. Skutečný výsledek je: aplikace zamrzne po zadání „Test input: $ä\".","b":"Není správně. V reportu je uveden odkaz na testovací případ a související požadavek, kdy je uvedeno, že defekt byl zamítnut. Stav defektu by také vývojářům příliš nepomohl.","c":"Je správně. Nevíme, ve kterém testovacím prostředí byla anomálie detekována, a také nevíme, ve které aplikaci a verzi se objevila.","d":"Není správně. Report o defektu uvádí, že vyřešení anomálie je urgentní a jedná se o globální problém (tj. je ovlivněno mnoho účtů správy testů, možná dokonce všechny) a uvádí, že dopad je pro byznysové zainteresované strany vysoký."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"},"id":"OF-A38","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 38 (© ISTQB®, překlad CaSQB)"},{"n":39,"lo":"FL-6.1.1","k":"K2","vyber":1,"q":"<p>Kterou testovací činnost podporuje nástroj pro přípravu dat?<\/p>","m":["Monitoring testování a řízení testování.","Testovací analýza.","Návrh testů a implementace testování.","Dokončení testování."],"ok":[2],"vys":{"a":"Není správně. Monitoring testování zahrnuje průběžnou kontrolu všech činností testování a porovnávání skutečného stavu proti plánu. Řízení testování zahrnuje přijetí opatření nezbytných pro dosažení cílů testování definovaných v plánu testování. Během těchto činností se nepřipravují žádná testovací data.","b":"Není správně. Testovací analýza zahrnuje analýzu testovací báze za účelem identifikace testovacích podmínek a stanovení jejich priorit. Testovací data se během této činnosti nepřipravují.","c":"Je správně. Návrh testů i implementace testování mohou zahrnovat identifikaci, vytvoření nebo získání testwaru nezbytného pro provedení testů (např. testovací data).","d":"Není správně. Aktivity dokončení testování se vyskytují v milnících projektu (např. vydání, konec iterace, dokončení úrovně testování), takže na přípravu testovacích dat je příliš pozdě."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"},"id":"OF-A39","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 39 (© ISTQB®, překlad CaSQB)"},{"n":40,"lo":"FL-6.2.1","k":"K1","vyber":1,"q":"<p>Která možnost správně identifikuje potenciální riziko automatizace testů?<\/p>","m":["Může způsobit neznámé regrese v produkčním prostředí.","Na údržbu testwaru není alokována dostatečná pracnost.","Na testovací nástroje a související testware se nelze dostatečně spolehnout.","Může zkrátit čas vyhrazený pro manuální testování."],"ok":[1],"vys":{"a":"Není správně. Automatizace testování nezpůsobuje nové (neznámé) regrese v produkčním prostředí.","b":"Je správně. Špatná (obvykle nízká) alokace pracnosti na údržbu testwaru je riziko.","c":"Není správně. Testovací nástroje musí být vybrány tak, aby se na ně a jejich testware dalo spolehnout.","d":"Není správně. Primárním cílem automatizace testů je snížit množství manuálního testování. Jedná se tedy o výhodu, nikoli riziko."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"},"id":"OF-A40","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška A, otázka 40 (© ISTQB®, překlad CaSQB)"},{"n":1,"lo":"FL-1.2.1","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení je příkladem toho, proč je testování nezbytné?<\/p>","m":["Dynamické testování zvyšuje kvalitu tím, že způsobuje selhání testovaných objektů způsoby, ke kterým by se uživatelé nikdy nedostali.","Vývojáři nejprve používají statické testování k nalezení selhání ve svém vlastním kódu, a teprve pak používají dynamické testování.","Statická analýza poskytuje zákazníkům důkaz, že prvky systému, které nedávají žádné výstupy, jsou vhodné k vydání.","Revize zvyšují kvalitu specifikací požadavků a vedou k menšímu počtu změn potřebných v navazujících pracovních produktech."],"ok":[3],"vys":{"a":"Není správně. Často je možné využít dynamické testování k vyvolání selhání testovaného objektu způsoby, ke kterým by se uživatelé nikdy nedostali, například pomocí vkládání chyb (fault injection). Nicméně, pokud se nemůže takové selhání nikdy vyskytnout u reálných koncových uživatelů, pak není jeho identifikace nijak zvlášť hodnotná, protože testování je v konečném důsledku zaměřeno na zlepšení pracovního produktu pro koncové uživatele. Trávit čas testováním takových selhání není efektivní využití času testerů.","b":"Není správně. Statické testování ve formě statické analýzy používají vývojáři k identifikaci defektů v jejich kódu dříve, než toho lze dosáhnout prostřednictvím dynamického testování. Pořád ale platí, že statické testování (a statická analýza) se používá k detekci defektů, nikoli selhání (která jsou identifikována dynamickým testováním). Důvodem, proč je tato odpověď nesprávná, je použití termínu \"selhání\".","c":"Není správně. Statická analýza přímo detekuje defekty v kódu, a její výsledky obvykle využívají vývojáři, nikoliv zákazník.","d":"Je správně. Revize jsou formou statického testování, které lze aplikovat od úplného začátku životního cyklu vývoje softwaru. Nalezení a odstranění defektů v požadavcích tak ušetří pracnost, která by se vyplýtvala při činnostech vývoje, které by s těmito chybnými požadavky souvisely. Pokud by nebyly tyto defekty včas zjištěny a odstraněny a došlo by k jejich detekci v navazujících pracovních produktech (jako je návrh a kód), muselo by dojít ke změně požadavků."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.2.1","nazev":"Jak testování přispívá k úspěchu","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-jedna-jak-testovani-prispiva-k-uspechu"},"id":"OF-B1","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 1 (© ISTQB®, překlad CaSQB)"},{"n":2,"lo":"FL-1.2.2","k":"K1","vyber":1,"q":"<p>Které z následujících tvrzení o zajištění kvality (QA) a/nebo kontrole kvality (QC) je správné?<\/p>","m":["QA se provádí jako součást testování.","Testování se provádí jako součást QC.","Testování je jiný termín pro QC.","Testování se provádí v rámci QA."],"ok":[1],"vys":{"a":"Není správně. QA se zaměřuje na zlepšování a implementaci procesů s cílem vyhnout se chybám a defektům preventivním způsobem, zatímco testování je jednou z forem QC, která se používá k detekci defektů.","b":"Je správně. QC se snaží dosáhnout odpovídající úrovně kvality zaměřením se na identifikaci a opravu defektů v produktu. Testování je významnou součástí QC a pomáhá tyto defekty odhalit.","c":"Není správně. Ačkoli je testování významnou součástí QC a pomáhá odhalovat defekty, existují i další (netestovací) techniky používané v QC, které zahrnují formální metody jako jsou ověření modelu, důkazy správnosti, simulace nebo prototypování.","d":"Není správně. QA se zaměřuje na zlepšování a implementaci procesů s cílem vyhnout se chybám a defektům preventivním způsobem, zatímco testování je jednou z forem QC, která se používá k detekci defektů."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.2.2","nazev":"Testování a zajištění kvality","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-dva-testovani-a-zajisteni-kvality"},"id":"OF-B2","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 2 (© ISTQB®, překlad CaSQB)"},{"n":3,"lo":"FL-1.3.1","k":"K2","vyber":1,"q":"<p>Jeden ze sedmi principů testování říká, že kompletní testování není možné. Které z následujících tvrzení je příkladem praktického uplatnění tohoto principu?<\/p>","m":["Vytváření testovacích případů, které pokrývají všechny možné výstupy.","Dokumentace všech možných variant testovacích vstupů a stanovení priorit na základě jejich důležitosti.","Zahájení testování co nejdříve za pomoci revizí a dalších metod statického testování.","Použití technik rozdělení tříd ekvivalence a analýzy hraničních hodnot k tvorbě testovacích případů."],"ok":[3],"vys":{"a":"Není správně. Tento princip říká, že není možné otestovat vše kromě triviálních případů. Testování všeho by vyžadovalo testování všech možných variant vstupů za všech okolností, což je obecně neproveditelné, protože existuje prakticky nekonečné množství možností. Testování každého možného očekávaného výsledku tento problém nevyřeší, protože vztah mezi vstupy a očekávanými výsledky se může u každého testovaného objektu lišit. Někdy může existovat prakticky nekonečný počet možných očekávaných výsledků (např. když existuje několik proměnných reprezentujících reálná čísla), zatímco jindy mohou být jen dva (například s jednou proměnnou, kdy je výsledek pravda nebo nepravda).","b":"Není správně. Princip říká, že není možné testovat všechny možné varianty vstupů za všech okolností. Je to proto, že pro netriviální systémy existuje prakticky nekonečné množství kombinací. V praxi by proto bylo zdokumentování všech možných variant vstupů nereálné, protože by to trvalo nekonečně dlouho.","c":"Není správně. Zahájení testování co nejdříve s využitím revizí a dalších technik statického testování nevyřeší problém s příliš mnoha možnými testovacími případy. Princip \"včasné testování šetří čas a peníze\" se týká včasného odstranění defektů s cílem zabránit vzniku následných defektů odvozených pracovních produktů, čímž se sníží náklady a pravděpodobnost selhání.","d":"Je správně. Použití rozdělení tříd ekvivalence a analýzy hraničních hodnot ke tvorbě testovacích případů je jedním ze způsobů, jak tento princip uplatnit, protože tyto testovací techniky poskytují systematický návod, jak ze všech možných testovacích případů odvodit jejich konečnou podmnožinu."},"obecne":"<p>Princip \"kompletní testování není možné\" znamená, že není možné otestovat všechny možné kombinace testovacích vstupů za všech okolností s výjimkou triviálních případů. Je lepší zaměřit úsilí na vhodné techniky testování, stanovení priorit testovacích případů a testování založené na rizicích s cílem vybrat z celé množiny vstupů pouze určité vzorky.<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"},"id":"OF-B3","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 3 (© ISTQB®, překlad CaSQB)"},{"n":4,"lo":"FL-1.4.1","k":"K2","vyber":1,"q":"<p>Která testovací činnost zahrnuje práci s požadavky na testovací data, testovacími podmínkami, požadavky testovacího prostředí a testovacími případy?<\/p>","m":["Návrh testů.","Provedení testů.","Testovací analýza.","Implementace testování."],"ok":[0],"vys":{"a":"Je správně. Návrh testů zahrnuje použití testovacích podmínek k vytvoření testovacích případů a dalšího testwaru jako jsou požadavky na testovací data a testovací listiny pro průzkumné testování. Specifikovány jsou také požadavky na testovací prostředí včetně potřebné infrastruktury a nástrojů.","b":"Není správně. Provedení testů zahrnuje provedení testovacích případů (jako součást testovacích procedur), ale přímo nepokrývá ostatní testware uvedený v otázce, tzn. požadavky na testovací data, požadavky na testovací prostředí a testovací podmínky.","c":"Není správně. Testovací analýza se používá k identifikaci funkcionalit, které vyžadují testování. Je analyzována a definována testovací báze, kdy výstupem jsou prioritizované testovací podmínky spolu se souvisejícími riziky. I když tato aktivita zahrnuje práci s testovacími podmínkami, nepokrývá další testware zmíněný v otázce, tzn. požadavky na testovací data, požadavky na testovací prostředí a testovací případy.","d":"Není správně. Implementace testování zahrnuje vytváření testovacích procedur jako jsou manuální a automatizované testovací skripty, které se vytvářejí z testovacích případů a mohou být sestaveny do testovacích sad. Testovací procedury jsou prioritizovány a uspořádány v harmonogramu provádění testů. Vytváří se testovací data, nastaví se testovací prostředí a ověří se jeho nastavení. Přestože tato aktivita explicitně pracuje s testovacími případy a může využívat požadavky na testovací data a testovací prostředí k jejich vytvoření, nezahrnuje testovací podmínky."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"},"id":"OF-B4","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 4 (© ISTQB®, překlad CaSQB)"},{"n":5,"lo":"FL-1.4.2","k":"K2","vyber":1,"q":"<p>Která z následujících možností bude mít NEJVĚTŠÍ vliv na testování určitého objektu?<\/p>","m":["Průměrná úroveň zkušeností marketingového týmu organizace.","Povědomí uživatelů o tom, že je pro ně vyvíjen nový systém.","Délka praxe členů testovacího týmu.","Organizační struktura koncového uživatele pro komerční aplikaci pro streamování hudby."],"ok":[2],"vys":{"a":"Není správně. Je nepravděpodobné, že by marketingový tým organizace prováděl testování (i když v některých organizacích může být zapojen do akceptačního testování), takže jeho průměrná úroveň zkušeností (která by byla většinově v oblasti marketingu) pravděpodobně nebude mít vliv na to, jak se provádí testování pro daný testovaný objekt.","b":"Není správně. Je nepravděpodobné, že úroveň znalostí uživatelů, pro které je systém vyvíjen, ovlivní způsob provádění testování. Jakékoli zapojení uživatelů, které by mohlo ovlivnit způsob provádění testování, bude s větší pravděpodobností výsledkem rozhodnutí učiněných testery, zákazníkem a projektovým manažerem.","c":"Je správně. Délka praxe členů testovacího týmu pomůže určit potřebné schopnosti a znalosti (např. různých nástrojů a typů defektů), které členové týmu uplatní při testování.","d":"Není správně. Organizační struktura různých koncových uživatelů (kteří se mohou měnit) může být odlišná. Při testování aplikace tedy nemusí být známo, kdo bude koncovým uživatelem, a organizační struktura tohoto uživatele tak může mít jen malý vliv na způsob provádění testování."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.4.2","nazev":"Proces testování v souvislostech","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-dva-proces-testovani-v-souvislostech"},"id":"OF-B5","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 5 (© ISTQB®, překlad CaSQB)"},{"n":6,"lo":"FL-1.4.4","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení je SPRÁVNÝM příkladem přínosu trasovatelnosti?<\/p>","m":["Trasovatelnost mezi zmírněnými riziky a úspěšnými (passed) testovacími případy pomáhá určit úroveň zbytkového rizika.","Trasovatelnost mezi uživatelskými požadavky a výsledky testů pomáhá měřit postup prací v projektu v porovnání s byznysovými cíli.","Trasovatelnost mezi testery a neúspěšnými (failed) testovacími případy pomáhá určit úroveň dovedností testerů.","Trasovatelnost mezi zjištěnými riziky a sepsanými testovacími podmínkami pomáhá určit, která rizika stojí za to testovat."],"ok":[1],"vys":{"a":"Není správně. Trasovatelnost mezi zmírněnými riziky a úspěšnými (passed) testovacími případy neposkytuje dostatek informací. Aby byla rizika testováním zmírněna, musel by k nim být přiřazen úspěšný (passed) testovací případ. Pro posouzení zbytkového (reziduálního) rizika je nezbytná sledovatelnost mezi všemi riziky a výsledky testů, což umožňuje identifikovat jako zbytková ta rizika, která nejsou pokryta žádným úspěšným testem.","b":"Je správně. Trasovatelnost mezi uživatelskými požadavky a výsledky testů poskytuje informace o tom, které požadavky uživatelů již byly testovány. Tím měří postup projektových prací (v kontextu testování) oproti byznysovým cílům.","c":"Není správně. Není jasné, zda neúspěšné testovací případy vypovídají o schopnostech testera více než úspěšné testovací případy. Částečně by to záviselo na cílech testování (např. budování důvěry nebo vyvolání selhání). Měření testerů ve smyslu úspěšných a neúspěšných testovacích případů může být také kontraproduktivní, protože by mohlo způsobit to, že testeři optimalizují své testování podle této metriky a nikoliv podle cílů testování.","d":"Není správně. Trasovatelnost mezi identifikovanými riziky a vytvořenými testovacími podmínkami umožňuje určit, jaké další testovací podmínky je nutné napsat. Určení, která rizika stojí za to testovat, je součástí managementu rizik, zejména pak zmírňování rizik."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.4.4","nazev":"Trasovatelnost mezi testovací bází a pracovními produkty z testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-ctyri-trasovatelnost-mezi-testovaci-bazi-a-pracovnimi-produkty-z-testovani"},"id":"OF-B6","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 6 (© ISTQB®, překlad CaSQB)"},{"n":7,"lo":"FL-1.5.1","k":"K2","vyber":1,"q":"<p>Která z následujících možností je NEJPRAVDĚPODOBNĚJŠÍM příkladem toho, že tester při testování používá nějakou obecnou dovednost, která je užitečná z hlediska testování?<\/p>","m":["Díky hlubokým znalostem různých počítačových her si tester dobře rozumí s jedním z vývojářů, který se také věnuje hrám.","Tester je bývalý pilot a je schopen lépe porozumět akceptačním kritériím řídicího systému helikoptéry.","Tester dříve pracoval jako programátor a své dovednosti v této oblasti využil k lepší komunikaci s byznysovými analytiky.","Tester před zahájením průzkumného testování vytvoří seznam testovacích případů, protože je velmi opatrný a nechce dělat chyby."],"ok":[1],"vys":{"a":"Není správně. Dobré komunikační dovednosti, schopnost aktivního naslouchání a týmové spolupráce umožňují testerovi efektivně komunikovat se všemi zainteresovanými stranami, nicméně hluboká znalost různých počítačových her, která pomáhá dobře vycházet s jedním z vývojářů, není příkladem obecné dovednosti užitečné pro testery.","b":"Je správně. Znalost oboru, kterou lze využít pro porozumění a komunikaci s koncovými uživateli a zástupci byznysu, je jednou z obecných dovedností požadovaných po testerech. Tester se zkušenostmi pilota může být schopen lépe posoudit akceptační kritéria řídicího systému vrtulníku.","c":"Není správně. Ačkoli by schopnost programovat mohla být považována za technickou znalost, která může zvýšit efektivitu používání některých testovacích nástrojů, je nepravděpodobné, že by tato dovednost zlepšila komunikaci s byznysovými analytiky.","d":"Není správně. Ačkoli důkladnost, smysl pro detail, zvídavost a metodický přístup k identifikaci těžko zjistitelných defektů jsou pro testery užitečné obecné dovednosti, lze pochybovat o tom, že by testeři vygenerovali testovací případy již před zahájením průzkumného testování. Je to proto, že jednou z hlavních zásad průzkumného testování je, že testovací případy jsou generovány během testování (nejsou napsány předem)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.5.1","nazev":"Obecné dovednosti potřebné pro testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-jedna-obecne-dovednosti-potrebne-pro-testovani"},"id":"OF-B7","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 7 (© ISTQB®, překlad CaSQB)"},{"n":8,"lo":"FL-1.5.2","k":"K1","vyber":1,"q":"<p>Které z následujících tvrzení je výhodou týmového přístupu?<\/p>","m":["Umožňuje členům týmu kdykoliv převzít jakoukoliv roli.","K podpoře kompletního vývojového projektu je potřeba pouze jeden tým.","Začleňuje zástupce byznysu a vývojáře do jednoho týmu.","Vytváří týmovou soudržnost (synergii), což prospívá celému projektu."],"ok":[3],"vys":{"a":"Není správně. Týmový přístup znamená, že se jakýkoliv člen týmu s potřebnými dovednostmi a znalostmi může ujmout jakéhokoliv úkolu. To ale neznamená, že může kdykoliv zastat jakoukoliv roli. Obvykle členové týmu přebírají pouze ty role, ve kterých se cítí kompetentní. Nelze obecně říci, že každý člen týmu zvládne jakoukoli roli.","b":"Není správně. Týmový přístup se vztahuje ke způsobu práce jednoho konkrétního týmu (typicky při agilním vývoji softwaru). Nevztahuje se na to, jak má pracovat více týmů na větších projektech a neříká nic o tom, že na celý projekt je zapotřebí pouze jeden „velký“ tým.","c":"Není správně. Týmový přístup nepředpokládá, že každý člen týmu bude zapojen do každého důležitého rozhodnutí. Například není nutné, aby se zástupci byznysu (např. vlastník produktu) podíleli na každém technickém rozhodnutí, které nemá vliv na výsledek z pohledu byznysu. Realizace takového přístupu by naopak zbytečně zpomalovala postup týmu.","d":"Je správně. Týmový přístup co nejefektivněji využívá rozmanité dovednosti každého člena, a tím podporuje lepší týmovou dynamiku, posiluje efektivní komunikaci a spolupráci a vytváří soudržnost (synergii), z níž těží celý projekt."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"},"id":"OF-B8","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 8 (© ISTQB®, překlad CaSQB)"},{"n":9,"lo":"FL-2.1.1","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení o zvoleném životním cyklu vývoje softwaru je SPRÁVNÉ?<\/p>","m":["Pokud se používá agilní vývoj softwaru, automatizace systémových testů nahrazuje potřebu regresního testování.","Pokud se používá sekvenční model vývoje, pak je pro dynamické testování obvykle vyhrazena jeho pozdější fáze.","Pokud se používá iterativní vývojový model, pak je testování komponent obvykle manuálně prováděno vývojáři.","Pokud se používá inkrementální (přírůstkový) vývojový model, pak se statické testování provádí v počátečních přírůstcích a dynamické testování v pozdějších přírůstcích."],"ok":[1],"vys":{"a":"Není správně. Při agilním vývoji softwaru jsou výstupy vytvářeny v každé iteraci a časté dodávání přírůstků vyžaduje rozsáhlé regresní testování. Ačkoli některé (nebo všechny) testy z tohoto regresního testování mohou být automatizované, regresní testování (ať už automatizované nebo manuální) nemůže být nahrazeno automatizací systémových testů.","b":"Je správně. Pokud se používá sekvenční vývojový model, pak není v raných fázích životního cyklu k dispozici žádný spustitelný kód, a proto se během této doby provádí statické testování (např. revize). V pozdějších fázích životním cyklu (kdy už je k dispozici spustitelný kód) je možné provádět dynamické testování. Je nutno ale poznamenat, že příprava na dynamické testování často probíhá právě v těchto raných fázích životního cyklu vývoje softwaru.","c":"Není správně. Pokud se používá iterativní vývojový model (např. agilní vývoj softwaru), pak lze pro regresní testování v každé iteraci použít testy komponent. V takovém případě existuje pádný důvod pro jejich automatizaci, protože budou spouštěny často. Naopak je jen malá pravděpodobnost, že by se našel pádný argument pro to, aby je vývojáři prováděli manuálně.","d":"Není správně. Ve většině modelů inkrementálního vývoje jsou výstupy vytvářeny v každém přírůstku, což vyžaduje statické i dynamické testování ve všech úrovních testování pro každý dodaný přírůstek."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.1","nazev":"Vliv životního cyklu vývoje softwaru na testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-jedna-vliv-zivotniho-cyklu-vyvoje-softwaru-na-testovani"},"id":"OF-B9","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 9 (© ISTQB®, překlad CaSQB)"},{"n":10,"lo":"FL-2.1.2","k":"K1","vyber":1,"q":"<p>Které z následujících tvrzení je příkladem osvědčeného postupu v testování, který platí pro všechny životní cykly vývoje softwaru?<\/p>","m":["Testeři by měli revidovat pracovní produkty v rámci následující fáze vývoje.","Testeři by měli revidovat pracovní produkty, jakmile jsou k dispozici jejich rozpracované verze (drafts).","Testeři by měli revidovat pracovní produkty před zahájením testovací analýzy a návrhu testů.","Testeři by měli pracovní produkty revidovat ihned po jejich vydání."],"ok":[1],"vys":{"a":"Není správně. Testeři by měli revidovat pracovní produkty v okamžiku, kdy jsou k dispozici pracovní verze tak, aby využili včasné testování (jako součást principu shift left). Pokud by čekali do další vývojové fáze, pak by mohly být zahájeny zbytečné vývojové (a testovací) práce na nerevidovaných chybných pracovních produktech.","b":"Je správně. Testeři by měli revidovat pracovní produkty v okamžiku, kdy jsou k dispozici pracovní verze tak, aby využili včasné testování (jako součást principu shift left).","c":"Není správně. Testeři obvykle revidují ty pracovní produkty, které tvoří testovací bázi v rámci testovací analýzy, nikoli před testovací analýzou a návrhem testů.","d":"Není správně. Testeři by měli revidovat pracovní produkty v okamžiku, kdy jsou k dispozici pracovní verze (drafty) tak, aby využili včasné testování (jako součást principu shift left). Čekání na jejich zveřejnění znamená, že všechny defekty, které by mohly být nalezeny pomocí revize, budou ve zveřejněném pracovním produktu."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"},"id":"OF-B10","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 10 (© ISTQB®, překlad CaSQB)"},{"n":11,"lo":"FL-2.1.3","k":"K1","vyber":1,"q":"<p>Která z následujících možností je příkladem přístupu k vývoji iniciovaného testy (test first)?<\/p>","m":["Vývoj řízený testy (TDD).","Vývoj řízený pokrytím.","Vývoj řízený kvalitou.","Vývoj řízený užitnými funkcemi (features)."],"ok":[0],"vys":{"a":"Je správně. Vývoj řízený testováním (TDD) je známým příkladem vývoje iniciovaného testy.","b":"Není správně. Vývoj řízený pokrytím není správným příkladem vývoje iniciovaného testy.","c":"Není správně. Vývoj řízený kvalitou není správným příkladem vývoje iniciovaného testy.","d":"Není správně. Vývoj řízený (užitnými) vlastnostmi není příkladem vývoje iniciovaného testy, ale jedná se o agilní metodiku vývoje softwaru založenou na dodávání užitných vlastností (na rozdíl od uživatelských scénářů ve Scrumu)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"},"id":"OF-B11","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 11 (© ISTQB®, překlad CaSQB)"},{"n":12,"lo":"FL-2.1.4","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení o DevOps je SPRÁVNÉ?<\/p>","m":["Aby se urychlil proces vydávání, používá se průběžná integrace, která vývojáře nabádá k rychlému dodávání kódu bez nutnosti dokončit testování komponent.","Aby bylo možné častěji aktualizovat a vydávat systémy, je zapotřebí mnoho automatizovaných regresních testů s cílem snížit riziko regrese.","Aby testeři přistupovali stejně k vývojářům i zástupcům provozu, navýší pracnost věnovanou testování vydání (releasů) ze strany provozu s využitím principu shift right.","Aby se vytvořila lepší soudržnost (synergie) mezi testery, vývojáři a zástupci provozu, musí být testování plně automatizované (tzn. bez manuálního testování)."],"ok":[1],"vys":{"a":"Není správně. DevOps obohacuje testování několika způsoby, například poskytováním rychlé zpětné vazby o kvalitě kódu, automatizovaným regresním testováním (které minimalizuje riziko regrese) a podporou principu shift left s dodáváním vysoce kvalitního kódu a testů komponent. To je z velké části zajištěno prostřednictvím průběžné integrace, kdy vývojáři dodávají společně se svým novým kódem také testy komponent, které musí projít, jinak není kód akceptován do sestavení (buildu). Vývojáři proto musí dokončit testování komponent.","b":"Je správně. DevOps obohacuje testování několika způsoby, například poskytováním rychlé zpětné vazby o kvalitě kódu, automatizovaným regresním testováním, které minimalizuje riziko regrese, a podporou principu shift left s dodáváním vysoce kvalitního kódu a testů komponent.","c":"Není správně. DevOps obohacuje testování několika způsoby, například poskytováním rychlé zpětné vazby o kvalitě kódu, automatizovaným regresním testováním (které minimalizuje riziko regrese) a podporou principu shift left s dodáváním vysoce kvalitního kódu a testů komponent. Testeři se nesnaží vyvažovat svůj přístup k vývojářům a provozu tím, že by věnovali více času testování vydání, ačkoliv je možné tento princip (tzv. shift right neboli testování v produkci) možné klidně používat.","d":"Není správně. Automatizované procesy, jako je průběžná integrace/průběžné doručování (CI/CD) v DevOps, pomáhají se stabilizací testovacího prostředí a snižují potřebu manuálního testování, existuje však riziko přehlédnutí důležitosti manuálního testování, zejména z pohledu uživatele."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.4","nazev":"DevOps a testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-ctyri-devops-a-testovani"},"id":"OF-B12","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 12 (© ISTQB®, překlad CaSQB)"},{"n":13,"lo":"FL-2.2.1","k":"K2","vyber":1,"q":"<p>Která z následujících možností bude s NEJVĚTŠÍ pravděpodobností provedena v rámci systémového testování?<\/p>","m":["Testování bezpečnosti úvěrového systému nezávislým testovacím týmem.","Testování rozhraní směnárenského systému s externím bankovním systémem.","Beta testování systému pro vzdálenou výuku přímo vývojáři výukového softwaru.","Testování interakcí mezi uživatelským rozhraním a databází systému pro oddělení lidských zdrojů (HR)."],"ok":[0],"vys":{"a":"Je správně. Systémové testování zkoumá chování a schopnosti celého systému a zahrnuje nefunkcionální testování kvalitativních charakteristik, například testování bezpečnosti. Tento typ testování je často prováděn nezávislým testovacím týmem na základě specifikací systému.","b":"Není správně. Systémové integrační testování zkoumá rozhraní s jinými systémy a externími službami.","c":"Není správně. Beta testování je typ akceptačního testování prováděného v externí lokalitě rolemi mimo vývojovou organizaci.","d":"Není správně. Integrační testování komponent zahrnuje testování interakcí mezi komponentami systému, což jsou například uživatelská rozhraní a databáze."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"},"id":"OF-B13","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 13 (© ISTQB®, překlad CaSQB)"},{"n":14,"lo":"FL-2.2.3","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení je SPRÁVNÉ?<\/p>","m":["Počet regresních testů se v průběhu projektu zvyšuje, zatímco počet konfirmačních testů se v průběhu projektu snižuje.","Regresní testy jsou vytvářeny a prováděny při opravách testovaného objektu, zatímco konfirmační testy při jeho vylepšeních.","Regresní testování se zabývá kontrolou, zda provozní prostředí zůstává nezměněno, zatímco konfirmační testování se zabývá testováním změn testovaného objektu.","Regresní testování se zabývá nepříznivými účinky v nezměněném kódu, zatímco konfirmační testování se zabývá testováním změněného kódu."],"ok":[3],"vys":{"a":"Není správně. Počet regresních testů v průběhu projektu roste, protože se změnami v systému jsou obvykle zapotřebí nové regresní testy. Podobně se obvykle zvyšuje také počet konfirmačních testů, protože pro každou opravu systému jsou potřeba nové konfirmační testy.","b":"Není správně. Je to naopak. Konfirmační testy jsou vytvořeny a spuštěny, když je testovaný objekt opravován, a regresní testy jsou (v ideálním případě) spuštěny vždy, když je testovaný objekt rozšiřován (měněn).","c":"Není správně. Konfirmační testování ověřuje, že defekt byl správně opraven, a proto se týká testování změn testovaného objektu. Regresní testování však zajišťuje, aby změny (včetně změn provozního prostředí) neměly negativní vliv na nezměněný software, a proto nekontroluje, zda provozní prostředí zůstává nezměněno.","d":"Je správně. Regresní testování zajišťuje, že změny nebudou mít negativní vliv na nezměněný software. Konfirmační testování ověřuje, že defekt byl opraven, týká se tedy změněného kódu."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"},"id":"OF-B14","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 14 (© ISTQB®, překlad CaSQB)"},{"n":15,"lo":"FL-3.1.3","k":"K2","vyber":1,"q":"<p>Která z následujících možností je příkladem defektu, který lze zjistit statickým testováním, ale NE dynamickým testováním?<\/p>","m":["Nedostatečná použitelnost uživatelského rozhraní.","Nedosažitelný kód.","Vysoká doba odezvy pro většinu uživatelů.","Požadované funkcionality, které ale nejsou implementovány v kódu."],"ok":[1],"vys":{"a":"Není správně. Nedostatečnou použitelnost poskytovanou prostřednictvím uživatelského rozhraní lze zjistit prostřednictvím revize s využitím vhodného kontrolního seznamu. Nedostatečnou použitelnost lze také identifikovat tak, že několik typických uživatelů dynamicky testuje uživatelské rozhraní a poskytuje zpětnou vazbu o jeho použitelnosti.","b":"Je správně. Revize kódu může detekovat kód, který nemůže být žádným způsobem spuštěn (tzv. nedosažitelný kód). Dynamické testy mohou testovat pouze dosažitelný kód a nemohou tedy zjistit, že daný kód nelze spustit při všech možných kombinacích vstupů a stavů vstupů.","c":"Není správně. Špatnou dobu odezvy u většiny očekávaných uživatelů je obtížné určit bez spuštění kódu (tj. statickým testováním), takže v této situaci by dynamické testování defekt najít mohlo, naopak statické testování jej pravděpodobně nenajde.","d":"Není správně. Revize kódu někým, kdo zná požadované funkcionality, by mohla identifikovat, že nebyly implementovány v kódu. Dynamické testování by mohlo být použito ke zjištění, že obecně nebyly implementovány vůbec."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"},"id":"OF-B15","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 15 (© ISTQB®, překlad CaSQB)"},{"n":16,"lo":"FL-3.2.1","k":"K1","vyber":1,"q":"<p>Která z následujících možností je výhodou včasné a časté zpětné vazby zainteresovaných stran?<\/p>","m":["Manažeři mají přehled o méně produktivních vývojářích.","Umožňuje projektovým manažerům upřednostňovat komunikaci se zainteresovanými stranami.","Usnadňuje včasnou komunikaci o potenciálních problémech s kvalitou.","Koncoví uživatelé lépe chápou, proč se dodání pracovního produktu zpožďuje."],"ok":[2],"vys":{"a":"Není správně. Zpětná vazba pochází od zainteresovaných stran (např. zástupců byznysu nebo koncových uživatelů), nikoli od vývojářů, takže pravděpodobně neinformuje manažery o tom, kteří vývojáři jsou více či méně produktivní.","b":"Není správně. Včasnou a častou zpětnou vazbu od zainteresovaných stran nepoužívají projektoví manažeři k tomu, aby upřednostnili způsob, jakým komunikují s různými zainteresovanými stranami.","c":"Je správně. Získání zpětné vazby od zainteresovaných stran včasně a často v procesu vývoje softwaru může být velmi přínosné, protože umožňuje včasnou komunikaci o potenciálních problémech s kvalitou, může zabránit nedorozuměním ohledně požadavků a zajišťuje, že jakékoli změny v požadavcích zainteresovaných stran budou pochopeny a implementovány včas.","d":"Není správně. Včasná a častá zpětná vazba může zabránit vývoji produktu, který nesplňuje potřeby zainteresovaných stran a/nebo vede k nákladnému přepracování a zmeškání termínů. V ideálním případě by tedy nemělo dojít k žádnému zpoždění. Zpětná vazba navíc směřuje od zainteresovaných stran (což jsou také koncoví uživatelé), nikoliv k nim. Samotné poskytování zpětné vazby ze strany uživatelů tedy nezlepšuje jejich vlastní porozumění."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"3.2.1","nazev":"Výhody včasné a časté zpětné vazby od zainteresovaných stran","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-jedna-vyhody-vcasne-a-caste-zpetne-vazby-od-zainteresovanych-stran"},"id":"OF-B16","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 16 (© ISTQB®, překlad CaSQB)"},{"n":17,"lo":"FL-3.2.2","k":"K2","vyber":1,"q":"<p>Předpokládejme následující popis úkolů:<\/p><ol><li>Hodnotí se charakteristiky kvality a vybírají výstupní kritéria.<\/li><li>Každý má přístup k pracovnímu produktu.<\/li><li>Anomálie v pracovním produktu jsou identifikovány.<\/li><li>Anomálie jsou diskutovány.<\/li><\/ol><p>Dále předpokládejme tyto činnosti procesu revize:<\/p><ol type=\"A\"><li>Individuální revize.<\/li><li>Zahájení revize.<\/li><li>Plánování.<\/li><li>Komunikace a analýza.<\/li><\/ol><p>Která z následujících možností NEJLÉPE přiřazuje popisy úkolů k činnostem?<\/p>","m":["1B, 2C, 3D, 4A","1B, 2D, 3C, 4A","1C, 2A, 3B, 4D","1C, 2B, 3A, 4D"],"ok":[3],"vys":{"a":"Není správně.","b":"Není správně.","c":"Není správně.","d":"Je správně. Správná kombinace je: 1C, 2B, 3A, 4D"},"obecne":"<p>S ohledem na každý z uvedených popisů úkolů platí, že:<\/p><ol><li>Jsou vybrány hodnocené kvalitativní charakteristiky a výstupní kritéria. Plánování (C): Definování rozsahu revize, účelu, pracovního produktu, který má být přezkoumán, kvalitativních charakteristik, které mají být hodnoceny, oblastí zaměření, výstupních kritérií, podpůrných informací, což jsou např. normy, pracnost a časové rámce.<\/li><li>Každý má přístup k pracovnímu produktu. Zahájení revize (B): Zajistit, aby všichni účastníci měli přístup k pracovnímu produktu a potřebným zdrojům, a vyjasnit jejich role a odpovědnosti.<\/li><li>Anomálie v pracovním produktu jsou identifikovány. Individuální revize (A): Vyhodnocení kvality pracovního produktu, identifikace a zaznamenání anomálií, doporučení a otázek pomocí technik revize jako je revize založená na kontrolních seznamech a revize založená na scénářích.<\/li><li>Anomálie jsou analyzovány a diskutovány. Komunikace a analýza (D): Analýza a diskuze o každé anomálii, určení jejího stavu, vlastnictví a požadovaných akcí, a učinit rozhodnutí při revizi, obvykle na schůzce. To by mohlo zahrnovat určení potřeby následné revize.<\/li><\/ol><p>Tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"3.2.2","nazev":"Činnosti procesu revize","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-dva-cinnosti-procesu-revize"},"id":"OF-B17","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 17 (© ISTQB®, překlad CaSQB)"},{"n":18,"lo":"FL-3.2.3","k":"K1","vyber":1,"q":"<p>Předpokládejme následující role v procesu revize:<\/p><ol><li>Zapisovatel.<\/li><li>Vedoucí revize.<\/li><li>Moderátor (facilitátor).<\/li><li>Manažer.<\/li><\/ol><p>Dále předpokládejme následující seznam zodpovědností:<\/p><ol type=\"A\"><li>Zajišťuje efektivní průběh revizních schůzek a nastavení komfortního prostředí pro revize.<\/li><li>Zaznamenává informace o revizi, jako jsou různá rozhodnutí a nové anomálie zjištěné během revizní schůzky.<\/li><li>Rozhoduje o tom, co má být revidováno, a rozhoduje o zdrojích, jako jsou lidé nebo čas.<\/li><li>Přebírá celkovou odpovědnost za revizi, například organizuje, kdy a kde se bude revize konat.<\/li><\/ol><p>Která z následujících možností NEJLÉPE přiřazuje role k zodpovědnostem?<\/p>","m":["1A, 2B, 3D, 4C","1A, 2C, 3B, 4D","1B, 2D, 3A, 4C","1B, 2D, 3C, 4A"],"ok":[2],"vys":{"a":"Není správně.","b":"Není správně.","c":"Je správně. Správná kombinace je: 1B, 2D, 3A, 4C.","d":"Není správně."},"obecne":"<p>S ohledem na každou z uvedených rolí platí, že:<\/p><ol><li>Zapisovatel – zodpovídá za shromažďování zpětné vazby od revidujících a zdokumentování informací o revizi jako jsou učiněná rozhodnutí a jakékoli nové anomálie zjištěné během revizní schůzky. B: Zaznamenává informace o revizi, jako jsou rozhodnutí a nové anomálie zjištěné během revizní schůzky.<\/li><li>Vedoucí revize – zodpovídá za dohled nad procesem revize jako je výběr členů revizního týmu, plánování revizních schůzek a zajištění úspěšného dokončení revize. D: Přebírá celkovou odpovědnost za revizi, například organizuje, kdy a kde se bude revize konat.<\/li><li>Facilitátor (nebo moderátor) - odpovídá za zajištění efektivního průběhu revizních schůzek včetně řízení času, vedení diskusí a vytvoření komfortního prostředí, kde může každý svobodně vyjádřit svůj názor. A: Zajišťuje efektivní průběh revizních schůzek a nastavení komfortního prostředí pro revizi.<\/li><li>Manažer – odpovídá za rozhodování o tom, co je třeba revidovat, a za přidělování zdrojů pro revizi (např. lidé nebo čas. C: Manažer – rozhoduje o tom, co má být revidováno, a rozhoduje o zdrojích jako jsou lidé nebo čas.<\/li><\/ol><p>Tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"},"id":"OF-B18","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 18 (© ISTQB®, překlad CaSQB)"},{"n":19,"lo":"FL-4.1.1","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje rozdíl mezi testováním dle rozhodovací tabulky a testováním větví?<\/p>","m":["Při testování dle rozhodovací tabulky jsou testovací případy odvozeny z rozhodovacích příkazů v kódu. Při testování větví jsou testovací případy odvozeny ze znalosti řídicího toku testovaného objektu.","Při testování dle rozhodovací tabulky jsou testovací případy odvozeny ze specifikace popisující byznysovou logiku. Při testování větví jsou testovací případy založeny na předvídání potenciálních defektů ve zdrojovém kódu.","Při testování dle rozhodovací tabulky jsou testovací případy odvozeny ze znalosti řídicího toku testovaného objektu. Při testování větví jsou testovací případy odvozeny ze specifikace popisující byznysovou logiku.","Při testování dle rozhodovací tabulky jsou testovací případy nezávislé na tom, jak je software implementován. Při testování větví lze testovací případy vytvořit až po návrhu nebo implementaci kódu."],"ok":[3],"vys":{"a":"Není správně. Testování dle rozhodovací tabulky je technika testování černé skříňky, nikoli technika testování bílé skříňky. Testovací případy nejsou tedy založeny na rozhodnutích ve zdrojovém kódu. Při testování větví jsou testovací případy odvozeny ze znalosti řídicích toků testovaného objektu.","b":"Není správně. Předvídání potenciálních defektů se používá při odhadování chyb (technika testování založená na zkušenostech), nikoli při testování větví (technika testování bílé skříňky). Při testování dle rozhodovací tabulky jsou testovací případy odvozeny ze specifikace, která popisuje byznysovou logiku.","c":"Není správně. Pokud je testovací případ založen na znalosti řídicího toku testovaného objektu, jedná se o techniku testování bílé skříňky. Testování dle rozhodovací tabulky je obvykle založeno na analýze byznysové logiky, jedná se tedy o techniku testování černé skříňky. Při testování větví nejsou testovací případy odvozeny ze specifikace – to by z něj udělalo techniku testování černé skříňky. Testování větví je technika testování bílé skříňky, kdy jsou testovací případy odvozeny na základě struktury zdrojového kódu.","d":"Je správně. Testování dle rozhodovací tabulky je technika testování černé skříňky, takže je založena na analýze specifikovaného chování testovaného objektu bez odkazu na jeho vnitřní strukturu. Testovací případy jsou tedy nezávislé na tom, jak je software implementován. Testování větví je technika testování bílé skříňky, takže testovací případy jsou založeny na analýze vnitřní struktury a procesů testovaného objektu. Vzhledem k tomu, že testovací případy jsou závislé na návrhu a implementaci daného softwaru, mohou být vytvořeny pouze po jeho ukončení nebo po jeho implementaci (pokud není použita technika TDD)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"},"id":"OF-B19","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 19 (© ISTQB®, překlad CaSQB)"},{"n":20,"lo":"FL-4.2.1","k":"K3","vyber":1,"q":"<p>Zákazníci sítě mycích linek TestWash mohou využít věrnostní karty se záznamy o počtu provedených mytí. Počáteční hodnota je 0. Po vjezdu do myčky systém zvýší číslo na kartě o jednu. Tato hodnota představuje číslo aktuálního mytí. Na základě tohoto čísla systém rozhodne, na jakou slevu má zákazník nárok.<\/p><p>Pro každé desáté mytí poskytuje systém 10% slevu a pro každé dvacáté mytí další 40% slevu (tj. 50% slevu celkem).<\/p><p>Která z následujících sad vstupních dat (chápaná jako čísla aktuálního mytí) dosahuje nejvyššího pokrytí tříd ekvivalence?<\/p>","m":["19, 20, 30","11, 12, 20","1, 10, 50","10, 29, 30, 31"],"ok":[0],"vys":{"a":"Je správně. 19 pokrývá třídu \"bez slevy\", 20 pokrývá třídu \"50 % sleva\" a 30 pokrývá třídu \"10 % sleva\". Tyto tři hodnoty pokrývají všechny tři platné třídy ekvivalence.","b":"Není správně. 11 a 12 pokrývají třídu \"bez slevy\", zatímco 20 pokrývá třídu \"50 % sleva\", takže celkově pokrývají dvě ze tří platných tříd ekvivalence.","c":"Není správně. 1 pokrývá třídu \"bez slevy\", zatímco 10 a 50 pokrývají třídu \"10 % sleva\". Třída \"50 % sleva\" není pokryta, takže celkově jsou pokryty dvě ze tří platných tříd ekvivalence.","d":"Není správně. 29 a 31 pokrývají třídu \"bez slevy\", zatímco 10 a 30 pokrývají třídu \"10 % sleva\". Třída \"50 % sleva\" není pokryta, takže celkově jsou pokryty dvě ze tří platných tříd ekvivalence."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"},"id":"OF-B20","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 20 (© ISTQB®, překlad CaSQB)"},{"n":21,"lo":"FL-4.2.2","k":"K3","vyber":1,"q":"<p>Testujete formulář, který ověřuje správnost délky zadaného hesla. Formulář akceptuje heslo se správnou délkou a odmítne heslo, které je příliš krátké nebo příliš dlouhé. Délka hesla je správná, pokud má 6 až 12 znaků včetně. Ostatní případy jsou považovány za nesprávné.<\/p><p>Formulář je nejprve prázdný (délka hesla = 0). Na proměnnou \"délka hesla\" aplikujete analýzu hraničních hodnot (BVA).<\/p><p>Vaše sada testovacích případů dosáhne 100% pokrytí 2-hodnotové analýzy hraničních hodnot. Tým se rozhodl, že vzhledem k vysokému riziku této komponenty by měly být přidány takové testovací případy, aby bylo zajištěno 100% pokrytí 3-hodnotové BVA.<\/p><p>Jaké další délky hesel by měly být testovány, aby toho bylo dosaženo?<\/p>","m":["4, 5, 13, 14","7, 11","1, 5, 13","1, 4, 7, 11, 14"],"ok":[3],"vys":{"a":"Není správně.","b":"Není správně.","c":"Není správně.","d":"Je správně."},"obecne":"<p>Obor hodnot pro délku hesla má tři třídy ekvivalence:<\/p><ul><li>hesla příliš krátká {0, 1, ..., 4, 5}<\/li><li>správná hesla {6, 7, ..., 11, 12}<\/li><li>hesla příliš dlouhá {13, 14, ...}<\/li><\/ul><p>Abychom dosáhli plného pokrytí pro 3-hodnotovou BVA, musíme otestovat následující hodnoty:<\/p><p style=\"margin-left:2em\">0, 1, 4, 5, 6, 7, 11, 12, 13, 14.<\/p><p>Vzhledem k tomu, že 2-hodnotová BVA je již pokryta, znamená to, že jsme již otestovali hesla délky:<\/p><p style=\"margin-left:2em\">0, 5, 6, 12 a 13.<\/p><p>To znamená, že další délky, které je potřeba pokrýt, aby bylo možné přejít z 2-hodnotové na 3-hodnotovou BVA, jsou:<\/p><p style=\"margin-left:2em\">1, 4, 7, 11 a 14.<\/p><p>Tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"},"id":"OF-B21","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 21 (© ISTQB®, překlad CaSQB)"},{"n":22,"lo":"FL-4.2.3","k":"K3","vyber":1,"q":"<p>Následující rozhodovací tabulka obsahuje pravidla pro stanovení rizika aterosklerózy.<\/p><table><thead><tr><th><\/th><th>Pravidlo 1<\/th><th>Pravidlo 2<\/th><th>Pravidlo 3<\/th><th>Pravidlo 4<\/th><th>Pravidlo 5<\/th><\/tr><\/thead><tbody><tr><th colspan=\"6\" style=\"text-align:left\">Podmínky<\/th><\/tr><tr><th style=\"text-align:right\">Cholesterol [mg/dl]<\/th><td>≤ 124<\/td><td>≤ 124<\/td><td>125 – 200<\/td><td>125 – 200<\/td><td>≥ 201<\/td><\/tr><tr><th style=\"text-align:right\">Krevní tlak [mm Hg]<\/th><td>≤ 140<\/td><td>&gt; 140<\/td><td>≤ 140<\/td><td>&gt; 140<\/td><td>–<\/td><\/tr><tr><th colspan=\"6\" style=\"text-align:left\">Akce<\/th><\/tr><tr><th style=\"text-align:right\">Úroveň rizika<\/th><td>velmi nízká<\/td><td>nízká<\/td><td>střední<\/td><td>vysoká<\/td><td>velmi vysoká<\/td><\/tr><\/tbody><\/table><p>Navrhli jste testovací případy (TC) s následujícími vstupními daty:<\/p><table><tbody><tr><td>TC1:<\/td><td>Cholesterol = 125 mg/dl<\/td><td>Krevní tlak = 141 mm Hg<\/td><\/tr><tr><td>TC2:<\/td><td>Cholesterol = 200 mg/dl<\/td><td>Krevní tlak = 201 mm Hg<\/td><\/tr><tr><td>TC3:<\/td><td>Cholesterol = 124 mg/dl<\/td><td>Krevní tlak = 201 mm Hg<\/td><\/tr><tr><td>TC4:<\/td><td>Cholesterol = 109 mg/dl<\/td><td>Krevní tlak = 200 mm Hg<\/td><\/tr><tr><td>TC5:<\/td><td>Cholesterol = 201 mg/dl<\/td><td>Krevní tlak = 140 mm Hg<\/td><\/tr><\/tbody><\/table><p>Jakého pokrytí rozhodovací tabulky dosáhnou tyto testovací případy?<\/p>","m":["40 %","60 %","80 %","100 %"],"ok":[1],"vys":{"a":"Není správně.","b":"Je správně.","c":"Není správně.","d":"Není správně."},"obecne":"<p>V rozhodovací tabulce je pět sloupců. Každý testovací případ pokrývá jeden z nich.<\/p><p style=\"margin-left:2em\">TC1 a TC2 pokrývají Pravidlo 4.<\/p><p style=\"margin-left:2em\">TC3 a TC4 pokrývají Pravidlo 2.<\/p><p style=\"margin-left:2em\">TC5 pokrývá Pravidlo 5.<\/p><p>Těchto pět testovacích případů tedy pokrývá tři z pěti sloupců a dosahuje pokrytí (3/5)*100 % = 60 %. Proto je správně možnost b).<\/p><p>Tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"},"id":"OF-B22","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 22 (© ISTQB®, překlad CaSQB)"},{"n":23,"lo":"FL-4.2.4","k":"K3","vyber":1,"q":"<p>Úložný systém, jehož model je zobrazen níže ve formě stavového diagramu může ukládat až tři prvky. Proměnná N představuje počet aktuálně uložených prvků.<\/p><p><img src=\"assets/vzorove/b-23.png\" alt=\"Stavový diagram úložného systému: stavy START, ZAPLNĚN a NENÍ ZAPLNĚN s přechody Přidat a Odebrat\"><\/p><p>Který z následujících testovacích případů (reprezentovaných jako sekvence událostí) dosahuje nejvyšší úrovně pokrytí platných přechodů?<\/p>","m":["Přidat, odebrat, přidat, přidat, přidat.","Přidat, přidat, přidat, přidat, odebrat, odebrat.","Přidat, přidat, přidat, odebrat, odebrat.","Přidat, přidat, přidat, odebrat, přidat."],"ok":[2],"vys":{"a":"Není správně.","b":"Není správně.","c":"Je správně.","d":"Není správně."},"obecne":"<p><img src=\"assets/vzorove/b-23-vysvetleni.png\" alt=\"Stavový diagram s označenými přechody E1 až E5\"><\/p><p>Označme přechody E1 – E5 (viz obrázek). Proměnná N označuje počet aktuálně uložených prvků. Každá událost \"Přidat\" ji zvyšuje o 1 a každá událost \"Odebrat\" ji snižuje o 1. Pokud dojde k události \"Přidat\" ve stavu NENÍ ZAPLNĚN, stav se změní na ZAPLNĚN pouze v případě, že N=2. Pokud je N&lt;2, systém zůstane ve stavu NENÍ ZAPLNĚN. Pokud N=0, není možná žádná akce \"Odebrat\". Podobně, pokud N=3, není možná žádná akce \"Přidat\".<\/p><p style=\"margin-left:2em\">Test a) lze zapsat jako E1, E3, E3, E2, E4 (pokrývá tedy 4 z 5 platných přechodů a dosahuje 80% pokrytí platných přechodů).<\/p><p style=\"margin-left:2em\">Test b) je neproveditelný, protože po prvních třech akcích \"Přidat\" je systém ve stavu ZAPLNĚN a nedochází k platnému přechodu ze ZAPLNĚN vyvolanému událostí \"Přidat\". Po prvních třech přechodech je dosaženo pouze 60% pokrytí platných přechodů.<\/p><p style=\"margin-left:2em\">Test c) lze zapsat jako E1, E2, E4, E5, E3 (pokrývá tedy 5 z 5 platných přechodů, čímž dosahuje 100% pokrytí platných přechodů).<\/p><p style=\"margin-left:2em\">Test d) lze zapsat jako E1, E2, E4, E5, E4 (pokrývá tedy 4 z 5 platných přechodů, dosahuje 80% pokrytí platných přechodů).<\/p><p>Tedy:<\/p>","pozn":"v obrázku z českého překladu jsou prohozené popisky dvou stavů. Podle anglického originálu je prostřední stav (se smyčkami „Přidat [N &lt; 2]“ a „Odebrat“) <em>NENÍ ZAPLNĚN<\/em> a pravý stav <em>ZAPLNĚN<\/em>; podmínka u dolní smyčky má znít „[N &gt; 0]“.","pozn_vyh":"","kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"},"id":"OF-B23","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 23 (© ISTQB®, překlad CaSQB)"},{"n":24,"lo":"FL-4.3.1","k":"K2","vyber":1,"q":"<p>Spouštíte dva testovací případy T1 a T2, oba na stejném kódu. Test T1 dosáhl 40% pokrytí příkazů a test T2 dosáhl 65% pokrytí příkazů.<\/p><p>Které z následujících tvrzení musí být nutně pravdivé?<\/p>","m":["Testovací sada složená z testů T1 a T2 dosahuje 105% pokrytí příkazů.","Existuje alespoň jeden příkaz, který byl spuštěn pomocí T1 i T2.","Alespoň 5 % příkazů v testovaném kódu je nespustitelných.","Testovací sada složená z testů T1 a T2 dosahuje plného pokrytí větví."],"ok":[1],"vys":{"a":"Není správně. Pokrytí je vždy definováno jako procento pokrytých prvků, proto nemůže překročit 100 %.","b":"Je správně. Pokud by příkazy prováděné T1 a T2 byly disjunktní, pokrytí testovací sadou {T1, T2} by bylo 105 %, což je nemožné (viz odpověď a). Proto musí být alespoň 5 % spustitelných příkazů provedeno T1 i T2.","c":"Není správně. Pokrytí příkazů nám neříká nic o počtu nespustitelných příkazů v kódu.","d":"Není správně. I v případě, že testovací sada dosáhne úplného pokrytí příkazů, neznamená to, že dosáhne úplného pokrytí větví."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"},"id":"OF-B24","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 24 (© ISTQB®, překlad CaSQB)"},{"n":25,"lo":"FL-4.3.2","k":"K2","vyber":1,"q":"<p>Nechť je metrika pokrytí větví definována jako BCov = (X / Y) * 100 %.<\/p><p>Co představují X a Y v tomto vzorci?<\/p>","m":["X = počet výsledků rozhodnutí pokrytých testovacími případy,<br>Y = celkový počet výsledků rozhodnutí v kódu.","X = počet podmíněných větví pokrytých testovacími případy,<br>Y = celkový počet větví v kódu.","X = počet větví pokrytých testovacími případy,<br>Y = celkový počet větví v kódu.","X = počet podmíněných větví pokrytých testovacími případy,<br>Y = celkový počet výsledků rozhodnutí v kódu."],"ok":[2],"vys":{"a":"Není správně. Výsledek rozhodnutí je podmíněná větev. Pro testování větví se do X započítávají nejen podmíněné, ale i nepodmíněné větve.","b":"Není správně. Pokrytí větví počítá nejen podmíněné, ale i nepodmíněné větve.","c":"Je správně. Pokrytí se měří jako počet větví pokrytých testy k celkovému počtu větví (obvykle vyjádřeno v procentech).","d":"Není správně. X i Y počítají pouze podmíněné větve a neberou v úvahu nepodmíněné větve."},"obecne":"<p>Testování větví je technika testování bílé skříňky, ve které jsou položkami pokrytí větve. Větev je přenos řízení mezi dvěma uzly v grafu řídicího toku zobrazujícího možné sekvence, ve kterých jsou příkazy zdrojového kódu v testovacím objektu prováděny. Každý přenos řízení může být buď nepodmíněný (tj. lineární kód) nebo podmíněný (tj. výsledek rozhodnutí). Pokrytí se měří jako počet větví pokrytých testy k celkovému počtu větví (obvykle vyjádřeno v procentech).<\/p><p>Tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"},"id":"OF-B25","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 25 (© ISTQB®, překlad CaSQB)"},{"n":26,"lo":"FL-4.4.2","k":"K2","vyber":2,"q":"<p>Která DVĚ z následujících tvrzení poskytují NEJLEPŠÍ zdůvodnění pro použití průzkumného testování?<\/p>","m":["Testeři neměli dostatek času na návrh a provedení testů.","Stávající strategie testování vyžaduje, aby testeři používali formální techniky testování černé skříňky.","Specifikace je napsána ve formálním jazyce, který může být zpracován softwarovým nástrojem.","Testeři jsou členy agilního týmu a mají dobré programátorské dovednosti.","Testeři mají zkušenosti z daného odvětví (domény) a dobré analytické schopnosti."],"ok":[0,4],"vys":{"a":"Je správně. Průzkumné testování je nejvíce užitečné v případech, kdy je specifikace nedostatečná nebo úplně chybí, taktéž je vhodnou metodou v případě výrazného časového tlaku na testování.","b":"Není správně. Průzkumné testování není technikou testování černé skříňky.","c":"Není správně. Průzkumné testování je užitečné, když jsou specifikace napsané špatně.","d":"Není správně. Programátorské dovednosti v zásadě nemají s průzkumným testováním nic společného.","e":"Je správně. Průzkumné testování bude účinnější v případech, kdy je tester zkušený, má znalosti z daného odvětví a vysokou úroveň klíčových dovedností jako jsou analytické schopnosti, zvídavost a kreativita."},"obecne":"<p>Průzkumné testování je nejvíce užitečné v případech, kdy je specifikace nedostatečná nebo úplně chybí, taktéž je vhodnou metodou v případě výrazného časové tlaku na testování. Průzkumné testování je také výhodné jako doplněk jiných (formálnějších) technik testování. Průzkumné testování bude účinnější v případech, kdy je tester zkušený, má znalosti z daného odvětví a vysokou úroveň klíčových dovedností jako jsou analytické schopnosti, zvídavost a kreativita.<\/p><p>Tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.4.2","nazev":"Průzkumné testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-dva-pruzkumne-testovani"},"id":"OF-B26","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 26 (© ISTQB®, překlad CaSQB)"},{"n":27,"lo":"FL-4.4.3","k":"K2","vyber":1,"q":"<p>Která z následujících možností se NEJLÉPE hodí jako prvek seznamu používaného při testování založeném na kontrolních seznamech?<\/p>","m":["Vývojář udělal chybu při implementaci kódu.","Dosažené pokrytí příkazů přesahuje 85 %.","Program funguje správně co se týče funkcionálních a nefunkcionálních požadavků.","Chybové zprávy jsou psány jazykem, kterému uživatel porozumí."],"ok":[3],"vys":{"a":"Není správně. Kontrolní seznamy by měly obsahovat testovací podmínky, které mají být ověřeny. Tato odpověď je příkladem chyby, nikoli testovací podmínky. I kdyby byl tester schopen odvodit některé možné testovací podmínky z možných chyb, je tento popis chyby i tak příliš obecný.","b":"Není správně. Kontrolní seznamy by neměly obsahovat položky, které jsou vhodnější jako výstupní kritéria. Tato odpověď je příkladem výstupního kritéria.","c":"Není správně. Kontrolní seznamy by neměly obsahovat položky, které jsou příliš obecné. Tato odpověď je velmi obecná věta, která vlastně popisuje cíl testování.","d":"Je správně. Toto je příklad testovací podmínky, kterou může prověřit člověk."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.4.3","nazev":"Testování založené na kontrolních seznamech","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-tri-testovani-zalozene-na-kontrolnich-seznamech"},"id":"OF-B27","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 27 (© ISTQB®, překlad CaSQB)"},{"n":28,"lo":"FL-4.5.2","k":"K2","vyber":1,"q":"<p>Uvažujme následující akceptační kritéria uživatelského scénáře napsaná z pohledu vlastníka internetového obchodu.<\/p><p><em>GIVEN uživatel je přihlášen a je na domovské stránce<\/em><\/p><p><em>WHEN uživatel klikne na tlačítko \"Přidat položku\"<\/em><\/p><p><em>THEN objeví se formulář \"Vytvořit položku\"<\/em><\/p><p><em>AND uživatel je schopen zadat název a cenu nové položky<\/em><\/p><p>V jakém formátu jsou tato akceptační kritéria napsána?<\/p>","m":["S orientací na pravidla.","S orientací na scénáře.","S orientací na produkt.","S orientací na proces."],"ok":[1],"vys":{"a":"Není správně. Formát orientovaný na pravidla zahrnuje formáty, jako jsou ověřovací seznamy (checklisty) ve formě odrážek nebo tabulky mapující vstupy na výstupy zobrazující explicitně pravidla, která je třeba dodržovat. Given/When/Then je formát orientovaný na scénáře, protože popisuje scénář, který má být ověřen.","b":"Je správně. Jedná se o formát Given/When/Then, který je orientován na scénáře.","c":"Není správně. Neexistuje žádný formát akceptačních kritérií orientovaný na produkt.","d":"Není správně. Neexistuje žádný formát akceptačních kritérií orientovaný na proces."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"},"id":"OF-B28","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 28 (© ISTQB®, překlad CaSQB)"},{"n":29,"lo":"FL-4.5.3","k":"K3","vyber":1,"q":"<p>Váš tým analyzuje následující uživatelský scénář s cílem definovat akceptační kritéria:<\/p><p><em>JAKO registrovaný zákazník CHCI mít možnost prohlížet si své předchozí objednávky na webových stránkách společnosti, ABYCH měl přehled o svých nákupech.<\/em><\/p><p>Který z následujících testovacích případů NENÍ pro tento uživatelský scénář relevantní?<\/p>","m":["Vstup: zákazník se přihlásí ke svému účtu na webových stránkách a klikne na tlačítko \"Zobrazit historii objednávek\".<br>Očekávaný výsledek: systém zobrazí seznam všech předchozích objednávek zákazníka včetně data, čísla objednávky a celkové ceny.","Vstup: zákazník klikne na objednávku ze seznamu objednávek.<br>Očekávaný výsledek: systém zobrazí jednotlivé nakoupené položky, jejich ceny a množství.","Vstup: zákazník klikne na tlačítko \"Seřadit vzestupně\" na stránce historie objednávek.<br>Očekávaný výsledek: systém zobrazí historii objednávek seřazenou vzestupně podle čísla objednávky.","Vstup: neregistrovaný zákazník se zaregistruje jako nový zákazník s platnou e-mailovou adresou, která ještě neexistuje v databázi zákazníků.<br>Očekávaný výsledek: systém přijme registraci a vytvoří účet."],"ok":[3],"vys":{"a":"Není správně. Testovací případ souvisí se zobrazením předchozích objednávek v historii objednávek.","b":"Není správně. Testovací případ souvisí se zobrazením předchozích objednávek.","c":"Není správně. Testovací případ souvisí se zobrazením předchozích objednávek v historii objednávek.","d":"Je správně. Testovací případ souvisí s procesem registrace, který ale není v tomto uživatelském scénáři popisován (tento uživatelský scénář popisuje zobrazení předchozích objednávek)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"},"id":"OF-B29","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 29 (© ISTQB®, překlad CaSQB)"},{"n":30,"lo":"FL-5.1.3","k":"K2","vyber":1,"q":"<p>Váš tým postupuje podle procesu, který používá DevOps pipeline. První tři kroky tohoto procesu jsou:<\/p><ul style=\"list-style:none\"><li>(1) Vývoj kódu.<\/li><li>(2) Odeslání kódu do systému pro správu verzí a jeho sloučení (merge) do větve \"Test\".<\/li><li>(3) Provedení testování komponent pro odeslaný kód.<\/li><\/ul><p>Která z následujících možností je NEJVHODNĚJŠÍ jako vstupní kritérium pro krok (2) této pipeline?<\/p>","m":["Statická analýza odeslaného kódu nevrací žádná varování s vysokou závažností.","Systém pro správu verzí nehlásí žádné konflikty při sloučení kódu do větve \"Test\".","Testy komponent jsou sestaveny (zkompilovány) a připraveny ke spuštění.","Pokrytí příkazů je minimálně 80 %."],"ok":[0],"vys":{"a":"Je správně. To je něco, co může (a mělo by) být zkontrolováno před odesláním kódu do repozitáře.","b":"Není správně. To je něco, co lze zkontrolovat po provedení kroku (2), protože hlášení konfliktů při sloučení lze provést po odeslání a sloučení kódu.","c":"Není správně. To se lépe hodí jako vstupní kritérium pro krok (3).","d":"Není správně. To se lépe hodí jako výstupní kritérium pro krok (3)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"},"id":"OF-B30","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 30 (© ISTQB®, překlad CaSQB)"},{"n":31,"lo":"FL-5.1.4","k":"K3","vyber":1,"q":"<p>Chcete odhadnout pracnost potřebnou pro testování nového projektu pomocí odhadu založeného na poměrech. Hodnotu poměru pracnosti vývoje a testování vypočítáte na základě zprůměrovaných dat ze čtyř již realizovaných projektů podobných novému projektu. Tato historická data jsou uvedena v následující tabulce:<\/p><table><thead><tr><th>Projekt<\/th><th>Pracnost vývoje [Kč]<\/th><th>Pracnost testování [Kč]<\/th><\/tr><\/thead><tbody><tr><th>P1<\/th><td>800 000<\/td><td>40 000<\/td><\/tr><tr><th>P2<\/th><td>1 200 000<\/td><td>130 000<\/td><\/tr><tr><th>P3<\/th><td>600 000<\/td><td>70 000<\/td><\/tr><tr><th>P4<\/th><td>1 000 000<\/td><td>120 000<\/td><\/tr><\/tbody><\/table><p>Odhadované náklady (pracnost) na vývoj nového projektu jsou 800 000 Kč. Jaký je váš odhad pracnosti testování v tomto projektu?<\/p>","m":["40 000 Kč","80 000 Kč","81 250 Kč","82 500 Kč"],"ok":[1],"vys":{"a":"Není správně.","b":"Je správně.","c":"Není správně.","d":"Není správně."},"obecne":"<p>Průměrná pracnost vývoje je 900 000 Kč a průměrná pracnost testování je 90 000 Kč (počítáno ze čtyř projektů).<br>Průměrný poměr pracnosti mezi testováním a vývojem je 1:10 (90 000 Kč : 900 000 Kč), což znamená, že historicky tvoří testování v průměru 10 % pracnosti vývoje.<br>Pokud se tedy pracnost vývoje odhaduje na 800 000 Kč, pracnost testování se odhaduje takto:<\/p><p style=\"margin-left:2em\">10% * 800 000 Kč = 0,1 * 800 000 Kč = 80 000 Kč.<\/p><p>Tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"},"id":"OF-B31","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 31 (© ISTQB®, překlad CaSQB)"},{"n":32,"lo":"FL-5.1.5","k":"K3","vyber":1,"q":"<p>Testujete webovou aplikaci, která uživatelům umožňuje VYHLEDAT produkty, ZOBRAZIT podrobnosti o produktech, PŘIDAT produkty do nákupního košíku a VYTVOŘIT objednávku.<\/p><p>Připravili jste následujících sedm testovacích případů (TC), které chcete všechny provést. Testy by měly být spouštěny v optimálním pořadí na základě jejich priority (1 = nejvyšší priorita):<\/p><table><thead><tr><th><\/th><th>Test<\/th><th>Priorita<\/th><\/tr><\/thead><tbody><tr><th>TC1<\/th><td>VYHLEDAT produkt A<\/td><td>4<\/td><\/tr><tr><th>TC2<\/th><td>VYHLEDAT produkt B<\/td><td>4<\/td><\/tr><tr><th>TC3<\/th><td>ZOBRAZIT podrobnosti o produktu A<\/td><td>3<\/td><\/tr><tr><th>TC4<\/th><td>ZOBRAZIT podrobnosti o produktu B<\/td><td>2<\/td><\/tr><tr><th>TC5<\/th><td>PŘIDAT produkt A do nákupního košíku<\/td><td>3<\/td><\/tr><tr><th>TC6<\/th><td>PŘIDAT produkt B do nákupního košíku<\/td><td>1<\/td><\/tr><tr><th>TC7<\/th><td>VYTVOŘIT objednávku<\/td><td>5<\/td><\/tr><\/tbody><\/table><p>Identifikovali jste také následující logické závislosti mezi testovacími případy:<\/p><ul><li>Funkcionalita VYHLEDAT musí být otestována před funkcionalitou ZOBRAZIT.<\/li><li>Funkcionalita ZOBRAZIT musí být otestována před funkcionalitou PŘIDAT.<\/li><li>Funkcionalita PŘIDAT musí být otestována před funkcionalitou VYTVOŘIT objednávku.<\/li><\/ul><p>Který testovací případ by měl být proveden jako čtvrtý?<\/p>","m":["TC3","TC1","TC7","TC2"],"ok":[1],"vys":{"a":"Není správně. TC1 musí být proveden před TC3.","b":"Je správně.","c":"Není správně. Jak je uvedeno výše, TC7 je v provedení testů poslední.","d":"Není správně. Produkt B musí být proveden před produktem A."},"obecne":"<p>Podle závislostí musí být nejprve provedeny testy VYHLEDAT, ZOBRAZIT a PŘIDAT, a to před provedením VYTVOŘIT. Před spuštěním VYTVOŘIT je možné přidat více produktů (použitím stejného postupu).<br>Na základě toho musí být TC1 nebo TC2 proveden jako první.<br>Prvními testy by měly být ZOBRAZIT a PŘIDAT produkt B, protože jeho testovací případy (TC6, TC4) mají přiřazenou vyšší prioritu.<br>První 3 testy k provedení jsou tedy TC2 -&gt; TC4 -&gt; TC6.<\/p><p>Nyní musíme zvážit, zda spustit TC7 a poté celý průběh pro produkt A, nebo nejprve spustit všechny testy pro produkt A. Pokud má TC7 nižší prioritu než ostatní testy, měly by být tyto testy provedeny jako první.<br>Proto by celý postup měl být:<br>TC2 -&gt; TC4 -&gt; TC6 -&gt; TC1 -&gt; TC3 -&gt; TC5 -&gt; TC7.<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"},"id":"OF-B32","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 32 (© ISTQB®, překlad CaSQB)"},{"n":33,"lo":"FL-5.1.7","k":"K2","vyber":1,"q":"<p>Která z následujících možností spadá podle modelu testovacích kvadrantů do kvadrantu Q1 (tj. zaměřené na technologii a podporující tým)?<\/p>","m":["Testování použitelnosti.","Funkcionální testování.","Uživatelské akceptační testování.","Integrační testování komponent."],"ok":[3],"vys":{"a":"Není správně. Testování použitelnosti je testování zaměřené na byznys a kritiku produktu (Q3).","b":"Není správně. Funkcionální testování je testování zaměřené na byznys a podporující tým (Q2).","c":"Není správně. Uživatelské akceptační testování je testování zaměřené na byznys a kritiku produktu (Q3).","d":"Je správně. Integrační testování komponent je testování zaměřené na technologii, které podporuje tým (vede vývoj) (Q1)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"},"id":"OF-B33","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 33 (© ISTQB®, překlad CaSQB)"},{"n":34,"lo":"FL-5.2.4","k":"K2","vyber":1,"q":"<p>Uvažujme následující rizika:<\/p><ol><li>Neefektivní implementace smyčky způsobuje dlouhé odezvy systému.<\/li><li>Spotřebitelé mění své preference.<\/li><li>Vytopení serverovny.<\/li><li>Pacienti nad určitý věk dostávají nepřesné reporty.<\/li><\/ol><p>Dále uvažujme následující opatření ke zmírnění:<\/p><ol type=\"A\"><li>Akceptace rizika.<\/li><li>Testování výkonnostní efektivity (výkonnosti).<\/li><li>Použití analýzy hraničních hodnot.<\/li><li>Přenos rizika.<\/li><\/ol><p>Která z následujících kombinací NEJLÉPE přiřazuje rizika k opatřením?<\/p>","m":["1C 2D 3A 4B","1B 2D 3A 4C","1B 2A 3D 4C","1C 2A 3D 4B"],"ok":[2],"vys":{"a":"Není správně.","b":"Není správně.","c":"Je správně. Správné kombinace rizik a opatření k jejich zmírnění jsou: 1B, 2A, 3D a 4C.","d":"Není správně."},"obecne":"<p>S ohledem na každé z uvedených rizik a opatření k jejich zmírnění platí, že:<\/p><ol><li>Dlouhé odezvy systému (1) lze testovat při testování výkonnostní efektivity (výkonnosti) (B).<\/li><li>Změny preferencí spotřebitelů (2) jsou obvykle mimo naši kontrolu, proto je toto riziko obvykle akceptováno (A).<\/li><li>Vytopení serverovny (3) může způsobit značné ztráty, proto by mělo dojít k přenosu (transferu) rizika, např. sjednáním pojistky (D).<\/li><li>To, že pacienti nad určitý věk dostávají nepřesné reporty (4), naznačuje potenciální hraniční problém, který lze účinně detekovat technikami, jako je analýza hraničních hodnot (C).<\/li><\/ol><p>Tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.2.4","nazev":"Řízení produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-ctyri-rizeni-produktovych-rizik"},"id":"OF-B34","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 34 (© ISTQB®, překlad CaSQB)"},{"n":35,"lo":"FL-5.3.1","k":"K1","vyber":1,"q":"<p>Která z následujících možností je metrikou týkající se kvality produktu?<\/p>","m":["Střední doba do poruchy (MTTF).","Počet nalezených defektů.","Pokrytí požadavků.","Procento zjištěných defektů (DDP)."],"ok":[0],"vys":{"a":"Je správně. Metriky týkající se kvality produktu měří charakteristiky kvality. Střední doba do poruchy (MTTF) měří vyspělost, takže se jedná o metriku týkající se kvality produktu.","b":"Není správně. Toto je příklad metriky týkající se defektů, nikoli metriky týkající se kvality produktu.","c":"Není správně. Toto je příklad metriky pokrytí, nikoli metriky týkající se kvality produktu.","d":"Není správně. Toto je příklad metriky týkající se defektů, nikoli metriky týkající se kvality produktu."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.3.1","nazev":"Metriky používané v testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-jedna-metriky-pouzivane-v-testovani"},"id":"OF-B35","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 35 (© ISTQB®, překlad CaSQB)"},{"n":36,"lo":"FL-5.3.3","k":"K2","vyber":1,"q":"<p>Jste členem testovacího týmu se sídlem v Severní Americe, který vyvíjí produkt pro klienta v Evropě. Tým je agilní, používá DevOps a používá CI/CD pipeline (průběžná integrace / průběžné doručování).<\/p><p>Která z následujících možností je NEJMÉNĚ efektivní způsob, jak sdílet zákazníkovi postup prací při testování?<\/p>","m":["Osobně tváří v tvář (face-to-face).","Pomocí ukazatelů (dashboardů).","E-mailem.","Ústně pomocí videokonference."],"ok":[0],"vys":{"a":"Je správně. Klient se nachází na jiném místě a v jiném časovém pásmu, takže může být obtížné komunikovat osobně (tváří v tvář).","b":"Není správně. Dashboardy jsou obvykle dostupné kterémukoli uživateli kdykoli, takže rozdíl v časových pásmech není takovou překážkou v komunikaci jako verbální osobní komunikace.","c":"Není správně. Přestože je mezi Evropou a Amerikou několikahodinový časový posun, což může působit jisté komplikace, rozhodně to není tak velká překážka jako je pro osobní komunikaci.","d":"Není správně. Videokonferenční nástroje jsou vhodným komunikačním prostředkem. Ačkoli komunikace mezi Evropou a Amerikou v pracovní době obvykle vyžaduje, aby se jedna strana připojila ve velmi časných nebo velmi pozdních hodinách, není tak velkou překážkou jako je pro osobní komunikaci."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.3.3","nazev":"Komunikování stavu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-tri-komunikovani-stavu-testovani"},"id":"OF-B36","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 36 (© ISTQB®, překlad CaSQB)"},{"n":37,"lo":"FL-5.4.1","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE popisuje příklad toho, jak konfigurační management (CM) podporuje testování?<\/p>","m":["S číslem verze prostředí může CM nástroj zjistit čísla verzí knihoven, stubů a ovladačů používaných v tomto prostředí.","Díky záznamu hodnot vstupů může CM nástroj provádět testovací případy pro tyto konfigurace a vypočítat pokrytí.","S informací o datu zakoupení licence softwaru CM nástroj automaticky poskytne informaci o tom, že platnost licence bude končit.","S číslem verze testovacího případu může CM nástroj automaticky vytvořit testovací data pro tento testovací případ."],"ok":[0],"vys":{"a":"Je správně. V případě komplexní konfigurační položky (např. testovací prostředí) lze v rámci CM zaznamenávat dílčí položky, ze kterých se tato komplexní položka skládá, jejich vztahy a verze.","b":"Není správně. Nástroje CM neprovádějí testovací případy a nepočítají pokrytí.","c":"Není správně. Nástroj CM není nástroj pro management licencí.","d":"Není správně. CM nástroje negenerují testovací data."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"},"id":"OF-B37","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 37 (© ISTQB®, překlad CaSQB)"},{"n":38,"lo":"FL-5.5.1","k":"K3","vyber":1,"q":"<p>Testujete funkci SORT, která na přijímá na vstupu sadu čísel a vrací ji na výstupu vzestupně seřazenou. Protokol z provedení testu vypadá následovně:<\/p><pre>Konfigurace prostředí: funkce SORT, sestavení 2.002.2182, sada testovacích případů (TCS): TCS-3, počet testovacích případů (TC): 5\nID běhu testu: 736\nStart 12:43:21.003\n12:43:21.003  Provedení TC1  Vstup: 3               Výstup: 3          Výsledek: prošel\n12:43:21.003  Provedení TC2  Vstup: 3 11 6 5        Výstup: 3 5 6 11   Výsledek: prošel\n12:43:21.004  Provedení TC3  Vstup: 8 7 3 7 1       Výstup: 1 3 7 8    Výsledek: selhal\n12:43:21.005  Provedení TC4  Vstup: -2 -2 -2 -3 -3  Výstup: -3 -2      Výsledek: selhal\n12:43:21.005  Provedení TC5  Vstup: 0 -2 0 3 4 4    Výstup: -2 0 3 4   Výsledek: selhal\nKonec 12:43:21.005\nCelková doba testovacího cyklu: 0:00:00.002<\/pre><p>Která z následujících možností poskytuje NEJLEPŠÍ popis selhání, který lze použít v reportu o defektu?<\/p>","m":["Systém nedokáže seřadit několik sad čísel. Odkaz na testovací případy: TC3, TC4, TC5.","Zdá se, že systém při řazení ignoruje duplicitní vstupy. Odkaz na testovací případy: TC3, TC4, TC5.","Systém nedokáže seřadit záporná čísla. Odkaz na testovací případy: TC4, TC5.","TC3, TC4 a TC5 mají defekty (duplicitní vstupní data) a měly by být opraveny."],"ok":[1],"vys":{"a":"Není správně. I když je tato věta pravdivá, neposkytuje vývojářům velkou hodnotu.","b":"Je správně. Z výsledků testů se zdá, že systém ignoruje duplicity a řadí seznam bez ohledu na opakování, což je pravděpodobně příčina selhání v TC3, TC4, TC5. Tyto informace mohou vývojáři pomoci při nalezení a opravě defektu.","c":"Není správně. Systém nevykazuje selhání při řazení záporných čísel. Problém je spíše v tom, že se neberou v potaz duplicity.","d":"Není správně. Testovací případy TC3, TC4 a TC5 selžou, ale neexistuje žádná informace o tom, že by testovací případy měly nějaké defekty."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"},"id":"OF-B38","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 38 (© ISTQB®, překlad CaSQB)"},{"n":39,"lo":"FL-6.1.1","k":"K2","vyber":1,"q":"<p>Předpokládejme následující charakteristiky testovacích nástrojů:<\/p><ol><li>Podpora sledování pracovních postupů (workflows).<\/li><li>Usnadnění komunikace.<\/li><li>Virtuální počítač.<\/li><li>Podpora revidujících.<\/li><\/ol><p>A jejich následující kategorie:<\/p><ol type=\"A\"><li>Nástroj pro statické testování.<\/li><li>Nástroje podporující škálovatelnost a standardizaci nasazení.<\/li><li>Nástroje DevOps.<\/li><li>Nástroje pro spolupráci.<\/li><\/ol><p>Která z následujících možností NEJLÉPE přiřazuje kategorie nástrojů k jejich charakteristikám?<\/p>","m":["1A, 2B, 3C, 4D","1B, 2D, 3C, 4A","1C, 2D, 3B, 4A","1D, 2C, 3A, 4B"],"ok":[2],"vys":{"a":"Není správně.","b":"Není správně.","c":"Je správně. Správná kombinace je: 1C, 2D, 3B, 4A","d":"Není správně."},"obecne":"<p>S ohledem na každou z uvedených kategorií nástrojů a jejich popisy platí, že:<\/p><ol type=\"A\"><li>Nástroje pro statické testování – poskytují podporu při provádění revizí a statické analýzy (4).<\/li><li>Nástroje podporující škálovatelnost a standardizaci nasazení, např. virtuální počítače, nástroje pro práci s kontejnery (3).<\/li><li>Nástroje DevOps - podpora DevOps pipelines, sledování pracovních postupů, automatizovaný proces sestavování (build process), průběžná integrace/průběžné dodávání (CI/CD) (1).<\/li><li>Nástroje pro spolupráci – usnadňují komunikaci (2).<\/li><\/ol><p>Tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"},"id":"OF-B39","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 39 (© ISTQB®, překlad CaSQB)"},{"n":40,"lo":"FL-6.2.1","k":"K1","vyber":1,"q":"<p>Která z následujících možností bude s NEJVĚTŠÍ pravděpodobností přínosem automatizace testů?<\/p>","m":["Poskytuje metriky pokrytí, které jsou pro člověka příliš komplikované na to, aby je bylo možné ručně vypočítat.","Přenáší část zodpovědnosti za testování na dodavatele nástroje.","Odstraňuje potřebu kritického myšlení při analýze výsledků testů.","Generuje testovací případy z analýzy programového kódu."],"ok":[0],"vys":{"a":"Je správně. Automatizace testování může poskytovat metriky, které jsou příliš komplikované pro manuální výpočet, např. míry pokrytí testů bílé skříňky (pro jakýkoliv komplexnější kód).","b":"Není správně. Při použití testovacích nástrojů odpovídá za testování tester a tato odpovědnost NENÍ sdílena s dodavatelem nástroje, protože dodavatel se na testování nepodílí. Jedinou možnou odpovědností, která by mohla být přiřazena dodavateli nástroje, je situace, kdy nástroj nefunguje podle očekávání a poskytuje nesprávné výsledky testů.","c":"Není správně. Testeři stále musí při analýze anomálií ve výsledcích testů aplikovat kritické myšlení, aby určili jejich pravděpodobnou příčinu.","d":"Není správně. Testeři ani nástroje nemohou generovat testovací případy jednoduše z analýzy programového kódu, protože kód je implementací a neposkytuje žádné informace o očekávaných výsledcích. Ty budou muset pocházet z jiné části testovací báze, jako je např. specifikace návrhu."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"},"id":"OF-B40","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška B, otázka 40 (© ISTQB®, překlad CaSQB)"},{"n":1,"lo":"FL-1.1.1","k":"K1","vyber":1,"q":"<p>Která z následujících možností je typickým cílem testování?<\/p>","m":["Validace, že jsou splněny zdokumentované požadavky.","Vyvolání selhání a identifikace defektů.","Iniciování chyb a identifikace kořenových příčin.","Ověření, že testovaný objekt splňuje očekávání uživatele."],"ok":[1],"vys":{"a":"Není správně. Použití termínu validace pro kontrolu splnění zdokumentovaných požadavků je nesprávné, protože validace se zabývá naplněním potřeb a očekávání uživatelů, zatímco verifikace (ověření) se zabývá splněním specifikovaných požadavků. Správně by to tedy bylo, pokud bychom slovo „validace“ nahradili slovem „verifikace“ (ověření).","b":"Je správně. Vyvolávání selhání a identifikace defektů je nejčastějším cílem dynamického testování.","c":"Není správně. Iniciování chyb a identifikace jejich kořenových příčin je nesprávně, protože testeři chyby neiniciují, snaží se vyvolat selhání. Chyby jsou obvykle způsobeny vývojáři (a opravdu je nelze iniciovat) a vedou k defektům, které se testeři snaží identifikovat buď přímo pomocí statického testování, nebo nepřímo prostřednictvím selhání při dynamickém testování. Identifikace kořenových příčin je užitečná, ale je součástí ladění, což není testovací činnost.","d":"Není správně. Verifikace (ověření), že testovaný objekt splňuje očekávání uživatelů, je nesprávné, protože ověření se zabývá kontrolou, zda jsou splněny specifikované (zdokumentované) požadavky. Splněním potřeb a očekávání uživatelů se naopak zabývá validace. Tvrzení by tedy bylo správné, pokud bychom nahradili pojem „ověření“ pojmem „validace“."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"},"id":"OF-C1","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 1 (© ISTQB®, překlad CaSQB)"},{"n":2,"lo":"FL-1.1.2","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení NEJLÉPE vystihuje rozdíl mezi testováním a laděním?<\/p>","m":["Testování způsobuje selhání, zatímco ladění selhání napravuje.","Testování je negativní činnost, zatímco ladění je pozitivní činnost.","Testováním se zjišťuje, zda defekty existují, zatímco laděním se defekty odstraňují.","Testování zjišťuje příčinu defektů, zatímco ladění ji odstraňuje."],"ok":[2],"vys":{"a":"Není správně. Dynamické testování skutečně vyvolává selhání (na jejichž základě lze následně lokalizovat a opravit defekty). Ladění se však zabývá lokalizací defektů a jejich opravou. Ladění tedy neopravuje selhání.","b":"Není správně. Jak testování, tak ladění přispívají ke zlepšení kvality testovaného objektu, a proto by měly být obě tyto činnosti považovány za pozitivní. Ladění je obecně považováno za pozitivní činnost, protože se při ní něco opravuje. Dynamické testování zahrnuje záměrné vyvolání selhání testovaného objektu, což je důvod, proč jej někteří lidé považují za negativní aktivitu. To je ale velmi zúžený pohled (který testeři obvykle nezastávají). Jsou možné jak pozitivní, tak negativní testovací případy. Pozitivní testovací případy kontrolují, zda testovaný objekt správně provádí to, co má, zatímco negativní testování kontroluje, zda testovaný objekt nedělá to, co dělat nemá.","c":"Je správně. Testování zjišťuje existenci defektů buď přímo pozorováním defektu při revizích (nebo pomocí nástroje při statické analýze), nebo nepřímo vyvoláním selhání při dynamickém testování. Ladění je činnost odlišná od testování (obvykle prováděná vývojáři) a zabývá se vyhledáváním defektů (pouze u dynamického testování) a jejich odstraňováním.","d":"Není správně. Příčinou defektů jsou obvykle lidské chyby. Testování odhaluje defekty buď přímo prostřednictvím statického testování, nebo nepřímo tím, že vyvolává selhání při dynamickém testování. Ladění odstraňuje přímo defekty. Testování tedy nezjistí a ladění neodstraní příčinu defektů."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.1.2","nazev":"Testování a ladění","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-dva-testovani-a-ladeni"},"id":"OF-C2","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 2 (© ISTQB®, překlad CaSQB)"},{"n":3,"lo":"FL-1.3.1","k":"K2","vyber":1,"q":"<p>Jeden z principů testování říká: \"Nepřítomnost defektů je klam\". Které z následujících tvrzení je příkladem praktického uplatnění tohoto principu?<\/p>","m":["Vysvětlení, že testování nemůže prokázat neexistenci defektů.","Podpora koncových uživatelů při provádění akceptačního testování.","Zajištění toho, že v dodaném systému nezůstanou žádné defekty v implementaci.","Úprava testů, které již selhání nevyvolávají, aby se zajistilo, že zůstane jen malé množství defektů."],"ok":[1],"vys":{"a":"Není správně. Princip \"testování prokazuje přítomnost defektů, nikoli jejich nepřítomnost\" ukazuje, že testování sice může odhalit existenci defektů v testovaném objektu, ale nedokazuje, že v něm žádné defekty neexistují, a nemůže tedy zaručit jeho správnost. Vysvětlení, že testování nemůže prokázat neexistenci defektů, by se tedy částečně odkazovalo na tento princip, nikoliv ale na princip \"nepřítomnost defektů je klam\".","b":"Je správně. Využitím koncových uživatelů při provádění akceptačních testů by mělo být možné ověřit, že systém splňuje potřeby a očekávání uživatelů.","c":"Není správně. Není možné zajistit, aby v dodaném systému nezůstaly žádné implementační defekty, protože princip \"testování prokazuje přítomnost defektů, nikoli jejich nepřítomnost.\" vysvětluje, že testování sice může odhalit existenci defektů v testovaném objektu, ale není možné prokázat, že v něm žádné defekty nejsou, a tedy ani zaručit jeho správnost.","d":"Není správně. Jedním ze způsobů, jak řešit princip \"testy se opotřebovávají\", je úprava testů, které nezpůsobují žádné selhání tak, aby se nějaké defekty objevily. Tento princip se týká myšlenky, že opakování stejných testů na nezměněném kódu pravděpodobně neodhalí nové defekty, a proto může být důležité tyto testy upravit. Tím se ovšem nepotvrdí, že systém splňuje potřeby a očekávání uživatelů."},"obecne":"<p>Princip \"nepřítomnost defektů je klam\" se týká myšlenky, že zajištění správnosti v návaznosti na požadavky (tj. ověření absence defektů implementace) nezaručuje spokojenost uživatele se systémem. Je také nutno ověřit, že systém splňuje potřeby a očekávání uživatelů, plní byznysové cíle a překonává konkurenční systémy.<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"},"id":"OF-C3","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 3 (© ISTQB®, překlad CaSQB)"},{"n":4,"lo":"FL-1.4.1","k":"K2","vyber":2,"q":"<p>Které z následujících testovacích činností budou s NEJVĚTŠÍ pravděpodobností zahrnovat použití analýzy hraničních hodnot a rozdělení tříd ekvivalence?<\/p>","m":["Implementace testování.","Návrh testů.","Provedení testů.","Monitoring testování.","Testovací analýza."],"ok":[1,4],"vys":{"a":"Není správně. V rámci implementace testování se pravděpodobně nebudou používat techniky testování, protože implementace testování se většinou zabývá sestavením testovacích případů do testovacích procedur, zatímco výstupem technik testování jsou testovací případy.","b":"Je správně. V rámci návrhu testů se pravděpodobně budou používat techniky testování s cílem vytvořit testovací případy z testovacích podmínek a položek pokrytí.","c":"Není správně. V rámci provedení testů se pravděpodobně nebudou používat techniky testování, protože provedení testování se většinou zabývá provedením testovacích procedur (a tím testovacích případů), zatímco výstupem technik testování jsou testovací případy.","d":"Není správně. V rámci monitorování testování se pravděpodobně nebudou používat techniky testování. Monitorování testování se většinou zabývá průběžnými kontrolami s cílem zajistit dodržování plánu, zatímco výstupem technik testování jsou testovací případy.","e":"Je správně. Testovací analýza používá testovací techniky k identifikaci testovacích podmínek."},"obecne":"<p>Testovací analýza je popsána takto:<\/p><p>Pro identifikaci funkcionalit, které vyžadují testování, je analyzována testovací báze, a výstupem této analýzy jsou prioritizované testovací podmínky spolu se souvisejícími riziky. Systematická identifikace testovacích podmínek jako položek pokrytí často zahrnuje použití technik testování jak během testovací analýzy, tak během činností návrhu testů.<\/p><p>Z výše uvedeného popisu vyplývá, že techniky testování se často používají v činnostech testovací analýzy a návrhu testů. Technikami testování jsou analýza hraničních hodnot a rozdělení tříd ekvivalence.<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"},"id":"OF-C4","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 4 (© ISTQB®, překlad CaSQB)"},{"n":5,"lo":"FL-1.4.3","k":"K2","vyber":1,"q":"<p>Máte k dispozici následující testware:<\/p><ol><li>Položky pokrytí.<\/li><li>Požadavek na změnu.<\/li><li>Harmonogram provádění testů.<\/li><li>Prioritizované testovací podmínky.<\/li><\/ol><p>A následující testovací činnosti:<\/p><ol type=\"A\"><li>Testovací analýza.<\/li><li>Návrh testů.<\/li><li>Implementace testování.<\/li><li>Dokončení testování.<\/li><\/ol><p>Která z následujících možností NEJLÉPE vystihuje fakt, že je výše uvedený testware výstupem těchto testovacích činností?<\/p>","m":["1B, 2D, 3C, 4A","1B, 2D, 3A, 4C","1D, 2C, 3A, 4B","1D, 2C, 3B, 4A"],"ok":[0],"vys":{"a":"Je správně. Správná kombinace je: 1B, 2D, 3C, 4A","b":"Není správně","c":"Není správně","d":"Není správně"},"obecne":"<p>Výstupní testware testovacích činností je definován takto:<\/p><ol type=\"A\"><li>Testovací analýza - prioritizované testovací podmínky (4) (např. akceptační kritéria) a reporty o defektech v testovací bázi.<\/li><li>Návrh testů - prioritizované testovací případy, testovací listiny, položky pokrytí (1), požadavky na testovací data a požadavky na testovací prostředí.<\/li><li>Implementace testování - testovací procedury, automatizované testovací skripty, testovací sady, testovací data, harmonogram provádění testů (3) a prvky testovacího prostředí jako jsou stuby, ovladače, simulátory a virtualizace služeb.<\/li><li>Dokončení testování - souhrnný report z testování, zdokumentovaná ponaučení (lessons learned), akce pro zlepšení a požadavky na změny (2) obvykle ve formě jako položek produktového backlogu.<\/li><\/ol><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"},"id":"OF-C5","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 5 (© ISTQB®, překlad CaSQB)"},{"n":6,"lo":"FL-1.4.5","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení o různých testovacích rolích je s NEJVĚTŠÍ pravděpodobností SPRÁVNÉ?<\/p>","m":["Role manažera testování je v agilním vývoji softwaru primárně odpovědností týmu, zatímco role testera je primárně odpovědností jednotlivce mimo tým.","Role testera je primárně zodpovědná za monitoring testování a řízení testování, zatímco role manažera testování je primárně zodpovědná za plánování testování a dokončení testování.","V agilním vývoji softwaru jsou činnosti managementu testování, probíhající napříč více týmy, vykonávány manažerem testování mimo tým, zatímco některé úkoly managementu testování jsou vykonávány týmem samotným.","Role manažera testování je primárně zodpovědná za testovací analýzu a návrh testů, zatímco role testera je primárně zodpovědná za implementaci testování a provedení testů."],"ok":[2],"vys":{"a":"Není správně. Ačkoli je správné říci, že v agilním vývoji softwaru může některé úkoly spojené s rolí manažera testování vykonávat samotný agilní tým, není role testera primárně odpovědností jednoho člověka mimo tým. Místo toho je pravděpodobnější, že budou tuto roli zastávat různí členové týmu dle týmového přístupu.","b":"Není správně. Role manažera testování se primárně zaměřuje na činnosti související s plánováním testování, monitoringem testování, řízením testování a dokončením testování. Ačkoli je tedy toto tvrzení částečně správné, je nesprávné tvrdit, že role testera je primárně zodpovědná za monitorování a řízení testování.","c":"Je správně. V agilním vývoji jsou některé úkoly manažera testování vykonávány celým agilním týmem. U testovacích činností, které zasahují do více týmů v rámci organizace, mohou tyto úkoly vykonávat manažeři testování mimo vývojový tým.","d":"Není správně. Role manažera testování se primárně zaměřuje na činnosti související s plánováním testování, monitorováním testování, řízením testování a dokončením testování, zatímco role testera je primárně zodpovědná za technické a inženýrské aspekty testování, jako je testovací analýza, návrh testů, implementace testování a provedení testů. Role manažera testování tedy obvykle neodpovídá za testovací analýzu a návrh testů (ačkoli tvrzení, že role testera odpovídá především za implementaci a provedení testů je správné)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.4.5","nazev":"Role v testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-pet-role-v-testovani"},"id":"OF-C6","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 6 (© ISTQB®, překlad CaSQB)"},{"n":7,"lo":"FL-1.5.2","k":"K1","vyber":1,"q":"<p>Která z následujících možností je výhodou týmového přístupu?<\/p>","m":["Týmy bez testerů.","Zlepšení týmové dynamiky.","Specializace členů týmu.","Větší velikost týmu."],"ok":[1],"vys":{"a":"Není správně. V týmovém přístupu hrají testeři důležitou roli tím, že sdílejí své odborné znalosti v oblasti testování s týmem a usměrňují vývoj produktu. Spolupracují s ostatními členy týmu na dosažení požadované úrovně kvality a také se zástupci byznysu na vytváření akceptačních testů. Testeři také spolupracují s vývojáři při určování optimální testovací strategie a přístupů k automatizaci testů.","b":"Je správně. Tím, že co nejefektivněji využívá rozmanité dovednosti každého člena týmu, týmový přístup podporuje týmovou dynamiku, podporuje komunikaci a spolupráci, a vytváří týmovou synergii, která je přínosem pro celý projekt.","c":"Není správně. Týmový přístup umožňuje každému členovi týmu s potřebnými dovednostmi a znalostmi převzít jakýkoli úkol, takže specializovaní členové týmu nejsou v tomto přístupu výhodou.","d":"Není správně. Neexistuje žádné konkrétní doporučení ohledně optimální velikosti týmů využívajících týmový přístup a nic nenasvědčuje tomu, že větší týmy jsou lepší."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"},"id":"OF-C7","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 7 (© ISTQB®, překlad CaSQB)"},{"n":8,"lo":"FL-1.5.3","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení o nezávislosti testování je SPRÁVNÉ?<\/p>","m":["Nezávislí testeři najdou díky svému odlišnému technickému pohledu od vývojářů defekty, ale jejich nezávislost může vést k nepřátelskému vztahu s vývojáři.","To, že vývojáři důvěrně znají svůj vlastní kód, znamená, že v něm najdou jen málo defektů. Nicméně skutečnost, že s testery sdílejí společné softwarové znalosti (zázemí), znamená, že by tyto defekty našli i testeři.","Nezávislé testování vyžaduje testery, kteří jsou mimo vývojářský tým a ideálně i mimo organizaci, nicméně je pro ně často obtížné porozumět aplikační doméně.","Testeři mimo vývojářský tým jsou nezávislejší než testeři z týmu, kteří jsou ale častěji obviňováni ze zpoždění při vydávání (release) produktu."],"ok":[0],"vys":{"a":"Je správně. Hlavní výhodou nezávislosti testování je to, že testeři odhalí různé typy selhání a defektů mnohem pravděpodobněji než vývojáři, kteří mají jiné odborné zázemí, technický pohled a možné předsudky včetně kognitivního zkreslení. Hlavní nevýhodou nezávislosti testování je však to, že testeři mohou být izolováni od vývojového týmu, což vede k problémům v komunikaci, nízké úrovně spolupráce a potenciálně i k nepřátelskému vztahu, kdy jsou testeři obviňováni ze zpoždění a překážek při vydávání (release).","b":"Není správně. To, že vývojář zná kód, neznamená, že v něm zřídkakdy najde defekty, naopak, tato znalost znamená, že může efektivně najít mnoho defektů ve svém vlastním kódu. Jako důvod, proč testeři a vývojáři nacházejí různé druhy defektů, se obvykle uvádí to, že vývojáři a testeři nemají stejné odborné zázemí.","c":"Není správně. Testování lze provádět v různých úrovních nezávislosti, od nulové nezávislosti autora až po velmi vysokou nezávislost testerů mimo organizaci. Ve většině projektů se využívá více úrovní nezávislosti, kdy vývojáři provádějí testování komponent a integrační testování komponent, testovací tým provádí systémové testování a systémové integrační testování a zástupci byznysu provádějí akceptační testování. Testeři tedy mohou být součástí vývojového týmu a nemusí pocházet z prostředí mimo své organizace. Znalost byznysového kontextu aplikace se bude lišit případ od případu a není navázaná na úroveň nezávislosti.","d":"Není správně. Testování lze provádět v různých úrovních nezávislosti, od nulové nezávislosti autora až po velmi vysokou nezávislost testerů mimo organizaci, přičemž testeři mimo tým vývojáře jsou obecně nezávislejší než testeři uvnitř týmu. Existuje ale předpoklad, že testeři mimo vývojový tým budou pravděpodobně více izolováni od vývojářů, a tak je pravděpodobnější, že budou více obviňováni ze zpoždění při vydávání produktu."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.5.3","nazev":"Nezávislost testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-tri-nezavislost-testovani"},"id":"OF-C8","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 8 (© ISTQB®, překlad CaSQB)"},{"n":9,"lo":"FL-2.1.2","k":"K1","vyber":1,"q":"<p>Které z následujících tvrzení je příkladem osvědčeného postupu v testování, který platí pro všechny životní cykly vývoje softwaru?<\/p>","m":["Pro každou úroveň testování existuje odpovídající úroveň vývoje.","Ke každému cíli testování existuje odpovídající cíl vývoje.","Pro každou testovací činnost existuje odpovídající uživatelská činnost.","Pro každou vývojovou činnost existuje odpovídající testovací činnost."],"ok":[3],"vys":{"a":"Není správně. Ke každé vývojové činnosti existuje odpovídající testovací činnost, takže všechny vývojové činnosti podléhají řízení kvality. Nicméně zde je pokus o přiřazení úrovní testování k úrovním vývoje, které nemají (na rozdíl od přesné definice úrovní testování) obecně přijímanou definici.","b":"Není správně. Každá činnost při vývoji softwaru má odpovídající činnost testování, avšak cíle testování jsou zcela odlišné. Cílem testování může být například zajistit, aby testovaný objekt splňoval smluvní požadavek, že před dodáním musí být proveden určitý typ testování. V tomto případě není důvod, aby existoval odpovídající cíl vývoje.","c":"Není správně. Ke každé vývojové činnosti existuje odpovídající testovací činnost, takže všechny vývojové činnosti podléhají řízení kvality. Stejná symetrie však neplatí pro testovací činnosti a uživatelské činnosti. U některých systémů je například obtížné identifikovat koncové uživatele. Některé činnosti testování jsou také zaměřeny na vývojáře (např. testování vysoké míry udržovatelnosti), k čemuž neexistuje žádný uživatelský aspekt.","d":"Je správně. Ke každé vývojové činnosti existuje odpovídající testovací činnost, takže všechny vývojové činnosti podléhají řízení kvality."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"},"id":"OF-C9","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 9 (© ISTQB®, překlad CaSQB)"},{"n":10,"lo":"FL-2.1.3","k":"K1","vyber":1,"q":"<p>Která z následujících možností je příkladem přístupu k vývoji iniciovaného testy (test-first approach)?<\/p>","m":["Vývoj řízený testy komponent.","Vývoj řízený integračními testy.","Vývoj řízený systémovými testy.","Vývoj řízený akceptačními testy."],"ok":[3],"vys":{"a":"Není správně. Vývoj řízený testy komponent není správným příkladem přístupu k vývoji iniciovaného testy (test-first).","b":"Není správně. Vývoj řízený integračním testováním není správným příkladem přístupu k vývoji iniciovaného testy.","c":"Není správně. Vývoj řízený systémovými testy není správným příkladem přístupu k vývoji iniciovaného testy.","d":"Je správně. Vývoj řízený akceptačními testy (ATDD) je známým příkladem přístupu k vývoji iniciovaného testy."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"},"id":"OF-C10","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 10 (© ISTQB®, překlad CaSQB)"},{"n":11,"lo":"FL-2.1.5","k":"K2","vyber":1,"q":"<p>Která z následujících možností nejlépe popisuje princip shift left?<\/p>","m":["Po dohodě s vývojáři jsou manuální činnosti na levé straně testovacího procesu (dřívější) automatizovány s cílem podpořit princip \"včasné testování šetří čas a peníze\".","Pokud je to nákladově efektivní, testovací činnosti jsou přesouvány do dřívějších fází životního cyklu vývoje softwaru (SDLC) za účelem snížení celkových nákladů na kvalitu, a to omezením počtu defektů nalezených v pozdějších fázích SDLC.","Pokud mají testeři volný čas, musí automatizovat testy pro regresní testování, počínaje testy komponent a integračními testy komponent.","Pokud je to možné, testeři jsou vyškoleni k provádění úkolů na počátku SDLC, což umožňuje pozdější automatizaci většího počtu testovacích činností v SDLC."],"ok":[1],"vys":{"a":"Není správně. Praktiky spojené s principem shift left jsou zaměřeny na zavedení většího počtu testovacích činností v raných fázích životního cyklu vývoje softwaru (SDLC), přičemž tento cyklus je zobrazován jako plynoucí zleva doprava. Neexistuje ale nic jako levá strana testovacího procesu.","b":"Je správně. Princip shift left zdůrazňuje důležitost zahájení testování na začátku SDLC. Jeho zavedení vyžaduje dodatečné školení a navýšenou pracnost a náklady v počátečních fázích SDLC, nicméně v souhrnu by mělo dojít k úspoře nákladů.","c":"Není správně. Ačkoli jsou automatizované testy komponent a integrační testy komponent pro regresní testování obecně cenné, za jejich vytvoření jsou obvykle odpovědní vývojáři. Pokud je využívána průběžná integrace a průběžné dodávání (CI/CD), pak jsou tyto testy odevzdávány spolu s kódem. V některých situacích může tester automatizovat regresní testy a někdy i v úrovni testů komponent nebo v úrovni integračního testování komponent, což však není součástí principu shift left (jeho podstatou je přesun testování do dřívějších fází SDLC).","d":"Není správně. Školení testerů k vykonávání úkolů v raných fázích SDLC by podpořilo princip shift left, protože zdůrazňuje důležitost zahájení testování již v počátečních fázích SDLC. Automatizace dalších testovacích činností, které se mají provádět později v SDLC, však není součástí principu shift left."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.5","nazev":"Princip shift left","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-pet-princip-shift-left"},"id":"OF-C11","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 11 (© ISTQB®, překlad CaSQB)"},{"n":12,"lo":"FL-2.1.6","k":"K2","vyber":1,"q":"<p>Která z následujících možností je NEJMÉNĚ pravděpodobným důsledkem retrospektivy?<\/p>","m":["Kvalita budoucích testovaných objektů se zlepší díky identifikaci zlepšení ve vývojových procesech.","Efektivita testování se zvýší z důvodu automatického nastavení konfigurace testovacích prostředí.","Zlepší se porozumění koncových uživatelů procesům vývoje a testování.","Na základě zpětné vazby od vývojářů budou vylepšeny automatizované testovací skripty."],"ok":[2],"vys":{"a":"Není správně. Jedním z cílů retrospektiv je identifikovat potenciální zlepšení procesů, která – pokud jsou uvedena do praxe – by měla vést ke zvýšení kvality budoucích výstupů procesu vývoje. Je tedy pravděpodobné, že k tomu dojde v důsledku retrospektivy.","b":"Není správně. Přínosem retrospektivy pro testování je zvýšení efektivity testování prostřednictvím zlepšení procesů. Je tedy pravděpodobné, že k tomu dojde v důsledku retrospektivy.","c":"Je správně. Retrospektivy se obvykle účastní testeři, vývojáři, architekti, vlastníci produktů a byznysoví analytici. Koncoví uživatelé jsou ale na tyto schůzky zváni (nebo se jich účastní) jen zřídka. Je tedy nepravděpodobné, že by z těchto schůzek dostali nějaké reporty. Stejně tak je velmi nepravděpodobné, že by se prostřednictvím retrospektivy dozvěděli a pochopili více o procesech vývoje a testování.","d":"Není správně. Přínosem retrospektivy pro testování je zlepšení kvality testwaru (včetně automatizovaných testovacích skriptů) díky společným revizím s vývojáři. Je tedy pravděpodobné, že k tomu dojde v důsledku retrospektivy."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"},"id":"OF-C12","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 12 (© ISTQB®, překlad CaSQB)"},{"n":13,"lo":"FL-2.2.1","k":"K2","vyber":1,"q":"<p>Která z následujících úrovní testování se s NEJVĚTŠÍ pravděpodobností provádí, pokud je testování zaměřeno na validaci a není prováděno testery?<\/p>","m":["Testování komponent.","Integrační testování komponent.","Systémové integrační testování.","Akceptační testování."],"ok":[3],"vys":{"a":"Není správně. Testování komponent (nazývané také testování jednotek) testuje jednotlivé komponenty izolovaně a většinou se jedná o ověřování vůči specifikaci, nikoli o validaci vůči potřebám uživatele. Toto testování však obvykle neprovádějí testeři, ale vývojáři, a to ve svém vývojovém prostředí.","b":"Není správně. Integrační testování komponent spočívá v testování rozhraní a interakcí mezi komponentami a většinou se jedná o ověřování vůči specifikaci, nikoli o validaci vůči potřebám uživatele. Toto testování také obvykle neprovádějí testeři, ale vývojáři.","c":"Není správně. Systémové integrační testování zkoumá rozhraní s jinými systémy a externími službami a jedná se převážně o ověřování vůči specifikaci, nikoliv o validaci vůči potřebám uživatele. Tento typ testování obvykle provádějí testeři.","d":"Je správně. Akceptační testování se zaměřuje na validaci, zda systém splňuje byznysové potřeby uživatele a je připraven k nasazení. V ideálním případě toto testování provádějí koncoví uživatelé."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.2.1","nazev":"Úrovně testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-jedna-urovne-testovani"},"id":"OF-C13","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 13 (© ISTQB®, překlad CaSQB)"},{"n":14,"lo":"FL-2.2.3","k":"K2","vyber":1,"q":"<p>Software navigačního systému byl aktualizován kvůli tomu, že navrhoval trasy, které porušovaly dopravní předpisy (například jízdu v protisměru jednosměrnými ulicemi). Která z následujících možností NEJLÉPE popisuje, jaké typy testování mají být provedeny?<\/p>","m":["Pouze konfirmační testování.","Konfirmační testování a následně regresní testování.","Pouze regresní testování.","Regresní testování a následné konfirmační testování."],"ok":[1],"vys":{"a":"Není správně. Konfirmační testování s cílem ověřit, že provedené aktualizace vedly ke správné implementaci, je nezbytné. Poté však dává smysl provést také regresní testování, aby se zajistilo, že v nezměněných částech systému nevznikly nebo se neprojevily žádné další defekty.","b":"Je správně. Konfirmační testování prověří, že provedené aktualizace vedly ke správné implementaci. Regresní testování je použito k zajištění toho, že v nezměněných částech systému nevznikly nebo se neprojevily žádné další defekty.","c":"Není správně. Regresní testování by mělo být použito k zajištění toho, že při aktualizaci nevznikly nebo se neprojevily žádné defekty v nezměněných oblastech systému. Je však také nutné provést konfirmační testování, které ověří, zda aktualizace vedly ke správné implementaci.","d":"Není správně. Konfirmační testování prověří, že provedené aktualizace vedly ke správné implementaci. Regresní testování je použito k zajištění toho, že v nezměněných částech systému nevznikly nebo se neprojevily žádné další defekty. Pokud se však provádí (tj. pokud je potřeba otestovat aktualizaci), konfirmační testování předchází regresnímu testování."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.2.3","nazev":"Konfirmační a regresní testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-tri-konfirmacni-a-regresni-testovani"},"id":"OF-C14","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 14 (© ISTQB®, překlad CaSQB)"},{"n":15,"lo":"FL-3.1.3","k":"K2","vyber":1,"q":"<p>Uvažujme následující příklady defektů:<\/p><ol type=\"i\"><li>Kvůli složitosti návrhu si dvě různé části specifikace návrhu protiřečí.<\/li><li>Doba odezvy je příliš dlouhá, takže uživatelé ztrácejí trpělivost.<\/li><li>Určitá cesta v kódu je během provádění nedosažitelná (nelze ji spustit).<\/li><li>Proměnná je deklarována, ale v programu není nikdy použita.<\/li><li>Program potřebuje k vygenerování reportu příliš velké množství paměti.<\/li><\/ol><p>Která kombinace z výše uvedených příkladů NEJLÉPE popisuje příklady defektů, které by mohly být nalezeny statickým testováním (spíše než dynamickým testováním)?<\/p>","m":["ii, v","iii, v","i, ii, iv","i, iii, iv"],"ok":[3],"vys":{"a":"Není správně","b":"Není správně","c":"Není správně","d":"Je správně. Správná kombinace je tedy i, iii a iv."},"obecne":"<p>Pro uvedené příklady defektů platí, že:<\/p><ol type=\"i\"><li>Kvůli složitosti návrhu si dvě různé části specifikace návrhu protiřečí. Jedná se o příklad defektu ve specifikaci, která může obsahovat nesrovnalosti, nejednoznačnosti, rozpory, opomenutí, nepřesnosti a duplicity. Tyto defekty lze nejlépe odhalit pomocí statického testování.<\/li><li>Doba odezvy je příliš dlouhá, takže uživatelé ztrácejí trpělivost. To je příklad defektu v době odezvy, kterou lze v praxi zjistit pouze spuštěním programu a změřením doby odezvy, což lze nejlépe zjistit dynamickým testováním.<\/li><li>Určitá cesta v kódu je během provádění nedosažitelná (nelze ji spustit). Jedná se o příklad defektu programování (například proměnná s nedefinovanými hodnotami, nedeklarované proměnné, duplicitní nebo nedosažitelný kód a přílišná složitost kódu), který lze nejlépe zjistit statickým testováním.<\/li><li>Proměnná je deklarována, ale v programu není nikdy použita. Jedná se o příklad defektu programování (například proměnná s nedefinovanými hodnotami, nedeklarované proměnné, duplicitní nebo nedosažitelný kód a přílišná složitost kódu), který lze nejlépe zjistit statickým testováním.<\/li><li>Program potřebuje k vygenerování reportu příliš velké množství paměti. To je příklad defektu výkonnosti, kterou lze v praxi zjistit pouze spuštěním programu a měřením spotřebované paměti, což lze nejlépe zjistit dynamickým testováním.<\/li><\/ol><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"3.1.3","nazev":"Rozdíly mezi statickým a dynamickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-tri-rozdily-mezi-statickym-a-dynamickym-testovanim"},"id":"OF-C15","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 15 (© ISTQB®, překlad CaSQB)"},{"n":16,"lo":"FL-3.2.1","k":"K1","vyber":1,"q":"<p>Která z následujících možností je výhodou včasné a časté zpětné vazby zainteresovaných stran?<\/p>","m":["Změny požadavků jsou pochopeny a implementovány dříve.","Zajišťuje, aby zástupci byznysu rozuměli uživatelským požadavkům.","Umožňuje vlastníkům produktů měnit své požadavky tak často, jak chtějí.","Koncoví uživatelé jsou informováni o tom, které požadavky nebudou implementovány před vydáním."],"ok":[0],"vys":{"a":"Je správně. Získávání zpětné vazby od zainteresovaných stran v rané fázi procesu vývoje softwaru může být velmi přínosné. Usnadňuje včasnou komunikaci o možných problémech s kvalitou, může zabránit nedorozuměním ohledně požadavků a zajišťuje, že případné změny v požadavcích zainteresovaných stran budou pochopeny a implementovány rychleji (dříve).","b":"Není správně. Zpětná vazba pochází od zainteresovaných stran a je tedy nepravděpodobné, že by poskytování zpětné vazby zlepšilo to, jak rozumí svým vlastním uživatelským požadavkům.","c":"Není správně. Získávání zpětné vazby od zainteresovaných stran v rané fázi procesu vývoje softwaru může být velmi přínosné. Usnadňuje včasnou komunikaci o možných problémech s kvalitou, může zabránit nedorozuměním ohledně požadavků a zajišťuje, že případné změny v požadavcích zainteresovaných stran budou pochopeny a implementovány rychleji (dříve). To, že změny v požadavcích lze pochopit a implementovat dříve, však neznamená, že jsou změny požadavků umožněny neomezeně.","d":"Není správně. Zpětná vazba je od zainteresovaných stran a nezahrnuje komunikaci s nimi. Komunikace směrem ke koncovým uživatelům může znamenat také informování o tom, které požadavky nebudou před vydáním implementovány (ideálně by ovšem k takové situaci vůbec nemělo dojít)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"3.2.1","nazev":"Výhody včasné a časté zpětné vazby od zainteresovaných stran","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-jedna-vyhody-vcasne-a-caste-zpetne-vazby-od-zainteresovanych-stran"},"id":"OF-C16","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 16 (© ISTQB®, překlad CaSQB)"},{"n":17,"lo":"FL-3.2.4","k":"K2","vyber":1,"q":"<p>Uvažujme následující typy revizí:<\/p><ol><li>Technická revize.<\/li><li>Neformální revize.<\/li><li>Inspekce.<\/li><li>Předvedení (walkthrough).<\/li><\/ol><p>A následující popisy:<\/p><ol type=\"A\"><li>Zahrnuje cíle jako je zajištění dohody, generování nových nápadů a motivování autorů ke zlepšení.<\/li><li>Zahrnuje cíle jako je vzdělávání revidujících, dosažení dohody, generování nových nápadů a odhalování potenciálních anomálií.<\/li><li>Hlavním cílem je odhalování anomálií, mimo jiné je vyžadováno zavedení sady metrik s cílem podpořit zlepšování procesů.<\/li><li>Hlavním cílem je odhalování anomálií a není vytvářen žádný formální dokumentovaný výstup.<\/li><\/ol><p>Která z následujících možností NEJLÉPE přiřazuje typy revizí k jejich popisům?<\/p>","m":["1A, 2B, 3C, 4D","1A, 2D, 3C, 4B","1B, 2C, 3D, 4A","1C, 2D, 3A, 4B"],"ok":[1],"vys":{"a":"Není správně","b":"Je správně.","c":"Není správně","d":"Není správně"},"obecne":"<p>Platí, že:<\/p><ol><li>Technická revize - tento typ revize provádějí technicky kvalifikovaní revidující a vede ji moderátor. Cílem je dosáhnout dohody a rozhodnout o technických problémech a zároveň hodnotit kvalitu a budovat důvěru v pracovní produkt, generovat nové nápady, odhalovat anomálie a motivovat autory a umožnit jim zlepšovat se.<\/li><li>Neformální revize - hlavním cílem je odhalit anomálie. Proces není definován a nevyžaduje se formální dokumentovaný výstup.<\/li><li>Inspekce - jedná se o nejformálnější typ revize, který se řídí celým obecným procesem revize. Primárním cílem je najít co nejvíce anomálií, nicméně mezi další cíle patří hodnotit kvalitu a budovat důvěru v pracovní produkt, generovat nové nápady, odhalovat anomálie a motivovat autory a umožnit jim zlepšovat se včetně shromažďování metrik, které lze využít ke zlepšení životního cyklu vývoje softwaru (SDLC), včetně samotného procesu inspekce. Při inspekcích nemůže autor vystupovat jako vedoucí revize nebo zapisovatel.<\/li><li>Předvedení (walkthrough), které je vedené autorem, může sloužit mnoha cílům jako je hodnocení kvality a budování důvěry v pracovní produkt, vzdělávání revidujících, dosažení dohody, generování nových nápadů, motivace a podpora pro autory s cílem zlepšovat pracovní produkt a odhalovat anomálie. Revidující mohou (ale nemusí) před předvedením provést individuální revizi.<\/li><\/ol><ol type=\"A\"><li>Zahrnuje cíle jako je zajištění dohody, generování nových nápadů a motivování autorů ke zlepšení.<\/li><li>Zahrnuje cíle jako je vzdělávání revidujících, dosažení dohody, generování nových nápadů a odhalování potenciálních anomálií.<\/li><li>Hlavním cílem je odhalování anomálií, mimo jiné je vyžadováno zavedení sady metrik s cílem podpořit zlepšování procesů.<\/li><li>Hlavním cílem je odhalování anomálií a není vytvářen žádný formální dokumentovaný výstup.<\/li><\/ol><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"3.2.4","nazev":"Typy revizí","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-ctyri-typy-revizi"},"id":"OF-C17","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 17 (© ISTQB®, překlad CaSQB)"},{"n":18,"lo":"FL-3.2.5","k":"K1","vyber":1,"q":"<p>Který z následujících faktorů přispívá k úspěšné revizi?<\/p>","m":["Zajištění účasti managementu v roli revidujících.","Rozdělení velkých pracovních produktů na menší části.","Nastavení hodnocení revidujícího jako cíle.","Naplánovat si jeden dokument na jednu revizi."],"ok":[1],"vys":{"a":"Není správně. Pro zajištění úspěšné revize je důležité si zajistit podporu managementu, což však neznamená, že by se management měl účastnit procesu revize jako revidující.","b":"Je správně. Pro zajištění úspěšné revize je důležité rozdělit pracovní produkt na části, které jsou dostatečně malé na to, aby mohly být revidovány v přiměřeném časovém horizontu. Zamezí se tak ztrátě pozornosti revidujících během jednotlivých revizí nebo revizních schůzek.","c":"Není správně. Pro zajištění úspěšné revize je důležité jasně definovat cíle a měřitelná výstupní kritéria a rozhodně nehodnotit její účastníky.","d":"Není správně. Pro zajištění úspěšné revize je důležité rozdělit revizi na menší části tak, aby nedošlo ke ztrátě pozornosti revidujících během jednotlivých revizí nebo revizních schůzek. Není tedy vhodné plánovat pokrytí jednoho dokumentu v rámci jedné revize."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"3.2.5","nazev":"Faktory úspěchu při revizi","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-pet-faktory-uspechu-pri-revizi"},"id":"OF-C18","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 18 (© ISTQB®, překlad CaSQB)"},{"n":19,"lo":"FL-4.1.1","k":"K2","vyber":1,"q":"<p>Jaký je HLAVNÍ rozdíl mezi technikami testování černé skříňky a technikami testování založenými na zkušenostech?<\/p>","m":["Testovaný objekt.","Úroveň testování, na kterou se testovací technika používá.","Testovací báze.","Životní cyklus vývoje softwaru (SDLC), ve kterém lze techniku testování použít."],"ok":[2],"vys":{"a":"Není správně. Ve většině případů lze pro stejné testované objekty použít jak techniky testování černé skříňky, tak techniky testování založené na zkušenostech.","b":"Není správně. Techniky testování černé skříňky i techniky testování založené na zkušenostech lze použít ve všech úrovních testování.","c":"Je správně. Techniky testování černé skříňky (známé též jako techniky založené na specifikaci) jsou založeny na analýze specifikovaného chování testovaného objektu bez informací o jeho vnitřní struktuře. Testovací bází je tedy obvykle specifikace. Techniky testování založené na zkušenostech využívají znalosti a zkušenosti testerů pro návrh a implementaci testovacích případů. To znamená, že tester při navrhování testů nemusí specifikaci vůbec použít.","d":"Není správně. Techniky testování založené na zkušenostech mohou odhalit defekty, které techniky testování černé (i bílé) skříňky neodhalí. Proto jsou techniky testování založené na zkušenostech doplňkem k technikám testování černé skříňky a k technikám testování bílé skříňky. Techniky testování černé skříňky i techniky testování založené na zkušenostech lze použít ve všech SDLC."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"},"id":"OF-C19","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 19 (© ISTQB®, překlad CaSQB)"},{"n":20,"lo":"FL-4.2.1","k":"K3","vyber":1,"q":"<p>Testujete validátor PIN, který přijímá platné PIN kódy a odmítá neplatné PIN kódy. PIN je sekvence číslic. PIN je platný, pokud se skládá ze čtyř číslic, které nesmí být všechny stejné. Identifikovali jste následující platné třídy ekvivalence:<\/p><p>Proměnná: Délka PINu<\/p><ul><li>Třída \"správná délka\" - čtyřmístné PINy<\/li><li>Třída \"nesprávná délka\" - PINy s jinou délkou než 4<\/li><\/ul><p>Proměnná: Počet odlišných číslic<\/p><ul><li>Třída \"správný počet odlišných číslic\" - PINy s nejméně dvěma odlišnými číslicemi<\/li><li>Třída \"nesprávný počet odlišných číslic\" - PINy se stejnými číslicemi<\/li><\/ul><p>Která z následujících možností je NEJLEPŠÍ sadou vstupních testovacích dat pro pokrytí identifikovaných tříd ekvivalence?<\/p>","m":["12, 1111, 1234, 12345","1, 123, 1111, 1234","11, 12, 1111, 12345","123, 1222, 12345"],"ok":[0],"vys":{"a":"Je správně.<ul><li>Hodnota \"12\" pokrývá \"nesprávná délka - málo číslic\".<\/li><li>Hodnota \"1111\" pokrývá \"správná délka\" a \"nesprávný počet odlišných číslic\".<\/li><li>Hodnota \"1234\" pokrývá \"správná délka\" a \"správný počet odlišných číslic\".<\/li><li>Hodnota \"12345\" pokrývá \"nesprávná délka - příliš mnoho číslic\".<\/li><\/ul>","b":"Není správně. Všechny třídy jsou pokryty, ale u třídy \"nesprávná délka\" je pokryta pouze dolní část (tedy málo číslic).","c":"Není správně. Neexistují žádné hodnoty pokrývající \"správný PIN\".","d":"Není správně. Neexistuje žádná hodnota pokrývající \"počet odlišných číslic\"."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"},"id":"OF-C20","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 20 (© ISTQB®, překlad CaSQB)"},{"n":21,"lo":"FL-4.2.2","k":"K3","vyber":1,"q":"<p>Vývojář byl požádán, aby implementoval následující byznysové pravidlo:<\/p><pre>VSTUP: hodnota (celé číslo)\nPOKUD (hodnota ≤ 100 NEBO hodnota ≥ 200) POTOM napiš \"Hodnota je nesprávná\"\nJINAK napiš \"Hodnota OK\"<\/pre><p>Navrhujete testovací případy pomocí 2-hodnotové analýzy hraničních hodnot.<\/p><p>Která z následujících sad testovacích vstupů dosahuje největšího pokrytí?<\/p>","m":["100, 150, 200, 201,","99, 100, 200, 201,","98, 99, 100, 101,","101, 150, 199, 200,"],"ok":[3],"vys":{"a":"Není správně. Pouze 100 a 200 jsou platné položky pokrytí pro 2-hodnotové BVA, takže je dosaženo 50 % pokrytí.","b":"Není správně. Pouze 100 a 200 jsou platné položky pokrytí pro 2-hodnotové BVA, takže je dosaženo 50 % pokrytí.","c":"Není správně. Pouze 100 a 101 jsou platné položky pokrytí pro 2-hodnotové BVA, takže je dosaženo 50 % pokrytí.","d":"Je správně. Hodnoty 101, 199 a 200 jsou platné položky pokrytí pro 2-hodnotové BVA, takže je dosaženo 75 % pokrytí."},"obecne":"<p>Třídy ekvivalence jsou: {..., 99, 100}, {101, 102, ..., 198, 199}, {200, 201, ...}.<\/p><p>Existují tedy 4 hraniční hodnoty, kterými jsou: 100, 101, 199 a 200.<\/p><p>V případě 2-hodnotové varianty BVA existují pro každou hraniční hodnotu dvě položky pokrytí (daná hraniční hodnota a její nejbližší soused patřící do vedlejší třídy). Protože nejbližší sousedé jsou zároveň hraničními hodnotami v sousední třídě, pak existují pouze čtyři položky pokrytí.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"},"id":"OF-C21","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 21 (© ISTQB®, překlad CaSQB)"},{"n":22,"lo":"FL-4.2.3","k":"K3","vyber":1,"q":"<p>Pracujete na projektu, jehož cílem je vyvinout systém pro analýzu výsledků řidičských zkoušek. Byli jste požádáni, abyste navrhli testovací případy na základě následující rozhodovací tabulky (F-false/nepravda, T-true/pravda, znak - znamená, že hodnota podmínky je pro výsledek akce výstup irelevantní):<\/p><table><thead><tr><th><\/th><th>R1<\/th><th>R2<\/th><th>R3<\/th><\/tr><\/thead><tbody><tr><th>C1: První pokus o zkoušku?<\/th><td>-<\/td><td>-<\/td><td>F<\/td><\/tr><tr><th>C2: Teoretická zkouška složena?<\/th><td>T<\/td><td>F<\/td><td>-<\/td><\/tr><tr><th>C3: Praktická zkouška složena?<\/th><td>T<\/td><td>-<\/td><td>F<\/td><\/tr><tr><th>Vydat řidičský průkaz?<\/th><td>X<\/td><td><\/td><td><\/td><\/tr><tr><th>Požádat o další lekce v řízení?<\/th><td><\/td><td><\/td><td>X<\/td><\/tr><tr><th>Požádat o opakování zkoušky?<\/th><td><\/td><td>X<\/td><td><\/td><\/tr><\/tbody><\/table><p>Jaká testovací data prokáží, že v rozhodovací tabulce existují protichůdná pravidla?<\/p>","m":["C1 = T, C2 = T, C3 = F","C1 = T, C2 = F, C3 = T","C1 = T, C2 = T, C3 = T a C1 = F, C2 = T, C3 = T.","C1 = F, C2 = F, C3 = F"],"ok":[3],"vys":{"a":"Není správně. Kombinace (T, T, F) neodpovídá žádnému pravidlu. Jedná se o příklad opomenutí, nikoliv rozporu.","b":"Není správně. Kombinace (T, F, T) odpovídá pouze jednomu sloupci R2, takže zde neexistuje žádný rozpor.","c":"Není správně. Obě kombinace (T, T, T) a (F, T, T) odpovídají pouze jednomu sloupci R1, takže zde neexistuje žádný rozpor.","d":"Je správně. Kombinace (F, F, F) odpovídá R2 i R3, ale R2 a R3 mají různé akce. Tím existuje mezi R2 a R3 rozpor."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"},"id":"OF-C22","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 22 (© ISTQB®, překlad CaSQB)"},{"n":23,"lo":"FL-4.2.4","k":"K3","vyber":1,"q":"<p>Navrhujete testovací případy na základě následujícího stavového diagramu.<\/p><img src=\"assets/vzorove/c-23.png\" alt=\"Stavový diagram: START, ŽÁDOST, VE FRONTĚ, POTVRZENO, KONEC s přechody Žádost o pokoj, Je k dispozici, Není k dispozici, Zaplatit, Zrušit\"><p>Jaký je MINIMÁLNÍ počet testovacích případů potřebných k dosažení 100 % pokrytí platných přechodů?<\/p>","m":["3","2","5","6"],"ok":[0],"vys":{"a":"Je správně.","b":"Není správně.","c":"Není správně.","d":"Není správně."},"obecne":"<p>Následující tři přechody:<\/p><p>\"ŽÁDOST -&gt; POTVRZENO\" \"VE FRONTĚ -&gt; POTVRZENO\" \"VE FRONTĚ -&gt; KONEC\" se nemohou vyskytovat ve stejném testovacím případu, což naznačuje, že jsou zapotřebí alespoň tři testovací případy. Všechny ostatní přechody se mohou objevit v kombinaci s jedním nebo více z těchto tří přechodů, takže potřebujeme minimálně tři testovací případy. Ve skutečnosti jsou možné pouze tři sekvence:<\/p><p>TC1: START (Žádost o pokoj) → ŽÁDOST (Je k dispozici) → POTVRZENO (Zaplatit) → KONEC TC2: START (Žádost o pokoj) → ŽÁDOST (Není k dispozici) → VE FRONTĚ (Je k dispozici) → POTVRZENO (Zaplatit) → KONEC TC3: START (Žádost o pokoj) → ŽÁDOST (Není k dispozici) → VE FRONTĚ (Zrušit) → KONEC Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"},"id":"OF-C23","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 23 (© ISTQB®, překlad CaSQB)"},{"n":24,"lo":"FL-4.3.2","k":"K2","vyber":1,"q":"<p>Chcete použít testování větví na kód reprezentovaný následujícím grafem řídícího toku.<\/p><img src=\"assets/vzorove/c-24.png\" alt=\"Graf řídicího toku se 7 uzly a 8 hranami\"><p>Kolik položek pokrytí potřebujete otestovat?<\/p>","m":["2","4","8","7"],"ok":[2],"vys":{"a":"Není správně.","b":"Není správně.","c":"Je správně.","d":"Není správně."},"obecne":"<p>Při testování větví jsou položkami pokrytí větve, které jsou reprezentovány hranami (spojnicemi) v grafu řídicího toku. V něm je 8 hran.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.3.2","nazev":"Testování a pokrytí větví","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-dva-testovani-a-pokryti-vetvi"},"id":"OF-C24","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 24 (© ISTQB®, překlad CaSQB)"},{"n":25,"lo":"FL-4.3.3","k":"K2","vyber":1,"q":"<p>Jak může být testování bílé skříňky užitečné pro podporu testování černé skříňky?<\/p>","m":["Metriky pokrytí bílé skříňky mohou testerům pomoci vyhodnotit testy černé skříňky z hlediska pokrytí kódu dosaženého těmito testy černé skříňky.","Analýza pokrytí testů bílé skříňky může testerům pomoci identifikovat nedosažitelné části zdrojového kódu.","Testování větví zahrnuje techniky testování černé skříňky, takže dosažení plného pokrytí větví zaručuje dosažení plného pokrytí jakékoli techniky černé skříňky.","Technika testování bílé skříňky může poskytnout položky pokrytí pro techniky testování černé skříňky."],"ok":[0],"vys":{"a":"Je správně. Pouhé testování pomocí technik černé skříňky neposkytuje informace o míře skutečného pokrytí kódu. Naopak výsledky testování s využitím technik bílé skříňky poskytují objektivní měření pokrytí, poskytují také nezbytné informace umožňující vytváření dalších testů s cílem zvýšení tohoto pokrytí a následného zvýšení důvěry v kód.","b":"Není správně. Toto tvrzení je správné, ale nemá nic společného s testováním černé skříňky.","c":"Není správně. Mezi technikami testování bílé skříňky a technikami černé skříňky obecně neexistuje žádný vztah.","d":"Není správně. Testovací techniky bílé skříňky se používají k návrhu testů na základě samotného testovaného objektu, zatímco testovací techniky černé skříňky se používají k návrhu testů na základě specifikace. Proto neexistuje žádný vztah mezi položkami pokrytí odvozenými z těchto dvou typů testovacích technik."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"},"id":"OF-C25","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 25 (© ISTQB®, překlad CaSQB)"},{"n":26,"lo":"FL-4.4.1","k":"K2","vyber":1,"q":"<p>Předpokládejte, že máte k dispozici následující seznam:<\/p><ul><li>Správný vstup není přijat<\/li><li>Nesprávný vstup je přijat<\/li><li>Špatný výstupní formát<\/li><li>Dělení nulou<\/li><\/ul><p>Jakou testovací techniku NEJPRAVDĚPODOBNĚJI používá tester, který se při testování řídí tímto seznamem?<\/p>","m":["Průzkumné testování.","Útok na chyby.","Testování založené na kontrolních seznamech.","Analýza hraničních hodnot."],"ok":[1],"vys":{"a":"Není správně. Průzkumné testování používá testovací listiny, nikoli seznam možných defektů/selhání. Ačkoli může průzkumné testování využívat i jiné testovací techniky, v tomto případě je nejpravděpodobnější možností technika útok na chyby.","b":"Je správně. Toto je seznam možných selhání. Útoky na chyby jsou metodickým přístupem jak provést odhadování chyb a vyžadují, aby tester vytvořil nebo získal seznam možných chyb, defektů a selhání. Na základě tohoto seznamu navrhne testy, které identifikují defekty spojené s těmito chybami, odhalí je nebo způsobí selhání.","c":"Není správně. Tester používá kontrolní seznam položek, který mu pomáhá při testování. Jak odhadování chyb, tak testování na základě kontrolních seznamů takové seznamy používají, nicméně zde se jedná o seznam možných selhání, nikoliv o testovací podmínky, a proto je NEJPRAVDĚPODOBNĚJŠÍ testovací technikou útok na chyby, protože se zaměřuje na chyby, defekty a selhání.","d":"Není správně. Technika analýzy hraničních hodnot (BVA) je založena na analýze hraničních hodnot tříd ekvivalence. Výše uvedený seznam nezmiňuje třídy ekvivalence ani jejich hranice."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"},"id":"OF-C26","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 26 (© ISTQB®, překlad CaSQB)"},{"n":27,"lo":"FL-4.4.3","k":"K2","vyber":1,"q":"<p>Která z následujících možností NEJLÉPE popisuje, jak může testování založené na kontrolních seznamech vést ke zvýšení pokrytí?<\/p>","m":["Položky kontrolního seznamu lze definovat na dostatečně nízké úrovni detailu, takže tester může na základě těchto položek implementovat a provádět podrobné testovací případy.","Kontrolní seznamy lze automatizovat, takže každé automatické provedení testu pokrývá položky kontrolního seznamu, což vede k vyššímu pokrytí.","Každá položka kontrolního seznamu by měla být testována samostatně a nezávisle tak, aby jednotlivé prvky pokrývaly různé oblasti softwaru.","Dva testeři, kteří navrhují a provádějí testy na základě stejných položek obecného kontrolního seznamu (high-level) obvykle provedou testování mírně odlišnými způsoby."],"ok":[3],"vys":{"a":"Není správně. Je sice pravda, že tester může na základě kontrolního seznamu vytvářet a provádět detailní (tedy ne obecné) testovací případy, nevysvětluje to ale, jak by to mělo vést ke zvýšení pokrytí.","b":"Není správně. Položky kontrolního seznamu by neměly být automatizovány. I kdyby ale byly, automatizované testovací skripty provádějí testy vždy stejným způsobem, což obvykle nevede ke zvýšení pokrytí.","c":"Není správně. Je pravda, že každá položka kontrolního seznamu by měla být testována samostatně a nezávisle. To však ovlivňuje pořadí provedení testů bez vlivu na dosažené pokrytí, takže nemůže vést ke zvýšení pokrytí.","d":"Je správně. Jelikož se jedná o obecné kontrolní seznamy (high-level), je pravděpodobné, že se v daném testování může objevit určitá variabilita, což může přispět k většímu pokrytí, ale i k menší míře opakovatelnosti testování. Pokud dva testeři postupují podle kontrolního seznamu na obecné úrovni, každý z nich může použít jiná testovací data, jiné testovací kroky apod. Tímto způsobem první tester pravděpodobně otestuje oblasti, které druhý tester ne, což povede k většímu pokrytí."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.4.3","nazev":"Testování založené na kontrolních seznamech","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-tri-testovani-zalozene-na-kontrolnich-seznamech"},"id":"OF-C27","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 27 (© ISTQB®, překlad CaSQB)"},{"n":28,"lo":"FL-4.5.2","k":"K2","vyber":1,"q":"<p>Která z následujících možností je NEJLEPŠÍM příkladem akceptačního kritéria orientovaného na scénář?<\/p>","m":["Aplikace musí uživatelům umožnit smazat na požádání jejich účet a všechny související údaje.","Když zákazník přidá položku do košíku a přejde k pokladně, měl by být vyzván k přihlášení nebo vytvoření účtu (pokud tak ještě neučinil).","POKUD (obsahuje(produkt(23).Jméno, košík.produkty())) POTÉ vrátit NEPRAVDA.","Webové stránky musí být v souladu se zákonem č.99/2019 Sb. tak, aby byl jejich obsah přístupný pro pro osoby se zdravotním postižením."],"ok":[1],"vys":{"a":"Není správně. Toto akceptační kritérium popisuje, jaká pravidla nebo předpisy musí systém dodržovat (v tomto případě právo být zapomenut). Jedná se tedy o příklad kritéria orientovaného na pravidla.","b":"Je správně. Toto akceptační kritérium popisuje příklad scénáře, který musí být v systému realizován. Jedná se tedy o je příklad kritéria orientovaného na scénář.","c":"Není správně. Tato věta vypadá spíše jako řádek kódu, který implementuje nějaké byznysové pravidlo. Akceptační kritéria by měla být sepsána ve spolupráci se zástupci byznysu, a proto by měla být napsána v jazyce, kterému rozumí. Tato věta bude pro ně pravděpodobně nesrozumitelná.","d":"Není správně. Toto akceptační kritérium popisuje, s jakými pravidly nebo předpisy musí být systém v souladu a jak bude tento soulad zajištěn. Jedná se tedy o příklad kritéria orientovaného na pravidla, nikoliv kritéria založeného na scénáři."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.5.2","nazev":"Akceptační kritéria","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-dva-akceptacni-kriteria"},"id":"OF-C28","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 28 (© ISTQB®, překlad CaSQB)"},{"n":29,"lo":"FL-4.5.3","k":"K3","vyber":1,"q":"<p>Používáte vývoj řízený akceptačními testy a navrhujete testovací případy na základě následujícího uživatelského scénáře:<\/p><p>Jako běžný nebo speciální uživatel chci mít možnost používat elektronickou kartu pro přístup do konkrétních podlaží.<\/p><p>Akceptační kritéria.<\/p><p>AC1: Běžní uživatelé mají přístup do pater 1 až 3.<\/p><p>AC2: 4. patro je přístupné pouze speciálním uživatelům.<\/p><p>AC3: Speciální uživatelé mají všechna přístupová práva běžných uživatelů.<\/p><p>Který testovací případ je NEJVHODNĚJŠÍ pro testování AC3?<\/p>","m":["Prověřte, zda má běžný uživatel přístup do pater 1 a 3.","Prověřte, zda nemá běžný uživatel přístup do 4. patra.","Prověřte, zda má speciální uživatel přístup do 5. patra.","Prověřte, zda má speciální uživatel přístup do pater 1, 2 a 3."],"ok":[3],"vys":{"a":"Není správně. Chceme zkontrolovat, zda mají speciální uživatelé práva běžných uživatelů, takže potřebujeme otestovat přístupová práva pro speciálního uživatele, nikoli pro běžného uživatele.","b":"Není správně. Chceme zkontrolovat, zda mají speciální uživatelé práva běžných uživatelů, takže potřebujeme otestovat přístupová práva pro speciálního uživatele, nikoli pro běžného uživatele.","c":"Není správně. V akceptačních kritériích není popsáno žádné podlaží 5. Testovací případy by neměly rozšiřovat rozsah uživatelského scénáře. I kdybychom chtěli provést negativní testování, nebude tento test přímo souviset s AC3.","d":"Je správně. Tímto způsobem můžeme zkontrolovat, zda má speciální uživatel přístup k podlažím, která jsou přístupná běžnému uživateli."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"},"id":"OF-C29","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 29 (© ISTQB®, překlad CaSQB)"},{"n":30,"lo":"FL-5.1.1","k":"K2","vyber":1,"q":"<p>Která z následujících možností NENÍ účelem plánu testování?<\/p>","m":["Definovat testovací data a očekávané výsledky pro testy komponent a integrační testy komponent.","Jako výstupní kritérium z úrovně testování komponent definovat, že \"musí být dosaženo 100 % pokrytí příkazů a 100 % pokrytí větví\".","Popsat, jaká pole má report o postupu prací při testování obsahovat a jakou má mít tento report podobu.","Vysvětlit, proč bude systémové integrační testování vyloučeno z testování, ačkoli testovací strategie tuto úroveň testování předepisuje."],"ok":[0],"vys":{"a":"Je správně. Plán testování může obsahovat požadavky na testovací data (jako součást přístupu k testování), ale nikoliv konkrétní testovací data využitelná v testovacích případech. Testovací data jsou součástí testovacích případů, nikoliv plánu testů. Při tvorbě plánu testů také obvykle není možné tato data definovat, protože není přesně známo, jak budou komponenty vypadat.","b":"Není správně. Jedním z účelů plánu testování je pomoci zajistit, aby testovací činnosti splňovaly stanovená kritéria, a to zahrnutím vstupních a výstupních kritérií. Kritéria pokrytí kódu jsou příkladem takových kritérií v úrovni testování komponent.","c":"Není správně. Typickým obsahem plánu testů jsou šablony dokumentace. To pomáhá usnadnit komunikaci mezi zainteresovanými stranami definováním standardního způsobu komunikace nebo reportování.","d":"Není správně. Jedním z účelů plánu testování je prokázat, že testování je v souladu se stávající politikou a strategií testování, nebo vysvětlit, proč se od nich testování odchyluje. Tato možnost je příkladem vysvětlení takové odchylky a týká se úrovní testování, které budou (nebo nebudou) použity."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.1.1","nazev":"Účel a obsah plánu testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-jedna-ucel-a-obsah-planu-testovani"},"id":"OF-C30","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 30 (© ISTQB®, překlad CaSQB)"},{"n":31,"lo":"FL-5.1.4","k":"K3","vyber":1,"q":"<p>Na začátku každé iterace tým odhadne množství práce (v člověkodnech), které bude muset během iterace vykonat. Nechť E(n) je odhadovaný a A(n) skutečný objem práce pro iteraci n. Od třetí iterace tým používá následující model odhadu založený na extrapolaci:<\/p><p><img src=\"assets/vzorove/c-31.png\" alt=\"E(n) = (3 * A(n − 1) + A(n − 2)) / 4\"><\/p><p>Graf ukazuje odhadovaný a skutečný objem práce pro první čtyři iterace.<\/p><img src=\"assets/vzorove/c-31-2.png\" alt=\"Sloupcový graf Odhadovaná a skutečná pracnost (v člověkodnech): iterace 1 odhad 8, skutečnost 7; iterace 2 odhad 7, skutečnost 12; iterace 3 odhad 10,75, skutečnost 8; iterace 4 odhad 9, skutečnost 6\"><p>Jaký je odhadovaný objem práce pro iteraci č. 5?<\/p>","m":["10,5 člověkodnů","8,25 člověkodnů","6,5 člověkodnů","9,4 člověkodnů"],"ok":[2],"vys":{"a":"Není správně.","b":"Není správně.","c":"Je správně.","d":"Není správně."},"obecne":"<p>Z grafu vyplývá:<\/p><p>A(4)=6 a A(3)=8 (poslední dvě šedá pole).<\/p><p>Ze vzorce získáme:<\/p><p>E(5) = (3*A(4) + A(3)) / 4 = (3*6+8) / 4 = 26 / 4 = 6,5 člověkodní.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"},"id":"OF-C31","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 31 (© ISTQB®, překlad CaSQB)"},{"n":32,"lo":"FL-5.1.5","k":"K3","vyber":1,"q":"<p>Připravujete harmonogram provádění testů pro provedení sedmi testovacích případů TC 1 až TC 7.<\/p><p>Následující obrázek znázorňuje priority těchto testovacích případů (1 = nejvyšší priorita, 3 = nejnižší priorita).<\/p><p>Na obrázku jsou také pomocí šipek znázorněny závislosti mezi testovacími případy. Například šipka z TC 4 do TC 5 znamená, že TC 5 lze provést pouze tehdy, pokud byl předtím proveden TC 4.<\/p><img src=\"assets/vzorove/c-32.png\" alt=\"Závislosti testovacích případů: TC 1 (priorita 2) → TC 2 (3) → TC 5 (1) → TC 6 (3); TC 4 (2) → TC 5 a TC 7 (1); TC 3 (2) bez závislostí\"><p>Který testovací případ by měl být proveden jako šestý?<\/p>","m":["TC 3","TC 5","TC 6","TC 2"],"ok":[0],"vys":{"a":"Je správně.","b":"Není správně.","c":"Není správně.","d":"Není správně."},"obecne":"<p>Chceme sice provést testovací případy podle jejich priorit, ale musíme také zohlednit závislosti.<\/p><p>Pokud bereme v úvahu pouze priority, chceme nejprve spustit TC 5 a TC 7 (nejvyšší priorita), poté TC 1, TC 3 a TC 4 a nakonec TC 2 a TC 6 (nejnižší priorita).<\/p><p>Abychom však mohli spustit TC 7, musíme nejprve spustit TC 4.<\/p><p>Abychom mohli spustit TC 5, musíme spustit TC 4 a TC 2, ale TC 2 je blokován TC 1, který by měl být spuštěn před TC 2.<\/p><p>Aby bylo možné spustit testovací případy s prioritou 1 co nejdříve, mělo by být pořadí prvních pět testovacích případů následující: TC 4 - TC 7 - TC 1 - TC 2 - TC 5.<\/p><p>Dále musíme spustit TC 3, protože má vyšší prioritu než TC 6.<\/p><p>Úplný harmonogram tedy bude vypadat následovně: TC 4 - TC 7 - TC 1 - TC 2 - TC 5 - TC 3 - TC 6.<\/p><p>Šestým testovacím případem tedy bude TC 3.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"},"id":"OF-C32","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 32 (© ISTQB®, překlad CaSQB)"},{"n":33,"lo":"FL-5.1.6","k":"K1","vyber":1,"q":"<p>Co ukazuje model testovací pyramidy?<\/p>","m":["Že testy mohou mít různé priority.","Že testy mohou mít různou granularitu.","Že testy mohou vyžadovat různá kritéria pokrytí.","Že testy mohou záviset na jiných testech."],"ok":[1],"vys":{"a":"Není správně. Testovací pyramida neobsahuje informace o prioritách testů.","b":"Je správně. Testovací pyramida ukazuje, že různé testy mají různé úrovně granularity.","c":"Není správně. Testovací pyramida je nezávislá na kritériích pokrytí.","d":"Není správně. Testovací pyramida neznázorňuje žádné vztahy mezi jednotlivými testy."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.1.6","nazev":"Testovací pyramida","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sest-testovaci-pyramida"},"id":"OF-C33","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 33 (© ISTQB®, překlad CaSQB)"},{"n":34,"lo":"FL-5.1.7","k":"K2","vyber":1,"q":"<p>Jaký je vztah mezi testovacími kvadranty, úrovněmi testování a typy testů?<\/p>","m":["Testovací kvadranty představují konkrétní kombinace úrovní a typů testů a definují jejich umístění v životním cyklu vývoje softwaru.","Testovací kvadranty popisují míru granularity jednotlivých typů testů prováděných v každé úrovni testování.","Testovací kvadranty přiřazují k jednotlivým úrovním testování typy testů, které v nich lze provést.","Testovací kvadranty sdružují úrovně testování a typy testů podle několika kritérií, jako je zacílení na konkrétní zainteresované strany."],"ok":[3],"vys":{"a":"Není správně. Testovací kvadranty seskupují úrovně testování a typy testů odděleně podle několika kritérií. Nepředstavují žádné kombinace úrovní testování a typů testů a nesouvisí s žádným umístěním v rámci životního cyklu vývoje softwaru. Jak typy testů, tak testovací úrovně jsou v testovacích kvadrantech řešeny odděleně.","b":"Není správně. Testovací kvadranty seskupují testovací úrovně a typy testů podle několika kritérií. Nepopisují míru granularity jednotlivých typů testů prováděných v jednotlivých úrovních testování (tuto informaci obsahuje testovací pyramida).","c":"Není správně. Toto tvrzení je chybné, protože obecně lze provést jakýkoli typ testu v jakékoli úrovni testování.","d":"Je správně. Kvadranty testování (používané zejména v agilním vývoji softwaru) seskupují úrovně testování, typy testů, činnosti, techniky testování a pracovní produkty. V tomto modelu mohou být testy zaměřené na byznys nebo na technologii a mohou také podporovat tým (tj. usměrňovat vývojové aktivity) nebo kritizovat produkt (tj. měřit jeho chování proti očekáváním). Kombinací těchto dvou úhlů pohledu je určen každý ze čtyř kvadrantů."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"},"id":"OF-C34","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 34 (© ISTQB®, překlad CaSQB)"},{"n":35,"lo":"FL-5.2.3","k":"K2","vyber":1,"q":"<p>Která z následujících možností je příkladem toho, jak analýza produktových rizik ovlivňuje důkladnost a rozsah testování?<\/p>","m":["Průběžný monitoring rizik nám umožňuje co nejdříve identifikovat nově vznikající rizika.","Identifikace rizik nám umožňuje implementovat zmírňující opatření a snížit tak jejich úroveň.","Ohodnocená úroveň rizika nám pomáhá zvolit míru důkladnosti testování.","Analýza rizik nám umožňuje odvodit položky pokrytí."],"ok":[2],"vys":{"a":"Není správně. Monitoring rizik je součástí řízení rizik, nikoli analýzy rizik.","b":"Není správně. Samotná identifikace rizik nám neumožňuje provádět aktivity na jejich zmírnění. Zmírňující opatření jsou definována ve fázi řízení rizik.","c":"Je správně. Toto je příklad toho, jak analýza rizik ovlivňuje důkladnost a rozsah testování.","d":"Není správně. Položky pokrytí jsou odvozeny pomocí testovacích technik, nikoli pomocí analýzy rizik."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.2.3","nazev":"Analýza produktových rizik","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-tri-analyza-produktovych-rizik"},"id":"OF-C35","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 35 (© ISTQB®, překlad CaSQB)"},{"n":36,"lo":"FL-5.3.2","k":"K2","vyber":1,"q":"<p>Která z následujících činností v procesu testování NEJVÍCE využívá reporty o postupu prací při testování?<\/p>","m":["Návrh testů.","Dokončení testování.","Testovací analýza.","Plánování testování."],"ok":[1],"vys":{"a":"Není správně. Reporty o postupu prací při testování se většinou používají při monitoringu, řízení a dokončení testování, nikoliv při návrhu testů.","b":"Je správně. Souhrnný report z testování se připravuje v průběhu fáze dokončení testování, kdy je projekt, úroveň testování nebo typ testů ukončen, a kdy jsou (v ideálním případě) splněna stanovená výstupní kritéria. Tento report využívá informace z dílčích reportů o postupu prací při testování, ale i jiné zdroje dat.","c":"Není správně. Reporty o průběhu testování se většinou používají při monitorování a kontrole testů a při dokončení testování, nikoli při testovací analýze.","d":"Není správně. Zprávy o průběhu testování se většinou používají při monitorování testování, řízení testování a při dokončení testování, nikoli při plánování testování."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"},"id":"OF-C36","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 36 (© ISTQB®, překlad CaSQB)"},{"n":37,"lo":"FL-5.4.1","k":"K2","vyber":1,"q":"<p>Která z následujících možností NENÍ příkladem toho, jak konfigurační management podporuje testování?<\/p>","m":["Všechny commity do repozitáře jsou jednoznačně identifikovány a jejich verze jsou řízeny.","Všechny změny v prvcích testovacího prostředí jsou sledovány.","Na všechny specifikace požadavků je v testovacích plánech jednoznačně odkazováno.","Všechny identifikované defekty mají přiřazený stav."],"ok":[3],"vys":{"a":"Není správně. Když uživatel nahlásí selhání v softwaru, díky jedinečné identifikaci commitů je možné znovu sestavit soubory z verze softwaru, kterou uživatel používal (stejně jako související verze testovacích skriptů), a tím reprodukovat selhání a rychleji nalézt defekt.","b":"Není správně. Pokud změna v testovacím prostředí způsobí během testování neočekávané problémy, konfigurační management umožňuje testerům vrátit se k předchozí verzi prostředí. Tím je zajištěno, že testování může pokračovat, aniž by bylo ovlivněno touto změnou.","c":"Není správně. Konfigurační management zajišťuje, že veškerá identifikovaná dokumentace (např. specifikace požadavků) a softwarové položky jsou jednoznačně uvedeny v testovací dokumentaci (např. v testovacích plánech).","d":"Je správně. Toto je zajištěno v rámci procesu managementu defektů, nikoliv konfiguračního managementu."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"},"id":"OF-C37","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 37 (© ISTQB®, překlad CaSQB)"},{"n":38,"lo":"FL-5.5.1","k":"K3","vyber":1,"q":"<p>Předpokládejme existenci následujícího reportu o defektu webové nákupní aplikace:<\/p><blockquote><p>Aplikace: WebShop v0.99<\/p><p>Defekt: Nefunguje tlačítko pro přihlášení.<\/p><p>Kroky k reprodukci defektu:<\/p><p>Otevřete webovou stránku.<br>Klikněte na přihlašovací tlačítko.<\/p><p>Očekávaný výsledek: Uživatel by měl být přesměrován na přihlašovací stránku.<br>Skutečný výsledek: Přihlašovací tlačítko po kliknutí nereaguje.<\/p><p>Závažnost: Vysoká<br>Priorita: Naléhavé<\/p><\/blockquote><p>Jaká NEJDŮLEŽITĚJŠÍ informace v tomto report o defektu chybí?<\/p>","m":["Jméno testera a datum","Identifikace prvků testovacího prostředí a číslo jejich verze.","Identifikace testovaného objektu.","Dopad na zájmy zainteresovaných stran."],"ok":[1],"vys":{"a":"Není správně. Tyto údaje jsou důležité, ale ne tak důležité jako prvky testovacího prostředí.","b":"Je správně. Důležité je, že chybí identifikace prohlížeče a zařízení použitého při testování. Tyto informace jsou důležité, protože defekt může být specifický pro určitý prohlížeč nebo určité zařízení. Například přihlašovací tlačítko může v jednom prohlížeči (nebo v jedné verzi určitého prohlížeče) fungovat správně, ale v jiném ne. Informace o prohlížeči a zařízení proto mohou vývojářům pomoci reprodukovat problém a rychleji najít jeho kořenovou příčinu.","c":"Není správně. Testovaný objekt je identifikován (WebShop v0.99)","d":"Není správně. Dopad je v reportu zahrnut ve formě závažnosti (vysoká)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"},"id":"OF-C38","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 38 (© ISTQB®, překlad CaSQB)"},{"n":39,"lo":"FL-6.1.1","k":"K2","vyber":1,"q":"<p>Které nástroje z následujících kategorií pomáhají s organizací testovacích případů a nalezených defektů a s konfiguračním managementem?<\/p>","m":["Nástroje pro provádění testů a pokrytí.","Nástroje pro návrh testů a implementaci testování.","Nástroje pro management defektů.","Nástroje pro management testování."],"ok":[3],"vys":{"a":"Není správně. Nástroje pro provedení testů a měření pokrytí usnadňují automatizované provedení testovacích případů a měření pokrytí dosaženého spuštěním těchto testovacích případů. Tyto nástroje však nepomáhají se správou defektů a konfiguračním managementem.","b":"Není správně. Nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, testovacích dat a testovacích procedur, ale nepomáhají se správou defektů a konfiguračním managementem.","c":"Není správně. Nástroje pro management defektů se používají k managementu defektů, ale nejsou to nástroje pro testování a nepoužívají se ke správě testovacích případů nebo ke konfiguračnímu managementu.","d":"Je správně. Nástroje pro management testování zvyšují efektivitu procesu testování tím, že usnadňují management životního cyklu vývoje softwaru (SDLC), požadavků, testů, defektů a konfigurační management."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"},"id":"OF-C39","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 39 (© ISTQB®, překlad CaSQB)"},{"n":40,"lo":"FL-6.2.1","k":"K1","vyber":1,"q":"<p>Která z následujících možností bude s NEJVĚTŠÍ pravděpodobností přínosem automatizace testování?<\/p>","m":["Možnost generování testovacích případů bez přístupu k testovací bázi.","Dosažení většího pokrytí prostřednictvím objektivnějšího hodnocení.","Prodloužení doby provádění testů díky vyššímu výpočetnímu výkonu.","Prevence lidských chyb prostřednictvím vyšší konzistence a opakovatelnosti."],"ok":[3],"vys":{"a":"Není správně. Generování testovacích případů bez přístupu k testovací bázi není možné. Generování testovacích případů testery nebo nástroji vyžaduje přístup k testovací bázi.","b":"Není správně. Dosažení většího pokrytí díky objektivnějšímu hodnocení není přímým přínosem automatizace testování. Automatizace testování umožní objektivnější posouzení pokrytí, avšak toto objektivní posouzení nezvýší pokrytí (pouze použitím výsledků pokrytí k psaní dalších testovacích případů lze zvýšit pokrytí).","c":"Není správně. \"Prodloužení doby provádění testů, které je k dispozici s vyšším výpočetním výkonem\" je protichůdné tvrzení, protože vyšší výpočetní výkon by za normálních okolností zkrátil dobu provádění testů, a prodloužení doby provádění testů není přínosem, protože testování by trvalo déle.","d":"Je správně. Výhodou automatizace testování je prevence lidských chyb díky větší konzistenci a opakovatelnosti, protože automatizace testování není náchylná k lidským chybám. Znamená to například, že testy jsou důsledně odvozovány z požadavků, testovací data jsou vytvářena systematicky a testy jsou nástrojem prováděny ve stejném pořadí a se stejnou frekvencí."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"},"id":"OF-C40","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška C, otázka 40 (© ISTQB®, překlad CaSQB)"},{"n":1,"lo":"FL-1.1.1","k":"K1","vyber":1,"q":"<p>Která z následujících možností je typickým cílem testování?<\/p>","m":["Nalezení a oprava defektů v testovaném objektu.","Udržování efektivní komunikace s vývojáři.","Validace splnění zákonných požadavků.","Budování důvěry v kvalitu testovaného objektu."],"ok":[3],"vys":{"a":"Není správně. Nalezení a oprava defektů v testovaném objektu není typickým cílem testování. Identifikace defektů sice je cílem testování, ale oprava defektů už nepatří mezi testovací činnosti.","b":"Není správně. Udržování efektivní komunikace s vývojáři není typickým cílem testování. Komunikace je užitečná pro dosažení dalších cílů testování (např. poskytování informací zainteresovaným stranám tak, aby mohly přijmout kvalifikovaná rozhodnutí), není to však primární důvod, proč se testuje.","c":"Není správně. Validace, zda byly splněny zákonné požadavky, není typickým cílem testování. Validace se týká kontroly, že systém splňuje potřeby uživatelů a ostatních zainteresovaných stran v provozním prostředí. Kontrola splnění zákonných požadavků je jednou z forem ověřování.","d":"Je správně. Budování důvěry v kvalitu testovaného objektu je dosaženo úspěšným provedením testů."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.1.1","nazev":"Typické cíle testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-jedna-tecka-jedna-typicke-cile-testovani"},"id":"OF-D1","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 1 (© ISTQB®, překlad CaSQB)"},{"n":2,"lo":"FL-1.2.3","k":"K2","vyber":1,"q":"<p>Návrhář (designér) kvůli únavě nevhodně navrhl uživatelské rozhraní. V důsledku toho není rozhraní přizpůsobeno uživatelům se zdravotním postižením. Programátor implementuje uživatelské rozhraní podle návrhu, ale jelikož je pod velkým časovým tlakem, nezačlení do kódu vhodné ošetření výjimek pro výpočty bonusů. Během provozu systému se objeví stížnosti od některých uživatelů se zdravotním postižením ohledně rozhraní, načež je společnost pokutována příslušným regulačním orgánem (úřadem). Nikdo si nevšimne, že výpočty bonusů jsou někdy nesprávné.<\/p><p>Které z následujících tvrzení je SPRÁVNÉ?<\/p>","m":["Chybný výpočet bonusů je defekt, který se občas vyskytuje.","Pokuta obdržená za nezohlednění potřeb některých uživatelů se zdravotním postižením je selháním.","Kořenovou příčinou je programátor pracující pod velkým časovým tlakem.","Návrh uživatelského rozhraní obsahuje chybu návrháře (designéra)."],"ok":[2],"vys":{"a":"Není správně. Chybný výpočet bonusů je selháním systému, nikoliv defektem.","b":"Není správně. Systém, který nedostatečně podporuje uživatele se zdravotním postižením, je selháním, které nakonec vede k pokutě. Ale samotná pokuta selháním není (jde jen o důsledek správného fungování regulačního systému).","c":"Je správně. Chyba je na straně programátora a tato chyba je způsobena tím, že pracuje pod velkým časovým tlakem, což je kořenovou příčinou následného defektu.","d":"Není správně. Špatný návrh uživatelského rozhraní, který se vhodně nezabývá uživateli se zdravotním postižením, je defekt návrhu způsobený chybou designéra. Návrh uživatelského rozhraní tedy obsahuje defekt v návrhu, nikoli chybu designéra."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.2.3","nazev":"Chyby, defekty, selhání a kořenové příčiny","href":"kapitola-1/vyklad.html#cast-jedna-tecka-dva-tecka-tri-chyby-defekty-selhani-a-korenove-priciny"},"id":"OF-D2","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 2 (© ISTQB®, překlad CaSQB)"},{"n":3,"lo":"FL-1.3.1","k":"K2","vyber":1,"q":"<p>Testovací podmínky používají testeři k vytváření testovacích případů a provádění testů. Přestože se testovací podmínky nemění, testovací případy jsou pokaždé jiné. Kterého z následujících principů testování se týká tato obměna (variace) testovacích případů?<\/p>","m":["Testy se opotřebovávají.","Nepřítomnost defektů je klam.","Včasné testování šetří čas a peníze.","Shlukování defektů."],"ok":[0],"vys":{"a":"Je správně. Princip \"testy se opotřebovávají\" se týká myšlenky, že opakování stejných testů na nezměněném kódu pravděpodobně neodhalí nové defekty, a proto je nezbytné testy modifikovat. Díky použití testovacích podmínek je možné pokaždé vygenerovat nové testy (které nebudou identické s původními) a snížit tak riziko jejich opotřebení.","b":"Není správně. Princip \"nepřítomnost defektů je klam\" se zabývá zajištěním toho, aby byly potřeby uživatelů splněny i v případě, že se provede velké množství testů a nejsou nalezeny žádné defekty (tj. je nutná i validace). Použití testovacích podmínek pro generování testovacích případů a provádění s tímto principem nesouvisí.","c":"Není správně. Princip \"včasné testování šetří čas a peníze\" se týká včasného odstranění defektů s cílem zabránit vzniku následných defektů v odvozených pracovních produktech, čímž se sníží náklady a pravděpodobnost výskytu selhání. Obvykle je to řešeno co nejčasnějším zahájením testování (statického i dynamického), ale nesouvisí to s použitím testovacích podmínek pro generování testovacích případů a provádění testů.","d":"Není správně. Princip \"shlukování defektů\" se týká rozložení defektů v systému, které obvykle odpovídá rozdělení dle Paretova pravidla. Použití testovacích podmínek pro generování testovacích případů a provádění testů s tímto principem nesouvisí. Tento princip je obvykle aplikován testováním založeným na rizicích."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.3","nazev":"Principy testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-tri-principy-testovani"},"id":"OF-D3","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 3 (© ISTQB®, překlad CaSQB)"},{"n":4,"lo":"FL-1.4.1","k":"K2","vyber":1,"q":"<p>Jsou zadány následující testovací úkoly:<\/p><ol><li>Odvození testovacích případů z testovacích podmínek.<\/li><li>Identifikace opakovaně použitelného testwaru.<\/li><li>Uspořádání testovacích případů do testovacích procedur.<\/li><li>Vyhodnocení testovací báze a testovaného objektu.<\/li><\/ol><p>A následující testovací činnosti:<\/p><ol type=\"A\"><li>Testovací analýza.<\/li><li>Návrh testů.<\/li><li>Implementace testování.<\/li><li>Dokončení testování.<\/li><\/ol><p>Která z následujících možností NEJLÉPE přiřazuje úkoly k činnostem?<\/p>","m":["1B, 2A, 3D, 4C","1B, 2D, 3C, 4A","1C, 2A, 3B, 4D","1C, 2D, 3A, 4B"],"ok":[1],"vys":{"a":"Není správně.","b":"Je správně. Správná kombinace je: 1B, 2D, 3C, 4A","c":"Není správně.","d":"Není správně."},"obecne":"<p>S ohledem na jednotlivé uvedené testovací činnosti a jejich úkoly platí, že:<\/p><ol type=\"A\"><li>Testovací analýza: za účelem identifikace užitných vlastností (features) vyžadujících testování, se testovací báze analyzuje a jsou definovány testovací podmínky, které jsou následně prioritizovány spolu se souvisejícími riziky. Během testovací analýzy se obvykle odhalí defekty v testovací bázi a může se také posoudit testovatelnost testovaného objektu. (Úkol 4)<\/li><li>Návrh testů: zahrnuje použití testovacích podmínek k vytvoření testovacích případů a dalšího nezbytného testwaru jako jsou požadavky na testovací data a testovací listiny průzkumného testování. (Úkol 1)<\/li><li>Implementace testování: zahrnuje generování testovacích procedur jako jsou manuální a automatizované testovací skripty. Ty jsou vytvořeny z testovacích případů a mohou být sestaveny do testovacích sad. Testovací procedury jsou prioritizovány a uspořádány v harmonogramu provádění testů. (Úkol 3)<\/li><li>Ukončení testování: nastává při dosažení milníku projektu, jako je vydání verze, konec iterace nebo konec určité úrovně testování. Testware je identifikován a archivován, příp. předán příslušným týmům k opětovnému použití, testovací prostředí je uzavřeno a testovací činnosti jsou analyzovány s cílem získat zkušenosti a ponaučení pro budoucí zlepšení procesu. (Úkol 2)<\/li><\/ol><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"1.4.1","nazev":"Testovací činnosti a úkoly","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-jedna-testovaci-cinnosti-a-ukoly"},"id":"OF-D4","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 4 (© ISTQB®, překlad CaSQB)"},{"n":5,"lo":"FL-1.4.3","k":"K2","vyber":1,"q":"<p>Máte k dispozici následující testware:<\/p><ol type=\"i\"><li>Souhrnný report z testování.<\/li><li>Data uložená v databázi, používaná pro testovací vstupy a očekávané výsledky.<\/li><li>Seznam prvků potřebných k vytvoření testovacího prostředí.<\/li><li>Zdokumentované sekvence (posloupnosti) testovacích případů seřazené v pořadí k provedení.<\/li><li>Testovací případy.<\/li><\/ol><p>Která z následujících možností NEJLÉPE vyjadřuje fakt, že výše uvedený testware je výsledkem implementace testování?<\/p>","m":["ii, iv","iii, v","i, ii, v","i, iii, iv"],"ok":[0],"vys":{"a":"Je správně. Položky ii a iv v seznamu jsou výstupem implementace testování.","b":"Není správně.","c":"Není správně.","d":"Není správně."},"obecne":"<p>S ohledem na každou z uvedených testovacích činností a jejich výstupním testware platí, že:<\/p><ol type=\"i\"><li>Výstupem dokončení testování je souhrnný report z testování.<\/li><li>Výstupem implementace testování jsou testovací data, tedy data uchovávaná v databázi a používaná jako testovací vstupy a očekávané výsledky.<\/li><li>Výstupem návrhu testů je seznam prvků potřebných k vytvoření testovacího prostředí, což jsou vlastně požadavky na testovací prostředí.<\/li><li>Testovací procedury jsou zdokumentované sekvence testovacích případů v pořadí jejich provedení. Jedná se o výstup implementace testování.<\/li><li>Testovací případy jsou výstupem návrhu testů.<\/li><\/ol><p>Implementace testování vytváří následující výstupy: testovací procedury (iv), automatizované testovací skripty, testovací sady, testovací data (ii), harmonogram provádění testů a prvky testovacího prostředí (např. stuby, ovladače, simulátory a virtualizace služeb).<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"1.4.3","nazev":"Testware","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-tri-testware"},"id":"OF-D5","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 5 (© ISTQB®, překlad CaSQB)"},{"n":6,"lo":"FL-1.4.5","k":"K2","vyber":1,"q":"<p>Která z následujících možností NEJPRAVDĚPODOBNĚJI popisuje úkol vykonávaný někým v roli manažera testování?<\/p>","m":["Vyhodnocení testovací báze a testovaného objektu.","Definice požadavků na testovací prostředí.","Posouzení testovatelnosti testovaného objektu.","Vytvoření souhrnného reportu z testování."],"ok":[3],"vys":{"a":"Není správně. Role testera je primárně zodpovědná za technické a inženýrské aspekty testování jako je testovací analýza, návrh testů, implementace testování a provedení testů. Hodnocení testovací báze (za účelem identifikace defektů) a testovaného objektu (za účelem posouzení jeho testovatelnosti) jsou úkoly prováděné v rámci testovací analýzy, takže je pravděpodobné, že se jedná o úkoly vykonávané v rámci role testera.","b":"Není správně. Role testera je primárně zodpovědná za technické a inženýrské aspekty testování jako je testovací analýza, návrh testů, implementace testování a provedení testů. Definování požadavků na testovací prostředí je úkol, který je prováděn v rámci návrhu testů, takže se pravděpodobně jedná o úkol vykonávaný v rámci role testera.","c":"Není správně. Role testera je primárně zodpovědná za technické a inženýrské aspekty testování jako je testovací analýza, návrh testů, implementace testování a provedení testů. Posouzení testovatelnosti testovaného objektu je úkol, který je prováděný v rámci testovací analýzy, takže se pravděpodobně jedná o úkol prováděný v rámci role testera.","d":"Je správně. Role manažera testování se primárně zaměřuje na činnosti související s plánováním testování, monitoringem testování, řízením testování a dokončením testování. Vytvoření souhrnného reportu z testování, který je hlavním výstupem dokončení testování, bude tedy pravděpodobně úkolem, který bude prováděn někým v roli manažera testování."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.4.5","nazev":"Role v testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-ctyri-tecka-pet-role-v-testovani"},"id":"OF-D6","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 6 (© ISTQB®, překlad CaSQB)"},{"n":7,"lo":"FL-1.5.2","k":"K1","vyber":1,"q":"<p>Které z následujících tvrzení je výhodou týmového přístupu?<\/p>","m":["Zlepšení komunikace mezi členy týmu.","Snížení individuální odpovědnosti za kvalitu.","Rychlejší nasazení dodávek (výstupů) koncovým uživatelům.","Omezení spolupráce s externími byznysovými uživateli."],"ok":[0],"vys":{"a":"Je správně. Týmový přístup podporuje intenzivní komunikaci a spolupráci mezi členy týmu.","b":"Není správně. Přestože týmový přístup klade důraz na kolektivní odpovědnost za kvalitu, je za ni zodpovědný i nadále každý člen týmu.","c":"Není správně. Princip týmového přístupu spočívá ve schopnosti týmu spolupracovat s cílem dosáhnout vyšší kvality výsledků, což ale nemusí nutně vést k rychlejšímu nasazení koncovým uživatelům.","d":"Není správně. Při použití týmového přístupu spolupracují testeři při tvorbě akceptačních testů se zástupci byznysu. Nic nenasvědčuje tomu, že by tento přístup omezil spolupráci s externími byznysovými uživateli."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"1.5.2","nazev":"Týmový přístup","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-dva-tymovy-pristup"},"id":"OF-D7","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 7 (© ISTQB®, překlad CaSQB)"},{"n":8,"lo":"FL-1.5.3","k":"K2","vyber":1,"q":"<p>Uvažujme následující výhody a nevýhody nezávislosti testování:<\/p><ol type=\"i\"><li>Testeři pracují jinde (na jiném místě) než vývojáři.<\/li><li>Testeři zpochybňují předpoklady, které programátoři dělají při psaní kódu.<\/li><li>Mezi testery a vývojáři vzniká konfrontační (nepřátelský) vztah.<\/li><li>Vývojáři jsou přesvědčeni o tom, že za kvalitu odpovídají především testeři.<\/li><li>Testeři mají jiné předsudky než vývojáři.<\/li><\/ol><p>Které z nich jsou s NEJVĚTŠÍ pravděpodobností považovány za přínosy?<\/p>","m":["i, iv","ii, v","i, iii, iv","ii, iii, v"],"ok":[1],"vys":{"a":"Není správně.","b":"Je správně. Výhodami jsou možnosti ii a v.","c":"Není správně.","d":"Není správně."},"obecne":"<p>Uvažujme všechny níže uvedené výhody a nevýhody nezávislosti testování:<\/p><ol type=\"i\"><li>V ideálním případě je žádoucí úzká spolupráce mezi testery a vývojáři, která se izolací nezvyšuje. Tato možnost je tedy nevýhodou.<\/li><li>Testeři a vývojáři mají odlišné zázemí, technický náhled a předsudky, což testerům umožňuje užitečně zpochybnit předpoklady učiněné zainteresovanými stranami během specifikace a implementace systému. Tato možnost je tedy výhodou.<\/li><li>Hlavní nevýhodou nezávislosti testování je, že nezávislí testeři mohou být izolováni od vývojového týmu, což může vést k nedostatečné spolupráci, problémům v komunikaci nebo nepřátelskému vztahu s vývojovým týmem. Testeři mohou být také považování za úzké místo ve vývojovém procesu nebo mohou být obviňování za zpoždění při vydávání produktu. Tato možnost je tedy nevýhodou.<\/li><li>Jednou z nevýhod nezávislosti v testování je, že se testeři mohou izolovat od vývojového týmu, což vede k tomu, že vývojáři cítí menší odpovědnost za kvalitu. Tato možnost je tedy nevýhodou.<\/li><li>Hlavní výhodou nezávislosti testování je to, že testeři odhalí různé typy selhání a defektů mnohem pravděpodobněji než vývojáři, kteří mají jiné odborné zázemí, technický pohled a možné předsudky včetně kognitivního zkreslení.<\/li><\/ol><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"1.5.3","nazev":"Nezávislost testování","href":"kapitola-1/vyklad.html#cast-jedna-tecka-pet-tecka-tri-nezavislost-testovani"},"id":"OF-D8","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 8 (© ISTQB®, překlad CaSQB)"},{"n":9,"lo":"FL-2.1.2","k":"K1","vyber":1,"q":"<p>Které z následujících tvrzení je příkladem osvědčeného postupu v testování, který platí pro všechny druhy životního cyklu vývoje softwaru?<\/p>","m":["Každá úroveň testování má specifické a odlišné cíle testování.","Implementace a provedení testů pro danou úroveň testování by měly začít během odpovídající vývojové fáze.","Testeři by měli začít navrhovat testy, jakmile jsou k dispozici pracovní verze příslušných pracovních produktů.","Každá činnost dynamického testování má odpovídající činnost statického testování."],"ok":[0],"vys":{"a":"Je správně. Každá úroveň testování má specifické a odlišné cíle testování, protože v každé úrovni testování se testuje jiná forma testovaného objektu (např. jednotlivá komponenta, celý systém) a překrývání cílů testování by vedlo ke zbytečné duplicitě.","b":"Není správně. Testovací analýza a návrh testů pro danou úroveň by měly začít během odpovídající vývojové fáze SDLC, aby se podpořilo včasné testování (např. testovací analýza a návrh akceptačních testů by měly začít během analýzy požadavků). Implementace testování bude zpravidla zahájena později, zatímco provádění testů bude zahájeno v průběhu dané úrovně testování.","c":"Není správně. Návrh testů pro danou úroveň by měl začít během odpovídající vývojové fáze, aby se podpořilo včasné testování. Je však důležité, aby návrh testů (např. vytváření testovacích případů ) vycházel z řádně analyzované testovací báze, a nikoli z pouhé rané pracovní verze (draftu), jinak může být promarněno značné množství pracnosti vytvářením testovacích případů pro návrh, který se později změní.","d":"Není správně. Řízení kvality se vztahuje na všechny vývojové činnosti, což znamená, že ke každé vývojové činnosti existuje odpovídající testovací činnost. Stejná symetrie však neplatí pro dynamické testování a statické testování. Existují některé činnosti statického testování (např. statická analýza), pro které neexistuje žádná zjevná odpovídající činnost dynamického testování."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.2","nazev":"Životní cyklus vývoje softwaru a osvědčené testovací postupy","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-dva-zivotni-cyklus-vyvoje-softwaru-a-osvedcene-testovaci-postupy"},"id":"OF-D9","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 9 (© ISTQB®, překlad CaSQB)"},{"n":10,"lo":"FL-2.1.3","k":"K1","vyber":1,"q":"<p>Která z následujících možností je příkladem přístupu k vývoji iniciovaného testy (test-first)?<\/p>","m":["Vývoj řízený chováním.","Vývoj řízený úrovní testování.","Vývoj řízený funkcionalitou.","Vývoj řízený výkonností."],"ok":[0],"vys":{"a":"Je správně. Vývoj řízený chováním (BDD) je dobře známým příkladem vývoje iniciovaného testy.","b":"Není správně. Vývoj řízený úrovní testování (Test Level Driven Development) není správným příkladem vývoje iniciovaného testy.","c":"Není správně. Vývoj řízený funkcemi (Function-Driven Development) není správným příkladem vývoje iniciovaného testy.","d":"Není správně. Vývoj řízený výkonem (Performance-Driven Development) není správným příkladem vývoje iniciovaného testy."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.3","nazev":"Vývoj softwaru řízený testováním","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-tri-vyvoj-softwaru-rizeny-testovanim"},"id":"OF-D10","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 10 (© ISTQB®, překlad CaSQB)"},{"n":11,"lo":"FL-2.1.4","k":"K2","vyber":1,"q":"<p>Která z následujících výzev se při implementaci DevOps vyskytne s NEJVĚTŠÍ pravděpodobností?<\/p>","m":["Zajistit, aby nebyly přehlédnuty nefunkcionální charakteristiky kvality.","Správa neustále se měnících testovacích prostředí.","Potřeba více manuálních testerů s vhodnými (odpovídajícími) zkušenostmi.","Nastavení automatizace testů jako součásti pipeline pro dodávání (delivery pipeline)."],"ok":[3],"vys":{"a":"Není správně. DevOps obecně zvyšuje viditelnost nefunkcionálních charakteristik kvality jako je výkonnost a bezporuchovost (spolehlivost).","b":"Není správně. Automatizované procesy jako je průběžná integrace/průběžné nasazování (CI/CD) používané v DevOps, umožňují nastavit stabilní testovací prostředí.","c":"Není správně. Automatizované procesy jako CI/CD používané v DevOps obecně snižují potřebu manuálního testování.","d":"Je správně. Implementace DevOps může představovat několik rizik a výzev, včetně potřeby definovat a nastavit pipelinu zodpovědnou za dodávání (delivery pipeline), zavést a udržovat nástroje pro CI/CD a zavést a udržovat automatizaci testování."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.4","nazev":"DevOps a testování","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-ctyri-devops-a-testovani"},"id":"OF-D11","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 11 (© ISTQB®, překlad CaSQB)"},{"n":12,"lo":"FL-2.1.6","k":"K2","vyber":1,"q":"<p>Která z následujících možností NEJLÉPE popisuje retrospektivu?<\/p>","m":["Retrospektivy umožňují členům týmu identifikovat jiné členy týmu, kteří plně nepřispěli k dosažení kvality, jak je v týmovém přístupu vyžadováno.","Retrospektiva dává testerům příležitost identifikovat činnosti, které byly úspěšné a zachovat je až budou v budoucnu zaváděna potenciální zlepšení.","Retrospektivy jsou místem, kde mohou členové agilního týmu vyjádřit své obavy týkající se vedení a zákazníků bez rizika obviňování.","Retrospektivy poskytují členům agilního týmu fórum, kde diskutují plány a technická rozhodnutí pro následující iteraci."],"ok":[1],"vys":{"a":"Není správně. Mezi přínosy retrospektiv patří stmelování týmu a vzájemné učení (například jako výsledek možnosti hlásit problémy a navrhovat zlepšení) a zlepšování spolupráce mezi vývojem a testováním (například díky pravidelným revizím a optimalizaci vzájemné spolupráce). Poukazování na jednotlivce, o kterých se člen týmu může domnívat, že plně nepřispěli k dosažení kvality (jak vyžaduje týmový přístup) k tomuto stmelování týmu a spolupráci nepřispěje.","b":"Je správně. Během retrospektivy skupina diskutuje o tom, které aspekty projektu byly úspěšné a měly by být zachovány, stejně jako o oblastech, které by mohly být zlepšeny, a jak toho dosáhnout.","c":"Není správně. Přínosy retrospektivy jsou založeny na zvýšení efektivity a účinnosti prostřednictvím zlepšování procesů. Není to příležitost k „vypouštění páry“ a kritizování vedení a zákazníků. Výsledky testů jsou zaznamenány (obvykle v souhrnném reportu z testování), takže vše, co na schůzce zaznělo, si mohou přečíst i ostatní zainteresované strany.","d":"Není správně. Retrospektivy jsou schůzky, které se obvykle konají na konci iterace, a na kterých se členové týmu soustředí na projednání problémů souvisejících s kvalitou, které se vyskytly v aktuální iteraci. Nejsou využívány k vytváření plánů nebo technických rozhodnutí pro další iteraci (to by mělo být prováděno na plánovací schůzce na začátku další iterace)."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.1.6","nazev":"Retrospektivy a zlepšování procesů","href":"kapitola-2/vyklad.html#cast-dva-tecka-jedna-tecka-sest-retrospektivy-a-zlepsovani-procesu"},"id":"OF-D12","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 12 (© ISTQB®, překlad CaSQB)"},{"n":13,"lo":"FL-2.2.2","k":"K2","vyber":1,"q":"<p>Který z následujících testů bude s NEJVĚTŠÍ pravděpodobností proveden jako součást funkcionálního testování?<\/p>","m":["Test, který kontroluje, zda funkcionalita řazení seřadí prvky seznamu nebo pole vzestupně.","Test, který kontroluje, zda funkcionalita řazení dokončí řazení do jedné sekundy od spuštění.","Test, který kontroluje, jak snadno lze změnit funkcionalitu řazení z vzestupného na sestupné.","Test, který kontroluje, zda funkcionalita řazení funguje správně i při přechodu z 32bitové na 64bitovou architekturu."],"ok":[0],"vys":{"a":"Je správně. Kontrola, zda funkcionalita řazení seřadí prvky seznamu nebo pole vzestupně, je vyhodnocením funkcionální správnosti, což je součástí funkcionálního testování.","b":"Není správně. Posouzení, zda funkcionalita řazení splňuje svůj nefunkcionální požadavek na dokončení operace do jedné sekundy, je součástí testování její výkonnostní efektivity, které je součástí nefunkcionálního testování.","c":"Není správně. Hodnocení snadnosti, s jakou lze řazení upravit z vzestupného na sestupné, je testování její modifikovatelnosti. Jedná se o formu nefunkcionálního testování udržovatelnosti, které je součástí nefunkcionálního testování.","d":"Není správně. Posouzení, zda funkcionalita řazení funguje správně i po přechodu z 32bitové na 64bitovou architekturu, je testováním její adaptability, což je forma testování přenositelnosti, která je součástí nefunkcionálního testování."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.2.2","nazev":"Typy testů","href":"kapitola-2/vyklad.html#cast-dva-tecka-dva-tecka-dva-typy-testu"},"id":"OF-D13","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 13 (© ISTQB®, překlad CaSQB)"},{"n":14,"lo":"FL-2.3.1","k":"K2","vyber":1,"q":"<p>Která z následujících možností je NEJPRAVDĚPODOBNĚJŠÍM podnětem, který vede k testování údržby systému elektronické směnárny?<\/p>","m":["Vývojáři nahlásili, že úprava systému byla obtížná, a testeři se rozhodli ověřit, zda je to pravda.","Možnost vrácení peněz byla ze systému odstraněna, protože ne vždy vracela zákazníkům správnou částku.","Agilní tým začal vyvíjet uživatelský scénář, který do systému přidává novou funkcionalitu věrnostního programu.","V systému byla použita možnost volby jazyka, která umožnila provádění transakcí v angličtině i v místním jazyce."],"ok":[1],"vys":{"a":"Není správně. Za předpokladu, že by testeři mohli zkontrolovat snadnost úpravy systému, pak by to bylo provedeno spíše v rámci testování udržovatelnosti než testování údržby. Tím pádem se nejedná o podnět ke spuštění testování údržby.","b":"Je správně. Příkladem podnětu pro spuštění testování údržby je změna systému (například oprava nebo vylepšení). Odstranění možnosti vrácení peněz bylo úpravou, která by vedla k testování údržby.","c":"Není správně. Pokud agilní tým začal vyvíjet uživatelský scénář, který do systému směnárny přidává novou funkcionalitu věrnostního programu, pak to povede k testování nové funkcionality a poté provedení regresního testování. V této situaci se nevyžaduje žádné testování údržby.","d":"Není správně. Rekonfigurace systému tak, aby podporoval transakce v místním jazyce i angličtině, není úpravou systému, změnou provozního prostředí ani vyřazením systému, což jsou tři podněty pro zahájení testování údržby."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"2.3","nazev":"Testování údržby","href":"kapitola-2/vyklad.html#cast-dva-tecka-tri-testovani-udrzby"},"id":"OF-D14","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 14 (© ISTQB®, překlad CaSQB)"},{"n":15,"lo":"FL-3.1.1","k":"K1","vyber":1,"q":"<p>Který z následujících pracovních produktů NELZE prověřit statickým testováním?<\/p>","m":["Smlouva.","Plán testování.","Šifrovaný kód.","Testovací listina."],"ok":[2],"vys":{"a":"Není správně. Obecně platí, že většinu pracovních produktů lze prozkoumat některou z forem statického testování. Pokud je pracovní produkt (v tomto případě smlouva) interpretovatelný pro člověka, lze na něj aplikovat revizi, což je druh statického testování.","b":"Není správně. Obecně platí, že většinu pracovních produktů lze prozkoumat některou z forem statického testování. Pokud je pracovní produkt (v tomto případě plán testování) interpretovatelný pro člověka, lze na něj aplikovat revizi, což je druh statického testování.","c":"Je správně. Obecně platí, že většinu pracovních produktů lze prozkoumat některou z forem statického testování. To ale neplatí pro pracovní produkty, které jsou příliš složité pro člověka z hlediska srozumitelnosti, a na které nelze aplikovat analýzu pomocí nástrojů. Šifrovaný kód je pro člověka příliš složitý a pokud je správně zašifrován, nebude možné jej ani analyzovat většinou nástrojů.","d":"Není správně. Obecně platí, že většinu pracovních produktů lze prozkoumat některou z forem statického testování. Pokud je pracovní produkt (v tomto případě testovací listina) interpretovatelný pro člověka, lze na něj aplikovat revizi, což je druh statického testování."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"3.1.1","nazev":"Pracovní produkty, které mohou být prověřeny statickým testováním","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-jedna-pracovni-produkty-ktere-mohou-byt-provereny-statickym-testovanim"},"id":"OF-D15","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 15 (© ISTQB®, překlad CaSQB)"},{"n":16,"lo":"FL-3.1.2","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení o hodnotě (významu) statického testování je SPRÁVNÉ?<\/p>","m":["Typy defektů nalezené statickým testováním se liší od typů defektů, které lze zjistit dynamickým testováním.","Dynamické testování může odhalit typy defektů, které lze nalézt statickým testováním, a navíc některé další typy defektů.","Dynamické testování může odhalit některé defekty, které lze nalézt statickým testováním, ale ne všechny.","Statické testování může odhalit typy defektů, které lze nalézt dynamickým testováním, a navíc některé další typy defektů."],"ok":[2],"vys":{"a":"Není správně.","b":"Není správně.","c":"Je správně","d":"Není správně."},"obecne":"<p>Některé typy defektů lze odhalit pouze statickým testováním, například nedosažitelný kód, chybně implementované návrhové vzory a defekty v nespustitelných pracovních produktech. Některé typy defektů mohou být nalezeny jak statickým, tak dynamickým testováním. Příkladem je defekt v kódu, který může být nalezen jak revidujícím při revizi kódu (tedy statickým testováním), tak zpozorován ve formě následného selhání při dynamickém testování. Konečně některé typy defektů lze odhalit pouze dynamickým testováním, např. problémy s výkonností nebo pamětí, které lze pozorovat pouze při spouštění kódu nebo systému.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"3.1.2","nazev":"Přínosy statického testování","href":"kapitola-3/vyklad.html#cast-tri-tecka-jedna-tecka-dva-prinosy-statickeho-testovani"},"id":"OF-D16","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 16 (© ISTQB®, překlad CaSQB)"},{"n":17,"lo":"FL-3.2.2","k":"K2","vyber":1,"q":"<p>Předpokládejme následující popis činností revize:<\/p><ol><li>Zjištěné anomálie jsou analyzovány, prodiskutovány a je rozhodnuto o jejich stavu, vlastnictví a požadovaných opatřeních.<\/li><li>Defekty jsou zaznamenány a veškeré potřebné opravy jsou provedeny před akceptací pracovního produktu.<\/li><li>Revidující používají různé techniky pro vytváření doporučení a otázek ohledně pracovního produktu, a k identifikaci anomálií.<\/li><li>Je stanoven účel a harmonogram revize s cílem zajistit cílenou a efektivní revizi.<\/li><li>Účastníkům je poskytnut přístup k revidovanému pracovnímu produktu.<\/li><\/ol><p>Která z následujících možností je SPRÁVNÉ pořadí činností v procesu revize odpovídající daným popisům?<\/p>","m":["4 – 3 – 5 – 2 – 1","4 – 5 – 3 – 1 – 2","5 – 4 – 1 – 3 – 2","5 – 4 – 3 – 2 – 1"],"ok":[1],"vys":{"a":"Není správně.","b":"Je správně. Správné pořadí činností je následující: 4 – 5 – 3 – 1 – 2","c":"Není správně.","d":"Není správně."},"obecne":"<p>Uvedené popisy spadají do následujících činností procesu revize:<\/p><ol><li>Fáze \"komunikace a analýza\".<\/li><li>Fáze \"opravy a reportování\".<\/li><li>Fáze \"individuální revize\".<\/li><li>Fáze \"plánování“.<\/li><li>Fáze \"zahájení revize\".<\/li><\/ol><p>Obecný proces revize podle normy ISO/IEC 20246, který je uveden v učebních osnovách, popisuje činnosti v tomto logickém pořadí:<\/p><ul><li>Plánování (4).<\/li><li>Zahájení revize (5).<\/li><li>Individuální revize (3).<\/li><li>Komunikace a analýza (1).<\/li><li>Opravy a reportování (2).<\/li><\/ul><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"3.2.2","nazev":"Činnosti procesu revize","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-dva-cinnosti-procesu-revize"},"id":"OF-D17","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 17 (© ISTQB®, překlad CaSQB)"},{"n":18,"lo":"FL-3.2.3","k":"K1","vyber":1,"q":"<p>Který účastník procesu revize je zodpovědný za zajištění efektivního průběhu revizních schůzek a za to, aby mohl každý jejich účastník vyjádřit svobodně svůj názor?<\/p>","m":["Manažer.","Moderátor.","Předseda.","Vedoucí revize."],"ok":[1],"vys":{"a":"Není správně. Manažer rozhoduje o tom, co má být revidováno a jaké zdroje budou využity (včetně lidí a času).","b":"Je správně. Moderátor (někdy také facilitátor) je zodpovědný za zajištění efektivního průběhu revizních schůzek včetně dodržení časového rámce, využití mediace a zajištění komfortního prostředí, ve kterém může každý svobodně vyjádřit svůj názor.","c":"Není správně. Předseda není funkce, která by měla být při revizích využita.","d":"Není správně. Vedoucí revize je odpovědný za dohled nad procesem revize jako je výběr členů revizního týmu, plánování revizních schůzek a zajištění úspěšného dokončení revize."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"3.2.3","nazev":"Role a odpovědnosti při revizích","href":"kapitola-3/vyklad.html#cast-tri-tecka-dva-tecka-tri-role-a-odpovednosti-pri-revizich"},"id":"OF-D18","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 18 (© ISTQB®, překlad CaSQB)"},{"n":19,"lo":"FL-4.1.1","k":"K2","vyber":1,"q":"<p>Provádíte systémové testování webové aplikace e-shopu a máte k dispozici následující požadavek:<\/p><blockquote><em>REQ 05-017. Pokud celková cena nákupu přesáhne 100 €, získá zákazník 5% slevu na další nákupy. V opačném případě zákazník slevu neobdrží.<\/em><\/blockquote><p>Které techniky testování budou NEJVÍCE užitečné při navrhování testovacích případů na základě tohoto požadavku?<\/p>","m":["Techniky testování bílé skříňky.","Techniky testování černé skříňky.","Techniky testování založené na zkušenostech.","Techniky testování založené na rizicích."],"ok":[1],"vys":{"a":"Není správně. Dokument neodkazuje na vnitřní strukturu testovaného objektu, ale specifikuje požadované chování testovaného objektu. Testovací techniky bílé skříňky proto nebudou při navrhování testovacích případů užitečné.","b":"Je správně. Text je požadavek, který specifikuje požadované chování testovaného objektu. Proto jsou v tomto případě nejvhodnějšími testovacími technikami techniky černé skříňky (např. analýza hraničních hodnot nebo testování dle rozhodovací tabulky).","c":"Není správně. Ačkoli lze k návrhu testovacích případů na základě uvedeného textu použít techniky testování založené na zkušenostech, vhodnější bude použití techniky testování černé skříňky. Dokument popisuje přesné byznysové pravidlo a navíc formulace jako \"přesahuje 100 €\" naznačuje existenci důležitých hranic tříd ekvivalence, které by měly být testovány pomocí testovacích technik černé skříňky, např. pomocí analýzy hraničních hodnot.","d":"Není správně. Testování založené na rizicích není uznávaným typem testovací techniky."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.1","nazev":"Přehled technik testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-jedna-prehled-technik-testovani"},"id":"OF-D19","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 19 (© ISTQB®, překlad CaSQB)"},{"n":20,"lo":"FL-4.2.1","k":"K3","vyber":2,"q":"<p>Systém pro prodej vstupenek do kina vypočítá typ slevy na základě roku narození klienta (KR) a aktuálního roku (AR) takto:<\/p><p>NECHŤ D je rozdíl mezi AR a BY, tj. D = AR - KR<\/p><ul><li>KDYŽ D &lt; 0 PAK vypíše chybové hlášení \"rok narození nemůže být větší než aktuální rok\".<\/li><li>KDYŽ 0 ≤ D &lt; 18 PAK je uplatněna studentská sleva.<\/li><li>KDYŽ 18 ≤ D &lt; 65 PAK není uplatněna žádná sleva.<\/li><li>KDYŽ D ≥ 65 PAK je uplatněna sleva pro důchodce.<\/li><\/ul><p>Vaše sada testů již obsahuje dva testovací případy:<\/p><ul><li>KR = 1990, AR = 2020, očekávaný výsledek: žádná sleva.<\/li><li>KR = 2030, AR = 2029, očekávaný výsledek: vypsání chybové zprávy.<\/li><\/ul><p>Která z následujících sad testovacích dat by měla být přidána k dosažení plného pokrytí platných tříd ekvivalence pro typ slevy?<\/p>","m":["KR = 2001, AR = 2065","KR = 1900, AR = 1965","KR = 1965, AR = 1900","KR = 2011, AR = 2029","KR = 2000, AR = 2000"],"ok":[1,4],"vys":{"a":"Není správně. CY - BY = 64. Tyto vstupy odpovídají již pokryté třídě \"žádná sleva\".","b":"Je správně. CY - BY = 65. Tyto vstupy odpovídají třídě, která ještě není pokrytá (\"sleva pro důchodce\").","c":"Není správně. CY - BY = -65. Tyto vstupy odpovídají již pokryté třídě \"chybové hlášení\".","d":"Není správně. CY - BY = 18. Tyto vstupy odpovídají již pokryté třídě \"žádná sleva\".","e":"Je správně. CY - BY = 0. Tyto vstupy odpovídají třídě, která ještě není pokrytá (\"studentská sleva\")."},"obecne":"<p>Existují dvě třídy ekvivalence, které ještě nejsou zahrnuty, a které odpovídají \"slevě pro studenty\" a \"slevě pro důchodce\".<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.2.1","nazev":"Rozdělení tříd ekvivalence","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-jedna-rozdeleni-trid-ekvivalence"},"id":"OF-D20","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 20 (© ISTQB®, překlad CaSQB)"},{"n":21,"lo":"FL-4.2.2","k":"K3","vyber":1,"q":"<p>Testujete systém řízení teploty pro zahradnické chladírenské zařízení. Systém přijímá jako vstup teplotu (v celých stupních Celsia). Pokud je teplota v rozsahu od 0 do 2 stupňů včetně, systém zobrazí zprávu „teplota OK“. Pro nižší teploty systém zobrazí zprávu „příliš nízká teplota“ a pro vyšší teploty zobrazí zprávu „příliš vysoká teplota“.<\/p><p>Která z následujících sad testovacích vstupů poskytuje nejvyšší úroveň pokrytí hraničních hodnot při použití 2-hodnotové BVA?<\/p>","m":["–1, 3","0, 2","–1, 0, 2, 3","–2, 0, 2, 4"],"ok":[2],"vys":{"a":"Není správně.","b":"Není správně.","c":"Je správně. Správná možnost je: -1, 0, 2, 3","d":"Není správně."},"obecne":"<p>Existují tři třídy ekvivalence: {..., - 2,-1}, {0, 1, 2 }, a {3, 4, ...}.<br>U 2-hodnotové BVA musí být pokryty všechny hraniční hodnoty pro všechny třídy ekvivalence.<br>Hraniční hodnoty jsou -1 (pro třídu \"příliš nízká teplota\"), 0, 2 (pro třídu \"teplota OK\") a 3 (pro třídu \"příliš vysoká teplota\").<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.2.2","nazev":"Analýza hraničních hodnot","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-dva-analyza-hranicnich-hodnot"},"id":"OF-D21","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 21 (© ISTQB®, překlad CaSQB)"},{"n":22,"lo":"FL-4.2.3","k":"K3","vyber":1,"q":"<p>Navrhujete testovací případy na základě následující rozhodovací tabulky:<\/p><table><thead><tr><th><\/th><th>R1<\/th><th>R2<\/th><th>R3<\/th><th>R4<\/th><th>R5<\/th><th>R6<\/th><th>R7<\/th><\/tr><\/thead><tbody><tr><th>C1: Věk<\/th><td>0-18<\/td><td>19-65<\/td><td>19-65<\/td><td>&gt;65<\/td><td>0-18<\/td><td>19-65<\/td><td>&gt;65<\/td><\/tr><tr><th>C2: Zkušenosti<\/th><td>-<\/td><td>0-4<\/td><td>&gt;4<\/td><td>-<\/td><td>-<\/td><td>-<\/td><td>-<\/td><\/tr><tr><th>C3: Registrován?<\/th><td>NE<\/td><td>NE<\/td><td>NE<\/td><td>NE<\/td><td>ANO<\/td><td>ANO<\/td><td>ANO<\/td><\/tr><tr><th>Kategorie<\/th><td>A<\/td><td>A<\/td><td>B<\/td><td>B<\/td><td>B<\/td><td>D<\/td><td>C<\/td><\/tr><\/tbody><\/table><p>Dosud jste navrhli následující testovací případy:<\/p><ul><li>Testovací případ 1 (TC1): Muž ve věku 19 let, neregistrovaný a bez zkušeností.<br>Očekávaný výsledek: kategorie A.<\/li><li>Testovací případ 2 (TC2): Žena ve věku 65 let, neregistrovaná s 5 roky praxe.<br>Očekávaný výsledek: kategorie B.<\/li><li>Testovací případ 3 (TC3): Muž ve věku 66 let, registrovaný a bez zkušeností.<br>Očekávaný výsledek: kategorie C.<\/li><li>Testovací případ 4 (TC4): Žena ve věku 65 let, registrovaná se 4 roky praxe.<br>Očekávaný výsledek: kategorie D.<\/li><\/ul><p>Který z následujících testovacích případů zvýší pokrytí rozhodovací tabulky v případě, kdy jej přidáte ke stávající sadě testovacích případů?<\/p>","m":["Muž ve věku 66 let bez zkušeností. Očekávaný výsledek: kategorie B.","Žena ve věku 55 let, neregistrovaná se 2 roky praxe. Očekávaný výsledek: kategorie A.","Žena ve věku 19 let, registrovaná s 5 roky praxe. Očekávaný výsledek: kategorie D.","Žádný další testovací případ nemůže zvýšit již dosažené pokrytí rozhodovací tabulky."],"ok":[0],"vys":{"a":"Je správně. Podmínky \"66 let\", \"neregistrovaný\" a \"bez zkušeností\" odpovídají pravidlu R4, které není pokryto stávajícími testovacími případy, takže po přidání tohoto testovacího případu se pokrytí rozhodovací tabulky zvýší.","b":"Není správně. Podmínky \"55 let\", \"neregistrovaný\" a \"2 roky praxe\" odpovídají pravidlu R2, které je již zahrnuto v TC1. Přidáním tohoto testovacího případu se tedy pokrytí nezvýší.","c":"Není správně. Podmínky \"19 let\", \"registrovaný\" a \"5 let praxe\" odpovídají pravidlu R6, které je již zahrnuto v TC4. Přidáním tohoto testovacího případu se tedy pokrytí nezvýší.","d":"Není správně. Stávající testovací případy pokrývají pouze 4 ze 7 sloupců rozhodovací tabulky. Pokrytí lze zvýšit přidáním testovacích případů, které pokrývají dosud nepokryté sloupce, tedy R1, R4 a R5."},"obecne":"<p>Testovací případy TC1, TC2, TC3 a TC4 pokrývají pravidla R2, R3, R7 a R6 v rozhodovací tabulce.<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.2.3","nazev":"Testování dle rozhodovací tabulky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-tri-testovani-dle-rozhodovaci-tabulky"},"id":"OF-D22","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 22 (© ISTQB®, překlad CaSQB)"},{"n":23,"lo":"FL-4.2.4","k":"K3","vyber":1,"q":"<p>Používáte techniku testování přechodů stavů na systém rezervace hotelových pokojů modelovaný následující stavovou tabulkou se 4 stavy a 5 různými událostmi:<\/p><table><thead><tr><th><\/th><th colspan=\"5\">Události<\/th><\/tr><tr><th>Stav<\/th><th>Dostupný<\/th><th>Nedostupný<\/th><th>ZměnitPokoj<\/th><th>Zrušit<\/th><th>Zaplatit<\/th><\/tr><\/thead><tbody><tr><th>S1: Poptávka<\/th><td>S2<\/td><td>S3<\/td><td><\/td><td><\/td><td><\/td><\/tr><tr><th>S2: Potvrzen<\/th><td><\/td><td><\/td><td>S1<\/td><td>S4<\/td><td>S4<\/td><\/tr><tr><th>S3: Ve frontě<\/th><td>S2<\/td><td><\/td><td><\/td><td>S4<\/td><td><\/td><\/tr><tr><th>S4: Konec<\/th><td><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><\/tbody><\/table><p>Který z následujících testovacích případů, reprezentovaných jako sekvence událostí, dosahuje nejvyššího pokrytí platných přechodů stavů? Předpokládáme, že všechny testovací případy začínají ve stavu Poptávka.<\/p>","m":["Nedostupný, Dostupný, ZměnitPokoj, Nedostupný, Zrušit","Dostupný, ZměnitPokoj, Nedostupný, Dostupný, Zaplatit","Dostupný, ZměnitPokoj, Dostupný, ZměnitPokoj, Nedostupný","Nedostupný, Zrušit, ZměnitPokoj, Dostupný, Zaplatit"],"ok":[1],"vys":{"a":"Není správně. Tato sekvence pěti událostí zahrnuje 4 různé platné přechody (obě události \"Nedostupný\" odpovídají stejnému přechodu mezi S1 a S3). Tento testovací případ zahrnuje 4 ze 7 platných přechodů.","b":"Je správně. Tato sekvence pěti událostí pokrývá 5 různých přechodů (první událost \"Dostupný\" odpovídá přechodu mezi S1 a S2 a druhá událost \"Dostupný\" odpovídá přechodu mezi S3 a S2, takže jsou pokryty dva různé přechody). Tento testovací případ pokrývá 5 ze 7 platných přechodů a dosahuje nejvyššího pokrytí platných přechodů.","c":"Není správně. Tato sekvence pěti událostí zahrnuje 3 různé přechody (obě události \"Dostupný\" odpovídají stejnému přechodu z S1 do S2; obě události \"ZměnitPokoj\" odpovídají stejnému přechodu z S2 do S1). Tento testovací případ zahrnuje 3 ze 7 platných přechodů.","d":"Není správně. Tato posloupnost pěti událostí nepředstavuje proveditelný testovací případ, protože po \"Zrušit\" systém skončí ve stavu Konec a nelze provést žádné další platné přechody."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.2.4","nazev":"Testování přechodů stavů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-dva-tecka-ctyri-testovani-prechodu-stavu"},"id":"OF-D23","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 23 (© ISTQB®, překlad CaSQB)"},{"n":24,"lo":"FL-4.3.1","k":"K2","vyber":1,"q":"<p>Vaše testovací sada S pro program P dosahuje 100% pokrytí příkazů. Skládá se ze tří testovacích případů, z nichž každý dosahuje 50% pokrytí příkazů.<\/p><p>Které z následujících tvrzení je SPRÁVNÉ?<\/p>","m":["Provedení S způsobí všechna možná selhání v P.","S dosahuje 100% pokrytí větví pro P.","Každý spustitelný příkaz v P, který obsahuje defekt, byl spuštěn alespoň jednou během provádění S.","Po vyjmutí jednoho testovacího případu z S budou zbývající dva testovací případy stále dosahovat 100% pokrytí příkazů."],"ok":[2],"vys":{"a":"Není správně. Příkaz s defektem nemusí při svém provedení způsobit selhání. Například příkaz x := y / z způsobí selhání <em>pouze<\/em> když z=0.","b":"Není správně. 100 % pokrytí příkazů nezaručuje 100 % pokrytí větví. Například testovací případ, kdy x=0 pro kód:<pre>1. IF (x=0) THEN\n2.     A;\n3 ENDIF<\/pre>dosáhne 100 % pokrytí příkazů, ale nepokryje větev z bodu 1 do bodu 3.","c":"Je správně. 100 % pokrytí příkazů znamená, že každý spustitelný příkaz byl proveden alespoň jednou.","d":"Není správně. Odstraněný testovací případ mohl poskytovat pokrytí některých příkazů, které nejsou pokryty žádným z ostatních dvou testovacích případů, a v takovém případě zbývající dva testovací případy společně nedosáhnou 100% pokrytí příkazů."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.3.1","nazev":"Testování a pokrytí příkazů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-jedna-testovani-a-pokryti-prikazu"},"id":"OF-D24","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 24 (© ISTQB®, překlad CaSQB)"},{"n":25,"lo":"FL-4.3.3","k":"K2","vyber":1,"q":"<p>Proč testování bílé skříňky umožňuje odhalování chyb i v případě, že je specifikace softwaru vágní, zastaralá nebo neúplná?<\/p>","m":["Testovací případy jsou navrženy na základě struktury testovaného objektu, nikoliv na základě specifikace.","Pro každou techniku testování bílé skříňky lze dobře definovat a snadno změřit pokrytí.","Techniky testování bílé skříňky slouží velmi dobře k odhalení opomenutí v požadavcích.","Techniky testování bílé skříňky lze použít jak při statickém testování, tak při dynamickém testování."],"ok":[0],"vys":{"a":"Je správně. Základní význam technik bílé skříňky spočívá v tom, že se při testování bere v úvahu celá implementace softwaru, což usnadňuje detekci defektů v případech, kdy je jeho specifikace vágní, zastaralá nebo neúplná. To znamená, že testování bílé skříňky může odhalit defekty, jako je například dodatečná funkce přidaná do kódu (náhodně nebo záměrně), která tam být nemá, což testování černé skříňky odhalit nedokáže.","b":"Není správně. Skutečnost, že pokrytí lze přesně definovat, není tím správným důvodem. Dosažená úroveň pokrytí má mnohem větší dopad než možnost toto pokrytí měřit.","c":"Není správně. Pokud software (z důvodu opomenutí) neimplementuje jeden nebo více požadavků, je nepravděpodobné, že by testování bílé skříňky odhalilo defekty související s tímto opomenutím.","d":"Není správně. Tvrzení je sice pravdivé, ale nejedná se o správnou odpověď. Neexistuje žádná souvislost mezi možností využití při statickém i dynamickém testování a tvrzením, že testování bílé skříňky usnadňuje odhalování defektů v případě nekvalitních specifikací."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.3.3","nazev":"Význam testování bílé skříňky","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-tri-tecka-tri-vyznam-testovani-bile-skrinky"},"id":"OF-D25","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 25 (© ISTQB®, překlad CaSQB)"},{"n":26,"lo":"FL-4.4.1","k":"K2","vyber":1,"q":"<p>Kterou z následujících možností tester NEPŘEDPOKLÁDÁ při použití techniky odhadování chyb?<\/p>","m":["Vývojář špatně pochopil vzorec v uživatelském scénáři pro výpočet úroku.","Vývojář ve zdrojovém kódu napsal \"FA = A*(1+IR^N)\" místo \"FA = A*(1+IR)^N\".","Vývojář nestihl seminář o nové legislativě týkající se složeného úročení.","Přesnost úroku vypočítaného systémem není dostatečná."],"ok":[2],"vys":{"a":"Není správně. Toto je příklad předvídání chyby vývojáře.","b":"Není správně. Toto je příklad předvídání defektu.","c":"Je správně. Toto je příklad potenciální kořenové příčiny defektu, která není ani chybou, defektem nebo selháním, a proto je pro testera obtížné ji předvídat.","d":"Není správně. Jedná se o příklad předvídání selhání, pravděpodobně založené na zkušenosti s předchozími systémy v této aplikační doméně."},"obecne":"<p>Odhadování chyb spočívá v předvídání chyb, defektů a selhání založených na znalostech testera.<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"4.4.1","nazev":"Odhadování chyb","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-jedna-odhadovani-chyb"},"id":"OF-D26","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 26 (© ISTQB®, překlad CaSQB)"},{"n":27,"lo":"FL-4.4.2","k":"K2","vyber":1,"q":"<p>Které z následujících tvrzení o průzkumném testování je pravdivé?<\/p>","m":["Testovací případy jsou navrženy před zahájením průzkumného testování.","Tester může provést test, ale nemůže jej navrhnout.","Na základě výsledků průzkumného testování lze dobře předvídat počet zbývajících defektů.","Během průzkumného testování může tester použít techniky testování černé skříňky."],"ok":[3],"vys":{"a":"Není správně. V rámci průzkumného testování se testovací případy obvykle vytvářejí v průběhu testovacích relací spolu s testovací analýzou, implementací testování a prováděním testů.","b":"Není správně. Při průzkumném testování jsou testy současně navrhovány, prováděny a vyhodnocovány, zatímco tester získává znalosti (učí se) o testovaném objektu.","c":"Není správně. Výsledky testů při průzkumném testování jsou do značné míry závislé na zkušenostech testera, takže je lze použít k předvídání rizika a na jejich základě vyhodnotit, zda bude v porovnání s předchozím během průzkumného testování méně nebo více defektů, nejsou dobrým příkladem spolehlivých modelů predikce defektů, které by dokázaly předpovědět počet zbývajících defektů.","d":"Je správně. Během průzkumného testování mohou testeři použít všechny techniky testování, které považují za užitečné."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.4.2","nazev":"Průzkumné testování","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-ctyri-tecka-dva-pruzkumne-testovani"},"id":"OF-D27","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 27 (© ISTQB®, překlad CaSQB)"},{"n":28,"lo":"FL-4.5.1","k":"K2","vyber":1,"q":"<p>Která metoda společného psaní uživatelských scénářů umožňuje týmu dosáhnout společného pochopení toho, co je třeba dodat?<\/p>","m":["Plánovací poker, takže tým dosáhne shody ohledně pracnosti potřebné k implementaci uživatelského scénáře.","Revize, takže tým odhalí nesrovnalosti a rozpory v uživatelském scénáři.","Plánování iterací, takže je možné stanovit priority pro implementaci uživatelských scénářů s nejvyšší byznysovou hodnotou pro zákazníka.","Konverzace, takže členové týmu pochopí, jak se bude software používat."],"ok":[3],"vys":{"a":"Není správně. Plánovací poker dokáže odhadnout pracnost již napsaného uživatelského scénáře. Nepomáhá pochopit, co by mělo být dodáno.","b":"Není správně. Revize nejsou technikou společného psaní uživatelských scénářů.","c":"Není správně. Plánování iterace je činnost související s projektem, která slouží k plánování práce, nikoli k pochopení toho, co má být dodáno.","d":"Je správně. Konverzace se používá k vysvětlení toho, jak bude software používán, a často umožňuje týmu definovat smysluplná akceptační kritéria. Tím se získá společná vize toho, co by mělo být dodáno."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.5.1","nazev":"Společné psaní uživatelských scénářů","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-jedna-spolecne-psani-uzivatelskych-scenaru"},"id":"OF-D28","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 28 (© ISTQB®, překlad CaSQB)"},{"n":29,"lo":"FL-4.5.3","k":"K3","vyber":1,"q":"<p>Právě jste začali navrhovat testovací případy pro následující uživatelský scénář.<\/p><blockquote><p>Jako zákazník,<br>chci filtrovat výsledky vyhledávání podle cenového rozpětí, protože tak snadněji najdu produkty v rámci mého rozpočtu.<br>Akceptační kritéria:<\/p><ol><li>Filtr by měl fungovat pro všechny verze aplikace od verze 3.0 výše.<\/li><li>Filtr by měl zákazníkovi umožnit nastavit cenový rozsah pomocí minimální a maximální ceny.<\/li><li>Výsledky vyhledávání by se měly dynamicky aktualizovat podle toho, jak zákazník upravuje filtr cenového rozsahu.<\/li><\/ol><\/blockquote><p>Ve všech testovacích případech je předpoklad následující: k dispozici jsou pouze dva produkty, A a B. Produkt A stojí 100 € a produkt B stojí 110 €.<\/p><p>Která z následujících možností je NEJLEPŠÍM příkladem testovacího případu pro tento uživatelský scénář?<\/p>","m":["Otevřete webovou stránku a nastavte filtr pro zobrazení cen mezi 90 € a 100 €. Očekávaný výsledek: výsledky zobrazují pouze produkt A. Nastavte maximální cenu na 110 €. Očekávaný výsledek: výsledky nyní zahrnují produkty A i B.","Otevřete webovou stránku. Očekávaný výsledek: výchozí minimální a maximální ceny jsou 100 € a 110 €. Vložte produkt C s cenou 120 € do košíku. Obnovte stránku. Očekávaný výsledek: výchozí maximální cena se změní na 120 €.","Otevřete webovou stránku a nastavte filtr pro zobrazení cen na hodnoty mezi 90 € a 115 €. Očekávaný výsledek: budou zobrazeny produkty A i B. Změňte měnu z € na $. Očekávaný výsledek: rozsah filtru se správně změní na hodnoty v $ podle aktuálního směnného kurzu.","Otevřete webovou stránku pomocí tří různých prohlížečů: Edge, Chrome a Opera. V každém prohlížeči nastavte filtr na hodnoty mezi 90 € a 110 €. Očekávaný výsledek: výsledky zahrnují produkty A i B a zobrazení výsledků je ve všech třech prohlížečích stejné."],"ok":[0],"vys":{"a":"Je správně. Tento testovací případ souvisí s akceptačními kritérii 2 a 3, protože prověřujeme, zda můžeme nastavit cenový rozsah (akceptační kritérium 2) a zda se výsledky dynamicky aktualizují po úpravě filtru cenového rozsahu (akceptační kritérium 3).","b":"Není správně. Tento testovací případ nesouvisí s žádným akceptačním kritériem. Kontroluje, zda filtr dynamicky nastavuje výchozí minimální a maximální cenový rozsah, nikoliv to, že to může udělat zákazník.","c":"Není správně. Tento testovací případ nesouvisí s žádným akceptačním kritériem. Kontroluje funkcionalitu přepočtu měn, která není v tomto uživatelském scénáři popsána.","d":"Není správně. Tento testovací případ nesouvisí s žádným akceptačním kritériem. Kontroluje kompatibilitu aplikace s různými prohlížeči, která není v tomto uživatelském scénáři řešena."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"4.5.3","nazev":"Vývoj řízený akceptačními testy","href":"kapitola-4/vyklad.html#cast-ctyri-tecka-pet-tecka-tri-vyvoj-rizeny-akceptacnimi-testy"},"id":"OF-D29","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 29 (© ISTQB®, překlad CaSQB)"},{"n":30,"lo":"FL-5.1.3","k":"K2","vyber":2,"q":"<p>Která z následujících možností je NEJLEPŠÍM příkladem VÝSTUPNÍHO kritéria v testovacím projektu?<\/p>","m":["Rozpočet je schválen.","Je vyčerpán rozpočet.","Je k dispozici testovací báze.","Testovací případy dosáhly alespoň 80% pokrytí příkazů.","Všichni testovací analytici jsou certifikováni na úrovni ISTQB Foundation."],"ok":[1,3],"vys":{"a":"Není správně. Schválení rozpočtu je příkladem vstupního kritéria. Nemělo by smysl schvalovat rozpočet na již provedenou činnost.","b":"Je správně. Vyčerpání rozpočtu lze považovat za platné výstupní kritérium.","c":"Není správně. Dostupnost zdrojů (testovací báze) je příkladem vstupního kritéria pro testování.","d":"Správně. Pokrytí je měřítkem důkladnosti, takže je typickým výstupním kritériem.","e":"Není správně. Toto je příklad vstupního kritéria, které se kontroluje před zahájením projektu."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.1.3","nazev":"Vstupní a výstupní kritéria","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-tri-vstupni-a-vystupni-kriteria"},"id":"OF-D30","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 30 (© ISTQB®, překlad CaSQB)"},{"n":31,"lo":"FL-5.1.4","k":"K3","vyber":1,"q":"<p>Tým potřebuje odhadnout čas, který potřebuje jeden tester k provedení čtyř testovacích případů pro softwarovou komponentu. Byly shromážděny následující údaje o pracnosti potřebné k provedení jednoho testovacího případu:<\/p><ul><li>Optimistický scénář: 1 hodina<\/li><li>Pesimistický scénář: 8 hodin<\/li><li>Nejpravděpodobnější scénář: 3 hodiny<\/li><\/ul><p>Jaký je konečný odhad času potřebného k provedení všech čtyř testovacích případů při použití techniky tříbodového odhadu?<\/p>","m":["14 hodin","3,5 hodiny","16 hodin","12 hodin"],"ok":[0],"vys":{"a":"Je správně. V tomto případě je odhad pro provedení jednoho testovacího případu následující:<br>E = (1 + 4*3 + 8) / 6 = 3,5<br>Celkový čas, který tester potřebuje k provedení 4 testovacích případů, je tedy:<br>3,5 * 4 = 14 hodin","b":"Není správně.","c":"Není správně.","d":"Není správně."},"obecne":"<p>Pomocí techniky tříbodového odhadu se konečný odhad (E) vypočítá jako:<\/p><p>E = (a + 4*m + b) / 6,<\/p><p>kde <u>a<\/u> je nejoptimističtější odhad, <u>m<\/u> je nejpravděpodobnější odhad a <u>b<\/u> je nejpesimističtější odhad.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.1.4","nazev":"Techniky pro odhadování","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-ctyri-techniky-pro-odhadovani"},"id":"OF-D31","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 31 (© ISTQB®, překlad CaSQB)"},{"n":32,"lo":"FL-5.1.5","k":"K3","vyber":1,"q":"<p>Tabulka znázorňuje trasovací matici od testovacích případů (TC) k požadavkům (Req). \"X\" znamená, že daný testovací případ pokrývá odpovídající požadavek.<\/p><table><thead><tr><th><\/th><th>Req1<\/th><th>Req2<\/th><th>Req3<\/th><th>Req4<\/th><th>Req5<\/th><th>Req6<\/th><th>Req7<\/th><\/tr><\/thead><tbody><tr><th>TC1<\/th><td>X<\/td><td><\/td><td>X<\/td><td>X<\/td><td><\/td><td><\/td><td>X<\/td><\/tr><tr><th>TC2<\/th><td>X<\/td><td><\/td><td><\/td><td><\/td><td>X<\/td><td><\/td><td>X<\/td><\/tr><tr><th>TC3<\/th><td><\/td><td><\/td><td><\/td><td><\/td><td>X<\/td><td>X<\/td><td><\/td><\/tr><tr><th>TC4<\/th><td><\/td><td>X<\/td><td><\/td><td><\/td><td><\/td><td><\/td><td><\/td><\/tr><\/tbody><\/table><p>Chcete stanovit priority testovacích případů pomocí techniky prioritizace dodatečného pokrytí.<\/p><p>Musíte provést všechny čtyři testovací případy.<\/p><p>Který testovací případ by měl být proveden jako POSLEDNÍ?<\/p>","m":["TC1","TC2","TC3","TC4"],"ok":[1],"vys":{"a":"Není správně.","b":"Je správně","c":"Není správně.","d":"Není správně."},"obecne":"<p>TC1 dosahuje nejvyššího pokrytí 4/7 (požadavek 1, požadavek 3, požadavek 4 a požadavek 7), proto by měl být proveden jako první. Požadavky 2, 5 a 6 stále nejsou pokryty.<\/p><p>Dalším testovacím případem, který dosahuje nejvyššího dodatečného pokrytí zbývajících požadavků, je TC3, který pokrývá 2 z těchto 3 požadavků (požadavek 5 a požadavek 6). TC3 by tedy měl být proveden jako druhý.<\/p><p>Jediný požadavek, který stále není pokryt, je požadavek 2, který je pokryt testovacím případem TC4. Proto by měl být TC4 proveden jako třetí testovací případ.<\/p><p>Posledním provedeným testovacím případem tedy bude TC2.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.1.5","nazev":"Prioritizace testovacích případů","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-pet-prioritizace-testovacich-pripadu"},"id":"OF-D32","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 32 (© ISTQB®, překlad CaSQB)"},{"n":33,"lo":"FL-5.1.7","k":"K2","vyber":1,"q":"<p>Jak mohou být testovací kvadranty přínosné pro testování?<\/p>","m":["Pomáhají při plánování testů tím, že rozdělují proces testování do čtyř fází, které odpovídají čtyřem základním úrovním testování: testování komponent, integrační testování, systémové testování a akceptační testování.","Pomáhají při hodnocení pokrytí na vyšší obecné úrovni (např. pokrytí požadavků) na základě pokrytí na nižší specifické úrovni (např. pokrytí kódu).","Pomáhají netechnickým zainteresovaným stranám pochopit různé typy testů, a také to, že některé typy testů jsou pro určité úrovně testování relevantnější než jiné.","Pomáhají agilním týmům vytvořit komunikační strategii založenou na rozdělení lidí do čtyř základních psychologických typů a na modelování vztahů mezi nimi."],"ok":[2],"vys":{"a":"Není správně. Testovací kvadranty nemají nic společného s popisem vztahů mezi jednotlivými úrovněmi testování.","b":"Není správně. Testovací kvadranty nemohou pomoci při posuzování jakéhokoli typu pokrytí.","c":"Je správně. Testovací kvadranty umožňují manažerům a dalším zainteresovaným stranám pochopit vztahy mezi typy testů, podpůrnými činnostmi (podpora týmu nebo kritika produktu) a hlediskem, na které se zaměřují (zaměřené na byznys nebo na technologii).","d":"Není správně. Testovací kvadranty nejsou psychologický model."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.1.7","nazev":"Testovací kvadranty","href":"kapitola-5/vyklad.html#cast-pet-tecka-jedna-tecka-sedm-testovaci-kvadranty"},"id":"OF-D33","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 33 (© ISTQB®, překlad CaSQB)"},{"n":34,"lo":"FL-5.2.1","k":"K1","vyber":1,"q":"<p>Úroveň určitého rizika je odhadnuta na 1 000 € a jeho pravděpodobnost na 50%.<\/p><p>Jaký je jeho dopad?<\/p>","m":["500","2,000","50,000","200"],"ok":[1],"vys":{"a":"Není správně.","b":"Je správně","c":"Není správně.","d":"Není správně."},"obecne":"<p>Ohodnocení rizik může využívat kvantitativní nebo kvalitativní přístup (příp. oba). Při kvantitativním přístupu se úroveň rizika vypočítá jako násobek pravděpodobnosti rizika a dopadu rizika. Tedy: úroveň rizika = pravděpodobnost rizika * dopad rizika.<br>Potom: dopad rizika = úroveň rizika / pravděpodobnost rizika.<br>V našem případě je dopad rizika = 1 000 € / 50 % = 1 000 € / 0,5 = 2 000 €.<\/p><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"5.2.1","nazev":"Definice rizika a jeho atributy","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-jedna-definice-rizika-a-jeho-atributy"},"id":"OF-D34","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 34 (© ISTQB®, překlad CaSQB)"},{"n":35,"lo":"FL-5.2.2","k":"K2","vyber":2,"q":"<p>Které z následujících možností jsou produktová rizika?<\/p>","m":["Neřízené rozšiřování rozsahu (scope creep).","Špatná architektura.","Snižování nákladů.","Špatná podpora nástrojů.","Příliš dlouhá doba odezvy."],"ok":[1,4],"vys":{"a":"Není správně. Neřízené rozšiřování rozsahu (scope creep) je příkladem projektového rizika souvisejícího s technickými otázkami.","b":"Je správně. Špatná architektura je příkladem produktového rizika, protože se týká vlastnosti produktu.","c":"Není správně. Snižování nákladů je příkladem projektového rizika, které souvisí s organizačními otázkami.","d":"Není správně. Špatná podpora nástrojů je příkladem projektového rizika souvisejícího s technickými otázkami.","e":"Je správně. Příliš dlouhá doba odezvy je příkladem produktového rizika, protože se týká vlastnosti produktu."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.2.2","nazev":"Projektová a produktová rizika","href":"kapitola-5/vyklad.html#cast-pet-tecka-dva-tecka-dva-projektova-a-produktova-rizika"},"id":"OF-D35","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 35 (© ISTQB®, překlad CaSQB)"},{"n":36,"lo":"FL-5.3.2","k":"K2","vyber":1,"q":"<p>Která z následujících možností NENÍ účelem reportu z testování?<\/p>","m":["Sledování průběhu testování a identifikace oblastí, které vyžadují zvýšený dohled.","Poskytování informací o provedených testech, jejich výsledcích a všech nalezených defektech.","Poskytování informací o každém defektu, např. kroky k jeho reprodukci.","Poskytování informací o testování plánovaném na příští období."],"ok":[2],"vys":{"a":"Není správně. Sledování průběhu testování a identifikace oblastí, které vyžadují zvýšenou pozornost, je příkladem podpory průběžného řízení testování. To je jeden z účelů reportu z testování.","b":"Není správně. Příkladem shrnutí testovacích činností provedených v dané úrovni testování je poskytnutí informací o provedených testech, výsledcích testů a zjištěných defektech. To je jeden z účelů reportu z testování.","c":"Je správně. Poskytování informací o defektech je účelem reportu o defektu, nikoli reportu z testování.","d":"Není správně. Jedním z účelů reportu z testování je poskytnutí informací o testech plánovaných na další období."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.3.2","nazev":"Účel, obsah a cílové skupiny reportů z testování","href":"kapitola-5/vyklad.html#cast-pet-tecka-tri-tecka-dva-ucel-obsah-a-cilove-skupiny-reportu-z-testovani"},"id":"OF-D36","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 36 (© ISTQB®, překlad CaSQB)"},{"n":37,"lo":"FL-5.4.1","k":"K2","vyber":1,"q":"<p>Uživatel nahlásil selhání softwaru. Technik z týmu podpory požádal uživatele o číslo verze softwaru, ve které bylo selhání pozorováno. Na základě čísla verze tým znovu sestavil všechny soubory, ze kterých byla verze vytvořena. To později umožnilo vývojáři provést analýzu, najít defekt a opravit jej.<\/p><p>Která z následujících činností umožnila týmu provést výše uvedenou aktivitu?<\/p>","m":["Management rizik.","Monitoring a řízení testování.","Týmový přístup.","Konfigurační management."],"ok":[3],"vys":{"a":"Není správně. Management rizik se skládá z analýzy a řízení rizik. Žádná z těchto činností nepodporuje opětovné sestavení souborů, z nichž se skládá vydání (release), protože tyto činnosti se týkají rizik, nikoli konfiguračních položek.","b":"Není správně. Monitoring testování se zabývá shromažďováním informací o testování. Tyto informace se využívají k posouzení průběhu testování a k měření toho, zda jsou naplněna výstupní kritéria nebo dokončeny testovací úkoly spojené s výstupními kritérii (jako např. splnění cílů pro pokrytí produktových rizik, požadavků nebo akceptačních kritérií). Řízení testování využívá informace z monitoringu testování k tomu, aby byly (ve formě nařízení nebo směrnic) poskytnuty pokyny a nezbytná nápravná opatření k dosažení co nejúčinnějšího a nejefektivnějšího testování. Žádná z těchto činností se nezabývá managementem konfiguračních položek.","c":"Není správně. Týmový přístup staví na schopnosti testera efektivně pracovat v týmu a pozitivně přispívat k plnění týmových cílů. Zaměřuje se tedy na otázky týkající se týmu, nikoli na konfigurační položky.","d":"Je správně. Konfigurační management je systém, který slouží k identifikaci, řízení a sledování pracovních produktů. Při vytváření nového výchozího stavu (baseline) je úkolem konfiguračního managementu uchovávat záznamy o všech změněných konfiguračních položkách. Pomocí konfiguračního managementu je možné vrátit se k předchozímu výchozímu stavu, aby bylo možné reprodukovat předchozí výsledky testů."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.4","nazev":"Konfigurační management","href":"kapitola-5/vyklad.html#cast-pet-tecka-ctyri-konfiguracni-management"},"id":"OF-D37","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 37 (© ISTQB®, překlad CaSQB)"},{"n":38,"lo":"FL-5.5.1","k":"K3","vyber":1,"q":"<p>Předpokládejme existenci následujícího report o defektu pro systém pro půjčování knih:<\/p><blockquote><p><strong>ID defektu:<\/strong> 001<\/p><p><strong>Název:<\/strong> Nelze vrátit knihu<br><strong>Závažnost:<\/strong> Vysoká<\/p><p><strong>Priorita:<\/strong> [nedefinována]<br><strong>Konfigurace systému:<\/strong> Windows 10, Google Chrome<\/p><p><strong>Popis:<\/strong> Při pokusu o vrácení knihy pomocí funkce Vrácení knihy systém nezaregistruje vrácení a kniha zůstává vypůjčená uživatelem.<\/p><p><strong>Kroky k reprodukci:<\/strong><br>Přihlaste se do systému půjčování knih jako uživatel, který má vypůjčenou knihu.<br>Klikněte na tlačítko \"Vrátit knihu\" u knihy, která byla vypůjčena.<br>Systém nezaregistruje vrácení a kniha zůstává vypůjčená.<\/p><p><strong>Očekávaný výsledek:<\/strong> Kniha by měla být vrácena a již by se neměla zobrazovat jako vypůjčená uživatelem.<br><strong>Skutečný výsledek:<\/strong> Kniha zůstává vypůjčená uživatelem a není v systému evidována jako vrácená.<\/p><p><strong>Přílohy:<\/strong> [prázdný seznam]<\/p><\/blockquote><p>Která z následujících možností pomůže NEJPRAVDĚPODOBNĚJI vývojáři rychle znovu reprodukovat toto selhání?<\/p>","m":["Přidání informací o tom, kterých uživatelů a kterých knih se selhání týká (do sekce Popis).","Vyplnění chybějící hodnoty pro pole Priorita.","Přidání výpisů paměti a snímků databáze pořízených po každém kroku popsaném v sekci Kroky k reprodukci do sekce Přílohy.","Opakování stejného testovacího případu pro různá prostředí a sepsání samostatných hlášení defektů pro každé z nich."],"ok":[0],"vys":{"a":"Je správně. Přidání těchto informací umožní vývojáři použít stejná vstupní data, takže je pravděpodobnější, že bude schopen rychle reprodukovat selhání, a tak rychleji identifikovat defekt.","b":"Není správně. Doplnění priority při reprodukci samotného defektu nepomůže.","c":"Není správně. I když některé z těchto informací mohou být cenné, přidávání výpisů paměti a snímků databáze po každém kroku by bylo nadbytečné, protože většina těchto pracovních produktů by pro vývojáře obsahovala neužitečné informace a snižovala by čitelnost reportu o defektu. Vývojář také bude muset strávit mnoho času analýzou těchto informací, což prodlouží proces opravy.","d":"Není správně. Otázka se týkala toho, jak pomoci vývojáři reprodukovat selhání v rámci konkrétní konfigurace prostředí."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"5.5","nazev":"Management defektů","href":"kapitola-5/vyklad.html#cast-pet-tecka-pet-management-defektu"},"id":"OF-D38","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 38 (© ISTQB®, překlad CaSQB)"},{"n":39,"lo":"FL-6.1.1","k":"K2","vyber":1,"q":"<p>Jsou dány následující kategorie testovacích nástrojů:<\/p><ol type=\"i\"><li>Nástroje pro spolupráci.<\/li><li>Nástroje DevOps.<\/li><li>Nástroje pro management.<\/li><li>Nástroje pro nefunkcionální testování.<\/li><li>Nástroje pro návrh a implementaci testů.<\/li><\/ol><p>Nástroje z kterých kategorií NEJPRAVDĚPODOBNĚJI usnadní provádění testů?<\/p>","m":["i, v","ii, iv","i, iii, v","ii, iii, iv"],"ok":[1],"vys":{"a":"Není správně.","b":"Je správně. Nástroje DevOps (ii) a nástroje pro nefunkcionální testování (iv) usnadňují provádění testů.","c":"Není správně.","d":"Není správně."},"obecne":"<p>Platí, že:<\/p><ol type=\"i\"><li>Nástroje pro spolupráci – usnadňují komunikaci. Komunikace neusnadňuje samotné provádění testů.<\/li><li>Nástroje DevOps – podporují pipeline v DevOps, sledování pracovních toků, procesy automatizovaného sestavování a CI/CD. Jak delivery pipeline, tak CI/CD usnadňují provádění testů, například testováním komponent v rámci CI.<\/li><li>Nástroje pro management zvyšují efektivitu procesu testování tím, že usnadňují správu SDLC, požadavků, testů, defektů a konfigurací. Management těchto položek neusnadňuje provádění testů.<\/li><li>Nástroje pro nefunkcionální testování umožňují provádět nefunkcionální testování, které jde provést manuálně buď s velkými obtížemi nebo vůbec. Nefunkcionální testování může zahrnovat statické i dynamické testování, včetně provádění testů.<\/li><li>Nástroje pro návrh a implementaci testů usnadňují vytváření testovacích případů, testovacích dat a testovacích procedur. Vytvoření tohoto testwaru neusnadňuje provádění testů.<\/li><\/ol><p>Pak tedy:<\/p>","pozn":"","pozn_vyh":"","kap":{"c":"6.1","nazev":"Nástroje pro podporu testování","href":"kapitola-6/vyklad.html#cast-sest-tecka-jedna-nastroje-pro-podporu-testovani"},"id":"OF-D39","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 39 (© ISTQB®, překlad CaSQB)"},{"n":40,"lo":"FL-6.2.1","k":"K1","vyber":1,"q":"<p>Která z následujících možností je NEJPRAVDĚPODOBNĚJI rizikem automatizace testování?<\/p>","m":["Odhalení dodatečných defektů s vysokou závažností.","Poskytování metrik, které jsou příliš složité na to, aby je bylo možno ručně vypočítat.","Nekompatibilita s platformou vývoje.","Podstatně zkrácené doby provádění testů."],"ok":[2],"vys":{"a":"Není správně. Odhalení dalších vysoce závažných defektů by bylo spíše přínosem automatizace testování než jejím rizikem.","b":"Není správně. Provádění opatření, která jsou pro člověka příliš komplikovaná, je obvykle považováno za výhodu automatizace testů.","c":"Je správně. Pokud je automatizace testování nekompatibilní s vývojovou platformou, nebude možné provést integraci a například předávat testovanému objektu testovací vstupy a přijímat z něj výsledky testů.","d":"Není správně. Za výhodu, kterou obvykle přináší automatizace testování, považujeme zejména podstatné zkrácení doby provádění testů."},"obecne":"","pozn":"","pozn_vyh":"","kap":{"c":"6.2","nazev":"Výhody a rizika automatizace testů","href":"kapitola-6/vyklad.html#cast-sest-tecka-dva-vyhody-a-rizika-automatizace-testu"},"id":"OF-D40","k3":true,"navic":false,"varianta":false,"oficialni":true,"zdroj":"oficiální vzorová zkouška D, otázka 40 (© ISTQB®, překlad CaSQB)"}],"kapitoly":{"1":"Základy testování","2":"Testování v průběhu životního cyklu","3":"Statické testování","4":"Testovací analýza a návrh testů","5":"Management testování","6":"Testovací nástroje"}};
